/**
 * Capabilities registry — the single source of truth for everything HYBRID can
 * (and can't yet) do. Surfaced in the web admin "Capabilities" screen.
 *
 * KEEP THIS CURRENT: whenever a feature ships, gets blocked, or is planned,
 * update this file in the same change (see CLAUDE.md).
 */

export type CapabilityStatus = "shipped" | "blocked" | "planned";

export type CapabilityArea =
  | "Core"
  | "Web"
  | "Mobile"
  | "Backend"
  | "Auth"
  | "Data"
  | "AI"
  | "Integrations";

export interface Capability {
  id: string;
  area: CapabilityArea;
  title: string;
  detail: string;
  status: CapabilityStatus;
  /** For `blocked` items: what's needed to unblock it. */
  blockedBy?: string;
}

export const CAPABILITIES: Capability[] = [
  // ---- Core (shared) ----
  { id: "monorepo", area: "Core", status: "shipped", title: "Monorepo + shared core", detail: "Turborepo/pnpm workspace; engines, types, plan library, sport engine, session helpers and brand tokens written once in @hybrid/core and consumed by web + mobile." },
  { id: "engines", area: "Core", status: "shipped", title: "Training engines", detail: "Fatigue (decay), readiness (+ biometric adjustment), per-lift progression signal, periodization (macrocycle/microcycles), and the prescription engine. Pure, unit-tested." },
  { id: "plans-lib", area: "Core", status: "blocked", title: "Plan library", detail: "Goal-first plan tree of 19 goals spanning strength (Powerlifting, Olympic Weightlifting, Strongman), physique (Bodybuilding, Fat Loss), endurance (Triathlon, Running, Cycling, Swimming), functional/sport (Hyrox, CrossFit, Hybrid Athlete, Calisthenics, Kettlebell, Tactical & Military, Sport Performance) and health (General Fitness, Mobility & Longevity, Pre & Postnatal), each with full plan detail (split, every training day fully spec'd, progression). Each goal carries a category; GOAL_GROUPS exposes the goals grouped by category (Strength/Physique/Endurance/Functional & Sport/Health) and both the web/mobile Plans screens and the onboarding goal picker render them in those groups. PLAN MODEL REDESIGN — the old one-size-fits-all gym plans (exercise – sets×reps – rest – RPE) were retired because that single shape is wrong for most goals. Plans are now DISCIPLINE-SHAPED: a PlanProgram (plan-program.ts) is tagged with a discipline that selects its structure, loading units, volume metric and progression — `strength-percent` (Olympic WL / Powerlifting: % of 1RM, ramped sets, complexes, tempo, AM/PM sessions, NL number-of-lifts volume counting, date-anchored peaking), with `hypertrophy` (Bodybuilding: sets×reps×load), `endurance` (Running/Cycling/Swim: distance/pace/mileage, NO gym) and `conditioning` (Hyrox/CrossFit/Fat-Loss: circuit blocks of exercises with a rounds count, each prescribed as a sets×reps OR a time/hold scheme, no % or paces). CONSISTENCY IS THE POINT — however differently a source plan is worded, it ends up rendered in ONE identical HYBRID card+table layout (the shared ProgramDays component on web — used by BOTH classic + Aurora — and its mobile twin in percent-program.tsx, off the SAME view model) whose row body ADAPTS per discipline: bodybuilding shows Sets×Reps + an intensity-coloured RPE 'heat' bar (rpeColor); weightlifting shows a %-ramp prescription with each load colour-graded (loadColor) and AM/PM doubles split by lime/blue session bands; running renders the whole week as one card of Day rows with a workout-type dot (workoutColor) and muted rest days. THE LAYOUT IS CHOSEN FROM CONTENT, not the plan label: an all-prose week (pure running) becomes the single week card; any week containing gym work renders one card per day, and a day's content is grouped by KIND so the formats never collide — a RUN block (prose), a MAIN block (%-of-1RM barbell work, the colour-graded %-ramp) and an ACCESSORIES/STRENGTH block (classic sets×reps×RPE, the heat table) each render in their own labelled section (liftKind in @hybrid/core). So an Olympic day with a biceps-curl accessory, or a run day with a strength block, splits cleanly instead of mixing %-ramps and RPE rows in one table. The intensity thresholds live once in @hybrid/core so the colour wave can't drift across clients. planProgramView() builds a single render-ready view model that ALL four renderers consume (web classic + Aurora, mobile classic + Aurora): a week selector, a discipline-aware volume label, day cards (AM/PM sessions OR weekday columns), a 'fill in your numbers' panel, a 'peaks to …' note, progression, and enroll. The panel and labels generalize: strength shows numeric MAXES (→ derived kg) and an 'N lifts' volume; hypertrophy shows working weights and an 'N exercises' volume; endurance shows text GOAL PACES and no counter; the peak day reads 'Competition' or 'Race day' (or none) per program; a single-week plan hides the week selector. FOUR programs shipped so far: (1) the SOVIET 8-WEEK Olympic-weightlifting block (`oly-soviet-8wk`, strength-percent) — %-first loading kept as written, 1RM derives working kg via stepKg, a notation parser (parsePercentSteps) turns coach shorthand into steps, NL derived (Σ (reps+complex)–sets) and unit-checked vs the source's own running totals (Week 1 Day 1 = 160 lifts); (2) the HANSONS 5K BEGINNER 9-WEEK running plan (`run-5k-beginner-9wk`, endurance) — a Mon–Sun grid of PROSE workouts (intervals/tempo/hills/easy/long run, 'or cross-train' alternatives as notes), goal-pace inputs, a taper into race day, NO gym; (3) the 6-DAY PUSH/PULL/LEGS bodybuilding split (`bb-ppl-6day`, hypertrophy) — a one-repeating-week weekday split of exercises with sets×reps ranges, each day built on a progressively-overloaded main lift; (4) the SATURDAY KETTLEBELL + FAT-LOSS circuit (`fatloss-kb-saturday`, conditioning) — ONE ~90-min session modelled as seven block cards (warm-up → five work blocks → cool-down), each carrying its round count in the title and its exercises as time/hold or sets×reps schemes; each block has an EFFORT TIER (conditioningColor) so the circuit rides the SAME intensity wave the %-plans and RPE-plans do — the prescription/dot colours blue→lime→amber→red as the session builds (warm-up easy → finisher peaks red → cool-down ash); volume counts MOVEMENTS like hypertrophy ('N exercises'); the 4-week emphasis rotation (form → speed → volume → heavier) + the recovery routine live in the progression note; (5) the 12-WEEK KETTLEBELL block (`kb-12wk-strong`, hypertrophy) — a strength/muscle program whose split ROTATES every week (full body → push/pull/legs+core → upper/lower, weeks 1/4/7/10, 2/5/8/11, 3/6/9/12), rendered as the bodybuilding sets×reps table with a 12-week selector; reps are SINGLE numbers (per the project rule — source ranges collapsed to the top, '15-20' → '20'), with per-side '10/leg' and holds '30 s' kept as-is, via the free-text scheme and NO RPE invented (the source gives sets × reps + rest, not effort); instead the sets×reps rides the TRAINING-ZONE wave (repZoneColor) — each prescription coloured strength/amber (≤6) → hypertrophy/lime (7–12) → endurance/blue (13+, and timed holds) from its OWN rep count — so it carries the same coloured intensity dimension as the oly %-wave and the bb RPE heat, derived not fabricated. (6) the HYBRID ATHLETE strength-and-engine base (`hybrid-engine-base`, hypertrophy) — the hybrid case the other five don't cover: a single week (run on repeat) that carries BOTH heavy barbell strength AND an aerobic engine, authored as a direct PlanProgram because it mixes strength/conditioning/endurance content that no single builder fits. Its point of difference is the DAY SHAPE — two key days are THREE-A-DAY (AM strength / MID conditioning / PM easy run) and Saturday is a two-a-day (AM long run / PM full-body), which is what exercises the AM/MID/PM session model end to end; each session is a single content kind so a day reads as clean, separately-startable blocks. Reps are single numbers, kettlebell work uses the KB prefix. All six are wildly different source formats rendered in ONE identical UI. The remaining 13 goals still carry 0 plans and degrade gracefully (web/mobile show '0 plans' / 'No plans here yet'; onboarding returns no recommendation) until authored in their fitting shape. See reference/plan-model-redesign.md. PLAN PROVENANCE — the model has THREE kinds of plan, by who authors them and who they're for: (1) PRE-MADE app plans — the curated library shipped with the app, free for casual users to browse, enroll & follow as written (this `plans-lib` content); (2) ATHLETE-built plans — a paid athlete composes their own via the Builder (own templates/programs); (3) COACH plans — authored by a coach and assigned to THEIR clients only (private to that coach↔client relationship; see `coach-assign-plans`). Today (1) carries five discipline-shaped plans so far (the Soviet OWL block on Olympic Weightlifting, the Hansons 5K plan on Running, the 6-day PPL split on Bodybuilding, the Saturday kettlebell circuit on Fat Loss, and the 12-week kettlebell block on Kettlebell; the rest await authoring), the coach path (3) assigns by goal / a named pre-made plan / a coach-AUTHORED multi-week program (the program builder is shipped — see coach-program-builder), and deeper athlete program-building for (2) is the remaining authoring step.", blockedBy: "The discipline-shaped plan model ships with six programs (Soviet 8-week OWL, Hansons 5K running, 6-day PPL bodybuilding, Saturday kettlebell fat-loss circuit, 12-week kettlebell strength block, and a Hybrid Athlete strength-and-engine base). The other 13 goals still need plans authored in their fitting shape — more endurance/no-gym (Cycling, Swimming, Triathlon, longer-distance running), conditioning (Hyrox, CrossFit), strength (Powerlifting, Strongman), etc." },
  { id: "engine-name-resolution", area: "Core", status: "shipped", title: "Engine exercise-name resolution (library-named lifts attribute load)", detail: "BUGFIX + hardening. Every muscle-attribution engine indexed the MOVEMENTS map by EXACT key and silently skipped a miss, so a lift logged under a name the built-in catalog doesn't carry verbatim contributed ZERO load — the tissue simply read as untrained. That is most of what athletes actually pick: the shipped exercise library (reference/sql-exercise-seed.sql, 209 rows) names lifts differently from the built-in DB, and 153 of its 209 names missed by exact key — equipment-qualified twins ('Barbell Deadlift' vs 'Deadlift', 'Barbell Bench Press' vs 'Bench Press'), case-only differences ('Pull-up' vs 'Pull-Up', 'Chin-up', 'Step-up'), and 148 library-ONLY lifts with no built-in twin at all ('Dumbbell Bulgarian Split Squat', 'Seated Cable Row', 'Cable Crossover'…). Reported symptom: a full second workout (deadlift, pull-up, bench, Bulgarian split squat) left the injury-risk tissue map bit-for-bit unchanged, with quads/glutes/posterior/back reading '—' (no chronic history) while the athlete had just trained them. FIX, in two parts. (1) movementFor(name) in engines/movements.ts is now the ONE resolver every engine shares — exact key → trimmed → built-in rename breadcrumbs (GYM_ALIASES) → the shipped library's equipment-qualified display names (GYM_LIBRARY_ALIASES) → case-insensitive — mirroring gymExercise's order so the property sheet and the engines can never disagree about whether a lift is known; musclesFor(name) is the []-returning convenience the volume callers want. Wired into fatigue, injury, session (inferBlockKind + toTrainingLog's energy-system lookup), analytics (volume-by-muscle), landmarks, records, exercise-browse, prescription and sports. (2) setExerciseCatalog(custom) publishes the admin-managed library to those engines, so library-ONLY lifts resolve too. The catalog is GLOBAL admin-authored data (identical for every athlete), not per-request state, so a module-level registry is correct on both clients and in a server route — and it keeps every engine signature unchanged (no 20-call-site churn, no per-screen memo-dependency drift). Ordering is a guarantee, not a race: the engines run on SESSION data, so both clients publish the catalog from inside their session fetchers (web lib/exercise-catalog.ts ensureExerciseCatalog() awaited in useSessions; mobile the same helper in lib/api.ts awaited in fetchSessions + querySessions), and useExercises() tops it up on a later refetch so the engine catalog and the picker's never drift. Server-side engine paths publish it too (lib/cache.ts publishExerciseCatalog() → athleteState, /api/ai-coach, /api/coach/squad). Degrades to the built-ins alone when signed-out / the table isn't seeded. 12 new unit tests (engines/movement-resolution.test.ts) pin the resolution order, the registry lifecycle, volume-by-muscle on a library name, and the reported regression: the second workout now raises risk instead of leaving it identical." },
  { id: "catalog-attribution-guard", area: "Core", status: "shipped", title: "Catalog attribution guard — a pickable exercise must log load", detail: "PREVENTION for the engine-name-resolution class of bug. The failure mode is silent by construction: a logged lift reaches the engines as a NAME, and a name that doesn't resolve — or resolves to an EMPTY muscle list — is indistinguishable from 'this tissue was never trained'. The output is a plausible-looking zero, not an error, so nothing anywhere surfaces it. THE INVARIANT is now pinned in CI instead: packages/core/src/engines/catalog-coverage.test.ts parses the shipped library seed (reference/sql-exercise-seed.sql — the actual rows the picker offers) and fails the build if any row is unresolvable, carries no muscles, uses a muscle group outside the engine enum, has an unresolvable alias, or would drop out of catalogNames (exactly what the two pickers render). A degraded-path case covers the state the original bug ran in — the library NOT published (signed out / table unseeded / fetch failed), engines on the built-ins alone while stored sessions carry library names — via the rule that THE ENGINES MUST NEVER BE BLINDER THAN THE PROPERTY SHEET: if gymExercise() resolves a name, movementFor() must too, or the exercise page shows a full muscle map for a lift the engines score as zero. Mutation-tested: reverting movementFor to the old exact-key lookup fails 7 tests, deleting one GYM_LIBRARY_ALIASES bridge fails 4, and emptying a single seed row's muscles fails 3 — with the offending exercise NAMED in the assertion message. SECOND DEFECT FOUND AND FIXED by the new guard: 55 seed rows (every curl, calf raise, ab and grip movement — categories Biceps, Traps & Forearms, Calves, Abs & Core) shipped with muscles deliberately left EMPTY, on the assumption that only the per-muscle volume chart would skip them. It doesn't stop there — they contributed zero to fatigue, ACWR, injury risk, landmarks and records too. They now map to their coarse home exactly as core's ENGINE_GROUP already does for the built-in catalog (biceps + forearms + traps -> back, calves + abs + obliques -> posterior); a rough attribution beats none. RUNTIME ADDITIONS are covered by the existing admin write path — api/admin/exercises/shared.ts parseExercise already rejects an exercise with no muscles ('at least one muscle required'), so the only way to introduce an empty row is raw SQL, which is what the CI guard now watches. LIVE: reference/sql-exercise-muscles-fix.sql has been run in the Supabase SQL Editor, so the 55 already-inserted rows now carry their muscle group and curls / calf raises / ab work / grip work attribute load on the live app. A fresh install needs only the seed (it now carries these values); the repair script stays in reference/ as the idempotent fix for any database seeded from the older file." },
  { id: "prescribed-name-attribution", area: "Core", status: "shipped", title: "Plan- and sport-PRESCRIBED movements must attribute load too", detail: "SAME silent-drop class as engine-name-resolution / catalog-attribution-guard, from a name source those fixes do NOT cover. Exercise names reaching the engines come from three places: (1) the exercise PICKER — fixed and guarded; (2) the shipped PLAN PROGRAMS (plan-programs.ts PlanLift.name and the structured gym PlanEntry.label); (3) the SPORT S&C pools (olympic-sports.ts PoolExercise.name). Sources 2 and 3 are authored free-hand in TypeScript and were never checked against the movement catalog, so they miss it the same way library names used to. MEASURED with the library catalog published (i.e. the real runtime state after the resolver fix): 154 of 214 prescribed plan movements and 22 of 34 sport S&C movements resolve to NO muscle group — they log zero fatigue, ACWR, injury risk, volume-by-muscle, landmarks and records. Worst case is kb-12wk-strong at 108/121: enrol in the 12-week kettlebell plan, follow it exactly, and almost the entire program reads as untrained. Also bb-ppl-6day 14/28, fatloss-kb-saturday 14/19, oly-soviet-8wk 16/26. Two distinct causes, needing different fixes: (a) NAMING VARIANTS of catalog lifts that just need an alias bridge — 'Squat' -> Back Squat, 'Dips' -> Dip, 'Dumbbell Curl' -> Dumbbell Biceps Curl, 'Lateral Raises' -> Dumbbell Lateral Raise, 'Skull Crushers', 'Hamstring Curl', 'Chest Fly', 'Pullover'; and (b) movements the catalog genuinely lacks and that need real DB entries with muscle data — most of the kettlebell vocabulary (KB Halo, KB Windmill, KB Slingshot, KB Figure 8, KB Gorilla Row…), the Olympic derivatives (Hang Snatch, Clean Extension, Snatch Balance, the Eccentric/Slow deadlift variants), and the athletic/plyo pool (Pogo Hops, Depth Jumps, Lateral Bound, Shuttle Sprints, Front Lever Progression). Warm-up and mobility labels (Jumping Jacks, Hip Circles, Arm Swings) are a third, lower-stakes bucket — arguably fine to attribute little, but they should resolve deliberately rather than by accident. SHIPPED. 52 new exercises authored into the built-in DB with real primary/secondary muscles — the kettlebell vocabulary (KB Halo, KB Windmill, KB Slingshot, KB Figure 8, KB Gorilla Row, KB Renegade Row, KB Arm Bar, KB Z Press, KB Chop, KB Front Rack Lunge, Suitcase Deadlift, Man Maker…), the bodyweight core work (Hollow Body Hold, Superman, Reverse Crunch, Mountain Climber), unilateral/lateral legs (Cossack Squat, Curtsy Lunge, Shrimp Squat, Sumo Squat), the athletic/plyo pool (Jump Squat, Pogo Hop, Lateral Bound, Shuttle Sprint, Trap Bar Jump, Med-Ball Rotational Throw, Jumping Jacks, High Knees, Bob and Weave, Hip Circles, Arm Swings), the sport-pool accessories (Band Pull-Apart, Cable Straight-Arm Pulldown, Scapular Pull-Up, Front Lever Progression, Hangboard Repeaters, Towel Pull-Up Hold, Landmine Punch Press), two bodybuilding accessories and two Olympic derivatives (Clean Deadlift, Snatch Balance). Plus 140 GYM_ALIASES bridges pointing each authored name at a real entry. Bridge targets are BUILT-IN entries on purpose: a plan is CODE and must attribute without waiting on the DB-backed library to load, which the guard now asserts separately. The bridges also collapse duplicate spellings of the same lift inside one program ('Crush Grip KB Pushup' / 'KB Crush Grip Pushup' / 'Crush Grip Push-up'; 'High Pull' / 'High Pulls' / 'Single-arm High Pulls'), honouring the KB-prefix naming rule. RESULT: 0/214 prescribed plan movements and 0/34 sport movements now attribute nothing, down from 154 and 22. GUARD EXTENDED: catalog-coverage.test.ts gained three cases covering the third name source — every PlanLift.name and structured PlanEntry.label resolves, every PoolExercise.name resolves, and both do so WITHOUT the library published. Mutation-tested: renaming one new entry or deleting one bridge fails 2 tests, naming the offending plan and movement. TWO BEHAVIOUR CHANGES fell out and are pinned by updated tests: 'Calf Raise (slow)' got its own bodyweight entry rather than a bridge to the loaded machine lift (a runner's slow tempo raise must not inherit a 60 kg base load), and exerciseBucket now prefers a RESOLVED movement over its keyword guess, so 'Eccentric Snatch Deadlift' buckets as posterior — agreeing with its canonical Snatch-Grip Deadlift entry — instead of being pulled into 'olympic' by the word 'snatch'." },
  { id: "sport-engine", area: "Core", status: "shipped", title: "Sport S&C engine", detail: "Per-sport demands + exercise pools; prescribeForSport ranks the strength & conditioning that transfers, by level, and doses today's working load from the athlete's OWN logged lifts (a level-appropriate % of their best e1RM) — falling back to a starting estimate for known barbell lifts or a bodyweight/tempo scheme, never a fabricated number. Pure + unit-tested. UNIFIED (Jul 2026): there is now ONE sport database — the engine no longer keeps its own list. Every prescribable sport (Running, Swimming, Cycling, Boxing, BJJ, Squash, Climbing) is a catalog entry in olympic-sports.ts carrying an optional `sc` block (family + performance marker + ranked demands + level-tagged pool); sports.ts derives SPORTS/SPORT_NAMES/prescribeForSport as a projection over exactly those entries (same pool array by reference — one source of truth), so the S&C engine and the manual-logging catalog can never again disagree on what a sport is or drift apart. Add a sport once, in the catalog; give it an `sc` block to make it prescribable. sports.test.ts asserts the projection." },
  { id: "signal-ontology", area: "Core", status: "shipped", title: "Signal ontology (Athlete Twin foundation)", detail: "Universal time-series in @hybrid/core: every measurement (HRV/RHR/sleep today; GPS load, force-plate, blood tomorrow) is one Signal shape from any source, with rolling baselines + oriented z-scores. A toBiometrics() adapter feeds the readiness engine unchanged. End-to-end loop live: Signal table (reference/sql-signal-table.sql) ← /api/signals (GET/POST, kind-validated) ← manual check-in writes it; dashboard reads it back via useSignals to drive the Twin. Pure + unit-tested." },
  { id: "sport-subpage", area: "Core", status: "shipped", title: "A page for every sport", detail: "SHIPPED on BOTH clients (design: design/sport-page.html). The 65-sport catalog had no destination — the Sport screen was a chip picker over one shared body, so a sport was a filter rather than a place. Now every catalog sport has its own page, rendered from ONE self-configuring model in @hybrid/core (sport-page.ts, `sportPageModel`) that branches on the sport's own record: `metrics` decides whether the distance cell, the volume bars, the pace trend and the effort split exist; `distanceUnit`/`pacePer` decide the units (km + /km for the road, metres + /100m for the pool); an `sc` block decides whether the transfer section exists at all (7 of the 65). No new aggregates — totals, weeks, zones and the prescription come from runTotals/weeklyMileage/paceEffortSplit/prescribeForSport, so a figure here and the same figure on Today cannot disagree; the slice runs through deviceTrueSessions() first, so every number is the watch's read where a watch recorded it and pace derives from cardioSeconds, not from display minutes. THE PAGE: a `cover`-rank Hero (eyebrow = category – family, meta = efforts/distance/since, level in the rail's accessory, a docked 'Log a … session'); the ONE figure — the sport's own marker (a 5 km time, a 100 m time, an FTP) where the athlete has typed one, else best pace, else distance, else time; totals on hairlines; 8-week volume; the reversed pace trend + the easy/steady/hard split for a paced sport; a full-bleed Bests rail; the ranked demands + prescribeForSport's blocks with a live level control that re-doses off the athlete's own e1RM, then the pool's why-lines (locked entries name the level that unlocks them); recent efforts reading through device-truth, tapping into the session. THE MARKER IS TYPED, so a delta needs kept history: SportStore.markerLog (core `recordMarker`/`markerHistory`, one shape written by both clients under 'hybrid.sport') keeps up to 24 typings and the page shows a delta + sparkline only from the second one — never an invented trend. ENTRY POINTS: the Sport screen is now the INDEX (`sportIndex` — sports you actually train first, then the prescribable ones, the whole catalog behind a search) and Today's other-sport tiles open the sport's page directly instead of dead-ending at the index. EVERY LINK LANDS ON THE SPORT, NOT THE PICKER: a sport page has an ADDRESS on both clients — web `/app?s=sportpage&sport=<slug>` (the slug comes from core `sportSlug`, so the shell's deep-link parser keeps its strict [A-Za-z0-9_-] boundary; `sportPageUrl()` builds a shareable link and `sportFromSlug` resolves either a slug or a display name back to the catalog, degrading to the INDEX rather than to an empty page), mobile `/sport-page?name=<slug|name>` (scheme `hybrid://`), which means a link survives a refresh, a bookmark, a paste and a hand-off between the two clients. Every surface that NAMES a sport now opens that sport's page rather than the index: Today's other-sport tiles and the Cockpit's Sport S&C module + breakdown tab on both clients. The Sport nav item still lands on the index, which is what a nav item means. Starting today's transfer session hands the logger the same blocks on both clients (core `transferSessionBlocks`). Colour is NOT per sport — every sport page wears the one action accent; what distinguishes Running from Swimming is the unit." },
  { id: "sport-page-followups", area: "Core", status: "shipped", title: "Sport page — the three follow-ups it raised", detail: "All three closed. (1) A HOLD IS NOT SIX REPS. prescribeForSport now doses each movement in the measure the exercise database says it IS (`GymExercise.measure`): reps stay sets×reps, a `time` movement becomes a hold in seconds (Swimming's Hollow Body Hold reads 3×20 s at Beginner and 5×45 s at Elite — growing with the level, because there are no reps to take away), and a `distance` movement becomes a carry in metres (Squash's Shuttle Sprints 3×20 m → 5×50 m). SportBlock gained `measure` + `amount`, and `reps` is now set ONLY for reps-measured work, so nothing downstream can read a 30-second hold as 30 repetitions; the reconciler carries the measure through (the week's envelope scales the SET COUNT, never the per-set quantity's unit), and both the sport page's and the reconciler's logger seeds fill the per-set field in that measure — which is what the logger already labels off exerciseProfile (reps / s / m). A hold and a carry get NO load: the engine derives working load from an e1RM, blockBestE1rm returns 0 for non-reps measures, and claiming a percentage of a number that does not exist would be fabricated, so those blocks prescribe the effort and leave the load to the athlete. Also fixed the data hole behind it — Boxing's 'Assault Bike Intervals' resolved to nothing (its alias pointed at an 'Assault Bike' entry that did not exist), so it had fallen back to reps. (2) ENDURANCE HUB vs SPORT PAGE — decided. The app now has ONE destination per depth: ALL your endurance (the Endurance hub) → ONE sport (the sport page) → ONE move (the exercise page, which already owns per-move pace analytics). The hub's discipline picker and its duplicate volume/pace/zone charts are gone; it is the COMPARISON now — every logged discipline side by side (the shared enduranceLanes block, uncapped and headless), each lane opening that sport's page, and Today's lanes open the sport page too. `sportForDiscipline` in core is the one place the lanes' discipline vocabulary meets the catalog's names, and it is an EXPLICIT map: inferring it from catalog order filed a cross-country ski under SKATEBOARDING (cardioDiscipline's skiing pattern matches 'skate'). `walking` is deliberately unmapped — the catalog's only walking sport is Race Walking, and filing a hike under a track event is a lie a link then repeats, so a lane with no sport shows no exit. (3) A DRAWN SPORT MARK. theme/sport-marks.ts: 15 stroke marks in the same 72-unit box as the icon set, resolved per sport where its instrument is distinctive (oar, sail, blade) and per CATEGORY otherwise — there are not 65 distinctive silhouettes, and the title already says which sport it is. Both Hero Systems gained `artPaths` (drawn art wins over `glyph`, same box, same parallax, same ghost floor), so the mark holds its shape at 152pt and can survive into the collapsed bar as texture, which a desaturated emoji could not. Every closed shape is drawn as TWO arcs: a single self-returning arc is degenerate, two of the first-cut marks rendered as nothing, and it took a screenshot to notice — a test now guards the shape of the path data itself." },
  { id: "hpi", area: "Core", status: "shipped", title: "HPI — Hybrid Performance Index", detail: "The headline 0..100 number that fuses strength + endurance + recovery (distinct from readiness, which is muscle-only). Reports its three pillars, its limiter, and a band; sport-weightable. Unit-tested and surfaced in the web dashboard Performance State card + the mobile Home. GATED: HPI is a Full feature — free (casual) users don't see the score (the Cockpit/Performance screens are athlete-nav-gated, the Today Performance-State block is athlete-only, and the Profile HPI hero shows a locked upsell instead of the number; see free-tier-gating)." },
  { id: "free-tier-gating", area: "Core", status: "shipped", title: "Free-tier feature gating (single source of truth)", detail: "packages/core/src/access.ts is the one place that decides what a FREE (casual) user can and can't do, so web + mobile gate identically (parity rule). Keyed on the resolved Persona (not raw entitlement) so it composes with resolvePersona — a client only reaches the athlete/Full surface when they've BOTH chosen athlete mode AND carry a paid entitlement; coaches/admins are Full by role. Predicates (unit-tested): isFullAccess, canSeeHPI, canEditEnrolledPlan, canScanFoodLabel, canSaveMealsAndProducts, canUseRecipes, canSaveRoutine (count-aware — free keeps up to FREE_TEMPLATE_LIMIT saved templates, see workout-routines). Enforced in the UI on both clients: (1) HPI — the Profile HPI hero + the spec-strip/ID-card index show a locked '🔒' + an 'Unlock with Full' upsell for casual users instead of the score (Cockpit/Performance are already athlete-nav-gated); (2) PLAN EDITING — a free user can browse, enrol in and follow a plan, but cannot edit the plan they're enrolled in (the reconciled 'This week' scheduler/re-sync only renders for athlete-or-coached on Today/Home, so casual users never get the edit control); (3) NUTRITION — free users add macros manually (kcal/protein/carbs/fat), but scanning a product label for an automatic add and saving meals/products to a library are Full features (the Nutrition screen shows a locked upsell for casual users; for Full users the buttons are present but tied to the blocked food database — see nutrition-fooddb). The upsell routes to the upgrade screen on both clients." },
  { id: "vbt-engine", area: "Core", status: "shipped", title: "Velocity-based training engine", detail: "velocity.ts: per-set summaries (best/mean/final mean concentric velocity, velocity loss %, ROM), velocity zones (absolute-strength → starting-speed with %1RM bands), a linear load–velocity profile fit (least squares, r²) that resolves an estimated 1RM at each movement's minimal velocity threshold, %1RM↔velocity conversion, and an autoregulated load recommender (target a bar speed → plate-rounded kg). Reads (load, velocity) straight off logged sessions (StrengthSet.vel) and adds a barVelocity Signal kind. The prescription engine is now velocity-aware: pass velocityProfiles(sessions) and the working load anchors to the velocity-estimated 1RM (which moves with daily readiness) with a target bar speed for the work sets — wired into the web + mobile loggers and the AI coach. Pure + 25 unit tests. Capture-agnostic: sensor, camera, or manual all feed the same math." },

  { id: "accountability-engine", area: "Core", status: "shipped", title: "Accountability Engine (v1) — predict the quit", detail: "accountability.ts: scores disengagement RISK (0..100) from training cadence — gap since last session vs target interval, week-over-week frequency decline, target miss, dormancy — BEFORE the user churns, classifies an engagement band (thriving→steady→wobbling→at-risk→dormant), ranks the drivers, and picks the single best re-engagement intervention (onboard/celebrate/nudge/ease/winback) with urgency + copy. Heuristic v0, documented; built so labeled save/churn outcomes can refit it through the data network. Pure + unit-tested. Surfaced in the Fitness GPS home (web + mobile)." },
  { id: "habits-streaks", area: "Core", status: "shipped", title: "Habits & streaks", detail: "habits.ts: forgiving day-streaks (a planned rest day never breaks the streak), weekly consistency, and a recency-weighted 0..100 habit-strength score so a comeback rebuilds quickly. Reads only session dates. Pure + unit-tested." },
  { id: "nutrition", area: "Core", status: "shipped", title: "Adaptive nutrition (manual macros)", detail: "nutrition.ts: manual macro logging lands on the Signal ontology (energyIntake/protein/carbs/fat/water — summed per day), and the engine ESTIMATES maintenance from energy balance (avg intake vs bodyweight trend, ~7700 kcal/kg) — MacroFactor-style adaptation, not a static calculator — then sets goal-aware targets (lose/maintain/gain; protein from bodyweight, fat ~25%, carbs fill the rest). Pure + unit-tested. Nutrition screen on web + mobile: today vs adaptive target bars, quick-add, recent days, maintenance readout. Bodyweight feeds it from the weekly check-in — the weigh-in is mirrored into a bodyMass signal — so targets are driven by the athlete's real weight; until maintenance can be estimated (no weigh-in / not enough intake) the targets card prompts for a weigh-in instead of presenting a population default as a personal target. The food database + barcode scan is a separate, blocked layer (nutrition-fooddb). GATED: manual macro logging is free for everyone; free users can also build + save up to FREE_MEAL_LIMIT (4) of their OWN meals (see nutrition-library); free users also keep up to FREE_PRODUCT_LIMIT (4) saved custom PRODUCTS (mirrors meals); only scanning a label stays Full-only (see free-tier-gating). PANEL (07+08 redesign, web + mobile at parity — pixel-matched to the approved mockup): first-run runs a GUIDED 3-STEP onboarding (goal → activity + real weigh-in that posts a bodyMass signal → a plan step offering the ✦ Full trial OR 'Continue on Free' — the free plan spells out what's included (daily macro logging, 4 saved meals, 4 saved products, insights) and drops the user straight into the tracker without an upgrade; the onboarding is its OWN flow (an early return), never stacked above the tracker). Once targets personalize the HOME leads with a time-of-day greeting + a tick-RING calorie hero (the app's kit Ring idiom — web conic/tick, mobile kit Ring) carrying a P/C/F macro trio, then the coach-voiced NUDGE line (nutritionNudge — protein-short / calories-left / over / on-track) and a QUICK-ACTION row (Add / ✦ Scan / Meals). The SUMMARY dashboard (nutritionSummary — week/month toggle, goal-progress strip from the 28-day weight change, avg intake, adherence, protein-hit, macro balance) rolls up the last 7/30 days and, for free users, ends on the deep-insights ✦ Full lock. HISTORY carries a 7-day streak strip above the recent-days list; the products library gains an on-device search over the user's own foods. nutritionSummary + nutritionNudge are pure + unit-tested in @hybrid/core so the two clients show identical numbers. REFINED (design pass, web + mobile at parity): the surface was re-cut against a harder restraint bar — EVERY emoji is gone, replaced by ONE monoline icon voice (NUTRITION_GLYPHS in @hybrid/core/theme/icons.ts — sunrise/sun/moon/cup meal times, water, scan, mic, spark, target, bowl, chevron — rendered as true 72×72 vectors: inline <svg> on web, react-native-svg on mobile, no PNG assets). The calorie tick-ring is now the undisputed hero (bigger, thinner ticks, room to breathe) with the P/C/F macros as full-width hairline LINES beneath (label + value + 4px bar) rather than a cramped trio; the nudge is a quiet spark-glyph line (no boxed accent-bar card); quick meals + saved meals + presets are type-first rows with time-of-day glyphs (no gradient lock tiles); the streak is shown as a plain number + week strip (consistency as data, not a trophy); and colour is confined to meaning only (lime = go; blue/amber/violet = protein/carbs/fat; generic stat tiles neutral). Onboarding choice cards dropped their emoji for label+sub+radio. HUB (web + mobile at parity): the subpage is no longer one long scroll — it's a HUB (an internal view-state, no routing change) whose landing keeps only the daily essentials (goal card → calorie ring + macros → nudge → 'Log a meal') then a MENU of rows into sub-screens (Diary = week strip + recent days; Insights = the summary dashboard; Body & weight = weigh-in + bodyweight trend; My meals; My foods), each opening with a back-to-hub header. The goal itself is changed through a deliberate Sheet opened from a card (never a live toggle, which an accidental tap could flip and recompute every target)." },
  { id: "nutrition-premade-meals", area: "Core", status: "shipped", title: "Premade meals (one-tap macro logging)", detail: "MEAL_PRESETS in @hybrid/core (nutrition.ts) — a shared set of common meals (breakfast/lunch/dinner/snack) with approximate single-number macros, plus mealPresetSignals() which writes the SAME energyIntake/protein/carbs/fat Signal kinds as the manual quick-add, so a preset log is indistinguishable downstream. Surfaced as a 'Quick meals' grid on the Nutrition screen (web + mobile) and gated on access.canSaveMealsAndProducts: free (casual) users see the grid LOCKED (🔒 tiles → upgrade), Full users tap a tile to log it. The manual macro path (kcal/protein/carbs/fat) stays free for everyone. This is the lightweight in-app preset layer; the full food-search/barcode DB remains separate + blocked (nutrition-fooddb). EDITABLE (Jul 2026): logging a preset now routes through the editable food-log (/api/nutrition/log) on the Nutrition screen, web + mobile — so a preset appears in the Diary as a named, edit/delete-able entry (was four anonymous source='preset' Signals that the per-part hub grouping ignored and nothing could remove). Attributed to the preset's natural part of the day (its id prefix breakfast|lunch|dinner|snack), so it also groups correctly on the hub. The mirrored Signals the engines read are still written by the same endpoint, so totals are unchanged; needs the FoodLog table (nutrition-diary-edit) for the entry row, and soft-degrades to Signals-only without it." },
  { id: "nutrition-library", area: "Core", status: "shipped", title: "Personal meal & product library (build-your-own)", detail: "The redesigned Nutrition panel lets a user BUILD and SAVE their own meals + custom products, persisted server-side (Prisma SavedMeal + FoodProduct; RLS in reference/sql-nutrition-meals.sql — run it in the Supabase SQL Editor, the sandbox can't migrate). API on both clients: /api/nutrition/meals (GET/POST/DELETE) + /api/nutrition/products (GET/POST/DELETE). A saved meal stores single-number macros (kcal derived 4·4·9 when omitted) and logs via the SAME energyIntake/protein/carbs/fat Signal kinds as manual quick-add. Create-a-meal has TWO builders (both clients, at parity): a manual macro form, OR compose the meal FROM your saved PRODUCTS — an 'Add product' sheet picks from the products library, each component carries a serving count, and the meal's macros are the summed total (sumMealComponents in @hybrid/core, unit-tested). Empty component list → the form falls back to manual macros. GATING (access.ts, unit-tested, mirrored client + server): free (casual) users may keep up to FREE_MEAL_LIMIT (4) saved meals — canSaveMeal(persona,count); POST /api/nutrition/meals returns 403 upgrade_required at the cap. Free users ALSO keep up to FREE_PRODUCT_LIMIT (4) saved custom PRODUCTS — canSaveProduct(persona,count); POST /api/nutrition/products 403s upgrade_required at the cap (mirrors saved meals). Full is unlimited on both. The live food-search/barcode DB remains a separate blocked layer (nutrition-fooddb) — the products screen builds against the user's OWN products until a food-DB key lands. Web + mobile at parity." },
  { id: "today-focus-hierarchy", area: "Core", status: "shipped", title: "Today focus & hierarchy (3-tier home)", detail: "The Today/Home screen (web today.tsx + mobile home.tsx, at parity) is ranked into a clear visual hierarchy so a returning user lands on one thing. The day-streak moves up into the header row to free the greeting line (as a terracotta PILL beside the bell — since superseded: the streak now rides under the wordmark as the header lockup's second line, see today-header-redesign); a compact TIER-2 glance strip (Quick Log – Readiness – Done today) sits under the plan hero — Quick Log opens the sport-log carousel in a modal, Readiness opens the check-in, and Done today opens a MODAL listing everything logged today with a 'See full calendar' link (replacing the old always-expanded inline done-list + the standalone quick-log section, which were redundant). The screen is then TRIMMED to that focused shape: the Stories row, the plan⇄AI-coach pager (collapsed to a single hero), the check-in/nutrition square widgets, the week-adherence + calendar pair, the reconciled 'This week' block and the Connect feed/coach rails are removed from Today — those features stay reachable via their own screens (Cockpit, Calendar, Coaches, Feed, AI coach). Below the hero: a violet 'Go Full – your edge' band (Cockpit + Sport baits) and a Follow-a-coach row (the section that once carried nutrition alongside it is gone — fuelling lives on its own Nutrition screen). Keeps chartreuse reserved for the single primary action; premium routes wear violet/lime accents per the semantic spectrum." },
  { id: "plan-week-rail", area: "Core", status: "shipped", title: "Plan week rail (date-anchored 'today')", detail: "The count-based 'Your plan today' (dayIndex = sessionsLogged % trainingDays — which rolled the card to the next day the instant you finished one, and could never represent a missed or skipped day) is replaced by a DATE-ANCHORED week rail on Today/Home (web today.tsx + mobile home.tsx, at parity). @hybrid/core's planSchedule() pins the enrolled program's days onto consecutive calendar dates from the plan's start (Macrocycle.startedAt) and reconciles each date against logged sessions + skip overrides, giving every day a readable STATUS: done (a session logged that date, with its id linked), missed (a past training day with nothing logged), skipped (explicit, no adherence penalty), today, upcoming, or rest. A horizontally-scrollable seven-day strip shows the week with per-status visuals (done = filled lime + check, missed = amber, skipped = struck-through slate, today = lime rim + pulsing dot, upcoming = faint outline, rest = moon); chevrons page a week; tapping any day opens a STATE-AWARE detail card that decides the action — Start / Do it now / Start early / View in history / Skip / Undo skip / Postpone (move to a later day, which relocates the session onto that day's card as a catch-up item) / Un-postpone. planAdherence() derives a done-vs-due % (skips + postpones + rest excluded). Pure + unit-tested (plan-schedule.test.ts); both clients render the same schedule off the SAME programCalendarDays() day-builder that the legacy count-based planProgramToday now also uses, so display + prefill can't drift. Skips persist client-side (localStorage on web, AsyncStorage on mobile) through a storage-agnostic override map the engine consumes — the server-backed sync + the postpone action are the plan-schedule-persistence follow-up. SESSION TABS (Jul 2026): a day's content is now GROUPED BY SESSION in @hybrid/core (planSchedule → ScheduledDay.sessions, built by the shared programCalendarDays day-builder, with the flat rows/blocks preserved) so a multi-session day (the Soviet block's AM/PM doubles, or any day the plan authors as several trainings) renders one TAB per session instead of one heading stacked over every lift — the title stays welded to its own lifts. Each session carries a timeOfDay ('AM'/'PM' when the plan sets one) + a 1-based ordinal; the tab label is the time-of-day, or a plain 'Training N' fallback when the plan gives no time (the ordinal, never a fabricated time, is the anchor), and the primary Start now prefills just the ACTIVE session's blocks (not a merged AM+PM blob). DESLOP: the detail card's accent LEFT BORDER was removed (status reads from the state pill, not a glowing rail), and the two cramped header chevrons became round pagers that hug the rail edges with an edge-fade (a CSS mask on web, expo-linear-gradient on mobile) so the strip visibly runs past them. Both clients at parity (web week-rail.tsx + mobile week-rail.tsx); unit-tested (plan-schedule.test.ts asserts the grouping re-flattens to the day's rows/blocks and carries the AM/PM band); new i18n key w.home.rail.session (EN/PL). SESSION IDENTITY IS CONSISTENT EVERYWHERE a plan day is laid out (the Today week-rail tabs AND the Plans program table, program-days.tsx + percent-program.tsx): the time-of-day model widened from AM/PM to AM/MID/PM (SessionTimeOfDay) so a three-a-day is expressible, and a shared pure sessionColor(label, index) in @hybrid/core gives each session marker a stable hue (AM lime, MID amber, PM blue; untimed sessions cycle by ordinal) so the same session can't read one colour on Plans and another on Today. The Plans table now also shows a marker for UNTIMED multi-session days ('Training 1/2/3' from the ordinal) instead of silently merging them under no band — so whether a day is split by clock (AM/MID/PM) or just numbered, its sessions are always distinguished. sessionColor unit-tested (plan-program.test.ts)." },
  { id: "history-calendar-views", area: "Core", status: "shipped", title: "History × Calendar — three switchable merged layouts", detail: "The History screen on BOTH clients carries a view switcher offering FOUR merged History × Calendar layouts, so the athlete picks how their training story reads (choice persists per device — localStorage / AsyncStorage 'hybrid.historyView'): (1) AGENDA (the default) — a pinned current-week strip with load dots, the next plan days as dashed 'planned' ghosts (from the date-anchored planSchedule), a highlighted TODAY group, then the past newest-first with rest gaps collapsed to hairlines; (2) WEEKS — Mon–Sun week chapters, each with a 7-day load sparkline, weekly totals and slim session rows; (3) TIMELINE — a vertical diary rail with date nodes sized by load (teal for sport days) and rest gaps as literal empty space; (4) TREND — the RETIRED Statistics screen, folded in Jul 2026: its week/month/year range toggle, session-count bar chart (peak bucket in chartreuse) and window totals (active days, distance, minutes), off the same sessionBuckets() / weeklyRecap() engines, so no number changed on the way over. Statistics was a second destination charting the SAME sessions History already held, one grain coarser — the same screen twice. Its nav entry is now promotedTo \"history\" (menus drop it; route, icon, label and gate stay live), and the \"This week\" card on Today points its History row here. RETIRED LAYOUTS: the classic LIST and the HEATMAP were trialled and dropped early; the JOURNAL (month grid) and BLOCKS (plan-week chapters) layouts were removed Jul 2026 (user request) — normalizeHistoryView maps their persisted ids (and anything unknown) to the agenda, so a device with an old choice degrades gracefully; the list markup survives only as the archived-management screen, and because its swipe actions went with it, archive/delete for LIVE sessions moved onto the session breakdown (web SessionDetail gets optional onArchive/onDelete/manageBusy rendered as a manage row of shared Button pills — the lib/ui Button primitive now carries a fill|outline variant on BOTH clients, outline tinted by `color` for destructive actions; mobile /session/[id] uses the shared useSessionActions hook — one busy/confirm/invalidate/error flow with the archived list — and reads sessions from the react-query cache; archived cards are non-openable on both clients since the detail route serves only live sessions). ALL grouping/aggregation math is shared + unit-tested in @hybrid/core engines/history-views.ts (historyStream, upcomingPlanDays, weekChapters, HISTORY_VIEWS registry, shared day-key/loadLevel/WEEKDAY_LABEL_KEYS from the calendar engine; the journalMonth + blockChapters aggregates were deleted with their views, as was the heatmap-only historyStats) — web + mobile only render via a compile-checked view→component table; same encoding as the calendar (chartreuse = lifting, teal = sport/cardio, shading = sRPE load); i18n EN/PL/DE (histview.*). POST-REVIEW HARDENING: every aggregate (day chips, weekly totals) is bodyweight-aware (BodyweightLookup threaded into every engine call, matching the per-session cards); every view function accepts the clients' memoized PR lookup (PrLookup) so PR detection never re-runs O(n²); the agenda surfaces TODAY's still-open plan session as a chartreuse due-today ghost (not just future days); ghost labels localize Week via histview.weekLbl; conditioning-only sessions (match/circuit) read summed minutes everywhere including the archived list; mobile hydrates the persisted view choice behind a loader (no default→saved-layout flash). KNOWN LIMITS: on mobile the aggregate layouts render inside the FlatList header (not virtualized — the archived list still is). Day-keying is unified on the athlete's LOCAL calendar day app-wide (see history-daykey-unification). JUL 2026 CARD REDESIGN — the 'headline number' treatment (user-picked from 10 mocked concepts, reference/history-mockups/history-redesign-10.html): the old title+metric-chip+raw-blockSummary card said everything twice (single-block sport logs echoed 'Tennis, 75 min' in title AND block line; swims restated distance/time in two unit systems; lifting cards dumped every set). Cards now lead with ONE large mono figure via the shared engine sessionHeadline(session, units, bwKg) — tonnage for lifting/mixed (bodyweight-aware, kg 't' / lb), distance in the sport's NATURAL unit for cardio (metres for swim/row via displaySportDistance, km otherwise; pace only for single-activity sessions — a summed pace would lie), minutes for timed sports, block count as last resort — followed by one mono meta line (title – N lifts – minutes – pace – ↑PRs in lime) where each fact appears EXACTLY once (minutes suppressed when minutes IS the headline). The agenda's day-level tonnage/PR chips were removed (the cards now carry the numbers) and the weeks-view rows read from the same headline; i18n histview.liftLbl/liftsLbl (EN/PL/DE); unit-tested in engines/history-views.test.ts. NEXT: fold the standalone Calendar screen into this merged History." },
  { id: "history-daykey-unification", area: "Core", status: "shipped", title: "One day-key convention — the athlete's LOCAL calendar day, app-wide", detail: "The app previously split day-keying two ways: the calendar engine (sessionsByDay/trainingHeatmap), history views, habits/streaks, recap, nutrition days and body-progress keyed days by UTC (iso.slice(0,10)) while plan-schedule.ts keyed by LOCAL midnight — so an athlete in a negative-UTC-offset zone logging an evening session could see it on one date in the week rail / Blocks view and the NEXT date in Agenda/Journal/Heatmap/Calendar. Now unified on the athlete's LOCAL calendar day via one canonical module, packages/core/src/day-key.ts (localDayKey / localTodayKey / localMidnightMs / addLocalDays [DST-safe day stepping — a local day can be 23/25 h] / localMondayMs / dayKeyDiff [pure label math]). Converted in one sweep: engines/calendar.ts (sessionsByDay groups local; trainingHeatmap anchors on the LOCAL Monday and steps calendar days; monthMatrix unchanged — it enumerates calendar-date LABELS), engines/history-views.ts (stream/stats/journal/weeks + gap math via dayKeyDiff), engines/habits.ts (activeDays, streak day-numbers via label math, weekly counts, dailyChecklist 'today'), engines/recap.ts activeDays, engines/nutrition.ts daily buckets + todayNutrition, engines/composition.ts point dates, body-progress weigh-in days, and plan-schedule.ts now delegates its dateKeyOf to the shared helper. Clients: both calendar screens' today-highlight + selected-day session filter, both history-views' week strip/today keys/selection, and the date-input defaults (coach assign date, coach-programs, competition target) all use localTodayKey/localDayKey. stats.ts was already local (toDateString) and is untouched. VERIFIED cross-timezone: the full core suite (830 tests) passes under TZ=UTC, TZ=America/New_York, TZ=America/Anchorage and TZ=Pacific/Auckland — fixtures for calendar/history-views/heatmap/nutrition were rewritten to LOCAL-constructed timestamps so the expectations are timezone-invariant, and day-key.test.ts pins the 23:30-local boundary case explicitly." },
  { id: "plan-schedule-persistence", area: "Core", status: "shipped", title: "Plan schedule — server-backed skips + postpone", detail: "The week rail's per-day overrides now persist SERVER-SIDE for cross-device sync, and POSTPONE is a first-class action. Built: (1) the PlanDayOverride table (prisma/schema.prisma) — one row per (user, plan, local date key) holding only explicit intent, status 'skipped' | 'postponed' + a postponedTo target date; 'done'/'missed' stay derived so the table never fights reconciliation. (2) /api/plan-days (GET returns the plan's override map, POST upserts/clears one day) — every handler tolerates the table not existing yet and degrades to a no-op, so the rail keeps working off its client cache until the migration runs. (3) Both client stores (web lib/plan-overrides.ts localStorage + mobile AsyncStorage) are now write-through: they hydrate from the server on mount and POST optimistic writes, keeping the offline cache as the immediate source. (4) POSTPONE in the engine (planSchedule): a postponed day is excluded from the adherence penalty, points at its target via postponedTo, and its session is RELOCATED onto the target date's card via postponedIn (a catch-up list) — surfaced on both clients with a violet 'Postpone' action (moves to the next day), an 'Un-postpone', a 'Moved to {date}' state, and the target-day catch-up section. Unit-tested (plan-schedule.test.ts). The PlanDayOverride table is APPLIED in production (sql-pending.sql run, Jul 2026) — skips/postpones now sync across the athlete's devices." },
  { id: "today-plan-vs-done-separation", area: "Core", status: "shipped", title: "Today — scheduled plan vs 'Also today' off-plan separation", detail: "Today/Home now separates THE PLAN'S scheduled workout from WHAT WAS ACTUALLY DONE (user-picked 'Design 1 — stacked cards' from design/, Jul 2026). Previously an off-plan workout (e.g. a quick-logged tennis match) was invisible on Today except behind the done-count ring's modal — AND it silently marked the plan day 'done' (planSchedule counted ANY session on the date), so the rail showed 'View in history' instead of Start/Skip/Postpone for a day whose prescription was never touched. Two changes, shared in @hybrid/core: (1) MATCHING — planSchedule now claims a session for a plan day only when it's recognisably that day's workout (sessionMatchesPlanDay: the client-composed plan title '<plan>' or '<plan> – …', OR ≥1 exercise/block name shared with the day's prescription — the block-overlap arm covers the web logger's auto-titles like 'Evening workout'); the result carries fulfilledSessionIds, and offPlanSessionsOnDay() returns today's unclaimed sessions (everything, when un-enrolled). Unit-tested (plan-schedule.test.ts: sport log can't complete a day, auto-titled plan session still does, the split, title-form edge cases). (2) UI — a teal-coded 'Also today — off-plan' card on BOTH clients (web aurora/today.tsx AlsoTodayCard + mobile aurora/home.tsx twin) between the plan card/week rail and the feeling card: one row per off-plan session (shared core sessionIcon tile, title, sport-adaptive meta + shared sessionClockTime logged-at time, lime check; tap → the session's breakdown on both clients — mobile /session/{id}, web deep-links History via the app-shell's pendingSessionId → AuroraHistory initialOpenId), a count badge, and a dashed '+ Log another workout' footer that opens the quick sport-log sheet. The week rail now correctly keeps Start/Skip/Postpone on a day where only unrelated training was logged. i18n EN/PL/DE (w.home.today.alsoToday, w.home.today.alsoTodayLog); with no schedule the kicker falls back to plain 'Done today' — nothing is 'off-plan' relative to a plan that doesn't exist. REVIEW-HARDENED (same change, post 8-angle review): (a) the content arm needs ≥2 shared exercise names when the day prescribes ≥2 blocks, so a freestyle session containing one common lift (Back Squat) can't silently swallow the day; (b) RUN days (endurance discipline, or any cardio '…run…' block) accept a cardio-only logged RUN — the quick sport log's natural output — while a racket/team sport still doesn't; (c) claiming is ORDERED, content-match first then plan-generic title as fallback, and a POSTPONED day claims a content-match on its TARGET date, so the catch-up 'Do it now' flow credits the source day instead of being mislabeled off-plan (or stealing the target's day); (d) WEB now stamps the plan-composed title at save time (rail/plan-card onStart carries title → app-shell pendingTitle → logger initialTitle), at parity with mobile's pendingPlanSession — the fuzzy content arm remains for pre-existing auto-titled sessions; (e) planSchedule surfaces every fulfilledSessionId (not just each day's first) so an AM/PM day's second session is still credited to the plan on Today; (f) plannedToday (both clients) guards on isToday so an ended/not-yet-started plan can't leave a phantom scheduled count. The done-count ring still counts EVERYTHING logged today (it tracks training done, not plan compliance). UPDATE (Jul 2026, user-requested): the Done-Today card now lists EVERY session logged on the viewed day as a row — the plan-claimed workout included, wearing a lime tile + a mono 'Plan' tag (off-plan rows keep the teal tile) — so the display-weight count and the visible rows always agree (previously the plan workout hid behind the count and only off-plan extras were rows, which read as a missing workout). The 'off-plan — beyond the schedule' sub-line was retired with its i18n key (alsoTodayCopy simplified to {doneCount, isToday}, unit tests updated); rows come from sessionsOnDay with plan membership from PlanScheduleResult.fulfilledSessionIds. Both clients at parity (web today.tsx + mobile home.tsx). KNOWN TRADE-OFFS (deliberate strictness): a plan-titled session on a REST day shows as an extra; an AI-prescribed or routine/freestyle session done INSTEAD of the plan day leaves that day open (it appears under 'Also today' and the day stays actionable — Start or Skip); switching historical data to the strict matcher can flip old loosely-matched days to missed (the athlete can Skip them, no penalty); renaming a plan in the library breaks the title arm for old sessions (the content arm still matches unedited ones). UPDATE (Aug 2026, user-requested): the row meta line NO LONGER ends with the session's clock time. '0.2 km – 10 min – 21:33' read as the time the swim happened, but for a quick-logged sport startedAt is stamped at save time — so it was the moment the RECORD was typed, presented as a property of the workout. Bookkeeping, and wrong at that; dropped on both clients (web today.tsx, mobile home.tsx) leaving the row to state only what was done. sessionClockTime still serves the readiness-read timeline and the session detail header, where 'when it was written' is the actual subject. The freed space now carries PACE (user-picked idea 1 of five in design/done-row-tail-ideas.html): '0.2 km – 10 min – 5:00 /100m'. Distance and duration say how much, pace is the only figure on the line that says how hard, and it needs no new data — sessionCardioTotals already derives secPerKm, and formatSportPace/sportPacePerMeters already label it in the sport's own split (/km, /100m for Swimming, /500m for Rowing & Canoe Sprint). No tail when the session can't honestly be paced: a timed sport (Tennis 75 min), a distance with no clock, or — the case worth naming — a session MIXING sports with different splits, where the distance-weighted secPerKm would print one figure under one sport's label while describing both. In the SAME change, sessionMeta itself moved into core (engines/session.ts): it had been hand-written identically in web today.tsx and mobile home.tsx, so both clients now import one function; unit-tested (session.test.ts — per-sport splits, every no-tail branch, the mixed-split refusal, strength tonnage, and a regression that the line never ends in a wall clock)." },
  { id: "log-sport-vs-workout-clarity", area: "Core", status: "shipped", title: "Today — 'Log a sport' vs 'Log a workout' disambiguated", detail: "Two adjacent Today actions read as the same thing but did different work, so users couldn't tell them apart: the 'Also today' card's dashed footer said 'Log a workout' / 'Log another workout' yet opened the QUICK SPORT log (QuickSportLog — a single cardio activity: a run, a swim, a match, time + optional distance → /api/sessions), while the STRUCTURED block logger (the Train hero / launcher, the logbook rail's empty-day CTA, the first-run 'Just train' chooser) is the one that actually logs a 'workout'. Fix (copy only, no behaviour/schema change, shared in @hybrid/core so both clients move together): the sport quick-log now says SPORT everywhere and 'workout' is reserved for the structured logger. alsoTodayCopy (plan-schedule.ts) returns new logKeys — w.home.today.alsoTodayLogSport ('Log a sport', empty) / alsoTodayLogSportMore ('Log another sport', once anything's logged) — instead of the old alsoTodayLog*/workout keys; the QuickSportLog sheet header (w.home.quickSport.title/.sub) changed from 'Already trained?' / 'Log it — it still counts' to 'Log a sport' / 'A run, a swim, a match — it still counts'. The logbook rail's full-workout CTA keeps w.home.today.alsoTodayLogFirst ('Log a workout') — it opens the real logger, so the word is now correct and unambiguous. i18n EN/PL/DE; alsoTodayCopy unit tests updated (plan-schedule.test.ts). Both clients at parity automatically — the AlsoTodayCard label (web today.tsx + mobile home.tsx) and the sheet title render straight from these core keys. FOLLOW-UP (same task, 'go further'): the structured-logger side was then unified on the word WORKOUT so every entry to the block logger reads consistently and parallels 'Log a sport'. The first-run + logbook chooser card 'Just train' (chooserLogTitle) → 'Log a workout' (sub reworded off the doubled 'Log…log a workout' to 'One workout, right now — no plan needed.'); PL 'Po prostu trenuj' → 'Zapisz trening', DE 'Einfach trainieren' → 'Training loggen'. Verb/word alignment so each language pairs cleanly (EN Log a workout / Log a sport; PL Zapisz trening / Zapisz sport — the logbook rail CTA alsoTodayLogFirst PL moved 'Dodaj'→'Zapisz' to match; DE Training loggen / Sport loggen — slimLogSub DE 'Workout'→'Training'). The 'Just train' label is fully retired from the UI (the sand ↯ glyph and the card's onStart→logger behaviour are unchanged); the two 'Follow a plan / Build your own / …' code comments updated. NOT touched (deliberate, out of scope): the Train nav tab / centre FAB / launcher ('Train', 'Start training') — those name a navigation destination, not a log action, so renaming them is an IA change, not a copy fix; and nav.log ('Log session'), which is the same-screen nav item, not one of the confusable Today controls." },
  { id: "live-logger-set-focus", area: "Core", status: "shipped", title: "Live logger — focus the active set, sunset the rest ('Glass + ghost add')", detail: "A live workout with many sets used to render every row at equal weight — eight near-identical outlined rows with no answer to 'which set am I on?' (the screenshot problem). The logger now lifts exactly ONE set and recedes the others (user-picked concept 01 'Glass + ghost add' from design/sets-focus-apple-2types.html, Jul 2026). Shared model in @hybrid/core set-focus.ts (unit-tested, 10 tests): activeSetIndex() = the first un-banked set (the next thing you do; role-agnostic; −1 when the exercise is complete), setFocus() classifies each row done | active | upcoming, and addSetIsNext() encodes the TWO logging habits from one rule — true (prominent) when nothing is queued below the active set (the one-at-a-time lifter, whose next move IS adding a set), false (quiet) when a plan already sits below (the plan-ahead lifter). PRESENTATION only — changes no data. Both clients at parity, gated to the LIVE logger so the Builder (which edits a plan, has no 'now') is untouched: the LIVE logger drops the set TABLE entirely and renders the active set as a FLAT hero section directly on the exercise card (late-Jul 2026 de-slop pass, on user review: the earlier frosted lime glass card read as a card-inside-a-card and washed the screen green, so the inner border/tint/glass/glow were removed — focus now comes from SCALE and breathing room, and the only lime left in the logging loop is the Log CTA itself): a mono eyebrow ('Set n — up now', gaining an 'of N' denominator only when a queue waits — from addSetIsNext), weight and reps as two EQUAL big editable numbers (46px display, one shared baseline so 'kg' and 'reps' sit level) whose UNIT labels are tap targets that focus the field (web wraps input+unit in a <label>; mobile focuses via an inputRefs map), a planned-rest hint on the label row (prefs.restSeconds when the rest timer is on, else hidden — both clients read the same logger pref; web passes it via the new restSec prop), and — since the Jul 2026 'set-logging-redesign.html' pass — RPE tucked behind a QUIET CHIP on the label row (rpe/rir + value, or '–'; tapping it reveals a ONE-TAP PILL ROW of the core RPE scale — late-Jul 2026, replacing the earlier full-width text input the user flagged as unnecessary for a single number: one pill per RPE_SCALE step, RIR labels when swapped, tap sets the value and closes, tap the picked value again to clear, the RPE⇄RIR toggle leading the row; Simple mode hides it entirely), and a proper full-width 'Log set ✓' BUTTON below the numbers (one tap banks the set + starts rest); the earlier floating ＋ circle was retired as oversized, and per-set m/s entry moved to the exercise detail sheet (see live-logger-exercise-sheet). Banked + queued sets COLLAPSE to quiet one-line hairline-separated LEDGER ROWS (late-Jul 2026: the boxed mini-card rows were flattened — no card-in-card) that tap/click to re-open (banked → active again); bodyweight lifts put reps in the hero (no load), plank/carry read s / m. Per-set drag-reorder (grip) is preserved on both the hero and the collapsed rows; set DELETE is now swipe-only — swipe a row left to reveal a red Delete (the always-visible '−' icon buttons were removed as clutter, Jul 2026). Mobile uses the existing SwipeRow (PanResponder); web gains a matching components/swipe-row.tsx (Pointer Events — works with touch or a mouse drag) that starts a swipe anywhere except a text input or the grip and swallows the tap once a horizontal drag is claimed, so the banked-row 're-open' tap and the log '＋' still fire. The action row is now two glass tiles (Jul 2026 redesign): '+ Add set' is a SPLIT tile — the wide zone quick-adds one carry-over set (still following addSetIsNext: a brighter chalk hairline + bold label when it's the next move — no lime fill since the de-slop pass — quiet card when a queue sits below), a ⋯ zone opens the presets/plan panel; and a GLYPH-ONLY '⚡' Special tile (the text label was dropped) holds the warm-up / ramp / cool-down / drop menu. The ⋯ panel is a single POPULAR-PRESETS RAIL (Jul 2026 redesign — the earlier 2×2 preset grid AND the manual plan-ahead stepper were removed as over-nested clutter, on user request): a horizontal, edge-bleeding scroll of scheme cards — 3×3 (heavy), 5×5 (strength), 3×12 (hypertrophy), 4×8 (volume), 10×10 (GVT) — each showing its total working reps; one tap (applyPreset) lays out that whole scheme as the exercise's working sets (each rep count a SINGLE number, carrying the current load; banked sets kept, the un-banked plan replaced). The rail bleeds to its container's edge by the gutter width with matching inner padding (mobile ScrollView marginHorizontal −space.lg inside the exercise Card; web overflow-x rail with margin/padding ±14 inside the popover), per the full-bleed-rail idiom, so cards slide under the edge. addPlannedSets and the Straight/Pyramid shapes are retired. To close the incremental lifter's tap-tap loop, the WEB logger's addSet honours the carryOver logger pref (default on) — a new set seeds from the last set's load/reps/rpe as a clean working set, at parity with mobile's emptySet(from); the Builder still adds blank sets since it never passes the pref. i18n keys workout.setWord / ofWord / upNow / logSet / restShort / presetsTitle / presetReps / schemeHeavy / schemeStrength / schemeHypertrophy / schemeVolume / schemeGvt (EN/PL/DE, web mirror under w.train.blocks.*); no schema change." },
  { id: "live-logger-exercise-sheet", area: "Core", status: "shipped", title: "Live logger — exercise detail sheet (per-set bar speed) + live per-exercise summary", detail: "From the empty-logger UI review (late-Jul 2026): every STRENGTH card in the LIVE logger now ends in a tappable LIVE SUMMARY BAR — sets banked of total, tonnage so far, top set (load × reps) and, once entered, mean bar speed — derived by the new @hybrid/core exerciseLiveStats() (live-stats.ts, unit-tested; reuses strengthBlockStats so it can never disagree with the Builder's signal math; bodyweight-aware). The EXERCISE DETAIL SHEET (the shared aurora Sheet on both clients — mobile ExerciseSheet in app/workout.tsx, web ExerciseDetailSheet in components/workout-blocks.tsx) opens two ways (entry picked by the user, review round 3): PRESS-AND-HOLD anywhere on the strength card — mobile a bare Pressable onLongPress wrapper (400 ms, medium haptic; interactive children keep their own touches), web the pointer twin (pointerdown starts a 400 ms timer; starting on an input/button/grip is ignored, >8 px movement or pointer up/leave/cancel aborts, so scroll/swipe/drag never false-fire) — or tapping the summary bar, the visible entry. V2 layout after a second review round (the first cut's boxed stat cells re-introduced card-in-card, duplicated 'm/s' between a stat cell and the input caption, and had a redundant set-pill selector): FLAT totals (big number over a small mono label, no boxes — total volume + the picked set as load × reps), then ONE velocity module where the unit is named exactly once — a 'BAR SPEED (M/S)' header carrying the mean, above a bar chart that IS the set selector: each set is a column with its m/s value riding above its bar, the SELECTED column's value is the editable input (underline style, no boxed field), bars share a hairline baseline, and set numbers (✓ on banked) sit underneath as secondary tap targets — the manual-VBT twin of a bar-sensor app's set screen, modelled on the user's reference shot. This replaces the old inline m/s field on the active-set hero (the velocity logger pref still shows the m/s column in the non-live Builder grid); entered speeds keep feeding StrengthSet.vel → the vbt-engine/Velocity screens unchanged, and live sensor capture remains the blocked vbt-capture capability. i18n: workout.setsWord / topWord / meanWord / totalVolume / barSpeed / exDetail / velHint (EN/PL/DE)." },
  { id: "today-day-scoped-cards", area: "Core", status: "shipped", title: "Today — Also-today + feeling cards follow the rail's selected day", detail: "Tapping a day chip on the plan week rail now scopes the WHOLE Today screen to that day, not just the scheduled-plan detail: the rail lifts the tapped ScheduledDay to the caller via a new onSelectDay prop (web + mobile week-rail.tsx), and Today/Home (web today.tsx + mobile home.tsx, at parity) re-keys the 'Also today' card (done count via sessionsOnDay(sessions, day.ts), off-plan rows via offPlanSessionsOnDay(…, day.ts)), the Done-Today sheet, AND the feeling card to the viewed day. Until the first tap (or on tapping today's chip) everything stays pinned to the real today. Day-aware presentation: on a non-today day the done label/sheet title read 'Done {date}' (new i18n w.home.today.glanceDoneOn, EN/PL/DE), the empty sub-line goes past-tense ('nothing logged this day' — alsoTodayCopy in core grew an isToday flag + w.home.today.alsoDayEmpty; unit-tested), the sheet's empty line drops the 'start your session' invitation (doneModalEmptyDay), and the quick-log ghost row hides (a quick log always saves at 'now', so it can't land on another day). FEELING: the clients keep the raw /api/checkins list and derive the VIEWED day's check-in, so a past day shows that day's logged feeling; tapping a face on a past day BACK-LOGS it (weekOf = that day's local noon — the API already accepted a client weekOf); a future day is read-only (you can't feel the future). The card shows the viewed date next to the title, and the 6h re-log cooldown now mirrors the server exactly — computed from the newest check-in's createdAt (a global write-lock across days), with the 'Next in Xh Ym' chip also shown alone when the faces are locked on a day without its own check-in." },
  { id: "today-pill-rail", area: "Core", status: "planned", title: "Today \u2014 sticky pill rail (the contracted calendar) \u2014 REMOVED", detail: "RETIRED. The sticky rail Today left behind on scroll \u2014 up to three pills (DATE from the week strip, DONE from the day's result, READINESS from the check-in) captured as their source cards passed under a 46dp bar \u2014 has been DELETED from both clients, along with packages/core/src/today-rail.ts, its unit tests, the 11 i18n keys (w.home.pill.*, EN/PL/DE) and the week-row measurement hooks both week rails (plan + logbook, both clients) carried only to feed it. WHY: it was a SECOND head competing with the screen's own chrome, and it answered questions the athlete had already read rather than taking them anywhere \u2014 a status bar, not navigation. The scroll-persistent slot on Today is being re-spent on the HUB itself: the Dashboard / Performance / Feed switcher detaching into floating pills as you scroll, so the persistent element is a way OUT of the current view instead of a summary of it (see today-hub-floating-pills). The capture/hysteresis/ceiling model (todayRailState, TODAY_RAIL_MOTION) is worth recovering from git history if a contracted status rail is ever wanted again \u2014 but it must not return as a screen-top overlay." },
  { id: "today-hub-floating-pills", area: "Core", status: "shipped", title: "Today hub \u2014 the tabs detach into floating pills on scroll", detail: "Replaces the removed sticky rail (today-pill-rail). The Dashboard / Performance / Feed switcher used to scroll away with the profile header, so reaching Performance or Feed from deep in the dashboard cost a full scroll back to the top. It now DETACHES and floats. Two rules, both in one shared engine \u2014 packages/core/src/today-hub-dock.ts, 24 unit tests \u2014 so the clients cannot drift on when a pill appears. SPLIT: once the in-flow segmented control has scrolled off, the three destinations stop being segments of one track and become three independent glass pills; the equal-width constraint that forces glyph-only labels only exists INSIDE a track, so exactly one pill \u2014 the one you are in \u2014 carries its WORD and the two siblings contract to a 44pt glyph. Selecting a sibling is a width EXCHANGE (one inflating to its word as the other contracts), which is the physics the LiquidSeg lens carried inside the track. RETURN: the row answers scroll DIRECTION, not depth \u2014 reading down sends it off the top edge (180ms, flat: something leaving should not ask to be watched), and the first upward run of 12px or more brings it straight back (220ms on the pin curve). The dead zone is a RUN accumulated across frames, not one event's delta, so a slow drag commits and momentum decay does not; offsets are clamped at zero before anything is compared, because iOS rubber-band and Android overscroll both report negative offsets and an unclamped diff turns the settle of a bounce into a phantom flick at the very moment you arrive at the top. Re-attach uses a looser threshold (10px) than detach so crossing the line cannot make the row flicker. THRESHOLD: detach is 'the real control has left the viewport', never a fixed depth \u2014 detaching at the nav bar's 48px would draw the floating row while the in-flow control is still on screen, i.e. two copies of one control. Web measures the switcher's exact bottom edge (getBoundingClientRect) and passes it; mobile passes none and takes the shared HUB_DOCK_FLOOR (116), deliberately a touch late, because rebuilding the switcher's content-space y from its parent chain is the exact fragility the deleted rail carried and the three views nest it differently. REDUCED MOTION falls back to DOCK, the runner-up treatment: one capsule, glyph-only, permanently on screen while detached \u2014 a shipped shape rather than a degraded one, since RETURN's whole value is the motion and a control that vanishes without one has simply disappeared. The row is LEADING-ANCHORED rather than centred, and it lines up with the CONTENT COLUMN rather than the raw screen edge \u2014 the pills sit exactly where the in-flow switcher's own left edge was, so detaching reads as the control lifting straight up instead of sliding sideways on its way out. Web measures that edge from the same rect as the threshold (its column is inset by the shell's sidebar, so a row flush to the viewport would float over the nav \u2014 verified at 1280 wide: pill left 272, column left 272); mobile's 16dp screen gutter IS the column, so it takes the shared HUB_PILL.inset. MOTION IS THE APP'S SPRINGS, AND ON iOS THE GLASS IS REAL (Aug 2026, from live feedback that the floating row 'should look more like Liquid Glass with the native transition'). It shipped wearing glass as a MATERIAL: three static glassEffect tiles whose widths were tweened in JS on five bezier curves the dock had minted for itself (HUB_DOCK_MOTION), plus a 40ms per-pill scale stagger (hubSplitDelay) standing in for the split. Both are gone. (1) THE GLASS IS ONE BODY: apps/mobile/components/aurora/swiftui.tsx GlassPillRow is a native SwiftUI GlassEffectContainer whose three capsules share a Namespace and carry a glassEffectId, so the system treats them as one volume of glass — adjacent capsules FUSE, and a frame that changes makes the glass FLOW between the old shape and the new (rim travelling, refraction re-sampling, a droplet stretching and pinching off) instead of a blur being resized. (2) SPLIT IS NOW THE GAP, on both clients: the row arrives with the pills touching — which under Liquid Glass is not three shapes but ONE lozenge — and springs them apart; leaving, it runs backwards and they merge. One animated number replaces the stagger, and it finally renders the split in the material rather than miming it with three views scaling in. (3) ONE PHYSICS, THREE RENDERERS: HUB_DOCK_SPRINGS binds the dock to the shared tokens (motion.ts) — EXCHANGE is springs.lens (the very spring the in-flow switcher's selection flies on, because it is the same gesture one layer up) and SPLIT/MERGE is springs.sheet; CONCEAL stays a bezier because it is opacity and a short lift with nothing positional to interrupt, and it stays faster than the arrival. hubMotion() returns each transition as {ms, spring, css, bezier}, so SwiftUI gets response/dampingFraction natively, RN gets the same token through springToRN, and CSS gets a sampled linear() — all three integrating ONE differential equation rather than three curves that agree at the endpoints and drift in between. That is what keeps the glyph on the capsule it is riding: the marks, the words and the taps stay in React Native ON TOP of the glass (same vector glyphs as the in-flow switcher, same type, same i18n, same accessible names), laid out from the same shared widths (hubPillWidths). Nothing is driven frame-by-frame over the bridge — the native side is handed target numbers and animates itself, which is what made the earlier JS-driven glass jank. The Host is pointerEvents='none', so if the native layer never renders (pre-iOS-26, a failed mount) the RN row above is still the entire working control; Android and Reduce Motion keep the RN treatment unchanged. ALL THREE VIEWS carry it: web mounts it in the shared hub header, PORTALLED TO THE BODY \u2014 the screen-transition wrapper carries a transform, and a transformed ancestor becomes the containing block for position:fixed, so a nested fixed row scrolled with the page (measured); the portal also keeps the dock out of the hub's own view transition, which is what 'the chrome holds still' requires. Mobile layers it OVER each view's scroller (Performance and Feed own their own) and rides the nav-scroll signal every scroller already publishes \u2014 extended with a subscribe() for the raw offset \u2014 so there is no second scroll listener anywhere; the dashboard's safe-area inset moved from the shell to a padded layer inside it so the dock mounts in the same coordinate space on all three. Selecting a hub tab on web now scrolls to the top: the three views share one window scroll and the dock made it possible to switch from deep inside a page for the first time. Both clients keep each pill's accessible name from TODAY_TABS (the glyph stays decorative), the row is hidden from assistive tech while concealed, and mobile fires a selection haptic. Design study of the seven candidate treatments, the storyboards, the comparison matrix and the open decisions: the artifact linked on the PR." },
  { id: "today-themed-groups", area: "Core", status: "shipped", title: "Today — dashboard grouped into four themed clusters (Train / Recover / Progress / Explore)", detail: "Today's dashboard had grown into a flat scroll of ~9 blocks — plan hero, exercises rail, done-today, feeling, week verdict, endurance lanes, other sports, Go Full, coach rail — each with its own head but no higher-level structure, so the page read as chaos. It is now organised into FOUR NAMED CLUSTERS, each opened by a GroupMark. REVISED (Aug 2026, the cluster-marker study): the marker is the HEADLINE TIER — the cluster's name as pure type in the display face at 23 (serif in Kyoto Hour, like the masthead), sitting between the masthead (34) and the block heads (18), with 36px/dp of whitespace above doing all the separating and NO other chrome. The first cut (mono-uppercase label + a trailing hairline) was retired: label-plus-rule is the default divider generated layouts reach for, and the rule restated a separation the whitespace already performed. TRAIN = the scheduled hero (week rail / logbook / chooser / plan card) + the Done-today card (schedule and receipt are two sides of the same day). RECOVER = the feeling/check-in card. PROGRESS = This week's verdict, the favourite-exercise widget rail (MOVED here from its old slot between the hero and Done-today — it is per-movement trend, not part of the day's job, and now sits directly under the verdict whose lifting columns it breaks down), endurance lanes and other sports. EXPLORE = Go Full + the coach marketplace rail (the label the retired Explore tab left behind). Nothing was removed; every block keeps its own head and behaviour. Web today.tsx + mobile home.tsx at parity via shared i18n keys w.home.group.* (EN/PL/DE); markers are headings to screen readers (role=heading / accessibilityRole=header)." },
  { id: "performance-themed-groups", area: "Core", status: "shipped", title: "Performance page — organised into four named clusters (State / Training / Season / Explore)", detail: "The Performance hub tab (Today's second pill) was a flat scroll of ~11 blocks — state card, trajectory, injury risk, week recap, breakdown, volume, trends, horizon, goal+season, return-to-play — numbered in comments but visually undifferentiated: the same disease Today's dashboard had before its clustering. It now wears the SAME taxonomy system: four named clusters, each opened by the shared headline-tier GroupMark (extracted to aurora/group-mark.tsx on both clients when this second consumer arrived; Today imports it too). STATE = Performance State → 14-day trajectory → injury risk → return-to-play ('how is the body right now'). TRAINING = this week's recap → discipline breakdown → volume vs landmarks → eight-week trend ('the work'). SEASON = goal + season widgets + setup ('the long arc'). EXPLORE = the horizon doors (Sport S&C / Velocity / Endurance / AI Coach), closing the page exactly as Explore closes Today. Two moves, nothing removed: RETURN-TO-PLAY moved up from the page's foot into the State cluster — it is injury management, and a flagged tissue's protocol now sits beside the flag instead of a whole page away; the HORIZON doors moved from mid-page to the end. The GroupMark's `mt` prop keeps the optical 36px above every marker inside containers that contribute their own spacing (web's grid gap). New i18n w.home.group.state/training/season (EN/PL/DE); Explore reuses the existing shared label. Web + mobile at parity." },
  { id: "progress-head-and-exits", area: "Core", status: "shipped", title: "Progress cluster — one head grammar + one 'see more' (consistency wave 1)", detail: "First of the Progress-cluster consistency waves (see the 'Progress, made consistent' design study). ONE HEAD GRAMMAR: the exercises rail's nano-mono kicker head ('Exercises – your favourites') is promoted to the Explore-standard SectionHead the other three blocks already wear (bold display 800, fs.title, chalk; new i18n w.home.exw.title EN/PL/DE), so the cluster no longer mixes two head tiers; and the right-hand slot now follows one codified rule — a FACT sits in ash (date range, count), an ACTION sits in lime ('All ›', the sort toggle), and a head carries at most one. ONE 'SEE MORE': the cluster used to end its blocks four different ways (dashed ghost card in-rail, two bare '+N' outline buttons, door rows). The rule is now by container: a RAIL ends in a trailing ghost tile (other-sports' '+N' button became a dashed ghost tile inside the rail carrying its count, the exercises rail's ghost card already complied), and a FULL-WIDTH block ends in a door row (endurance's '+N' button now wears the This-week card's door-row anatomy — ink2 fill, 32px glyph tile, display title, count on the right). Expand/collapse behaviour, caps and counts unchanged. Web + mobile at parity." },
  { id: "progress-tile-skeleton", area: "Core", status: "shipped", title: "Progress cluster — one tile skeleton + one chart language (consistency wave 2)", detail: "Second Progress-cluster consistency wave (see the 'Progress, made consistent' design study). ONE TILE SKELETON: every rail card in the cluster now reads name row → headline figure → chart zone → footer meta, top to bottom, radius 16, mono figures at 26 — an athlete who has learned to read one tile has learned to read them all. The exercises rail's 340×200 radius-28 sparkline heroes came down to 200px instrument tiles obeying the contract (name + ticker delta, figure — still the shared-element that flies into the exercise page — strip, label/kind footer); the endurance VolumeTile leads with this week's km as its figure over the strip; the TrendTile carries its pace delta on the label row, the current pace as its figure, and draws its line — the one honest exception to bars (pace is a level, not a quantity per week) — in the strip's own 24px zone so even the exception aligns; the endurance/sports tiles' shared Tile primitive gained the name-row `right` slot the exercises tiles use. ONE CHART LANGUAGE: a shared HistoryStrip primitive (aurora/history-strip.tsx on both clients — up to 8 bars, one 24px zone, past periods at 34% tint, current period full-strength, in the block's semantic hue: lime lifts / teal endurance / violet sports) replaces the three drawings the cluster had (92px area sparkline, 46px bars, 26px bars). Normalization lives in core history-strip.ts (unit-tested): historyStripBars() maps LEVEL series (weights, paces — pace reversed so faster is taller, the old sparkline's rule) onto a floored band so the change's shape shows; zeroBasedBars() keeps ZERO-BASED weekly series honest (an empty week reads as zero); exerciseStripBars() dispatches per widget-card metric so both clients bucket identically. All metrics, tap-throughs, semantic hues and full-bleed rails unchanged. Web + mobile at parity; new i18n w.home.end.window8 (EN/PL/DE)." },
  { id: "progress-parentage", area: "Core", status: "shipped", title: "Progress cluster — the verdict is the index, the rails are its chapters (consistency wave 3)", detail: "Third and final Progress-cluster consistency wave (see the 'Progress, made consistent' design study). The This-week card's columns are the PARENTS of the rails beneath it, and that parentage is now visible: each rail's head meta quotes the figure it decomposes — Exercises quotes the VOLUME column ('12.4 t this week'), Endurance the DISTANCE column ('21.6 km this week'), Other sports the sports' SHARE of the hours column ('3.1 of 5.2 h this week'). THE RECONCILIATION RULE: core progress-parentage.ts (unit-tested) computes nothing of its own — it calls the exact activitySummary the verdict renders over the exact Mon–Sun 'week' range, so a head quote and a column can never disagree to the decimal. The right-slot rule holds: the quote is a FACT (ash), so the actions that used to ride those heads relocated — Exercises' 'All ›' lives in the rail's trailing ghost tile (already there since wave 1), Endurance's sort toggle moved to its own quiet right-aligned row under the head, shown only when there is more than one lane to reorder. THE DOORS: the History + Analytics door rows moved OUT of the This-week card to the END of the cluster (rendered by today.tsx / home.tsx via the now-exported DoorRow), so Progress reads summary → breakdowns → one exit point instead of a detour between the summary and the rails that decompose it. DELIBERATE DEVIATION from the study: verdict column taps still open their inline breakdown panels (shipped behaviour, better than scrolling away) rather than becoming scroll anchors. New i18n w.home.group.metaWeek / metaOf (EN/PL/DE). Web + mobile at parity." },
  { id: "week-rail-done-receipt", area: "Core", status: "shipped", title: "Week rail — done-state receipt ('All done for today')", detail: "A DONE plan day on the week rail now collapses to a RECEIPT instead of re-listing the settled prescription (user-picked concept 1 'The receipt, corrected' from design/done-card-redesign-ideas.html, Jul 2026): a lime check + 'All done for today' headline ('Completed' when viewing a past done day), the finishing time as a quiet meta line ('finished 11:18'), a quiet stat row, and 'View in history →' as an uppercase mono TEXT link (the completed state stands down — no pill). THE TRUST RULE, in @hybrid/core done-receipt.ts (doneReceipt/doneReceiptStats, unit-tested): completedAt−startedAt is the span of the LOG, not necessarily the WORKOUT — a session typed in after the fact spans a minute of typing while carrying a full day of sets, which previously read as an absurd '1 min'. A wall-clock duration below the plausibility floor (≥1 min per logged set) is DROPPED, falling back to athlete-entered cardio/conditioning minutes when present, else the stat simply doesn't render — a figure that can't be vouched for is omitted, never shown. Stats carry the unit INSIDE the value ('48 min', '3.0 t' via fmtTonnage in the athlete's units, '7.2 km') under bare uppercase labels (one grammar), ordered duration – volume – distance – sets, each included only when non-zero. Both clients at parity off the same core model (web + mobile week-rail.tsx; the catch-up list for sessions postponed onto the date is preserved on the receipt); new i18n keys w.home.rail.allDone / finishedAt / duration (EN/PL/DE)." },
  { id: "rail-day-stamp", area: "Core", status: "shipped", title: "Rail corner — distance from now (and the run), never the date the strip already showed", detail: "Both week rails printed the absolute date in the corner of the day detail (‘Fri 31 Jul’). Directly above it the rail draws that same day as a chip — weekday over day-of-month, highlighted — and on the done state it sat beside a headline reading ‘All done for TODAY’, so five words managed to repeat both the week strip and the headline. Replaced by the DAY STAMP (@hybrid/core day-stamp.ts, dayStamp/dayStampText, unit-tested): the corner reports how far the day sits from NOW, and never says something the card has already said. Inside a ±6-day window it reads ‘Yesterday’ / ‘3 days ago’ / ‘In 2 days’; an open today reads ‘Today’; a DONE today spends the slot on the one thing the card cannot otherwise show — the athlete’s current run (‘6-day streak’, from engines/habits streak() with its one grace day, so a rest day never breaks it) — and stays EMPTY when there is no run yet, because a first day is not a streak. Past the window the absolute date returns, since ‘in nine days’ stops meaning anything. Pure label math on YYYY-MM-DD keys, so all four surfaces stamp identically: plan week rail + logbook rail, web and mobile, in every state (done, open, missed, skipped, postponed, empty past day). New i18n keys w.home.rail.stampToday / stampYesterday / stampTomorrow / stampDaysAgo / stampInDays / stampStreak (EN/PL/DE)." },
  { id: "rail-done-floor", area: "Core", status: "shipped", title: "One day, one card — the Done-today rows moved INSIDE the week rail", detail: "Today drew the same day twice: the week rail summarised it under the calendar, and the Done-today card three hundred pixels below listed the very same sessions with icons and figures. receipt-names-once fixed the copy; this fixes the structure. The rows now render as the rail card's LOWER FLOOR (aurora/done-floor.tsx, web + mobile twins), and the separate card is gone from both rail paths — roughly 90px of Today's scroll returned (one border, one card's padding, the 16px gap and a display-weight numeral that only ever counted to three). Chosen as option 01 of a seven-option merge study, over the variant that also dropped the receipt's stat tiles: the day's totals keep their display weight. THE SEAM IS THE WHOLE DESIGN. Above it is what the plan ASKS of the athlete (title, prescription, Start / Skip / Move, the catch-up list); below it is what they DID. A tennis row sitting under Trap-Bar Deadlift with only a hairline between them reads as the last line of the prescription, so the seam carries the old card's count as a mono label ('2 done today', '1 done Sun 2 Aug' on a scrubbed day) plus the arrow into the Done-today sheet; at zero it drops the arrow and speaks the invitation instead ('a match, a run, a swim — it lands here'). The floor composes with EVERY day state, which is what made 01 survive plan mode: a missed plan day now shows its terracotta note directly above the 8.4 km run that day actually held, and a rest day shows the moon and the easy swim in one card instead of two unrelated ones. The floor is built by the SCREEN (today.tsx / home.tsx) and passed into the rail as a `doneFloor` node, because the screen owns the sessions, the quick-log sheet and the Done-today sheet — the rail owns only the surface. Day scoping, the Plan tag, the lime/teal tile split and 'Log another sport' are unchanged. The logbook rail's past-empty day gets no floor (it already says 'nothing logged'), and the count-based plan hero — which has no rail to sit in — keeps the floor in a card of its own so the confirmation loop never vanishes. Zero new i18n: the seam reuses w.home.today.glanceDone / glanceDoneOn and the alsoTodayCopy state machine." },
  { id: "receipt-names-once", area: "Core", status: "shipped", title: "The day's work is named ONCE — the receipt keeps the clock, the Done-today card keeps the names", detail: "Today said the same thing twice within one screen. The week rail's done receipt led its meta line with the day's work — the logbook rail joined every session logged that day ('Tennis – Afternoon workout – finished 14:33'), the plan rail printed the scheduled day's title ('Upper + Engine – finished 11:18') — and a few hundred pixels below, the Done-today card lists those very sessions by name, one row each, with an icon, its own meta figures and a PLAN tag. Two namings, one day, no new information in the second. The receipt now drops the names entirely and keeps the ONE fact the card below deliberately withholds (see the row's own note: no clock time on a row, because the save time is not the workout's time) — the clock the day finished at, rendered as the whole meta line ('finished 14:33') and omitted altogether when nothing stamped a completion. Everything else on the receipt is untouched: headline, day stamp, trusted stat row, 'View in history →', the plan rail's catch-up list. All four surfaces at parity (plan week rail + logbook rail, web and mobile). @hybrid/core stripWeekdayPrefix is deleted with the line it existed to trim." },
  { id: "receipt-sets-are-strength", area: "Core", status: "shipped", title: "Sets are a strength figure — a swim, a match and a squash game never show one", detail: "The done card poured every session through the gym’s mould: a 10-minute pool swim rendered ‘1 SETS’ because DoneReceipt.sets counts one EFFORT per cardio/conditioning block (the unit the duration plausibility floor needs). True of the data model, meaningless to the athlete — swimming, tennis and squash have no such thing as a set. doneReceipt() now also carries `strengthSets` (sets logged on strength blocks, by the same reps-or-load-filled rule as liveSessionStats), `sets` is documented as the effort counter it is, and doneReceiptStats() renders `strengthSets` — so a swim shows duration + distance and stops, a match shows its time, and a day that lifted AND swam reports the 11 sets it lifted instead of the 12 the effort counter padded. mergeDoneReceipts sums it for the logbook’s multi-session days, and the Wrapped’s sets tile reads it too (its discipline gate already kept sets away from a swim; this keeps a MIXED day’s count honest). Same principle as session-wrapped-discipline, applied at the source. Regression-tested for swim / tennis / squash / lifted-and-swam." },
  { id: "dashboard-logbook-rail", area: "Core", status: "shipped", title: "Today — logbook week rail for the plan-less logger ('The Constant')", detail: "A free user with NO enrolled plan but real logged history used to see the three first-run chooser cards forever — five workouts by Friday and still no calendar on Today (user-picked concept C1 'The Constant' from reference/first-log-dashboard-c1-the-constant.html, Jul 2026). Now, after the very first logged session, the SAME week-rail object the plan state ships mounts in LOGBOOK MODE on both clients (web aurora/logbook-rail.tsx + mobile twin, identical anatomy to week-rail.tsx: one ink2 surface, header row, seven day chips, full-bleed hairline, state-aware day detail). The shared engine is @hybrid/core logbook-week.ts (unit-tested): logbookWeek() maps the trailing 7 LOCAL calendar days ending today onto LogbookDay entries reconciled against logged sessions (field names match ScheduledDay so Today's day-scoped cards accept a lifted day from either rail), plus mergeDoneReceipts() to sum a multi-session day into one honest receipt (per-session untrusted durations stay dropped; last finish clock wins). The logbook vocabulary is deliberately promise-free: a day is either logged (chalk number + ✓) or quiet greyscale — no 'missed', no terracotta, because a logbook makes no promises. Day detail states: logged → the plan rail's done receipt (✓ 'All done for today' / 'Logged' on past days, the finished clock, trusted stat row, the day's sessions as the card's lower floor per rail-done-floor, 'View in history →'); today empty → 'Nothing logged yet' + the one lime 'Log a workout' pill; past empty → quiet 'Nothing logged'. Tapping a chip scopes the masthead + Also-today + feeling cards to the viewed day, exactly like the plan rail (shared railDay state, ScheduledDay | LogbookDay). The chooser DEMOTES instead of disappearing: an Explore-standard 'Train your way' section head (mono 'Optional' on the right) over a horizontal SNAP SLIDER of compact StructureCard cards (Follow a plan / Build your own / Just train — the ChooserCard's corner-glow anatomy at ≈72% rail width so the next path peeks in; mobile ScrollView snapToInterval, web scroll-snap, the exercise-widget rail's idiom), so the paths stay reachable without re-onboarding a regular every day. Day zero (no plan, no history) keeps the full three-card chooser; enrolling swaps the logbook rail for the plan week rail — same geometry, new fill. Premium athletes with history keep their AI-prescription hero (unchanged). New i18n w.home.logbook.* (EN/PL/DE); the masthead's 'Free' caption now also shows in logbook mode." },
  { id: "nav-explore-train", area: "Core", status: "shipped", title: "Bottom-nav Explore + Train destinations (Explore SUPERSEDED)", detail: "HISTORICAL — the Explore half of this is superseded by nav-nutrition-tab (below); Train is unchanged and still shipped. EXPLORE (retired Aug 2026) opened a discovery surface (aurora/explore.tsx — search, a coach rail, the plan library as a COVER FLOW, and a community-feed preview) off the second bar slot on both clients. TRAIN (the centre slot) opens the Train launcher hub (AuroraTrain — start today's session / AI / repeat-last / routines / resume a draft) on BOTH clients; previously mobile bypassed the hub and dropped straight into the live logger, and web opened the logger directly with no hub — both now open the SAME launcher (web mounts it as the app-shell 'train' screen off the pill-nav centre + the Train sidebar/springboard item). LAUNCHER REDESIGN (Minimal + adaptive hero): the hub is a calm single hairline list of ways to start (Empty session – From a routine – Repeat last), topped by ONE adaptive slot — for a paid athlete it's the big lime hero for today's AI-prescribed session; for a free/casual user it's the Premium pitch (routines themselves are free — up to 2 saved templates, see workout-routines — so the routines row lists them for every persona); and once ANY session is logged today (sessionsOnDay) the slot collapses to a compact 'done' marker (lime check + today's session, taps through to the summary) while the list stays for an extra session. From the hub one tap still starts the live session." },
  { id: "nav-nutrition-tab", area: "Core", status: "shipped", title: "Bottom nav — Nutrition replaces Explore; Follow a coach moves to Today", detail: "The second bar slot now carries NUTRITION, and the Explore tab is gone. The reasoning is in @hybrid/core nav-bar.ts, where the tab table lives: a five-slot bar is the scarcest real estate in the app, and Explore spent one of those slots on DISCOVERY — something a user does a handful of times ever — while eating happens several times a day, every day, and the tracker sat two taps down inside More. Every block Explore carried was a PREVIEW of a screen that still exists: its search opened Find friends, its plan Cover Flow opened Plans, its community rail opened the Feed — all three are still in More, so nothing became unreachable. The one block with a daily job, FOLLOW A COACH, moved onto Today. WHAT CHANGED, identically on both clients: (1) @hybrid/core nav-bar.ts AURORA_NAV_TABS reads today – nutrition – train – more – profile (AuroraNavTabId lost 'explore', gained 'nutrition'), and motion.ts NAV_ROOT_ORDER follows it, so a Today↔Nutrition move slides sideways like any two bar roots. The feed/discover/coaches/leaderboard ROOT_ALIAS entries that pointed at the Explore root are gone with it — those screens are leaves reached from More (or from Today's coach rail) now, so they push and pop instead of sliding. Pinned by nav-bar.test.ts + motion.test.ts. (2) A new kit glyph, `fork-knife` (theme/icons.ts AURORA_ICON_PATHS + the 216px mobile PNG), drawn as the Fuel widget's PlateGlyph redrawn in the kit's 72×72 stroke box so it carries the same optical weight as village/grid beside it; AURORA_NAV_ICONS.nutrition points at it instead of the borrowed `store` shopfront, so Nutrition reads the same in the bar, the More springboard and the web sidebar. On iOS the tab takes the SF Symbol `fork.knife` for both states — it ships with no plain .fill counterpart (only circle-wrapped variants, which would change SHAPE on selection), so the tint carries selection, which is what iOS itself does for symbols without a fill pair. (3) MOBILE: app/nutrition.tsx moved into app/(tabs)/nutrition.tsx (a native tab bar renders every route in its folder), so router.push('/nutrition') from Today's Fuel sheet now switches tabs rather than pushing a screen. AuroraNutrition gained a `root` prop that drops the masthead back button — a back arrow on a tab root is a dead control. (4) WEB: the app-shell 'explore' screen and aurora/explore.tsx are deleted; 'nutrition' was already a shell screen, so the pill nav lands straight on it. (5) FOLLOW A COACH on Today is now a RAIL ON THE PAGE, not a row that opened a sheet — the rail sells coaches by showing them, and a row reading 'Follow a coach' sold nothing. It mounts headerless under a section head (display title left, mono 'Find a coach for your goal' right — the Explore SectionHead vocabulary, no marker) with bleed + seeMore, so the cards run full-bleed under the screen edge per the slider rule and the trailing 'See more' carries through to the marketplace. The coach Sheet and the DeferRow component it fronted are deleted from both clients. Today's order below the premium cards is now Fuel → Follow a coach. i18n: nav.explore and the nine Explore-screen-only keys (w.explore.title/sub/search/plans/all/plansCard*/community/feed) are removed in EN/PL/DE; the coach-card and seeAll/seeMore keys stay — they are shared by CoachRail, FeedPreview, the endurance lanes and the Nutrition rails." },
  { id: "plans-cover-flow-rehome", area: "Core", status: "planned", title: "Rehome the plan Cover Flow + the community rail (ex-Explore)", detail: "RECORDED SO IT IS NOT LOST, per the capabilities rule. Retiring the Explore tab (nav-nutrition-tab) took its screen with it, and two blocks on that screen had no other host. (1) The PLAN COVER FLOW — three curated full-width 'album-art' covers (discipline-accent duotone over a fixed-dark base, oversized glyph, name + hairline meta) over a full-bleed micro-rail of the remaining previews, with press-scale and cover-glyph parallax under reduced-motion gates. Its curation survives in @hybrid/core (FEATURED_PLAN_IDS → FEATURED_PREVIEWS, still exported and still unit-tested in explore-plans.test.ts), and the cover RECIPE itself is alive on the Plans screen (goal tiles + CoverHero/plan-hero use it at tile and screen scale) — what is gone is the curated three-up entry point. (2) The COMMUNITY RAIL — aurora/feed-preview.tsx (both clients) is intact and unchanged but no longer mounted anywhere; the full Feed is still in More. Neither is a regression in REACH (Plans and Feed are both nav destinations); both are a loss of a curated front door. Decide where they belong — a 'Discover' section on Today, a curated header on the Plans screen, or a shelf in More — and mount them there, or delete feed-preview.tsx deliberately rather than leaving it unmounted." },
  { id: "bottom-sheet-quick-actions", area: "Core", status: "shipped", title: "Slide-up bottom-sheet quick actions (Today + upgrade)", detail: "A shared slide-up bottom-sheet primitive (aurora/sheet.tsx on web — a fixed overlay with a scrim fade + CSS transform slide-up, Esc/scrim to dismiss and a body-scroll lock; aurora/sheet.tsx on mobile — a transparent RN Modal with an Animated translateY panel + scrim + grab handle, kept mounted through the exit animation) backs every Today quick action on BOTH clients. Each sheet is a FOCUSED, purpose-built quick action (not the whole screen crammed in): Quick Log → 'Already trained?' a 2×2 sport grid (tap-to-log, + Other opens the searchable picker); Readiness → 'How ready do you feel?' a 4-choice picker (Primed/Good/Flat/Wrecked, spectrum dots) that logs a daily check-in in one tap; Done today → everything logged today + a calendar link; Nutrition → 'Add a meal' a compact quick-add (today-vs-target kcal, manual name+kcal → energyIntake signal, the premade-meals grid, and a 'Targets, trends & history →' deep-link to the full tracker); Follow a coach → the coach rail. The full check-in + nutrition SCREENS stay reachable on their own routes; the sheets share the same write paths (/api/checkins, /api/signals). The Full upgrade paywall is the same slide-up sheet: web app-shell renders it as an OVERLAY via a central navigate() intercept (any onNavigate('upgrade') pops the sheet, not a screen switch); mobile keeps its transparent-modal /upgrade route. Concise COCKPIT-badge sheet — benefit list, $9.99/month, a 7-day free-trial note, a violet 'Start free trial' CTA, 'Maybe later' — over the same Stripe Checkout / Apple IAP billing (live purchase still blocked on credentials, see full-billing). The Today 'Go Full' cards (Cockpit/Sport) were restyled to match: a soft violet fill (no lime rim), a value sub-line, an explicit 'Unlock with Full →' CTA, and a 'See plans →' action on the section header." },
  { id: "readiness-load-adjust", area: "Core", status: "shipped", title: "Subjective readiness → today's load auto-adjust", detail: "The Readiness pick (Primed/Good/Flat/Wrecked) now MECHANICALLY scales the prescribed session, not just the copy. prescribeSession gained an optional subjectiveReadiness (ReadinessFeeling) — a load multiplier applied on top of the progression-signal dose: primed ×1.05, good ×1.0 (neutral, identical to omitting it), flat ×0.94, wrecked ×0.85 AND −1 work set (a real deload). The factor lives in @hybrid/core readiness-feeling.ts (READINESS_LOAD_FACTOR / readinessLoadFactor), so the feeling→load-effect mapping is one source of truth; the explanation string calls out the adjustment ('You checked in feeling flat, so I eased the load back'). Unit-tested (engines.test.ts: primed > good > flat > wrecked load, good == neutral, wrecked sheds a set). BOTH clients feed TODAY's READINESS ANSWER (quickCheckinFeeling of the day's row, independent of the week rail's selected day) into every athlete-facing prescribeSession call — this used to be checkinFeeling, the average of all four metrics, which meant the pill quoted the athlete words they never said; see checkin-answers-survive: the Today/Home readout (web today.tsx rx also flows into onStart → the started session; mobile home.tsx rx) AND the AI-session generators the athlete starts (mobile app/workout.tsx source='ai' + the empty-state loadPrescribed; web logger.tsx in-logger 'AI session'). Still layered on top of the OBJECTIVE readiness score (fatigue + wearable bio via toBiometrics), which the pick does NOT overwrite — subjective load nudge and objective recovery score are separate, and the 'why' explains both. SURFACED (Jul 2026): the adjustment is no longer buried in the 'why' prose — prescribeSession now returns a structured readinessAdjust ({ feeling, loadPct, setAdj }, present only when a feeling actually moved the load/sets, absent on neutral 'good'), and both clients render a glanceable pill: the feeling's own ReadinessFace + a mono line tinted in its semantic accent ('Eased to 94% — you're feeling flat today', 'Boosted to 105%…', 'Deloaded to 85%, −1 set…'; a bodyweight wrecked day shows the shed set only, since it carries no % load). New i18n w.home.today.rx{Primed,Flat,Wrecked,WreckedBw} (EN/PL/DE); the load-% delta assertions extend engines.test.ts. RELOCATED (post-merge): the Today/Home redesign moved the readiness-driven AI prescription OFF Today (premium-no-plan users now land in logbook mode) onto the COCKPIT, so the pill lives there now — web cockpit.tsx + mobile cockpit.tsx render it in the Performance-State card's readiness block, beneath the readiness Ring + rx.why, off the same readinessAdjust. Both Cockpits fetch TODAY's check-in feeling (fetch /api/checkins on web; fetchCheckins folded into the load Promise.all on mobile) and pass it as subjectiveReadiness, so the Cockpit prescription both scales and explains the nudge. The scaling itself still applies to the SESSION the athlete starts (workout.tsx / logger.tsx), unchanged by the relocation." },
  { id: "nutrition-training-aware", area: "Core", status: "shipped", title: "Training-aware nutrition targets (eat for the work)", detail: "Nutrition targets now flex with training. @hybrid/core/engines/load.ts gains sessionEnergyKcal (a MET-style estimate of a logged session's energy cost from each block's minutes × intensity × bodyweight — resistance work is metabolically flatter, conditioning climbs with RPE) and trainingEnergyOnDay (sum across today's sessions). adaptiveTargets takes a trainingKcal and adds it ON TOP of the goal target entirely as CARBOHYDRATE, so a hard training day earns a higher carb + calorie target while protein (bodyweight-set) and fat hold — a periodised 'fuel for the work you did' model, not a static number. Both clients fetch today's sessions (web useSessions / mobile useSessionsQuery), compute the bump from the athlete's latest weight, and surface a '+N kcal training fuel' chip under the calorie ring on rest→train days. Pure + unit-tested (sessionEnergyKcal, trainingEnergyOnDay, adaptiveTargets fuel path). Web + mobile at parity; i18n (EN/PL/DE). Also in this pass: bodyweight is now DERIVED FROM THE PROFILE — POST /api/body mirrors weightKg into a bodyMass Signal (source 'profile', like the check-in bridge), and both nutrition weigh-ins (onboarding + the Body sub-view) write to /api/body, so the profile owns one canonical weight that the maintenance estimate + smoothed trend read." },
  { id: "nutrition-meal-picker", area: "Core", status: "shipped", title: "Meal-based add-food picker + Create Food (redesign)", detail: "The redesigned add-to-meal flow, web + mobile at parity, pixel-matched to the approved mockups. The Nutrition hub now leads with today's MEALS (Breakfast / Lunch / Dinner / Snacks) — each row shows the kcal already logged to that meal and opens the PICKER attributed to it. Logs from the picker carry the meal as the Signal `source` (breakfast/lunch/dinner/snack), so the hub groups today's intake by meal. The PICKER (view 'add') is a full screen: a meal chooser in the header ('Dinner ▾'), a text-or-barcode search box, Quick Log + Create Food actions, and Recent / Favorites / Personal tabs. Recent (a per-device MRU written on every log) and Favorites (a per-device starred set, toggled by the row star) persist in localStorage / AsyncStorage so the tabs work with no backend change; Personal is the saved-products library (swipe-left to delete). A row's lime add-circle opens the shared portion editor. CREATE FOOD (view 'create') is the redesigned product builder as its own screen: a photo/label affordance (repurposed to the Full label-scan), Food Name, Serving + Unit (unit sheet: gram/ml/oz/piece/serving → composed into servingLabel), and colour-coded Calories / Carbs / Protein / Fat, saved via the existing /api/nutrition/products. Quick Log is the fast kcal+macro sheet (4·4·9 fill). i18n EN/PL/DE." },
  { id: "nutrition-food-subname", area: "Core", status: "shipped", title: "Food subname + de-cluttered Create form", detail: "Two changes, web + mobile at parity. (1) SUBNAME — SavedMeal + FoodProduct gain an optional `subname`, the user's OWN label for a food (a dish named \"Tuna Bowl\" with subname \"w/ sushi rice\"; \"Whey scoop\" / \"the usual way\"). Threaded through the products/meals API (POST accepts it, GET returns it) and shown as a lighter second line everywhere a food appears: picker rows, saved meal + product lists, the portion editor, and carried into the Recent MRU. (2) The add-food form was rebuilt to kill the card-in-card-in-card border clutter (see the reported screenshot): ONE blend layout — a title plate holding Name + Subname, then a macro HERO (calories as the big number, protein/carbs/fat as three light tiles), with serving on a single quiet line (products only). The same form serves BOTH targets via a createMode: 'Create Food'/'Add manually' → product (serving + unit → servingLabel), 'Create meal' → meal (logs as one serving). This replaces the old inline bordered builders as the primary path. NEEDS the subname column in production — run reference/sql-nutrition-subname.sql in the Supabase SQL Editor (idempotent ALTER TABLE ADD COLUMN); until then POST/GET still work but silently drop subname. i18n EN/PL/DE." },
  { id: "nutrition-hub-prefs", area: "Core", status: "shipped", title: "Nutrition prefs: onboarding once, saved goal, custom parts, meals-or-products picker", detail: "Five fixes to the Nutrition hub, web + mobile at parity. (1) ONBOARDING SHOWS ONCE — the first-run wizard was gated on a per-device localStorage flag that was only set on the 'Continue on Free' button, so starting the ✦ trial OR just weighing in left it unset and re-showed onboarding every visit. Completion is now persisted SERVER-SIDE (/api/nutrition/prefs, stored under answers.nutrition on the shared OnboardingState row, soft-guarded + update-only so it never falsely flips the GLOBAL onboarding gate), with localStorage/AsyncStorage as a fast cache and a derived 'has any energyIntake/bodyMass logged' safety net; it's marked done on EVERY wizard exit. (2) GOAL IS SAVED — the chosen goal persists in the same prefs and is restored on load (was resetting to 'maintain' each visit). (3) WEIGHT FROM PROFILE — the Body sub-view now leads with the current weight READ from the profile (latest bodyMass) labelled 'synced with your profile', and the onboarding weigh-in reuses an existing profile weight instead of asking again — one canonical source, no duplicate silos (weigh-ins already write to /api/body → bodyMass). (4) CUSTOM PARTS OF THE DAY (Full) — resolveMealParts/mealPartKey in @hybrid/core merge the four built-ins (breakfast/lunch/dinner/snack) with a user's own parts (e.g. 'Pre-workout'), persisted in prefs (mealParts, capped at MAX_CUSTOM_MEAL_PARTS=8) and rendered in the home list, diary + the picker's part chooser; free users keep the four. Logs carry the part key on Signal.source. (5) MEALS-OR-PRODUCTS PICKER — the add-to-meal picker gained a 'Meals' tab so any part of the day can be filled with either a full saved MEAL or a single PRODUCT (was products-only). Pure helpers unit-tested; i18n EN/PL/DE." },
  { id: "nutrition-diary-edit", area: "Core", status: "shipped", title: "Editable food diary (edit quantity / delete logged entries)", detail: "Logged foods were four anonymous Signals (energyIntake + P/C/F) with no id, name or grouping, so nothing could be edited or removed. Two layers now make every logged item editable. (1) The FoodLog model (prisma/schema.prisma) is the RICH record: one row per logged food/meal storing PER-SERVING macros + a qty + the mirrored Signal ids. All logging routes through /api/nutrition/log (POST creates the FoodLog AND the mirrored Signals the engines read); /api/nutrition/log/[id] PATCH rescales an entry's quantity (and its Signals), DELETE removes the entry + its Signals. (2) SIGNAL-DERIVED ENTRIES (Jul 2026) make the Diary work with NO migration at all: because every log writes its four Signals at one exact ts + source, the server regroups Signals that no FoodLog row owns back into individual entries (derivedFoodEntries in @hybrid/core, pure + unit-tested) and returns them from GET /api/nutrition/log with a `sig:<signalIds>` id. PATCH on such an id rescales those Signal readings by a relative factor, DELETE removes them — so an item logged before the FoodLog table shipped, or on a database where the migration hasn't run, can still be corrected or removed. The Diary (web + mobile at parity) lists the selected day's entries grouped by part, each with a −/＋ stepper (an absolute serving count for a FoodLog row, a ×multiplier for a derived one) and a delete; entries whose source isn't a part of the day (a quick log, a food-search hit, a preset) group under 'Other' so nothing logged is unreachable; the recent-days list selects any past day (120-day window) to edit/delete its records. DIARY DAY-SUMMARY: the Diary leads with a day-summary card read from the always-on Signals (dailyNutrition) — a ‹ › date stepper picks ANY calendar day (never past today, with a 'Today' shortcut), a big total-kcal-vs-target number, and P/C/F progress bars vs target. New i18n w.recovery.nutrition.{prevDay,nextDay,diaryTotalsOnly,loggedEntry,otherEntries} (EN/PL/DE). What still waits on the FoodLog migration is only the NAME on an entry logged without the table (a derived entry is labelled by its time of day) — see nutrition-foodlog-table." },
  { id: "nutrition-foodlog-table", area: "Core", status: "shipped", title: "Food diary — named entries (FoodLog table)", detail: "The FoodLog table stores the NAME, the brand/serving subname and the per-serving macros + qty behind a logged item, so the Diary shows 'Chicken & rice — 2 servings' and edits it as an absolute serving count. reference/sql-nutrition-log.sql was RUN in the Supabase SQL Editor (Jul 2026) — the table, its (userId, ts) index and its owner-only RLS policy now exist, so POST /api/nutrition/log writes the row alongside the mirrored Signals and every newly logged item carries its name across devices. Items logged BEFORE the migration stay Signal-derived (their names were never stored anywhere to recover) and remain fully editable + deletable via the derived-entry path — see nutrition-diary-edit. The soft guards on both routes stay in place, so a database without the table still degrades cleanly." },
  { id: "nutrition-recipes-library", area: "Core", status: "shipped", title: "Recipes library (read-only, cook-along)", detail: "A curated, READ-ONLY recipes library shared by both clients (RECIPES in @hybrid/core/recipes.ts — pure + typed, no DB, no external image assets). Each recipe carries per-serve single-number macros (the no-range rule), a meal + active time, ingredients (quantities stored for baseServes) and a method (steps with optional per-step timers). The hero is a warm brand-accent gradient keyed to the dish (recipeHeroBg) with the dish emoji — self-contained, no photo hosting. UI (web + mobile at parity, pixel-matched to the mockup): BROWSE (view 'recipes') is a filter-chip row (All / Breakfast / Lunch / Dinner / High protein → filterRecipes) over a 2-up card grid; DETAIL (view 'recipe') is the hero + a per-serve Energy/Protein/Carbs/Fat strip + a serves stepper that SCALES the ingredient quantities live (scaleIngredientQty / formatIngredient); COOK (view 'cook') is a read-only step-through with a progress bar, per-step timer chips and Back/Next. The library is a Full feature (access.canUseRecipes, unit-tested, mirrored on both clients): the Nutrition-hub recipes entry shows a ✦ for free (casual) users and tapping it routes to the upgrade screen. DETAIL also offers 'Create meal' — recipeToMeal saves the recipe's per-serve macros (name + dish emoji) into the personal meal library (POST /api/nutrition/meals, respecting the free meal cap) so a favourite recipe becomes a one-tap saved meal. Logging a cooked recipe straight into the day is a separate planned capability (nutrition-recipe-cook-log). HUB PRESENTATION (Jul 2026): the hub's Recipes menu row was replaced by a left/right RAIL at the very bottom of the Nutrition hub — every recipe as a swipeable card (gradient hero + emoji, name, meal – time, kcal) under a SectionHead-anatomy head ('Recipes' + 'See all →' on the right, carrying the ✦ and the upgrade route for free users; every card tap routes free users to upgrade too). Full-bleed like every screen-level rail (web `margin: 0 calc(-1 * var(--page-pad-x))` with matching padding, mobile `marginHorizontal: -16` + snapToInterval against AuroraScreen's 16dp gutter). The browse view (filter chips + 2-up grid) is unchanged and is where 'See all' lands. THE DETAIL NOW OPENS WITH THE PLAN DETAIL'S COVER (Jul 2026), not a lookalike: the collapsing full-bleed cover scaffold was lifted out of plans.tsx into apps/web/components/aurora/cover-hero.tsx (web) and reuses the already-generic CoverScreen (mobile plan-hero.tsx), both driven by core's new `recipeCoverView` — one view-model, so a recipe cover and a plan cover cannot drift. A plan and a recipe are the same kind of object from the athlete's side (a shape, a cost in time, a set of numbers, that you commit to and then follow); they were arriving through two unrelated headers only because they were built in different months. SLOTS: the tint becomes the duotone accent, the meal the chip, the time the top-right label, and '2 serves / 7 ingredients / High protein' the meta line. NEW `recipe` VARIANT on the cover spec: the dish emoji is the cover art at emblem scale and FULL COLOUR — a ghosted 7%-white emoji is a grey smudge, not a dish — which is also why it is the one variant that fades to NOTHING rather than to a residue (a monochrome mark can drift into the pinned bar as texture; a colour emoji only smears behind the bar title). The old boxed four-tile macro strip is now the cover's HEM — the same rule-topped editorial columns a plan uses, straight on the ink — at FOUR columns rather than the plan's three, because a recipe's headline numbers are its four macros and dropping one to fit a borrowed grid would be the layout choosing what the athlete sees; both clients tighten the type at four. BLURB: `Recipe` gained a `note` — one line saying what the dish actually is, the job `GoalPlan.desc` does on a plan cover — written for all eight recipes and unit-tested for presence and length, because a cover with an empty blurb slot reads as clipped. METHOD ON THE DETAIL: the steps now render on the recipe page (numbered, with their timer chips) instead of living only inside the cook flow. You could previously read a recipe end to end without ever seeing how it is made, which made 'Start cooking' a decision taken blind; it also gives the page the length a collapsing cover needs to be worth having (the bar only pins once there is roughly a screen-height of content beneath it). The cook view is unchanged and is still the hands-free step-through. NO DOCKED CTA, deliberately: the plan detail docks Enrol because its button sits in flow, while this screen already ends in a sticky action bar, so Start cooking never leaves the screen." },
  { id: "nutrition-label-panel", area: "Core", status: "shipped", title: "Full label panel — saturates, sugars, fibre, salt, kJ", detail: "Nutrition logging was four numbers (kcal + protein/carbs/fat), which is not what a food label states and cannot answer the questions an athlete actually asks of a burger: how much of that fat is SATURATED, how much of those carbs is SUGAR, am I over on salt. packages/core/src/food-facts.ts is the new single source of truth for a food's nutrition: NutritionFacts = the four macros (required) + an OPTIONAL MicroFacts panel (satFat / sugar / fiber / salt, grams). THE CENTRAL RULE: null means NOT STATED, never zero — an unstated sugar content is not a sugar-free food, so the clients render an em dash and never a fabricated 0 g. Pure + unit-tested: kj() (energy in kJ derived from kcal at the labelling definition 1 kcal = 4.184 kJ — deliberately NOT stored, since a second copy of the same fact can only drift), sodiumMg()/saltFromSodiumMg() (the EU salt field ↔ the US sodium field), scaleFacts (a scaled unknown stays unknown), sumFacts (a total is stated only when EVERY contributor states it, and reports which fields it had to drop — three foods with sugar plus one unknown is NOT a known sugar total), atwaterKcal + auditFacts (the 4·4·9 reconciliation, saturates ≤ fat, sugars ≤ carbs), per100g (fair comparison between two different serving sizes), factsCompleteness, and nutritionPanel() — the EU-order rendered panel (energy / fat / of which saturates / carbohydrate / of which sugars / fibre / protein / salt) that BOTH clients render from, so they can never disagree about what a food says. THE STACK: SignalKind gains satFat/sugar/fiber/salt (better: 'low' except fibre — these are ceilings, not totals to chase) and NutritionDay rolls them up per day; foodLogSignals() in the engine is the ONE builder deciding which Signals a log writes, so a food that doesn't state a field writes NO Signal for it (absence in the stream is how a day knows it is only partially described). Prisma: SavedMeal / FoodProduct / FoodLog gain nullable satFat/sugar/fiber/salt, FoodProduct also servingGrams + verifiedId, FoodLog also verifiedId — run reference/sql-nutrition-label-panel.sql in the Supabase SQL Editor (idempotent). Every write is SOFT-GUARDED with a two-attempt fallback (with panel, then without), so a database that predates the migration still logs and still saves, just without the panel. Open Food Facts hits now carry the panel too (saturated-fat/sugars/fiber/salt, read on the SAME serving-vs-100 g basis as the macros, plus a parsed serving weight). UI (web + mobile at PARITY): the portion editor gained the full facts panel under the macro tiles — scaled live by the quantity stepper, with a per-100 g column when the serving weight is known; the Create Food form gained an optional, folded-away Saturates/Sugars/Fibre/Salt block where a blank field stays NOT STATED; and the Diary day-summary carries the day's panel with an explicit 'from the foods that state it' caption so a partial total never reads as a complete one. i18n EN/PL/DE." },
  { id: "nutrition-verified-foods", area: "Data", status: "shipped", title: "HYBRID Verified foods (team-checked catalog)", detail: "The trusted tier of the food search. Open Food Facts is broad and free, but crowd-sourced — duplicates, per-100 g numbers filed as per-serving, missing saturates, a 'cheeseburger' that is somebody's guess. A HYBRID VERIFIED item is one a human on our team transcribed from the operator's OWN published nutrition table, reconciled against 4·4·9 (auditFacts) and DATED. packages/core/src/verified-foods.ts is the catalog: a VerifiedSource (the business) plus its VerifiedFood[] (English canonical name, the operator's own-language name as a search alias, serving label + weight, the full label panel, verifiedOn, provenance). Pure data + lookup, no DB, no key, no migration — adding a business is adding a literal. SOURCES: Max Premium Burgers (PL) with three checked items — Cheeseburger (121 g / 327 kcal / 1368 kJ, 19.6 g fat of which 7.3 saturates, 22.9 g carbs of which 4.1 sugars, 14.2 g protein, 1.7 g salt), Chicken Jr (123 g / 311 kcal — saturates, sugars and salt are NOT published for this item and are therefore null, never 0), and Fries (small) (172 kcal, 6.9 g fat of which 0.7 saturates, 25.4 g carbs of which 0.2 sugars, 1.9 g protein, 0.6 g salt; the operator states the portion but not its weight, so servingGrams stays null rather than being invented). SECOND SOURCE — LIDL (PL), the first RETAILER rather than a restaurant, with Rye Sourdough Bread (yeast-free) (per 100 g: 196 kcal / 830 kJ, 1.1 g fat of which 0.26 saturates, 39.0 g carbs of which 2.66 sugars, 7.1 g fibre, 4.06 g protein, 0.99 g salt; 450 g pack). A shelf item declares PER 100 G, so that is the serving stated — inventing '1 slice' would be inventing a slice weight the pack never publishes — and the pack weight is carried separately as packSize. A packaged good also declares what a restaurant dish never does, so VerifiedFood gained OPTIONAL ingredients + mayContain (the precautionary allergen line), both stored in ENGLISH like the rest of the catalog and rendered as a 'from the pack' card under the facts panel on both clients, with an explicit line saying the text is OUR translation of someone else's pack (an allergen statement is the last place to imply we quoted verbatim). A dish has none of these fields and its card is ABSENT rather than rendered with blanks. FIBRE CARRIES ENERGY: this bread is the item that exposed a real gap in the audit — on an EU label 'carbohydrate' EXCLUDES fibre (declared on its own line, not as an 'of which'), so 4·4·9 alone derived 182 kcal against a published 196 and an honestly-transcribed food would have failed auditFacts as mis-transcribed. atwaterKcal now adds fibre at 2 kcal/g (EU 1169/2011 Annex XIV) when it is stated, which reconciles the bread EXACTLY; an unstated fibre contributes nothing, so every existing item is unaffected. The pack's other unit (830 kJ) and our derived 820 kJ are BOTH right — an EU label computes each unit from its own factor table (fat 37 kJ/g vs 9 kcal/g, carbs 17 vs 4, fibre 8 vs 2) and those ratios are not 4.184 — so energy stays stored ONCE, in the stated kcal, rather than carrying a second figure that could drift. ONE NAME PER FOOD: the operator's own-language name (menuName, now nativeName/nativeLocale) is a SEARCH ALIAS ONLY and is no longer rendered anywhere. Printing 'Hamburger z serem' under 'Cheeseburger' put a second name on screen for a food the app had already named, which read as clutter rather than help; searching 'frytki', 'male', 'chleb zytni' or 'zakwasie' still finds the right item. SEARCH: /api/nutrition/search is now two-tier — verifiedHits() runs locally and instantly, mergeFoodHits() pins those rows ABOVE the community results and drops the community duplicate of a verified item (so the trusted row never sits beside a stranger's guess); the search accent-folds Polish (ł→l), so 'frytki'/'male' finds Fries (small) even though the app is English. Because the tier is local, an Open Food Facts outage now DEGRADES the result list instead of emptying it. UI (web + mobile at parity): the picker row carries the same quiet lime ✓ the verified-coach badge uses, and the portion editor leads with a provenance card naming the business and the date our team checked it. Provenance is persisted (verifiedId on FoodProduct + FoodLog) so a saved or logged item can be traced back to the catalog entry. auditVerifiedCatalog() is asserted in the unit tests — a mis-transcribed item fails CI rather than shipping under the badge. SOURCE MARKS: a VerifiedSource may carry the operator's own logo as SELF-CONTAINED inline SVG (SourceMark — never a URL: a remote logo breaks offline, hotlinks someone else's bandwidth, leaks a request per food opened, and is blocked by the artifact CSP; the app already resolves this the same way for nutrition glyphs and recipe heroes). The provenance card keeps the two claims APART — the operator's mark under a 'Nutrition data published by' label, then a divider, then the lime HYBRID ✓, then the trademark line — because a third-party logo beside a green tick otherwise reads as a partnership, and these operators have neither partnered with us nor reviewed the app. Marks never appear on picker rows (a logo per row is an advertising rail). Web renders the mark through a data URI on an <img> (never innerHTML, so a mark can't become an injection surface), mobile through react-native-svg's SvgXml; auditVerifiedCatalog() rejects any mark carrying a remote reference, an <image>, an xlink:href or an @font-face, so a broken mark fails CI rather than an athlete's screen. LIDL ships with its roundel — the operator's OWN logo vector, supplied by the HYBRID team: the blue field, the yellow disc, the red keyline ring and the LIDL lettering with its red i-dot and red diamond are all the artwork's own coordinates at its own colours. Two mechanical normalisations: the hard-coded width/height dropped for the viewBox, and the exporter's PAINTED WHITE 0.5-unit edge frame removed with the blue field run full-bleed instead. White paint is not a hole — on the charcoal card that frame would have drawn a keyline around the badge that the real logo does not have, which is the same failure mode MAX's evenodd knockouts exist to avoid. No coordinate inside the badge was touched. Unlike MAX's it is a SOLID badge rather than knockouts, so it carries its own ground and reads identically on both themes; verified by rendering it at 24/26/34/120 px on #1a1e17 and #f7f6ec in headless Chromium, which is the whole theme check with no simulator involved. MAX Premium Burgers ships with its REAL wordmark (packages/core/src/source-marks.ts — one enumerable home for every third-party mark): traced to vector paths from the operator's own artwork with potrace on the PNG's alpha channel, verified numerically against the source mask (IoU 0.9994, 0.034% of pixels disagreeing) rather than by eye. It is ONE path with fill-rule='evenodd', so the white keylines between the letterforms are true HOLES, not painted white — they take the colour of whatever the mark sits on, which is what keeps it legible on BOTH the AURORA charcoal card and the Kyoto Hour washi one (a raster or a painted-white knockout leaves white slabs on the dark theme). 2.9 KB. A source WITHOUT artwork stays a supported state, not a broken one: the clients render a WORDMARK FALLBACK — the business name in our own display face inside a hairline chip, visibly ours so it can never pass as an approximation of their logo. Adding artwork is one literal + one field — see reference/verified-source-marks.md, which also covers the licensing position (a Commons logo is typically PD-textlogo AND trademarked; MAX's mark came from artwork supplied by the team, so redistribution terms should be confirmed with the operator before a public release) and sourceMarkCredits(). FRESHNESS: every item was already dated and nothing ACTED on the date, so a five-year-old transcription looked exactly as confident as this morning's. verifiedFreshness()/staleVerifiedFoods() (pure + unit-tested, VERIFIED_STALE_AFTER_DAYS = 365 — the honest interval for a restaurant menu, which gets reformulated quietly but not monthly) age a check, and a stale item KEEPS its ✓ (the numbers were true when we checked; withdrawing the claim would be its own dishonesty) while the product page says in amber that it is due another look. The mark's credit line is now rendered at the foot of the source page under the trademark — until then 'third-party artwork stays enumerable' was a claim with nowhere to read it. i18n EN/PL/DE." },
  { id: "nutrition-verified-pages", area: "Core", status: "shipped", title: "Verified product pages (a page per checked food)", detail: "A verified food now has its OWN screen, and so does the business behind it — web + mobile at parity (NutView gains 'food' and 'source'). WHY A PAGE AND NOT JUST THE SHEET: the portion editor is a modal that exists to log a food you ALREADY trust — fast, in-context, dismissed on log. It is the wrong surface for deciding WHETHER to trust one, and it was carrying the mark, the provenance, the panel and the per-100 g column in a space that had to stay short. The two now split by job and the sheet is unchanged. FOOD PAGE: the source mark leads under a 'Nutrition data published by' row (tap → the source page), then the English name (ONE name — the operator's own-language name is a search alias, no longer printed beneath it), the serving line, an energy hero in BOTH units, the P/C/F strip (the recipe-detail idiom), the full facts panel with per-100 g where the serving weight is known — and an explicit line where it ISN'T, so a missing column reads as a fact about the food rather than a gap in the app. Then the claim: ✓ HYBRID Verified, the date, the operator's own wording of where the numbers came from, and the trademark line. Then MORE FROM THIS BUSINESS (relatedVerifiedFoods) so a checked item is a way into a checked menu instead of a dead end. A sticky footer carries Save to my foods + Log this, and Log this opens the SAME portion sheet — the page never re-implements logging. SOURCE PAGE: the mark at hero size, the business note, items-checked + last-checked (sourceCheckedOn = the newest verifiedOn across its items), the full item list, and the trademark line. NAVIGATION: in the picker a verified row's ⊕ still logs immediately (the fast path is untouched) while the row BODY opens the page — FoodRow gained an `onOpen` distinct from `onAdd`, and a non-verified row keeps both on add. The portion sheet's provenance card is now tappable straight through to the product page. `pageBack` remembers the origin so Back never lands somewhere the athlete didn't start. Both views guard on the RESOLVED catalog entry rather than the id, so a stale id falls through to the hub instead of setting state during render. SCOPE: pages are for VERIFIED items only — a community (Open Food Facts) hit has no stable id, no provenance and no sibling menu, so a page for one would be an empty frame around four numbers. New core helpers relatedVerifiedFoods + sourceCheckedOn, pure + unit-tested. i18n EN/PL/DE (noServingWeight, packSize, mayContain, labelTranslated, moreFrom, logThis, verifiedSourceTitle, itemsChecked, lastChecked, checkedItems); 'See all' reuses the shared w.explore.seeAll rather than minting a duplicate string. NOT BUILT YET: a URL/deep link for a product page (the web app shell is a screen switch, not routed) — see nutrition-verified-deeplink." },
  { id: "nutrition-verified-deeplink", area: "Core", status: "shipped", title: "Deep-linkable verified product pages", detail: "A verified product page now has an ADDRESS on both clients, so a checked item can be sent to someone, bookmarked, or landed on from a push. WEB: apps/web/lib/deep-link.ts mirrors the app shell's current screen into `?s=` and the open verified page into `?food=` / `?source=`. Deliberately NOT next/router — pushing a real route would remount the shell and throw away the directional screen transition — so it writes with history.replaceState (tapping through five tabs must not cost five Back presses to leave) and reads on mount plus on popstate, which makes the browser's Back button work across screens for the first time. The URL is a MIRROR of state, never the source of truth: state changes, then the URL follows. Params are bounded and pattern-checked before use (a link is attacker-controlled input), an unrecognised param is IGNORED rather than an error (a link from an older build must never land someone on a broken screen), and the mirror is cleared on the way out so a stale ?food= can't point at a page the user has left. Landing on a link uses setScreenRaw, not the transitioning setter, so arriving doesn't animate from a screen you were never on. MOBILE: app/food/[id].tsx and app/source/[id].tsx (expo-router, scheme `hybrid`) pass an id into the Nutrition screen's openFood/openSource props — the route only says WHERE to land, so there is one implementation of a product page rather than two; an id missing from the catalog falls through to the hub. SHARE: the product page header carries a share action — navigator.share where the browser has it, clipboard otherwise (a denied permission stays silent rather than erroring); mobile uses React Native's Share sheet and shares the HTTPS form, not hybrid://, because a link is only worth sending if it opens for someone who hasn't installed the app. STILL NEEDED for a tapped https link to open IN the iOS app: the associated-domains entitlement + an apple-app-site-association file on the domain, which needs a TestFlight build to verify — until then a shared link lands on the web page, which is the right fallback rather than a dead scheme. HISTORY SEMANTICS (fixed after first ship): opening a product page PUSHES a history entry while a tab switch only REPLACES — a page is a destination, a tab is not — so Back closes the page instead of leaving the app; the popstate handler closes an open page when the param is gone (otherwise the URL and the screen disagree and Back looks broken on the one screen we just gave history support to); and the screen clears its params ON UNMOUNT, without which leaving Nutrition left a stale ?food= behind and returning later dumped the athlete on that product instead of their hub. The parse/serialise half is PURE (parseDeepLink/applyDeepLink over plain strings, DOM only in the thin read/write wrappers) and unit-tested in apps/web/__tests__ — path traversal, script tags, over-long ids and junk query strings all degrade to 'the app opened', never to an error. i18n EN/PL/DE." },
  { id: "nutrition-verified-browse", area: "Core", status: "shipped", title: "Verified foods — browse the businesses we've checked", detail: "The verified tier was only reachable by STUMBLING INTO one of its foods through search: the source page existed but had no front door, so nothing in the app told an athlete the tier was there at all. The Nutrition hub menu now carries a 'Verified foods' row (the lime ✓ as its icon, the source count as its badge) opening a new 'sources' view — every VerifiedSource as a card with its mark, name and item count, into the existing source page and on to each product page. Web + mobile at parity; i18n EN/PL/DE. This is also the surface the catalog needs before it grows past one business. HUB PRESENTATION (Jul 2026): the menu ROW was replaced by a left/right RAIL at the very bottom of the hub — the businesses themselves as swipeable cards (mark, name + lime ✓, items-checked), under a SectionHead-anatomy head ('Verified foods' + 'See all →' in mono uppercase on the right, no marker on the left) whose action still opens the full 'sources' view. A menu row hid the catalog behind a chevron; the rail puts the companies on the screen. Full-bleed like every screen-level rail (web `margin: 0 calc(-1 * var(--page-pad-x))` with matching padding, mobile `marginHorizontal: -16` against AuroraScreen's 16dp gutter + snapToInterval), so cards slide under the physical screen edge. Card taps open the source page with pageBack='home'. THE LOGO LEADS THE CARD (Jul 2026): a new MarkPlate (both clients) gives the operator's mark a FIELD to sit on rather than dropping it straight onto the app's charcoal — a hairlined tile a touch lighter than the card (chalk at 7%), the mark contained and centred, never cropped or stretched. This is not decoration: MAX's wordmark is one evenodd path whose keylines are true HOLES, so on ink they fill with ink and the letterforms close up. The plate is deliberately NOT white — a white slab reads as a broken image on AURORA and as a sticker on Kyoto Hour. It is used EVERYWHERE a business appears on a card: the hub rail (full-width plate leading the card, since recognising the business at a glance is that rail's whole job), the sources list, the food page's 'published by' row, the portion sheet's provenance card, and the source page's own hero at plate scale. A source with no artwork keeps the WORDMARK FALLBACK inside the same plate, which is honest (visibly ours) rather than an approximation of a logo we do not hold. Marks still never appear on picker ROWS — a logo per row is an advertising rail." },
  { id: "nutrition-reference-intakes", area: "Core", status: "shipped", title: "Reference intakes for the label panel", detail: "The four panel fields (saturates / sugars / fibre / salt) were recorded and rolled up but had no yardstick, so a day's 24 g of saturates meant nothing on screen. referenceIntakes(kcalTarget) + panelStatus(day, kcalTarget) in @hybrid/core (pure + unit-tested) give them one. THEY ARE NOT PERSONAL TARGETS and the UI never presents them as such — the adaptive macro targets come from THIS athlete's own maintenance and bodyweight, whereas these are WHO/EFSA adult POPULATION REFERENCE INTAKES, and the Diary says so in a caption. Saturates (≤10% of energy) and sugars (≤10% of energy) SCALE with the athlete's energy target, because an athlete eating 4 000 kcal to support training is not 'over' at the same grams a sedentary adult would be; salt (≤5 g) is flat, because a big training day doesn't earn more of it. Fibre (30 g) is stored as a FLOOR, not a ceiling — the one field where more is the goal — and is never coloured as a breach. The Diary day panel now shows value / reference with a hairline bar, terracotta only once a ceiling is actually passed, and keeps the existing 'from the foods that state it' caveat: the totals are a floor by construction, so 'over' means 'already over on what we can see', never 'definitely over'. Web + mobile at parity; i18n EN/PL/DE." },
  { id: "nutrition-hub-bento", area: "Core", status: "shipped", title: "The Nutrition hub's five destinations, as a bento with a real Diary chart", detail: "The back half of the Nutrition home — Diary, Insights, Body & weight, Your meals, Your products — rendered as a flex-WRAP row of five bare buttons in mono uppercase ash at caption size: no surface, no glyph, no arrow, no press state and no data, wrapping onto a second line so the group read as a caption belonging to the block above it. Five destinations dressed as a footnote, with the one opened daily (Diary) at exactly the same weight as the one opened monthly (Your products). REPLACED by a BENTO (apps/{web,mobile}/components/aurora/nutrition-hub.tsx, one component per client, same props): Diary leads as a full-width tile, the other four follow as a 2x2 of stat tiles — each a NUMBER first and a link second (7-day average kcal, bodyweight + weekly rate, saved-meal count, saved-product count), so the block informs even when nobody taps it. The grid does the ranking flat text refused to do. FOUR NEW MONOLINE GLYPHS in NUTRITION_GLYPHS (theme/icons.ts — diary/chart/scale/box, same 72x72 stroke box as the rest, true vectors on both clients, no emoji and no PNG). THE DIARY CHART IS TWO LINES, NOT A SPARKLINE: the day's TARGET against what was actually LOGGED across the last seven days, with the gap between them shaded — a single bar per day only says how much was eaten, two lines say whether it was ENOUGH. The comparison is only interesting because the target MOVES: adaptiveTargets is training-aware, so nutritionHubSeries adds each day's OWN trainingEnergyOnDay on top of the goal target and the dashed target line steps up on hard days — the shape of the week's training is legible in the same picture as the eating. Today's point is the endpoint dot (partial by definition) and the tile always prints the raw pair ('1 840 of 2 600 kcal today'), so the exact figures never have to be read off the pixels. TWO DELIBERATE DEPARTURES FROM spark.ts, whose doctrine is a true zero baseline: (1) this chart is NOT zero-anchored — both series live in a narrow band around 2 000-3 000 kcal and a zero baseline would collapse them onto each other, killing the comparison, so the domain is fitted to both series with a tenth-of-span of padding; (2) a day with NOTHING logged BREAKS the logged line instead of drawing through zero, because 'I didn't log' and 'I ate nothing' are different claims — the target line stays continuous, so the break reads unambiguously as missing data, and a lone logged day with no neighbour is drawn as a dot rather than dropped. Series + geometry are pure and unit-tested in @hybrid/core nutrition-hub.ts (nutritionHubSeries / nutritionHubChart), so the line on the phone and the line in the browser are the same line. Mobile MEASURES the tile (onLayout) and draws in real pixels rather than stretching a fixed viewBox — react-native-svg has no dependable non-scaling-stroke, so a stretched viewBox would draw the stroke thicker across than down; web keeps the scaled viewBox, which browsers rasterize correctly. The delta chip takes the app's existing colour grammar (terracotta past the same +5% grace the hero ring uses, sand under 90%, chartreuse inside the band). The Insights tile is pinned to a SEVEN-day average and never follows the Insights dashboard's own 7/30 toggle — a tile whose number changes because of a control on another screen is a tile you can't trust. Recipes and the verified tier stay OUT of the bento: both are libraries you browse, so they keep their own full-bleed rails below it. Web + mobile at parity; i18n EN/PL/DE (15 new keys)." },
  { id: "nutrition-hud", area: "Core", status: "planned", title: "Sticky \"what's left\" rail across the nutrition screens — REMOVED", detail: "RETIRED (see hero-system-sweep). The sticky HUD — four capsules (kcal left, then P/C/F grams left) that captured as you scrolled past the ring and macro cards and stayed pinned across the nutrition sub-screens — has been DELETED from both clients, along with packages/core/src/nutrition-hud.ts, its unit tests, its 12 i18n keys, and the AuroraScreen stickyTop / stickyTopReserve / onScrollY slot it was the only user of. WHY: it occupied exactly the HERO SYSTEM rail y (safeTop + 4, 44pt), so Nutrition was the single screen in the app whose head could not be the system's — two bars competing for one row. The decision was to REMOVE the HUD rather than dock it as a sub-rail: a persistent numeric rail on every sub-screen is a second head, and the rank rule says a screen has one. The budget it carried is still one tap away — the hub's calorie ring and macro card are the source, and every sub-view's back control returns there. IF IT COMES BACK it must return through HeroScreen's `rail` slot (which docks BENEATH the hero's rail rather than replacing it), never as a screen-top overlay; the capture/hysteresis/ceiling model in the old nutrition-hud.ts is worth recovering from git history if so." },
  { id: "nutrition-recipe-cook-log", area: "Core", status: "planned", title: "Log a cooked recipe to the day", detail: "The recipes library is read-only today (browse → scale → cook-along). The next step is to LOG a cooked recipe's macros into the day: a 'Log this meal' action on the recipe detail / end of the cook flow that writes the SAME energyIntake/protein/carbs/fat Signal kinds (recipeMacrosForServes already computes the whole-recipe totals for a chosen serves count), attributed to the current meal. Also planned: user-saved / editable recipes (needs a Recipe Prisma model + RLS + /api/nutrition/recipes, mirroring saved meals) so the library isn't only the curated set." },
  { id: "nutrition-barcode-camera", area: "Core", status: "planned", title: "Live camera barcode scan (point-and-scan)", detail: "The OFF barcode LOOKUP is shipped (type/paste a barcode number → product) — see nutrition-fooddb. The remaining piece is a live CAMERA scanner on mobile: open the camera, detect the EAN/UPC, and fire the same /api/nutrition/search?barcode= lookup. Needs a native module (expo-camera's barcode scanner) added to the Expo config + a prebuild/TestFlight rebuild, which can't be built or verified in this sandbox (no simulator). Web has no equivalent camera-scan (desktop) so parity holds via the shared typed-barcode path." },
  { id: "nutrition-label-scan", area: "Core", status: "blocked", title: "AI nutrition-label scan (Full)", detail: "The 'Add a meal' sheet has a Full-only 📷 Scan label action on BOTH clients: web uses a file input (accept=image/*, camera capture on mobile browsers), mobile uses expo-image-picker (base64). The photo is sent to a new server route /api/nutrition/scan which asks Claude (vision, claude-opus-4-8, server-side only) to read the per-serving macros and returns {name, kcal, protein, carbs, fat}; the sheet flips to the Macros tab and prefills the fields for a one-tap add. Auth + rate-limited (15/min/IP) + Full-gated server-side (entitlementOf, 403 → client routes to upgrade) so the paid feature can't be called directly. NEEDS: ANTHROPIC_API_KEY in the deployment env — until then the endpoint returns 503 {configured:false} and the button shows an error toast. (Distinct from the barcode/food-DB approach in nutrition-fooddb; this is a vision-LLM read of the label, no food database required.)", blockedBy: "ANTHROPIC_API_KEY in the Vercel/server env (same key the AI coach + agents use). No other dependency — the UI, upload, gating and endpoint all ship." },
  { id: "profile-volume-stats", area: "Core", status: "shipped", title: "Profile — total sessions + lifetime tonnage", detail: "The Profile/You screen (web profile.tsx + mobile profile.tsx, at parity) shows a second hairline stat strip beneath the HPI/Streak/PRs spec strip: total SESSIONS (sessions.length) and LIFETIME TONNAGE (sum of sessionVolume(s.blocks) across every logged session, formatted via fmtTonnage to the athlete's units — tonnes for kg, total lb for lb). Both degrade to '—' with no data (no fabricated numbers)." },
  { id: "profile-overview-thisweek", area: "Core", status: "shipped", title: "Profile Overview — 'This week' snapshot", detail: "The Overview tab leads with a current-focus band: sessions logged + tonnage moved in the last 7 days (computed from sessions' startedAt + sessionVolume). It sits above the lifetime highlight tiles and is deliberately distinct from both those tiles (lifetime windows) and the 26-week Activity heatmap (daily dots), so it adds signal without duplicating either. Hidden when there are no sessions this week (no demotivating zeros). Web + mobile at parity. i18n (en/pl/de) w.account.profile.ov-tw." },
  { id: "settings-drill-in", area: "Core", status: "shipped", title: "Settings — search + drill-in sub-pages + value summaries", detail: "The account/settings hub (web account-settings.tsx + mobile aurora/settings.tsx, at parity) was rebuilt from an accordion into an Apple/iOS-style structure on BOTH clients: (1) a SEARCH box filters every category by title/subtitle/keywords via the shared matchSettings() helper (@hybrid/core settings-nav.ts, which now carries per-category `keywords`); (2) DRILL-IN sub-pages — tapping a category opens a focused sub-view with a back button instead of expanding inline (mobile keeps its dedicated routes for social/logger/coaching/subscription; the rest drill into the shared renderBody); (3) each category ROW shows a live CURRENT-VALUE summary on the right (e.g. Preferences → 'Aurora – EN – kg', Notifications → '3/4', Subscription → 'Full'); (4) the shared groups were reorganized/renamed (General – Visibility & reach – Account & billing – Data & danger zone). The per-category control bodies + all read/write logic (Supabase auth, useAccountSettings, logger prefs, billing) are unchanged — only the shell + IA changed. New i18n (search/no-results/back, en/pl/de). BENTO PASS (both clients, at parity): the grouped LIST-of-rows was replaced with a BENTO TILE GRID — each SETTINGS_CATEGORY renders as a rounded tap-target tile (tinted icon chip + title + live value summary/subtitle) in a 2-column grid under the existing group headers, with a full-width wide tile for odd-count groups and the red danger treatment preserved; search, drill-in sub-pages, the FREE/FULL membership pill and all useAccountSettings wiring are unchanged (web account-settings.tsx CSS grid + mobile aurora/settings.tsx flexWrap). PARITY/FIDELITY HARDENING: web↔mobile audited 1:1 and against the design mock — the web TONE was unified to the mobile multi-hue chip palette (it was lime-forward, and the `${accent}24` lime chip-tint was silently invalid because LIME is a CSS var not hex) — since SUPERSEDED: both clients' TONE were later collapsed to a single neutral ash chip (red kept only for danger) per the one-accent discipline, see design-system-unification. The profile hero anatomy (bordered card, rounded-square initial avatar, name, secondary line, role/provider pills, membership pill) was made identical on both clients; mobile membership + title copy moved to i18n." },
  { id: "weekly-recap", area: "Core", status: "shipped", title: "Weekly recap (retention loop)", detail: "recap.ts: weeklyRecap rolls the last 7 days into one summary — sessions, tonnage, sets, minutes, active days, distinct lifts, total cardio DISTANCE (km), the week's PRs (best per lift via pr-detection) AND cardio PRs (distance/pace), the top trained muscle (volumeByMuscle), and deltas vs the prior 7-day window. The 'Your week' cards (web + mobile) show weekly distance + a 🏃 cardio-PR chip when there's running. Pure + 5 unit tests. Drives the 'Your week' card on web + mobile Today and a branded, shareable recap image on mobile — giving 'come home and review' a weekly beat and a natural social moment. The same engine file also exports weekAdherence() — a glanceable Mon→Sun strip (done / today / missed / future per day + a done/target count) that powers the collapsible week-adherence card in the Today PLAN section on both clients (it sits above the detailed reconciled 'This week', which stays expanded)." },
  { id: "pr-detection", area: "Core", status: "shipped", title: "Personal-record detection + muscle volume", detail: "records.ts: pure session-analysis helpers. PRs — bestE1rmMap (all-time best per lift), newPrsInSession (records set in a session vs everything done before it, first-time lifts included, ranked by improvement) and prsForSession (PRs for one session pulled from the full history by date) — power the post-workout PR celebration + share line and the session-detail / History PR badges. CARDIO PRs too: newCardioPrsInSession / cardioPrsForSession detect a DISTANCE PR (furthest ever for a cardio move) or a PACE PR (beat your best pace among prior runs of that move that were this distance or SHORTER, so a quick short jog can't fake a long-run record) — surfaced as a 🏃 celebration on finish, a share line, and a cardio-PR banner/badge on web + mobile session detail. volumeByMuscle attributes each strength set's tonnage to every muscle the movement trains (via the MOVEMENTS map) for the 'what did this session work?' breakdown on web + mobile. exerciseHistory lists every exercise the athlete has logged (most-recent-first, with counts) to power the live workout's fast picker. Pure + 10 unit tests." },
  { id: "workout-summary-slides", area: "Core", status: "shipped", title: "Shareable workout-summary slides + fun comparisons (2 'wrapped' styles)", detail: "The post-workout 'Workout complete' screen is a swipeable carousel of slides — Overview (name + minutes/sets/volume), then Spotify-Wrapped-style single-stat SPOTLIGHT slides (Time trained, Total load — one giant hero number each), PRs & bests, Muscle focus (volumeByMuscle), and a Hevy-style Fun comparison — floating as the hero object of the Liquid-Field finish screen (see finish-liquid-field). ALL slides ship on every client (web, responsive/mobile web, native mobile); on web the carousel captures horizontal swipes (touch-action: pan-x) and the page dots are tappable so every slide is reachable on a phone browser, not just by swipe. Each slide is rendered as the REAL full 9:16 Instagram-story card right on screen (what-you-see-is-what-you-share), not a compressed preview box, and TAPPING the card cycles between 2 looks before sharing (the old segmented style toggle folded into the card itself — see finish-liquid-field): Liquid Glass (a BORDERLESS frosted translucent slab over a lime×blue blur — the old rim stroke read as a 'weird' floating box, so it was dropped) is now the DEFAULT (DEFAULT_STORY_STYLE in story-styles.ts, so both clients open in Liquid Glass), with Aurora (signature dark + lime glow) the alternate. (A third 'SwiftUI' share style + its native iOS renderer were REMOVED — the cross-platform card is the one source of truth.) Every card's footer signs off with the HYBRID LOGO — the 'Tracked with HYBRID.' line renders the trailing brand as the real wordmark (display type + lime accent dot) on all three renderers (web canvas, web DOM preview, mobile RN), locale-safe (the brand mark is terminal in EN/PL/DE so the dot never lands mid-sentence). The styles live in ONE shared source of truth — packages/core/src/story-styles.ts (STORY_STYLES / storyStyle()): renderer-agnostic looks (base bg, optional diagonal gradient, soft glow discs positioned as fractions, optional translucent glass panel, text/accent/bar colours) so web and mobile paint the SAME card. The model also supports gradients (canvas linear-gradient on web; expo-linear-gradient on mobile) so new styles are a one-entry addition. The single Share button exports whichever slide is on screen, in the chosen style, as a 9:16 (1080×1920) PNG (mobile: the on-screen SlideStoryCard captured via react-native-view-shot + expo-sharing; web: the <canvas> painters drawSlideStory(slide, …, styleId) → navigator.share, downloads/text as fallbacks). Style names localized EN/PL/DE (summary.style.*). comparisons.ts is the pure, i18n-safe fun-fact engine: workoutFunFact/sessionFunFact map a session's volume (kg), reps, or distance to a playful tiered equivalent ('over a tonne — about a small hippo'), choosing the most impressive metric so it varies naturally; copy lives in i18n (en/pl/de). Built on the existing stats engines (sessionVolume, newPrsInSession, volumeByMuscle). Web + mobile parity; unit-tested; web build + iOS bundle export green." },
  { id: "finish-liquid-field", area: "Core", status: "shipped", title: "Finish workout — Liquid Field redesign", detail: "The post-workout summary was redesigned on BOTH clients around one principle: celebrate first, decide second, one action. The 9:16 story card now FLOATS in a Liquid Field — an intensified pocket of the ambient Aurora field (web: .ff-a/.ff-b radial glow discs drifting on the shared lgDrift keyframes over .lg-field, with the Kyoto-Hour washi retint and prefers-reduced-motion honoured; mobile: FinishField — two oversized lime/teal glow orbs faked from concentric translucent circles with a slow Animated drift, Reduce Motion parks it, KYOTO HOUR swaps to the warm washi tones). The five stacked near-equal CTAs collapsed into ONE pill cluster: the lime Share pill (the only filled action, milestone-aware label + glow — 'Share your first workout' / 'Share your PR' / 'Share your win') flanked by two glass satellite orbs — ★ Routine (expands the save-as-routine composer in place via a new startOpen prop on SaveRoutine/SaveRoutineCard) and → Analysis (history) — plus a glass ✕ top-left as the one exit ('Done — back to Today'; guests exit to welcome, keeping their sign-up path below the cluster). The segmented STYLE TOGGLE is gone: tapping the card cycles the wrapped look (selection haptic on mobile; role=button + Enter/Space on web), with a one-line mono hint naming the current look ('LIQUID GLASS — TAP TO CHANGE THE LOOK', summary.cardHint). The old hero header (badge + 'Workout complete' + name) was removed — the card IS the headline (it already carries the title and the 'First workout 🎉' treatment); the optional rename + private note stay as quiet dashed pills under the hint; pending-sync and guest states unchanged. The entrance spring + success haptics/vibration now land on the floating card. Dead keys removed across EN/PL/DE (summary.styleLabel/digDetail/shareNudge/complete/firstTitle/firstSub + w.train.logger.firstDone/sessionComplete/shareStory); new keys summary.cardHint/orbRoutine/orbAnalysis." },
  { id: "session-pr-reveal", area: "Core", status: "shipped", title: "PR reveal on the individual-workout page (celebrate first)", detail: "The individual-workout page (web SessionDetail + mobile /session/[id]) opened on a flat '🏆 N new personal records' banner — a receipt, not a moment. It now LEADS with an animated PR REVEAL when a session set a record: ONE headline record lands as a hero (the trophy springs in, a lime sweep crosses once on web, the est-1RM/distance/pace counts up from zero, then rests on the exact value), with 'Share your win' as the payoff CTA wired to the existing story share. Which record headlines is chosen by a NEW shared pure model — packages/core/src/session-celebration.ts (sessionCelebration(prs, cardioPrs) → the heaviest strength lift leads, headlined by the WEIGHT ACTUALLY MOVED (see session-summary-heaviest); a cardio distance/pace PR only headlines a PR-but-no-lift session; carries firstEver + the total PR count so the hero reads 'first ever' / '+Δ' / 'furthest yet' / 'fastest yet' and lists 'and N more' below) so web + mobile headline the SAME record with the SAME copy. Count-up reuses the shared statCountUp (same core as the summary carousel + mobile CountUpText); web uses CSS keyframes (prTrophyPop/prSweep/prRise, all prefers-reduced-motion-guarded → static card) and mobile an Animated spring. When a session set >1 record the full PR list (🏆 strength + 🏃 cardio) stays in a quiet card beneath the hero. New i18n EN/PL/DE (summary.prOne/firstEver/furthestYet/fastestYet). Unit-tested (session-celebration.test.ts). FIDELITY PASS: the reveal also fires a rotating gold ray halo + a deterministic confetti burst (web CSS keyframes prRaysSpin/prConfetti + module-level fan; mobile Animated rotate loop + LinearGradient halo + Animated confetti fan), both prefers-reduced-motion-guarded. Web + mobile typecheck green." },
  { id: "session-wrapped-flow", area: "Core", status: "shipped", title: "Workout-page Wrapped + multi-story share picker", detail: "The individual-workout page's PR reveal (session-pr-reveal) now opens a full 'Wrapped' TAKEOVER — the reference/ prototype (reference/pr-wrapped-flow.html) built for real on both clients (web components/aurora/workout-wrapped.tsx overlay + mobile components/workout-wrapped.tsx Modal). Two steps: (1) WRAPPED — a hero (session title + the PR headline or total tonnage) over a free BASICS strip (sets / reps / volume / time / distance) then a premium ANALYTICS panel GATED behind isFullAccess(usePersona()): est-1RM, e1RM trend (gain from first-logged to this session, coloured up/down), the session's top muscle by tonnage, and logged readiness — REAL derived data only, no fabricated power/energy/percentile; free users see the panel obscured (web blur / mobile dim) under a ✦ upsell using the admin-set premium accent (web VIOLET / mobile usePremiumAccent) that routes to /upgrade. (2) SHARE — the multi-story picker: swipeable 9:16 cards (overview / time / load / PRs / muscle / fun) that TAP-cycle the STORY_STYLES look, reusing the SAME primitives as the finish carousel (web StoryCard — extracted from logger.tsx into components/aurora/story-card.tsx so both screens share one card — + shareWorkoutSlide; mobile the already-shared SlideStoryCard + shareWorkout capture). The reveal's 'Share your win' opens the takeover; a no-PR session gets a '✦ See your Wrapped' entry so every workout can reach it. CLEANUP (post-TestFlight review): the pre-existing OLD share UI on the workout page was retired so the Wrapped is the single share surface — mobile dropped the inline WorkoutShareCard + its 'Share your win' button, and web repointed its header share pill at the Wrapped (removing the old shareWorkoutStory path); the page no longer shows two competing share buttons. PAGE-AS-EXPERIENCE (mobile, post-TestFlight): the individual session screen (apps/mobile/app/session/[id].tsx) was rebuilt to BE the reference prototype 1:1 — opening a session renders full-screen: the PR reveal panel (trophy spring + rays + confetti + count-up, when there's a record) → the premium WRAPPED panels you SCROLL through (snapToOffsets: hero 'your workout, wrapped' + big number + basics; premium 'What this set really did' facts; 'Where you stand' Top N% + the session-signature ribbon) with a sticky share dock (dots + 'Share this win') → the slide-up story SHEET ('Choose your story' + swipeable SlideStoryCards + dots). The set breakdown + archive/delete ride along as a trailing 'The session' details section. New i18n session.wrapped.scroll/premiumLead/signatureCap + session.theSession. WEB PARITY PENDING: web session-detail is embedded in the app-shell History view (not a full route) and still uses the tap-to-open Wrapped overlay — bringing the same full-screen scroll experience to web is the immediate follow-up (tracked under parity-followups). The panel data is one shared pure model — packages/core/src/session-wrapped.ts sessionWrapped(session, all, {units, bw}) → basics[] + facts[] (each present only when computable, honesty rule inherited from done-receipt), unit-tested (session-wrapped.test.ts). The Wrapped hero also draws the SESSION SIGNATURE — a per-set effort ribbon from the shared pure sessionSignature() (RPE → load-relative → neutral, deterministic, unit-tested), gated on SIGNATURE_MIN_BARS so a 1-set session doesn't draw two sticks. New i18n EN/PL/DE (session.wrapped.*). Both clients typecheck; web build + iOS bundle export green. PROTOTYPE-FIDELITY GAPS still open (tracked as session-wrapped-prototype-gaps): the 'Top X%' percentile panel (needs sex/age + a population dataset — see benchmarks.ts synthetic priors / exercise-analytics-rankings) and the 4 bespoke story-card DESIGNS (Trophy / Signature / Wrapped-stat / Minimal) — the picker currently reuses the shared 6-slide story system in 2 looks rather than a fabricated percentile or a second story renderer." },
  { id: "session-wrapped-web", area: "Core", status: "shipped", title: "Web parity — individual session as the full-screen Wrapped experience", detail: "DONE — web now matches mobile 1:1. apps/web/components/aurora/workout-wrapped.tsx was rebuilt from the earlier tap-to-open overlay into a FULL-SCREEN, vertically-scrolling takeover (fixed inset-0, scroll-snap-type y): opening a session renders the same panels as the mobile prototype (reference/pr-wrapped-flow.html) — the PR REVEAL (trophy pop + rotating gold rays + confetti + count-up via the shared prTrophyPop/prRise/prRaysSpin/prConfetti keyframes, when there's a record) → the premium WRAPPED panels you scroll (hero '✦ your workout, wrapped' + session title + big number + basics grid + the sessionSignature ribbon; premium 'What this set really did' facts, blurred behind a ✦ upsell for free users; 'Where you stand' Top N% + signature) → a sticky bottom share DOCK (page dots + 'Share this win') → the slide-up story SHEET ('Choose your story' + the shared StoryCard pager + dots). apps/web/components/session-detail.tsx was rewired: it computes the charts (Muscle focus + e1RM/pace trends) + the per-exercise breakdown + the archive/delete manage row into a trailing `details` node and returns <WorkoutWrapped … details={details}/> — so the workout page IS the experience on web too, not an overlay grafted onto the old page. Reuses the SAME shared pure core as mobile (sessionWrapped / sessionSignature / liftStanding / sessionCelebration) so the two clients can't drift; talent-gated standing + Full-gated premium facts inherit the honesty rule (real derived data only). Web typecheck + build green." },
  { id: "session-summary-heaviest", area: "Core", status: "shipped", title: "Workout summary headlines the weight lifted, not the estimated 1RM", detail: "Follow-through on #231, which retired e1RM as the headline across the EXERCISES surfaces but left every SESSION-SUMMARY surface still leading with it — so a deadlift session topping out at 100 kg was celebrated as '120 kg', a number the athlete never lifted. Fixed at the source rather than per-screen: PrHit (engines/records.ts) now carries `topLoad` + `previousTopLoad` (the heaviest ACTUAL working load, bodyweight-aware via the existing blockTopLoad/topLoadMap primitives #231 added) ALONGSIDE the e1rm/previous pair. e1RM still DETECTS records and is deliberately untouched there — a rep PR (100 kg x 5 -> 100 kg x 8) is a genuine record that no weight comparison would ever find — it just no longer DISPLAYS as 'your best'. Celebration (session-celebration.ts) gained topLoad/previousTopLoad plus a `repPr` flag and now picks the headline by heaviest actual lift (e1RM only breaks ties), so the record chosen is the one whose number goes on screen. New shared formatter formatStrengthPr (engines/session.ts, mirroring formatCardioPr) renders the three honest shapes -- 'Deadlift 100 kg (first!)' / 'Bench 82 kg (+6 kg)' / 'Pull-up 88 kg (more reps)' -- replacing four duplicated client prLine copies, so the wording and delta math can't drift. RETIRED at parity on web + mobile: the Wrapped reveal + hero big number, the per-exercise breakdown badge ('120 kg e1RM' -> '100 kg'), the PR list lines, the post-workout summary, the story-share slides/cards (ShareBest.e1rm -> .weight, sourced from blockTopLoad), the weekly-recap share line, and the Cockpit 'your week' PR rows (which would otherwise have contradicted the summary for the SAME PR). e1RM deliberately KEPT where it is labelled as such and honest: the premium 'Est. 1RM' Wrapped fact, the labelled e1RM trend charts, %e1RM intensity zones, rep-max matrix, load-reps isolines, Team Compare, sport-engine prescription, and the 'Where you stand' percentile (the benchmark norms are built on e1RM, so it keeps an e1RM input on purpose). i18n EN/PL/DE: new summary.morePrReps + summary.heaviest, and summary.todaysBests no longer promises '(est. 1RM)'. PARITY SWEEP (follow-up): the summary surfaces were audited pair-by-pair and the shared logic hoisted into core so the two clients cannot drift again — strengthPrDelta (the first/+X kg/more-reps branch, previously hand-written in SIX places across both clients; it also formats through fmtWeight, fixing a float artifact where a 0.1-rounded topLoad subtraction printed +4.799999999999997 in the Cockpit rows) and workoutShareCaption (the share blurb, which on web was hardcoded ENGLISH and headlined the session's heaviest lift rather than the record actually set — both clients now emit the same localized caption and headline the SAME record the reveal hero showed, taken from the celebration rather than prs[0], which is ordered by e1RM gain and could name a different lift). Drifts closed at the same time: web session-detail's cardio PR line and readiness label were hardcoded English; the post-workout PR row used w.train.logger.firstTime on web vs summary.firstTime on mobile (different copy in all three locales); the PR-slide headline pluralized on web only (now pluralized on all four summary surfaces); web's cardio PR row showed '1.5 km / faster pace' where mobile used the sport's natural unit with a delta (both now formatCardioPr); the story row list truncated at 7 on web vs 6 on mobile; web's canvas card hardcoded 'TODAY'S BESTS' so it never picked up the new '(heaviest)' qualifier; and its overview slide used 'MIN' + w.train.logger.* labels vs mobile's summary.* ones. The coach weekly-recap rows — the same PrHit data — still headlined e1RM AND differed between clients (web showed a 'first' label, mobile omitted it); both now use formatStrengthPr, so coach, cockpit and the session summary agree on one number for one PR. The unused summary.heaviest key added in the first pass was removed. A re-audit then caught two things the sweep had half-done: the story-card label fix had been applied to web's DOM preview but NOT to the canvas painter that produces the actual shared PNG — breaking that file's own 'the preview is exactly what we export' contract and leaving the exported image's minutes cell hardcoded English — and the two Wrapped surfaces still rendered cardio PR rows as raw km (a 400 m swim PR read 'Swimming 0.4 km', with no delta) while the two post-workout surfaces used formatCardioPr; all four now share the one formatter. KNOWN + DELIBERATELY LEFT: the Cockpit/coach PR rows hardcode kg (identical on both clients, so not a parity break, but a lb athlete sees kg there — needs units plumbed into those components), and apps/web/lib/workout-share.ts still carries the legacy drawStoryCard/shareWorkoutStory painter, which has had no callers since the Wrapped became the single share surface — dead, but left in place rather than removed as drive-by scope. GUARD (packages/core/src/e1rm-headline.test.ts): #231 had to be fixed twice — first across the Exercises surfaces, then again for the whole workout summary — because nothing stopped a new screen from reaching for the best-e1RM helpers and labelling the result 'best'. Every client reference to blockBestE1rm / bestE1rmByLift / bestE1rmMap is now listed with a reason, and a NEW one fails the core suite with a message naming the topLoad replacement (blockTopLoad / bestTopLoadByLift / topLoadMap); a second assertion deletes stale entries so the list can't rot. Verified in both directions — it fires on an injected regression and on a stale path, and passes when clean. e1rmSeries is deliberately unguarded (a time series, always plotted under an explicit 'e1RM trend' label). e1RM itself is untouched and still ships wherever it's LABELLED as an estimate: the premium Est. 1RM fact, the trend charts, %e1RM zones, the rep-max matrix, velocity profiles and the relative-strength percentile — the formulas (Epley/Brzycki/Lombardi) are valid across their rep range and are NOT capped. NEW GAP the guard surfaced, recorded rather than silently changed: apps/web/app/api/social/posts/route.ts publishes an athlete's PR post as bestE1rmByLift, and core profileStats().topLifts does the same for the public profile (rendered unlabelled as '{n} kg' in apps/web/components/social-profile.tsx) — so a 250 kg x 10 deadlift is announced socially as 333 kg while that athlete's own Profile PRs grid (topLoadMap) says 250 kg. Not a drop-in swap: both write a PERSISTED { lift, e1rm } shape (Post.data JSON + ProfileStats), so converting needs a read path that still renders already-stored posts. DETECTION now matches display: newPrsInSession fires a record on EITHER basis — a heavier top load than ever, or a better estimated 1RM. Previously detection ran on e1RM alone while the display had moved to top load, so a heaviest-ever lift that followed a high-rep block set no record at all: 80 kg x 15 (e1RM 120) then 100 kg x 5 (e1RM 117) is the heaviest that athlete has ever squatted and produced no trophy, no PR row and no Cockpit entry. The rep PR (100x5 -> 100x8) still fires exactly as before — it qualifies on the e1RM basis — so nothing that used to be a record stopped being one; the change only ADDS the load basis. PrHit.e1rm is now documented as 'this session's best e1RM', NOT necessarily greater than previous, since a load-only hit can carry a lower estimate than the athlete's prior best. Ordering changed to heaviest-first across newPrsInSession and weeklyRecap, matching the basis sessionCelebration picks the hero by — so prs[0] is now the same record the trophy shows (they could previously disagree, which is how a share caption ended up naming a different lift than the trophy above it). The DERIVED social feed PR chips (social.ts, computed live from sessions) were converted to top load in the same pass — they had rendered an unlabelled '{e1rm} kg'; the PERSISTED post route is now converted too, with an expand-and-fall-back read rather than a rename: apps/web/app/api/social/posts/route.ts writes { lift, topLoad, e1rm } (topLoad is the headline, e1rm retained so the estimate isn't lost and nothing expecting the old shape breaks), and the new shared reader social.ts prPostFigure() prefers topLoad, falling back to a LABELLED '{n} kg e1RM' for rows written before #231 — those can't be backfilled, since an estimate can't be reversed into a bar weight, so they stay honest instead of being passed off as a weight the athlete lifted. ProfileStats.topLifts is DERIVED (computed per request from sessions, never stored) so it moved straight to bestTopLoadByLift with the field renamed e1rm → topLoad, and its one consumer (apps/web/components/social-profile.tsx) renders the real weight; mobile never surfaced top lifts, so there is no mobile counterpart to update (a pre-existing gap, not a new drift). Four migration tests pin BOTH stored shapes and were verified to fail against a naive rename that drops the legacy branch. Net effect: an athlete's public profile and shared PR posts now announce the same number their own Profile PRs grid shows. Six tests cover the new detection, verified to fail against the old e1RM-only logic. Core suite green (1049 passing, +10 new covering the reported bug, the rep-PR case, the weight-vs-e1RM pick and the formatter); core + mobile typecheck clean, web clean apart from the pre-existing nutrition/Prisma-client errors on main." },
  { id: "session-wrapped-prototype-gaps", area: "Core", status: "shipped", title: "Workout Wrapped — prototype-fidelity pieces", detail: "reference/pr-wrapped-flow.html is now reflected end-to-end. SHIPPED across the passes: the reveal rays + confetti; the Wrapped-hero signature ribbon; TWO bespoke share designs as first-class slide kinds across all three renderers (web DOM StoryCard + web canvas drawSlideStory + mobile SlideStoryCard) — 'trophy' (🏆 + PR value + 'new personal record') and 'signature' (the sessionSignature effort ribbon) — which LEAD the workout-page story picker; and the 'Where you stand — Top X%' percentile, done HONESTLY: the Wrapped overlays fetch the athlete's talent cohort (GET /api/talent → sport/sex/age; mobile fetchTalent()), and when that profile AND a known bodyweight exist, the shared pure liftStanding(e1rmKg, bodyweightKg, cohort) (packages/core/session-wrapped.ts, unit-tested) computes the heaviest lift's relative-strength percentile from the documented benchmarks.ts synthetic norms (norms-prior-v0) and renders 'Top N%' inside the premium (Full-gated) analytics panel, captioned '<sport> — estimate'. It NEVER fabricates: no talent profile or no bodyweight → the standing simply doesn't render (a fuller live board is exercise-analytics-rankings). New i18n EN/PL/DE (session.wrapped.standing/top/estimate). REMAINING (intentional, not a gap): the mockup's in-app share DESTINATION buttons (Instagram/Messages/Copy-link) are delegated to the OS native share sheet, which already surfaces those targets; the 'minimal' card ≈ the existing 'stat' slide. Both clients typecheck; web build + iOS bundle export green." },
  { id: "session-wrapped-discipline", area: "Core", status: "shipped", title: "Workout Wrapped is discipline-shaped (a swim is not a gym session)", detail: "The Wrapped poured EVERY logged session through the gym's Sets/Reps/Volume mould, so a 1 500 m swim read '1 SET' (a cardio effort counts as one set in doneReceipt) and its hero showed '0.0 t' of tonnage — numbers that are true of the data model and meaningless to the athlete. Fixed in the shared model, not per-screen: sessionWrapped() now returns a `discipline` (strength / endurance / sport / conditioning / mixed, from wrappedDiscipline()), a `headline` (the ONE number that defines that kind of session) and a discipline-shaped BASICS strip capped at four tiles, each tile included only when it has something true to say. STRENGTH keeps sets/reps/volume/minutes; ENDURANCE gets distance/time/pace/calories in the sport's own units (metres and /100m for swimming, /500m for rowing, km elsewhere — via the existing formatSportDistance/formatSportPace); a timed SPORT (tennis, judo, football) gets time/calories/effort and never a set count; CONDITIONING gets time/rounds/calories/effort; MIXED gets time/distance/volume/calories. The hero follows the same rule — distance for a swim, tonnage for a lift, time for a match — instead of tonnage for everything. Premium FACTS gained the endurance side too (derived pace, climb, MET-minutes). Both clients render the same model (web components/aurora/workout-wrapped.tsx, mobile components/workout-wrapped.tsx) and the shape is unit-tested per discipline, including the 'never show sets or volume for a swim' regression. ALSO FIXED here: on mobile the floating Liquid-Glass pill nav is rendered at the ROOT over every screen, so it sat ON TOP of the Wrapped's sticky Share dock — the share button was literally behind the tab bar. The Wrapped is a full-bleed story takeover with its own back button, exactly like the live logger, so the `session` route joined global-nav's HIDE_ON. That matches web, where the Wrapped is an opaque fixed overlay ABOVE the pill nav and the bar was never visible. FOLLOW-UP CAUGHT IN REVIEW: widening the value vocabulary from '11.3 t' to '1500 m' and '2:20 /100m' overflowed the slots those sizes were chosen for — the 96px hero wrapped to two lines and a tile value pushed its label out of line with the three beside it. fitScale() in session-wrapped.ts now shrinks a value to one line, off a per-glyph em table MEASURED from Archivo Black rather than a character count: '11.3 t' and '1500 m' are both six characters and measure 66px and 85px in the tile, because a dot and a space are a third the width of a digit, so counting characters is off by 30%. It lives in core because mobile could lean on adjustsFontSizeToFit and web has no equivalent — two implementations would mean two different answers to 'how big is this number'. Both clients apply it to the hero (with the slot's negative tracking) and to the four tiles; tests assert every value the panel can produce fits its measured slot width." },
  { id: "session-wrapped-measured-precision", area: "Core", status: "shipped", title: "The Wrapped reads the watch's numbers, at the watch's precision", detail: "A matched pool swim's Wrapped showed 500 m at 4:00 /100m while the comparison panel two screens away showed the watch's own 510 m at 3:52 /100m — so a correctly matched session looked as though the sync had never landed. Neither figure was the typed one; both were the measurement, mangled by our own rounding. THREE FIXES, all in shared core so both clients inherit them. (1) doneReceipt rounded distance to 0.1 km, which erased the ten metres the watch measured (0.51 → 0.5) and then paced the swim over the wrong distance; it now rounds to the METRE, with the coarse tenth-of-a-km applied where a rail stat renders it (doneReceiptStats) rather than in the model. displaySportDistance caps km sports at two decimals so an unrounded measured distance can't print '10.234 km'. (2) The receipt gained `durationSec` — the recording's second-accurate moving time — and every DERIVED rate reads it in preference to the whole minutes: 510 m in 19:41 is 3:52 /100m, and dividing by a rounded 20 min turns that into 3:55. CardioBlock gained the same optional `seconds`, written ONLY by the device projection (device-truth.ts), so cardio PRs, pace trends and the block's own pace line agree with the watch too; the duration itself still DISPLAYS in minutes. (3) A cardio PACE PR headlined `${paceClock(value)} /km` hard-coded on both clients, so a swim PR read '39:13 /km' — it now goes through formatSportPace and reads '3:52 /100m'. Regression-tested against the reported swim (500 m / 20 min typed, 510 m in 19:41 measured) in session-wrapped.test.ts + device-truth.test.ts. FOURTH FIX (Aug 2026, same class, one layer lower): the STORED read was on a 10 m grid. sanitizeDeviceWorkout rounded distanceKm to two decimals of a kilometre, so a 34 m pool swim (0.034 km) was written as 0.03 — the app showed '34 m' in the logged column and '30 m' in the measured one beside it, and paced the swim 12:33 /100m against the watch's own 11:06. Ten metres is invisible on a 10 km run and is the whole workout on a warm-up length, and distance is the one measured figure spanning three orders of magnitude — there is no single grid that fits it. So the rounding is GONE from the model layer entirely: sanitizeDeviceWorkout stores the device's figure verbatim, doneReceipt and mergeDoneReceipts carry it unrounded, and every surface rounds where it RENDERS (deviceDistanceLabel — extracted from the comparison panel and now shared with the match picker, which was printing the raw float — displaySportDistance for the session's own figures, doneReceiptStats for the rail's coarse headline). Nothing derived may divide by a rounded distance, which is the whole reason the summary's pace and the watch's pace can agree. Its lower bound dropped from 0.01 km to 0.001 km too — the old floor discarded any recording shorter than 10 m outright. doneReceiptStats reads a sub-kilometre distance in metres for the same reason (tenths of a km made that swim '0 km' on the week + logbook rails). Already-matched sessions heal themselves: Connections → Apple Health → Sync re-reads every stored uuid (refreshMatchedWorkouts) and re-PATCHes the rows whose read changed — it needs the new mobile build, because the rounding happened on-device before the PATCH." },
  { id: "session-edit", area: "Core", status: "shipped", title: "Edit a workout you already logged", detail: "Logging is a hurry: a distance gets skipped, minutes get fat-fingered, a set lands with the wrong load — and until now the only remedies were to live with it or DELETE the workout and log it again, which throws away its PRs, the feel report and any device match. An 'Edit workout' sheet on BOTH clients (mobile components/session-edit.tsx, web components/session-edit.tsx, opened from the session summary's manage row) now corrects the figures in place: the workout name, each cardio effort's distance / time / climb / RPE, each conditioning block's rounds / time / RPE, and every strength set's load × reps × RPE (clear a row to delete that set, or add one). The model is SHARED (core/session-edit.ts, unit-tested): sessionEditDraft turns the stored session into editable strings — distance in the sport's own unit (metres for swimming/rowing), loads in the athlete's own unit — and sessionEditPatch FOLDS the draft back onto the ORIGINAL blocks rather than rebuilding them, so everything the sheet never showed (stroke, incline, zone, superset group, planned rest, a set's role/drop flag, the live logger's measured rest and bar velocity) survives an edit; a draft that no longer lines up with the session leaves that block untouched instead of guessing. An UNTOUCHED load keeps its stored string verbatim, because kg → lb → kg does not round-trip and would otherwise quietly rewrite every load of an lb athlete who opened the sheet to fix one distance. editableBlockFields decides which inputs a block shows (no distance for a timed-only sport like judo; no climb for a pool swim unless one was already logged), so the two clients can't drift. PATCH /api/sessions/[id] now accepts `blocks`, validated by sanitizeSessionBlocks — unlike the create route, which stores what our own logger built, an edit OVERWRITES an existing workout, so anything that doesn't sanitize is a 400 rather than a partial write. On a MATCHED session the sheet says so: the measurement still leads everywhere, and what is edited here is the logged column beside it. i18n EN/PL/DE." },
  { id: "session-energy-estimate", area: "Core", status: "shipped", title: "Estimated calories for every session + the connect-a-device prompt", detail: "Athletes with no watch had NOTHING on a sport log beyond a duration. packages/core/src/energy.ts now models the session's energy cost with the standard MET method (Compendium of Physical Activities 2011): kcal = MET x 3.5 x bodyweight / 200 x minutes, where the MET comes from the best input the session actually carries — a measured pace first (ACSM running/walking equations; Compendium speed bands for cycling, and per-100m / per-500m pace bands for swimming and rowing), then the sport catalog's own MET (per sport, falling back to its category), then RPE, then bare duration. Two honesty rules, in the done-receipt tradition: NO BODYWEIGHT, NO NUMBER (the formula is linear in mass, so a 'typical 70 kg athlete' would be inventing the answer — it returns null and the UI asks for a bodyweight instead), and the `basis` is carried, not hidden, so a weak estimate can be labelled as one. Every estimated figure renders with a leading '~' on both clients and never appears as a measurement. ONE MET MODEL, not two: engines/load.ts already carried a cruder RPE-only sessionEnergyKcal for the nutrition fuel target, so it now delegates to this one and its own blockMet was deleted. The two callers keep different HONESTY BUDGETS on purpose — the nutrition target must produce some number and so keeps its documented 75 kg default, while the Wrapped must not show a stranger's calories as the athlete's and so gets null. Paired with a CONNECT-A-DEVICE panel in the Wrapped, shown only when the athlete has no active connection AND the session is genuinely thin (no pace, no RPE, no usable estimate — `sparse`): it names exactly what a watch/strap/Apple Health would add (heart rate & zones, measured calories, precise moving time, recovery & sleep) and routes to Connections. hasActiveConnection() in connectors.ts is shared so both clients decide identically when the prompt is honest." },
  { id: "effort-model", area: "AI", status: "shipped", title: "Effort model — the reported feeling becomes training load", detail: "The ML foundation under session-feel, built on the idioms PR #267 established. THE PROBLEM: two athletes run 10 km in 40 minutes; one floats home, the other is destroyed. The log records the same session, so fatigue, ACWR, readiness and the prescription treated them as the same athlete doing the same work. engines/effort.ts closes that gap. (1) OBJECTIVE EFFORT — objectiveSessionRpe() is the minutes-weighted mean RPE the log implies, derived as sessionLoad / sessionMinutes (sessionMinutes newly exported from load.ts) so it is identical BY CONSTRUCTION to the load engine rather than a second opinion about the same quantity. (2) THE RESIDUAL — reported minus objective, per rated session, is the signal: a consistently positive residual means this athlete pays more for the same work. (3) THE LEARNED BIAS — deriveEffortModel() shrinks the mean residual toward the population prior (0) by a prior weight of 6 and clamps it to +/-2.5 RPE, exactly the shrinkage idiom personal.ts uses for the ACWR spike onset and datanet.ts for cohort norms: one rated session barely moves it, twenty move it a long way, no history pushes it somewhere absurd. (4) IT SCORES ITSELF LEAVE-ONE-OUT — for each sample the bias is refitted on every OTHER sample and used to predict the held-out one, then compared against the unpersonalised engine (baselineMae). An in-sample fit would beat the baseline whether or not the athlete has a real bias, so the model can and does report no improvement for an athlete who has none. (5) FITNESS TREND — effortTrend() regresses the residual against time, holding the objective work fixed and watching only what the athlete says it cost: a falling residual is the one honest fitness read a self-report can give. Null under 6 rated sessions or a 14-day span, because a slope through four points in one week is a line through noise. WIRED, NOT JUST AVAILABLE: toTrainingLog() gained a feelRpe hook and personalTrainingLog() threads the athlete's own answer through it, replacing the CONSTANTS every intensity used to fall back to (7 for a lift, 6 for cardio, 8 for conditioning) — all 17 call sites across both apps now use it, so Today, the AI coach, the squad endpoint and the prescription can't disagree about the same athlete. An RPE entered per block still wins: it is more specific than a whole-session rating. MEASURED EFFECTS, pinned in tests rather than assumed: injury risk moves strongly (28 days of the identical squat session read ACWR 1.43 / risk 36 when the last week is reported all-out vs ACWR 0.40 / risk 23 when it is reported easy — ACWR is an sRPE ratio, so a reported effort is literally its input); readiness moves only while the athlete's raw load sits under the fatigue engine's 40-unit normalisation floor, because muscle fatigue is normalised against the athlete's own max and a uniform shift otherwise cancels exactly — both regimes are pinned so nobody builds a 'your feeling sets your readiness' claim the engine never made. An earlier cut also back-filled UNRATED sessions with the model's prediction; that was reverted, because substituting one guess for another silently moved every existing athlete's numbers with no new information behind it. The prediction's honest use is forward (how hard will this session feel), not rewriting history. Four formulas registered in ENGINE_FORMULAS under a new 'effort' group, so the admin Engine Room's formula sheet renders the real math, drift-guarded against the live constants. CONSOLE SURFACE: the Engine Room gained an 'Effort model' card beside the personal-ACWR one, fed by GET /api/admin/engine (which now computes the model server-side, since it needs the RAW sessions the TrainingLog has already collapsed away — athleteInputs returns them alongside the log). It shows the learned bias on a -2.5..+2.5 scale with the prior marked, the rated-session count, and — the part that matters — the LEAVE-ONE-OUT error beside the unpersonalised engine's, with a verdict line that can and does say 'no better than the engine, this athlete reports roughly what their log implies'. An in-sample number would always have flattered the model, so the console would have shown a win for every athlete including the ones with nothing to personalise. Plus the fitness trend, or an explicit note of how many more rated sessions it needs. 24 unit tests." },
  { id: "session-feel", area: "Core", status: "shipped", title: "\"How did that feel?\" — post-workout effort + fatigue (training-load foundation)", detail: "The log alone cannot tell two athletes apart. User A runs 10 km in 40 minutes and floats home; user B runs the identical 10 km in 40 minutes and is destroyed. Identical rows, identical engine input, and prescribing the same next session for both is how you break the second one. The Wrapped now asks, once, right after the workout: how HARD it felt (1..5, easy -> all out) and how SPENT you are now (1..5, fresh -> wrecked). packages/core/src/session-feel.ts is the shared model — FEELS/FATIGUES (labels, emoji, tone), the 1..5 -> 1..10 session-RPE mapping, feltSessionLoad() = sRPE x minutes (Foster's internal training load, the field-standard measure), loadBand(), and the ML-facing pieces: feelSamples() reduces history to labelled {minutes, feel, fatigue, load, distance, tonnage} rows, loadBaseline() takes the athlete's own 28-day mean (null under three rated sessions, so 'relative effort' is never computed from noise) and relativeEffort() reports this session against that personal baseline — always the athlete vs themselves, never a cohort. Distinct from the two self-reports already in core: readiness-feeling is asked BEFORE training, notes MOOD is an optional private reflection; this is the only one that feeds training load. ASKED AT THE RIGHT MOMENT, on both clients: the prompt ships as ONE shared component (feel-prompt.tsx) with TWO homes, because the question has two natural moments. Primary is the FINISH screen — straight after the last set, while the athlete is still holding the phone and the answer is most accurate; a first pass put it only on the Wrapped, which an athlete reaches by re-opening a logged session later, so most sessions would never have been rated at all. Secondary is the Wrapped panel, which catches a session that was opened later and never answered. Both seed from the stored value, so nobody is asked twice, and either entry point fills the same columns. Taps save optimistically, one field at a time, via PATCH /api/sessions/[id] -> sanitizeFeelLevel; the read-out shows the session load, its band, and the personal +/-% once there is a baseline. Schema adds Session.feel + Session.fatigue (Int?), owner-only like note/mood/tags. LIVE: reference/sql-session-feel.sql has been run in the Supabase SQL Editor, so Session.feel + Session.fatigue exist and the prompt now persists. Reads had to be widened to match: every SERVER-side path built its LoggedSession with an explicit field list that dropped feel, so the engines there would have fallen back to the old constants while the clients (which receive the full row from GET /api/sessions) used the real answer — the AI coach and the athlete state would have been reasoning about a different athlete than the app displayed. api/ai-coach and lib/athlete-state now carry it. The COACH squad endpoint carries it too but as ENGINE INPUT ONLY: that response serialises per-athlete aggregates and a session count, never session objects, so a coach's readiness/ACWR/risk reflects what their athlete reported without the per-session answer leaving the server. The one endpoint that does return raw rows to a coach (coach/links/[id]/sessions) keeps its explicit select, which excludes feel/fatigue alongside the private note."},
  { id: "exercise-picker", area: "Core", status: "shipped", title: "Searchable exercise picker (grouped by muscle/pattern)", detail: "Adding an exercise in the logger + routine builder now uses the same field-styled trigger → searchable modal as the 'Log a sport session' sport picker, replacing the old wall of chips. exercisesByCategory (movements.ts) groups a catalog by movement pattern (Squat/Hinge/Push/Pull/Conditioning, with free-typed/library lifts in Other), sorted A–Z, empty groups dropped, headers localized (exercise.cat.*). The modal also lists recent lifts (logger), sports (olympicSportsByCategory → cardio) and a '+ custom name' entry. Web (workout-blocks.tsx ExercisePicker) + mobile (workout.tsx, builder.tsx, aurora/builder.tsx). Pure categorization unit-tested." },

  { id: "future-self", area: "Core", status: "shipped", title: "Future Self Simulator", detail: "future-self.ts: projects the athlete forward from current behavior — a lift's e1RM trajectory or bodyweight path (least-squares fit), a goal ETA, and an honest goal-by-date probability (normal CDF over fit uncertainty). Consistency bends the curve (adherence factor 0.5..1.2) so the simulator shows the cost of slipping and the reward of showing up. Pure + unit-tested. The motivational hook on the Fitness GPS home." },
  { id: "volume-landmarks", area: "Core", status: "shipped", title: "Volume landmarks (MV / MEV / MAV / MRV)", detail: "Renaissance-Periodization-style weekly set-volume landmarks per muscle group: MV (maintenance), MEV (minimum effective), MAV (maximum adaptive range), MRV (maximum recoverable). landmarks.ts: VOLUME_LANDMARKS holds starting per-muscle ranges mapped onto HYBRID's seven muscle groups; weeklySetsByMuscle counts this week's (last 7 days) performed WORKING sets per muscle (warm-ups/cool-downs already excluded by the session engine, empty sets skipped, each set counting toward every muscle the movement trains via MOVEMENTS); classifyVolume buckets a count into under / productive / peak / overreaching; muscleVolumeStatus + volumeStatus report where each muscle sits with its landmark numbers; and volumeAdvice gives the PRESCRIPTION — only the actionable muscles, ADD sets when below MEV (toward the MAV low end) or REDUCE/deload when at/over MRV, most-urgent first (over-MRV before under-MEV). Pure + 9 unit tests. SURFACED on a new Volume screen (analyze group, athlete persona) on BOTH clients: web components/volume.tsx + mobile app/volume.tsx — a per-muscle bar with the MEV/MAV-band/MRV markers + zone colour, and a 'this week — adjust volume' advice list; honest empty state until working sets are logged. Nav entry localized EN/PL/DE (screen body copy is English for v1, matching the web analytics screens). SCOPE delivered: tracking + an advisory prescription layer. NEXT: fractional secondary-muscle weighting, per-athlete adaptive landmarks (from fatigue/recovery data), and auto-applying the nudge inside the prescribed next session (deeper progression-engine integration); volume trends over time land in the training-analytics-hub." },
  { id: "volume-screen-redesign", area: "Core", status: "shipped", title: "Volume screen — hero redesign", detail: "The Volume screen rebuilt on both clients (apps/web/components/aurora/volume.tsx + apps/mobile/components/aurora/volume.tsx) off a new shared view model, packages/core/src/volume-view.ts (railX / railGeometry / volumeSummary / sortByUrgency / setsLabel / deltaLabel, 14 unit tests). What changed and why: (1) HERO — the screen now opens on one verdict, `4/7 muscles in their productive range`, drawn as a seven-column week-shape you read before you read a word; tapping a column swaps the verdict line for that muscle's count and zone. The old opener was a paragraph of acronyms. (2) NORMALISED RAIL — every muscle's landmarks are different (Triceps cap at 18 sets, Back at 22), so an absolute-scale bar put every band at a different x and the stack was unreadable. railX maps each muscle against its OWN landmarks onto fixed anchors (MEV .34, MAV-high .72, MRV .86, then an overshoot tail saturating at 1.5x MRV), so the rows stack into one comparable picture; the absolute count is printed alongside. (3) NOTCHED TICKS — MEV/MRV are cut out of the rail in the card colour rather than drawn as coloured lines, so they stay legible under a full fill. (4) The per-row legend loses its SWATCHES but keeps its LABELS. Two earlier cuts were wrong and are recorded here so they are not repeated: dropping the whole legend cost the athlete the values themselves, and re-adding bare numbers under a single named header row left no way to tell which number was which once you had scrolled past it. What ships: every row carries its own named scale (railScale in volume-view.ts) — MEV 8 / MAV 12–18 / MRV 20 — with each value POSITIONED under the mark it belongs to (MEV and MRV directly beneath their rail notches, MAV under the middle of the band) rather than left-packed, and with the label as the quiet part (9px ash) against the number a size up in chalk. No coloured square in front of any label, per the no-marker-before-a-label rule. Because every row now names its own values, the shared legend rail above the list is gone. The row header carries the count AND the zone word ('24 sets — over MRV'), and the track itself is a key: the MAV band lit, the territory past MRV tinted, so the zones read even on an empty rail. Expanding a row therefore adds only what the scale does not already say — the MV floor and the prescription sentence. (5) PRESCRIPTION — the three verbatim-identical 'Over your recoverable ceiling…' sentences collapse into Ease off / Add volume chip rows (muscle + signed delta), with the reason stated once. (6) Rows sort by urgency (over the ceiling, then under the minimum, then the rest). (7) TYPE — the display face carries names and headings; mono is reserved for numbers and eyebrow labels, retiring the all-monospace terminal look. (8) PROGRESSIVE DISCLOSURE — the MV floor and the per-muscle advice live behind a row tap (the scale stays on the surface); the acronym glossary behind a 'What the bands mean' disclosure. (9) The separate 5x7 landmark-editor grid is retired: Edit landmarks opens every row in place and the values become fields where they are already shown. (10) SPOTLIGHT — the row's scale is a left-aligned three-column table (values line up down the whole list rather than floating at three indents, which read as chaos on a phone) and every cell is a CONTROL: tapping MEV / MAV / MRV scrims everything outside that band on EVERY row at once, caliper edges frame the lit slice so it reads even when empty, the tapped label lights across the list, and the definition appears under the row you touched (mobile fires a selection haptic). Tapping MRV instantly shows which muscles poke into the ceiling zone; tapping MAV shows who has reached the productive band. bandRegion in volume-view.ts, shared by both clients. New copy localized EN/PL/DE." },
  { id: "volume-provenance-redesign", area: "Core", status: "shipped", title: "\"Whose numbers are these?\" — the provenance card rebuilt", detail: "The SourceCard on both Volume screens (apps/web/components/aurora/volume.tsx + apps/mobile/components/aurora/volume.tsx) was doing seven jobs at one type size: provenance, profile completeness, fitness level, the personalization factors, the adaptive toggle, the ceiling replay and the profile form — six explanatory paragraphs stacked in identical ash body copy with nothing to look at. Rebuilt around three questions, each at a different weight. (1) THE PROVENANCE LADDER. `athleteLandmarks` layers population → profile → observed → manual and returns `layers` + `source`; that is a four-rung climb, and the card was reducing it to one caption ('Learned from your training') set on the SAME row as the title, where the longer of the two forced the title to wrap. It is now drawn as what it is: four rungs, each with a spine segment lit when that layer contributed, at full strength on the layer that actually named the numbers, and carrying the confidence THAT layer can claim (the profile rung shows profileConfidence, the observed rung observedConfidence). A column that stops at rung one says 'textbook averages' before a word is read; an unlit rung is also the thing to do next. Rungs are radio controls — tap one to read what that layer did, which is where the four sourceWhy sentences now live instead of only ever showing one. New shared view model `provenanceLadder` / `rungMeta` / `LANDMARK_LAYERS` in volume-view.ts so the rungs, their order and their confidences cannot drift between clients (5 unit tests). (2) ONE THING TO DO NEXT. The completeness meter kept its weighted score but the 'Next: Training age' line, previously inert text, is now a CONTROL: tapping it opens the About-you form in place (its own local state, so it no longer has to borrow the screen-level `editing` flag and expand every landmark field on the muscle rows above). The bar thins to 3px — it is a reading, not a subject. A complete profile gets a sentence saying so rather than an empty rail. (3) SHOW THE WORKING. Level-from-your-lifts, the factors, the adaptive toggle and the ceiling replay fold behind one disclosure, matching the 'What the bands mean' idiom already on the screen. FOUR HONESTY BUGS FIXED ON THE WAY: the factor rows rendered with NO heading directly under 'Your level, from your lifts', so 'Sleep 3/5 −6%' read as evidence of how strong you are — they now carry their own head ('What moved your bands') and each row names WHICH END of the band it moved (`affects`, which the engine has always returned and the UI threw away — factorAffectsKey); the orphan '25% confidence' line is gone, its number now sitting on the ladder rung it belongs to; the adaptive toggle's ON label was 'Done', which is not a state of 'Learn from my training' — it reads common.on/common.off; and the replay block no longer prints a second 'not enough evidence yet' paragraph directly under the first, staying silent until a week has actually been tested. New copy localized EN/PL/DE. Core tests + web/mobile typecheck green." },

  { id: "ui-templates", area: "Core", status: "shipped", title: "Aurora — the single UI template (Classic removed)", detail: "AURORA IS NOW THE ONE AND ONLY UI look — the old industrial 'classic' template was REMOVED: there is no skin switch, no per-device template preference, and no classic screen variants are rendered. @hybrid/core theme/templates.ts collapsed to a single-entry registry: TemplateName is just 'aurora', resolveTemplate() always returns 'aurora' (a stored 'classic' is coerced), isTemplateName only accepts 'aurora'; the Template switcher was removed from web + mobile Settings. The clients' useTemplate() hooks are kept (always 'aurora') so the residual `template === 'aurora'` style ternaries compile and always pick the Aurora value — the dead classic component files have now been REMOVED (web: ~34 classic screen/helper files deleted, SessionDetail extracted to components/session-detail.tsx, the classic ⌘K command menu + header dropped from app-shell; mobile: the inline ClassicX body removed from all ~35 template-switched route files, each now rendering only its Aurora screen). ORIGINAL DESIGN (history): a template layer that re-skinned the app's SCREENS (layout/structure/component shapes) without touching data or brand tokens — distinct from theme/palette.ts (which flips light/dark palettes). AURORA is a soft, rounded look adapted from the uploaded mobile Figma kit (big corner radii, pill buttons/inputs, segmented controls, schedule-first home), built ON the existing HYBRID brand tokens (lime accent, ink surfaces, Archivo) via the shared theme palette so it stays on-brand and theme-aware. The active template is a per-device preference: mobile lib/template.tsx (TemplateProvider + useTemplate over AsyncStorage, mounted in app/_layout.tsx) and web lib/use-template.ts (localStorage hook), both keyed off the SHARED @hybrid/core TEMPLATE_STORAGE_KEY so the two clients can't drift on the key string. SWITCHABLE from Settings on both clients (mobile app/settings.tsx Template card; web account-settings Preferences → Template). MOBILE Aurora slice shipped: Welcome, Login/Register, the stepped Onboarding wizard, and the schedule-first Home (components/aurora/*) — each route renders the Aurora variant when the template is active and the classic screen otherwise, all on the SAME auth/onboarding/engine logic (Supabase auth incl. the onboarding-pending flag, recommendPlan, prescribeSession/computePerformanceState). WEB Aurora slice shipped for AUTH: components/aurora/login.tsx mirrors the rounded Figma login and reuses the identical Supabase flow (OAuth – email – MFA step-up – demo roles) so there's no 2FA regression. ICON SET wired in: the uploaded design-kit line icons (icons1/2/3) are the canonical Aurora glyphs — @hybrid/core theme/icons.ts holds the name union (AuroraIconName) + 72×72 SVG path data (single source of truth); web renders them as inline <svg stroke=currentColor> (components/aurora/icons.tsx) and mobile renders the matching transparent PNGs (apps/mobile/assets/icons) recoloured via <Image tintColor> (no react-native-svg dep), names kept in lockstep. Used across the Aurora auth fields (mail/lock/eye/user), back buttons, the onboarding selected-choice check, the Home search/bell + Start (play) buttons, and the mobile bottom-nav glyphs (which swap to the line-icon set when Aurora is active). iOS bundle export is green with the assets bundled. GLOBAL SKIN so EVERY screen (not just the hand-built hero flows) picks up the Aurora look without a per-screen rewrite: on mobile the shared lib/ui primitives are template-aware (Card → larger radius, Button → pill) so all screens built on them shift automatically; on web TemplateSync mirrors the active template onto <html data-template> and globals.css [data-template=\"aurora\"] rounds the shared surfaces (liquid-glass cards, inputs, rounded-xl/lg) across the whole app shell. DEDICATED Aurora layouts now also cover mobile Settings (components/aurora/settings.tsx — avatar header + grouped icon list, keeps every control) and the web LANDING (components/landing.tsx, client-gated, uses the icon set). Remaining bespoke Figma layouts are tracked under 'ui-template-aurora-web'. THEME FOLDER: the shared theme is now ONE self-contained, swappable unit (WordPress-theme style) at packages/core/src/theme/ — tokens.ts (brand tokens), palette.ts (light/dark palettes), templates.ts (the Classic⇄Aurora skin switch), icons.ts (the Aurora icon set), an index.ts barrel and a README.md documenting how to re-tint, tweak, or add a whole new skin. The rest of the app keeps importing from the @hybrid/core barrel (no churn). The per-client RENDERERS necessarily stay with each app (apps/mobile/components/aurora/* + lib/theme.tsx; apps/web/components/aurora/* + globals.css) since React Native and Next.js can't share component code. Stale design source was removed in the same pass (the raw Figma export 'hybrid app deisgn/', design-mockups/, and the Aurora design-exploration HTML under reference/) — reference/ SQL + BUILD_BRIEF kept." },
  { id: "ios-privacy-manifest", area: "Mobile", status: "shipped", title: "Apple Privacy Manifest (PrivacyInfo.xcprivacy)", detail: "App Store submission requires a privacy manifest since spring 2024, and any app using a required-reason API must declare it — HYBRID bundles @react-native-async-storage/async-storage (UserDefaults, category CA92.1), so it was a hard upload blocker (ITMS-91053). app.json now declares ios.privacyManifests (Expo generates PrivacyInfo.xcprivacy at prebuild): NSPrivacyTracking=false + empty tracking domains (no ATT SDK), the collected data types (Fitness, Health, Email, Name, UserID, Photos — all Linked, non-Tracking, AppFunctionality purpose), and required-reason API declarations for UserDefaults (CA92.1), FileTimestamp (C617.1), SystemBootTime (35F9.1) and DiskSpace (E174.1) that RN/Expo trigger. Expo modules add their own manifests during prebuild and are merged. VERIFY after `expo prebuild`: confirm the generated aggregated manifest, and confirm the App Store Connect data-collection questionnaire matches (Fitness data, contact info, identifiers, user content)." },
  { id: "legal-pages", area: "Web", status: "shipped", title: "Privacy Policy + Terms of Service (public, linked in-app)", detail: "App Store Connect requires a resolvable privacy-policy URL to submit and Guideline 5.1.1 requires it be reachable in-app; a paid subscription also needs Terms — HYBRID previously had neither (hard blocker). Added public /privacy and /terms pages on the web app (apps/web/app/privacy, /terms; shared contact + effective date in app/legal/legal.ts) covering data collected, use, sharing (incl. coach links + service providers), the access/export/reset/delete rights, retention, security, children, and contact. Linked on BOTH clients: web login (aurora) + Settings danger zone, mobile login (with an 'agree' line) + Settings (Legal section) via a shared LegalLinks component that opens the hosted pages. Localized labels EN/PL/DE (legal.* keys). OPERATOR TODO before submission: set the real legal-entity name, postal address and contact email in app/legal/legal.ts (currently HYBRID + privacy@hybrid.app placeholders) and set the same privacy-policy URL in App Store Connect. Have counsel review the templates for your jurisdiction." },
  { id: "app-store-submission-notes", area: "Mobile", status: "shipped", title: "App Store Connect submission notes", detail: "reference/app-store-submission.md — the operator-facing checklist for submitting the iOS build: the App Privacy data-collection answers kept in sync with app.json's ios.privacyManifests (Health, Fitness, Email, Name, User ID, Photos — all Linked, non-Tracking, App Functionality; no ATT since there's no tracking SDK), export-compliance (usesNonExemptEncryption=false is accurate — TLS + Keychain only), why Sign in with Apple (4.8) doesn't apply (iOS login is email-only), where in-app account deletion lives (5.1.1(v)), the IAP/subscription config + reviewer note, a reviewer demo-account + review-notes template, the metadata/age-rating checklist, and the pre-submit sanity list (apply RLS SQL, set IAP/encryption/rate-limit env). Bracketed [...] values (demo creds, real legal entity/contact, privacy/terms URLs) are the operator's to fill." },
  { id: "api-health-check", area: "Backend", status: "shipped", title: "Health check endpoint (/api/health)", detail: "GET /api/health does a trivial `SELECT 1` DB round-trip and returns 200 { ok:true, db:'up', latencyMs } when reachable, 503 when not — no user auth (exposes nothing), generously per-IP rate-limited (120/min) so it can't hammer the DB. Point an external uptime monitor (e.g. BetterUptime / Pingdom / a Vercel cron) at it so real outages page someone instead of waiting for user complaints." },
  { id: "crash-reporting", area: "Core", status: "planned", title: "Crash reporting + error monitoring (Sentry)", detail: "Neither client currently has a crash reporter, so native crashes and JS errors on real devices are invisible and there's no post-release regression triage. PLAN: add @sentry/react-native (Expo plugin) to mobile and @sentry/nextjs to web, initialized behind the existing feature-flag kill switch, with the root ErrorBoundary (mobile) reporting caught render errors. Scrub PII from events (the analytics layer is already a no-op stub, so nothing leaks there today). NEEDS: a Sentry account + DSN (SENTRY_DSN / EXPO_PUBLIC_SENTRY_DSN) in the env; can't be verified in this sandbox without it." },
  { id: "staging-environment", area: "Core", status: "planned", title: "Staging vs production environment separation", detail: "Today one Supabase project + one Vercel deployment serves web + mobile, dev + prod (apps/mobile/lib/supabase.ts hardcodes the prod project as a fallback), so test writes hit production data and there's no safe place to rehearse a migration — a SOC2 change-management gap. PLAN: stand up a separate staging Supabase project + Vercel preview environment, drive every URL/key purely from per-environment env (no hardcoded prod fallback), and point staging mobile builds at it via EXPO_PUBLIC_* build vars. NEEDS: a second Supabase project + the env wiring; operational, not code." },
  { id: "audit-remediation-2026-07", area: "Core", status: "shipped", title: "iOS production-readiness audit — remediation", detail: "Fixed the release-gating findings from audit/06-ios-production-readiness-audit-2026-07.md (14 commits). SECURITY: closed the RLS policy-logic escalations that the anon key could exploit even with RLS enabled — User UPDATE column-restricted (no self-escalate to ADMIN), CoachLink insert forced to PENDING with client-only activation (no forged-ACTIVE cross-tenant read), org/team/membership writes server-only, CoachInvite claim scoped to own-email, ProcessedWebhookEvent RLS enabled, blanket anon REVOKE (rls-policies.sql + sql-all.sql). Coach GET routes require an ACTIVE link (no reading a non-consented user pre-acceptance). Account export redacts OAuth tokens (+ CI regression test). Entitlement mirror moved to app_metadata. OAuth callback validates `next` (open-redirect), clientIp uses the trusted-proxy hop (no XFF spoof), rate-limiter alarms when unconfigured in prod, coach-invite throttled, hot write routes body-capped. APP STORE: self-serve account deletion (+ complete erasure shared by reset/admin), PrivacyInfo.xcprivacy, /privacy + /terms pages linked in both clients, IAP restore + launch listener + StoreKit price + paywall legal links + Apple manage-subscription. RELIABILITY: fetch timeouts + root ErrorBoundary + password reset, offline-onboarding clobber + workout load-race fixed, one-shot flag/persona/plan-maxes stores reset on auth change, throwing query layer so History shows a real error/retry state, /api/health probe. Bounded coach/squad + datanet queries. NOTE: the RLS/index/cascade SQL must be RUN in the Supabase SQL Editor (sql-all.sql) — it's inert until then (see schema-tenant-isolation-rls)." },
  { id: "mobile-password-reset", area: "Mobile", status: "shipped", title: "Password reset on mobile", detail: "The mobile login's 'Forgot password' was a dead <Text> with no handler (users were locked out on mobile — web already had reset). Now a real control that calls supabase.auth.resetPasswordForEmail(email) with a confirmation notice; requires the email field first. Localized EN/PL/DE (w.account.login.forgot-*)." },
  { id: "mobile-secure-store", area: "Mobile", status: "shipped", title: "Store the auth session in the Keychain (SecureStore)", detail: "The Supabase session (access + long-lived REFRESH token) now persists in the iOS Keychain / Android Keystore via expo-secure-store (~56.0.4), not plaintext AsyncStorage where it was recoverable on a jailbroken device / via an unencrypted backup / forensic image (session theft — audit H-7). apps/mobile/lib/secure-store.ts is a Supabase auth `storage` adapter that (1) CHUNKS the session across Keychain items to stay under SecureStore's ~2KB per-value limit, (2) transparently MIGRATES an existing AsyncStorage session into the Keychain on first read and deletes the plaintext copy — so no one is force-logged-out on upgrade — and (3) falls back to AsyncStorage on the Expo web bundle (where SecureStore is unavailable and the at-rest risk doesn't apply). Wired in apps/mobile/lib/supabase.ts. Mobile typecheck + iOS bundle export green; the native Keychain round-trip itself needs an on-device/EAS build to exercise (can't run in the sandbox)." },
  { id: "schema-migrations-reproducible", area: "Core", status: "blocked", title: "Reproducible Prisma migrations (retire manual-SQL drift)", detail: "DONE in code (audit C-3): prisma/migrations/0_init/migration.sql was regenerated from schema.prisma via `prisma migrate diff --from-empty --to-schema-datamodel` into a COMPLETE 64-table baseline (all tables, enums, 110 indexes, 50 FKs incl. the 47 ON DELETE CASCADE the old 7-table 0_init lacked) — verified byte-identical to a fresh diff. So `prisma migrate deploy` now reproduces the ENTIRE schema on any fresh env (staging / preview / DR), which it couldn't before (the other 56 tables lived only as hand-run reference/*.sql). prisma/MIGRATIONS.md documents the fresh-env flow, the go-forward `migrate dev` workflow, and the two-layer model (Prisma owns the schema; reference/*.sql owns the RLS/grants/policy-indexes). The reference SQL layer (sql-all.sql) stays the source for RLS + security. blockedBy below is the one thing the sandbox can't do: reconcile the EXISTING prod DB (its _prisma_migrations still records the old 0_init).", blockedBy: "Reconcile production per prisma/MIGRATIONS.md (needs live-DB access the sandbox lacks): back up, confirm no drift (`migrate diff --from-url $DIRECT_URL --exit-code`), delete the stale `_prisma_migrations` 0_init row, `prisma migrate resolve --applied 0_init`, verify `migrate status` clean. Then gate CI on a clean migrate status." },
  { id: "swiftui-kit", area: "Core", status: "blocked", title: "Aurora × SwiftUI native kit (Liquid Glass)", detail: "The mobile Aurora kit now renders REAL native SwiftUI on iOS via @expo/ui (56.0.18; newArch/Fabric already enabled, autolinked native module — no config plugin or babel plugin needed since we don't use Icon.select; react-native-worklets stays an optional soft-require so it's not installed). New native layer apps/mobile/components/aurora/swiftui.tsx exposes: GlassSurface (a SwiftUI glassEffect RoundedRectangle that fills its parent and sits BEHIND ordinary RN content, with a translucent RN floor under it so the surface is still visible on iOS < 26 / pre-mount), GlassSegment (SwiftUI Picker + .pickerStyle(.segmented), tinted with the brand lime), GlassButton (content-sized SwiftUI Button with .buttonStyle(.glass/.glassProminent)) and GlassPanel (RN content on a glass backdrop). These are wired into the SHARED kit (apps/mobile/components/aurora/kit.tsx) so screens inherit them with no per-screen change: ACard drops a Liquid Glass surface behind its content (transparent RN base) on iOS, the neutral `soft` APill becomes a glass pill, and ASegment delegates to the native segmented Picker. The native treatment is ALWAYS ON on iOS (the single gate is swiftui.tsx LIQUID_GLASS_SUPPORTED = Platform.OS === 'ios') — the per-device opt-in toggle that originally shipped here was REMOVED by request (Aug 2026): the native look is the product, not a preference. Android falls back to the existing RN Aurora treatment and the web client (Next.js) keeps its CSS Aurora — SwiftUI is iOS-only by construction. The classic Aurora backdrop (AuroraField in kit.tsx) is a soft layered LinearGradient wash (the RN parity of the web .lg-field's blurred blobs) so it reads as a smooth gradient rather than hard-edged discs, and renders in BOTH modes. TOGGLE REMOVED (Aug 2026): the 'Liquid Glass (iOS)' Settings switch, its LiquidGlassProvider (lib/liquid-glass.tsx), the LIQUID_GLASS_STORAGE_KEY persistence and the w.account.settings.liquid-glass* strings were all deleted — a stale AsyncStorage value on old installs is simply never read. Composition rule honoured: SwiftUI subtrees live entirely inside a <Host>; RN children are never nested in a Host (glass is a backdrop, not a wrapper). Mobile typecheck + iOS export bundle are green. SOLID OPT-OUT (Aug 2026): ACard grew a `solid` prop that skips the glass surface even on iOS — the Performance surface (performance.tsx + its inline volume.tsx/trends.tsx) and the Nutrition tab (nutrition.tsx) now use it on every card, because the translucent material washed out their data-dense charts/stat columns (and left Nutrition half-glass, half-solid); solid ink2 there matches Today's dominant card treatment and the web Performance screen. WEB↔MOBILE PARITY: the web already simulates Liquid Glass via CSS (.liquid-glass) and mobile already had a blur-based GlassCard (lib/ui.tsx); this adds the TRUE native material on iOS only. GLASS AS A BEHAVIOUR, NOT ONLY A MATERIAL (Aug 2026): everything above uses glassEffect as a surface — one pane at a time, a prettier background. The Today hub dock (today-hub-floating-pills) is the first place that uses what the material actually DOES: swiftui.tsx GlassPillRow is a GlassEffectContainer whose capsules share a Namespace and each carry a glassEffectId, so touching capsules FUSE into one lozenge and a frame change makes the glass FLOW between shapes. @expo/ui 56 exposes the pieces that make this possible — GlassEffectContainer, Namespace and the glassEffectId/animation modifiers — which the screen-transitions-wave3 notes had recorded as missing; they are not missing, and the pattern is now proven at the JS/bundle level. Two rules learned the hard way and honoured here: the animating view must PERSIST (a view that inserts or removes has no source and destination to morph between, which is why the old nav's conditional lens snapped), and every animatable value must arrive as a plain target number the native side springs to ITSELF (driving it frame-by-frame from JS re-samples the backdrop every frame and janks). blockedBy below.", blockedBy: "Native SwiftUI rendering can't be built/verified in this sandbox (no Xcode/simulator, Supabase+native build host blocked) — it needs an EAS dev/preview build (see mobile-preview) on an iOS 26 device to confirm the Liquid Glass surfaces, segmented Picker and glass buttons render and lay out correctly, then to tune tint/opacity on-device. That now includes the Today hub dock's GlassPillRow: on device, confirm the three capsules fuse at gap 0 and separate on arrival, that the selected pill's glass STRETCHES into its word rather than snapping, that the lime glass tint reads as a tinted pane (not a coloured film), and that the RN glyphs sit dead-centre on their capsules through the whole morph — the one thing two matched springs cannot prove without eyes on it. Until then only typecheck + JS bundle are verified." },
  { id: "liquid-glass-segments", area: "Core", status: "shipped", title: "Liquid Glass segmented controls (Today hub + date filter)", detail: "The two in-screen segmented controls — the Today hub switcher (the three HUB_GLYPHS marks) and the This-week date filter (Week / 7 days / 30 days / YTD / Month) — now behave like the iOS 26 SYSTEM control, per the user-approved interactive preview (artifact, 'rest pill, glass on touch'): AT REST the selection is a quiet near-solid NEUTRAL pill (the chartreuse fill is retired from these two controls — the user chose system-neutral over the brand tint when offered both); ON TOUCH the pill inflates past the track's edges into a clear glass lens with a hairline rim, DRAGGING scrubs the lens across segments (select on release, selection haptic on mobile), and a TAP sends the lens over glassy IN FLIGHT, condensing back into the pill on landing — SwiftUI's default spring (response 0.55 / dampingFraction 0.75 ≈ stiffness 130 / damping 17). ONE shared primitive per client: apps/mobile/components/aurora/liquid-seg.tsx (PanResponder scrub that yields to vertical scroll + native-driver Animated springs; honours useReducedMotion) and apps/web/components/aurora/liquid-seg.tsx (pointer capture + rAF spring physics with gel stretch; honours prefers-reduced-motion; CSS-only initial position so SSR paints the pill in place), consumed by aurora/today-tabs.tsx and aurora/week-verdict.tsx on BOTH clients. The date filter's Month segment INTERCEPTS selection (opens its picker sheet; the pill springs home and only lands on Month once a month is in force) — same contract on both clients. THE LENS MATERIAL: on iOS the inflated lens is REAL native SwiftUI glassEffect via the existing GlassSurface — always on, no user toggle (see swiftui-kit); on Android and web a translucent simulated lens carries the identical interaction — on web by construction, since a browser has no system material. Verified: core tests + both typechecks + web build + iOS export bundle. The native-glass lens itself shares swiftui-kit's blocker: confirm on an iOS 26 device with the next TestFlight build." },

  { id: "aurora-spectrum-palette", area: "Core", status: "shipped", title: "Aurora Spectrum — palette refresh (chartreuse/teal/sand/terracotta)", detail: "The dark Aurora theme was retinted from a single flat acid-lime to the brand 'Spectrum' coolors palette, applied ONLY as text/accents/ornaments — the dark surfaces (ink #0c0d0c / ink2 / card / line) are unchanged. The five brand accent tokens now hold: lime → CHARTREUSE #c7ef00 (primary action / 'go'), blue → TEAL #3c787e (conditioning / info), amber → SAND #d0cd94 (sport / caution), red → TERRACOTTA #d56f3e (alert / injury / streak); violet #c9a9f0 is kept for the premium/coach slot (the palette has no purple). Source of truth: packages/core/src/theme/tokens.ts (colors) + palette.ts (THEMES.dark.accentText — teal/terracotta are lifted to #6cb6bd / #e58a5c so they clear WCAG AA as TEXT on the card; chartreuse/sand pass verbatim, guarded by palette.test.ts), mirrored in apps/web/app/globals.css (@theme --color-*, the dark --*-text vars, and every hardcoded lime glow rgba 196,240,53 → chartreuse 199,239,0). SPECTRUM SECTION-CODING (the signature): the Today daily-flow sections are colour-coded across the palette so the screen reads as a guided gradient — Train=chartreuse, Feel=teal, Plan=sand, Connect=terracotta — via a shared decorative map @hybrid/core semantic.ts SECTION_COLOR (DailySection → AccentKey, kept apart from the state-colour ROLE_COLOR so meaning can't drift), consumed by the section kickers on BOTH clients (apps/web/components/aurora/today.tsx + apps/mobile/components/aurora/home.tsx); the streak chip wears the warm terracotta accent (pairs with the 🔥) while chartreuse stays reserved for the primary action. The whole app picks up the brighter chartreuse primary for free (buttons, rings, brand wordmark, focus ring, nav active state) since it flows through the lime token. Hardcoded brand-hex literals across shipped surfaces were updated in the same pass for consistency (plans.ts, story-styles.ts, engines/periodization.ts phase colours; web workout-share.ts, landing, nutrition, onboarding, calendar, today-quick, invite/not-found/error/global-error; mobile calendar). JAPANDI (light) is untouched — its accentText stays the warm darkened set and the clay accent fill is preserved (the light theme only overrides --color-lime → clay; its blue/amber/red FILLS inherit the new teal/sand/terracotta, which suit the oat-paper palette). WEB↔MOBILE PARITY: identical token values + the same SECTION_COLOR map drive both clients. Five standalone explorations were rendered in reference/aurora-palette-explorations.html and 'Aurora Spectrum' was chosen. Core tests + both typechecks green. REFRESH (Jul 2026): (1) the primary chartreuse was retuned #c7ef00 → #c6f84f (rgb 198,248,79) — a softer, less-acid green — across every source (tokens.ts, palette.ts dark accent-text, web globals.css --color-lime/--lime-text + the glass-glow rgb, mobile ACCENTS via colors.lime, and the hardcoded literals in web error/not-found/global-error/invite/workout-share + core periodization phase colours + plans.ts + story-styles glow). (2) the LIGHT theme is WARM JAPANDI again, matching reference/today-cockpit-design-concepts/04-japandi.html (the interim cool 'MIST' grey is retired): oat-paper surfaces (ink #efe9df → warm off-white card #fcfaf4, chalk #3a352c, ash #6d665a) with a SOFT WARM hairline (line #e2d9c9) — never pure white, never a hard black box. The brand CHARTREUSE stays the accent (mossy dark-green #47630a as text, bright #c6f84f as fill with dark on-accent text); the display face stays Archivo sans (no clay-accent / no Fraunces serif — those japandi-identity/japandi-serif notes are superseded). blue/amber/red accent-text keep the darkened Spectrum hues. Mirrored in palette.ts THEMES.light + web globals.css [data-theme=light] + mobile paletteFor. WCAG AA guarded by palette.test.ts (677 green). BORDER FIX (the 'black borders are awful' report): web lib/ui.tsx `LINE` was a RAW dark hex (colors.line) used for inline borders, so it painted near-black hairlines on the light Japandi paper — a hard contrast break. LINE is now the themed `var(--color-line)` (soft warm in light, subtle in dark); a new `LINE_HEX` keeps the raw hex for the recharts/SVG spots where CSS var() can't resolve (all ~27 chart stroke/fill call-sites repointed). Mobile already used the themed palette line, so it inherited the warm hairline for free." },

  { id: "japandi-clay-sage", area: "Core", status: "shipped", title: "Japandi light theme — Clay & Sage on Oat", detail: "The warm light theme was redesigned off the acid-chartreuse-on-oat look (harsh: white-on-lime buttons measured 1.34:1 — a WCAG fail — and the bright lime glared on paper while page #efe9df and card #fcfaf4 sat at almost the same value, so nothing floated). NEW PALETTE 'Clay & Sage on Oat': an OAT surface RAMP with real steps so cards lift — ground #eae3d4 → raised #f2ecdf → near-white card #f9f5ec, soft warm hairline #e0d7c6. The PRIMARY action is a muted CLAY #a4543a carrying a warm paper ink #faf6ef (4.99:1); the SECONDARY is a calm SAGE #5f6d4b on the blue/conditioning channel. Chartreuse survives ONLY as small accent-TEXT (mossy clay #8f4a30 on the primary channel, sage #4f5c3a on the secondary), never as a full fill. ARCHITECTURE: added per-theme `accent` (action fill) + `onAccent` (ink ON the fill) to ThemePalette (packages/core/src/theme/palette.ts), so the light theme stops borrowing the FIXED dark-theme chartreuse fill from tokens.ts — dark keeps chartreuse + #0c0d0c ink, light gets clay + paper. palette.test.ts now GUARDS onAccent-on-accent ≥ AA for both themes (the exact pairing the old theme broke). Mirrored across all three surfaces per the web↔mobile parity rule: web globals.css [data-theme=light] (--color-lime→clay, --color-blue→sage, --on-accent→paper, --accent-text/--lime-text→clay-text, --blue-text→sage-text, glass-glow rgb→clay); mobile lib/theme.tsx paletteFor (the accent FILLS now flip per theme — lime→accent, blue→sage on light — and onAccent comes from the theme) + the shared lib/ui.tsx Button/Chip (defaults resolve the primary fill through the palette). ON-ACCENT TEXT FIX: 28 web bespoke buttons used `color: C(\"ink\")` as their on-fill text — an idiom that only reads in dark (near-black on lime); repointed to `var(--on-accent)` (identical in dark, correct paper on clay in light). Core tests (692) + web build + both typechecks green. This SUPERSEDES the aurora-spectrum-palette note claiming the light theme keeps chartreuse as fill. MOBILE parity COMPLETE: the bespoke Aurora screens alias the theme palette as `C` (`const C = useTheme().palette`), so their `C.lime`/`C.blue` FILLS flip to clay/sage automatically once paletteFor maps the accent fills per theme — no per-screen fill sweep was needed (the earlier '~76 raw fills' estimate mistook the palette alias for the fixed brand constant). Two follow-ons landed in the same effort: (1) `txt()` now recognizes the theme's OWN fill values (palette.lime→clay / palette.blue→sage), not just the fixed brand constants, so the ~151 accent-as-TEXT sites resolve to the clay/sage text tones in light instead of falling through to the raw fill hex; (2) ~30 direct `color: C.<accent>` accent-as-text sites across ~10 themed screens (red error messages, amber rating stars, the percent-program load-table numbers + section Band labels) were wrapped in `txt()` so they clear AA on the Oat card — red errors were ~2.6:1 and amber stars ~1.3:1 on paper before. Share cards (lib/share.tsx) intentionally keep the FIXED dark brand (`C` = colors) since a shared image is not theme-dependent. Mobile typecheck green. SETTINGS/NAV FOLLOW-UPS: (a) the decorative per-cluster section-header dots were removed from the mobile springboard menu (web app-shell) + the mobile More tab — the ash label + count already name each cluster; (b) the Appearance theme-picker swatches now preview the real palettes (Aurora ink/chartreuse/ash, Japandi oat/clay/sage) instead of lime; (c) the Settings profile card's leftover lime is themed — the completeness ring (web used a fixed LIME_HEX SVG stroke → now var(--color-lime)=clay), the avatar gradient (hardcoded #9bd400 → the sage secondary), and the Edit-profile chip's lime tint → clay; (d) a new theme-aware `gold` palette token (dark #e6c34e / light #b58a24, decorative so not AA-guarded) gives coach ★ ratings a real Pantone-gold instead of the washed-out sand `amber`, wired across every star site on both clients; (e) the middot ` – ` separators in the Settings row subtitles + profile completeness line now render through the shared MetaLine hairline (matching the rest of the app)." },
  { id: "kyoto-hour-light-theme", area: "Core", status: "shipped", title: "Kyoto Hour — light theme redesign (washi / sumi / pine / vermilion)", detail: "The light theme was redesigned from 'Clay & Sage on Oat' to KYOTO HOUR, chosen from a 9-concept exploration (design/japandi-light-05…13-*.html; the winner is design/japandi-light-10-kyoto-hour.html). DIAGNOSIS of the old theme: the oat ground #eae3d4 was a MIDTONE, so the surface ramp had no real light in it — cards couldn't float and the brick-clay action #a4543a read as mud sitting in shadow ('cheap and plain… depressing'). NEW PALETTE: a lifted WASHI ramp — ground #f6f3ea → raised #efebdf → near-white card #fcfaf3, hairline #e6e1d2 — with sumi ink text (chalk #2b2a26, ash #6f6b5e), a deep PINE primary action #44584c carrying an ivory ink #f2f5ef (6.95:1), the SAGE #5f6d4b secondary kept on the blue/conditioning channel, and the `red` accent-text channel retuned to the hanko VERMILION #a3442f. accentText: lime→pine-text #3c4f43 (8.41:1), blue→sage-text #4f5c3a, violet/amber unchanged, red→vermilion — every pairing AA-guarded by palette.test.ts (chalk/ash on card AND ground, onAccent on accent). Mirrored across all three sources per the parity rule: core palette.ts THEMES.light, web globals.css [data-theme=light] (surfaces, --color-lime→pine, accent/on-accent/accent-text vars, --glass-glow-rgb→pine 68,88,76, the ambient .lg-field washes retinted to washi+pine #e7e0cc/#d9ddd0/#e3dcc8), and mobile (palette flows from core; the AuroraField light washes retinted to match). DISPLAY FACE: light-theme hero headings now use SHIPPORI MINCHO, a Japanese book serif — web --font-heading swaps to it under [data-theme=light] (Fraunces dropped from the font import; weights 500–800), and mobile serifIf() now returns the ShipporiMincho_500/600/700/800 cuts for the light scheme (F.serif* remapped, @expo-google-fonts/fraunces → @expo-google-fonts/shippori-mincho, loaded in _layout.tsx); Aurora (dark) keeps Archivo everywhere. THE HANKO: a small vermilion seal (力, 24px rounded square, rotated −3°, decorative/aria-hidden) is stamped beside the Today masthead headline — only on the true 'Today', never on scrubbed days, light theme only — web .hanko-seal in globals.css + today.tsx, mobile home.tsx at parity. NAMING: the theme picker label is now 'Kyoto Hour' (was 'Japandi') with real-palette preview swatches (washi/pine/vermilion) on both Preferences screens; the mobile Preferences summary line also dropped a stray middot for the spaced en dash per the separator rule. SUPERSEDES the palette/typography notes in japandi-clay-sage (its architecture — per-theme accent/onAccent, txt() routing, on-accent text fixes — all still stands and now carries pine instead of clay). REFINEMENT (post-live review, 'plain and basic' report): (1) the first cut shipped light ink2 #efebdf DARKER than the ground — an inverted ramp that sank every ACard/ink2 surface into the page; corrected to #faf7ef so the washi ramp rises ground → raised → card. (2) ~45 web aurora card sites hardcoded the DARK-theme shadow (0 6px 22px -12px rgba(0,0,0,.55)) — a black band under washi cards, visibly TRUNCATED at the horizontal-rail scroll clips (the 'cut gradient' report); all swept to a new themed --shadow-card var (dark keeps the black bloom, light gets a soft warm sumi-wash 0 14px 30px -18px rgba(88,74,52,.38)), the coach-rail + feed sliders got internal padding pulled back by negative margins so shadows render inside the clip, and the mobile coach/feed rail cards gained the scheme-aware twin (warm #584934 on light / black on dark). (3) the feed-preview post cards rendered EVERYTHING in one mono voice ('cannot distinguish anything'); the lead (workout name / 'PR') is now the card TITLE in the display face (Mincho on light) with prose sans and mono reserved for the fact line + counts, and the coach-rail coach names + section headers moved onto the display face too — three voices per card, both clients. (4) the readiness faces ('primary school') were redrawn as a crafted kaomoji pictogram set — one consistent 2px round-capped stroke, with the EYES carrying the expression (delight = happy ⌒ arcs, calm/flat = level strokes, wrecked = outward-drooping slants) over the mood mouth; web readiness-face.tsx SVG paths + the mobile plain-View twin (clipped-ring arcs, no new deps), verified by headless-Chromium render. (5) FULL-BLEED RAILS: the Explore coach/community sliders clipped at the CONTENT COLUMN (the web app-shell <main> pads 16px with overflow-x:clip; the mobile AuroraScreen pads 16dp), so cards + shadows vanished visibly before the physical screen edge. The shell now publishes --page-pad-x and both rails take an opt-in `bleed` prop — negative margins the width of the page gutter with matching internal padding, so resting cards align with the column but scroll + clip at the true screen edge; Explore passes bleed on both clients, while the Sheet-hosted Today rail stays column-bound by design. The web rails also set scroll-padding to the same gutter — mandatory scroll-snap ignores the scroller's own padding, so without it the browser snapped the FIRST card to the scrollport start, glued to the bezel at rest. Mechanics (bleed + resting alignment) verified in headless Chromium against overflow-x:clip. The same treatment was then SWEPT across every page-level horizontal rail on both clients: the profile Achievements tile rail (web; the mobile counterpart is a wrap grid, no scroll), the Today 'Exercises — your favourites' widget rail (its centre-snap now centres cards on the physical screen), the Cockpit context-pill rail, and the History ViewSwitcher chip rail. In-card table scrollers (analytics/team/plans etc.), full-width pagers (logger, exercise-page charts) and sheet-hosted rails deliberately stay column-bound. The web profile section heads also moved onto the display face per the SectionHead standard (mobile twin via serifIf). SPARKLINE FIX ('gradient bottom weirdly looking'): the web exercise-widget spark (recharts) pinned a flat/zero series to the card's bottom border — a half-clipped stroke that read as a broken card edge with a torn area wash — and its KIND_STROKE hexes were the DARK-theme accents (Aurora teal on washi). The recharts spark was replaced with the same hand-rolled SVG the mobile card already uses (identical 340×92 path math, 18%-padded domain so the baseline floats, round joins, end dot), and the stroke/up/down hexes are now theme-resolved (kindStroke/upHex/downHex + web useTheme): Aurora keeps chartreuse/teal/sand, Kyoto Hour draws pine/sage-text/amber-text with vermilion for regressions — wired through the exercise page's charts too." },
  { id: "design-system-unification", area: "Core", status: "shipped", title: "Design-system unification — one-accent discipline", detail: "The app's single typographic/colour discipline, enforced after a 'de-AI-slop' pass. THE RULE: within any cluster of PARALLEL items (a stat row, a list of tiles, a set of section headers) the hue lives in ONE small MARKER or carries real semantic meaning — it never floods labels or repeats arbitrarily; parallel values + labels stay NEUTRAL (chalk value / ash label). What's PRESERVED because it actually encodes something: the Aurora section wayfinding (SECTION_COLOR kicker dots, semantic.ts — Train=lime/Feel=teal/Plan=sand/Connect=terracotta), the genuine state/role colours (ROLE_COLOR, danger=red), and the ✦ premium signifier (the SAND ✦ on every Full badge / unlock CTA / locked tile — recoloured from violet, see premium-accent-sand). Only DECORATIVE multi-hue — colour with no meaning — is collapsed. FOUR Today/Settings surfaces swept so far, web + mobile at parity: (1) the Today glance strip (Quick Log – Readiness – Done today) — its three values were lime/blue/amber, now one chalk value colour (today.tsx / home.tsx); (2) the GO FULL section header — the whole label was violet, now ash with the accent kept only on the ✦ marker (that marker is now SAND, not violet — see premium-accent-sand), matching the shared Kicker hue-in-marker pattern; (3) the Settings icon tiles — the per-category TONE map gave every row a different hue (account=lime, preferences=teal, notifications=violet…) with no logic behind the mapping; collapsed to one neutral ash chip, red kept ONLY for the destructive danger section (account-settings.tsx / aurora/settings.tsx). This SUPERSEDES the earlier 'web TONE unified to the mobile multi-hue chip palette' note in settings-drill-in — both clients are now the single neutral chip. (4) the RECOVER & MORE header + its Nutrition/Follow-a-coach rows — the header gained a neutral ash marker dot so all three Today headers share the marker+ash-label structure, and the two DeferRow icon chips (blue/violet) were unified to the neutral ash tile (DeferRow now colours its glyph from the token directly, since there is no --ash-text var). Both typechecks green on every pass. SEPARATOR PURGE — the training-plans surface (web + mobile at parity): the middot ` – ` separator (read as AI-slop) is gone from every plan surface. A shared MetaLine helper (apps/web/components/aurora/meta.tsx + the mobile twin) is now the app's ONE consistent way to divide inline PEER FACTS — a thin vertical HAIRLINE rule (1px, currentColor at ~0.32 opacity) instead of a dot, so it reads as structure not punctuation; it accepts either an array of `parts` or a `–`-joined `text` string (split internally) so a stored/i18n meta with ` – ` renders as hairlines WITHOUT changing the data. Wired across: the Train launcher ListRow meta + Repeat-last meta, the Explore plan-preview cards (p.meta), the Plans list/detail/percent-detail header metas (weeks │ ×/wk │ tag │ level │ peak-note), and the Today prescription meta (goal │ block │ wk) on both clients. PRIMARY+ANNOTATION joins (not peer facts) were instead reworded to PARENTHESES — the hairline stays reserved for peer-fact meta lines: the plan-detail day-card band labels (`Main (3 exercises)`, `Strength/Accessories (n exercises)`), the AM/PM session band (`PM (12k)`), and the prose/week prescription+note detail (`… (cue)`) in web program-days.tsx + mobile percent-program.tsx. HARDCODED ELEMENTS removed on the same surface (new i18n, en/pl/de): `train.aiCoach` replaces the literal 'AI coach' eyebrow (both clients' PremiumHero) + the mobile Start-button caption fallback; mobile `plans.title`/`plans.popular`/`plans.perWk`/`plans.week1`/`plans.wkShort`/`plans.enrollError` replace the hardcoded 'Plans' heading, 'Popular', '×/wk', '1 week', 'Wk', and the 'Couldn't enroll…' error; web `w.train.plans.week1`/`wkShort`/`thisWeek` replace the '1 week'/'Wk'/'this week' literals in aurora/plans.tsx; the ` – AI` dot on the mobile Start button was dropped (the ✦ already signals AI) and the `train.aiReadiness` i18n value was de-dotted ('AI coach – readiness' → 'readiness-aware'). The Explore plan-preview rail no longer duplicates the library in a hardcoded array (custom emoji + tints + drifting names like 'Hansons 5K' / '12-Week Kettlebell') — it now DERIVES from a shared @hybrid/core `PLAN_PREVIEWS` (top plan per goal that has one, carrying goalName + icon + colour), so both clients render the real plan name, the goal's own geometric glyph tinted in the goal colour, and a derived `goalName │ scheme-tag` meta — the preview can't drift from the real plans and the emoji/tint hardcoding is gone. Both typechecks + web build + 690 core tests green. Remaining screens tracked in design-system-unification-sweep." },
  { id: "hero-system", area: "Core", status: "shipped", title: "The Hero System — one screen head for the whole app", detail: "Every screen head in the app is now ONE object at one of three RANKS, specified once in packages/core/src/hero.ts and consumed by both clients (apps/mobile/components/aurora/hero.tsx + apps/web/components/aurora/hero.tsx). Full spec, including the SwiftUI-native architecture and the migration plan: reference/hero-system.md. THE DIAGNOSIS: three shipped screens had invented three heroes — History (44x44 back square, radius 14, hairline border, IN CONTENT so it scrolled away, title 26 on the same row as the button, an \'Archived\' bordered pill), Workout Wrapped (40x40 back square, radius 12, black-40% fill, fixed at safeTop+6, title 40 — off the shared type ladder — under a gold mono kicker, figure at 96/112) and the Plan/Goal cover (38x38 back CIRCLE, white-12% fill, inside a collapsing bar at safeTop+4, title 31 under a filled white chip). Three sizes, three radii, three materials, three vertical positions, three type sizes, three names for \'what kind of thing this is\'. THE SYSTEM: three ranks — `bar` (the rail alone), `title` (the large-title hero, for INFORMATION pages whose subject is a collection: ambient field, no art) and `cover` (the art hero, for IDENTITY pages whose subject is one nameable thing: fixed-dark ink + accent wash + emblem) — plus `mode: takeover` for a paged full-screen experience (Wrapped), which is a MODE, not a fourth rank, because it keeps every anatomy rule and changes only two things that follow from having no scroll-to-collapse (fixed rail, dismiss instead of pop). A `bar` IS a `title` at collapse 1; a `title` IS a `cover` with its art removed — so the whole system is one container, one collapse track, one rail, one nav button, one title ramp, one metadata language. THE SPATIAL CONSTANT is the RAIL: a 44pt row at safeTop+4, present in every rank and mode, counter-translating the hero frame so the nav button never moves on screen and never scrolls away. ONE NAVIGATION BUTTON: a 40pt circle in a 44pt hit target (circular because it must float over arbitrary art and a rounded rect competes with the app\'s card language; because Apple\'s own art-backed surfaces use a circular glass button; and because a circle survives Dynamic Type without a re-tuned radius), whose MATERIAL — and only its material — varies with what is BEHIND it (`clear` over the plain field, Liquid Glass / white-12%+blur over art or once content scrolls under the rail), never with which screen it is on. Its accessibility label names the ORIGIN, not the action. TYPE: one ramp off the existing fs ladder (cover/takeover fs.hero 34, title fs.display 26, collapsed inline fs.subtitle 16, the takeover\'s one figure 76); a long title steps DOWN a rung rather than running to a third line or ellipsizing; the title block is BOTTOM-ANCHORED so a 1-line and a 2-line title share a last baseline and nothing below the hero moves when a name gets longer. METADATA: exactly three slots (eyebrow above the title = what kind; meta below = facts about this instance; the rail\'s trailing accessory = one label or one control), all in ONE mono/uppercase/11pt/+0.08em voice, joined by heroMetaLine() with a spaced en dash (never a middot). The accent-tinted white CHIP is reachable only over art, where an 11pt mono line has no contrast substrate — tone follows contrast need, never screen identity. BACKDROPS: the rank picks the ground (heroBackdrop() IS the rule), and the light source encodes hierarchy — a container is lit from the top-LEFT, the things inside it from the top-RIGHT. MOTION: exactly three transitions (`lift` a card becomes a hero; `deepen` same subject, more detail, nothing flies; `raise` a page becomes a takeover), all holding the rail fixed; if a move fits none of them the destination has the wrong rank. The collapse itself is finger-driven direct manipulation and is deliberately NOT suppressed under Reduce Motion (only the released-mid-track settle degrades to an instant jump). ANTI-DRIFT: core publishes the geometry (heroGeometry), the track (heroCollapse/heroSnapTarget), EVERY layer\'s interpolation (heroLayers — the thresholds that used to be hand-copied magic numbers like `delta * 0.62` in two separate trees), the type ramp, the metadata language and the backdrop/nav/status-bar rules, all unit-tested (hero.test.ts: 30 cases incl. \'the rail is at the identical y in every rank\', \'the display and inline titles are never both on screen\', and \'every transition holds the rail fixed\'). MIGRATED IN THIS CHANGE, both clients at parity: History (title off the rail row, the archived pill -> rail accessory, the view switcher -> a sub-rail that DOCKS beneath the collapsed bar instead of scrolling away, and the nav button no longer scrolls away; mobile keeps its FlatList via HeroScreen\'s `scroller` slot, so a screen never trades virtualization for a hero), the Plan/Goal/Library/Recipe cover (geometry, detents, nav button, chip -> eyebrow, meta line and title ramp all now read from core — which also closed a real 20px web-vs-mobile drift: web\'s cover was 272 tall against mobile\'s 252), and Workout Wrapped (one rail at the system y, the back square -> the dismiss circle with chevron-down, title 40 -> 34, figure 96/112 -> 76, gutter 24 -> 18; the shared-element clone now reads the same ramp as its destination so it lands on exactly the right type). Core tests (2023) + both typechecks + web build + iOS bundle export green. The remaining screens (Workout detail, Exercise detail, Exercise analytics, Statistics, Profile, and the ~40 sub-pages still on ABack) are tracked under design-system-unification-sweep and hero-system-migration." },
  { id: "hero-system-sweep", area: "Core", status: "shipped", title: "Hero System — every screen head migrated, ABack retired", detail: "THE SWEEP IS DONE: every screen head on BOTH clients now comes from the HERO SYSTEM (hero-system, packages/core/src/hero.ts, reference/hero-system.md). ABack — the 44x44 line-bordered square that 45 mobile files hand-rolled a header row around — is DELETED from kit.tsx, so it cannot come back; web's bare `<h1 fontSize: fs.display>` head is gone from every screen too. THE BRIDGE: AuroraScreen (mobile) and HeroScreen (web) take a `hero` prop and hand the whole shell to the system, so a screen is one prop rather than a hand-rolled ABack + AHeading row. Both shells were split so the hero path and the plain path never share a hook order (AuroraScreen -> AuroraPlainScreen), and AuroraField + withAlpha moved to components/aurora/field.tsx because kit routes through hero and hero needs the field — otherwise an import cycle. `back` defaults to router.back() (the default ABack had); `back={false}` renders an empty leading slot on a root screen so the title's y never shifts between a root and a pushed screen. `scroller` hands a screen the scroll props so it keeps its own FlatList — History, Leaderboard and Feed all kept virtualization. HeroScreen also gained refresh, center and a NON-SCROLLING mode (a screen that owns its own flex layout below the hero has no scroller, therefore no collapse track — the same rule, not a special case). MIGRATED (mobile, ~44 screens): Statistics, Analytics, Trends, Volume, Velocity, Video, Force plate, Endurance, Longevity, Progress, Exercises, Exercise detail, Calendar, Check-in, Periodize, Builder, Run track, Sport, Coach, Connections, Connection page, Competition, Talent, Tactical, Team monitor, Team compare, Org, AI coach, Logger settings, Profile edit, Coach apply, Notifications, Interval timer, Admin sections, Coaches, Discover, Leaderboard, Feed, Performance, Settings sub-pages, Login (rank `bar`). WEB PARITY in the same change (16 screens): Checkins, Connection page, Connections, Endurance, Exercises, Force plate, Longevity, Performance teaser, Progress, Run track, Sport, Trends, Velocity, Video, Volume, Statistics — plus web's HeroScreen gained the `back={false}` variant mobile had, which was a real parity gap. JUDGEMENT CALLS, all recorded in the spec: (1) Exercise detail takes rank `title`, NOT the `cover` the original migration plan assumed — the test for a cover is 'one nameable thing with an accent and a mark' and an exercise has neither in this codebase, so promoting it would mean inventing a per-exercise accent system or giving every exercise page the same theme-primary wash (the 'looks like a product page' failure the rank rule exists to prevent); it becomes a cover the day exercises get an accent. (2) Login is rank `bar` — the mark and the form ARE the screen, so a display title would be chrome. (3) Editors that live inside a Card rather than on a screen (the social-profile field editor, Nutrition's sub-views) take the system's nav CONTROL at the system's geometry without a rail, since they have no screen head to own. (4) Four decorative trailing glyphs (Calendar's calendar, Longevity's heart, Check-in's heart, Endurance's GPS pin) were DROPPED rather than moved: the rail's trailing slot carries one label or one control, never decoration. (5) Heads that were already heroes in disguise became heroes — Periodize's lime kicker is an eyebrow and its 'now in <block>' line a meta line; Performance's bespoke 'living masthead' is an eyebrow plus a title; Interval Timer's bordered lockup is a title plus a meta line; Notifications' unread count and Volume's Edit-landmarks toggle are rail accessories. (6) Statistics' weekly-volume readout stayed in the BODY — it is data, not metadata, so it does not ride the rail. Screens that render both standalone and as a Today hub tab (Trends, Volume, Performance, Feed, Nutrition) take a hero only when standing alone and keep their inline masthead when embedded, replacing three spellings of `{!top && <ABack/>}`. NUTRITION RESOLVED (follow-up): the sticky HUD that owned the rail y was REMOVED on both clients (see nutrition-hud), so Nutrition is now fully on the system — the hub takes a title-rank hero with the time-of-day greeting as its EYEBROW (it was a hand-rolled mono line over a hand-rolled AHeading), the diary/insights/body/meals/foods views take the same hero with a back that returns to the hub, and the seven PRESENTED sub-views (food picker, create meal/food, verified source, verified foods, recipes, recipe detail) keep their in-content head but it is now the system's BAR rank: the same 44pt row, the same 40pt circular HeroNav, the same inline-title type and one trailing slot. With the HUD gone, AuroraScreen's stickyTop / stickyTopReserve / onScrollY slot had no users left and was deleted too. Core tests (2010) + both typechecks + web build + iOS bundle export green." },
  { id: "design-token-ratchet", area: "Mobile", status: "shipped", title: "Design-token enforcement — the ratchet that stops the drift", detail: "The iOS design audit's ROOT finding was not that the token system is wrong (it is unusually well authored) but that NOTHING FAILED when a call site ignored it — motion was the one healthy axis precisely because motion.test.ts holds it to its own rules. THE FIX, in three parts. (1) THE TWO MISSING AXES: packages/core/src/scale.ts gained `lh` (4 leading RATIOS: tight 1.15 / snug 1.30 / normal 1.50 / relaxed 1.62) plus a `leading(size, role)` helper, and `tracking` (display -0.5 / normal 0 / label 0.9 / caps 1.2). These had NO token at all, which is why apps/mobile carried 29 distinct absolute lineHeights (nine of them — 15,16,17,18,19,19.5,20,21,22 — all serving body text) and 18 letterSpacings. Leading is a RATIO on purpose: an absolute line box is also why Dynamic Type could not work, since the OS scales glyphs and leaves the box where it was. (2) THE TWO MISSING RUNGS, both previously magic numbers: `fs.headline` (22 — 26 sites, and exactly the 26→22 step-down heroTitleType already documented) and `RADIUS.inner` (12 — 68 sites, the second-most-used radius in the app) plus `RADIUS.mark` (3, for chart bars/ticks written as 1/2/3/4 interchangeably). (3) THE GUARD: packages/core/src/scale.test.ts holds the ladder to its own promises (strictly ascending, nothing below the 10dp floor, headline between heading and display, leading always clears the font size, ratios scale); apps/mobile/lib/design-tokens.test.ts scans the source tree as TEXT and enforces one HARD rule (zero fontSize below 10) plus seven RATCHETS whose ceilings can only ever go DOWN — raw fontSize, absolute lineHeight, raw letterSpacing, raw borderRadius, hex literals, Alert.alert and raw <Modal>. A failure prints the offending file:line list, so it says WHERE, not just that a number moved. The ratchet is deliberately unglamorous: it fixes nothing, it makes the debt visible and stops it growing while the sweeps land." },
  { id: "type-legibility-floor", area: "Mobile", status: "shipped", title: "Type legibility floor — no text below 10dp", detail: "98 text nodes on iOS were set at 8–9dp — below the type ladder's own `nano` rung (10) and below any size Apple ships as readable — and they were overwhelmingly the app's dominant eyebrow style: mono + UPPERCASE + letter-spaced, which is the least legible combination available. Fourteen of them were in app/workout.tsx, the LIVE LOGGING screen, read one-handed mid-set. All 98 raised to fs.nano across 35 files (four of which had to gain an `fs` import). Guarded HARD by design-tokens.test.ts — not a ratchet, because there is no rung below nano and there never should be." },
  { id: "takeover-surface-tokens", area: "Core", status: "shipped", title: "Fixed-dark takeover surfaces named (and a Kyoto Hour break fixed)", detail: "The literals #0e0f0d and #0e100d appeared at 12 mobile sites doing TWO DIFFERENT JOBS, which is why neither was safe. On the Wrapped TAKEOVER they were the deliberately fixed-dark raised surface (a printed object does not change colour because the room did) — now named HERO_TAKEOVER_RAISED alongside the existing HERO_TAKEOVER_INK in hero.ts. On ORDINARY THEMED SCREENS the same literals were a genuine Kyoto Hour BUG: in feel-prompt.tsx one sat on the same line as C.ink2, so the two sibling states of one control landed at opposite ends of the value scale in the light theme (ink2 → near-white washi, the literal → still black); device-import and device-match had the same defect. Those became palette tokens. Separately the four raw-Modal sheet panels using #0e100d became C.ink2 — the colour the real Sheet already uses for its panel — so they match the sheet they should eventually BE. Net: 148 → 136 hex literals, and the ratchet ceiling moved down with them." },
  { id: "hit-target-floor", area: "Mobile", status: "shipped", title: "Tap targets — the 44dp floor across every interactive primitive", detail: "Every interactive PRIMITIVE now declares the 44dp floor — APill, AChip, ASegment segments and the compact admin PillBtn — and design-tokens.test.ts holds that HARD. AChip's selected state also carries fill AND border, never hue alone (WCAG 1.4.1). What remains is per-screen: a touchable hand-rolled inside a screen is still on its own, which is the argument for reaching through the primitives. — The iOS audit measured five selectable pills across five screens at ~25–31dp tall, built from three different horizontal paddings, four vertical paddings and three type sizes — and found exactly ONE `minHeight: 44` in the entire app, with hitSlop on 85 of 473 touchables. SHIPPED SO FAR: lib/ui.tsx exports HIT_TARGET (44) and HIT_SLOP (8) as the stated floor, and the shared primitives declare it — Button, APill (which was ALSO the one button primitive with no accessibilityRole/Label/State at all, so VoiceOver announced the app's primary action as a plain view) and the ASegment segments. REMAINING: the 18 local chip/pill implementations, which is the same work as the AppChip merge below — one geometry, one target, applied once." },
  { id: "vocabulary-one-noun", area: "Core", status: "shipped", title: "One noun for the object — session, not workout", detail: "The design audit found THREE nouns for the app's central object in shipped English copy — session (296), workout (168), training (116) — including two versions of the IDENTICAL empty-state sentence on two screens ('Empty workout — add blocks below, or load a template.' on the builder vs 'Empty session — add blocks below, or pull today's prescription.' on the logger), and a tab labelled 'Log session' leading to a settings category called 'Workout logger'. A user learns a product's vocabulary in the first session; three words for one object teaches them the product does not know its own name. THE VOCABULARY: a SESSION is the object; TRAINING is the mass noun for the activity and never labels an object; WORKOUT has left the interface. 96 English strings reworded across i18n.ts and the six web bundles, plus 7 hardcoded mobile strings and the settings-nav category title. THE ONE EXCEPTION, kept deliberately: 'workout' is Apple's own noun for what the DEVICE recorded, and device.import.lead turns the distinction into the sentence that explains the feature — 'Workouts your device recorded. New ones become sessions'. Six device keys are exempted BY NAME in the guard (i18n.test.ts), because a blind sweep would have destroyed the one place both words are doing real work. NOTE: 'logbook' was flagged alongside this in the audit as a competing name for History — it is not. All 36 occurrences are code identifiers (logbook-rail.tsx, logbookWeek); zero reach the user. That half of the finding was an artifact of counting raw source occurrences rather than shipped strings." },
  { id: "vocabulary-pl-de", area: "Core", status: "planned", title: "Vocabulary sweep — Polish + German", detail: "The one-noun vocabulary (see vocabulary-one-noun) was applied to the ENGLISH copy only. The Polish and German baselines still mix their own equivalents — de has both 'Workout' and 'Einheit'/'Training' for the same object, pl similarly — so each language is currently self-consistent but has not had the same editorial pass. Deliberately NOT swept by the same regex: picking between 'Einheit', 'Training' and 'Workout' in German is a translation decision with register and compounding implications, and guessing it from English is how a localization acquires a subtle wrongness that no test can catch. Wants a native reviewer per language, then the same guard extended in i18n.test.ts." },
  { id: "admin-kit-merge", area: "Mobile", status: "planned", title: "Fold the admin _kit into the shared kit", detail: "components/admin/_kit.tsx is the operator console's parallel design system (D-2 in the iOS design audit). Its ACard/cardStack now come from the real kit and its Segmented/Empty duplicates are next, but the substantial item is PillBtn → APill as a `size=\"compact\"` variant: 66 call sites across 13 files, and a genuine size class (an admin table row cannot carry a 16dp-padded primary pill on every line). The HIG violation it carried IS fixed — PillBtn measured ~29dp and now declares minHeight: HIT_TARGET with PressScale feedback, so the drawing stays compact while the target clears 44 — but the restyle itself is a visible change to every operator screen and wants a device to verify rather than a blind sweep." },
  { id: "type-leading-derived", area: "Core", status: "shipped", title: "Leading is derived from the size, not typed beside it", detail: "apps/mobile carried 287 absolute lineHeight values. 210 of them sat on a line with an fs.* token and were converted to leading(size, role), each snapping to the nearest of the four leading roles. THE EVIDENCE WAS THE FINDING: body/19, caption/17, bodyLg/20, caption/18 and micro/16 — 129 sites between them — were all 'normal' body leading written five different ways, so two paragraphs at the same size read at different densities depending on which screen you were on. FOUR were left deliberately because their ratio is >0.09 from any role (a 1.04 display title, a 2.71 spacer): those are making a point rather than picking a leading, and forcing them onto the scale would have been the regex overruling the designer. 77 remain, all on a RAW fontSize rather than a token — fixing them means tokenising the size first, so they are gated behind the raw-fontSize ratchet rather than hidden. Ratchet lowered 287 → 77." },
  { id: "mobile-kit-merge", area: "Mobile", status: "shipped", title: "Merge the two mobile UI kits (the Liquid Glass split)", detail: "DONE. lib/ui's Card/Screen/Button/H1/GlassField are retired into components/aurora/kit: 231 ACard renders across 72 files on ONE material (Liquid Glass reached 20 admin sections, Feed, Discover, Coaches, Leaderboard and Session detail for the first time), APill absorbed Button's outline variant and colour, AuroraScreen gained an explicit hubTab prop, AHeading reads the Hero System's own title rung. lib/ui is now hooks, tokens and the four primitives the kit never had. Net −198/+35 lines there. — THE HEADLINE FINDING of the iOS design audit. apps/mobile runs TWO complete UI kits side by side: lib/ui.tsx exports Screen/Card/Chip/Button/H1/Kicker/Mono/Loading, components/aurora/kit.tsx exports AuroraScreen/ACard/APill/AField/ASegment/AHeading/ASub. Both are alive and heavily used, and they disagree on padding (Card 16 vs ACard 20), on whether the component ships its own outer marginBottom (Card does, which is why they can't be stacked together), and DECISIVELY on MATERIAL: ACard drops a native SwiftUI glassEffect surface on iOS and Card never can. Since LIQUID_GLASS_SUPPORTED is just Platform.OS === 'ios' with no toggle, this is a permanent split a user cannot reconcile — 234 card instances across two materials, decided by which file the developer happened to import from. The divide runs straight through the consumer app: GLASS on Today/Nutrition/Performance/Plans/Profile, SOLID on Session detail, Feed, Discover, Coaches, Leaderboard, the social profile, the coach tools and all 20 admin sections. On an iOS 26 device the material CHANGES WHEN YOU TAP INTO A SESSION, which is the most visible inconsistency in the product. FIX: retire lib/ui's Card/Chip/Button/Screen/H1 into aurora/kit, keeping ACard's spec and its `solid` opt-out for data-dense read surfaces; move the layout margin to callers; delete the surviving classic-template ternaries in the same change. Roughly half the audit's other findings resolve with it." },
  { id: "mobile-confirm-sheet", area: "Mobile", status: "shipped", title: "One confirm sheet — retire the 38 system alerts and 12 raw Modals", detail: "DONE. components/aurora/confirm.tsx: confirm() (14 sites), notify() (20 sites that had no decision in them at all) and confirmText() — the last replacing Alert.prompt, which was iOS-only and silently DROPPED the moderator's note on Android. All 11 hand-rolled bottom sheets now present through Sheet; tour.tsx keeps its Modal, exempted by name, because a full-screen fade coach-mark is a different presentation. Both rules are HARD in design-tokens.test.ts. — The app owns a Sheet that tracks the finger 1:1, rubber-bands, supports detents, resolves release by velocity projection and recedes the presenting screen — and hands its highest-stakes moments to the OS instead: Alert.alert is called 38 times (delete a session, leave a plan, erase an account, every destructive nutrition action) and twelve surfaces present as raw `<Modal animationType=\"slide\">` (the exercise picker, session editor, device import, device match, quick sport, the share sheet, the coaches profile, the anatomy viewer). Those twelve get the OS slide with no drag-to-dismiss, no detents, no scrim gesture and no parent recede — so the gesture a user learns on Today is DEAD on the controls they touch most. FIX: an AppConfirm built on the existing Sheet with shared copy per action in i18n.ts, and re-present the twelve Modals through Sheet (the API already matches). Both are ratcheted in design-tokens.test.ts so the counts cannot grow while the work lands." },
  { id: "mobile-component-merge", area: "Mobile", status: "shipped", title: "Component merges — chip, section head, meter, empty state, field, search", detail: "PARTLY DONE — chips landed: 18 implementations became two (Chip static / AChip selectable), the six disagreeing axes collapsed, and two chips that painted their label with the raw accent instead of txt() (failing AA on the Kyoto washi) were fixed. Three survivors were renamed for what they actually are rather than merged: MetaPill (a status readout), RailAction (an animated rail item), DayChip ×2 (date tiles). STILL OPEN: 13 bar/meter implementations, 10 section headers, 108 raw TextInputs against AField, 12 unshared search fields, 8 segmented controls, and no skeleton at all. — The iOS audit's redundancy ledger, each entry a set of implementations that solve one problem several ways. 18 CHIP/PILL designs (Chip in lib/ui plus MiniChip ×2, SPill, Pill ×4, Chip ×4, Tag ×2, DayChip ×2, PlanDockPill and a selChip closure) → one AppChip, two variants, one geometry, ≥44dp. 13 BAR/METER implementations (Bar ×2, Bars ×2, BarRow ×2, MeterRow(s) ×2, MuscleBar, StackBar, PaceBars, Spark, percent-program) → a horizontal meter row and a vertical column series. 8 SECTION HEADERS (SectionHead, SectionLabel ×2, Section, SectionHeader, Label, Kicker, admin _kit) → one AppSection absorbing Kicker's 348 eyebrow sites. 2 EMPTY STATES that disagree with each other on padding, size and measure → one spec. 107 raw TextInputs against 5 uses of the perfectly good AField, and 12 search fields with no shared primitive → adopt AField, add AppSearchBar on it. 6 SEGMENTED CONTROLS → ASegment becomes the single entry point, dispatching to GlassSegment on iOS and LiquidSeg elsewhere. No AppSkeleton exists at all, so arriving content pops in behind a spinner (33 Loading() + raw ActivityIndicator in 18 files) instead of reserving its space. NOTE ON PARITY: the web client is scheduled for retirement and the audit that produced this list was scoped to apps/mobile only, so these merges are deliberately mobile-first — the usual web↔mobile parity rule is suspended for them by explicit instruction, not by oversight." },
  { id: "mobile-primitive-sweep", area: "Mobile", status: "shipped", title: "The Medium tier — segment, section head, skeleton, meter, search", detail: "The iOS design audit's Medium findings, and in three of the five READING them before merging changed what the merge was. SEGMENTED CONTROLS 8 → 2: two of the eight (the admin Segmented, History's ViewSwitcher) were wrapping/scrolling chip RAILS, not segmented controls, so they became AChip rows (and cleared the 44dp floor doing it); what actually needed fixing was ASegment's non-iOS fallback, a static pill row, now LiquidSeg — so the gesture-tracked lens went from 2 surfaces to every segment. SECTION HEADS 8 → 1 (ASection): CLAUDE.md already NAMED that standard and it had been re-derived eight times, each agreeing on the shape and differing on title size, face, meta size, tracking and top margin — a standard that lives in prose gets re-derived. SKELETONS 0 → 46: every <Loading /> site was `if (data === null)`, i.e. arriving content behind a spinner; changing what Loading RENDERS fixed all 33 with no call-site edits, and the pulse stops under Reduce Motion. METERS: of '13 bar implementations', five were one labelled horizontal proportion (now AMeter, with the progressbar role and accessible value they never had), three were vertical column charts with real differences, and five were not bars at all — renamed RailSurface / FaceStroke / Rule, because the same misnaming is what hid `Pill` from the chip merge. SEARCH: thirteen fields, no two alike and NOT ONE with a clear button; the four standalone ones are ASearch (built on AField, which gained autoFocus/autoCorrect/onClear). STILL OPEN: the search fields nested inside bespoke rows (nutrition ×3, exercise picker, quick-sport) want their parents restructured; 108 raw TextInputs; the three vertical column charts." },
  { id: "mono-face-discipline", area: "Mobile", status: "shipped", title: "The mono face is for data — a correction to the audit's own metric", detail: "The audit reported that the monospace face was carrying the interface, on the raw ratio: F.mono 1,211 sites against 818 for all four Archivo weights combined. CLASSIFYING the 1,217 sites instead of counting them shows that framing was wrong. 57% are small labels and numerals, 27% are uppercase kickers — 84% is exactly what a mono face is for in an app full of loads, paces, counts and clock times. Only 173 sit at reading size without kicker treatment, and most of those are still data (step.rir, restSec, a set-type badge). FOURTEEN were unambiguously LANGUAGE in a monospace face, and those are the real finding: a coach's note, a coach's reply, a notification body, and the empty-state sentences on analytics/coach/org/plans/talent/team-compare/team-monitor/velocity. User-authored prose set in JetBrains Mono is the case that actually reads wrong; those moved to Archivo and the numerals stayed. The lesson is the measurement rather than the fix — a ratio counted the FACE, and the face was never the question. What the text SAYS is." },
  { id: "design-system-unification-sweep", area: "Core", status: "planned", title: "Design-system unification — remaining screens", detail: "The one-accent discipline (see design-system-unification) has been applied to the Today + Settings surfaces; the rest of the app still needs the same audit before it re-grows a rainbow — the Train launcher, the live Logger, Nutrition, Profile/You, Explore, Coaches/Feed, Calendar and the Volume/analytics screens — each swept for arbitrary multi-hue clusters (colour reserved for a single marker or a genuine state/role, parallel items + labels left neutral), web + mobile at parity in the same change. (NOTE: the mobile Clay & Sage accent parity that was briefly tracked here is DONE — see japandi-clay-sage; the bespoke screens alias the theme palette as `C`, so their fills flip automatically, and the accent-as-text sites were routed through `txt()`. This item remains only for the one-accent / de-rainbow discipline pass on the screens listed above.) PROGRESS (Aug 2026, the panel-critique sweep): foundations landed — tokens.ts card/line re-synced with palette/globals (charts drew a stale grey), fs gains hero(34)/stat(46) rungs, web Button rebuilt to the mobile spec (Archivo 700/15, ≥44px, hover+press), a shared press-feedback primitive on BOTH clients (web `.pressable` CSS utility; mobile `PressScale` running Animated.spring from springToRN(springs.nav), Reduce-Motion → opacity dip) adopted by kit primitives + the audited screens' rows, theme-aware card shadow (warm umbra on Kyoto washi) via one cardShadow helper, mobile entrance on the real sheet spring, dead material deleted (~900 lines: web .cmd-* menu, .lg-thin/thick/vibrant, .aurora-enter, mobile liquid-glass.tsx/GlassCard/GlassButton/GlassPanel/AuroraSvgIcon, stories/today-quick orphans, SECTION_COLOR which had zero call sites), type floors on exercise-page (no more 7-8px labels), F.monoBold where fontWeight '700' was faked on the static mono face, hit-target fixes (web period tabs, builder set-row column), sheet exit no longer truncated (fast+complete on both clients), single nutrition over-target threshold, error red unified, white hairlines made theme-aware, profile wiggle guarded + staggered on mobile." },
  { id: "sweep-arrow-emoji-glyphs", area: "Core", status: "shipped", title: "Design sweep — raw arrows + emoji → drawn glyphs", detail: "~275 raw `→` characters (Archivo's subset lacks U+2192 — cta-label.tsx exists precisely for this), plus 🏆/🔥/⚡/🔒/📅/🏃/🏁/📈 emoji and dingbat controls (⠿ ⧉ ⛓ ▾ ✕) across both clients' aurora screens. Replace with CtaLabel / drawn AuroraIcon glyphs (a few new icons needed: trophy, flame, bolt, lock, calendar); add a lint/grep guard so they don't return. Worst files: nutrition ×2, today/home, workout-wrapped. SHIPPED (Aug 2026): UI-chrome emoji replaced with drawn glyphs across both clients (trophy ×11, lock, bolt, calendar-event, arrow-up; Private tab de-emojied; wrapped CTA via CtaLabel); mobile week-rail day glyphs ported to web's exact SVGs. REMAINING BY DESIGN: share-story card content emoji. FINISH-LINE PASS (same sweep): stopwatch+moon glyphs added and the device-ad grid converted on BOTH clients; ~60 CTA/standalone arrows now render through CtaLabel/ArrowGlyph (mobile gained the SVG ArrowGlyph twin); value→value progressions deliberately keep the → as data notation; 2 Text-embedded glyph pairs left (mobile home disclosure, admin security marker). TYPOGRAPHY CONSOLIDATION (Aug 2026, same sweep): 197 sub-pixel font sizes snapped to integer rungs and 625 letterSpacing snaps across both clients — web trackings collapse to .08em/.12em/-.01/-.02/-.03em, mobile to 0.9/1.2/-0.3/-0.5/-1 dp; the uppercase kicker is now exactly two recipes (11/.08em and 10/.12em). Share-story art and deliberate stretched effects excluded." },
  { id: "sweep-radius-spacing-codemod", area: "Core", status: "shipped", title: "Design sweep — radius + spacing consolidation codemod", detail: "~30 distinct border radii and off-scale spacing literals (14 is the single most common mobile padding and is not a space.* rung; 11/13/9/7 add ~160 more uses) collapse to the token set: radius 28 (card) / 16 (field-nested) / 12 (tile) / 999 (pill); spacing snapped to the 4-pt rungs. Mechanical codemod per screen family with visual spot-checks; the audited-screen inventory lives in the panel critique (session Aug 2 2026). SHIPPED (Aug 2026): radii snapped app-wide to the 28/16/12/999 classes and odd off-scale spacing to the 4-pt grid on both clients (flat r22 cards gained the card shadow; profile's 4dp column misalignment fixed; today's 2px head insets dropped). FINISH-LINE PASS (same sweep): the even off-scale band is now empty too — ~400 web + 559 mobile snaps put every aurora padding/gap/margin on {4,8,12,16,20,24,32,40} (micro-nudges ≤10 and structural one-offs excluded by design)." },
  { id: "sweep-icon-stroke-grid", area: "Core", status: "shipped", title: "Design sweep — icon stroke = f(size) grid", detail: "The Aurora icon set renders at 18 distinct strokeWidths and every integer size 11-22; the same Today-hub glyphs are stroked 3.5 on web vs 5 on mobile (43% heavier) at the same 21px. Define one stroke-per-size table in @hybrid/core (e.g. ≤16px → 4.5 viewBox units, ≥20px → 3.5), apply through both renderers, and regenerate the mobile PNGs at the matching weight. Also: draw distinct glyphs for the arrow-up×5 / list-play×3 semantic collisions (statistics/performance/trends/velocity/leaderboard; exercises/video/feed) and retire the duplicate play/list-play + check/check-circle path data. SHIPPED (Aug 2026): auroraIconStroke(size) is the one size→stroke rule consumed by both renderers; mobile AuroraIcon renders true vectors from the shared paths (PNGs remain only for the native tab-bar fallback); hub glyphs 3.5 both clients; check/check-circle + play/list-play are distinct drawings; trophy/flame/bolt added." },
  { id: "sweep-today-hierarchy", area: "Web", status: "shipped", title: "Design sweep — Today hierarchy rebuild", detail: "The panel's biggest structural finding: ~20 top-level modules, the Start CTA below the fold, a 44px done-count and 46px mood word outweighing the primary action, and the two upsell AccessCards as the largest cards on screen. Rebuild to three modules above the fold (session card w/ Start, week strip absorbing WeekVerdict+AlsoToday+streak, one-row Feel), demote the upsells to a single quiet row, delete the greeting/live-dot/wordmark-rule ornaments. Web + mobile in the same change. SHIPPED (Aug 2026): greeting/live-dot/wordmark-rule deleted (hanko kept), the two 220px AccessCards + head collapsed to one quiet DoorRow-idiom ✦ row (funnel routing preserved), done-count 44→26 and mood word 46→26, 🔥→flame + 📅→calendar glyphs, Sheet sub widened to ReactNode; both clients, typechecks green." },
  { id: "sweep-nutrition-hub", area: "Web", status: "shipped", title: "Design sweep — Nutrition hub consolidation", detail: "~37 interactive targets and nine visually identical ink2/r18 rows (4 meal + 5 menu) on one scroll; the 200px calorie ring is the visual hero yet not interactive (and is 104 absolutely-positioned DOM spans on web). Consolidate: ring+macros as one animated SVG canvas (count-up, tap → diary), meal rows as one ledger with a persistent Add action, the 5 menu rows as a single link row. Ring tick weight also drifts 6px web vs 9dp mobile — one geometry. SHIPPED (Aug 2026): ring rebuilt as one SVG track+arc (104 spans → 3 nodes), ring+macros merged into one tappable card routing to the diary (web count-up honours reduced motion; mobile PressScale), menu ladder → one wrapping link row, hub row padding unified 14×16, HUD anchors preserved; both clients." },
  { id: "sweep-mobile-chart-axes", area: "Mobile", status: "shipped", title: "Design sweep — mobile exercise charts get their axes back", detail: "The mobile exercise-page scatter/surface charts dropped ALL gridlines, kg ticks, rep ticks and isoline labels (web keeps them); the body-weight chart is a Recharts line w/ axes on web but a 64dp bar sparkline on mobile. Restore reduced-density axes (kg + rep ticks minimum) on mobile and pick ONE chart identity per dataset across clients. Add page dots to the mobile chart pager (web has arrows; mobile has no affordance that 11 more slides exist). SHIPPED (Aug 2026): scatter regained kg gridline ticks / rep ticks / isoline labels at reduced density; surface regained per-bin rep + W1/mid/last labels; pager segment strip verified at parity (web's edge arrows are a pointer affordance, strip is the shared indicator)." },
  { id: "sweep-plan-cover-hues", area: "Core", status: "shipped", title: "Design sweep — per-goal plan cover hues", detail: "19 goals share 4 accent colours (plans.ts), so five different goal covers render literally the same wash; mobile covers also drop web's radial hotspot layer and accent-tinted chip (hardcoded #edefe8). Widen the goal palette (≥8 hues or a hue-per-goal derivation), add the radial layer + tinted chip on mobile, and align the gradient recipe (web color-mix stops vs mobile alpha stops) so the same plan reads as the same cover on both clients. SHIPPED (Aug 2026): 19 unique hand-authored hues in the muted brand register (originals kept for their most semantic goals); mobile cover gained the radial hotspot layer, 82%-white accent-tinted chip, and web-matched wash stops (covers + goal tiles)." },
  { id: "screen-transitions", area: "Core", status: "shipped", title: "Screen transitions + motion system (Wave 1)", detail: "WAVE 1 SHIPPED on both clients. Before: one 240-260ms fade-and-rise reused for every navigation (web `.aurora-enter` on a keyed wrapper; mobile `useEntrance()`), so a tab switch, a drill-down and a modal looked identical, and on web the outgoing screen was unmounted with no exit half. TOKENS: packages/core/src/motion.ts is now the single source of truth for both clients — SPRINGS, not duration+bezier, for everything positional (slide .34/1.00 -> 403ms, zoom .46/.92 -> 429ms, sheet .38/.86 -> 378ms, plus the already-shipped nav .32/.74 -> 365ms), expressed as SwiftUI response/dampingFraction because a bezier carries no velocity and therefore cannot be interrupted or retargeted, which makes gesture-tracked transitions impossible. `springToCss()` integrates the physics into a CSS linear() easing (with a bezier fallback declared first for engines without linear()); `springToRN()` converts the same parameters to RN's mass/stiffness/damping. Beziers survive only for opacity. Spring durations are solved NUMERICALLY for VISUAL settle (within 0.5% of target and staying there), not from the envelope bound: the analytic bound ignores the critically-damped `1+wt` term and made the first cut of these tokens 521ms (slide) and 641ms (zoom), both over the system's own 450ms ceiling — caught by motion.test.ts, which now guards it. DIRECTION FROM HIERARCHY: `screenTransition(from,to)` derives sibling/push/pop/replace from the bottom-nav order (NAV_ROOT_ORDER, with client-id aliases like log->train, you->profile), so both clients agree what a move means; back is the exact inverse of forward, and two unrelated leaves crossfade rather than inventing a direction. WEB: the shell lazy-loads nearly every screen, so keeping both trees alive for an exit would double-mount chunks — instead `lib/use-screen-transition.ts` wraps setScreen in the View Transitions API (`startViewTransition` + flushSync), which snapshots the outgoing tree in the browser, giving a real paired exit with no structural change; direction is published as data-nav-kind/data-nav-dir on <html> and globals.css picks the keyframes. `.motion-screen` carries `view-transition-name` so ONLY the screen travels (sidebar, header and banners stay put), with the default root cross-fade suppressed. Where the API is unsupported the state update just applies — the old behaviour, no worse. MOBILE: per-route native animation options on the expo-router Stack (rendered natively by react-native-screens 4.25 — previously only 2 of the Stack.Screen entries set any options at all), the tab shell pinned to `animation: none` since it is a root not a push, and `useEntrance()` retimed onto the shared sheet spring. SHEET PARENT-RECEDE on both clients: the presenting screen scales to 0.92 with its corner radius growing to a device radius and dimming, so the sheet sits on a real stack — which is what lets the scrim drop from 0.6 to 0.28. Web drives it via a `data-sheet-open` flag on <html> plus `.motion-recede-host` on the shell root, and Sheet now PORTALS to <body> because the transformed host would otherwise trap a position:fixed modal; mobile drives it through a new root-mounted `lib/sheet-recede.tsx` provider (same shape as NavScrollProvider — a Modal renders in its own native window and cannot reach the shell), reference-counted so a nested sheet does not un-recede early, with the brightness drop drawn as a black wash rather than a `filter` because RN filter support is uneven. REDUCE MOTION is a SUBSTITUTION, never a deletion: every transition cross-dissolves over durations.reduced (150ms) instead of cutting instantly, because an instant cut removes the user's only signal that the screen changed. This required scoping the long-standing global !important reduced-motion backstop in globals.css, which was collapsing the substituted dissolve to 0.001ms and silently reproducing the exact defect. GUARDS: motion.test.ts (springs never exceed the ceiling, slide never overshoots, sheet does, RN conversion round-trips, back inverts forward, reduced-motion duration is non-zero) and apps/web/__tests__/motion-tokens.test.ts, which REGENERATES every curve from core and fails if the pasted globals.css block drifts by so much as 1ms. TESTFLIGHT BUILD 80982819 (v1.0.0) uploaded 2026-07-26 from commit 973bc69 — GitHub Actions run #139, all steps green on a clean macOS runner. That run independently CONFIRMS the reanimated/worklets dependency fix: `pnpm install --frozen-lockfile` and `expo prebuild` both passed with no pre-existing node_modules, which is exactly what a resolution break would have failed. On-device behaviour is now AWAITING SIGN-OFF (internal testing, available immediately, no beta review) — check: sibling nav slides sideways while a drill-down pushes with the parent receding; the exercise-card figure travels into the stats-page hero (the hand-rolled FLIP, the most likely thing to look wrong — an offset landing or an early text reveal means the measurement timing needs adjusting); a sheet scales the screen behind it back with the scrim reading LIGHTER than before; all three repeated with iOS Reduce Motion on should cross-dissolve, never cut; and the edge-swipe back should work on detail screens and be dead on the live workout screen. VERIFIED in headless Chromium against the real globals.css: all five kinds fire the right keyframe pair, exits (160ms) leave faster than entrances (378ms) arrive, and every kind substitutes a 150ms dissolve under OS-level Reduce Motion. react-native-reanimated is now declared explicitly in apps/mobile/package.json (it was already a resolved runtime dependency of @expo/ui and expo-router's drawer, so nothing changed at runtime — it just stops a hoisting change from silently breaking the build). NOTE a pre-existing peer conflict, not introduced here: expo-modules-core wants react-native-worklets ^0.7.4||^0.8.0 while reanimated 4.4.0 requires 0.9.x, and 0.9.1 is what resolves; worklets is deliberately NOT declared so we do not assert a version expo disagrees with. Waves 2 and 3 also landed — see the wave-3 entry for what remains. Deck + working app reproduction: design/screen-transitions-ideas.html." },

  { id: "screen-transitions-wave3", area: "Core", status: "planned", title: "Screen transitions — Wave 3 remainder", detail: "Waves 1, 2 and most of 3 have SHIPPED (see screen-transitions). WAVE 3 DELIVERED: CONTINUOUS MASTHEAD COMPRESSION on both clients — the big screen title shrinks and the secondary lines recede as a function of scroll offset, not a stepped swap at a threshold. Web gained the shared scroll signal it was missing (lib/use-scroll-collapse.ts), the twin of the mobile NavScrollProvider, published as a REGISTERED CSS custom property (--scroll-collapse, @property <number>) rather than React state: it fires every scroll frame, so re-rendering the shell 60x/sec to move a title would be absurd — CSS does the interpolation and nothing re-renders. The masthead is sticky with a frosted backdrop that fades and blurs in over the same 0->48px range the mobile nav pill already collapses on, so the clients compress in step; mobile reads that same `collapse` value (one signal, two subscribers). Deliberately NOT suppressed under Reduce Motion: this is direct manipulation tracking the scroll position, not an animation, exactly as iOS keeps large titles collapsing. HAPTICS AUDITED: all 14 call sites reviewed; one removed (the exercise-anatomy sheet-open buzz — the only sheet in the app that fired one, so it read as a glitch rather than feedback). The rest kept and justified: every workout haptic is a genuine detent (rest target reached, set banked, drag picked up, reorder committed, pause toggled, timer finished) and the two nav haptics are consistent and a defensible idiom for a custom pill bar rather than a stock iOS tab bar — stripping them would have been applying a rule past the point where it helps. CORRECTION (Aug 2026 motion audit, audit/09): the claim that every site is 'user-gated by prefs.haptics' is NO LONGER TRUE and the count is now 17, not 14 — liquid-seg.tsx:154 and three sites in volume.tsx (216/230/458) fire regardless of the preference, and volume's Toggle uses selectionAsync where a switch wants Impact Light. Tracked for fix in motion-audit-followups. REMAINING. (1) AMBIENT FIELD COUNTER-DRIFT — deferred on a structural blocker, not on effort: web could do it (lg-field is position:fixed at shell level and already survives a screen change), but mobile renders AuroraField PER-SCREEN inside AuroraScreen, behind the Stack's opaque `contentStyle: { backgroundColor: palette.ink }`. A root-level field would be completely occluded, so parity needs every Aurora screen's background made transparent — real visual risk across the whole app for a low-impact flourish, and shipping web-only would create exactly the drift the parity rule exists to prevent. (2) NAV LENS -> FAB MERGE + scrolled-capsule merge. CORRECTION (Aug 2026): the blocker recorded here — 'needs @expo/ui to expose GlassEffectContainer/glassEffectID' — is no longer true, and was already stale. @expo/ui 56 ships GlassEffectContainer, Namespace and the glassEffectId/animation modifiers, and the Today hub dock now uses all of them for real (see swiftui-kit / today-hub-floating-pills): three capsules in one container that fuse at zero gap and flow between frames. So the merge idiom is available and proven at bundle level; what remains is a device to verify it on, and the fact that this particular target no longer exists as described (the hand-built floating nav capsule and its GlassMorphSelector were deleted when the bottom bar became the real system tab bar — see motion.ts). Re-scope before building. (3) LIVE-WORKOUT FOCUS BLUR on entering the logger. (4) CELEBRATION HANDOFF — wire the existing PR keyframes (prTrophyPop/prSweep/prConfetti, globals.css) to the transition into Done so the badge flies from the set row into the summary. (5) INTERRUPTIBLE BACK ON WEB — needs the shell's `{screen === \"x\" && …}` chain extracted into renderScreen(id) so two screens can coexist during a drag, plus real browser-history integration (setScreen pushes no history entry today, so browser Back exits the app — the bigger bug, and it should be fixed first). Both are navigation refactors with regression risk, not motion work. (6) ZOOM WHERE A CARD BECOMES A SCREEN — the mechanism is shipped and generic (SHARED_ELEMENTS); it needs a per-plan detail screen to point at, since Explore covers currently open the generic Plans list. CUT ON REVIEW, not to be re-proposed: staggered list entrance (Material idiom; iOS lists arrive as one unit and staggering delays content) and the specular sweep across the nav glass (glass refracts what is behind it; it does not emit a highlight because you navigated). NATIVE motion still needs a TestFlight build to sign off — it cannot be exercised in this sandbox." },

  { id: "mobile-render-tests", area: "Core", status: "planned", title: "Mobile render tests — a gate that actually renders", detail: "THE GAP THAT LET BUILD 81628102 SHIP BROKEN. Every tappable surface in the app lost its background, border, radius, width and flexDirection, because PressScale handed a FUNCTION to an Animated.createAnimatedComponent wrapper's `style` prop. React Native's AnimatedProps.js gates on `typeof value === \'object\' && value != null`, so a function skips the branch entirely: AnimatedStyle.from() never runs, the AnimatedValues never join the node graph, and they reach the view as raw objects where numbers belong. Aliasing Pressable -> PressScale in 83 files meant one line took out the whole app. THE POINT IS THAT NOTHING COULD HAVE CAUGHT IT: `tsc` passes because Pressable's own type accepts BOTH a style object and a style function; `expo export` passes because bundling is not rendering; and apps/mobile/vitest.config.ts scopes tests to PURE modules only ('anything that imports react-native is out of scope by construction'), so there is no gate anywhere in the repo that renders a mobile component. Web has real browser verification via Playwright; mobile has none, and the asymmetry is invisible until a render-only defect ships. WHAT TO BUILD: a render-level test setup for apps/mobile — react-test-renderer (or @testing-library/react-native) plus a vitest environment that can load react-native, added through pnpm at the workspace root (NOT npm: running `npm i` inside this pnpm workspace flattened node_modules and removed 887 packages, recoverable only with `rm package-lock.json && pnpm install --frozen-lockfile`). Minimum coverage worth having on day one: mount PressScale with a plain style object, an array, and Pressable's function form, and assert the caller's declarations survive to the rendered tree; mount AuroraScreen and one card-bearing screen and assert non-empty resolved styles. Until that exists, a change to a SHARED UI PRIMITIVE must not be swept across the app in the same change that introduces it — land the primitive, verify it on a device, then sweep. INTERIM GUARD (shipped): apps/mobile/lib/ui.test.ts extracts resolvePressStyle so the invariant is testable, evaluates the real source rather than a copy, reads RN's actual gate condition out of node_modules and runs our value through it, and asserts the JSX call site still passes an array. Verified to FAIL on the exact shipped code and pass on the fix." },
  { id: "motion-audit-followups", area: "Core", status: "shipped", title: "Motion & transition audit — the Apple-level pass (audit/09)", detail: "AUDIT + ALL FIVE TOP FIXES SHIPPED on both clients (audit/09-motion-transition-audit-2026-08.md; live before/after bench published as an artifact). The audit read the SHIPPING code, not the decks: a 9/10 token system with 5/10 adoption — motion.ts (springs over beziers, numerically-solved settle time, direction from hierarchy, Reduce Motion as substitution) is better than most shipping iOS apps and the components largely did not use it. WHAT SHIPPED. (1) BROWSER HISTORY ON WEB — setScreen pushes a real entry and popstate applies the move with the direction the browser TRAVELLED (an index stamped on each entry), so Back is the exact inverse of the navigation that got you there and Forward replays rather than re-inverting. Before, the shell held its whole location in useState and pushed nothing, so Back left the app from any depth. The direction counter lives in ONE place, owned by the shell: a `last` index cached in a closure inside onDeepLinkChange went stale on every forward push and reported the first Back as a Forward (caught by driving real history in a browser, guarded now by __tests__/deep-link.test.ts). (2) PRESS FEEDBACK — RN Pressable has NO default feedback and PressScale sat on 31 of 510 sites; web `.pressable` on 41 of 618. ~93% of tap targets answered a touch with nothing. Mobile: 83 files adopt it with ONE import line each (`PressScale as Pressable`), which required making PressScale a strict drop-in (style-as-function passes through); 4 files keep the raw Pressable deliberately (two full-screen scrims, the swipe row, the lens). Web: 574 buttons across 104 files, and the press now rides the `scale` PROPERTY not `transform`, so it composes with the inline transforms this codebase uses everywhere instead of being overridden by them (verified in a browser). Both: DOWN 120ms / UP 200ms — release is a recovery, not an input. Guarded by __tests__/press-feedback.test.ts so a new screen cannot ship silent buttons. (3) SHEET DRAG-TO-DISMISS + DETENTS — both clients drew iOS\'s 40x4 grab handle and bound NOTHING to it. The panel now tracks the finger 1:1 down, rubber-bands up, and the scrim AND the parent recede interpolate on the SAME drag input (web needed the recede made continuous via a new --sheet-p registered property). Release by velocity projection in core `resolveSheetRelease`, shared so both clients snap identically; a flick moves ONE detent, or dismisses from the smallest. Detents are opt-in (`detents={[\'medium\',\'large\']}`) and single-detent sheets stay CONTENT-SIZED — the first cut gave every sheet a fixed 92vh, which would have left Quick Log and Readiness mostly empty. Also fixed here: the mobile sheet ran Easing.out(cubic) at the sheet spring\'s DURATION (a different curve wearing the right number) and now runs springToRN(springs.sheet); the web sheet unmounted on setTimeout(160) racing its own transition and now listens for transitionend. (4) SHARED ELEMENTS — SHARED_ELEMENTS gains `sessionHero`: a logged session\'s TITLE travels from its history row into the heading of its own breakdown. The title rather than a figure deliberately — it is literally the same string at both ends, so the travelling element cannot show one value and land on another. The destination DECLINES the pair on a celebration session, whose panel runs its own reveal; the arm then expires and the ordinary push carries the change. (5) LIST MUTATION — zero LayoutAnimation on mobile, zero layout handling on web, so every delete teleported the rows below. Mobile: lib/list-motion.ts wrapping LayoutAnimation on springs.slide. Web: FLIP for inserts/reorders plus collapseAndRemove for deletes — no FLIP needed there because `height` is a layout property, so animating it to zero reflows the rows below every frame and the row leaving and the list healing become ONE animation (verified in a browser). Wired into the set-row deletes on both clients. SMALLER FIXES, all verified: springs.lens joins the token set at response .35/damping .68 (384ms, bouncier) — both clients hard-coded SwiftUI\'s DEFAULT spring at 629ms, 40% past this system\'s own ceiling on the most-tapped control, which escaped the guard because the guard only iterates TOKENS and this was not one; springs.nav renamed springs.press (it was documented as \'THE SHIPPED NAV LENS — global-nav.tsx animates on this\', a file deleted when the bottom bar became the system tab bar); the globals.css token block is now GENERATED by apps/web/scripts/gen-motion-css.mjs instead of pasted; ONE haptics gate per client (lib/haptics.ts) reading prefs.haptics by construction, because gating call sites individually demonstrably failed (4 of 17 fired regardless while the register claimed all were gated), plus Impact Light on switches instead of selection feedback; swipe rows decide on VELOCITY PROJECTION not displacement, rubber-band past the action width, commit a full swipe at 60% and buzz on the destructive commit, with geometry and physics moved to core `swipe` (the two \'twins\' agreed on none of their numbers). CORRECTION to the audit as written: it claimed web\'s three navigator.vibrate sites were all ungated — two were already gated; only the milestone celebration was not. REMAINING (not blockers, tracked as their own follow-ups): modality is still unused on mobile (one route uses a modal presentation, so Settings/editors/check-in arrive as right-slide drill-downs where Apple would use a sheet); there is no full-screen-cover vocabulary, so entering the live logger looks identical to opening Settings; loading is still spinner-first (43 ActivityIndicator sites vs 4 skeleton uses) where a skeleton of the known shape — or prefetching inside the 403ms push so no loading state renders at all — is the better answer; the remaining shared-element pairs (plan cover, coach avatar, chart expansion) need either a per-plan detail screen or a non-text flying primitive, since the mobile FLIP carries TEXT only; and the push/pop parity claim in motion.ts is still not real (the recede-and-rise push is web-only; mobile is slide_from_right for the whole Stack) — the recommended resolution stands: keep mobile\'s native push and move WEB onto a horizontal push, reserving recede-and-rise for sheet presentation. Re-affirmed CUT: staggered list entrance." },
  { id: "plan-page-cover-redesign", area: "Core", status: "shipped", title: "Plan page — full-bleed sticky cover redesign", detail: "SHIPPED on both clients (design brief + live prototype: design/individual-plan-redesign-ideas.html). THE COVER: the plan detail opens with a full-bleed cover at y=0 (under the status bar; the safe-area inset becomes cover padding) built from the Explore PlanCover recipe — duotone goal-accent wash over #0c0d0c cover ink, ghost discipline glyph, white chip, bottom-anchored 900 title, en-dash meta — via the NEW shared planCoverView() in core (accent/glyph/chip/duration/metaParts/weekBars; unit-tested), so card and hero render one view model. THE COLLAPSE: the cover pins and compresses 1:1 with scroll into a 56dp bar (chip+meta out first, big/compact titles cross-fade, glyph parallax, scrim out, hairline in). Mobile: overlay + counter-translate off one JS Animated scrollY (the NavScrollProvider idiom; PlanCoverScreen in plan-hero.tsx) with snap-to-pole on mid-range release + a prefs.haptics-gated selection detent. Web: position:sticky with negative top + a --hero-collapse custom property published rAF-throttled per frame (the use-scroll-collapse idiom; zero re-renders) + the same snap. NOT suppressed under Reduce Motion (direct manipulation — the masthead-compression stance); only the snap settle degrades to instant. THE BODY: stats hem directly on the ink; maxes as a hairline LEDGER (underline inputs, unit stated once via splitInputsTitle, live inputEcho working-weight echo, and the matrix morphs %->kg as you type since planProgramView already derives it); week pills replaced by the volume-WAVEFORM rail (bar height = real per-week volume from weekBars, so the wave/taper is visible; sticky beneath the collapsed bar; lime = selection only; label-only fallback when a discipline has no volume signal); programme day cards with display-face 'Day N' headers + right-meta counts, session bands read 'AM — 71 lifts', SILENT empty matrix cells (placeholder glyph removed), radius-28 web<->mobile parity (mobile was 16). THE DOCK: enroll leaves the flow and docks as a pill above the tab bar once the cover collapses (~45%); already-enrolled plans show a quiet status pill from the start; the classic (non-program) detail rides the same scaffold. REMAINING (niceties, not blockers): (1) 'Use my logged 1RMs' ledger prefill from the history engine; (2) the Explore covers still render their own copy of the recipe — port them onto planCoverView; (3) shared-element zoom Explore cover -> detail cover (the wave-3 item — needs Explore to route to the specific plan, not the Plans list); (4) enrolled-state extras: 2dp progress hairline on the collapsed bar, current week auto-centred + completed weeks dimmed in the rail, 'Week N of M' dock label; (5) sticky exercise column when the % matrix scrolls horizontally; (6) the native collapse feel needs a TestFlight pass to sign off (sandbox has no simulator)." },
  { id: "performance-page-merge", area: "Core", status: "shipped", title: "Performance page — Cockpit × Performance merged (one athlete hub)", detail: "The home-tab Cockpit and the analyze-tab Performance screen computed the same objects (computePerformanceState + computeInjuryRisk) and showed the athlete the same HPI twice, one tap apart — Cockpit's state card even deep-linked 'Performance →' for the depth it lacked. They are now ONE page on BOTH clients, and it lives in the ANALYZE group (nav.ts: home stays Today — 'what do I do?'; analyze leads with Performance — 'how am I doing?'); the cockpit id is gone (the web app-shell resolves BOTH screen ids to the merged screen so ⌘K entries, saved deep links and every setScreen('cockpit') caller keep working; mobile keeps /performance as a Redirect to the renamed /(tabs)/performance tab). THE PAGE (aurora/performance.tsx on both clients): living masthead (retitled 'Performance', sub 'Your state, your risk, your season — one read.', chip rail gains an HPI-band pill so the headline number reads before any scroll, and the ACWR pill now rides on HAVING TRAINING DATA, not on having a season — a planless athlete still sees their workload ratio) → Performance State — the CLASSIC card anatomy kept exactly as the Cockpit shipped it (big HPI + 'HPI – band – limiter' caption + sparkline, STR/END/REC as three big-number columns with recovery signed ±N, and today's readiness ring + check-in nudge below the hairline, explained by readinessWhy() — a truth-based line stack computed ONLY from the real log + wearable baseline (honest 'nothing logged yet' baseline copy on an empty log); the old rx.why prescription narrative, which invented a primary lift + starting load for athletes with no history, no longer renders here — it stays with the session pick on the Today flow) → the REAL 14-day trajectory as its own card right beneath (web: recharts, HPI solid lime 2.5px + Readiness DASHED teal — dash-encoded because Kyoto Hour's muted ramp can't separate two solid hues (ΔE≈8, validated), so line style + the legend carry identity, never hue alone; mobile keeps its native bars+marker rendering of the same two series — form first) → injury risk: the exception-driven summary card (calm = slim all-clear row; To Watch grid) with the analyze depth as a 'Tissue detail' DISCLOSURE — web: anterior/posterior body map + per-tissue calibrated probability table + model version; mobile: the phone-width tissue table; the plain-language driver explanations moved inside → This week → Breakdown tabs → Horizon rails (AI-coach door included; the dead 'Performance →' opener dropped) → Goal + Season duo + setup → Return-to-play panel at the bottom (protocols open on the same page as the risk that prompted them). Card headers moved off the mono-kicker+dot pattern onto the SectionHead golden standard (no-decorative-dot-headers). i18n: nav.cockpit removed, w.home.cockpit.commandCenter/-Sub + w.home.today.cockpitTitle + priv-cockpit-t retitled in EN/PL/DE (key NAMES keep the cockpit prefix — they're ids, not copy), new w.analyze.perf.tissueDetail. Casual persona keeps the same locked Teaser, now fronting both former entry points with one upsell." },
  { id: "plan-schedule-quiet-matrix", area: "Core", status: "shipped", title: "Plan schedule table — the quiet matrix (accordion + exercise sheet)", detail: "SHIPPED on both clients (brief: design/plan-schedule-table-redesign-ideas.html; ideas 01+02+04+05+06+07+08+09). The programme day tables were rebuilt in the subtraction vocabulary: (01) the session/group/column header stack collapses to single quiet rule lines — the session marker keeps its semantic colour, the tinted band washes retire, the group label rides the matrix's pinned corner or the accessory column-label line; (02) the per-column load rainbow is replaced by the monochrome INK RAMP (core loadTier: cells gain weight/opacity as %s climb; the single accent marks only the day's heaviest load); (04) PHANTOM COLUMNS die — core percentMatrixView derives columns per group and drops lifts whose loads nobody shares (the lone bodyweight Good Morning) out of the grid into full-width outlier rows (outlierPrescription), preserving authored order around the grid; (05) the exercise column PINS (web: real <table> with sticky row headers + column scope; mobile: name column outside the horizontal ScrollView with fixed row heights) and the scrolled edge fades softly (gradient, hidden at scroll end) instead of cutting; (06) QUIET NOTATION — the parser's leading × is dropped, cells read reps-first with the set multiplier stepped back to ash ('4+1 ×4', a single set is just '4'), tabular numerals throughout (core exposes reps/sets/nl per step alongside the legacy detail string); (07) the day header carries a PULSE — one hairline bar per real prescription, height = load × volume, top-% touches in accent (core dayPulse; aggregates per-lift past 14 bars) — the day-level echo of the week waveform rail; (08) the week is an ACCORDION — one day open at a time (first day by default, reset on week change), closed rows show the day title + a plain-words summary of what the day IS (core dayLeadWords) + pulse + volume + a +/− chevron; rest days are inert rows; all-prose endurance weeks keep the one-card week layout; the expand/collapse runs on the HOUSE MOTION tokens — the body arrives on the sheet spring (mobile Animated.spring via springToRN, web the 0fr→1fr grid-track transition on --e-sheet) and leaves fast on the accelerating exit curve, with Reduce Motion substituting the standard cross-dissolve (height snaps, opacity fades) and collapsed content clipped, untappable and hidden from AT on both clients; (09) every row presses into the EXERCISE SHEET (the shared aurora Sheet on both clients) — each load as % AND kg with its volume in words (stepWords), the note at reading size, the 1RM it's computed from (new ProgramLiftView.oneRm), and RPE explained as reps in reserve (rpeMeaning). NO DATA REMOVED: every %, sets×reps, RPE, note, AM/PM split and lift count survives on the surface or one tap deep. All derivation lives in core beside planProgramView (unit-tested) so the clients cannot drift." },
  { id: "plans-goal-cover", area: "Core", status: "shipped", title: "Plans — collapsing goal cover on the category screen ('the goal hero')", detail: "Idea 02 of the Plans-section redesign pitch, both clients: the category screen (goal → plan list) no longer opens as a flat heading over lonely cards — it rides the SAME full-bleed collapsing cover scaffold as the plan detail, so every depth of the Plans stack reads as one physical object at a different stage of compression. A new shared goalCoverView(goal) in core (plan-program.ts, unit-tested) derives the goal-level cover from GOAL_TREE alone: the goal's accent wash + ghost glyph, the discipline CATEGORY as the chip ('Strength'), the plan count as the top-right label ('1 PLAN' / '3 PLANS' — properly pluralised; an empty goal says 'COMING SOON', never '0 PLANS'), the goal name as the bottom-anchored display title, the plans' unique loading tags as the meta line, and NO aggregate hem — across a full category, ranges mush into noise ('6–16 weeks', '3–6/wk'); instead EACH plan card carries its OWN rule-topped hem from planHeroView (weeks / sessions / the discipline's volume metric — '656 lifts in wk 1' vs 'exercises in wk 1' vs 'sessions total') under a mono loading-tag kicker ('% OF 1RM'), so a crowded category differentiates plan-by-plan exactly where the athlete is choosing. The scaffolds were generalised rather than duplicated: mobile PlanCoverScreen (plan-hero.tsx) now wraps an exported CoverScreen that takes any CoverSpec — same Animated scrollY collapse into the 56dp glass bar, snap-to-pole detent, haptic, Reduce Motion stance; web PlanHero wraps a CoverHero the same way (position:sticky + --hero-collapse, same snap). PlanList/List render the goal cover with the plan cards beneath; no dock at goal level (nothing to commit to yet). The old goal-screen headers (mobile icon+AHeading, web backLink+h2) are retired. DIFFERENTIATED from the plan cover via a CoverSpec variant — same material, different object: the plan cover is the POSTER (wash from the top-RIGHT, modest ghost glyph, mono meta under the title, blurb below on the ink) while the goal cover is the EMBLEM (the discipline's mark blown up as the cover art — ~218px vs ~150px, 9% vs 7% white, deeper parallax factor 0.66 vs 0.55 — with the duotone wash MIRRORED to the top-LEFT so the light source itself says which level you're on, and the goal blurb rendered ON the cover face, 2-line clamped, in place of the meta line).", },
  { id: "exercise-picker-rooms-az", area: "Core", status: "shipped", title: "Exercise picker — Rooms/A–Z redesign (unified with Exercises page)", detail: "The 'Pick an exercise' surface was redesigned to close the drift with More → Exercises (five standalone concepts in reference/exercise-picker-design-concepts.html; the user chose #02 'Rooms, then Things' + #04 'The Index' with a switchable view). The picker now opens on a GROUPS view — a 2-col grid of pattern/muscle 'rooms' (initials tile tinted by modality or the sport glyph, name, movement count); tapping a room shows only its movements (crumb back to All) — two taps, never a 200-item scroll. A toggle (reusing the Exercises page's Groups/A–Z pill labels) switches to the A–Z INDEX: every movement under display-face letter heads with a right-edge letter rail for one-thumb jumps (web anchors + scrollIntoView; mobile onLayout-captured offsets + scrollTo). Rows share the Exercises-page anatomy — 40px initials tile tinted by kind, sports keep their emoji glyph, and a mono SHAPE HINT on the right (BW / BW+ / assist / secs / m from exerciseProfile) says what the set grid will ask before adding. The old 8px-dot-before-name list and the mono-uppercase category kickers are retired (per the no-decorative-dot-headers + Explore SectionHead rules). Search cuts across every room as one flat list; an unknown name is always a lime custom add. ONE component per client now serves every call-site: mobile ExercisePickerSheet (components/aurora/exercise-picker.tsx) is used by BOTH the Builder and the live logger (which passes its recent lifts as a 'Your lifts' shortcut slab above the rooms; workout.tsx's bespoke FlatList picker + item-flattening memo deleted); web's rewritten ExercisePicker in workout-blocks.tsx serves builder + logger by construction. New i18n w.train.picker.all (EN/PL/DE). Web + mobile at parity." },
  { id: "builder-one-number", area: "Core", status: "shipped", title: "Builder — 'One Number' redesign (advanced)", detail: "The routine Builder was redesigned to the 'One Number' concept (#02 of reference/builder-design-concepts.html, five Jony-Ive explorations rendered after a live TestFlight critique): the three stat tiles + balance card are replaced by a single display-weight LIVE readout — the routine's estimated minutes in 52-56px mono — that visibly grows as exercises are added (composing feels like loading a bar), with tonnage + moves as one hairline MetaLine and the strength/conditioning/endurance split as a thin 4px modality-coloured bar labelled only for modalities actually present (zeros vanish). ADVANCED EDITING kept and surfaced: per-set TYPE cycling (working/warmup/cooldown/drop badges — tap the set badge), RPE ⇄ RIR — the column header itself is now the mode switch on BOTH clients (persists via the shared rpeAsRir logger pref, setLoggerPref), and exercise reorder ↑/↓ now always available on mobile (open or collapsed, hidden only for a single exercise; web workout-blocks already had it). DISCIPLINE FIXES from the critique: (1) '+ Add set' and '+ Add exercise' demoted from lime fills to the ghost/dashed add affordance — the screen's one lime fill is Save (web workout-blocks add-set inherits this in the logger too); (2) the per-exercise signal metric row now renders ONLY while the card is COLLAPSED on both clients (expanded, the set table + hero already say those numbers — the triple narration is gone; the mobile collapsed-header text summary was dropped for the richer metric row); (3) ghost placeholders are unmistakably ghosts — web .ghost-ph::placeholder (dimmer + italic, carved out from the AA instructional-placeholder rule) on the set inputs, mobile ash@53% on the editor value fields (instructional placeholders like the routine name keep full AA ash); (4) the mobile screen gets 110px bottom clearance so the free-slots note can't slide under the floating tab bar's FAB. Web (aurora/builder.tsx + workout-blocks.tsx signal mode) + mobile (aurora/builder.tsx) at parity." },
  { id: "plans-stack-one-object", area: "Core", status: "shipped", title: "Plans stack — one cover at three compressions", detail: "The Plans stack (library root → goal → plan detail) is now ONE physical object at three levels of compression, on both clients. Levels 2 and 3 already shared the full-bleed collapsing CoverScreen/CoverHero scaffold; the ROOT opened with a plain masthead on the page ink, a 22dp coloured marker in front of each goal name (which also read as the decorative before-heading marker the house rule bans), bare mono category kickers instead of the Explore SectionHead, and '0 plans' / '1 plans' on goals with nothing authored. It now rides the SAME scaffold via a third CoverSpec variant, `library`: emblem-sized ghost glyph like the goal cover, but the wash comes from the RIGHT like the plan cover AND runs at a softer mix (34%/10% web, 7a/2e/08 mobile) so the container never out-shouts the nineteen goal accents on its shelves. Its accent is the THEME's own primary (palette.lime — chartreuse on Aurora, pine on Kyoto Hour) rather than an invented brand colour, because no discipline owns \'Plans\'; its glyph is `◈`, the same geometric family as the goal marks and not one of them (guarded by a test). Shared core: `libraryCoverView(goalCount, categories, labels)` builds the cover, `goalShelves(query)` returns filterGoalGroups with each category ordered READY FIRST (goals with plans, then coming-soon, GOAL_TREE order held inside each half) so what sits past the fold is what is not built yet, and `goalCoverView()` gained a `ready` flag so a goal with no programs dims to 45% and says COMING SOON instead of printing 0. EACH CATEGORY IS A FULL-BLEED SHELF — a SectionHead (display-face title, mono count on the right) over a horizontal rail of goal COVERS (Explore\'s PlanCover recipe at 172×140 tile scale, so tapping one expands into the same poster at screen scale), bleeding under the screen edge per the house rule (mobile marginHorizontal -16 + matching padding; web negative --page-pad-x margins). A category can hold ten or twenty goals without the screen growing down. Making a horizontal rail honest about its tail takes four things, all shipped: the head states the COUNT, the goals are sorted ready-first, a hairline TRACK under each rail shows position (native-driven Animated on mobile, direct node writes on web — no re-render per scroll frame), and the CATEGORY CHIPS dock beneath the collapsed bar and JUMP to a shelf. Those chips now navigate instead of filtering: with every category rendered as its own shelf, narrowing to one would just empty the screen, so the category lever is gone and free-text search remains (still the shared filterGoalGroups). The chips ride the scaffold\'s previously-unused `rail` slot on mobile (CoverScreen gained an optional `scrollApi` handle so a rail can scroll the content beneath it) and a `position: sticky; top: 56` nav on web. The web CoverHero\'s back button is now optional — the Plans root is a top-level screen with nowhere to go back to." },
  { id: "plans-root-enrolled-cover", area: "Core", status: "planned", title: "Plans root — the enrolled season as its own cover", detail: "The redesigned Plans root still shows the current season through the old generic EnrolledCard: a small ink2 card with a mono kicker, which looks nothing like the plan it stands for now that everything around it is a cover. Render it instead with the PLAN cover recipe (the plan\'s own accent, glyph and display face) carrying the week you are on, and let the library sit below it as a second section — so the screen opens on what you are doing before what you could do. Needs a week-of-season number the browse screen does not fetch today (the macrocycle response has planStartedAt; the week has to be derived or added server-side)." },
  { id: "no-decorative-dot-headers", area: "Core", status: "shipped", title: "Section headers — decorative marker dots removed (Explore SectionHead standard)", detail: "Per the new CLAUDE.md rule (a small dot/circle/square before a section label reads as AI slop), every decorative before-text marker was removed and the headers converted to the Explore tab's SectionHead vocabulary — a bold display-face title in chalk (web --font-heading 800/18, mobile serifIf F.black 18) with any meta/action as small mono uppercase on the RIGHT of the same row. Swept: Today's first-run chooser head (lime dot → title + right-side 'Free'), Today's RECOVER & MORE head (ash dot + mono kicker → title), Today's GO FULL head (mono kicker → title; the ✦ premium signifier STAYS — it is semantic, not decorative) — all web (aurora/today.tsx) + mobile (aurora/home.tsx) at parity — and the web More springboard cluster headers (pill-nav.tsx: the per-cluster accent square marker removed, label-only like the mobile More tab; the now-unused GROUP_ACCENT map deleted). Semantic dots are untouched by design: status/live dots, mood dots, chart legend swatches, calendar event markers, notification badges. Remaining screens with kicker-style headers (Cockpit, Sport, admin) fall under the design-system-unification-sweep item." },
  { id: "today-first-run-chooser", area: "Core", status: "shipped", title: "Today first-run chooser — 'Three Materials' redesign", detail: "The post-login 'How do you want to start?' state (new user, no plan, no logged history) was redesigned in the Jony-Ive material vocabulary. Five standalone concepts were rendered in reference/start-chooser-design-concepts.html (One Door, Single Slab, Three Materials, Just the Question, One Control) and 'Three Materials' (#03) was chosen: the question becomes an Explore-standard SECTION HEAD (bold display title with 'Free' said ONCE as the mono right-side meta — the three per-row Free badges are gone, per the one-accent discipline on parallel items; originally a dot+kicker, de-dotted same day per the no-decorative-dot-headers rule), and the three free paths wear the Go-Full AccessCard anatomy — corner accent glow, title, growing body, CTA pinned to the bottom in mono uppercase — so the athlete's FIRST decision feels as considered as the paid one. Spectrum-coded: Follow a plan=lime ▤, Build your own=teal ⌗, Just train=sand ↯, with the hue confined to the small glyph + CTA (title/body stay neutral). The floating top-right 'Start →' pill no longer renders in the chooser state on either client (it competed with the choice — each card IS the start; it still serves the athlete AI-prescription state). Copy tightened into card bodies + new chooser*Cta i18n keys (EN/PL/DE); the howStartSub paragraph was retired. LAYOUT FIX (same day, after a live phone screenshot): the chooser renders DIRECTLY on the page — the wrapping today-card (web `card` div / mobile ACard) is skipped in the first-run state, since a box around three cards read as chrome — and the cards are ONE stacked full-width column at natural height on both clients (the web auto-fit grid orphaned the third card 2+1 at phone widths); card surfaces moved to the page-level Go-Full spec (ink2 base, radius 24, padding 20). Web (aurora/today.tsx ChooserCard) + mobile (aurora/home.tsx ChooserCard, LinearGradient corner glow) at parity." },
  { id: "today-living-masthead", area: "Core", status: "shipped", title: "Today masthead — one 'Today' headline that names the viewed day", detail: "The Today/Home opening zone was redesigned (concept 02 of the three-round greeting-zone exploration in reference/greeting-chooser-design-concepts.html + greeting-zone-design-concepts-2/-3.html): the old layout stacked TWO near-equal bold headlines — the greeting (22) and 'How do you want to start?' (18) — four lines apart with a floating 'FREE', so neither won. Now the zone is a MASTHEAD in the App-Store-Today vocabulary: a mono uppercase caption line (viewed-day date left; right slot = 'Free' in the first-run chooser state, or the scrub-distance tag), ONE big display headline (34), and the greeting demoted to a single warm sentence beneath ('Good afternoon, Rafal.'). The first-run chooser's section head is deleted — its three cards need no sentence announcing a choice — and the howStart i18n key is retired (badgeFree moved to the caption line). THE HEADLINE LIVES: it names the VIEWED day, not the screen — scrubbing the plan week rail flips it 'Today' → 'Yesterday'/'Tomorrow' at ±1 → the weekday NAME beyond ±1 (never '2 days ago': clumsy as a headline and badly inflected in PL/DE; the distance rides the caption as a mono tag, daysBack/daysOut). The naming rule is shared core logic (masthead.ts, unit-tested) so the clients cannot drift. Off today the greeting line becomes the teal 'Back to today →' return affordance — same spot every time — which re-anchors both the lifted day scope AND the rail's own selection (new resetToken prop on both week rails). New i18n keys mastToday/mastYesterday/mastTomorrow/backToToday/daysBack/daysOut (EN/PL/DE). Web (aurora/today.tsx) + mobile (aurora/home.tsx) at parity." },
  { id: "profile-private-tab", area: "Core", status: "shipped", title: "Profile — dedicated Private tab", detail: "The profile 'You' screen gained a 4th owner-only tab (Overview / PRs / Activity / 🔒 Private), replacing the always-on 'Private – only you' HPI card that sat under every tab and read as public. Crucially it does NOT duplicate the Cockpit: HPI, readiness and injury-risk live in the Cockpit, so the Private tab's first row is a 'Command center' LINK there instead of a second copy of the score. The tab hosts identity/self-tracking with no other home — Body & progress, Journal (both Full-gated) — plus a link out to Settings for privacy & visibility. REDESIGN: the tab's icon chips are now a single neutral tone (ash), matching the Settings hub's unified TONE so the two owner surfaces read as one system (the previous per-row blue/lime/violet/amber rainbow is gone). The old 'Hidden highlights' block and the static 'Visibility at a glance' card were REMOVED — highlight curation moved to the Overview grid (press & hold a tile → Hide/Show, see profile-private-hidden) and account-level visibility is managed in Settings (Edit profile → who can see your results, + Privacy toggles). Web + mobile at parity. i18n (en/pl/de) w.account.profile.tab-private + priv-* (+ priv-privacy-*). JONY-IVE UNIFICATION (Jul 2026): the tab was re-skinned onto Today's material vocabulary so the owner surface reads as one system with the daily cockpit. The Command center is no longer a flat list row — it now LEADS as a premium HERO card, the twin of Today's 'Go Full' Cockpit bait: an admin-accent glow blooming from the top-right corner (radial + linear premium-accent wash), a crafted accent-tinted icon tile, a serif display title, and a CTA that reads 'Open →' when owned (→ Cockpit) or 'Unlock with Full →' when not (→ /upgrade, fired as FUNNEL.upgradeEntryClick source 'private-cockpit'). GATING FLIPPED: Body & progress and Journal are now FREE for everyone (the old LockedRow '✦ Full' upsell on those two blocks is gone) — the ONLY paid gate on the Private tab is now the Command-center hero (the HPI/readiness/injury-risk intelligence layer, which lives in the paywalled Cockpit). The remaining tool cards (Body & progress, Journal, Privacy & visibility) were re-materialised to match Today's deferred-row anatomy: a crafted icon tile drawn on the darker `ink` with a hairline so it lifts off the `ink2` card, larger radii (20), subtitle-weight titles, and roomier padding. Reuses the shared cardUnlock/cardOpen i18n from Today. Web + mobile at parity." },
  { id: "profile-private-body", area: "Core", status: "shipped", title: "Profile Private — Body & progress", detail: "The Private tab's 'Body & progress' block logs dated weight + tape measurements (BodyMetric table, owner-only RLS — reference/sql-private-tab.sql) via /api/body, shows the latest reading, converts kg/lb for display, and links to the existing progress-photos screen (which now works — its private 'progress' Storage bucket was created via reference/sql-progress-photos.sql). FREE for everyone as of the Jony-Ive unification (Jul 2026) — no longer Full-gated; the Private tab's only paid gate is now the Command-center hero (see profile-private-tab). Web + mobile at parity (PrivateTab component on each). Measurements beyond weight+waist (chest/hips/thigh/arm/…) are accepted by the API and can be surfaced next." },
  { id: "profile-private-journal", area: "Core", status: "shipped", title: "Profile Private — private journal", detail: "The Private tab's 'Journal' block is a working private notes editor (JournalEntry table, owner-only RLS) via /api/journal — compose, list newest-first, delete; never exposed on any follower-facing surface. FREE for everyone as of the Jony-Ive unification (Jul 2026) — no longer Full-gated (the Private tab's only paid gate is now the Command-center hero, see profile-private-tab). Web + mobile at parity." },
  { id: "profile-private-hidden", area: "Core", status: "shipped", title: "Profile Overview — highlight curation (Apple-style edit mode)", detail: "Highlight curation lives on the Overview grid as an Apple-home-screen-style EDIT MODE, replacing the old press-and-hold-then-Hide overlay (which hid a tile on the very next tap, with no undo and no reordering). Now: a plain TAP never hides anything; PRESS & HOLD (~450ms) any tile enters edit mode — every tile WIGGLES and grows a corner '–' button. In edit mode you DRAG tiles to REORDER them (the arrangement persists) and tap '–' to hide a tile, which drops it into a 'Hidden — tap to restore' TRAY below the grid (a chip with a + to bring it back). Done / Esc / tap-away leaves edit mode. Each tile carries a stable key — 'pr:<lift>', 'streak', 'sessions', 'tonnage', 'badges'. Reorder is pointer-driven with no DOM reshuffle mid-drag (snapshot each slot at grab, translate neighbours toward the vacated slot, commit once on drop); mobile uses the RN built-ins (PanResponder + Animated) with NO gesture-handler/reanimated dependency, so parity holds without new native deps. Persistence: hidden keys → HiddenHighlight; the arrangement → the new HighlightOrder table (one row per user, ordered key list; owner-only RLS), both via /api/highlights (POST { key, hidden } or { order }). The grid reconciles the saved order against the tiles that currently have data (known keys keep order, newly-earned keys append). Web reorder algorithm verified in headless Chromium; web typecheck + mobile iOS bundle export green; i18n ov-done / ov-restore / ov-edit-hint (EN/PL/DE). Web + mobile at parity. FOLLOW-UPS: (1) the follower-facing renderer should honour the hidden set server-side (service-role) — today the filter runs on the owner's own screen; (2) reorder PERSISTENCE needs the HighlightOrder table — run reference/sql-private-tab.sql section 4 in the Supabase SQL Editor (the API degrades gracefully to a non-persisted, in-session arrangement until then)." },
  { id: "premium-accent-sand", area: "Core", status: "shipped", title: "Premium upsell accent → sand (was violet)", detail: "The colour that ENCOURAGES BUYING FULL was migrated from violet to SAND/amber (#d0cd94 — the brand's `--amber-text` / `C.amber` / accentText.amber) across BOTH clients at parity, so the upgrade cue no longer collides with the lime everyday-action accent and reads as a distinct premium tier. Surfaces recoloured: the Today 'GO FULL' Cockpit/Sport bait cards + section ✦ (web today.tsx / mobile home.tsx); the upgrade paywall sheet — ✦ Full badge, benefit bullets and the primary CTA button, whose ink is now a theme-fixed near-black (#141614) because sand is a LIGHT fill in BOTH themes, unlike the theme-flipping `ink`/`onAccent` (web + mobile upgrade.tsx); the Train AI-coach PremiumHero + locked-routine 'Full' badge; the Nutrition AI-scan bait + locked meal-preset tiles + ✦ Full badges + lock icon + premium-tier chip; the free-user 'AI session' upsell pill (web logger.tsx / mobile app/workout.tsx — mobile brought to web parity: sand only for FREE users, lime for already-unlocked athletes); and the More springboard premium lock badge (web pill-nav.tsx / mobile more.tsx). SCOPE: only buy-premium usages changed — the coach/role + data-series violet usages stayed on the violet token (then recoloured wholesale, see coach-accent-steel). Both typechecks green." },
  { id: "premium-accent-admin", area: "Core", status: "shipped", title: "Admin-configurable premium-CTA colour", detail: "The accent every 'buy Full' CTA wears is now ADMIN-SETTABLE at runtime (no redeploy), not hardcoded sand. Source of truth: packages/core/src/premium-accent.ts — a `theme.premiumAccent` feature flag whose value is a brand-palette key (amber/violet/lime/blue/red) or a custom #hex; `resolvePremiumAccent(value, theme)` returns { fill, text, ink } (ink auto-picked near-black/white for contrast on the fill), with `normalizePremiumAccent` (validates + expands #abc→#aabbcc) and `wcagRating` for the checker. Reuses the existing feature-flag override storage + /api/flags read (no new migration). WEB: globals.css defines `--premium-accent` / `--premium-accent-text` / `--premium-accent-ink` (default → amber); `<PremiumAccentStyle>` (mounted in app-shell) restamps them on <html> from the flag — presets point --premium-accent-text at the theme-aware `--<key>-text` so it still flips light/dark, a custom hex is used verbatim. Every premium surface (Today Go Full cards + ✦ + [note], upgrade sheet badge/benefits/CTA, Train PremiumHero + routine badge, Nutrition scan/locked-tiles/Full-badges/lock/tier-chip, the free-user AI pill, the More upgrade card + springboard lock, the ⌘K hub lock, builder routine-unlock, profile HPI-locked CTA) reads those vars instead of --amber-* — so one setting recolours them all live. MOBILE: the flags store now also holds config VALUES (fetchFlagState) + a `useFlagValue` hook; `usePremiumAccent()` (lib/premium-accent.ts) resolves { fill, text, ink } for the theme, and the same premium surfaces read it instead of C.amber. ADMIN: the Flags panel renders a colour picker for this flag — palette swatches + a custom-hex input + a LIVE WCAG readout (ratio + A/AA/AAA) for the two pairings that matter (accent-as-text on the card, and the auto-ink on a solid button), so a hex that fails contrast is flagged before it ships. Non-premium sand/amber (Plan section, caution states, calendar events, macro chart colours, the free-trial note) is untouched. LATE ADD: the Profile → Private tab's locked-feature '✦ Full' pill (LockedRow on Body & progress + Journal) was the one buy-Full CTA still hardcoded lime — it now reads the premium accent too (web: var(--premium-accent-text) + a premium-tinted border; mobile: usePremiumAccent().text/fill), so the Private-tab upsell matches the Today Go-Full cards. (SUPERSEDED Jul 2026 by the Jony-Ive unification — Body & progress and Journal are now FREE, so those two LockedRows/'✦ Full' pills were removed entirely; the premium accent now dresses the Private tab's Command-center HERO card instead, see profile-private-tab.) 9 new core tests; both typechecks + 716 core tests green. NOTE: the flag override persists only once reference/sql-feature-flags.sql is applied in Supabase; until then it runs on the amber default." },
  { id: "coach-accent-steel", area: "Core", status: "shipped", title: "Non-premium violet → steel/slate blue", detail: "After the premium cue moved to sand (premium-accent-sand), the `violet` token was used ONLY by non-premium surfaces, so its VALUE was repurposed in one place — from lavender #c9a9f0 to a steel/slate BLUE — recolouring every remaining usage at once on both clients while keeping all multi-series chart hues distinct. New values (mirrored across tokens.ts colors.violet, palette.ts THEMES.*.accentText.violet, and web globals.css --color-violet/--violet-text for both themes): fill #8296c4; accent-TEXT #8ba0cc on dark / #4c5a78 on light (both clear WCAG AA on the card — guarded by palette.test.ts). This flips, in a single token edit, the coach identity (analytics roster/coach stats, admin COACH role + coach applications, financials coach segment, talent, team compare/monitor, coach-rail, calendar coach-assignment dots), the data-series 5th hue (fat macro, the 'mobility/other' exercise kind, the 5-zone velocity scale, HPI recovery, org ANALYST), the social nav section accent, the Cockpit season/phase progress, and the profile avatar/cover gradients. Hardcoded lavender literals were caught too: periodization Taper/Peak phase colours and the plans.ts VIOLET discipline colour (power/strongman/bodybuilding/tactical/sport). Steel is distinct from the teal `blue` token, so segment charts that show coach next to org (blue) don't collide. Also fixed: semantic.ts ROLE_COLOR.premium 'violet'→'amber' (+test) so the vocabulary reads premium=sand; and a premium lock badge in the web ⌘K hub (app-shell.tsx) that was still on violet was moved to sand. NAMING CAVEAT: the token/AccentKey is still keyed `violet` (renaming it touches ~40 direct call-sites + the type union) — the key is legacy, the value is steel; comments at each source flag this. Both typechecks + core tests (incl. the AA contrast guard) green." },

  // ---- Web ----
  { id: "web-deploy", area: "Web", status: "shipped", title: "Web app on Vercel", detail: "Next.js App Router, auto-deploys from main. Landing + login + authenticated app shell." },
  { id: "ui-template-aurora-web", area: "Web", status: "shipped", title: "Aurora template — bespoke per-screen layouts (web + mobile)", detail: "Aurora ships a DEDICATED, hand-crafted layout for the large majority of screens on BOTH clients (not just the global skin) — each route renders its Aurora variant when the template is active and the classic screen otherwise, all on the SAME data/engine/API logic so there's no feature loss. Coverage: AUTH/ONBOARDING (Welcome, Login/Register, Onboarding); HOME/ACCOUNT (Home/Today — now at FULL cockpit parity with classic: a horizontally-swipeable Plan-today + AI-coach pager with page dots, the season phase timeline, the reconciled This-week plan with schedule/re-sync + intensity/volume/load×/volume× + the exercise list, accountability, the weekly recap (tap → Statistics), and the Athlete-Twin + injury-risk-by-tissue panel — web reuses the shared ReconciledWeek, mobile mirrors it inline; Settings, Notifications); RECOVERY (Check-in, Nutrition, Progress, Longevity, Connections, Roles); ANALYZE (Statistics, Cockpit, Performance, Volume, Exercises, Trends, Velocity, Running, Force-plate, Video, History, Calendar) — the chart-heavy screens included, reusing recharts on web and the native bar/line primitives on mobile; TRAIN (Plans, Sport, Competition, Periodize, Builder [web + mobile], the Train launcher, and the Logger). IN-PLACE (template-aware radii/pills on the existing component, NOT a bespoke fork — a deliberate, lower-risk skin) rather than dedicated layouts: the mobile LIVE logger (app/workout.tsx — Aurora pills via auroraRadii AND, on Aurora, the ambient violet+lime blob field rendered behind its sticky-timer shell + the completion Summary, via the now-exported AuroraField from the kit, so the logger no longer reads as a flat classic screen in Aurora) + the mobile SESSION-DETAIL review (app/session/[id].tsx — previously always-classic with no template awareness, now wraps its body in AuroraScreen on Aurora / the classic Screen otherwise, with its PR/cardio banners + share CTA rounded to the Aurora pill/card radii) + mobile logger-settings + mobile More hub; the web account Settings (6-tab MFA/billing area); the web ADMIN console (operator-only, /admin, ~8.7k lines across 23 tools — its panel SHELL is template-aware pill nav + rounded chrome, the shared lib/ui --r-* radius tokens under [data-template=\"aurora\"] round the section bodies' cards/inputs/selects, AND the ~73 hardcoded structural borderRadius literals across the 19 tool files were converted to the same --r-card/--r-field tokens so no admin surface stays sharp-cornered next to the rounded shared components in Aurora — pills/dots/bars kept literal); and the multi-scope ANALYTICS hub (athlete/coach/operator dashboards — the scope toggle pills + every Card/ChartFrame/Stat tile round via the shared --r-card var, so the dashboards are Aurora-consistent without 3 risky recharts rewrites). The mobile Builder is a real route (apps/mobile/app/builder.tsx, reached from Train) with classic + Aurora variants. Components live in apps/web/components/aurora/* and apps/mobile/components/aurora/*; COACH surfaces are bespoke on BOTH clients: web AuroraCoach (full roster/invite/consent + ClientDetail programming), AuroraAskCoach (wired into Aurora Today), AuroraUpgrade, AuroraOrg, AuroraTalent, AuroraTactical, AuroraTeamCompare, AuroraTeamMonitor (gated in app-shell); mobile Aurora Coach tab, ai-coach, coach-apply, tactical, talent, upgrade. Icon set (theme/icons.ts) wired across both. BOTTOM NAV (mobile): Aurora's mobile navigation is a bespoke floating pill bar (Today(grid) – Cockpit(chart, athlete-only) – Train(add) – History(calendar) – More(settings)) shown on EVERY screen — not just the main tabs. apps/mobile/components/aurora/global-nav.tsx is rendered once at the ROOT (app/_layout.tsx) and is router-driven (useSegments for the active tab, router.navigate to switch), so it floats over pushed sub-pages (Statistics/Settings/Periodize/…) too; the per-Tabs Aurora bar is retired (Tabs tabBar → null in Aurora) so there's no double bar, and the classic glass bar + 'jump to' command orb render for classic only. It self-hides on auth/funnel + the live-workout screen. Each pill now carries a TEXT LABEL under its glyph (Today/Cockpit/Train/History/More) so the cog-glyphed 'More' tab no longer reads as 'Settings' and the active tab is unmistakable. The home GRID + statistics CHART glyphs are drawn from primitives (no extra asset); the rest use the shared Aurora line-icons. MOBILE AURORA POLISH (home/nav/overlap fixes): (1) the Today Plan-today⇄AI-coach pager aligns cards to the top so a shorter card keeps its natural height instead of stretching to the taller card's height (no more mostly-empty tall Plan-today card); (2) the Today 'Ask your coach' card embeds the AI-coach NOTE inline (AuroraAiCoach `embedded` prop renders just chips+text+Ask-again) instead of mounting the whole AI-coach SCREEN inside the card, which previously double-wrapped a header/back/inner-card; (3) the root Stack disables the back GESTURE on the (tabs) shell so the iOS edge-swipe can't pop the app back to Welcome/Login (which had looked like a sign-out, since welcome→login→replace-to-tabs leaves welcome underneath); (4) the shared Screen + AuroraScreen scroll primitives reserve ~132px bottom padding in Aurora so the floating pill nav never covers the last row (share buttons, sign-out, the Builder CTA on Train); (5) the More hub is reorganised — Settings is PINNED to the top (with the role/entitlement summary) rather than buried at the bottom, and BUILDER is a first-class entry in the More → Plan group (in addition to its existing Train-launcher entry), so composing a routine is reachable from the hub too. MORE-HUB DESIGN PASS (springboard, both clients): the section destinations now render as an iOS-style SPRINGBOARD GRID of rounded glyph tiles (the shared design-kit line icon per nav id via AURORA_NAV_ICONS, label beneath) instead of the old two-up cards with PER-ITEM coloured label text — fixing the 'rainbow text' inconsistency: every tile label is one chalk colour, the lime accent is reserved for the single Unlock-Full card + the active tile. UNLOCK FULL is reshaped from a thin pill into a premium 'membership card' (UPGRADE kicker → title → value line → 'Go Full →' pill, with a soft lime corner-sheen + glow). Mobile: apps/mobile/app/(tabs)/more.tsx (Settings + Athlete-cockpit rows neutralised to chalk with a glyph tile; springboard Tile component). Web parity: the AuroraPillNav 'More' sheet (apps/web/components/aurora/pill-nav.tsx) renders the same springboard tiles + the same Unlock-Full membership card (casual only, → upgrade screen). A SECOND audit pass fixed more of the same classes: (6) KEYBOARD AVOIDANCE — no mobile screen had any, so the keyboard covered low inputs/submit buttons; the shared Screen + AuroraScreen primitives (and the live workout logger) now wrap their scroll body in a KeyboardAvoidingView (iOS padding) with keyboardShouldPersistTaps, fixing every form screen (login/builder/check-in/nutrition/settings/talent/…) at once; (7) the 'builder' nav id was missing from the mobile More hub's MOBILE_NAV_IDS set, so athletes saw 'Builder' wrongly listed under 'More in the web app' even though mobile has a real Builder route — added it; (8) the Aurora Home header SEARCH button was a bare View (looked tappable, did nothing) — wired to the searchable Exercises browser, matching the working bell→Notifications next to it. AURORA DESIGN PASS (both clients, applied to the Today/Home hero): (#1) the greeting is demoted to a single quiet line so the readiness-bearing plan is the hero, not the user's own name; (#2) the AI-coach PROSE renders in the Archivo display sans (mono stays for chips) so a personal note reads like a coach, not a terminal log; (#3) headline numbers are now GLANCEABLE — readiness shows as a dial (mobile: dependency-free tick-ring via the kit `Ring`; web: a conic-gradient ring) and the Athlete-Twin HPI carries a 14-day SPARKLINE (`Spark`, from performanceTrajectory); (#4) colour SEMANTICS are locked in one shared vocabulary (packages/core/src/semantic.ts — role map go/info/premium/caution/danger/neutral + unit-tested readinessRole/hpiRole/riskRole/accountabilityRole/phaseRole), and the Today screens resolve every state colour through it so web+mobile can't drift; (#5) finishing a workout is a felt MOMENT — the mobile summary fires a success haptic (a heavier knock for a PR/first) and springs/fades the hero badge + PR card in; web wins pop-in on the Today recap (globals.css .win-pop, reduced-motion aware); (#6) the floating-nav clearance magic number was centralised in apps/mobile/lib/layout.ts (AURORA_NAV_BAR_HEIGHT + auroraScrollClearance) and the screen primitives derive bottom padding from the real bar height + safe-area inset, so a bar change can't re-hide content. Remaining screens migrate to the shared semantic helpers + Ring/Spark incrementally. DESIGN-FIDELITY AUDIT (vs the reference Aurora design): (A) the classic LEFT-ACCENT STRIPE (a card's coloured left rail — the classic HYBRID signature, used 0× in the reference aurora-preview.html, 21× in the classic HybridApp.jsx) was carried over onto Aurora cards; removed every card-accent stripe across BOTH clients (13 mobile + 24 web), including the conditional/semantic ones — each already conveys its state via a chip or coloured value (private-note chip, tactical GO/NO-GO chips, application-status text), so no information was lost (one blockquote-style indent on the check-in coach reply is kept — it's a quote treatment, not a card rail). (B) SKINNED→BESPOKE pass: (i) mobile logger-settings is now a dedicated components/aurora/logger-settings.tsx (AuroraScreen + ACard + ASegment segmented pills); (ii) the mobile More hub renders inside AuroraScreen; (iii) the mobile LIVE logger (already pill/rounded-card Aurora via auroraRadii) had its last hardcoded sharp corners (custom-exercise input + set-type/superset/work-rest/load-bump toggles) routed through the Aurora field-radius token; (iv) the web account Settings (6-tab MFA/billing — deliberately NOT forked) had its control radii aligned to the web Aurora tokens (--r-field 14, --r-card 24). The web ANALYTICS hub and the ~8.7k-line ADMIN console were CONFIRMED already Aurora-rounded via the shared token system ([data-template=\"aurora\"] sets --r-card:24/--r-field:14 and rounds .rounded-* + inputs; 17/22 admin tool files consume var(--r-card)/var(--r-field), the rest use Tailwind rounded-* which the Aurora overrides round) — a bespoke recharts/operator-tooling fork stays out of scope as the explicitly higher-risk, operator-only path. (C) TOKEN FIDELITY: verified our Aurora against reference/aurora-preview.html — colour tokens, type (Archivo + JetBrains Mono), the pill/segmented/choice/field/back/avatar primitives and the violet+lime blob field all match; the one drift (web corner radii had shrunk to --r-card 24/--r-field 14) was corrected to the reference's 28/16 across globals.css + the 21 hardcoded web card radii + the mobile Card primitive, so card=28/field=16/pill=999 is now uniform on both clients. (D) The reference is a design LANGUAGE + a few hero screens (auth/onboarding/home), so the other ~40 screens are a faithful EXTRAPOLATION of that language (same tokens/primitives/icons), not pixel copies — no foreign design system is used. (E) MODERN BEYOND THE REFERENCE (deliberate): the bottom nav is now LIQUID GLASS (mobile BlurView intensity 28 + translucent film + rim; web backdrop-filter blur(18px) saturate(1.2) over a 62% ink2 tint) — lighter than the classic glass and glassier than the reference's near-solid rgba(20,22,20,.92) bar; plus the readiness dial, HPI sparkline, finish haptics/animation already shipped. (F) FURTHER MODERN pass: (a) MOTION — content fades + rises (~10px) on every screen ENTRY, reduced-motion aware: mobile AuroraScreen + Today home wrap their body in an Animated.View driven by useFocusEffect (replays on pushes AND tab switches), web uses a key={screen} wrapper + .aurora-enter keyframe in the app-shell; (b) DEPTH — a soft low shadow on key cards (mobile ACard + the raw home cards; all 36 web Aurora card surfaces), far lighter than the classic glass shadow; (c) a real BESPOKE Aurora ANALYTICS dashboard for all three scopes (components/aurora/analytics.tsx — AuroraAthleteAnalytics/CoachAnalytics/OperatorAnalytics: accent-dot stat tiles, pill-framed brand-coloured recharts, a rounded roster/PR table), wired into the app-shell analytics screen in Aurora, reusing the exact sessions/roster/admin-stats data + engines (classic kept for the classic template). The bottom nav is also now LIQUID GLASS on both clients (mobile BlurView + film + rim; web backdrop-filter blur). Web production build green. WEB NAV: web keeps the left SIDEBAR at all times — in BOTH templates and on every screen (Aurora rounds it in place via the global skin; it is never replaced by a bottom bar), matching the uploaded HybridWeb sidebar design. In Aurora the app-shell drops its top page-title header (the bespoke Aurora screens render their own header, so this prevents a doubled title) and hides the ⌘K command orb (the sidebar is the nav — no floating circle); Classic keeps both. The theme/lang controls stay top-right in both. Aurora web screens fill a fuller content width (≈1000) rather than a narrow centred column, so they don't look stranded on desktop. Aurora web shows BOTH the sidebar AND a floating bottom pill bar (apps/web/components/aurora/pill-nav.tsx — Today – Cockpit – Train – History – More, More opens the full persona-filtered nav sheet); the ⌘K orb is Classic-only. ICONS: every nav glyph in Aurora comes ONLY from the uploaded design kit (icons1/2/3) — theme/icons.ts AURORA_NAV_ICONS maps EVERY nav id → an AuroraIconName, and 19 kit icons were wired into the shared set (SVG path data + mobile PNGs + the RN require map): bookmark, list-check/play/add, calendar-event, user-circle/add/square, store, globe, swap, village, gps, info, offer, check-circle, download, copy. No unicode/emoji glyphs remain in the Aurora nav; the kit is a generic UI set, so a few fitness/analytics items reuse the nearest icon (e.g. arrow-up for the trend metrics). Reaching a tool from Aurora Today (bell/Your-week) navigates IN-SHELL (keeps the sidebar + bar). Classic keeps its unicode glyphs + sidebar + ⌘K orb unchanged. The three lightweight TOOLS (Statistics, Interval timer, Notifications) are NOT Aurora-only — they ship in BOTH templates (template-aware radii/back glyph) and are first-class nav items (web sidebar + ⌘K via app-shell embedded screens; mobile More → Tools), reachable by the default Classic/casual user; the standalone web routes (/statistics, /timer, /notifications) remain for landing deep-links. iOS bundle export green; web + mobile typecheck clean. AURORA IS THE ONLY template on both clients (DEFAULT_TEMPLATE='aurora', TemplateName='aurora') — it's the main HYBRID look; the Classic skin and its Settings switcher were removed, and the dead classic screen variants described above no longer exist (see ui-templates). Also fixed: the mobile login race where the first sign-in attempt bounced back to /login — the login screens now navigate only once the Supabase session is live in context (a session-gated effect), so the first attempt lands reliably. RUN TRACKING shipped as a real PLACEHOLDER on both clients (nav id 'runtrack', train group, casual-visible): apps/web/components/run-track.tsx + aurora/run-track.tsx and apps/mobile/app/run-track.tsx + components/aurora/run-track.tsx — a live-run surface with a placeholder route map (clearly flagged 'live GPS lands with the native build') plus a working stopwatch + manual distance → derived pace (pacePerKm) that saves a real cardio session via /api/sessions. Reached from the web sidebar, the mobile More hub + command menu. The only piece still pending is the native GPS route MAP itself (needs expo-location + a map lib via an EAS build — can't be built/validated in this sandbox); it drops into this same screen without changing the save logic." },
  { id: "ui-aurora-stats", area: "Core", status: "shipped", title: "Statistics screen (session stats)", detail: "The Figma Statistics screen built for real on BOTH clients off REAL data. @hybrid/core stats.ts sessionBuckets groups logged sessions into Week (7 daily) / Month (5 weekly) / Year (12 monthly) buckets with window totals, active-day count and the peak bucket, unit-tested; empty history → all-zero buckets + honest empty state. Mobile app/statistics.tsx + web components/statistics.tsx render a Week/Month/Year segmented bar chart plus summary cards (active days, HPI, distance, minutes) from sessionBuckets + weeklyRecap + computePerformanceState. Available in BOTH templates (template-aware radii/back glyph, not Aurora-only): web is a first-class nav item (sidebar + ⌘K, embedded in app-shell) AND the /statistics route (landing deep-link); mobile is reached from the Aurora Home readiness hero AND the More → Tools section (so Classic users get it too). iOS bundle export green." },
  { id: "ui-aurora-timer", area: "Core", status: "shipped", title: "Interval timer (work/rest stopwatch)", detail: "A real interval timer — the Figma 'Workout' screen built for real on BOTH clients. @hybrid/core interval.ts is the pure engine (buildIntervalPlan expands rounds×work/rest with a lead-in and drops the trailing rest; locateInterval maps elapsed seconds → active phase + remaining; formatClock mm:ss), unit-tested. Mobile app/interval-timer.tsx + web components/interval-timer.tsx run the identical engine: 10s lead-in, work/rest cycling, round counter, progress ring + session bar, play/pause/reset and rounds/work/rest steppers. Available in BOTH templates (template-aware radii/back glyph, not Aurora-only): web is a first-class nav item 'timer' (sidebar + ⌘K, embedded in app-shell) AND the /timer route (landing deep-link); mobile launches from the Aurora Home (conditioning items → timer, strength → logger) AND the More → Tools section (so Classic users get it too). iOS bundle export green." },
  { id: "ui-aurora-activity", area: "Core", status: "shipped", title: "Notifications / activity feed", detail: "A real notifications feed (not mocked) — @hybrid/core activity.ts buildActivityFeed turns the athlete's REAL logged sessions + coach-assigned workouts into a sorted list (upcoming workouts first, then recent completed within a 14-day window; relativeTime formats 'in 2d' / '1h ago'), unit-tested; empty data → empty feed (honest, no fabricated entries). Mobile app/notifications.tsx and web components/notifications.tsx render it from each client's data. BOTH clients now feed sessions + coach assignments (web fetches /api/assignments, matching mobile — parity, no longer sessions-only). Available in BOTH templates (template-aware radii/back glyph, not Aurora-only): web is a first-class nav item 'notifications' (sidebar + ⌘K, embedded in app-shell) AND the /notifications route (landing deep-link); mobile is reached from the Aurora Home bell AND the More → Tools section (so Classic users get it too)." },
  { id: "profile-you", area: "Core", status: "shipped", title: "Profile (\"You\") screen + bottom-nav redesign", detail: "A dedicated athlete PROFILE on BOTH clients — mobile apps/mobile/components/aurora/profile.tsx (the /(tabs)/you route) and web apps/web/components/aurora/profile.tsx (wired into app-shell as the 'profile' screen). Apple-ID / Tesla-account styling on the HYBRID brand tokens: a centered account hero (avatar + edit badge, FULL/FREE tier chip, 'HYBRID ID – email', member-since), a hairline SPEC strip (HPI / Streak / PRs), a premium membership ID CARD (etched, lime sheen, athlete-id hash, no PII), an oversized HPI HERO with a 12-bar trace (performanceTrajectory) + band + pillar delta, a year-of-training HEATMAP, an ACHIEVEMENTS rail, top PERSONAL RECORDS, and athlete MODULE tiles (readiness / body / devices / coach). EVERY metric is REAL, computed in @hybrid/core from logged sessions + recovery signals (computePerformanceState, performanceTrajectory, trainingHeatmap, computeAchievements, lifetimePrCount, longestWeekStreak, streak, topLoadMap (top PRs now rank + read the athlete's HEAVIEST actual lift per movement, not an estimated 1RM — e1RM stays only as the strength-club achievement basis), sessionVolume); empty history degrades to honest empty states (no fabricated numbers). ACHIEVEMENTS are real, tiered, earned/locked milestones — strength club (max e1RM), consecutive-week streak, session count, lifetime tonnage, PRs broken, furthest run — pure + unit-tested (engines/achievements.ts + heatmap helper in engines/calendar.ts, lifetimePrCount in engines/records.ts). NAV REDESIGN (both clients, Aurora): the floating bottom bar is Today – Plans – [Train] – History – More — Cockpit moved into the More hub (still reachable there) and Train became an ELEVATED centre FAB (raised circle + dumbbell glyph). (The bar originally ended in a 'You' profile pill; once the Today-header redesign added a profile avatar, that pill was redundant and was swapped for Plans — see today-header-redesign. Profile is still reached from the header, the web sidebar/More-sheet, and a pinned card atop the mobile More hub.) mobile components/aurora/global-nav.tsx + web components/aurora/pill-nav.tsx. Mobile typecheck + iOS export green; web typecheck + production build green. NAV ENTRY (fix): web now also exposes Profile as a sidebar nav item (NAV_ITEMS, account group, every persona) with an Aurora user-circle glyph + nav.profile i18n (EN/PL/DE), so it's reachable from the desktop rail / ⌘K — previously it was ONLY on the Aurora 'You' pill, so desktop users had no way in ('on web there is no profile'). SOCIAL PASS (both clients, at parity): the profile was reorganized into a social layout — a cover banner, an avatar overlapping it with an EDIT (pencil) icon button (the old 'Edit profile' + 'Share' buttons removed; editing routes to /profile-edit on mobile and the settings surface on web), name + FREE/FULL membership pill (unchanged), bio + a quiet HYBRID-ID line, a Followers/Following/Rank counts row (rank derived from the real leaderboard endpoint), tabs (Overview / PRs / Activity) and a 3-column PUBLIC highlight grid built ONLY from real public stats (top PRs, streak, sessions, tonnage, badges; tiles with no real datum are omitted, never faked). PRIVACY: HPI is now PRIVATE — deliberately absent from the public grid and every follower-facing surface; it lives only in a 'Private – only you' card at the bottom (gated by canSeeHPI: the score for Full, the locked upsell teaser for free). mobile aurora/profile.tsx + web aurora/profile.tsx, still at parity. PARITY/FIDELITY HARDENING: audited 1:1 and against the mock — every new label moved to w.account.profile.* i18n (EN/PL/DE); mobile HPI empty-state now shows unrated/'—' (was a fabricated score) and the HPI trajectory window is aligned to 30d on both; the avatar lime ring, per-tile Overview icons and 96px cover were restored to match the mock. The edit affordance is an icon (the shared 'settings' glyph — a pencil PNG asset is a blocked follow-up), never an Edit/Share button." },
  { id: "today-header-redesign", area: "Core", status: "shipped", title: "Today tab header redesign — profile – HYBRID logo – notifications", detail: "Step 1 of a step-by-step Today-tab redesign. The pre-workout top of Today now opens with a dedicated brand HEADER on BOTH clients (apps/mobile/components/aurora/home.tsx + apps/web/components/aurora/today.tsx), replacing the old quiet greeting + search/bell row: a profile AVATAR on the left (initials on a lime-tinted, theme-aware square with a lime 'live' dot — opens the You/profile screen), the centred HYBRID. wordmark with a short lime accent rule beneath it, and a NOTIFICATIONS bell on the right carrying a live count badge. The badge is REAL — driven by the shared activity feed (buildActivityFeed over the athlete's logged sessions [+ coach assignments on mobile]; capped at 9+), never a fabricated number, and hidden at zero. Squared (radius-14) icon containers are the new Today-header treatment. The in-header Exercises SEARCH shortcut was removed per the redesign brief (Exercises stays reachable from its own route/nav). New shared i18n key w.home.today.profileAria (EN/PL/DE). Five standalone design options were explored in reference/today-header-mockups/ and Option 5 (compact, centred logo + lime accent, count badge) was chosen. BOTTOM-NAV DEDUP (follow-up): putting profile in the header made the bottom-bar 'You' pill redundant, so it was swapped for PLANS on BOTH clients — the bar now reads Today – Plans – [Train] – History – More (Plans beside Today, More on the far edge as the conventional last slot). Plans is casual-visible and the core 'follow a program' loop, previously buried in More. Profile stays reachable everywhere: the Today-header avatar, the web sidebar + More-sheet Account group, and a new pinned PROFILE card at the top of the mobile More hub (avatar initials + name + role → /(tabs)/you) so it isn't stranded on non-Today screens where the header isn't shown. Core tests + mobile typecheck green; web today.tsx/pill-nav typecheck clean (pre-existing Prisma-codegen errors are sandbox-only). MORE STEPS PLANNED — this only redesigns the header + the nav dedup; the rest of the Today tab is refined in subsequent steps. THE LOCKUP (the centring fix, both clients in one change): the header row was `space-between` with the wordmark as its middle child, which centres that child only when both flanks weigh the same. They never did — one 44px avatar tile on the left against the day-streak PILL plus the bell on the right — so the brand rendered ~69px LEFT of the screen's centre on a 390pt device and slid further with every digit the streak gained. Pinning the wordmark to the centre instead was measured and REJECTED: at a 12-day streak on 390pt it drives the wordmark 44px INTO the pill. The row is now a THREE-COLUMN grid with FIXED FLANKS — web `grid-template-columns: 44px 1fr 44px`, mobile fixed 42dp sides with a `flex: 1` centre column — so the wordmark is centred BY CONSTRUCTION, whatever the flanks carry. The streak LEFT THE ROW and became the lockup's second line: a hairline mono caption directly under the wordmark (9.5, .13em, uppercase, terracotta accent-text, flame glyph at 11) tapping through to the same done sheet the pill opened. It therefore survives on all three hub tabs (they render this one header), and it costs NO height — wordmark 19 + caption ~17 still sits inside the 44px/42dp the tiles already set, so the header's height is unchanged. A zero streak renders the wordmark alone. NO new i18n keys: the caption reuses w.home.today.dayStreak, uppercased at the leaf so PL/DE inherit it. Three directions were drawn to true device scale and self-measured in the design artifact (current −69px; the pinned-centre collision; the three candidates at 0px) and the LOCKUP was chosen. This SUPERSEDES the terracotta streak pill in the header row described by today-focus-hierarchy." },
  { id: "exercise-table-bounds", area: "Core", status: "planned", title: "Trends exercise table \u2014 bound it and virtualize it", detail: "exerciseTable(sessions, \"all\") returns EVERY exercise the athlete has ever logged, with no cap and no virtualization, and builds each row with a per-exercise exerciseDashboard() pass over the full session history \u2014 the heaviest single call in the app, at the bottom of a scroll. It left the Performance tab with the rest of Trends (performance-six-surfaces), so it no longer terminates a hub tab, but on its own screen it is still a hundred-plus rows for a two-year athlete. Wanted: a bounded default view (top movements by recency or volume, with 'show all' beneath), a bounded default period rather than 'all', and FlatList/FlashList virtualization on mobile (see mobile-list-virtualization)." },
  { id: "performance-six-surfaces", area: "Core", status: "shipped", title: "Performance rebuilt \u2014 twenty surfaces to six", detail: "An element-level audit of the Performance tab (audit/10-performance-tab-element-audit-2026-08.md, mockups in design/performance-tab-before-after.html) judged 26 elements across 20 card surfaces and found the page had become an archive: Volume and Trends, absorbed whole by `performance-unified`, took roughly 68% of the scroll against 16% for the four blocks that answer 'how am I doing right now', and eleven cards restated a neighbour or belonged on a screen of their own. FOUR DEFECTS FIXED FIRST, all of them places where the page contradicted itself. (1) The headline HPI figure applied the wearable's \u00b115 adjustment while the sparkline beside it and the whole trajectory chart came from performanceTrajectory() \u2192 computeHpi(fatigue) with NO biometrics \u2014 two numbers for the same day, 8px apart; same split on readiness (the ring read prescribeSession's bio+subjective score, the chart's series neither). performanceTrajectory now takes `bio` and applies it to the daysAgo===0 point only (there is no stored wearable history to replay, and today's point is the one the card also prints as a figure), and both clients compute the series ONCE instead of twice. (2) 'Your week' counted a rolling seven days while the sibling hub tab's 'This week' counts Monday\u2192Sunday \u2014 the card is cut and its PRs moved to Today's activity card via a new range-aware prsBetween(), so a month view lists the month's records. (3) HPI is 100\u2212fatigue: it rises on a deload and rises further on a layoff, with a top band called 'peak'. It is now LABELLED for what it measures \u2014 Freshness \u2014 and joined by the half a performance screen was missing: capabilityTrend() (engines/capability.ts), which splits an 8-week window in half and compares each movement's best e1RM (up is better) and best pace (down is better) across the halves, counting only movements present in BOTH halves and never mixing the units. (4) STR/END/REC rendered as three peer figures across two scales; recovery is a \u00b115 additive and now rides the headline as a signed contribution instead of impersonating a third index. THE PAGE, both clients: masthead with one computed VERDICT sentence (stateVerdict(), freshness band + the flagged tissue) replacing a subtitle that described the page rather than the athlete, and two chips instead of four \u2014 the HPI and ACWR pills were previews of a card within reach; YOUR STATE, the one block that grew (300\u2192430px), carrying freshness, the wearable's signed share, the limiter as a display-face SENTENCE with the top driver behind it (the Breakdown card's one unique line), two freshness columns, the capability row, the 14-day plot and readiness untouched; TISSUE; this week's VOLUME hero + a door; SEASON as one card; and five exit rows each carrying a live value. CUT: 'Your week', the Breakdown tabs (three of four panels duplicated the exit rows verbatim from the same runTotals()/velocityProfiles() calls), the band glossary, and all four group markers \u2014 six blocks in a deliberate order need no signposting. THE PLOT IS SHARED GEOMETRY: trajectory-plot.ts (trajectoryPlot / sessionDaysAgo, 11 tests) returns paths, a zoomed-and-STATED domain snapped to tens, and a mark per day that carried training \u2014 a dip you cannot attribute is decoration with axes. It also closed a parity drift: mobile had been approximating the chart with bars and per-day markers while web drew a recharts line, so the same fourteen days had two shapes and only one could be read per point. Both clients now stroke the same paths (react-native-svg was already in the app for the injury mannequin), and recharts is off this page entirely. MOVED, NOT DELETED: Volume and Trends are DESTINATIONS again (nav.ts promotedTo removed; web app-shell renders them directly, the mobile /volume and /trends routes render their screens instead of redirecting to /performance). Volume gained a `compact` prop \u2014 the hero shape, a verdict that names the muscles and their deltas, and one door \u2014 resolved by the SAME landmark code as the full screen so the two can never disagree, and skipping replayLandmarks() and seven weeklyMuscleSets() passes it would never render. The running RTP protocol moved to Today's Recover cluster (RtpPanel on both clients), where an injured athlete meets it on the morning they have to do it; the Tissue card keeps a status line and the door, so the flag and the protocol stay one object. The risk model version moved off the card face into a 'how is this calculated' disclosure. Web's 'Open setup' stopped expanding the whole enrolment flow inline mid-scroll and now routes, matching mobile. ALSO: the casual-persona teaser lost its six decorative leading dots (house rule), the dead `macroReady` prop is gone, and velocityProfiles is computed once rather than twice per render. New i18n in EN/PL/DE (w.home.cockpit.verdict.*, stateTitle, freshness, wearableOf, strengthFresh/enduranceFresh, limiter.*, capability, last14, shownRange, trajectoryKey, weekVolume, inRange, volumeDoor, seasonWeekOf, changeSeason, deeper, trends, askCoach; w.injury.protocolRunning/protocolDay/protocolWhere/howCalculated). Core tests green (2139), web + mobile typecheck green. THE THREE FOLLOW-UPS ARE NOW CLOSED TOO. (a) THE MODEL HAS ITS OWN ROUTE: the landmark fields, the profile form and the two model switches \u2014 around fifty controls that were revealed inside the Volume SCREEN by an 'Edit landmarks' toggle \u2014 are now aurora/volume-model.tsx on both clients (web screen id volume-model, promotedTo volume; mobile /volume-model), reached from Volume's header and from its provenance card's next-gap row. The resolution itself was extracted to a shared hook (lib/use-volume-model.ts, both clients) so the screen and the route read the IDENTICAL landmarks and an edit can never be computed two ways. And because these are model parameters rather than preferences, the route LEADS with the diff: the same profile resolved with and without the athlete's overrides, so every band they have moved is shown as a change from the estimate it replaced ('chest MRV 18 \u2192 22') and can be put back. Editing used to rewrite every band, prescription and verdict above it with no confirmation, no history and no way to tell an edit apart from the model's own estimate. Volume itself lost its `editing` mode entirely \u2014 the inline field grid, the block steppers, the about-you form and the reset button are gone from the read surface. (b) THE BAND GLOSSARY IS CUT: a collapsed card defining MV/MEV/MAV/MRV at the foot of the Volume screen, when every band value on every muscle row is already a control that spotlights that band across the whole list and prints its definition beside the pointer. The interactive version shows rather than tells and arrives when the question is asked; the card was the pre-interactive version left in place. (c) THE TEASER DEMONSTRATES: a casual-persona athlete used to get six identical padlocked rows telling them nothing about what the feature would say about THEM. It now leads with their OWN freshness \u2014 the real figure, from their real log, by the same engine the full page uses \u2014 plus the limiter sentence, and locks the depth behind it. With nothing logged there is no figure and none is invented. NEXT: the trends exercise table is still uncapped and unvirtualised on its own screen \u2014 tracked as exercise-table-bounds." },
  { id: "readiness-face-door", area: "Core", status: "shipped", title: "Readiness — one line on the face, the derivation behind a door", detail: "The Performance tab's readiness block opened with FOUR sentences of prose — ~38 words (47 with the nudge pill) restating four figures the engine had already computed, with every number buried mid-sentence. The word count was the visible fault; the structural one was worse: because the figures lived inside sentences they MOVED from day to day (with no conditioning load the third line vanished and the wearable line jumped up), so an athlete opening it daily could never learn where to look — which is most of the value of a daily metric. THE BLOCK NOW LEADS WITH ONE LINE. `readinessVerdict(log, bio)` (engines/performance-state.ts) returns the face — a kind (`limiter` / `clear` / `empty`), an i18n KEY rather than a baked English sentence (this is the one line most athletes will ever read, so it speaks Polish and German too), the tissue to substitute, the deficit (100 minus the score — arithmetic, not attribution), and how many reasons sit behind the door. The four sentences move INTO the door, unedited: `readinessReasons()` is `readinessWhy()` minus its score line, which the ring beside it already draws at full size. Nothing left the product, only the default view. AGREEMENT IS STRUCTURAL, NOT EDITORIAL: the face and the derivation share one limiter threshold (LIMITER_FATIGUE), so the card can never name a limiter its own lines don't; and the door's count IS the length of the array it opens onto, so it can never promise three reasons and reveal two. Plurals are the engine's to own (`readinessReasonsKey` — Polish needs three forms), so the clients can't pick differently for the same number, and the door's own label is picked by the engine too (`doorKey`): 'Where the 33 went' is the honest question while something is missing, but at a clean 100 nothing went anywhere and the wearable can still have a line worth reading, so it asks 'How today was read' rather than pointing at a zero. On an empty log there is no door at all — no reasons sit behind it, and the face says so. Both clients ship it in this change (web `<button aria-expanded>`, mobile `Pressable` with `accessibilityState.expanded`, matching the tissue card's disclosure idiom). New copy in EN/PL/DE (w.home.readiness.verdictLimiter/verdictClear/verdictEmpty, door, reasonsOne/Few/Many). 13 new tests. Design study: design/readiness-why-seven-ideas.html (seven concepts) and design/readiness-ring-door-spec.html (the chosen composite). This is step one of that spec — the door, which needs no engine attribution; the deficit ring that replaces the drawn ledger is tracked as readiness-deficit-ring." },
  { id: "readiness-conditioning", area: "Core", status: "shipped", title: "Readiness counts conditioning load (engine fix)", detail: "A MODELLING BUG, found by building the deficit ring on top of a sum law that refuses to draw a cause the score does not have. Readiness was `clamp(35..98, round(100 − 0.7 × avg(muscle fatigue) + bioAdj))` — tissue fatigue and the wearable, nothing else. Conditioning work doses `fatigue.systems`, never `fatigue.muscles`, so a week of hard running left the muscle average near zero and readiness near 98: an athlete could run themselves into the ground and the number that PRESCRIBES their training would not notice. HPI had always counted it (its endurance pillar); readiness, the number that actually moves load, did not. THE FIX: `readiness = clamp(READINESS_FLOOR..READINESS_CEILING, round(100 − MUSCLE_SLOPE × avgMuscleFatigue − ENDURANCE_SLOPE × enduranceFatigue + bioAdj))`, with ENDURANCE_SLOPE = 0.35 — deliberately HALF the tissue slope, because conditioning load clears faster and limits the next session less than local tissue damage. At saturation it can take 35 points; one hard threshold session (≈45) costs about 16; an athlete with no conditioning in their log scores exactly what they did before, so nothing changed for pure lifters. `enduranceFatigue` moved from hpi.ts to fatigue.ts (readiness cannot import hpi — hpi imports the wearable adjustment from readiness) and is re-exported, so every existing caller still resolves. THE CONSEQUENCES, all shipped in the same change: the deficit ring gains a third cause in the blue it uses everywhere else; the card's face can now say the engine is the limiter (`verdictEngine`) or that recovery is (`verdictRecovery`), chosen from the LARGEST arc the ring draws so the sentence and the ring can never name different causes; the drawer's conditioning line appears whenever the load has actually cost a point (CONDITIONING_VOICE = 10) instead of at a threshold of its own, and says that it counts. ADMIN, IN THE SAME CHANGE (the console is the engine's own witness): ENGINE_FORMULAS carries the real expression built from the live constants, plus a new `readiness-deficit` card documenting the attribution law; `deriveReadiness` gained the energy-system and both-terms steps — it had been printing `100 − 0.7 × avg` as the base while the live engine used two terms, a derivation that no longer reached its own result, which is worse than no derivation because it is trusted; `EngineTrace` carries the athlete's deficit split; and the Engine Room renders it as one bar with a visible SUM-LAW check beside it. Drift guards updated to read the exported constants rather than repeat the literals, so the console cannot silently fall behind the engine again. OPEN QUESTION, deliberately left open: 0.35 is a defensible first slope, not a fitted one — it should be validated against real outcomes once the data network has labelled enough of them." },
  { id: "readiness-deficit-ring", area: "Core", status: "shipped", title: "Readiness — the deficit ring (the number accounts for itself)", detail: "Steps two and three of design/readiness-ring-door-spec.html, on top of the shipped face-and-door. The readiness ring stopped gauging what is KEPT and now accounts for the whole 100: a run of ticks for the score, then one run per cause, each in its cause's own semantic colour. The explanation and the number are one object rather than a caption on one, and the drawer opens onto a LEDGER of the same points in the same order and colours (baseline 100, each cost, the total) above the sentences. THE SUM LAW is the gate: `readinessDeficit()` (engines/readiness-deficit.ts) returns `{ kept, deficit, costs, bioAdj, clamped }` where kept plus every cost equals EXACTLY 100, apportioned by largest remainder so whole points can't miss their own total. Nothing may fall off the edge — anything unattributable lands in a named cost. `readinessRingSegments/Ticks()` hand both clients ONE geometry (the way trajectoryPlot already does), enforcing a fixed drawing order (kept → tissue → wearable → ceiling, never re-sorted by value, or the card stops being learnable) and a minimum arc of one tick paid for by the longest run, so a −1 nudge is visible without being mistaken for a big one. 52 tests. TWO FINDINGS THE LAW FORCED OUT, both of which changed the design: (1) CONDITIONING DID NOT MOVE READINESS, AND NOW IT DOES. The ring tried to give conditioning an arc and the arithmetic said its cost was zero: readiness was `100 − 0.7 × avg(muscle fatigue) + wearable` and nothing else, while conditioning doses `fatigue.systems`, never `fatigue.muscles` — so a hard endurance week left the muscle average near zero and the score near its ceiling. An athlete could run themselves into the ground and the number that prescribes their training would not notice. That was a modelling bug the card surfaced, not a layout question, and it is fixed in the engine — see `readiness-conditioning`. Conditioning now takes a real arc, in the blue it has everywhere else. (2) PER-MUSCLE ARCS READ WORSE THAN ONE TISSUE ARC. Readiness averages all seven tissues, so a first cut split that term per muscle — and on any normal week the fatigue spreads, which made the ring's biggest arc an anonymous 'other tissue' LARGER than the tissue actually named (glutes 10, other 27, measured). The tissue term is now ONE cost named by whichever tissue carries most of it — the same tissue the card's face calls the limiter, so the ring and the sentence above it can't tell two different stories. A positive wearable nudge takes no arc: it doesn't cost anything, it makes the whole deficit smaller, so each cost is 'this cause's share of TODAY's deficit' — the only reading under which the parts sum to the whole. Both clients render it through the SAME tick ring they already used (web's local Ring + the mobile kit's, each gaining an optional `tickColors`), so the deficit arrives in the shape the athlete knows rather than as a new instrument. New copy in EN/PL/DE (w.home.readiness.baseline/total/costTissue/costWearable/costCeiling)." },
  { id: "readiness-ring-paint", area: "Core", status: "shipped", title: "Readiness — the ring's paint, and the block at full width", detail: "TWO FAULTS IN ONE BLOCK, reported off a screenshot at a score of 53 — 'that yellow thing is -3 but on the ring it is half the ring'. THE PAINT WAS LYING. The ledger was arithmetically sound (100 - 30 - 14 - 3 = 53, guaranteed by the sum law) and the geometry was right too — the wearable really did get 1 tick of 32. But the kept run wore `readinessRole(score)` and the wearable cost is fixed at `caution`, and at 40-59 BOTH RESOLVE TO SAND, so the ledger's 8px swatch — the only bridge between a row and an arc — pointed at the seventeen ticks the score had kept. The collision is structural, not a one-off: the kept band overlaps a cause in EVERY band but the top one (60-79 with conditioning's teal, under 40 with tissue's terracotta); only 80+ was honest, and only because no cause is chartreuse. The spec had anticipated hue collision and answered it with 'weight, not hue, says which part of the ring is yours' — sound for a shape you stare at, but the moment the LEDGER shipped, hue stopped being decoration and became a lookup key. THE FIX, chosen from four rendered options (design/readiness-ring-colour-and-layout.html — kept-in-chalk, kept-dimmed, deficit-only, two-rings, each shown across a teal/sand/terracotta day): the kept run KEEPS its band hue, so severity still reads before any number, and the WEIGHT separates them — kept draws at `KEPT_ARC_ALPHA` (0.3), every cause at full strength, so the causes sit in front of the run they were taken out of. CRUCIALLY THE RULE MOVED INTO CORE. Both clients derived the kept arc's colour inline and both derived the same collision; a `RingSegment` now carries the role it is drawn from (the BAND's role, not a neutral) plus a `dim` flag, and one `segPaint()` per client is the only place a colour is resolved — ring, proportional bar and ledger swatch all read it. THE LAYOUT, all of it at parity: the ring + kicker + face are ONE masthead row; the check-in nudge gets its own line (inside the old right-hand column it had ~24 characters and broke mid-sentence); and the door, a new PROPORTIONAL BAR and the ledger all span the full card with values flush right — the breakdown used to be trapped in a column starting a third of the way across, so its numbers never reached the card edge and its rows sat narrower than the prose beneath them. The bar reads the SAME segments the arcs do (it cannot disagree with them, and it inherits the minimum-arc rule that keeps a -3 visible), and the ledger's total row now carries the kept swatch so every colour on the ring is named by a row. THE PROSE IS GONE. Three sentences restated the three rows above them, in English-only prose. What they carried that the rows CAN'T is now `readinessFacts()` — i18n keys plus figures for the limiting tissue's own fatigue (the row says the term cost 30; only this says the tissue reads 81/100), the energy-system load, and the wearable's signed nudge. That last is the case that matters: a POSITIVE nudge takes no arc and no row (it shrinks every other share instead), so without it a wearable that was read and did move the score would show nothing anywhere on the card. CONSEQUENCE THE CUT FORCED: the door's count was `readinessReasons().length` — the sentences — and now counts the ledger's rows, because that is what opening it reveals. Both were 3 on a typical day, which is exactly how a door promising three of something no longer there ships unnoticed; the old drift test pinned the count to the prose and failed, which is how it should go. New copy in EN/PL/DE (barKept/barSpent/provFrom/factTissue/factLoad/factWearable). 11 new tests: the paint law sweeps every score 1-98 and asserts no two runs of one ring ever share a role-and-weight pair — and inside 40-59 asserts that the kept run and the wearable's DO share a role, which is precisely why the hold-back is not optional. OPEN, deliberately not fixed here: in KYOTO HOUR the cost hues themselves crowd — sand darkens to #875427 and terracotta to #a3442f, a brown and a vermilion that are closer to each other than their dark-theme twins. That is a collision between two CAUSES, which no choice of kept-arc paint addresses; tracked as readiness-light-cost-hues (now fixed — see that entry). ALSO FIXED HERE, a latent geometry bug the new tests' own fixtures surfaced: the kept-starvation guard in readinessRingSegments lifted a starved kept run to one tick WITHOUT PAYING for it, and the coverage correction then took the extra tick off the LAST run — the smallest. At a kept of 1 that drove the wearable's run to count 0 and `from` 32, past the end of a 32-tick ring: a legend row pointing at an arc that is not drawn, which is precisely the lie the minimum-arc rule exists to prevent. The guard now pays from the LONGEST run (the same idiom the minimum-arc rule uses), the coverage correction can never take a run below its one guaranteed tick and re-seats every `from` after the run it moved, and a regression test sweeps kept 1-3 across 12/24/32/60 ticks. Not reachable through readinessDeficit today — READINESS_FLOOR clamps the score at 35 — but readinessRingSegments is exported and takes any deficit, and the floor is a tunable constant." },
  { id: "accent-text-channel", area: "Core", status: "shipped", title: "Accent colours are drawn in the TEXT channel, app-wide", detail: "THE SWEEP the readiness fix uncovered. Every brand accent exists twice — a FILL (--color-red), tuned to sit UNDER something, and a TEXT tone (--red-text), tuned to be legible on the card in whichever theme is showing. lib/ui.tsx has mapped between them since the light theme shipped, but only for the RAW HEX constants (txt(RED)). The Aurora screens use a different idiom — C('red') → var(--color-red) — which that mapping never saw, so 78 call sites across 32 files painted GLYPHS in the fill. Measured against each theme's own card: light amber #d0cd94 is 1.57:1 (sand on washi paper — near-invisible), light violet 2.83:1, light red 3.26:1 (every role=alert error message on the light theme), dark blue 3.59:1. The type scale here runs 10-14px, so WCAG's large-text exemption covers exactly NONE of them; lime was the only accent that passed on both grounds. FIXED: lib/ui.tsx gains `accentText(name)` beside `roleText(role)` — same channel, for the many call sites that name an accent directly rather than deriving one from a semantic role (an error is red because it is an error, not because something computed `danger`). 75 sites repointed across 32 files; mobile's three raw `color: C.amber` error texts (device-import, device-match, session-edit) went through txt() for parity. THREE FALSE POSITIVES were caught and are the interesting part: in both builders, a `color` property on a data object was the bar-segment BACKGROUND, with a sibling `textColor` for the label. The property was renamed `fill` on both clients rather than exempted — a value used as a background should not be called `color` in a codebase where that word now means the text channel. GUARDED by apps/web/__tests__/accent-text-channel.test.ts: no `color:` in components/, app/ or lib/ may resolve to an accent fill, in either the C('x') or the var(--color-x) spelling, with doc-comment lines skipped so the rule can quote the pattern it forbids. Backgrounds, borders, bar segments and body-map areas still take C(...)/roleVar — the test only ever looks at the `color` property. A reviewer cannot hold this distinction across 32 files; the test can." },
  { id: "readiness-light-cost-hues", area: "Core", status: "shipped", title: "Kyoto Hour — the cost hues, and the colour a legend is actually drawn in", detail: "FOUND while fixing the ring's kept-arc collision (readiness-ring-paint) and fixed here, along with a bigger fault it uncovered. (1) THE COST HUES CROWDED. On dark the three costs are terracotta / teal / sand, plainly three marks. In Kyoto Hour the same roles darkened to #a3442f vermilion and #875427 brown — ΔE 13.2 apart, both comfortably AA against the paper, and still the same warm mark at the ledger's 8px swatch. The light `amber` accent-text is now a deep OCHRE #885c00: ΔE 22.1 from vermilion and 22.5 from sage, in line with the dark set's own floor (its worst cost pair is 28.4). Mirrored across THEMES.light.accentText.amber and globals.css --amber-text. (2) THE REAL FAULT WAS THE CHANNEL. Mobile has had `txt()` since the palette split — it maps an accent FILL to the AA-guarded text tone for the current theme — and WEB HAD NO EQUIVALENT. `roleVar()` returns the fill, which is tuned to sit UNDER something, and Kyoto Hour deliberately leaves --color-amber as the pale sand #d0cd94. Used as a text colour on washi paper that is 1.57:1 — roughly a quarter of AA. Every caution-band figure on the light theme was printed in near-invisible ink: the readiness ledger's wearable row and its −3, an elevated tissue's driver label, and the HPI headline at 46px (a compromised athlete's own score). Even on DARK the fill was the wrong channel — the teal fill #3c787e as text on the card is 3.2:1, under AA, which is exactly why accentText lifts it to #6cb6bd. lib/ui.tsx now exports `roleText()` (web's twin of mobile's txt(), ash passed through since the muted token is already a text colour) plus `tint()`, and the rule is stated where both live: a background, a bar or a body-map area takes `roleVar`; glyphs, a legend swatch or a ring's ticks take `roleText`. Repointed: the readiness ledger (swatch + value + ring ticks + the new bar), the HPI headline on both the full card and the Teaser, the tissue card's driver label, Today's readiness ring, and the admin Engine Room's DeficitBar — which also gets the kept run's hold-back, since its own comment claims it mirrors the athlete's ring and it was reproducing the exact collision the card had. GUARDED: contrast.ts gains `labOf()` + `deltaE2000()` (CIEDE2000) and DISTINCT_ROLE_DE, and palette.test.ts now measures the cost roles against EACH OTHER per theme, not just against the ground — the half of accessibility contrast cannot express, and the half that was missing when this shipped. Verified the guard bites: reinstating #875427 fails `light: danger vs caution`. The readiness ring's kept arc is deliberately exempt — it wears its band's hue, which DOES collide, and is separated by weight instead (KEPT_ARC_ALPHA), which is the whole design of that ring. NOTE for a future pass: in light, pine (#3c4f43, the kept arc at 80+) and sage (#4f5c3a, conditioning) are ΔE 9.6 — they co-occur on the ring but only ever as dimmed-vs-full, so the weight rule already separates them; if the kept arc is ever drawn at full strength again, that pair has to be retuned first." },
  { id: "performance-unified", area: "Core", status: "shipped", title: "Performance, Volume and Trends are ONE page (SUPERSEDED by performance-six-surfaces)", detail: "SUPERSEDED \u2014 the merge preserved everything and appended two whole screens to one scroll; Volume and Trends are their own destinations again and Performance keeps a volume hero plus doors. See performance-six-surfaces. HISTORICAL RECORD: The hub's Performance tab is a single scroll on BOTH clients (apps/web/components/aurora/performance.tsx + apps/mobile/components/aurora/performance.tsx), not three sub-views behind a chip rail. THE REDUNDANCY THAT FORCED IT: Volume and Trends were drawing the SAME engines twice. Both called volumeStatus() to render a per-muscle breakdown — Volume as landmark rails, Trends as a chip row — and both called volumeAdvice() to print the same add-volume / ease-off prescription, so an athlete could read 'add volume to chest' on one tab and see it again as a chip on another, with no way to tell whether they were two findings or one. Trends also carried a muscle PICKER purely to feed its focus-muscle chart, which meant selecting a muscle in two different places on the same subject. WHAT MERGED, IN ORDER: (1) the command centre unchanged — context rail, Performance State/HPI + components + readiness nudge, the 14-day HPI/readiness trajectory chart, injury risk with things-to-watch (ACWR, s-RPE, monotony, strain) + the tissue body-map disclosure + driver explanations, this week's recap & PRs, the discipline breakdown; (2) VOLUME entire — hero (muscles in range + the week as a seven-column shape + verdict), the block ramp, both prescription cards, the per-muscle rails with their band scales, gloss, targets and inline landmark editing, the provenance/profile card and the MV/MEV/MAV/MRV glossary; (3) TREND — weekly sets and weekly tonnage over eight weeks, then the sortable exercise-analytics table with its period toggle; (4) the horizon rails, goal + season, and return-to-play. WHAT WAS DEDUPLICATED, NOT DROPPED: Trends' muscle-chip breakdown is gone (Volume's rails say the same thing with the landmarks attached), its advice line is gone (the two prescription cards say it with magnitudes), and its focus-muscle 8-week chart MOVED onto the muscle row it describes — expanding a muscle in Volume now shows that muscle's own eight-week history, so '18 sets' and 'and it has been climbing for a month' are one thought instead of two screens. Nothing else was removed. PARITY GAP CLOSED ON THE WAY: mobile Trends never drew the weekly TONNAGE series web has always had — it does now. MECHANICS: volume.tsx and trends.tsx each take a `unified` prop — on web it demotes their <h1> to a section head; on mobile it ALSO returns the sections bare (no AuroraScreen), since the host page owns the scroller, safe area and pull-to-refresh, and nesting would have stacked two ScrollViews. Both still render standalone off their own props/queries, and useSessionsRead is literally toRead(useSessionsQuery(...)) so the three composed screens share one react-query entry rather than fetching three times. NAV: the volume + trends nav items are promotedTo \"performance\" (the same mechanism statistics\u2192history uses) so menus stop offering the same content twice, while the ids stay routable — web resolves screen \"volume\"/\"trends\" to the unified page, and the mobile /volume and /trends routes <Redirect> to /performance, so saved links and the More hub's map still land somewhere real. NO RESTYLE RULE: the merge is STRUCTURAL — not one stylesheet, theme token or palette value was touched, and no section was redrawn. Each merged block renders exactly as it did as its own screen: Volume and Trends keep their display-size titles verbatim (only the HEADING LEVEL changes, h1 to h2, so the unified page doesn't carry three h1s — identical CSS via createElement), the mobile sections use the page's existing 14dp rhythm rather than a new spacing value, and the relocated per-muscle 8-week chart is drawn in vocabulary that already existed at its destination (mobile lifts the old focus-chart geometry verbatim — 4 + n/max*48, radius 3, blue with 66 on older weeks; web reuses BlockCard's ramp idiom in the same file — ink track, radius 7, .95 current / .32 the rest — since Volume imports no chart library and a recharts frame with axes would have looked foreign inside a Volume card). A moved element must not become a restyled one. Core tests + web/mobile typecheck + web build + iOS bundle export green." },
  { id: "today-hub-tabs", area: "Core", status: "shipped", title: "Today is a hub — Dashboard / Performance / Feed pills", detail: "Today is no longer one screen; it is the athlete's HOME HUB. A three-pill segmented control sits directly under the profile header and ABOVE the calendar/week rail on BOTH clients (apps/web/components/aurora/today.tsx + apps/mobile/components/aurora/home.tsx), switching between: (1) DASHBOARD — the daily guided loop exactly as it was (masthead, week/logbook rail, plan hero, feel, this week, coaches); (2) PERFORMANCE — the analytical layer, all of it, behind a SECONDARY chip rail carrying the three existing screens unchanged: Performance (the command centre: HPI, injury risk, season, modules), Volume and Trends; (3) FEED — the social surface (posts, PR cards, kudos, comments), live today and the seat for the wider social product still to come. The registry (ids, order, labels) is shared in @hybrid/core today-tabs.ts (TODAY_TABS, PERFORMANCE_VIEWS, normalizeTodayTab, normalizePerformanceView; unit-tested) so the two clients cannot drift, and the labels REUSE the existing shared nav.* strings rather than minting a second copy of 'Dashboard'/'Performance'/'Volume'/'Trends'/'Feed' — zero new i18n keys. TWO LEVELS, TWO TREATMENTS: the top row is a primary segmented control (three equal full-width segments in one capsule, active filled chartreuse); the Performance tab's own switcher is the small mono chip rail History already established, so the hierarchy stays readable instead of pills-under-pills. The tab is deliberately NOT persisted (Today's job is 'what do I do today?', so every visit opens on the daily loop); the Performance sub-view is remembered for the session. NO SCREEN WAS FORKED: each tab renders the same component its own route/screen renders. Web embeds them as lazy dynamic imports (an athlete who only opens the daily loop never pays for recharts or the feed) and threads the shell's SAFE-CACHE gates (sessionsReady/macroReady/macroSettled) into Performance so it can still tell 'no history' from 'not asked yet'. Mobile keeps each screen owning its own scroller, pull-to-refresh and safe area via a new AuroraScreen `top` slot that renders the hub header + pills above the screen body (nesting them in Today's ScrollView would have doubled both); the mobile feed moved from the app/feed.tsx route into components/feed-view.tsx (route re-exports it) so the hub can host the same FlatList-virtualized feed, and the embedded screens hide their back button since there is nothing to go back to. Performance/Volume/Trends/Feed all remain reachable as their own destinations from nav — the hub is an additional entry point, not a replacement. GLYPHS, NOT WORDS (follow-up): the three pills carry marks rather than their labels — 'Dashboard', 'Performance' and 'Feed' are three very different lengths, so as text in three equal segments they read as a control out of alignment with itself, and no amount of centring fixes it (it gets worse in PL/DE). HUB_GLYPHS in theme/icons.ts adds three purpose-built 72x72 monoline marks in the SAME stroke box and weight as the design-kit icons — a bento (the daily loop's own shape: hero card plus the smaller cards under it), three rising bars on a baseline, and two figures — drawn as true vectors on both clients (inline <svg> on web, react-native-svg on mobile), so no PNG asset is needed. This follows the NUTRITION_GLYPHS precedent exactly: the kit is a generic UI set with no chart or community mark (its own comment says so), and an EMOJI would be the one place in the app that breaks the monoline voice while rendering as a different picture on every platform. The word is not lost — it stays each tab's ACCESSIBLE NAME (aria-label on web, accessibilityLabel on mobile) and the web tooltip, so screen readers, voice control and translation are unaffected and the i18n keys stay referenced. ONE ROW, NOT TWO: the Performance tab briefly carried its own chip rail (Performance / Volume / Trends); those three are now a single page (see performance-unified), so the rail had nothing left to switch between and was removed. THE HUB MOVE (follow-up fix): switching pills used to be a broken patchwork — web hard-cut the content; mobile replayed the WHOLE-SCREEN entrance over the supposedly-stable chrome on Dashboard→Performance, hard-cut on the other switches, and the lens pill teleported (with a one-frame vanish) because the tree swap remounts the LiquidSeg before it can fly. Now the switch is ONE motion on both clients, per the shared-element rule (the flying lens owns the move; the content behind it cross-dissolves; the chrome holds perfectly still): web runs a scoped View Transition (runHubTransition in lib/use-screen-transition.ts publishes data-nav-kind='hub'; globals.css lifts .motion-hub-chrome into its own still group and dissolves the rest over --d-dissolve/--e-fade, Reduce Motion inherits the --d-reduced substitution; guarded in __tests__/motion-tokens.test.ts); mobile suppresses the whole-screen entrance in AuroraScreen's hub mode and dissolves only the content below the `top` slot (lib/ui useHubDissolve/HubDissolve — also wired into FeedView's virtualized list and the Dashboard body's return trip, with the wrapper's offset threaded into the sticky-rail geometry), while LiquidSeg gains a `flightKey` FLIGHT MEMORY so the remounting control takes off from the slot its predecessor held and the lens still flies glassy across the change. ON-DEVICE FIX (frame-by-frame from a TestFlight screen recording): the first build showed (a) a one-frame chrome jump — a freshly mounted native SafeAreaView applies its inset a frame late, so hub shells (AuroraScreen hub mode, classic Screen's new `hubTab` prop, home's dashboard shell) now pad with the provider's synchronously-correct insets instead — and (b) the dissolve never visibly ran: mounting a hub tab blocks the JS thread longer than the fade, so a JS-driver timing snapped to its end on its first tick. The dissolve now runs on the NATIVE driver, started from the wrapper's onLayout (the view provably exists, dodging the Fabric strand race that forces useEntrance onto the JS driver)." },
  { id: "checkin-on-today", area: "Core", status: "shipped", title: "Guided daily check-in runs ON Today (no trip to More)", detail: "The daily check-in has FIVE cards (Energy, Sleep, Soreness, Mood, then the details/submit card), but Today's 'How ready do you feel?' offered only the single one-tap face row — the rest lived on a separate screen (web More \u2192 Daily check-in, mobile /checkin), so 'log more' meant leaving the homepage. The whole ritual now happens on Today. The one-tap face IS step 1 (it writes Energy); tapping the 'Log the full picture' nudge underneath EXPANDS the very same guided wizard inline inside the feeling card, opening on step 2 (Sleep) and walking Soreness \u2192 Mood \u2192 details, then submitting and collapsing back to the card. IMPLEMENTATION: both wizards (web components/aurora/checkins.tsx, mobile components/aurora/checkin.tsx) gained the same three props — `embedded` (drops the screen chrome: the h1/back header AND the card shell, so it reads as one surface rather than a card boxed in a card), `startStep` (the question to open on, which also becomes the floor the Back button cannot reverse under, so an embedded flow can't walk into a step its host already answered), and `onDone` (fires on a successful submit so the host collapses + refetches). ONE component serves both entry points — the standalone More/'/checkin' screen renders it with the defaults, so the two can never drift. The wizard already prefills from TODAY's row, so the expansion REFINES the one-tap value instead of resetting to neutral 3s, and the same-day upsert (see checkin-relog-cooldown) means it never dead-ends on a 429. CORRECTNESS: re-tapping a readiness face while the flow is open COLLAPSES it — the open wizard's prefill was read from the previous row, so submitting it would write the superseded values back; re-opening re-reads the row. Web lazy-loads the wizard (next/dynamic, ssr:false) so its weight only lands when an athlete actually expands it. New i18n w.recovery.readiness.logMoreOpenSub (EN/PL/DE) swaps the nudge subtitle while expanded, and the chevron rotates. Web + mobile at parity." },
  { id: "checkins", area: "Backend", status: "shipped", title: "Daily check-in (personal + optionally shared)", detail: "A DAILY training-readiness log (bodyweight, energy/sleep/soreness/mood 1–5, self-reported adherence, free-text note). By default it is for the athlete's OWN personal use; a PAID athlete may opt to SHARE a given check-in with their coach, who then reads + replies (the online-coaching loop). Checkin model gains sharedWithCoach (default false); /api/checkins POST honours sharedWithCoach only when entitlement==='paid' (free users are silently coerced to private). The coach read (/api/coach/links/[id]/checkins) and reply (/api/checkins/[id] PATCH) are gated to sharedWithCoach=true AND an ACTIVE CoachLink; the RLS coach-read/reply policies carry the same sharedWithCoach predicate. Client UI on web (Daily check-in screen + share-with-coach toggle, paid-gated) + mobile (check-in route + share toggle) — both now a GUIDED, one-question-per-card flow (Energy → Sleep → Soreness → Mood, each a big reactive readiness face on a 1–5 scale, then a final details/submit card), replacing the old wall of number pills; the shared step model + value→face mapping live in packages/core/src/checkin-flow.ts so the two clients can't drift, and the copy is day-framed (fixing the prior 'this week' mislabel). NOTE: run reference/sql-history-checkin-anon.sql to add Checkin.sharedWithCoach + update the coach RLS policies (and reference/sql-checkin.sql first if the table is brand new). The home feeling card also reads back today's last logged feeling + a re-log cooldown chip (see checkin-relog-cooldown)." },
  { id: "checkin-relog-cooldown", area: "Backend", status: "shipped", title: "6h re-log cooldown (enforced) + same-day refine", detail: "The product rule 'log a feeling ≥1×/day, re-log ≤1×/6h' is enforced, not just displayed — but REFINING the same day's check-in is exempt. Server: /api/checkins POST first looks for an existing check-in on the SAME (UTC-calendar) day as the submitted weekOf; if one exists it UPDATES that row (the coarse one-tap readiness is replaced by the detailed guided values — no duplicate, no cooldown), and only a check-in for a NEW day is rejected with 429 { retryAfterMs } when it lands within CHECKIN_COOLDOWN_MS (6h) of the athlete's most recent one (keyed on the server-side createdAt, so the cap holds regardless of client or client-supplied weekOf). This makes the Today 'log the full picture' nudge coherent: after the one-tap readiness pick, the guided full check-in refines today's row instead of dead-ending on the cooldown. Clients: the home feeling card (FeelingCard in today.tsx / home.tsx) disables the four faces while cooling and shows today's last logged feeling + a 'next in Xh Ym' chip (from the shared checkinCooldownRemainingMs), and — once today's feeling is set — surfaces a 'Log the full picture' nudge (w.recovery.readiness.logMore/logMoreSub, plus logMoreOpenSub while open) that EXPANDS THE GUIDED CHECK-IN IN PLACE — see checkin-on-today; the guided full check-in surfaces any 429 as a cooldown message (web inline error, mobile Alert) via createCheckin's { ok, cooldownMs } result. The 6h window + remaining-time helper live in packages/core/src/checkin-flow.ts (unit-tested), so server and both clients agree." },
  { id: "checkin-saved-state", area: "Core", status: "shipped", title: "A saved check-in READS as saved (muted answers + Edit)", detail: "Re-opening a day whose check-in was already complete looked exactly like a form that had never been sent: live 1-5 tiles under a 'Submit check-in' button, with no way to tell whether the answers had landed short of pressing Submit again. The wizard now distinguishes ANSWERED from ANSWERED-AND-STORED. `storedMetrics` is what the server holds, stored efforts come from each session's own `feel`, and `dirty` marks anything touched since the last successful write; `locked = hydrated && allAnswered && !dirty && (storedAll || submittedOnce) && !editing`. The submittedOnce clause matters because the refetch that would prove a just-completed write lands a beat after the write itself. HYDRATION IS PART OF THE CONTRACT: the flow renders NOTHING about the day until the stored check-in has arrived. It used to render off empty state, so an athlete at 4/4 opened the sheet onto 'Today's read - 0 / 4 answered', four dashes and a Submit button, which corrected itself a moment later — a blank form is not a neutral placeholder, it is a wrong answer. Web derives storedMetrics from the shared cache with useMemo rather than syncing it in from an effect (as state it lagged the first render that saw the cache by one frame, which was exactly long enough to draw the wrong button); mobile sets `hydrated` in a `.finally` so it always flips AFTER the values it gates. LOCKED, the flow is a READ-BACK: the scale/effort tiles are disabled, the lime selection drops to a neutral outline and the unpicked options fade to 35%; the 'Today's read' summary tiles are muted to 45% and stop being buttons, because left at full colour and still tapping through to their question they read as 'edit any of this whenever' — which is what Edit is for. The details footer is [Edit] [Done] — Edit lives there and ONLY there, beside Done, where the athlete already is when they decide the read is wrong. A banner states 'Check-in saved' as text, no control of its own. A write made while editing confirms as 'Check-in updated' rather than 'Check-in logged', and the CTA reads 'Save changes'. TODAY'S FACE ROW LOCKS TOO: the four readiness faces on the Today card stayed tappable over a finished day, so the committed answer could be overwritten by a stray thumb while the flow below was busy muting that same answer; they now mute and go inert once the day is complete (TODAY only — a past day has no follow-up sheet and that row is the only way to back-log it). THE OPTIONAL FIELDS ARE GONE: weight has a real home in the body log (one canonical weigh-in, not a second buried in a check-in), adherence is countable off the plan rather than worth asking for, and three blank boxes under a finished check-in made the card look unfinished when it was not. Share-with-coach stays — it is an entitlement control, not an optional data field. Both clients, i18n EN/PL/DE." },
  { id: "today-cockpit-ia", area: "Core", status: "shipped", title: "Today ⇄ Cockpit split — daily loop vs command center (no redundancy)", detail: "Today and the Cockpit no longer duplicate each other. TODAY (apps/web/components/aurora/today.tsx + apps/mobile/components/aurora/home.tsx) is now a GUIDED DAILY LOOP, walked top-to-bottom with section kickers: a time-of-day greeting + streak chip → TRAIN (today's session ⇄ AI-coach pager + quick sport log) → RECOVER – FEEL (a slim on-track/accountability strip + the check-in & nutrition SQUARE widgets) → PLAN (the reconciled This-week plan, or a follow-a-plan nudge for casual) → CONNECT (the coach rail + the friends' Feed strip). The strategic/analytical layer was MOVED OFF Today onto the COCKPIT (apps/web/components/aurora/cockpit.tsx + apps/mobile/components/aurora/cockpit.tsx, athlete/Full command center): the Performance Twin (HPI) now carries the 14-day sparkline + a readiness dial, and the injury-risk-by-tissue panel and the weekly recap ('Your week') moved there too — so HPI/readiness, injury risk, the season timeline and the recap live in exactly ONE place. The Today 'sell Full' upsell card and the free season-brief were dropped (the Cockpit is the paid hub; the AI-coach card + browse-plans still pitch upgrade). SQUARE WIDGETS: the check-in + nutrition quick-actions are now two iPhone-home-screen-style SQUARES side by side (apps/web/components/aurora/today-quick.tsx + apps/mobile/components/aurora/today-quick.tsx) — each shows a glanceable state (have you checked in today? today's kcal vs adaptive target + macros, read from /api/checkins + /api/signals via todayNutrition/adaptiveTargets) and OPENS THE FULL Check-in / Nutrition screen on tap (logging lives there, so the widgets stay small). Web + mobile at parity; new i18n keys under w.home.today.* + w.home.today.w.* (EN/PL/DE); accountability stays Today-only, the recovery analytics stay Cockpit-only. Manual macro entry only — the food DB + barcode scan remain the blocked nutrition-fooddb layer. PREMIUM-TODAY FIX: a premium (athlete) user WITHOUT an enrolled plan no longer gets a fabricated AI 'Back Squat + Assault Bike' hero on Today — everyone with logged history but no plan now routes into LOGBOOK MODE (their real last-7-days calendar rail + the Follow-a-plan / Build / Just-train chooser), so the home hero is always the plan/calendar or a path to one, and the readiness-driven daily prescription stays on the analytical Cockpit (the removed AI branch also took its awkward top-right Start+readiness cluster with it). COCKPIT VOICE: the Cockpit header is now a LIVING MASTHEAD in Today's editorial idiom (mono season caption + one oversized 'Cockpit' headline + a warm sub) and the w.home.cockpit.* copy was de-slopped — dropped 'command center', the A→B→C arrow chains, and the feature-list-as-sentence blurbs — so it reads as Today's sibling (EN/PL/DE)." },
  { id: "compliance", area: "Core", status: "shipped", title: "Planned-vs-actual compliance", detail: "compliance.ts: weekly planned-vs-actual adherence from logged sessions — this week's completion %, status (on-plan/under/over), a compliant-week streak (≥80% of target), and a 4-week history. Plus dailyChecklist (habits.ts) for the consumer daily 'rings' (trained / nutrition / check-in today, derived — no new storage). Pure + unit-tested. Surfaced on the Check-in screen and the Fitness GPS home." },
  { id: "persona-shape", area: "Core", status: "shipped", title: "Persona-aware app shape (nav by who you are)", detail: "The app shapes itself to the customer instead of showing one flat 28-item menu to everyone. @hybrid/core/nav.ts defines a nested Persona model — casual (Average Joe: a frictionless logger + share loop), athlete (the data/technique athlete: casual PLUS depth — periodize, sport, velocity, running, performance, video, connections), coach (athlete PLUS the console — roster, squad, team compare, org, tactical), admin (everything); casual ⊂ athlete ⊂ coach ⊂ admin. Each NAV_ITEM carries a minPersona; resolvePersona(role, clientChoice, entitlement) derives it from the auth role, a CLIENT's mode choice, and the account's billing entitlement, and navForPersona/navVisibleTo filter the surface (pure + unit-tested). Both clients carry it. The choice persists per-device (mobile lib/persona.ts on AsyncStorage; web lib/persona.ts on localStorage — each a useSyncExternalStore store + a usePersona hook that reads the session role) and is reversible (mobile: a Simple/Full toggle in More AND in Settings → Subscription/Mode; web: a Mode toggle in Settings; both client-only — coach/admin come from the role, and Full is entitlement-gated so an unpaid tap on Full routes to /upgrade). SET at onboarding: a 'How do you want to use HYBRID?' fork (Just track / Train for a goal) on both the mobile and web onboarding. SURFACED: the mobile More hub + CommandMenu tiles, and the web sidebar nav + ⌘K hub, all filter through navForPersona(persona); and the HOME shapes itself too — the mobile Today + web Today gate the athlete-depth cards (plan setup, This week reconciled plan, Future Self projection, Athlete Twin/HPI) behind the athlete persona, so a casual user gets the lean Start→route→on-track→share home while an athlete/coach gets the full cockpit. So a casual user no longer sees Coach/Squad/Velocity/Periodize anywhere; an athlete gets the depth; a coach gets the console. DEFAULT POLICY (the curated 'done deal', fully admin-overridable in Access control): CASUAL = the lean loop PLUS the free pre-built plan library (today, log, history, calendar, nutrition, progress, check-in, plans, settings — browse, enroll & FOLLOW a pre-built plan AS WRITTEN is free, and Today renders the enrolled plan's session for the day to a casual user (a single 'Unlock Full to auto-adjust loads to your recovery' strip is the only upsell, plus a 'Follow a plan — free' nudge when none is enrolled); what's PAID is the adaptive layer — periodizing the season + readiness-adjusted auto-progression + the Twin/analytics cockpit; onboarding is a flow, not a nav item); ATHLETE adds the cockpit + all depth/analytics (periodize, sport, competition, performance, velocity, running, force-plate, video, longevity, talent, connections, builder — the old Dashboard is retired; its surfaces live on Today); COACH adds the console (coach, squad, team-compare, org, tactical); ADMIN all. The casual set is pinned by a nav unit test so it can't silently drift. MOBILE PARITY OF ACCESS: the mobile app has fewer deep screens than web, so the More hub also shows a 'More in the web app' section listing exactly the features the user's persona allows that live on web only (with an 'Open the web app' link) — so access is never silently invisible on mobile. ACCESS TIERS (revised): the three modes are now ENTITLEMENT-GATED, not free self-select. (1) SIMPLE (casual) = free, the default. (2) FULL (athlete) = PAID: ClientPersona is casual|athlete only, and resolvePersona returns 'athlete' only when the client chose Full AND carries a paid Entitlement ('free'|'paid', read from the auth session.user_metadata on both clients). An unpaid client who taps Full hits the Upgrade/paywall screen (mobile app/upgrade.tsx; web account-settings note) instead of switching — the real purchase flow (Stripe / App-Store IAP) is still BLOCKED (see the 'full-billing' capability + its sub-items). COACHED (read-only): a client linked to an ACTIVE coach stays casual (free) but additionally gets a READ-ONLY view of everything the coach assigned (plans, programs, diet) via the useHasActiveCoach flag — a coach link NEVER grants Full; to edit/add or self-program the client makes their own paid upgrade (so the seat can't be used to obtain Pro for free). (3) COACH = VERIFIED only: coach is no longer a self-serve ClientPersona — the coach surface comes solely from a verified COACH role. A client applies via 'Become a coach' (mobile app/coach-apply.tsx; web Settings) → POST /api/coach/apply → an admin reviews the queue in Governance and approves, promoting the role to COACH (audited; mirrors the AccessRequest pattern — see the 'coach-verification' capability). Coach data APIs remain relationship-gated (squad/roster/compare filter by the caller's OWN CoachLinks — 'enforced by relationship, not role label'). INCOMING invites are still surfaced to EVERY persona — a CoachInviteBanner in the web app-shell + a Today invite card on mobile (fetch /api/coach/links asClient PENDING → Accept/Decline PATCH) — so any client can complete a mutual-consent link. See reference/roadmap.md + persona-gap-matrix.md." },
  { id: "coach-assign-plans", area: "Backend", status: "shipped", title: "Coach assigns plans to clients + client groups (bulk)", detail: "A coach builds/picks a plan and pushes it straight into a client's account — and into a whole GROUP of clients at once. PER-CLIENT: /api/coach/links/[id]/macrocycle now also accepts an optional named planId (on top of goal), so an active coach persists a full periodized season into the client's account; their Today/Periodize reflect it. GROUPS (the solo-coach version of segmentation, NOT the enterprise Org Graph): a lightweight CoachGroup model (coach-owned, holds client user ids; prisma + reference/sql-coach-groups.sql) with /api/coach/groups (GET/POST), /api/coach/groups/[id] (PATCH rename/set-members, DELETE) and /api/coach/groups/[id]/assign-plan (POST goal[,planId] → buildMacrocycle fanned out to every member who is still an ACTIVE client, via createMany). Membership is re-validated against ACTIVE CoachLinks on every write/assign, so a group can never grant access to a non-consented client. Every group endpoint SOFT-DEGRADES to 'not enabled yet' (503 / unavailable flag) until the table exists, so the deploy is safe in any order. COACHED CLIENTS ARE READ-ONLY (not Full): a client with an ACTIVE coach STAYS on the free/casual tier and gets a READ-ONLY view of what the coach assigned (plans, programs, diet) — surfaced via the useHasActiveCoach flag on both clients. resolvePersona NO LONGER elevates a coached client to athlete (the old hasActiveCoach→athlete path was removed); editing/adding and the adaptive engine remain a paid (athlete) upgrade, so a coach link can never grant Pro for free. A coached client who wants to self-program upgrades like any other consumer. UI: web Coach screen gets a 'Client groups' section (create/rename/delete, toggle members, assign a plan by goal to the whole group); mobile parity via a shared components/coach-groups.tsx rendered in BOTH the classic and Aurora coach tabs. Packaging: client groups + bulk assignment sit in the Coach PRO seat ($79); the full Org Graph (roles/medical/team subtrees) stays Business. Write routes are body-limit guarded (readJsonLimited) and the 'Client groups' section is admin-gateable via the coach.groups feature flag (web + mobile). NOTE: run reference/sql-coach-groups.sql in the Supabase SQL Editor to persist groups (and reference/sql-coach-macrocycle.sql for the coach-write macrocycle RLS if not already applied)." },
  { id: "plan-program-today", area: "Core", status: "shipped", title: "Discipline-shaped programs drive 'Your plan today'", detail: "Enrolling in a discipline-shaped PlanProgram (Soviet OWL %-block, 6-day PPL, 5K running, Saturday kettlebell circuit, 12-week kettlebell) now DRIVES the daily 'Your plan today' card — the enrolled plan's real session, not the engine's fallback prescription. planProgramToday(planId, sessionsLogged, maxes?) in plan-day.ts resolves the program via programFor(), flattens its weeks→days across the whole program (skipping pure REST days; AM/PM sessions kept and prefixed), and picks the current day by how many sessions the athlete has logged (cycling at the end — the same model as the legacy planToday). It returns BOTH a display view (rows: name + the SAME formatted prescription the Plans-library card shows, reusing planProgramView — %×reps×sets–kg, '4×8 – 80 kg – @9', or the prose run — plus any complex/tempo note) AND a prefill (blocks): each PlanLift %-ramp expands step-by-step into strength sets with kg DERIVED from the athlete's 1RM when a `maxes` map is supplied (else blank loads to fill live, via stepKg); structured hypertrophy/scheme entries → strength blocks; prose endurance/conditioning entries → a named conditioning block. Wired into BOTH Today cards (web today.tsx + mobile home.tsx render plan.rows + plan.day incl. a Week-N prefix for multi-week plans + a rest/competition kindLabel) and the live-logger 'Start' (web onStart(plan.blocks); mobile source=plan → planProgramToday(...).blocks in app/workout.tsx) — so a CASUAL (free) enrolled user sees and starts their real plan day (following a pre-made plan as written is free), which also fixes 'I can't tell whether I'm enrolled'. Pure + unit-tested (plan-day.test.ts: resolves an enrolled program, advances/cycles by sessions logged, derives kg from maxes). MAXES PERSISTENCE (shipped): the athlete's 1RMs entered on the Plans 'fill in your numbers' panel now persist on-device (a flat athlete-level `{ inputKey: 1RM }` map keyed by ProgramInput.key, shared across plans) via a small reactive store on each client — web lib/plan-maxes.ts (localStorage + usePlanMaxes/setPlanMax) and mobile lib/plan-maxes.ts (AsyncStorage-hydrated, mirrors the persona store). The Plans panel seeds each input from the store and writes on change; Today (web today.tsx + mobile home.tsx) reads it via usePlanMaxes and passes it to planProgramToday, and the live-logger source=plan prefill reads it via readPlanMaxes — so once you enter your maxes, 'Your plan today' and the prefilled session show REAL working kg (derived off the %-ramp), not just the %. CROSS-DEVICE SYNC (shipped, SQL-gated): the maxes also persist on the account — a JSONB User.planMaxes column (reference/sql-plan-maxes.sql) read/written via GET+PUT /api/plan-maxes using RAW queries (so it soft-degrades to on-device-only before the column is migrated). Each client hydrates once on first use (merging the server's values over local — server wins per key) and writes the whole map back on every change, and both clear it on sign-out (resetPlanMaxes in session.tsx, mirroring resetPersona) so a shared device never leaks one athlete's maxes. So maxes entered on one device appear on the others once the SQL is applied. LIFT DISCLOSURE (Jul 2026): the Today card's lift list leads with the first lift CLEAR and frosts the next THREE behind a 'Show all N lifts →' reveal — a REAL blur (CSS `filter: blur` + a gradient veil on web today.tsx; an expo-blur BlurView + expo-linear-gradient veil on mobile home.tsx), replacing the old bare ▾ text toggle — so the card teases 'there's more' at a fixed height; expanding lifts the frost and unfolds the remaining rows, collapsing via a quiet 'Hide lifts'. On a plan the primary START action is a full-width button anchored at the BOTTOM of the card (below the [note]); the top row then carries only the readiness dial (athlete), while other Today states keep the compact top-right Start. Both clients at parity; reuses the existing showAllLifts/liftsWord/hideLifts i18n and introduces no middot separator (honours the separator-purge rule in design-system-unification). Explored + verified as reference/glass-card-frosted.html (CSS-only checkbox prototype). REMAINING: NL/intensity-zone day targets on the card are still to surface. See reference/plan-model-redesign.md." },
  { id: "plan-page-hero", area: "Core", status: "shipped", title: "Plan detail — 'The Columns' hero (gradient panel + editorial stats)", detail: "The discipline-shaped plan detail page (the PercentDetail/PercentProgram renderer used by every PlanProgram) opens with a designed hero instead of a small title over a pipe-y meta line — the winning concept ('The Columns') from design/plan-page-redesign-ideas.html. Anatomy, web + mobile at parity: a rounded GRADIENT PANEL in the accent tint (web CSS radial+linear color-mix over ink2, mobile expo-linear-gradient over ink2 — both derive from the theme lime token so the Kyoto-Hour light theme gets a pine/sage wash automatically) carrying a square back chip + the plan's loading tag as a mono label (right), a CHALK-filled goal chip (auto-inverts per theme), and the plan name set big (900/clamp 30–38 web; F.black 33 mobile); then THREE RULE-TOPPED STAT COLUMNS (duration, frequency, and the discipline's own volume metric) and a one-line BLURB. All content comes from ONE shared view model — planHeroView(plan, program) in @hybrid/core plan-program.ts (unit-tested): stats are DERIVED, never authored (weeks + sessions from the plan meta; the third column is week-1 NL for strength-percent ('656 lifts in wk 1' for the Soviet block), week-1 exercise count for hypertrophy/conditioning, total sessions for endurance which has no comparable count; the 'in wk 1' suffix drops on single-week plans), the nav label is the plan's tag ('% of 1RM'), and the blurb is the first sentence of the plan description. The old header MetaLine (weeks │ ×/wk │ tag │ peak-note) is superseded by the columns on this page; the maxes panel, week selector, ProgramDays, progression card and enroll CTA below are unchanged. The CLASSIC (non-program) plan Detail is migrated too: the hero is a shared per-client component (web PlanHero in aurora/plans.tsx; mobile components/plan-hero.tsx) used by BOTH detail renderers, planHeroView's program param is optional (no program → the volume column falls back to total sessions), and the classic header's level fact moved into the info-card grid as a new Level card (i18n w.train.plans.level, en/pl/de) so nothing from the old meta line is lost." },
  { id: "coach-program-builder", area: "Backend", status: "shipped", title: "Coach-authored multi-week program builder", detail: "Type 3 of the plan model (see plans-lib): a coach composes their OWN multi-week program — weeks → days → exercises (name + sets×reps + RPE) — and assigns it to a client or a whole group, which MATERIALIZES it into dated Assignments (week i, day j → start + (i*7 + j) days) on the athlete's account, surfaced via the existing 'Assigned by your coach' Today card + calendar. CoachProgram model (coach-owned; weeks stored as JSON PlanSample[][], reusing the core plan shape so planDayToBlocks() turns each day into session blocks) + reference/sql-coach-programs.sql. APIs: /api/coach/programs (GET/POST), /api/coach/programs/[id] (PATCH/DELETE), /api/coach/programs/[id]/assign (POST {linkId|groupId, startDate} → createMany of the materialized assignments; targets re-validated as ACTIVE links). apps/web/lib/coach-program.ts holds the shared sanitizeProgramWeeks (clamps ≤26 wk / ≤7 days / ≤20 items) + programAssignments materializer. UI: a 'Programs' section in the Coach screen on BOTH clients — web components/coach-programs.tsx and mobile components/coach-programs.tsx (rendered in the classic AND Aurora coach tabs, on the template-aware Card) — list/create/edit (nested week/day/exercise editor)/delete + an assign control (client or group + start date). Every endpoint soft-degrades to 'not enabled yet' until the SQL runs; write routes are body-limit guarded (readJsonLimited) and the 'Programs' section is admin-gateable via the coach.programs feature flag (web + mobile). NOTE: run reference/sql-coach-programs.sql in the Supabase SQL Editor." },
  { id: "coach-verification", area: "Backend", status: "shipped", title: "Verified-coach application (coach is no longer self-serve)", detail: "Coaching others is now gated on a verified COACH role instead of a free persona toggle. A client applies via 'Become a coach' (mobile app/coach-apply.tsx → applyForCoach; web account-settings) → POST /api/coach/apply (own-row upsert, rate-limited, body-capped; rejects existing coach/admin) writes a CoachApplication (pending). An admin reviews the queue in Governance (components/admin/coach-applications.tsx) and approves/denies via PATCH /api/admin/coach-applications/[id] — approve promotes the user's role to COACH in one transaction and audits it (coach.approve); deny audits coach.deny. Mirrors the AccessRequest pattern (admin guard, audit, RLS). NOTE: run reference/sql-coach-applications.sql in the Supabase SQL Editor to create the CoachApplication table; until then the apply/queue routes soft-degrade to an 'aren't enabled yet' message so the deploy is safe in any order." },
  { id: "coach-assign-diet", area: "Backend", status: "shipped", title: "Coach-assigned diet (macro targets, read-only for the client)", detail: "The nutrition analogue of an assigned training plan: a coach sets a client's daily macro targets (kcal / protein / carbs / fat + note) and the client VIEWS them READ-ONLY on their Nutrition screen, above their own free macro logging (editing their own adaptive targets stays the paid upgrade). CoachDiet model (coach-owned, one per coach↔client; prisma + reference/sql-coach-diet.sql) with @@unique([coachId, clientId]). APIs: GET/POST /api/coach/links/[id]/diet (CoachLink-gated: coach owns + ACTIVE; upsert, clamped/body-limited) and GET /api/nutrition/assigned (the client reads the diet assigned by an ACTIVE coach — ending the link withdraws it). UI: a shared CoachDiet editor (web components/coach-diet.tsx + mobile components/coach-diet.tsx) in the client-detail view of the classic AND Aurora coach screens; the client-side read-only band on the web + mobile Nutrition screens. Soft-degrades to 'not enabled yet' until reference/sql-coach-diet.sql is run. NOTE: v1 is macro targets; a full structured meal plan is a later expansion." },
  { id: "coach-client-invite", area: "Backend", status: "shipped", title: "Coach-led client onboarding (invite by link / QR / email)", detail: "A coach can add a client who isn't on HYBRID yet. ONE CoachInvite (prisma + reference/sql-coach-invites.sql) backs all delivery methods: a copyable invite LINK, a QR code the client scans, or an EMAIL (stored for auto-match). The client CLAIMS it on first sign-up — by opening the link/QR (web app/invite/[token]/page.tsx; mobile app/invite/[token].tsx) OR an email auto-match in /api/me (claimPendingCoachInvites mirrors the org-invite claimPendingInvites) — which creates an ACTIVE CoachLink (the act of claiming IS the consent; decided 2026-06-19). The claimed client lands on the FREE plan with read-only access to what the coach assigns (see persona-shape: coached = casual + read-only). APIs: POST/GET /api/coach/invite (create/list, coach-only, roster-capped, body-limited), GET/DELETE /api/coach/invite/[token] (public-by-token info for the claim page / coach revoke), POST /api/coach/invite/[token]/claim (signed-in claim → ACTIVE link, single-use, expiry-checked). If the email already belongs to a HYBRID user it falls back to the existing-user PENDING-link path. A stashed token is also auto-claimed post-login (web CoachInviteBanner; mobile session provider). UI: shared CoachInvite component on BOTH clients (web components/coach-invite.tsx — QR via the qrcode lib's toDataURL; mobile components/coach-invite.tsx — QR drawn as a View matrix from qrcode's module data, no native dep so the iOS export stays green; Share API for the link) rendered in the classic AND Aurora coach screens. Tokens are random (18-byte hex), single-use, 30-day expiry. NOTE: run reference/sql-coach-invites.sql in the Supabase SQL Editor; until then every invite endpoint soft-degrades to 'not enabled yet'. Native deep-link app-open (QR → app rather than web) lands with the EAS build (see coach-invite-sms/mobile-preview); today the QR encodes the web URL which works now." },
  { id: "coach-invite-sms", area: "Integrations", status: "blocked", title: "Coach invite — automated SMS/phone delivery", detail: "The invite model already stores a client phone; v1 delivery is the QR + copyable link (the coach sends it via their own channel) plus email auto-match. Automatically TEXTING the invite link needs a third-party SMS provider.", blockedBy: "An SMS provider account + credentials (e.g. Twilio ACCOUNT_SID/AUTH_TOKEN + a sending number, or Vonage) in the server env, then a send step in POST /api/coach/invite when a phone is supplied. Carries per-message cost." },
  { id: "coach-invite-email", area: "Integrations", status: "shipped", title: "Coach invite — automated email delivery", detail: "When a coach supplies an email on a pre-account invite, POST /api/coach/invite now SENDS the invite link directly via the email system (sendEmail, transactional) — the coach no longer has to copy/share the link by hand (the link/QR are still returned as a fallback, and the email still auto-matches on sign-up). Best-effort: the response carries emailSent so the UI can confirm. Runs on the same Resend config as email-marketing; if email isn't configured it silently falls back to the manual link (no failure). The SMS analogue is still blocked (see coach-invite-sms)." },

  { id: "coach-verified", area: "Backend", status: "shipped", title: "Verified-coach tick", detail: "A coach whose credentials an admin has vetted carries a verified badge — User.coachVerified (prisma + reference/sql-coach-verified.sql). Set automatically to true when an admin APPROVES a coach application (apps/web/app/api/admin/coach-applications/[id]) and togglable on the admin Users → user record (the user PATCH route + the drawer's 'Verified coach' checkbox, shown for COACHes; audited). Surfaced as a '✓' next to the coach's name wherever a CLIENT sees them, on BOTH clients in BOTH templates: web classic + Aurora coach screens ('Your coach' + incoming coaching requests) and the web CoachInviteBanner; mobile classic + Aurora coach tabs. The flag rides on the coach object returned by GET /api/coach/links (and /api/me for the coach themselves). Soft-degrades until reference/sql-coach-verified.sql is run (the column simply reads false). NOTE: run reference/sql-coach-verified.sql in the Supabase SQL Editor." },

  { id: "admin-user-plan", area: "Backend", status: "shipped", title: "Admin sets a user's plan (Free ⇄ Premium)", detail: "An admin can change any account's entitlement between free and paid from Admin → Users → the user record (a Plan select in the drawer, plus a Free/Premium add-user default and a Plan column + chip in the table). PATCH /api/admin/users/[id] routes the change through setEntitlement (apps/web/lib/billing.ts) so it updates the DB entitlement AND mirrors 'paid'/'free' into the Supabase auth user_metadata — both clients unlock/lock Full from their session, exactly like a real purchase — and fires the `upgraded` lifecycle email automation when moving to paid. The change is audited (before/after). The auth-metadata mirror needs SUPABASE_SERVICE_ROLE_KEY to propagate to the clients (the DB always updates regardless — see entitlement-mirror)." },

  { id: "admin-user-delete-wipe", area: "Backend", status: "shipped", title: "Delete user — full record wipe (+ auth account)", detail: "Admin → Users → Delete now wipes EVERYTHING the account touches, not just the headline tables. DELETE /api/admin/users/[id] cascades sessions/macrocycles/biometrics/signals/checkins/rtp/videos/events/risk/talent/connections/memberships/templates/assignments/coachNotes/coachLinks AND the previously-missed coach-owned artefacts (coachGroups, coachPrograms, coachInvites incl. claimed, coachDiets as coach AND client), the coachApplication, and the user's email footprint (enrollments + the EmailMessage ledger — the EmailSuppression opt-out row is deliberately KEPT to honour an unsubscribe/bounce permanently per CAN-SPAM/GDPR) — then the User row. It ALSO now deletes the Supabase AUTH user via the service-role admin client (previously the code claimed to but didn't, leaving an orphaned login), best-effort + reported in the response/audit (authDeleted: deleted|skipped|failed). The same last-admin / self-delete lockouts and the type-the-email confirm remain. CONFIRM UX (Jul 2026): the destructive confirm is now a designed in-app modal (alertdialog) on web — it names the account, spells out the cascade, gates the button behind typing the email back, and shows a LIVE spinner while the request is in flight so 'Deleting…' never reads as stalled (mobile mirrors this with a native destructive Alert + a spinner on the busy button). The old bare window.prompt is gone. Auth deletion degrades to a no-op without SUPABASE_SERVICE_ROLE_KEY (the DB wipe is authoritative)." },

  { id: "admin-user-create", area: "Backend", status: "blocked", title: "Admin creates a user (real loginable account)", detail: "Admin → Users → '+ Add user' provisions a brand-new account: a modal takes email, name, role, plan (free/premium), language, an optional initial password and a 'send verification/welcome email' toggle. POST /api/admin/users creates a REAL Supabase auth user via the service-role admin API (so the person can actually sign in — confirmed immediately if a password is set, otherwise a magic-link verification email is sent), mirrors it into the User row in the same flow (cleaning up the auth user if the DB write fails), enrolls them into any active `signup` email sequence, and audits it. Code-complete; degrades to a clear 503 until the service-role key is configured.", blockedBy: "SUPABASE_SERVICE_ROLE_KEY is now set in the deployment — the only thing left is to confirm a live create (add a user with a test email) to flip this to shipped. STANDING DEPENDENCY (don't forget): account creation needs the Supabase service-role key, and the welcome/verification email rides on Resend (see email-marketing); keep both set in every environment." },

  { id: "email-marketing", area: "Integrations", status: "blocked", title: "Email — transactional, marketing & lifecycle automation", detail: "A full email system, provider-agnostic via the Resend HTTP API (no SDK dep) with graceful degradation — every send is a recorded no-op until the key is set, so the whole console works end to end the moment it's configured. SHARED CORE (packages/core/src/email.ts, unit-tested): audience segments (all/free/paid/coaches/clients/admins), lifecycle triggers (signup/inactive/trial_ending/upgraded/coach_approved/manual), {{merge}}-tag rendering, and the sequence scheduling math. SERVER (apps/web/lib/email.ts): sendEmail (renders merge tags, honours the suppression list for marketing, brand HTML shell + one-click List-Unsubscribe, lands an EmailMessage ledger row every time), audience→Prisma queries, sendCampaign fan-out, enrollInTrigger, and sendAccountVerification (generates a Supabase magic-link and delivers it via Resend). ADMIN CONSOLE (Admin → Business → 'Email & marketing', components/admin/email.tsx): an overview (provider status + audience sizes + ledger totals), CAMPAIGNS (compose a broadcast to a segment, schedule or send now, history with sent/failed tallies), and SEQUENCES (multi-step drip editor with per-step delays, trigger + audience, activate/pause, enrollment counts). API: /api/admin/email(+/campaigns, /campaigns/[id], /campaigns/[id]/send, /sequences, /sequences/[id]) — all admin-gated, rate-limited, audited. AUTOMATION runs on a cron worker (/api/cron/email, CRON_SECRET-auth, triggered hourly by a GitHub Actions schedule — .github/workflows/email-cron.yml — because Vercel's Hobby plan caps cron at once/day; switch to native Vercel Cron on Pro): sends due scheduled campaigns, advances every due sequence enrollment one step, and auto-enrolls newly-dormant users into active win-back sequences. Triggers are wired into the app: signup (first DB-user creation), upgraded (setEntitlement→paid), coach_approved (application approval). PUBLIC one-click unsubscribe (/api/email/unsubscribe, HMAC-signed) writes the suppression list. Data model: EmailCampaign/Sequence/SequenceStep/Enrollment/Message/Suppression (reference/sql-email.sql), all soft-guarded so the app runs before the migration.", blockedBy: "Creds are now set in the deployment (RESEND_API_KEY + a verified EMAIL_FROM domain, CRON_SECRET for the hourly worker, SUPABASE_SERVICE_ROLE_KEY for verification links) and reference/sql-email.sql has been run — the only thing left is a live-delivery smoke test (send a campaign to the Admins segment) to flip this to shipped. STANDING DEPENDENCY (don't forget): the entire email system runs on Resend — an EXTERNAL, per-email-cost provider; RESEND_API_KEY + a verified EMAIL_FROM domain + CRON_SECRET must stay set in EVERY environment or all sends silently no-op. See .env.example." },
  { id: "email-batch-send", area: "Integrations", status: "planned", title: "Email — batch/chunked sending for large audiences", detail: "Today campaigns + sequence steps send ONE Resend HTTP request per recipient, sequentially. That's fine at the current scale (the 'send now' route caps inline sends at 250 recipients + raises maxDuration to 300s, and hands larger audiences to the hourly cron worker which is also bounded). For LARGE lists this should move to Resend's Batch API (POST /emails/batch, up to 100 messages/request) and/or a bounded concurrency limiter, plus per-campaign send-progress tracking so the cron can RESUME a partially-sent campaign across runs instead of restarting. Until then very large broadcasts could exceed even the worker's window.", },
  { id: "full-billing", area: "Backend", status: "blocked", title: "Paid entitlement / subscription billing (consumer Full upgrade)", detail: "The Full (athlete) experience is a PAID tier — resolvePersona only grants the athlete persona when the account carries a paid Entitlement, read from auth session.user_metadata.entitlement on both clients (default 'free'). The ENTIRE flow is now code-complete — only external credentials remain, tracked as the three sub-items below (full-billing-stripe, entitlement-mirror, full-billing-iap). WEB (Stripe): apps/web/lib/billing.ts (lazy Stripe client, entitlement helpers) + routes POST /api/billing/checkout (hosted Checkout subscription), POST /api/billing/portal (manage/cancel), GET /api/billing/status, and POST /api/billing/webhook (signature-verified; checkout.session.completed + customer.subscription.* → setEntitlement). account-settings shows an 'Upgrade to Full' button (free) and 'Manage subscription' (paid). MOBILE: app/upgrade.tsx 'Subscribe' button → startCheckout() opens the hosted Checkout; POST /api/billing/iap/verify is built on the App Store Server API (StoreKit 2) — JWS-signature-verified transaction lookup, product/expiry checked — for the native IAP path. PROPAGATION: setEntitlement writes the DB User (entitlement/stripeCustomerId/subscriptionStatus columns — reference/sql-billing.sql) AND mirrors entitlement into Supabase auth user_metadata via a service-role admin client (lib/supabase/admin.ts), so both clients read it from their session (web auto-refreshes on /app?upgraded=1). Every entry point degrades to a 'not configured' 503 until the keys are set, so the deploy is safe meanwhile. DEVICE CHOICE NEVER OUTRANKS THE ACCOUNT: the Simple/Full mode choice is stored per-device (localStorage / AsyncStorage) while the entitlement lives on the account, so both persona stores now pipe the stored choice through core's effectiveClientChoice() before resolvePersona — a 'casual' recorded while the account was still FREE (the onboarding answer) is dropped the moment the account is paid. Without it, anyone who became paid other than by tapping upgrade in that very app instance (bought on the web then opened the phone, restored an IAP, or was granted Full by an admin) kept the free surface on every device holding the old answer — Cockpit/Performance, HPI and Recipes locked behind the teaser with 'Switch to Full' as the only escape. A Simple mode chosen DELIBERATELY while paid (Settings → Mode) is recorded as such and still honoured. NOT to be confused with 'billing' (coach/SMB monetization — a separate revenue layer).", blockedBy: "Three external dependencies, each tracked as its own capability below: full-billing-stripe, entitlement-mirror, full-billing-iap. Plus run reference/sql-billing.sql in the Supabase SQL Editor. See .env.example." },
  { id: "full-billing-stripe", area: "Backend", status: "blocked", title: "Full upgrade — Stripe keys + webhook (web checkout)", detail: "The web Stripe path is built (apps/web/lib/billing.ts + /api/billing/checkout, /portal, /status, /webhook) and powers the 'Upgrade to Full' / 'Manage subscription' buttons in account-settings. It degrades to a 503 'not configured' until the keys land, so deploying now is safe.", blockedBy: "A Stripe account, then set in the server env: STRIPE_SECRET_KEY, STRIPE_PRICE_FULL (the Full subscription Price id), STRIPE_WEBHOOK_SECRET, and NEXT_PUBLIC_APP_URL (redirect origin). Create a Stripe webhook pointed at POST /api/billing/webhook subscribed to checkout.session.completed + customer.subscription.* . See .env.example." },
  { id: "entitlement-mirror", area: "Backend", status: "blocked", title: "Full upgrade — service-role key to push 'paid' to the clients", detail: "On a successful purchase (or an admin plan change — see admin-user-plan), setEntitlement updates the DB AND mirrors the entitlement into Supabase auth APP_METADATA via the service-role admin client (apps/web/lib/supabase/admin.ts patchUserAppMetadata) so both clients read 'paid' straight from their session. SECURITY (2026-07 audit, H-4): the mirror moved from user_metadata to app_metadata — user_metadata is writable by the end user via supabase.auth.updateUser({ data }), so mirroring a paywall flag there was a self-upgrade trap; app_metadata is service-role-only. Clients read entitlement from app_metadata first (legacy user_metadata fallback), and the DB column from /api/me is the authoritative override. Without the key the DB still updates, but a user wouldn't see Full unlock until they next re-authenticate. SUPABASE_SERVICE_ROLE_KEY is now set in the deployment, so the mirror is live (already exercised by admin-driven plan changes); this stays surfaced only because it's part of the broader full-billing flow that still needs Stripe (see full-billing-stripe).", blockedBy: "SUPABASE_SERVICE_ROLE_KEY in the server env (Supabase → Settings → API → service_role) — now set. Server-only — never exposed to the browser." },
  { id: "full-billing-iap", area: "Mobile", status: "blocked", title: "Full upgrade — Apple In-App Purchase (iOS)", detail: "POST /api/billing/iap/verify is built on the modern App Store Server API (StoreKit 2), migrated off the deprecated verifyReceipt/shared-secret path. The native client posts a transactionId; apps/web/lib/apple-iap.ts authenticates to Apple with an App Store Connect API key (.p8, JWT-signed by @apple/app-store-server-library), fetches the signed transaction and CRYPTOGRAPHICALLY VERIFIES its JWS signature chain back to an Apple root CA before pinning the product id + unexpired window and calling setEntitlement('paid'). Config is env-driven + lazy, root certs loaded from APPLE_ROOT_CERTS_DIR (apps/web/lib/apple-root-certs, see its README), so the route degrades to a 503 'not configured' until everything is set — deploy-safe. The Apple .p8 sandbox key is in hand (Key ID RQTCHVF25S) and Apple's public root CA certs (G3/G2/Inc) are committed under apps/web/lib/apple-root-certs. The NATIVE IAP CLIENT IS NOW BUILT: react-native-iap v15 (Nitro/StoreKit 2) + its Expo config plugin, apps/mobile/lib/iap.ts (purchaseFull → requestPurchase subs → on success POSTs the transactionId to /api/billing/iap/verify → finishTransaction), wired into app/upgrade.tsx (iOS uses native IAP, web/Android fall back to hosted Stripe Checkout) and the session refreshes so the mirrored 'paid' entitlement unlocks Full immediately. Mobile typecheck + iOS bundle export both green. APP-STORE COMPLIANCE HARDENING (2026-07 audit): the paywall + IAP now meet Apple's auto-renewable-subscription requirements — (1) a LAUNCH-TIME transaction listener (startIap in app/_layout.tsx) verifies + grants + finishes any transaction that completes with no purchase UI open (interrupted / Ask-to-Buy / renewal / another-device), so paid-but-not-granted states can't happen; (2) a 'Restore purchases' button on the paywall (restorePurchases → getAvailablePurchases → server verify); (3) the paywall shows the LOCALIZED StoreKit price (fetchFullPrice → fetchProducts) instead of a hardcoded $9.99; (4) Terms + Privacy links on the paywall (shared LegalLinks); (5) 'Manage subscription' opens Apple's native sheet (showManageSubscriptionsIOS) on iOS instead of looping back to the paywall. The remaining work is all external/operational, not code.", blockedBy: "(1) Set the server env (see .env.example): APPLE_IAP_PRIVATE_KEY (the .p8 contents), APPLE_IAP_KEY_ID, APPLE_IAP_ISSUER_ID, APPLE_IAP_BUNDLE_ID, APPLE_IAP_PRODUCT_FULL (+ APPLE_IAP_APP_APPLE_ID for Production). (2) Create the auto-renewable 'Full' subscription product in App Store Connect (id must match APPLE_IAP_PRODUCT_FULL / EXPO_PUBLIC_IAP_PRODUCT_FULL). (3) An EAS build to run the native module on-device (needs an Expo token) — react-native-iap can't run in Expo Go or the web bundle. Apple Developer account is now OBTAINED (no longer a blocker); first sandbox purchase is the live test." },
  { id: "account-settings-pro", area: "Web", status: "shipped", title: "Professional account settings (General / Security / Privacy / …)", detail: "SHIPPED v1 — the web Settings (components/account-settings.tsx) is now a professional TABBED account area (General – Security – Coaching & access – Privacy & data) instead of one flat stack, preserving every existing flow. GENERAL: a new Account identity card (name/email + role + Free/Full-paid + provider badges, sign out) and a new Preferences card with REAL working controls — Appearance (dark/light via use-theme), Language (EN/PL/DE via useLang) and the Workout-logger Simple/Detailed toggle (logger-settings) — plus the existing Mode + billing (upgrade/manage). SECURITY: the existing MFA settings + an honest password/sessions note (provider-aware). COACHING & ACCESS: the existing Become-a-coach application + Request-a-feature. v2 FILLED THE GAPS (all SQL-free, on the user's own Supabase auth — no admin/backend tables): a 6-tab area (General – Notifications – Privacy – Security – Coaching & access – Data). GENERAL now has an EDITABLE PROFILE (display name → user_metadata, change email → auth.updateUser) on top of identity + the real Appearance/Language/Logger toggles + Mode/billing. NOTIFICATIONS + PRIVACY are real persisted preference sections (weekly recap / coach messages / check-in reminders / product updates; share-detail-with-coach / discoverable-in-talent / analytics-opt-out) stored in auth user_metadata so they sync across the user's devices (microcopy is honest: saved + honoured as channels roll out). SECURITY: MFA + change-password (auth.updateUser) + 'Sign out everywhere' (global signOut). DATA: 'Download my data (JSON)' (GET /api/account/export — read-only, gathers every user-owned table best-effort) above the Danger-zone reset. Everything degrades cleanly in demo mode (no Supabase). MOBILE PARITY (shipped): the mobile Settings — BOTH the classic (app/settings.tsx) and Aurora (components/aurora/settings.tsx) variants — now carry the same sections: editable profile (display name + change email), Notifications + Privacy preference toggles, change-password + Sign-out-everywhere (Security), and Download-my-data (the export JSON is fetched with the Bearer token, written to a cache file via expo-file-system and opened through the expo-sharing sheet). The notification/privacy row defs + keys are shared in @hybrid/core (account.ts — ACCOUNT_NOTIF_ROWS/ACCOUNT_PRIVACY_ROWS + defaults) and consumed by BOTH clients, and the mobile logic lives in a shared lib/account.ts hook used by both variants, so web ⇄ mobile can't drift. NEXT (deferred): active-session/device LISTING (needs the service-role admin API), cross-device sync of the per-device logger prefs, and Connections (Apple Health/wearables — the standing EAS/Apple-account blocker). ORIGINAL PLAN: Consolidate today's scattered settings into a proper, sectioned Account area on BOTH clients — web Settings is currently a single ~350-line stack (persona Mode, Become-a-coach, billing Upgrade/Manage, a Danger zone, Sign out) plus a separate MFA component, with language + theme up in the header; mobile has app/settings.tsx. Reorganize into clear sections and FILL THE GAPS: GENERAL/PROFILE (display name, avatar, email, units kg/lb, language, appearance/theme, timezone); ACCOUNT (change email, change password, mode/persona, manage subscription — billing already built); SECURITY (password, two-factor — mfa.ts/account/mfa.tsx already built — plus active sessions/devices + sign-out-everywhere + login history, which are NEW); PRIVACY (profile visibility, what a linked coach can see, analytics/marketing opt-out, consents — NEW); NOTIFICATIONS (push + email prefs: rest alerts, weekly recap, coach messages, check-in reminders — NEW, pairs with the notification infra); DATA (export my data / GDPR, delete account — Danger zone + an export hook already exist); COACHING & ACCESS (become a coach, manage coach links, request feature access — all already built, just re-homed); CONNECTIONS (wearables / Apple Health — future, gated on the wearables work). Reuses the existing pieces (MFA, billing, persona toggle, request-access, danger zone, language, theme) and ABSORBS the configurable-logger settings (logger-settings) as its own section. Shared section definitions + defaults in @hybrid/core so web + mobile stay in lockstep; new prefs persist per-device first then sync via a User-prefs column. Likely split into a few PRs (the shell + reorg first, then each new section). v3 REDESIGN (Instagram-style hub, both clients): the tabbed/flat layout is replaced by a categorised accordion HUB — a profile header (avatar + name + role/Free–Full badges + email) over four labelled groups (How you use HYBRID – Who can see & reach you – Login & billing – Your data & support), each a glass list of icon rows that EXPAND inline to their controls. The information architecture (group order, the 10 categories — account/preferences/logger/notifications/privacy/coaching/security/subscription/data/danger — and each row's icon/title/subtitle) is a SINGLE SOURCE OF TRUTH in @hybrid/core settings-nav.ts (SETTINGS_GROUPS / SETTINGS_CATEGORIES), so web (components/account-settings.tsx) and mobile (components/aurora/settings.tsx) render the same hierarchy and can't drift. Every existing flow is preserved and re-homed into a row (profile edit, appearance/template/language, logger detail+units+volume, notification/privacy toggles, become-a-coach + request-access, MFA + password + sign-out-everywhere, Simple/Full mode + Stripe billing, data export, danger-zone reset). On web each row expands inline (accordion); on mobile most expand inline (LayoutAnimation) and logger/coaching/subscription navigate to their existing dedicated screens (/logger-settings, /coach-apply, /upgrade). Built on the real Aurora glass tokens + the shared Aurora icon set (AuroraIcon) on both clients. Mockup explorations live in reference/settings-mockups/. Classic mobile (app/settings.tsx) keeps its existing layout (Aurora is the default skin on both clients)." },
  { id: "profile-settings-redesign", area: "Core", status: "shipped", title: "Instagram-grade profile & settings polish (both clients)", detail: "First tranches of the profile/settings redesign, shipped web+mobile in lockstep: (1) a dedicated 'edit' pencil glyph — a shared @hybrid/core SVG path + a matching 48×48 mobile PNG (assets/icons/edit.png) — on the profile-head edit-profile button so it's no longer the settings gear (the two read as the same action next to the avatar). (2) The 'Security' settings category renamed to 'Password & security' (Instagram's wording) via one change in the shared settings-nav. (3) The Password & security screen rebuilt from a single password box into two Instagram-style groups: 'Login & recovery' (MFA on web + change-password with a LIVE password-strength meter + a Connected-account line) and 'Security checks' ('Where you're logged in' → a This-device indicator + Sign-out-everywhere). Password strength is a shared, unit-tested core helper (passwordStrength — 0–4 score + weak/fair/good/strong, gates the app 8-char minimum) consumed identically by both clients; new i18n keys in EN/PL/DE. Verified: core tests (686) + web/mobile typecheck green. Remaining redesign MOVES are still to build: the unified single 'Edit profile' screen (merging Account & profile + Public profile), avatar upload (blocked on the social-avatar-upload Storage bucket), the live 'what followers see' preview, inline per-field validation, the Settings-header completeness ring, and the full rich treatment on every other tab (Preferences / Logger / Notifications / Privacy / Coaching / Subscription / Data). Mockup: design pitch published as an artifact. (4) HEADLINE MOVE — the unified single 'Edit profile' screen: 'Account & profile' and 'Public profile' are MERGED into one settings category ('Edit profile') on both clients — the separate 'social' category is removed from the shared settings-nav, and the profile-head pencil + Settings both open the same surface. It stacks the public profile (avatar, handle, display name, bio, visibility) over the account identity (name, email). AVATAR now has a real preview + one-tap branded GRADIENT PRESETS (six tiny PNG data-URIs in @hybrid/core AVATAR_PRESETS that persist in avatarUrl and render through the existing <img>/<Image> paths on both clients — no renderer change, no Storage bucket), plus an honest disabled 'Upload photo (soon)' affordance. Verified additionally: web prod build + mobile iOS bundle export green. (5) Live 'what followers see' PREVIEW card atop the editor (avatar / name / @handle / bio / visibility badge, re-renders as you type) + INLINE VALIDATION on both clients: a debounced handle-availability check (green ✓ available / red ✕ taken, using the /api/social/profile/:handle 404-vs-profile signal, with a 'this is your handle' case), instant format-rule feedback, and a live bio character counter (n/280). (6) MOVE 5 — the Settings header is now a launchpad: a completeness RING around the avatar (web = an SVG arc; mobile = a lime ring + a proportional bar, since RN has no inline SVG here) showing the % + an 'Add a photo & a bio' nudge, driven by a shared, unit-tested profileCompleteness() helper (name / handle / display name / bio / photo). The whole header is tappable → Edit profile, with quick-action chips (Edit profile – Share — native share sheet / clipboard of the @handle). (7) The per-tab TREATMENT pass (both clients): Preferences theme-swatch cards; Notifications + Privacy grouped sub-headers (via a shared PrefRowDef `group`); the Data tab's 'what's included' export checklist; the Subscription tab's Full-benefits list (FULL_BENEFITS, shared with the upgrade sheet so they can't drift); and the Coaching 'how it works' 3-step intro (web + the mobile coach-apply screen). Logger already carried its full toggle set. (8) ROW-DRILL — Edit profile is now the exact Instagram tap-a-row layout: a live preview + the avatar/presets on top, then a row list (Name / Username / Display name / Bio / Email / Visibility) where each row opens a FOCUSED single-field editor with its own validation (live handle availability, bio counter) and Save; name/email persist via Supabase auth (threaded into the shared SocialProfileEdit), the rest via the social API. The redesign is feature-complete; the only deferred piece is the real photo UPLOAD (blocked on the avatars Storage bucket — social-avatar-upload), with gradient presets shipping as the interim. Verified across every tranche: core tests + web/mobile typecheck + web prod build + mobile iOS bundle export." },
  { id: "persona-access", area: "Web", status: "shipped", title: "Admin access control — who sees what (per-persona nav)", detail: "An admin tool to choose what each persona sees, so retail users aren't overloaded yet anyone can be granted depth on request. Admin → Governance → 'Access control' (components/admin/access.tsx) is a per-nav-item matrix: the admin sets the MINIMUM persona each feature is visible from (Casual ⊂ Athlete ⊂ Coach ⊂ Admin) — drop Velocity/Analytics to Casual to give an average-Joe the stats, or raise an item to hide it. Pure core layer: a sparse PersonaAccess map ({ navId: minPersona }) overrides the code minPersona defaults; navForPersona/navVisibleTo take an optional override and sanitizePersonaAccess validates the payload (only known ids → valid personas), all unit-tested (404 core tests). STORAGE reuses the feature-flags infra with NO new table — the map is the value of a new registry flag access.personaNav, written via the existing admin flags POST (admin-gated, rate-limited, body-capped, AUDITED as flag.upsert) and read via /api/flags. CONSUMED on BOTH clients: the web sidebar + ⌘K hub filter through navForPersona(persona, …, access); mobile reads it (lib/access.ts store + useNavAccess hook over /api/flags) and applies it to the More hub + command menu + the cockpit entry. Changes take effect on the next client load — no deploy. Persistence needs the FeatureFlag table (reference/sql-feature-flags.sql); until applied it runs on code defaults and the screen says so. The Access control screen also carries the read-only RBAC role model (Client/Coach/Admin data-access permission matrix), moved here from the retired user-facing 'Roles & access' screen (the plan/entitlement 'what each plan gets' matrix now lives in the admin Business → Financials console). REMOVED (Jul 2026): the earlier PER-USER 'individual access' layer — admin-granted per-person FeatureGrants + the user-facing 'Request a feature' loop (AccessRequest) — was deleted end-to-end (web + mobile UI, /api/access-requests + /api/admin/access-requests routes, the FeatureGrant/AccessRequest Prisma models, and the /api/flags grant-fold). Access is now purely the per-persona matrix; there is no longer any one-off unlock-for-one-person path. NOTE: an earlier 'per-feature casual hidden/locked bait' axis was also REMOVED — scattering padlocks both undersold Full (looked like one screen) and cluttered the lean casual app; the freemium upsell is a single Unlock Full page (see 'full-upgrade-page'). The matrix is min-persona only." },
  { id: "athlete-cockpit", area: "Mobile", status: "shipped", title: "Athlete cockpit (the depth, organized)", detail: "Phase 2: a single mobile screen (app/cockpit.tsx) that assembles the data-athlete's scattered depth into one coherent path — Goal & season (the enrolled macrocycle's current phase/week, or a 'set up a plan' prompt) → Today's route (the velocity-aware prescription + readiness, Start) → Performance (the Athlete Twin: HPI score/band/limiter + pillar split + the top state driver) → Sport S&C (the saved sport + level) → Velocity & technique → Endurance (whole-history run totals). Each section shows a LIVE snapshot computed off the athlete's real sessions/signals (prescribeSession, computePerformanceState, runTotals, toBiometrics) and links out to the deep screen, so the athlete stops hunting through a flat menu for their cockpit. Surfaced ONLY to the athlete/coach personas (see persona-shape): a persistent Cockpit tab in the mobile bottom bar (athlete-gated via navVisibleTo, hidden for casual — the mobile parallel of the web sidebar's Home → Cockpit item) + a featured card atop the More hub; casual users never see it. WEB PARITY shipped too — a 'cockpit' nav item (nav.ts, minPersona athlete) + components/cockpit.tsx render the same six live sections (jumping to the deep web screens: Periodize/Log/Performance/Sport/Velocity/Running), wired into the app-shell. Honest empty states until there's training to compute from. The only remaining piece is the still-blocked real input streams it would feed on (Apple HealthKit recovery sync + camera pose-capture for the technique engine — see wearables / vbt-capture / video-intel, all gated on an EAS build + native modules/credentials)." },
  { id: "home-two-tab", area: "Web", status: "shipped", title: "Home consolidated to two tabs (Today + Cockpit)", detail: "The home nav group is two tabs now, not four. The old Dashboard (a web-only mirror that ran on a hardcoded demo macrocycle) is RETIRED — its two unique surfaces moved onto Today and now run on the athlete's REAL enrolled season: the macrocycle phase timeline (Base→Build→Peak→Taper, current phase/week highlighted) and the injury-risk-by-tissue panel (folded into the Athlete Twin card via computeInjuryRisk). 'Get started' (onboarding) is no longer a standalone tab either — see the onboarding capability (folded into Cockpit's 'Goal & season' as a 'Set up / change plan' flow; first-run still routes new accounts in). nav.ts drops both dashboard + onboarding from NAV_ITEMS (the casual lean-set unit test updated to match), and the web app-shell/screens.tsx drop the DashboardMirror screen. MOBILE PARITY: the mobile Today gained the identical season phase-timeline bar + injury-risk-by-tissue panel; Cockpit is a persistent bottom-bar tab (app/(tabs)/cockpit.tsx) for the athlete persona so the two-tab home reads the same on both clients, and the old redundant Today cockpit promo card was dropped; mobile's More keeps the onboarding tile (special-cased now that it's not a nav item). FREEMIUM FUNNEL (revised — see 'full-upgrade-page'): a casual (free) user keeps a CLEAN nav with NO scattered padlocks and NO locked Cockpit tab; the entire paid toolkit is sold on ONE 'Unlock Full' page reached from a single value-labeled entry, so the upgrade's full value is clear without cluttering the lean app." },
  { id: "funnel-analytics", area: "Core", status: "blocked", title: "Upgrade funnel instrumentation", detail: "The freemium funnel is instrumented end-to-end at the call-sites: shared event names in core (analytics.ts FUNNEL — upgrade_entry_click / upgrade_page_view / upgrade_cta_click), fired through a provider-agnostic track() shim on both clients (apps/web/lib/track.ts + apps/mobile/lib/track.ts) from the Unlock Full entries (web sidebar; mobile Today + More), the bundle page view, and the CTA. The shim is a safe no-op (dev-logs only) until an analytics provider is wired — do that in ONE place and every call-site reports for free. So conversion is measurable the moment a provider lands.", blockedBy: "Pick an analytics provider (PostHog / Segment / GA4 / Amplitude) and set its key, then forward `track()` to it (and ideally join with the billing purchase event for end-to-end conversion)." },
  { id: "full-upgrade-page", area: "Web", status: "shipped", title: "Unlock Full — one bundle upgrade page (clean freemium funnel)", detail: "The freemium upsell is a SINGLE value-labeled surface, not scattered per-feature padlocks (which both undersold Full as 'one screen' and cluttered the lean casual app). A casual (free) user keeps a clean nav; one pinned 'Unlock Full' entry (web sidebar; mobile a Today card) opens an Upgrade page that sells the WHOLE toolkit — a flagship Cockpit card + grouped bundle (Train smarter / Your performance / Sport & technique / Endurance & body), a '12+ pro tools' framing and the CTA. Web: components/upgrade.tsx (screen 'upgrade', nav.upgrade i18n), CTA hits /api/billing/checkout (or flips a paid-but-Simple user straight to Full). Mobile: app/upgrade.tsx reuses the existing IAP/Stripe subscribe flow with the same bundle content. The Cockpit teaser remains only as a deep-link fallback. Casual no longer sees a locked Cockpit tab on either client. OPEN FOLLOW-UPS (deliberately deferred): (1) PRICING/TRIAL — the page shows no fixed price yet ('pricing shown at checkout', CTA 'Upgrade to Full'); set the real monthly price + any free-trial copy once the Stripe/IAP products are live (see full-billing-stripe / full-billing-iap for the products + keys). (2) ANALYTICS — the funnel is instrumented but reports nowhere until a provider is wired (see funnel-analytics).", },
  { id: "onboarding", area: "Web", status: "shipped", title: "Guided onboarding → first plan", detail: "A guided intake (persona, goal, experience, days/week, equipment) → a personalized first plan via recommendPlan (onboarding.ts, pure + tested). The main-goal options are sourced directly from the plan library's goals (GOAL_TREE) so the two never drift; the chosen goal maps straight onto its node and picks the plan whose weekly frequency fits — a 3-day lifter never gets the 6-day split they'd quit. Enrolls the macrocycle on completion. When the chosen goal has no plans yet (current state — the library is empty), the picker shows a 'plans coming soon' card with a Continue-to-the-app action instead of dead-ending. NO LONGER A STANDALONE TAB — folded into Cockpit's 'Goal & season' as an inline 'Set up / change plan' expander on web, a routed setup screen (reached from Cockpit + More + the Home banner) on mobile; first-run still routes a brand-new account straight into it. DYNAMIC, ADMIN-EDITABLE QUESTIONS (admin → Onboarding): the questionnaire is DATA, not hard-coded UI. @hybrid/core DEFAULT_ONBOARDING_QUESTIONS holds the five built-ins (persona/goal/experience/days/equipment) as the seed + fallback; the OnboardingQuestion table stores the admin's edits — reword, reorder, enable/disable, and ADD/REMOVE custom questions (single/multi/number/text). Engine-relevant answers feed the recommendation via an `engineKey` (recommendFromAnswers); custom questions are saved to the profile and ignored by plan matching, so the engine never breaks. Both clients (classic + aurora, web + mobile) fetch /api/onboarding/questions and render every kind generically; admin mutations are ADMIN-gated + audited; reference/sql-onboarding.sql. SERVER-SIDE GATING (the fix for 'I never got onboarding'): completion is the OnboardingState table (its own table off the User hot path; surfaced as `onboardedAt` on /api/me, falling back to 'already has a plan' so existing users aren't nagged). A client who hasn't onboarded is routed into the questionnaire on entry — web app-shell + mobile index gate — and POST /api/onboarding saves the answer map + marks onboarded + enrolls in one call. This replaces the fragile localStorage 'pendingOnboarding' flag (set only at signup, lost across the email-confirm round-trip / device changes / the sign-in path), so onboarding reliably appears once and survives those. A same-device local 'onboarded' flag is the fallback before the migration is applied. The pre-registration GUEST flow is deliberately UNCHANGED — a non-registered user still goes welcome → train → finish → share with no persona/onboarding prompt; onboarding only appears AFTER they create an account. The persona fork (see persona-shape) leads the menu. The single biggest 30-day-retention lever." },
  { id: "first-run-tour", area: "Core", status: "shipped", title: "First-run guided tutorial", detail: "A guided coach-marks tour shown ONCE to a fresh account right after onboarding, on BOTH clients — web apps/web/components/tour.tsx is a spotlight overlay that highlights real `data-tour` anchors (the Today plan card + the Plans/Profile/Settings nav items) and tracks them on scroll/resize; mobile apps/mobile/components/tour.tsx is a stepped overlay mirroring the same copy/flow. Steps: your day on Today → follow a plan → your Profile → configure your account in Settings. GUEST-FIRST ORDERING: if the account was created right after logging a GUEST workout, that just-saved workout lands first — the tour steps aside for one app open (flushGuestSessions sets `hybrid.cameFromGuest` when it syncs ≥1 session; the home screen defers the tour that open, then shows it the next). Triggered via `hybrid.pendingTour` (set at signup on mobile / on onboarding completion on web) and never re-nags once `hybrid.tourSeen` is set." },
  { id: "today-first-session", area: "Core", status: "shipped", title: "First-session chooser", detail: "A brand-new, not-yet-enrolled user's Today plan card offers THREE explicit paths instead of a single Start button: Follow a plan (free → Plans library), Build your own (free → the Builder; a free account keeps up to 2 saved templates, see workout-routines), and Log a one-time workout (free → empty logger). Implemented on both clients AND both templates: web components/today.tsx + components/aurora/today.tsx, mobile components/aurora/home.tsx. Replaces the old single 'Start your first session' prompt. COLD-START FLASH FIX (Jul 2026): the chooser is the fallback shown when no plan resolves, so on a hard refresh (web) / cold app open (mobile) an ALREADY-ENROLLED athlete briefly saw 'How do you want to start?' before their plan loaded — the plan-card decision only gated on the sessions fetch, not the slower enrollment (macrocycle) fetch. Now the plan hero holds a skeleton until BOTH sessions and enrollment settle: web useMacrocycle exposes loading (isPending||isFetching), app-shell ORs it into Today's loading prop, and the aurora/today loading skeleton is ordered ahead of the AI-prescription and chooser fallbacks (plus the top Start pill is held back while loading); mobile aurora/home gates the same hero on a new initialLoad flag (true until the first Promise.all load settles). So the chooser only appears once we actually know the athlete isn't enrolled — never as a load-time flash." },
  { id: "today-upsell", area: "Core", status: "shipped", title: "Today premium upsell (Performance State)", detail: "Free users get a 'See your Performance State' card on Today that sells the Full intelligence layer (HPI + readiness + injury-risk fused into one live state, plus adaptive loads, periodization, velocity tracking, analytics and the AI coach), and an enrolled free user additionally gets a season-brief upgrade CTA. Both clients/templates, fired through the same FUNNEL track() events (source: today-perfstate / today-season / today-build) so the upsell is measurable the moment an analytics provider lands (see funnel-analytics). AI-PRESCRIPTION GATING (Jul 2026): the AI-prescribed session (prescribeSession — 'the moat') is now PREMIUM (paid) ONLY, everywhere it was entered: Today's 'Your plan today' card (web today.tsx + mobile home.tsx now render the readiness ring + rx.blocks + rx.why ONLY when isAthlete && (hasData||phase) — a casual/guest instead sees the honest enroll/build/log chooser, never the fabricated 'Back Squat + Assault Bike, readiness 98' session presented as theirs), the Train launcher AI card (mobile train.tsx), the live-logger empty-state AI button (web aurora/logger.tsx + mobile workout.tsx loadPrescribed + the source=ai deep-link handler). A non-premium tap is FUNNELLED not fulfilled: a GUEST (no account) is sent to register (/login?mode=signup), a free logged-in user to the upgrade paywall (/upgrade), tracked as FUNNEL.upgradeEntryClick (source: workout-ai / train-ai / logger-ai). This closes the leak where a guest could pull a fabricated readiness-driven session for free — the intelligence layer is the paid moat (see economics.ts). The hardcoded English AI-card copy ('Smart starter session' + blurb) was also moved to i18n (train.aiEmptyTitle/Blurb, train.aiLockedTitle/Blurb, train.premium; EN/PL/DE). Enrolled users (incl. casual/free — following a pre-made plan is free) now see their REAL enrolled plan day on the card (see plan-program-today), so 'Your plan today' is only the AI prescription when premium AND not on a named plan." },
  { id: "periodization-access", area: "Core", status: "shipped", title: "Periodization is a Full feature", detail: "The full Periodize screen is paid. Free (casual) users are NEVER routed there — the post-enroll redirect lands them back on Today (not Periodize), and Periodize stays out of their nav (minPersona athlete) — and instead get a read-only SEASON BRIEF on Today: the goal, current phase and the phase timeline, with an 'Unlock full periodization' CTA. Defense-in-depth: a casual who still reaches the Periodize screen is shown the upgrade page. Web app-shell + today.tsx/aurora-today; mobile aurora/home.tsx (mobile never force-redirected after enroll)." },
  { id: "nav-category-hub", area: "Core", status: "shipped", title: "Navigation — category hub (drill-in) on small screens", detail: "The full nav (40 destinations across the 7 canonical groups home/train/analyze/recovery/social/teams/account) was an unreadable single scroll on mobile. Redesigned as a CATEGORY HUB (concept 4 of a 5-concept study): the surface shows the SEVEN areas as cards — each with a Spectrum-coloured glyph, a live preview of its first few screens and a count — and tapping one drills into just that area's list; a back control returns. No feature was removed; only the door changed. Built on the SHARED canonical IA so web + mobile can't drift: both derive the areas from @hybrid/core groupedNav(navForPersona(persona, …, access)) (persona + admin-access filtered). MOBILE: apps/mobile/app/(tabs)/more.tsx is the hub — identity/Settings/mode-toggle/Unlock-Full/Admin pinned above the seven area cards, each area drilling to its screens (id→route via a local HREF map; screens with no mobile route show a 'WEB' tag and open the web app, so granted access is never invisible). WEB PARITY (responsive): the app-shell sidebar keeps every group EXPANDED on the desktop rail (there's room), but its mobile off-canvas DRAWER now drills the same way (area cards → one area's items → back) — so the two clients share the information architecture and each renders it right for its viewport. onboarding (a re-runnable setup flow, not a nav item) is injected into Train. Derived from reference/hybrid-nav-redesign.html (the 5-concept pitch). SEARCH-FIRST PASS (both clients, at parity): the More hub gained a SEARCH field at the top of the springboard that filters the launcher tiles by (localized) label and drops clusters left empty, with a total-tool count in the placeholder and a no-match empty state — mobile app/(tabs)/more.tsx, and on web BOTH More surfaces match (the app-shell mobile drawer AND the AuroraPillNav bottom-sheet, apps/web/components/aurora/pill-nav.tsx). Locking/gating still derives from groupedNavWithLocks (locked tiles show a lime 🔒 and route to upgrade); the identity card, Unlock-Full membership card and Sign out are unchanged. PARITY/FIDELITY HARDENING: the 3 springboard surfaces (mobile tab, web app-shell drawer, web pill-nav sheet) audited 1:1 and against the mock — unified to a 4-col grid with counted headers, a lime lock badge (was a 🔒 emoji on the sheet), per-cluster accent-tinted chips, an identity card + Sign out on the sheet, one `more-${id}` tracking token and one empty-state string; mobile now applies the same nav feature-flag gate (new useFlags() in apps/mobile/lib/flags.ts) and localizes the Unlock-Full copy (more.upgradeKicker/Blurb/goFull)." },
  { id: "nav-sliding-indicator", area: "Core", status: "shipped", title: "Bottom-nav sliding selection indicator (liquid pill)", detail: "The floating Aurora bottom-nav highlight now BEHAVES like Instagram's tab bar (the requested feature): instead of a static chalk pill that instantly pops onto whichever tab is active, a SINGLE shared indicator SLIDES between the four flat slots (Today · Explore · More · Profile) and STRETCHES mid-travel (a scaleX squash-and-settle) for the liquid feel, springing into its new position. Built once on BOTH clients at parity: WEB apps/web/components/aurora/pill-nav.tsx — one absolutely-positioned chalk span inside the pill, measured against each flat button (offsetLeft/offsetWidth via refs), animated with a CSS spring transition (cubic-bezier overshoot) on transform + a brief scaleX on move; recomputed on resize; the per-button background was removed so the glyph just tints ink over the shared pill. MOBILE apps/mobile/components/aurora/global-nav.tsx — an Animated.View (RN core Animated, no reanimated dep) positioned from each item's onLayout geometry, driven by Animated.spring(translateX) + an Animated.sequence(scaleX 1→1.28→1) + opacity, native-driver. The centre Train FAB is EXCLUDED (it keeps its own lime glow) so the indicator fades out (opacity→0) while Train is active. Both clients snap without animation on first paint and honour reduced motion (web prefers-reduced-motion; mobile AccessibilityInfo.isReduceMotionEnabled + reduceMotionChanged). Layout, icons, labels, blur/film/rim and the FAB are otherwise unchanged. Web build + iOS bundle export + both typechecks green. LIQUID GLASS + TAP-LAG (Jul 2026, from live TestFlight feedback): (1) the moving highlight is now REAL Liquid Glass on iOS — a native SwiftUI glassEffect lens (@expo/ui RoundedRectangle + glassEffect, the same material as the kit's GlassSurface) rendered on Platform.OS==='ios' (independent of the opt-in SwiftUI-kit toggle, so it's visible to evaluate; degrades gracefully on iOS<26 with a faint floor underneath). Android keeps the opaque chalk pill (which still scaleX-stretches; the glass gets its liquid quality from the material, so it only springs). Over the translucent lens the active glyph stays bright (chalk) instead of inverting to ink, so it can't read as a dark-on-glass smudge. (2) TAP-LAG FIX — selection is now OPTIMISTIC: a local selectedSeg updates the instant a tab is pressed and drives BOTH the pill position and the icon tint, then reconciles to the real route (useSegments) once it settles. Previously the tapped icon inverted to its dark on-pill colour the moment the route flipped — which on a heavy screen lagged ~1s behind the press — so you saw a black icon before the pill slid in. Now the pill leads the navigation. PARITY/PLATFORM: true native Liquid Glass is iOS-only (it's the blocked swiftui-kit material); web keeps its CSS backdrop-filter frost + chalk indicator (web in-shell nav is synchronous, so it has no tap-lag to fix) and Android keeps the chalk pill — a platform capability gap, not a feature gap. Native glass can't be visually verified in the sandbox (no Xcode/simulator); typecheck + iOS export are green and it validates on TestFlight. CROSS-FADE (from live feedback: sliding the glass 'lagged when moving between tabs'): sliding a single native glassEffect lens across the bar re-samples its backdrop every frame and janks, so the indicator no longer travels — each of the four slots now owns its OWN lens and selection CROSS-FADES (opacity only, ~170ms; nothing translates), which stays smooth because a fixed-position glass view doesn't re-sample while it fades. The optimistic-selection tap-lag fix is unchanged. Trade-off (superseded below): the highlight faded in place instead of gliding. NATIVE GLASS MORPH (from feedback: 'don't lose the Apple travel motion, but it can't be laggy'): iOS now renders the selection as a SINGLE native Liquid Glass lens that MORPHS between slots — Apple's matched-geometry travel via @expo/ui GlassEffectContainer + Namespace + glassEffectId (the four slot cells live in one container; only the selected cell renders the glass RoundedRectangle, tagged with a stable glassEffectId, so when selection moves SwiftUI fluidly morphs the glass across). This is smooth because the morph runs natively in SwiftUI — unlike the earlier JS-driven translate, which re-sampled the glass every frame and janked (the reported lag). Component: GlassMorphSelector in global-nav.tsx, a Host overlaying the inner row BEHIND the RN glyphs, laid out with concrete SwiftUI frames (four equal slots of (rowW−64)/4 + a fixed 64pt centre gap, measured via the row's onLayout) to align with the icons. Deliberately does NOT use withAnimation/worklets (which throw if react-native-worklets isn't wired) so there is no crash path — worst case the glass snaps instead of gliding. The glyphs, Train FAB and taps stay RN, so the bar still works if the native layer doesn't render. Android keeps the per-slot chalk cross-fade. Unverifiable in the sandbox (no Xcode/simulator) — typecheck + iOS export green; the morph itself is validated on TestFlight and may need device iteration. TRAVEL ANIMATION (grounded in a @expo/ui native-Swift audit, after two builds SNAPPED): the matched-geometry approach (GlassEffectContainer + glassEffectId, glass conditionally rendered only in the selected cell) does NOT animate — an ancestor `.animation(_:value:)` can't animate a child that INSERTS/REMOVES (source + destination never co-exist to morph between), so it cut. The pattern that DOES animate (per @expo/ui's own ChartView: `.animation(.easeInOut, value: props.data.count)`) is a PERSISTING view whose animatable property changes under `.animation(value:)`. So the selector is now a SINGLE persistent glass RoundedRectangle, centred, moved by an animated SwiftUI `.offset(x:)` bound to selectedIndex with `.animation(Animation.spring, selectedIndex)` — the offset animates natively in SwiftUI (smooth; unlike the very first attempt, which drove translateX from JS over the bridge and janked). No GlassEffectContainer/Namespace/glassEffectId, no worklets. Offsets are from row centre: ∓(1.5·slotW+32), ∓(0.5·slotW+32), slotW=(rowW−64)/4. Still native-only, validated on TestFlight. INSTAGRAM-AUDIT PASS (Jul 2026, from a frame-by-frame comparison of a real Instagram recording vs ours — 60fps centroid tracking showed our travel rendered smoothly but still READ laggy): the tells were (a) the active-glyph tint flipped INSTANTLY on press while the lens arrived ~250ms later (the eye reads 'tap registered… now watch a slow bubble catch up'), (b) a constant-size lens with no stretch/overshoot reads floaty at any duration, (c) selecting Train UNMOUNTED the lens (return null) so leaving/re-entering a side tab popped — the exact SwiftUI can't-animate-a-remount trap documented above. Fixes on BOTH clients at parity: (1) ICON-SYNC — the active tint is now a crossfade timed to the lens ARRIVAL (incoming glyph fades in delayed ~90-100ms to land with the lens, outgoing fades back immediately; mobile: per-slot Animated iconOp overlay icons, web: a delayed-transition ink overlay in PillButton); (2) STRETCH — the lens elongates toward the target mid-travel scaled by distance then settles (mobile: two native poses — frame width springs up then back, each keyed by a monotonic tick under .animation(value:); web: distance-scaled scaleX min(1+dist/240, 1.9) for 150ms); (3) snappier spring with arrival energy — mobile response 0.32/damping 0.74 (was 0.38/0.82), web .34s cubic-bezier(.32,1.36,.44,1) (was .44s); (4) NEVER UNMOUNTS — Train now fades the lens via animated opacity in place on both clients, so the next selection travels/fades instead of popping; (5) the lens widened 46→56pt toward IG's proportions (reads as 'the selection', not a token behind the glyph). Both honour reduced motion (snap, no stretch). Web + mobile typecheck and the iOS bundle export green; feel needs TestFlight validation as ever." },
  { id: "nav-ios26-tab-bar", area: "Core", status: "shipped", title: "Bottom nav — Liquid Glass capsule + detached Train (SUPERSEDED by nav-hig-anatomy)", detail: "HISTORICAL. This shipped the Aurora bottom nav as a Liquid Glass capsule of four tabs (Today, Explore, More, Profile) with Train as a DETACHED bar-height lime circle beside it, on both clients, and unified the nav glyph weight to 4 viewBox units after a live-preview note that the icons read too thick (it also fixed a real parity drift: mobile stroked the bar at the kit default 6 while web stroked it at a 2.6 hairline, so the 'same' bar never matched). The glyph-weight and parity work still stands. TWO CLAIMS IN IT WERE WRONG, corrected by nav-hig-anatomy below: (1) the detached circle was described as 'Apple's split tab bar (tab group + standalone accessory, like Search in the system apps)' — in iOS 26 a circle separated beside the tab bar is the SEARCH ROLE, which morphs into a search field on tap, so a training CTA parked there reads as search; (2) putting Train there at all runs against the guidance that a tab bar carries navigation — 'avoid placing screen-specific actions in the tab bar'. Kept as a record of what was built and why it changed." },
  { id: "nav-hig-anatomy", area: "Core", status: "shipped", title: "Bottom nav — five tabs in one capsule + session accessory (HIG anatomy)", detail: "The bottom nav rebuilt to Apple's actual tab-bar anatomy on BOTH clients, replacing the split capsule-plus-detached-circle of nav-ios26-tab-bar. ANATOMY: five tabs — Today, Explore, Train, More, Profile — inside a single Liquid Glass capsule (five is Apple's iPhone ceiling). Train is a TAB, not a detached action: it always opened the Train launcher, i.e. a destination, and 'avoid placing screen-specific actions in the tab bar' rules out the button reading. The separated-circle slot beside the bar is left EMPTY because that geometry is the iOS 26 search role (it morphs into a search field), so it now stays reserved for real search if HYBRID ever adds it. Persistent session state moved to the tab-bar ACCESSORY above the capsule (Apple's mini-player slot, the system home for players and active orders): when a workout draft exists, a glass strip shows a lime status dot, the draft title, a live elapsed clock and Resume, standing down on the Train launcher and the live logger where it would only repeat the screen. SHARED CONTRACT: packages/core/src/nav-bar.ts is new and holds the tab table, geometry and material constants plus formatSessionElapsed, so the two clients can no longer hard-code divergent copies (they previously did, which is how the glyph weights drifted). MATERIAL: the body went from a 40% ink film under blur(24) — the frosted recipe from iOS 7-18, opaque enough that nothing behind survived — to a ~6% film under blur(14) saturate(1.8) brightness(1.08), with the identity moved to the RIM: a specular arc bright at the top-left and gone by 40% around, a refraction band whose last 9px sample a magnified saturated backdrop so content visibly bends at the edge, and a dark bottom lip that makes the glass read as thick rather than printed. The selection lens is now LIFTED — thinner glass than the capsule carrying it (clearer + brighter), with its own drop shadow and a specular top arc — and travels with stretch along the axis plus counter-squash across it. The active glyph takes the brand tint rather than chalk (iOS moves the selected item to a true tint and a filled symbol; this kit is line icons only per the project rule, so tint carries it). WEB: the material lives in globals.css as .aurora-navglass with @supports and prefers-reduced-transparency fallbacks to a solid bar, so nav is never an invisible surface. MOBILE: iOS 26 keeps the real native SwiftUI glassEffect capsule and the travelling native glass lens (GlassMorphSelector, whose slot maths was hard-coded to four cells and is now derived from the tab table — promoting Train is exactly the change that would have silently mis-seated the lens); Android and iOS < 26 get the same improved fallback numbers as web. Verified here: core tests, both typechecks and the iOS bundle export are green. The native glass itself still needs TestFlight — no Xcode/simulator in the sandbox." },
  { id: "nav-native-tabs", area: "Core", status: "shipped", title: "Bottom nav — the real system tab bar (native UITabBarController)", detail: "The mobile bottom nav IS the system tab bar now: app/(tabs)/_layout.tsx uses expo-router's native tabs (expo-router/unstable-native-tabs, already present in SDK 56 — no new dependency and no config plugin), which is UITabBarController on iOS and BottomNavigationView on Android. Liquid Glass on iOS 26 is therefore INHERITED rather than reconstructed, along with everything the custom bar could only approximate: the material's real refraction and adaptive contrast, the system selection treatment, tabBarMinimizeBehavior (set to onScrollDown), the scroll-edge transition, Dynamic Type, Reduce Transparency, Increase Contrast, double-tap-to-pop-to-root, and sidebarAdaptable for iPad/macOS. DELETED: components/aurora/global-nav.tsx entirely, including GlassMorphSelector (the ~110-line workaround for SwiftUI matched-geometry not animating across insert/remove) and the hand-built collapse ramp with its mini hysteresis — all of it is system behaviour now. The session strip moved to components/aurora/session-accessory.tsx inside NativeTabs.BottomAccessory, with the draft and the clock in a module-level store because the accessory's children are rendered TWICE (once per placement, regular and inline) and per-component state would let the two copies disagree the moment the bar minimized. FOUR ACCEPTED TRADE-OFFS, all of them deliberate and all of them the platform's rules winning: (1) the bar no longer shows on pushed sub-pages (Statistics, Settings, Periodize, …) — a native tab bar is hidden by a stack pushed above it, and the old bar was root-mounted specifically to defeat that; (2) tab glyphs are SF Symbols (house, globe, dumbbell, square.grid.2x2, person.crop.circle, each with its .fill selected variant) rather than the Aurora design-kit line icons, because native tab bars take SF Symbols or image resources and never React components — the kit PNGs are passed as `src` so Android keeps the house style; (3) every route that is not one of the five tabs MOVED OUT of app/(tabs) into the root stack (performance, history, plans, sport, velocity, endurance, coach; explore moved in), because a native tab bar renders every route in its directory and marking one hidden makes it un-navigable — verified in expo-router's own NativeBottomTabsNavigator, which filters on options.hidden and throws if a hidden route is focused; (4) the Classic template's command orb moved from the tabs layout up to the root layout, since the tabs layout is now purely NativeTabs. VERIFIED HERE: mobile typecheck (which also validates every SF Symbol name against expo-router's SFSymbols union, so a typo is a build error rather than a blank tab), the iOS bundle export, and the core suite. NOT verifiable here and gated on the next TestFlight build: the bar's actual appearance, and the bottom clearance in lib/layout.ts, which is now sized for the floating iOS 26 bar rather than measured against it (it errs high on purpose — over-padding is a gap, under-padding is a hidden row)." },
  { id: "nav-parity-gap", area: "Core", status: "planned", title: "Web↔mobile nav parity — web has no system tab bar to inherit", detail: "RECORDED SO IT IS NOT LOST, per the parity rule. Mobile's bottom nav is now the real system tab bar (nav-native-tabs), which no browser can provide, so apps/web keeps the hand-built Liquid Glass pill (components/aurora/pill-nav.tsx + .aurora-navglass in globals.css). The two clients still share WHAT the bar contains — @hybrid/core AURORA_NAV_TABS drives both, so the five destinations and their order cannot drift — but no longer share HOW it looks or behaves. Known divergences on web, in rough order of visibility: no Dynamic Type (the labels are px, tracked separately as web-font-rem); a masked-ring approximation of edge refraction rather than true per-pixel displacement; no adaptive contrast, so the material does not re-tint itself over busy content; the selection lens keeps the stretch-and-squash flourish, which the system bar does not do; the minimize-on-scroll is a hand-built ramp rather than tabBarMinimizeBehavior; and no scroll-edge material transition. Closing this properly is not possible — the platform affordance does not exist on web — so the realistic goal is to narrow the visible gap: match the metrics to the measured system bar, drop the stretch-squash, and honour prefers-reduced-transparency and Dynamic-Type-equivalent rem scaling. Decide whether web should CHASE the native bar or own a deliberately different web-native treatment." },
  { id: "nav-collapse-on-scroll", area: "Core", status: "shipped", title: "Bottom-nav shrink-on-scroll (full at top, compact when scrolled)", detail: "The floating Aurora bottom nav now SHRINKS as you scroll (the requested Instagram behaviour): full size at the very top, scaling down smoothly to a compact pill as the active surface scrolls, and re-expanding when you scroll back up or land on a new screen. Continuous over the first 48px of scroll (not a hard snap). Built at web<->mobile parity, honouring reduced motion, and it scales the WHOLE bar — the centre Train FAB + the sliding selection indicator are children of the scaled element, so everything shrinks together. WEB apps/web/components/aurora/pill-nav.tsx — a passive window-scroll listener (the shell scrolls the document, no inner overflow container) drives an imperative per-rAF transform: scale on the bar (transform isn't in its React-managed style, so re-renders never clobber it); recomputed on screen change so a short screen re-expands. MOBILE — RN has no global scroll event, so a shared signal was added: apps/mobile/lib/nav-scroll.tsx (NavScrollProvider mounted once at the root in app/_layout.tsx) exposes a `collapse` Animated.Value + an `onScroll` handler; the scroll surfaces publish their offset by spreading useNavScrollProps() — wired into BOTH shared screen primitives (the Aurora AuroraScreen AND the classic lib/ui Screen, since Aurora is the only template so classic-Screen screens like Coaches/Admin still sit under the pill), plus every bespoke scroller that opts its parent out of the primitive's ScrollView (scroll={false}): the Today/home ScrollView, and the FlatLists in the social Feed, workout History and the Leaderboard. Horizontal rails/pagers/chip rows and modal scrollers are deliberately NOT wired (a sideways swipe or a sheet must not collapse the bar). apps/mobile/components/aurora/global-nav.tsx consumes `collapse` and interpolates it to scale/translateY/opacity on the pill wrapper, resetting to full on every route change (so a new screen always starts expanded). Both typechecks, the web build, the iOS bundle export and the 804 core tests stay green. ICON-ONLY WHEN SMALL: past the collapse threshold the bar now also DROPS ITS LABELS — the small bar is glyphs alone, matching the native minimized tab bar (the requested behaviour). Each slot's label row animates its HEIGHT (not display) to 0 while fading out, so the slot morphs smoothly from 60x46 to 44x34; the selection lens, the capsule and the detached Train circle (58 -> 46) tighten with it, and the residual scale was eased back (web 0.84 -> 0.94, mobile 0.82 -> 0.94) so the geometry does the shrinking and the bar never scales down to an untappable size. Accessibility is unaffected: the visible label is decoration over an aria-label / accessibilityLabel that is always present, so screen readers announce the same names in both states. Because it is a LAYOUT change rather than a continuous ramp, it flips on a hysteresis-guarded boolean (on at 0.6 of the collapse ramp, off at 0.25) so it cannot flicker at the threshold. WEB — CSS transitions on the slot/lens/circle box, the mini flag derived in the same per-rAF scroll pass that sets the scale; the sliding indicator re-places on the flag (and now only fires its travel-stretch on a genuine slot change, so resizing for mini does not read as a hop). MOBILE — a JS-driven miniAnim timing value (width/height/radius are not native-driver props) fed by a listener on the shared collapse value; the fallback chalk pill splits into two nested views so the native-driven opacity crossfade and the JS-driven radius never share a style object, and on iOS 26 the native Liquid Glass lens resizes with the slots via the existing .animation(value:) tick. Reduced motion keeps the bar full-size (no collapse ramp, so no mini state) on both clients." },
  { id: "named-plan-today", area: "Backend", status: "shipped", title: "Named-plan 'Your plan today'", detail: "When a user enrols in a REAL uploaded plan, that plan's exact day (planToday → PLAN_DETAIL) drives the Today card instead of the engine's algorithmic prescription. Both clients SEND the enrolled planId on enroll — web components/plans.tsx + aurora/plans.tsx, mobile aurora/plans.tsx, and the onboarding enroll — and the backend persists it on macrocycle.planId; the macrocycle.planId column has been migrated in Supabase (reference/sql-macrocycle-planid.sql), so the POST /api/macrocycles handler keeps the planId and useMacrocycle surfaces it to Today on both clients. Previously NO client sent planId AND the column was unmigrated, so Today always fell back to the generic prescription ('Back Squat + Assault Bike, readiness 98')." },
  { id: "perfstate-naming", area: "Core", status: "shipped", title: "'Performance State' naming (Athlete Twin retired)", detail: "The fused current-state object is called 'Performance State' everywhere user-facing — the legacy 'Athlete Twin' / 'Athlete Hybrid' / 'digital twin' wording is fully retired across both clients and all EN/PL/DE i18n string VALUES (DE: 'Leistungszustand', PL: 'Stan formy'). The engine file is engines/performance-state.ts (exports computePerformanceState / PerformanceState / performanceTrajectory — unchanged); i18n KEY identifiers were intentionally left as-is to avoid churn." },
  { id: "squad-monitor", area: "Web", status: "shipped", title: "Squad monitor (RAG + ACWR)", detail: "The screen a team coach opens every morning: one row per ACTIVE athlete with readiness (red/amber/green), training-load ACWR + band, acute load, injury-risk band + flagged tissue, HPI and last session — sortable worst-first, with a squad summary strip (low-readiness / ACWR / injury flag counts). New session-load engine (load.ts: sRPE load → rolling 7d:28d ACWR + monotony/strain, unit-tested) surfaces the load math; /api/coach/squad computes everything server-side from each consented client's real sessions + signals (CoachLink-gated)." },
  { id: "forceplate-ingest", area: "Integrations", status: "shipped", title: "Force-plate / jump-test CSV ingest", detail: "The buildable hardware loop: forceplate.ts parses a Hawkin/ForceDecks-style CSV (wide: date + metric columns, or long: date,metric,value,unit) and normalizes jump height / asymmetry / body mass into the Signal ontology — so they feed the Twin + injury engine with zero special integration (unknown columns are skipped, never guessed). Web import screen (file/paste, recognized-vs-skipped preview, one-click import) + a jump-height trend chart. Mobile parity: app/forceplate.tsx (paste + preview + import + jump trend). Pure + unit-tested. Live bar-velocity / per-rep capture is still a separate device-SDK job (vbt-capture)." },
  { id: "composition", area: "Core", status: "shipped", title: "Bodyweight trend (smoothed)", detail: "composition.ts: EWMA-smoothed bodyweight + fitted weekly rate (kg/wk) from bodyMass signals (the weekly check-in weigh-in writes one), so the UI shows the trend instead of demotivating daily noise. Pure + unit-tested. Charted on the Nutrition screen on BOTH clients — web via a recharts line (raw + smoothed), mobile via the native bar-trend idiom (no react-native-svg) on the smoothed series; both append a weightChangeKg/28d suffix to the maintenance line." },
  { id: "auto-segmentation", area: "Web", status: "shipped", title: "Coach auto-segmentation (triage)", detail: "segment.ts: athleteSegment buckets each athlete (needs-attention / dormant / new / on-track) from the squad signals the monitor already has — readiness, ACWR band, injury flag, days-since-last, session count. The Squad monitor filters + counts by segment and tags each row, turning a 100-athlete roster into a 'who needs me today' list. Pure + unit-tested." },
  { id: "coach-tags", area: "Web", status: "shipped", title: "Manual coach roster tags", detail: "Coach-authored labels on each CoachLink (e.g. powerlifting, remote, comp-prep) edited as chips in the client detail; the Squad monitor shows them per row and filters by tag, alongside the auto-segments. CoachLink.tags text[] (reference/sql-coach-tags.sql adds the column); GET + 'tags' PATCH action on /api/coach/links/[id], surfaced via /api/coach/squad. NOTE: run reference/sql-coach-tags.sql in Supabase. MOBILE PARITY: the Aurora coach console's client detail (apps/mobile/components/aurora/coach.tsx) reached parity with web's ClientDetail — roster tag chips (add/remove via the same 'tags' PATCH), per-client template ASSIGNMENT (pick a saved template + date → POST /api/coach/links/[id]/assignments), GENERATE PERIODIZED WEEK (enroll a macro via POST …/macrocycle, then buildTrainingWeek → bulk-assign the week off the client's real cadence/logs), and WEEKLY CHECK-INS with a coach reply (GET …/checkins + PATCH /api/checkins/[id]) all now ship on mobile too, using the same endpoints and the mobile fetch helpers in apps/mobile/lib/api.ts." },
  { id: "progress-photos", area: "Web", status: "shipped", title: "Progress photos", detail: "Body-recomposition photo timeline in a PRIVATE Supabase Storage bucket under progress/{auth.uid()}/… with owner-folder RLS, so each user only ever sees their own. Listed straight from storage (no app table to keep in sync), displayed via short-lived signed URLs; upload + delete from the web Progress screen. reference/sql-progress-photos.sql creates the bucket + policies. Web screen uploads/deletes; mobile screen (expo-image-picker) captures from camera or library to the same bucket — the phone is the natural capture surface. NOTE: run that SQL in Supabase; the storage upload path is untestable from this sandbox (Supabase host blocked), and the mobile native module needs an EAS build to run on-device (blocked on the Apple Developer account + Expo token)." },
  { id: "workout-builder", area: "Web", status: "shipped", title: "Workout builder + template library + scheduler", detail: "Build a workout (strength/conditioning blocks, sets×reps×load×RPE×velocity) with reorder (↑/↓), duplicate, and add/remove, then save it as a reusable WorkoutTemplate. A coach assigns a template to a rostered athlete on a date (CoachLink-gated); blocks are SNAPSHOTTED at assignment time so later template edits never change a workout already assigned. The athlete sees assignments on the mobile Home ('Assigned by your coach' → Start/done) and the web Calendar (violet markers + Mark-done); the coach sees status (assigned/completed/skipped) in the client detail. WorkoutTemplate + Assignment models + reference/sql-workout-builder.sql (own-rows + active-coach RLS); /api/templates, /api/templates/[id], /api/assignments, /api/assignments/[id], /api/coach/links/[id]/assignments. NOTE: run reference/sql-workout-builder.sql in Supabase to create the tables. ACCESS: composing your own routine in the Builder is FREE for every persona (the `builder` nav item is no longer minPersona-gated) — this fixed a web↔mobile parity gap where mobile surfaced the Builder to free clients (More hub + Train launcher) but web hid it from casual; Today's first-session 'Build your own' chooser is now a free path into the Builder (no ✦ Full badge), and the Builder was dropped from the Full upgrade bundles. A FREE user can also SAVE up to 2 templates (FREE_TEMPLATE_LIMIT, see workout-routines); an unlimited template library — plus adaptive plans / periodization / auto-progression — is the PAID layer, not the act of building a workout." },
  { id: "workout-routines", area: "Mobile", status: "shipped", title: "Save workouts as routines (self-serve, load-and-go)", detail: "The athlete-facing routine loop, closed on top of the existing WorkoutTemplate infra (model + /api/templates own-rows GET/POST + [id] DELETE). MOBILE: the Train launcher (app/(tabs)/log.tsx) now lists 'Your routines' below empty/AI/repeat-last — tap one to start (router.push('/workout?source=template&templateId=…'), which the live-workout screen loads via fetchRoutines→blocksToExercises); and the finish Summary has a 'Save as routine' action (name → createRoutine) for non-guest users. WEB: both loggers (Aurora components/aurora/logger.tsx + classic components/logger.tsx) show a 'Your routines' quick-start (tap to load a saved template's blocks into the editor). 'Save as routine' has MOVED off the live logging surface to the finish screen — a shared SaveRoutineCard (components/save-routine-card.tsx) renders a collapsed pill → inline name field → saved confirmation, so a workout is named only when it's actually being saved as a reusable routine (nobody names a plain workout). New mobile api helpers fetchRoutines/createRoutine/deleteRoutine. Reuses the shared SessionBlock shape so routines and logged sessions share one editor and can't drift; routines need an account (guests see none). Localized EN/PL/DE (train.routines, summary.saveRoutine/routineSaved, w.train.logger.saveAsRoutine/saveRoutineHint/routineNamePh). NEXT: a dedicated 'My routines' manage screen (rename/delete/reorder) and pre-building a routine from scratch (today you save one from a finished/edited workout); the coach-assign path (workout-builder) is unchanged. FREEMIUM GATE (Jul 2026, supersedes the earlier all-paid gate): a FREE (casual) user can now SAVE up to 2 reusable routines — the Builder itself is free for everyone; only a LIBRARY BEYOND 2 templates is Full. One source of truth in packages/core/src/access.ts: FREE_TEMPLATE_LIMIT = 2 + count-aware `canSaveRoutine(persona, savedCount)` (Full personas unlimited, casual true while savedCount < limit, fails closed on unknown personas; unit-tested). The API enforces it server-side: POST /api/templates counts the free client's WorkoutTemplate rows and 403s (code upgrade_required) only AT the limit — entitlement still read from the DB row, never client metadata. UI on BOTH clients + BOTH save surfaces: the Builder save button (web components/aurora/builder.tsx off templates.length, mobile components/aurora/builder.tsx off routines.length) shows a '{used} of {limit} free template slots used' hint (w.train.builder.freeSlots) for free users under the limit and flips to the ✦ upsell card (FUNNEL.upgradeEntryClick source 'builder-save') only at the limit; the finish-Summary SaveRoutineCard (web components/save-routine-card.tsx, mobile app/workout.tsx SaveRoutine, source 'save-routine') fetches the saved count for free users and upsells only at the limit (mobile's api createRoutine is status-aware — {ok, status} — so a stale count's 403 maps straight to the upsell, never a confusing error, and the mobile builder hook's save messages are localized w.train.builder templateSaved/signInSave/saveError/networkError instead of hardcoded English). The Train launchers' routines row is no longer a Premium-badged upsell for free users — everyone sees their saved routines (or the build-first prompt into the free Builder). Upsell copy is limit-aware ('Routine limit reached — Free includes 2 saved routines…', w.train.logger.routineFullTitle/Blurb + summary.routineFullTitle/Blurb, EN/PL/DE); the admin ENTITLEMENT_MATRIX row (Template builder) reads free '2 saved templates' / paid 'Unlimited', and FULL_BENEFITS gained 'Unlimited saved routines'." },
  { id: "today-quick-start", area: "Core", status: "shipped", title: "Today — Quick start a saved routine (favourites + rediscover sheet)", detail: "A fourth 'Train your way' path on Today/Home, beside Follow a plan / Build your own / Just log: a violet ⚡ 'Quick start' card that opens a bottom sheet to re-launch a routine the user already owns (WorkoutTemplate) in one tap — no re-onboarding through the builder every day. The card is ALWAYS present alongside the other three paths; with no saved routines the sheet shows a build-first empty state ('No saved routines yet' + a Build a new routine action), so it's a prompt rather than a dead door. When the user is ON A PLAN (where Today shows the plan hero instead of the four 'Train your way' cards) the sheet stays reachable via a quiet '⚡ Quick start a saved routine' secondary link under the plan card's Start button (w.home.today.quickStartLink), so a saved routine is one tap away without leaving the plan. The sheet (shared aurora/quick-start.tsx on each client, driven off the existing Sheet primitive) shows FAVOURITES as a snap rail on top (respecting the sheet's own padding — bleed is only for screen-level rails), then a shuffle-able 'Rediscover' list of the remaining routines; each card/row starts the session immediately (web onStart(blocks, name) → the shell logger; mobile router.push('/workout?source=template&templateId=…'), the launch path already shipped in workout-routines) and carries a ★ toggle to favourite/unfavourite. An honest one-line meta per routine comes from the shared pure helper routineSummary(blocks) in packages/core/src/engines/session.ts (move count + summed minutes ONLY from cardio/conditioning blocks that carry them — a pure gym routine shows just the move count, never a fabricated duration). A 'Build a new routine' footer routes into the free Builder. Mirrored web (components/aurora/today.tsx + quick-start.tsx) + mobile (components/aurora/home.tsx + quick-start.tsx). i18n w.home.today.chooserQuick* + w.home.quickStart.* + w.home.logbook.slimQuickSub (EN/PL/DE). The favourite FLAG's server persistence is tracked separately as `routine-favourite` (blocked on the reference SQL) — until it runs, starring soft-degrades (the launch + sheet work regardless, and favourites simply don't persist)." },
  { id: "routine-favourite", area: "Data", status: "shipped", title: "Routine favourite flag (persistent star)", detail: "A `favourite Boolean @default(false)` column on WorkoutTemplate powers the Quick-start sheet's Favourites rail (see today-quick-start). Following the plan-maxes soft-guard idiom: the column lives in prisma/schema.prisma but is READ via a guarded raw query merged onto the existing GET /api/templates list (missing column → every routine reads favourite:false, never an error) and TOGGLED via a new guarded PATCH /api/templates/[id] ({ favourite } → $executeRaw UPDATE, soft-degrading to 503 before the column exists). The DELETE handler's owner check now selects only ownerId so it can't touch the new column pre-migration. Mobile api gains fetchRoutines' `favourite` field + favouriteRoutine(id, favourite). The favourite column is APPLIED in production (sql-pending.sql run, Jul 2026) — starring now persists." },
  { id: "today-confirmation-loop", area: "Core", status: "shipped", title: "Today confirmation loop + quick-access (free-version UX pass)", detail: "A pass on the free-version Today + navigation, mirrored web (components/aurora/today.tsx) + mobile (components/aurora/home.tsx) via shared core helpers (packages/core/src/engines/session.ts: sessionsOnDay/trainedToday/sessionShape/sessionCardioTotals). (1) DONE TODAY — every session logged today (a finished prescribed session OR a quick sport log) now surfaces on Today with a ✓ and a sport-adaptive one-line meta (distance–time for cardio, tonnage for lifts), tapping through to its detail; this is the missing acknowledgement that a workout counted (previously Today only ever prompted 'Start'). (2) SPORT-ADAPTIVE SESSION SUMMARY — the session detail + history-list cards read per-sport: a run/match has no 'volume', so cardio sessions show Duration–Distance–Pace (web components/session-detail.tsx + aurora/history.tsx, mobile app/session/[id].tsx + components/aurora/history.tsx). (3) SHARE ANY SESSION — the branded story-card share (previously strength-only / finish-screen-only) is now on EVERY logged session's detail (web + mobile). (4) COCKPIT + SPORT quick-access on Today — the Cockpit (command center) and Sport prescription are reachable straight from Today; free users get an upgrade nudge in the SAME tile (Cockpit is Full; sport-specific prescriptions are Full, logging any sport stays free via the quick-log carousel), FUNNEL sources today-cockpit / today-sport. (5) CALENDAR widget — a swipeable calendar card sits beside the week done-strip (this-week dates, today ringed, logged days lime-filled) for easy day-by-day access → the full Calendar. (6) CONNECT as two labelled sliders — the Today Connect section is a 'Feed' heading over a left/right horizontal rail of feed cards (FeedPreview `horizontal`), then a 'Coaches' heading over the CoachRail, each with an Explore action through to the social surface (revised from the earlier swipe-tabs per feedback: both rails are visible + independently scrollable, not hidden behind a tab). BOTTOM NAV changed to Today – Explore – [Train] – More – Profile on both clients (web pill-nav.tsx, mobile global-nav.tsx): Explore opens the social/discovery Feed, Profile is a bar slot again; Plans/History/Cockpit live in the More sheet. (The Explore slot has since been replaced by NUTRITION and the coach rail moved onto Today — see nav-nutrition-tab.) i18n nav.explore + w.home.today.kDone/doneView/cockpit*/sport*/cal*/connect* + session.duration/distance/pace (EN/PL/DE). (7) LOCKED PREMIUM LIST — the upgrade page (web components/aurora/upgrade.tsx + mobile components/aurora/upgrade.tsx) shows a free viewer the WHOLE Full toolkit with an explicit 🔒 on every feature (the Cockpit flagship + each bundle item); a paid-Simple viewer sees ✓. i18n w.account.upgrade.locked (EN/PL/DE). (8) LOCKED-VISIBLE NAV — reversing the old 'clean nav, no scattered padlocks' freemium rule: a FREE user now SEES every Full (athlete-tier) destination in the nav with a 🔒 badge instead of it being hidden, so the whole toolkit (Cockpit, Analytics, Periodize, Velocity, …) is discoverable; tapping a locked item routes to the upgrade screen (FUNNEL.upgradeEntryClick, source `more-<id>`/`sidebar-<id>`). Coach/admin-only tools stay HIDDEN for a casual user (role-gated, not purchasable). Driven by new core helpers packages/core/src/nav.ts `navForPersonaWithLocks` / `groupedNavWithLocks` (returning {item, locked}), consumed by the mobile More hub (app/(tabs)/more.tsx), the web pill-nav More sheet (components/aurora/pill-nav.tsx) AND the web sidebar (components/app-shell.tsx). Guarded by nav.test.ts (casual sees cockpit locked + coach hidden; athlete sees cockpit unlocked). (9) PLAN → CALENDAR link — the Today PLAN section kicker carries a direct 'Open calendar →' action to the full month Calendar (the swipeable calendar widget was easy to miss behind the horizontal swipe), on both clients via an optional Kicker `action`." },
  { id: "paid-is-full-by-default", area: "Core", status: "shipped", title: "Paid clients are Full by default (Simple/Full toggle retired)", detail: "resolvePersona (packages/core/src/nav.ts) now resolves a PAID client to the athlete (Full) surface BY DEFAULT — paying for Full no longer requires flipping a separate mode toggle. They only fall back to casual if they've EXPLICITLY chosen Simple (clientChoice === 'casual'). Free clients stay casual regardless of choice; coach/admin still outrank. This let the redundant two-tab 'Simple / Full' selector at the top of the mobile More hub (app/(tabs)/more.tsx) be removed — it duplicated the Unlock-Full card for free users and was unnecessary for paid users. The web persona pref in account Settings is unchanged. Guarded by the updated nav.test.ts." },
  { id: "calendar", area: "Web", status: "shipped", title: "Training calendar (web + mobile)", detail: "A month calendar (calendar.ts: sessionsByDay + monthMatrix + loadIntensity, pure + unit-tested) that paints each day by training load (sRPE heat) and marks session count, competition events (amber), AND assigned workouts (violet), with prev/next/today navigation and a day-detail panel (session volume/load/blocks/readiness, events, and assignments with Mark-done). Reads logged sessions + /api/events + /api/assignments. The shared engine is reused by the native mobile Calendar screen (Home → Calendar)." },
  { id: "fitness-gps", area: "Web", status: "shipped", title: "Fitness GPS home (Today)", detail: "Consumer-first landing that fuses the engines into one screen: today's route (velocity-aware prescription + readiness + why), an 'On track?' card (Accountability Engine band + risk + streak + habit strength + the right intervention), a Future Self projection (12-week strength curve + goal ETA + probability), and the Twin/HPI. The default web screen and the mobile Home tab. Reframes existing intelligence for a beginner — 'what to do today, why, and how far to the destination.'" },
  { id: "week-verdict", area: "Core", status: "shipped", title: "This week — the verdict card (Statistics + Analytics, merged onto Today)", detail: "Statistics and Analytics were two destinations answering the same question at two depths, on two different gates (statistics free for every persona, analytics athlete-only). They are now ONE block on Today, sitting directly under Readiness because it is the same kind of thing: a verdict with its working-out shown. packages/core/src/week-verdict.ts owns every decision — it sums tonnage / session count / training time over the last 7 days, builds a FOUR-WEEK baseline from the four weeks before it, and names the metric whose signed move from that baseline is largest. TWO HONESTY RULES, in the done-receipt tradition: NO BASELINE, NO VERDICT (fewer than MIN_BASELINE_WEEKS = 2 of the prior four weeks carrying training returns `cold` — the figures render with no claim over them, because a percentage off one week of history is a coin flip wearing a number), and QUIET IS A REAL ANSWER (nothing past VERDICT_THRESHOLD_PCT = 15 returns `flat` and names no metric — a card that finds something wrong every week is a card people stop reading). An EMPTY prior week counts INTO the baseline rather than being dropped: a fortnight off genuinely is part of your average, and excluding it would make every return from a layoff read as a personal best. The card never disappears — a block that comes and goes is worse than one that is sometimes quiet. RENDERING: the sentence takes a {m} template so the metric name can be bolded inside it without string concatenation (EN/PL/DE), the signed delta and the NAMED metric's column both carry the SEMANTIC colour (terracotta down, chartreuse up, ash flat — never the brand accent, so a bad week cannot read as a highlight), and the named metric sorts FIRST in the figure row so the claim and its number are visibly the same thing. FOURTH COLUMN: distance (km) joins tonnage / session count / training time, but ONLY when the athlete has endurance in the window or in its baseline — a pure lifter never carries an empty column, and a runner who took this week off still sees theirs (the week they most need to look at is exactly the week a value-gated column would vanish). It arrived when the Endurance block's own cross-sport totals strip was retired into this card, so Today states the week ONCE; at four columns the figures step down a size and the divider gutter tightens. Distance is read off the same cardio block field the lanes read, so the two cannot disagree about a kilometre. Twin components on both clients (aurora/week-verdict.tsx), mounted under the Readiness card. NAV: both leave More, the sidebar, the pill-nav and ⌘K via promotedTo, which keeps their routes, icons, i18n labels and persona gates live (the mechanism Endurance uses) — `analytics` promotedTo \"today\" and `statistics` promotedTo \"history\", because Statistics turned out to duplicate History rather than this card (see history-calendar-views: it is now History's TREND view). Two rows under the card are the doors back to that depth: History → every session, the week chapters and the trend chart, and — for athletes only — Analytics → /analytics (per-lift loads and trends, plus the coach/operator scopes for roles that hold them), so nothing is stranded. SUPERSEDED IN PART (Aug 2026) by activity-breakdown: the window is no longer a fixed rolling seven days and the totals are no longer lifting-shaped — the card carries a date filter and every figure opens into its own sessions. week-verdict.ts now takes an ActivityRange and compares it against the preceding windows of the same length (four for a week, three for a month, two years for a YTD), and its totals come from activity-window.ts so the figure and the list behind it are one arithmetic. 17 engine tests." },
  { id: "activity-breakdown", area: "Core", status: "shipped", title: "Today's summary card — date filter + figures that open (total activity)", detail: "The \"This week\" card stated one rolling seven-day window of mostly-lifting totals and stopped there. Three things were wrong with that, and this fixes all three. (1) THIS WEEK WASN'T THIS WEEK: a rolling now−7d window on a Thursday reports last Friday under a label claiming the current week. It is MONDAY → SUNDAY now (localMondayMs — the same week History, the plan schedule and every calendar surface already use). (2) THE TOTALS WEREN'T TOTAL: training time counted only sessions with a completedAt, so a tennis match logged as 90 minutes on a block contributed NOTHING to the week's hours. A session's minutes are now the greater of its wall-clock elapsed time and the sum of its blocks' own minutes (a watch import carries 44 minutes on a session with no stopwatch; a two-hour gym day holds one logged 20-minute finisher), block minutes are attributed to their own sport, and whatever wall-clock is LEFT OVER belongs to the lifting — or, in a session with no lifting, to its largest activity — so every group sums back to exactly the figure the card shows. (3) THE FIGURES HAD NO RECEIPTS: \"41.6 km\" is four sports in a trench coat — 39 km of running, 600 m in the pool, the rest across tennis and squash. CORE: activity-window.ts owns the period model (resolveActivityRange: week | d7 | d30 | ytd | m:YYYY-MM, with `through` capping a live period at the end of today and `days` counting only elapsed ones), activityBaselineWindows (the preceding windows of the same length, TRUNCATED to the current period's elapsed length so three days of this week are compared against the first three days of the four before it, not against four finished weeks), activityMonths (this month back to the oldest session, empty months INCLUDED — a blank March is a fact about the training year), and activitySummary, which returns per-metric GROUPS + the sessions under them. Grouping is by SPORT, not by tag: every racket/team/combat block carries the same `sport` discipline, so they group by NAME (Tennis and Squash stay apart instead of collapsing into one lane called \"Sport\"), and a group keeps its own natural distance unit so 600 m of swimming never has to read as 0.6 km inside a km total. BOTH CLIENTS (parity): aurora/week-verdict.tsx on web + mobile. The filter is the iOS segmented-control idiom — a track, one thumb that TRAVELS between segments (CSS transform on web, Animated.spring on mobile), the label it lands on taking the foreground — with a fifth segment opening a grouped-list sheet of individual months; the choice persists per device (localStorage / AsyncStorage). Every figure column is a button: pressing one expands a drawer beneath the row with a caret that SLIDES to point at the column it belongs to (a 0fr→1fr grid row on web, a measured Animated height on mobile), carrying a share bar, one tappable row per activity (tap to narrow the list) and the sessions themselves — each opening the logged session. 16 breakdown tests + 17 verdict tests. i18n EN/PL/DE." },
  { id: "web-dashboards", area: "Web", status: "shipped", title: "Analytics dashboards — BOTH clients (web + mobile)", detail: "The 3-scope Analytics dashboard (Athlete/Coach/Operator) ships on web AND mobile, per the parity rule. HISTORY, because this drifted twice: it was first retired from web in favour of a 'get the app' pointer while mobile had NO Analytics screen — so the dashboard had no live surface on EITHER client, and the mobile springboard (which treats a nav id with no route as web-only) opened the browser, which pointed back at the phone. Both halves are now real screens: web app-shell mounts aurora/analytics.tsx (recharts) and mobile has app/analytics.tsx + components/aurora/analytics.tsx (dependency-free bars/meters). SHARED ACCESS MODEL: nav.ts owns analyticsScopesFor(role) / resolveAnalyticsScope() / analyticsScopeLabelKey() / analyticsScopePrivacyKey(), so both clients derive scope availability from the AUTH ROLE (never the self-serve persona), land on the highest scope the role holds, fall back to the athlete scope on a mid-session demotion, and render the SAME per-scope privacy note above the charts. A coach now gets the athlete scope too (a coach trains too — matching the documented persona nesting; the old web build locked a coach to the roster scope alone). Scope tabs are hidden when the role holds only one. 6 scope unit tests + an i18n test asserting every scope label and privacy note resolves in EN/PL/DE." },
  { id: "warmup-sets", area: "Core", status: "shipped", title: "Mark sets as warm-up / cool-down", detail: "A per-set role on StrengthSet — working (default, absent) / warmup / cooldown — added as an optional additive field, mirroring how drop?/rest?/vel? already ride the shared SessionBlock shape so every pre-existing session stays valid. UI: the leftmost set badge is a single SET-TYPE CYCLER — tap to walk working → warm-up (amber W) → cool-down (blue C) → drop (lime ↓) → working — folding the role enum and the drop flag into one mutually-exclusive choice (a set is exactly one of these); '+ warm-up' / '+ cool-down' / '+ drop set' add-buttons add a pre-flagged set (so cool-down has a one-tap button now, not just the badge cycle). One source of truth in @hybrid/core (setType / cycleSetType / setTypeBadge, generic over both clients' differing set shapes) drives the web shared editor (workout-blocks.tsx → Logger + Builder), the mobile live logger (app/workout.tsx) and the read-back badges + ' – warm-up/cool-down/drop' tags on both session-detail screens. ENGINE EFFECTS (the real reason it matters): warm-up/cool-down sets are EXCLUDED from working-set volume (volumeByMuscle), session tonnage (sessionVolume), e1RM (blockBestE1rm → so PR detection + e1rm trends), and the training-log hardSets/topRpe — so a heavy ramp single can't fake a PR and warm-ups don't inflate the weekly hard-set counts that will feed the volume landmarks (MV/MEV/MAV/MRV, see volume-landmarks). Drop sets remain WORKING sets (they count). Warm-up ramp sets are KEPT for load–velocity profiling (velocity.ts reads set.vel directly — useful sub-maximal points). DESIGN DECISION: warm-ups/cool-downs are excluded from volume by DEFAULT, but this is now USER-CONFIGURABLE — a 'Count warm-ups in volume' toggle (logger-settings → countWarmupsInVolume, default off, RP-style) flows a setsForVolume(block, includeWarmups) option through sessionVolume / volumeByMuscle / weeklySetsByMuscle / volumeStatus / weeklyVolumeTrend / exerciseDashboard so the Volume, Trends and per-exercise screens honour it; PRs &amp; e1RM always stay warm-up-excluded regardless. Pure helpers unit-tested (isWorkingSet/workingSets/setType/cycleSetType/setTypeBadge + the excluded-from-volume/e1RM cases); localized EN/PL/DE." },
  { id: "manual-sport-session", area: "Core", status: "shipped", title: "Manual sport-session logging (Olympic sports)", detail: "Log a sport session by HAND — no wearable / connected gear required (complements the blocked `wearables` sync, which is an OPTIONAL accelerator, never the only way in). @hybrid/core olympic-sports.ts is THE single sport database for the whole app (unified Jul 2026 — it now also backs the S&C transfer engine; see sport-engine): OLYMPIC_SPORTS catalogs 60+ sports/disciplines (mostly Summer & Winter Olympic, plus a few the app prescribes for — BJJ, Squash), each with an icon, a category (Athletics/Aquatics/Cycling/Combat/Racket/Team/Gymnastics/Target/Outdoor/Strength/Winter/Multisport) and the PARAMETERS it actually tracks — every sport carries duration (minutes); the endurance sports (Running, Swimming, Cycling, Track Cycling, Mountain Biking, Rowing, Canoe Sprint, Race Walking, Triathlon, Cross-Country Skiing, Biathlon, Speed Skating, Short Track) add distance (km) and a derived pace. The prescribable sports additionally carry an `sc` (S&C) block that sports.ts projects into its engine view — one list, no drift. Helpers olympicSport (case-insensitive lookup), sportTracksDistance, olympicSportsByCategory + OLYMPIC_SPORT_NAMES; pure + unit-tested. A picked sport is logged as a normal CARDIO activity block named after the sport, so pace (pacePerKm), cardio PRs (distance/pace), history, the weekly recap and the training log all read it with ZERO special-casing — no new block kind, no migration. UI parity on BOTH clients via the shared model: web adds a '+ Sport' button + a categorized sport picker to the shared workout editor (workout-blocks.tsx → Logger + Builder); mobile adds a grouped, searchable 'Sports' section to the live-logger exercise picker (app/workout.tsx). The activity editor shows duration ONLY for known timed sports (Tennis, Judo, Gymnastics, …) and the distance + minutes → pace grid for distance sports + generic/custom cardio (timedSportOnly = a KNOWN Olympic sport that doesn't track distance, so a typed-in 'Run' keeps its distance field). PER-SPORT DISTANCE UNITS: distance is shown/entered in each sport's natural unit (metres for Swimming/Rowing/Canoe Sprint, km for the rest) and pace by its split (Swimming /100m, Rowing & Canoe Sprint /500m, everything else /km) — but STORAGE stays kilometres, so the shared pace/PR/recap math is always single-unit. olympic-sports.ts owns the conversion (sportDistanceUnit / displaySportDistance / parseSportDistance / formatSportDistance / sportPacePerMeters) and session.ts the sport-aware pace (cardioPace / formatSportPace); cardioSummary, both loggers' distance inputs + pace lines, and the cardio-PR celebration lines (web screens.tsx + mobile workout/session-detail) all render per-effort distance/pace in the sport unit, while AGGREGATE totals (weekly recap distance, the Running screen, cockpit km) correctly stay in km. ENTRY POINTS (all three logging surfaces + a home widget, both clients): (1) LOG SESSION — the sport picker is in the shared workout editor (web workout-blocks.tsx → Logger + Builder) and the mobile live-logger picker (app/workout.tsx). (2) BUILDER — web inherits the picker via the shared editor; mobile builder (app/builder.tsx + components/aurora/builder.tsx) now has its own categorized Sports section + sport-aware distance units (use-routine-builder.ts converts display↔km). (3) SPORT TAB — a '+ Log a {sport} session' button opens the logger pre-seeded with that sport (web app-shell onLogSession→pendingBlocks; mobile /workout?source=sport&sport=…). (4) TODAY/HOME QUICK-LOG WIDGET — a 'Log a sport session' card on the dashboard (web components/quick-sport.tsx in Today + Aurora Today; mobile components/quick-sport.tsx in the classic Home + Aurora Home) where the athlete picks a sport, enters time (+ distance for distance sports) and taps Log to save a real session straight to /api/sessions (mobile falls back to a guest/on-device stash) WITHOUT leaving home — 'back from a run → log it → done'. The sport selector is a RECENT/SUGGESTED shortlist (suggestedSports: the athlete's most-recently-logged Olympic sports newest-first, topped up with defaults) shown as one-tap chips, with a 'More' expander revealing the full categorized catalog — so the common case is a single tap. Picker + button copy localized EN/PL/DE; distance-unit labels (dist m/km) localized too. Pure helpers unit-tested." },
  { id: "reorder-sets-exercises", area: "Core", status: "shipped", title: "Reorder sets & exercises (arrows + drag-to-reorder)", detail: "Two pure helpers in @hybrid/core/session — moveItem(arr,index,dir) (one slot up/down, clamped at the ends) and moveItemTo(arr,from,to) (slide an item to any index, for drag-and-drop) — are the single source of truth both clients share, so set + exercise reordering can't drift. UI parity: reordering is HOLD-AND-DRAG everywhere — the ↑/↓ single-step arrow buttons are GONE from set rows and exercise/block cards on both clients (drag is the gesture people actually use; the arrows were dead weight). SETS — every strength set row has a ⠿ grip: web drags the row onto another row (HTML5 drag, constrained to the same block) in the shared editor (Logger + Builder), mobile lifts the row via a shared useDragReorder hook (lib/use-drag-reorder.ts — onLayout-measured rows, nearest-centre drop, keyed by group so a drag can never cross into another exercise's ledger) in BOTH the live logger and the Builder set ledger; the grip itself is the shared components/drag-handle.tsx (PanResponder, no gesture-handler dep). EXERCISES/BLOCKS — drag via the ⠿ grip on each card (the mobile Builder's block cards gained the grip when their arrows were removed): web uses native HTML5 drag (draggable handle → the card is a drop target → moveItemTo by uid), mobile uses a PanResponder-based DragHandle (no react-native-gesture-handler/reanimated dependency — consistent with SwipeRow) that lifts only the dragged card (Animated translateY + elevation), measures every card via onLayout, and on release drops it next to whichever card's centre is nearest (robust across variable card heights). The web Log Session screen now passes `reorder` (it previously had no reorder controls at all — only the Builder did), so logging and template-building share the same reorder + grip-handle affordances. moveItem/moveItemTo are unit-tested (swap/clamp/no-op + arbitrary-index slide, no mutation)." },
  { id: "logger-settings", area: "Core", status: "shipped", title: "Configurable workout logger (simple ↔ detailed + automation prefs)", detail: "The hardcoded logger behavior is now a per-device preferences layer. logger-prefs.ts in @hybrid/core is the single source of truth: LoggerPrefs + DEFAULT_LOGGER_PREFS + normalizeLoggerPrefs (type-safe merge over defaults, restSeconds clamped to REST_SECONDS_CHOICES) — pure + 4 unit tests. v1 settings: detailed (Simple↔Detailed — hides the RPE column on both clients), velocity (the M/S bar-velocity column for VBT logging — its OWN toggle, OFF by default, so the column only appears for athletes who train with a velocity device; gates the column in the mobile live logger and the shared web editor/Logger/Builder alike), countIn (5→1→GO overlay on/off), restTimer (auto rest countdown on/off — switchable from Settings AND on demand mid-workout via a ⏱ pill in both live loggers' header row, writing the same persisted pref; turning it off mid-rest also dismisses the running countdown) + restSeconds default (60/90/120/180), carryOver (pre-fill a new set from the previous), keepAwake, haptics, and countWarmupsInVolume (whether warm-up/cool-down sets count toward Volume/Trends/per-exercise volume — default off; see warmup-sets). MOBILE: a Logger-settings screen (app/logger-settings.tsx, reached from Settings) writes a useSyncExternalStore store (lib/logger-prefs.ts on AsyncStorage); the live workout (app/workout.tsx) honours every toggle — count-in, keep-awake, all haptics, carry-over, the RPE column, and the rest timer (enabled + default duration). WEB: lib/logger-prefs.ts (localStorage store) + a Simple/Detailed toggle on the Logger, which passes a new `detailed` prop into the shared WorkoutBlocks editor (Builder stays detailed). Localized EN/PL/DE (loggerPrefs.*). Defaults match today's behavior so nothing changes until opted into. NEXT (the fuller list, deferred): auto-approve/auto-advance, RPE-vs-RIR, units (kg/lb with real conversion), rest sound/background notification toggles, per-exercise rest, plate calculator + quick-increments, auto warm-up generator, default start view, and cross-device sync via a User-prefs column. This settings surface will re-home into account-settings-pro as its 'Logger' section." },
  { id: "units-pref", area: "Core", status: "shipped", title: "Weight units (kg / lb)", detail: "A user weight-unit preference (LoggerPrefs.units, default kg). Storage stays canonical KILOGRAMS everywhere — units.ts converts only at the display/input boundary (kgToUnit/unitToKg, displayLoad/storeLoad for editable load inputs, fmtWeight, fmtTonnage) so the engines, DB and cross-device sync never care about the unit. Pure + 4 unit tests. Wired through EVERY weight surface on both clients: the loggers' load column (input + header label), the per-exercise dashboard (stats + e1RM chart), the Trends exercise table + weekly-tonnage chart, session detail (per-set load, block e1RM, volume, muscle tonnage, e1RM trend, PR lines), the web analytics dashboard, AND the branded share cards + share text (WorkoutShareCard/RecapShareCard, the post-workout summary and the weekly recap). Also covered by this work: the logger flow toggles autoAdvance / defaultStart / rpeAsRir (RIR = 10−RPE via rpeRirSwap, stored as RPE). Toggle in mobile Logger settings + web account Preferences; localized EN/PL/DE (summary.volumeMoved, loggerPrefs.units/defaultStart/autoAdvance/rpeAsRir)." },
  { id: "web-logger", area: "Web", status: "shipped", title: "Session logger + history", detail: "Engine-prescribed or manual sessions saved to the DB; History lists real sessions. CARDIO and CONDITIONING are now SEPARATE block kinds (alongside strength): a `cardio` block (distance/minutes → derived pace — runs/rows/rides) is distinct from a `conditioning` block (format/work/rest/rounds/minutes — metcons/intervals/EMOMs), each with its own '+ Cardio' / '+ Conditioning' button, field set and badge colour. RPE is captured on STRENGTH sets only — cardio and conditioning don't ask for it. SessionBlock is a 3-way union (StrengthBlock | CardioBlock | ConditioningBlock); a pure `migrateBlocks` upgrades sessions logged before the split (a conditioning block carrying a distance and no interval shape → cardio) and is applied at every read boundary (/api/sessions GET + the server engine reads), so old runs render as cardio with zero data loss. Adding a conditioning/cardio block no longer pre-fills phantom minutes/RPE. The block editor (strength sets×load×reps×RPE×velocity, cardio distance/min, conditioning format/work/rest/rounds/min) is ONE shared component (components/workout-blocks.tsx) the Logger and the template Builder both render, so the two can't drift — both pull the same exercise catalog (built-ins + the admin exercise library via useExercises) and both keep the set-row grid from overflowing (1fr inputs get minWidth:0). The AI 'Use prescribed' path keeps the prescribed interval (work/rest seconds × rounds) intact AND derives editable minutes, so prescribed conditioning is no longer blank. On an AEROBIC day the engine prescribes a STEADY RUN with a real distance + goal pace read off the athlete's own logged runs (easyRunTarget: their median easy pace + typical distance, scaled by today's readiness; a gentle 5 km @ 6:30/km default before any run history) — distance/minutes flow into the logger so its derived pace matches the target. CARDIO: conditioning blocks take a distance (km) and the shared conditioningSummary/pacePerKm helpers DERIVE pace (min/km) from distance + minutes (never stored, so it can't disagree) — surfaced in History + session detail. SUPERSETS & DROP SETS: strength blocks can be grouped into supersets — tap 'superset ↑' to join the exercise above and the shared supersetLabels helper labels the group A1/A2/A3… (stable group key on StrengthBlock.group, so a group survives reordering and holds 3+ moves; the pure toggleSuperset helper does the join/leave + singleton cleanup). Any set can be flagged a drop set (a lighter, no-rest continuation; '+ drop set' adds one pre-flagged) via StrengthSet.drop. Both are additive optional fields on the shared SessionBlock shape so existing sessions/engines are untouched. An RPE cheatsheet (the shared @hybrid/core RPE_SCALE + RIR explainer) opens from the rpe column / a 'What's RPE?' button. LIVE LOGGER (full parity with the mobile train-funnel): the web Aurora logger is now a LIVE logger, not a fill-then-save form. apps/web/lib/use-workout-timer.ts (useWorkoutTimer + mmss) drives a get-ready COUNT-IN overlay (5→1→GO, gated by the shared `countIn` pref) then a sticky elapsed stopwatch with a PAUSE/hold (freezes the clock + any running rest, shifting both so neither jumps); the saved startedAt is the real clock start (at GO), not the Save instant. The shared WorkoutBlocks editor gained a `live` mode (used by the logger, not the Builder): a ✓-to-BANK column per strength set + a 'last time' reference per lift (lastStrengthByLift + blockSummary). Banking a set starts a REST COUNTDOWN (default from the `restSeconds` pref, 60/90/120/180 presets, over-rest readout, a navigator.vibrate buzz at the target — the web analog of the mobile haptic/notification) and records the rest taken on StrengthSet.rest; banking into a drop set or mid-superset skips the rest (you keep moving), and auto-advance appends a fresh set — matching mobile exactly. KEEP-AWAKE via the Wake Lock API (re-acquired on tab refocus), and DRAFT auto-save/resume via apps/web/lib/workout-draft.ts (localStorage, debounced; restored post-mount so SSR hydration stays intact, resuming the original clock) — so a refresh/crash never costs the session. The classic (non-Aurora) logger keeps the lighter count-in + elapsed clock. Mobile (app/workout.tsx) already had all of this; this brings web up to it. FINISH FLOW + ADD-SET REDESIGN: logging is now name-free and ends in a single primary 'Finish workout' button (no more 'Save session' / inline 'Save as routine' pair). The session AUTO-TITLES itself via the shared defaultSessionTitle() (time-of-day, identical on web + mobile) — there's no title input while logging, because nobody names a plain workout. Finishing IS the save and lands on the finish/summary screen, where naming actually happens: a shared SaveRoutineCard (Save as routine, with the only name field) plus an OPTIONAL ✎ rename of the session (web SessionRename + mobile SummaryRename → PATCH /api/sessions/[id], which now accepts a `title`; createSession/the web POST surface the new row id). Adding sets is no longer a row of five equal buttons — one primary '+ Add set' with warm-up / ramp / cool-down / drop tucked into a compact 'Special ▾' menu (web in workout-blocks.tsx, mobile in app/workout.tsx); the set badge still re-types a set with a tap. The classic web logger gets the same flow via a minimal finish panel. ENTRY POINTS: the Aurora bottom-pill Train FAB and the Today 'Start' both open the logger and the timer goes off immediately — the Train FAB opens an EMPTY session, while Today's plan card prefills the enrolled plan's day (planDayToBlocks). MOBILE parity: the Aurora Train FAB (components/aurora/global-nav.tsx) now drops straight into the live /workout?source=empty (timer + count-in) instead of the launcher hub, and the Aurora Today plan-card CTA follows the enrolled plan (source=plan) before falling back to AI/empty — both already ran the mobile live clock." },
  { id: "builder-signal-redesign", area: "Core", status: "shipped", title: "Builder redesign — the signal board (per-set control, modality-aware fields, live session math)", detail: "The Builder on BOTH clients is now a SIGNAL BOARD: every metric on screen is a live projection of the editable prescription, never a stored label. CORE (engines/session-signal.ts, pure + unit-tested): sessionSignal(blocks) → estimated duration, working tonnage and an integer strength ⇄ conditioning ⇄ endurance time split (sums to 100); estimateBlockMinutes (strength = working sets × (planned rest + ~45 s) + ~1 min per warm-up/cool-down; cardio = entered minutes; conditioning = minutes else rounds × (work+rest)); strengthBlockStats (scheme / top load / working tonnage); blockSignalSummary (collapsed one-liner, en-dash separators per the no-middot rule); the exercise-profile model (see exercise-profile-model) decides WHICH fields a cardio activity shows, so a squat can never show pace and a swim can never show incline on either client. SCHEMA (additive, optional): StrengthBlock.restSec (PLANNED rest between working sets — distinct from StrengthSet.rest, the live logger's measured rest), CardioBlock.incline / stroke / zone. PER-SET CONTROL: the mobile Builder previously flattened an exercise to 'N sets × one reps/load'; it now edits the REAL SessionBlock[] shape — every set its own row (load × reps × RPE/RIR each, honouring the rpeAsRir + kg/lb logger prefs via rpeRirSwap/displayLoad), set-role badges cycling working → warm-up → cool-down → drop (shared cycleSetType), add-set carry-over, and a planned-rest stepper (15 s steps, 15–600 s clamp) — what you save is exactly what the logger runs. WEB: the shared WorkoutBlocks editor gained a `signal` prop (Builder only — Logger untouched): collapsible block cards (header keeps the grip/name/summary; arrows + superset controls tuck away when collapsed) with an always-visible METRIC ROW derived per modality (strength: set×reps / top load / tonnage / est min; cardio: distance / pace / minutes; conditioning: format / rounds / est min), the rest stepper, and the new cardio extras fields; the Builder screen adds the SESSION PULSE strip (est time, fmtTonnage, moves, balance bar in lime/violet/teal). MOBILE (components/aurora/builder.tsx + lib/use-routine-builder.ts rewrite): the same signal cards, pulse strip, per-set ledger and modality fields, same core math. DESLOP: modality is encoded in the kind tag + the accent on the key metric — no left border rails anywhere, no middot separators (spaced en dash where a string separator is unavoidable). i18n: w.train.signal.* + new blocks keys (restBetween/inclinePct/stroke/zone/setCol/expand/collapse) in EN/PL/DE. SET DELETION (mobile): the Builder's per-row '−' remove button is gone — a set row is deleted by SWIPING it left (the live logger's SwipeRow, now a shared component at components/swipe-row.tsx with a host-card background prop), so the ledger reads clean; web keeps its explicit per-row remove button (a swipe gesture is a touch idiom, pointer surfaces want the visible control). RPE ⇄ RIR EVERYWHERE: the tap-the-column-header mode switch the Builder and web editor already had is now also on the mobile LIVE logger's RPE/RIR column head — one gesture on every set-editing surface, all writing the same rpeAsRir pref. BUILDER↔LOGGER PARITY (mobile Builder caught up to the other three surfaces): the M/S bar-velocity column (gated on the same velocity pref, off by default), drag-to-reorder set rows (see reorder-sets-exercises), and the 'Special ▾' add-set menu (warm-up / auto warm-up ramp / cool-down / drop, with the ramp's ~40/60/80% logic shared via core warmupRamp) — all reusing the live logger's i18n keys and visual vocabulary. NEXT: feed restSec into the live logger's rest-timer default per exercise, and surface the pulse on the routine cards in Train." },
  { id: "exercise-database", area: "Core", status: "shipped", title: "Exercise database — every gym exercise as first-class data", detail: "exercise-db.ts: a comprehensive built-in catalog (150+ exercises, integrity-tested) where EVERY gym exercise carries its own property sheet — fine-grained muscles (20 muscles, primary/secondary), movement pattern (squat/hinge/lunge/push-h/push-v/pull-h/pull-v/olympic/carry/core/isolation/plyo), equipment (barbell/dumbbell/kettlebell/machine/cable/bodyweight/trap-bar/ez-bar/smith/sled/medball/landmine…), mechanics (compound/isolation), unilateral flag, LOAD MODE (external / bodyweight — plain Pull-Up, Triceps Dip, Pistol Squat take NO load entry, the column disappears / bodyweight-plus — the Weighted Pull-Up, Weighted Triceps Dip, Weighted Chin-Up variants read BW + added / assisted), MEASURE (reps / time for planks+holds / distance for carries+sleds) and a baseLoad anchor. Covers Chest, Back, Shoulders, Traps & Forearms, Quads & Glutes, Hamstrings & Glutes, Calves, Biceps, Triceps, Abs & Core, Olympic & Power (full snatch/clean/jerk family + KB ballistics) and Carries & Conditioning. Query API: gymExercise (case-insensitive), gymExercisesByMuscle (primaries first), gymExercisesByEquipment, gymExercisesByCategory. ENGINE BRIDGE: each entry derives an engine Movement (fine muscles mapped onto the 7 fatigue groups) and folds into MOVEMENTS — so fatigue attribution, volume-by-muscle, landmarks, records, prescription and BOTH clients' pickers cover the whole catalog with zero per-engine changes; the 18 original hand-tuned entries still override their DB twins so pinned engine behaviour is unchanged, and the sport S&C engine now prescribes real starting loads for DB movements it used to treat as bodyweight. PICKERS: exercisesByCategory folds the DB's muscle-group headings in by default (admin-library categories still override; LIBRARY_CATEGORY_ORDER gained Olympic & Power + Carries & Conditioning); the web editor's ad-hoc BASE_CATALOG is gone. EDITORS READ THE DB: exerciseProfile now returns a per-lift StrengthProfile (measure/loadMode/unilateral/equipment) and the set editors adapt on web + mobile Builder + mobile live logger — a Plank's set column reads seconds, a Farmer Carry reads metres, a Pull-Up's load placeholder reads +kg (BW+added), an Assisted Pull-Up reads −kg. i18n: w.train.blocks.secs EN/PL/DE. DIPS split by target muscle (Jul 2026): 'Triceps Dip' (upright torso) is triceps-primary under Triceps, 'Chest Dip' (forward lean) is chest-primary under Chest, each with a weighted variant ('Weighted Triceps Dip' / 'Weighted Chest Dip', bodyweight-plus) and 'Bench Dip' kept under Triceps — so tonnage and volume-by-muscle attribute the right muscle. RENAMED (Jul 2026): the triceps variant was originally just 'Dip', ambiguous against 'Chest Dip'; it's now explicitly 'Triceps Dip' / 'Weighted Triceps Dip', with GYM_ALIASES bridging the old names so already-logged sessions still resolve and canonicalize (see exercise-name-canonicalization). All four count bodyweight toward tonnage via effectiveSetLoadKg (see bodyweight-tonnage): 10 bodyweight dips at 70 kg BW = 700 kg, the weighted variants add the entered plate. NEXT: aliases per DB entry (e.g. 'Kettlebell Swing' → 'KB Swing'), per-exercise coaching cues + video hooks (exercise-video-library), unilateral '/side' rendering in schemes, and admin-library editing OF built-ins (override a DB entry from the CMS)." },
  { id: "bodyweight-tonnage", area: "Core", status: "shipped", title: "Bodyweight-aware tonnage (10 BW pull-ups at 70 kg = 700 kg of work)", detail: "effectiveSetLoadKg (engines/session.ts) is the canonical per-set effective load, resolved from the exercise DB's load mode: external = the entered kg; bodyweight = the athlete's bodyweight (10 pull-ups at 70 kg BW = 700 kg); bodyweight-plus = BW + the entered added weight (+10 kg → 800 kg total); assisted = BW − the entered assistance. Sets measured in seconds or metres (planks, carries) are NEVER tonnage — multiplying a hold's seconds by a load isn't work done. sessionVolume, sessionSignal, strengthBlockStats and liveSessionStats all take an optional bodyweightKg and stay exactly backward-compatible without it (unknown bodyweight degrades to entered-load math, so guests and pre-weight users see no change). SOURCE: the dated /api/body history (Profile → Private → Body & progress) via bodyweight.ts — bodyweightLookup(points) resolves the weight the athlete WAS at each session's date (sessions older than the log use the earliest measurement; no date → current weight), surfaced by useBodyweightLookup()/useBodyweight() hooks on each client (one shared fetch per page). e1RM AND PRs are bodyweight-aware too: blockBestE1rm ranks bodyweight/BW-plus/assisted lifts on their EFFECTIVE load, and newPrsInSession/prsForSession/bestE1rmMap/bestE1rmByLift/e1rmSeries compare with the SAME dated basis on both sides, so a +15 kg weighted pull-up correctly beats a +10 kg one from a lighter era. WIRED EVERYWHERE the athlete's own data renders: the Builder pulse + signal cards, both live loggers (live stats, finish volume, finish PRs, fun-fact), session detail (stats, per-block e1RM, share card, e1RM trend), history rows, calendar day chips + sessionsByDay, Today/Home done-today meta, analytics (lifetime volume, PR list, volume series), Trends (weeklyVolumeTrend + exerciseTable), per-exercise dashboards, profile (lifetime tonnage, this-week, achievements, PR tiles), statistics + cockpit weekly recaps — on BOTH clients. Unit-tested: the 700/800 kg canonical example, holds/carries excluded, dated lookup semantics, and a BW+ PR comparing on effective load. NUDGE (Jul 2026): a bodyweight lift under-counts (a plain one reads 0) until a weight is on file, so BOTH live loggers show an inline 'Set your bodyweight to count this' card the moment the board has a bodyweight-dependent lift and no weight is known — core needsBodyweight(blocks, bw) + isBodyweightDependent(name) decide when (rep-counted bodyweight/bodyweight-plus/assisted only; holds/carries/external excluded). The card takes a weight in the athlete's unit, POSTs /api/body (web fetch; mobile lib/api.logBodyweight) and calls the new refreshBodyweight() to invalidate the shared bodyweight cache and re-fetch in every mounted hook, so the live volume recomputes and the card self-dismisses without a reload — no navigating away to Profile. i18n EN/PL/DE (w.train.logger.bwNudge* / live.bwNudge*). MUSCLE BREAKDOWN (Jul 2026): volumeByMuscle is now bodyweight-aware too (optional bodyweightKg → effectiveSetLoadKg, with the same holds/carries guard as sessionVolume so a plank never gains bodyweight × seconds) — so the finish-summary muscle slide, session detail's Muscle Focus, the Wrapped share cards, session-wrapped facts and the weekly recap's top-muscle all count dips/pull-ups on both clients instead of reading 0; every call site passes the athlete's weight at that session's date. DELIBERATELY NOT WIRED (viewer's weight would be the WRONG body): coach views of an athlete's sessions, the social feed/compare/leaderboards (other athletes), and the server API summaries (roster, ai-coach prompt, social posts) — each needs the SUBJECT athlete's BodyMetric server-side; recorded here so it isn't forgotten." },
  { id: "dumbbell-tonnage", area: "Core", status: "shipped", title: "Dumbbell tonnage counts both bells (24 kg × 10 = 480 kg, not 240)", detail: "A bilateral dumbbell lift is performed with TWO dumbbells, one per hand, each carrying the entered per-bell load — so a rep moves twice the number on the bell. loadUnitCount(name) (exercise-db.ts) returns 2 for a bilateral dumbbell exercise, 1 for everything else (barbell, machine, cable, a single kettlebell). UNILATERAL dumbbell work splits by which limb is one-sided: single-ARM upper-body work (a one-arm DB row, a concentration curl) holds one bell → 1, but single-LEG lower-body work (a Bulgarian split squat, a walking lunge, a single-leg RDL — squat/hinge/lunge patterns) is unilateral at the LEG while both hands still hold a bell → 2 (previously these read half: 100 kg × 1 counted 100, not 200). This factor scales VOLUME/tonnage ONLY and is applied at every tonnage site — sessionVolume (engines/session.ts), the Builder signal's strengthBlockStats (session-signal.ts), volumeByMuscle (records.ts), the per-exercise dashboard volume (exercise.ts), weeklyVolumeTrend (analytics.ts), and exercise-analytics v2's weekly tonnage + tonnage surface + block-vs-last comparison (via a tonnageKg field on each flattened LiftSet) — so the same doubling flows through lifetime tonnage, calendar/history/recap volume, achievements, fun-facts and the profile stats on BOTH clients with no client math. DELIBERATELY NOT DOUBLED: e1RM, rep-maxes and PR detection (blockBestE1rm/newPrsInSession/bestE1rmByLift and the analytics rep-max matrix / e1RM isolines / intensity zones) stay PER-BELL — a dumbbell 1RM is quoted per bell, and a cross-lift 1RM board must not rank dumbbell work on a doubled number — so loadUnitCount lives APART from effectiveSetLoadKg and is never folded into it. Unit-tested: the 24×10 = 480 canonical example, a unilateral DB lift staying single, and a barbell lift unchanged. GUIDANCE: both loggers (web workout-blocks + mobile Builder + mobile live logger, at parity) show a per-dumbbell hint under any bilateral dumbbell lift — 'Enter one dumbbell's weight — volume counts both.' (i18n w.train.blocks.dbPerHint, EN/PL/DE) — so the athlete enters one bell and understands the doubled tonnage. CUSTOM LIFTS: a free-text movement the catalog doesn't know (the picker's '+ …' custom add) never carries an equipment tag, so loadUnitCount falls back to the NAME — anything reading as a bilateral dumbbell move ('Dumbbell Thruster', 'DB Snatch') counts two bells, while single-arm / concentration phrasing stays one — so a bespoke DB lift no longer under-counts its tonnage by half. Because the doubling lives in the shared loadUnitCount, the per-dumbbell hint and every tonnage site pick it up on BOTH clients with no extra wiring. IMPLEMENT COUNT: a GymExercise can carry an explicit `implements: 1 | 2` that overrides the heuristic for a hold it can't read — a two-hands-ONE-implement lift (Goblet Squat, overhead dumbbell extension) gripped bilaterally on a single bell, where 100 kg × 10 is 1 000 kg, not 2 000. So loadUnitCount resolves in order: explicit implements → non-dumbbell = 1 → bilateral or single-LEG dumbbell (both hands loaded) = 2 → single-ARM dumbbell = 1; the custom-name fallback mirrors it (single-arm / goblet / pullover phrasing = 1, else a named dumbbell move = 2). Because tonnage is computed on read (never stored — Session.blocks holds the raw sets), correcting the count reflows through all historical sessions on both clients with no data migration." },
  { id: "exercise-name-canonicalization", area: "Core", status: "shipped", title: "Renaming an exercise propagates to every summary (logged-name canonicalization)", detail: "Renaming an exercise now reflows through EVERY summary, history row and analytic — not just future logs — with no data migration (the sandbox can't touch the DB). Root cause it fixes: a logged Session stores the exercise as a plain string, so renaming the catalog entry (e.g. the barbell 'Incline Bench Press' → the dumbbell 'Incline Dumbbell Bench Press') left already-logged sessions displaying the OLD name. THE LAYER: (1) a built-in rename registry GYM_ALIASES (exercise-db.ts) maps an old catalog name → its current name; gymExercise()/loadUnitCount() now resolve through it, so a historical 'Incline Bench Press' set gets the dumbbell profile + correct two-bell tonnage. (2) exerciseNameAliasMap(library) (engines/movements.ts) folds those built-in breadcrumbs with the admin library's per-entry aliases (alias → primary name) into one name→canonical map; canonicalExerciseName(name, map) resolves a name, following a rename CHAIN (A→B→C) with cycle-guarding. (3) canonicalizeBlockNames(blocks, map) rewrites each block's display name; migrateBlocks() now applies it (built-in map by default) at EVERY read boundary it already guarded — so the old name heals to the new one everywhere migrateBlocks runs (server /api/sessions GET + coach/roster/compare/squad, ai-coach, social feed, mobile guest sessions). (4) /api/sessions GET passes the FULL map (built-in + the cached published library's aliases) so an ADMIN rename (which keeps the old name as an alias) propagates to the athlete's own summaries on BOTH clients (mobile reads the same endpoint). Only the display name changes — sets/e1RM/PRs are untouched; idempotent + pure. Unit-tested (movements + session + exercise-db): the incline heal, admin-alias folding, custom-wins-over-builtin, rename-chain + cycle guard, and migrateBlocks canonicalization. Ships with the Incline Bench Press breadcrumb seeded." },

  { id: "body-progress-dashboard", area: "Core", status: "shipped", title: "Body & progress — weekly report + trends dashboard", detail: "Profile → Private → Body & progress, rebuilt from a two-field (weight + waist) box into a weekly body report over a trends grid, on BOTH clients. body-progress.ts is the shared source of truth: metricTrends() collapses the dated /api/body history into per-metric trends (latest, delta vs previous, direction, an up-to-8-point series); weeklyReport() derives the latest weight, its ~7-day delta, logging cadence (distinct days in the last 7) and a narrative verdict that reads the weight move together with waist/body-fat direction (down + leaner tape → 'lean'; up + bigger tape → 'build'); sparkHeights() normalises a series into dependency-free column-bar heights (mobile has no react-native-svg, so both clients render the sparkline with Views/divs — identical maths). The logger now captures all nine BodyMetric fields the API already stored but the UI hid (weight, body-fat, neck, chest, waist, hips, thigh, arm, calf); the trends grid surfaces whichever the athlete tracks. First-run state invites the first measurement with placeholder tiles. No API/schema change — GET /api/body already returned the full history. i18n EN/PL/DE. Pure trend maths is unit-tested. REDESIGN (Jul 2026): the block no longer sits as an always-expanded panel on the Private tab. It is now a COMPACT card in the same nutrition-row idiom as Today's rows (icon tile + title + a live subline that leads with the latest weight then the tracked-metric count, joined by a spaced en dash + a chevron) — the whole surface is tappable. Tapping opens the shared slide-up Sheet, which LEADS with the full log-measurement form (all nine BodyMetric inputs), exactly like 'Add a meal' opens from the Nutrition row; the weekly report hero, the per-metric trends grid and the progress-photos link now live INSIDE that sheet beneath the form. The old separate 'Log' pill and the standalone EmptyBody first-run panel were removed (the form is the first thing in the sheet). Web + mobile at parity (PrivateTab.BodyBlock on each)." },
  { id: "session-notes", area: "Core", status: "shipped", title: "Private per-workout note (mood + tags)", detail: "Private post-workout reflection attached to each logged Session, on BOTH clients — replacing the standalone Journal (which overlapped session notes + the daily recovery check-in note). The finish screen reveals an optional note: free text + a quick mood tap (1..4, rough → strong) + context tags (tough/easy/pr/niggle/form/deload/tired/motivated), PATCHed onto the just-saved session next to the existing rename affordance; the note (mood dot + text + tags) then renders on the owner's History cards. Shared primitives in notes.ts (MOODS, SUGGESTED_TAGS, sanitizeNote/Mood/Tags, hasNote) — pure, unit-tested. Schema adds Session.note (String?) + mood (Int?) + tags (String[]). OWNER-ONLY: note/mood/tags are kept out of the LoggedSession DTO and every non-owner serializer; the one raw-row endpoint (coach reads a client's sessions) now uses an explicit select that excludes them. The standalone Journal block was removed from Profile → Private; its JournalEntry model + /api/journal are left dormant (not dropped) so any existing notes are preserved. i18n EN/PL/DE. Session.note/mood/tags are APPLIED in production (sql-pending.sql run, Jul 2026)." },
  { id: "exercise-profile-model", area: "Core", status: "shipped", title: "Exercise-profile model — every exercise declares its OWN values & units", detail: "One declarative resolver (exercise-profile.ts: exerciseProfile(name) → { kind, fields[], pace, distanceUnit, paceLabel }) answers 'which fields does THIS exercise get' for every movement and sport, on both clients: running gets pace + distance (km) + time + elevation gain; swimming paces per /100 m with metre distances and a stroke field; rowing/canoe pace per /500 m; treadmill work swaps elevation for incline (%); tennis/judo/team sports are time-only; every cardio effort carries an HR zone; strength prescribes per-set load × reps × effort + planned rest; conditioning keeps format/work/rest/rounds. Resolution order: the Olympic-sports catalog wins (a catalog sport ALWAYS logs as cardio — the keyword heuristic only matches whole words, 'Run' but not 'Running'), then inferBlockKind + name heuristics for custom entries (treadmill/incline-walk → incline; swim strokes → stroke; run/trail/hike/ruck/cycling/skiing → elevation, suppressed when incline applies). Replaces the ad-hoc cardioExtras regex helper. Schema: CardioBlock.elevation (m) joins incline/stroke/zone — all optional + additive. CONSUMED BY: the web shared editor (workout-blocks.tsx — Builder AND live Logger), the mobile Builder (CardioEditor), and the mobile LIVE logger (app/workout.tsx: WExercise carries incline/stroke/elevation/zone, the cardio card renders the profile's fields, buildBlocks persists them, itemsFromBlocks restores them — with ?? '' guards so a pre-upgrade draft resumes safely). Unit-tested (exercise-profile.test.ts). i18n: w.train.blocks.elevation EN/PL/DE. NEXT: per-exercise strength profiles (tempo, unilateral/per-side, bodyweight+load), and surfacing stroke/incline/elevation in history + session detail summaries." },
  { id: "exercise-dashboard", area: "Core", status: "shipped", title: "Per-exercise dashboard (open a lift, see all its progress)", detail: "A dedicated dashboard for ONE movement — its whole progress history on web + mobile. exercise.ts: the new pure per-movement aggregator exerciseDashboard(sessions, name, period) with date-WINDOWING (periodCutoff: 8 weeks / 6 months / 1 year / all) + exerciseKind detection, returning a discriminated union — STRENGTH: best e1RM (window + all-time), working sets, tonnage, sessions/frequency, heaviest load, the best set, and the windowed e1RM trend (e1rmSeries); CARDIO: runs, distance, longest, best pace + a windowed pace trend (paceSeries/runStats). Reuses the canonical session helpers (warm-ups already excluded, so working-set counts are honest) so it can't drift; 6 unit tests. SURFACED as a new 'Exercises' screen (analyze group — FREE FOR ALL personas: the minPersona gate was removed so casual/free users get per-exercise progress too; it's a universal hook, not paid depth) on BOTH clients — web components/exercises.tsx (searchable exercise list + per-period charts via recharts) and mobile app/exercises.tsx (search + chips + dependency-free trend bars). A period selector (8wk/6mo/1yr/all) re-slices every stat. Honest empty states. Nav entry localized EN/PL/DE (screen body English for v1). DEEP-LINKED: every strength/cardio exercise name in the session-detail breakdown (web components/screens.tsx + mobile app/session/[id].tsx) is now tappable — straight to that movement's dashboard (web focuses the Exercises screen via app-shell's openExercise/exerciseFocus; mobile router.push('/exercises', { name })) — so you drill in from where you're already looking, in addition to the Trends table and the Exercises search. NEXT: the same deep-link from the live exercise picker, and the velocity profile inline when bar speed is logged." },
  { id: "exercise-analytics-v2", area: "Core", status: "shipped", title: "Exercise dashboard v2 — advanced per-movement analytics", detail: "The (free-for-all) Exercises screen upgraded from 4 tiles + one trend line to a full analytics surface, on BOTH clients from ONE set of pure aggregators (engines/exercise-analytics.ts, 14 unit tests, all computed from LoggedSession so it works offline for free users). Shipped cards — strength: 1) heaviest-lift trend with PR-marked sessions (topLoadTrendWithPRs — the actual top weight is the headline, e1RM is a secondary stat; PRs judged against ALL history, not just the window), 2) rep-max matrix (best-ever 1–10RM grid with 8-week freshness shading + never-attempted cells as session ideas), 3) load×reps map (every working set as a dot, dashed Epley equal-e1RM isolines, recent sets highlighted), 4) weekly tonnage stacked by effort (hard = RPE ≥ 8; no-RPE counts as base), 5) intensity distribution (%e1RM zones vs the ROLLING all-time best so old sets grade honestly), 6) isometric 3D tonnage landscape (12 weeks × rep-range bins); cardio: 9) best-pace-per-distance-band curve (all-time vs last 8 weeks) + last-runs-vs-own-average delta bars (the honest stand-in for km splits, which aren't logged); both kinds: 8) per-movement consistency (26-week heat calendar reusing trainingHeatmap + week streak / per-week / longest gap), 10) this-block-vs-previous compare (8-week windows: delta-chipped metric tiles + week-aligned weekly overlay). Web renders recharts + custom SVG (aurora/exercises.tsx), mobile mirrors with react-native-svg (aurora/exercise-charts.tsx). Chart colors: brand accents for single-series, the CVD-validated deep chartreuse/sand pair (#84a01e/#bd871e) for stacked series. Localized EN/PL/DE. Designed in reference/exercise-analytics-designs.html; concept 7 (rankings) intentionally NOT built — see exercise-analytics-rankings." },
  { id: "today-exercise-widget", area: "Core", status: "shipped", title: "Today Exercises widget + individual exercise page (variant B)", detail: "The free-for-all Exercises surface pulled onto the HOMEPAGE as an iPhone-style widget rail, plus a dedicated per-movement page — on BOTH clients from ONE core module (exercise-widget.ts, 12 unit tests). WIDGET: exerciseWidgetCards auto-picks favourites so different purposes lead (most-trained strength lift, cardio move and conditioning move of the last 8 weeks, explicit favourites honoured first — the favourites param is ready for a user-managed list), each card carrying an 8-week headline (strength = the ACTUAL HEAVIEST lift, topLoadSeries, not estimated 1RM — e1RM is a secondary stat / best pace / strength-fallback tonnage / weekly MINUTES for conditioning + minutes-only cardio — ConditioningBlock has no per-set loads, so duration IS its volume, derived from the interval format when unlogged), a stock-ticker delta vs the PREVIOUS 8 weeks (pace: faster = improving) and a full-bleed sparkline — the 'chart is the card' reduced design (variant B) chosen over the badge-heavy variant A in review; prototypes for both in reference/exercises-widget-preview{,-ive}.html. Rail hides until history exists; end card + All link open the Exercises tab. PAGE: exercisePageModel returns hero-per-slide stats (strength: heaviest-lift PR trend (topLoadTrendWithPRs — actual top weight, e1RM demoted to a secondary substat), weekly tonnage, %e1RM zones, 26-wk consistency; cardio: pace trend, pace curve, runs-vs-average deltas, consistency — each gated on real data, minutes-only cardio falls back to weekly minutes; conditioning: weekly minutes, consistency) rendered as a no-boxes screen — one big number crossfading with the swiped chart, hairline segment indicator, quiet ALL STATS expansion, typographic substats row, 8W/6M/1Y/All underline periods. Web: aurora/exercise-widget.tsx + exercise-page.tsx (recharts), new 'exercise' app-shell screen (back → Today). Mobile: same-named components (react-native-svg), /exercise?name=… route, rail on aurora/home.tsx. Localized EN/PL/DE. NEXT: user-managed favourites (persisted), and PR push notifications off the widget deltas." },
  { id: "exercise-page-unification", area: "Core", status: "shipped", title: "One canonical exercise page (Exercises screen becomes a picker)", detail: "Fixes the split where an individual exercise opened TWO different screens depending on entry point: the Today favourites widget led to the variant-B exercise page, while More → Exercises / Trends / History / session detail led to the older inline Exercises dashboard. The exercise page is now the golden standard — the ONLY individual-exercise screen — and it absorbed the dashboard's full data/chart set AS SLIDES in the variant-B pager (per review: no boxed card stack — one hero number crossfading with one full-bleed chart, matching the Ive-reduced design). exercisePageModel gained the deep-dive slides, all gated on real data: repMax (best-ever 1–10RM grid, hero = heaviest rep-max), loadReps (load×reps cloud + e1RM isolines, hero = working sets plotted), surface (12-week isometric tonnage landscape, hero = peak week×rep-bin tonnage), compare (this 8-week block vs the previous — weekly overlay + delta-marked metric tiles, hero = block volume/distance with a ticker delta), and the consistency slide upgraded to the 26-week heat calendar + streak/per-week/gap/active-day stats (exerciseConsistency detail); the cardio paceCurve slide now draws the recent-vs-all-time band curve. Slide order: strength heaviest-lift (topLoadTrendWithPRs — the actual top weight is the headline; e1RM stays secondary in the substats + zones/isolines) → tonnage → zones → repMax → loadReps → surface → compare → consistency; cardio pace → curve → deltas → compare → consistency (unit-tested). Best set + velocity profile render as quiet typography over a hairline under the substats — no boxes anywhere. The interim web aurora/exercise-analytics.tsx and mobile aurora/exercise-charts.tsx card files were deleted; both clients render the new slides natively (recharts/SVG on web, react-native-svg on mobile) from the ONE core model. The Exercises screen is now a pure movement PICKER (search + kind/count/last-used rows) routing to the page: web app-shell's single openExercisePage (Today widget, picker, Trends, History/session detail) remembers the return screen so back goes to wherever you came from; mobile /exercises rows push /exercise?name=…, legacy /exercises?name deep links redirect to the page, and the Trends + session-detail deep links were retargeted. Same @hybrid/core aggregators throughout." },
  { id: "exercise-anatomy-animation", area: "Core", status: "shipped", title: "Exercise page — 'How it's done' animation + muscle activation + body-map", detail: "Every gym lift's exercise page now has a 'How it's done' surface, on BOTH clients from ONE pure core module (exercise-anatomy.ts, unit-tested). THREE parts, all derived from the exercise DB so all ~190 lifts are covered with zero per-exercise authoring: (1) a LOOPING SCHEMATIC ANIMATION of the movement — a side-profile stick figure whose 7-joint skeleton ping-pongs through 2–3 hand-tuned keyframes per movement ARCHETYPE (squat/lunge/hinge/hipThrust/pressH/pressV/dip/pullH/pullV/curl/extension/raise/calf/plank/crunch/hangingLeg/twist/jump/carry/olympic/generic; exerciseArchetype() resolves pattern-first, refined by category/name so a curl, a lateral raise and a triceps pushdown each get the right motion), with the loaded implement drawn per equipment (barbell/dumbbell/kettlebell/bodyweight/fixed) and a faint dotted trace of the bar path; skeletonAt() interpolates a triangle-wave eased phase so web + mobile render the exact same motion, and both respect prefers-reduced-motion (a held mid-rep pose). This is the unblocked, offline, zero-asset answer to 'show the movement' while the licensed demo-VIDEO library stays blocked (exercise-video-library). (2) MUSCLE ACTIVATION — the DB's primary/secondary muscles (order = importance) become a ranked list with a share-of-effort PERCENTAGE per muscle (primaries take the bulk weighted by order, secondaries split the remainder; muscleActivation() always sums to 100) and a High/Moderate/Low tier, each with an anatomical label ('Pectoralis major (chest)') and a bar — the 'main driver … triceps ~25%' breakdown, computed not typed. (3) STABILIZERS + step-by-step form CUES + a plain-language EMPHASIS line (e.g. bench: 'the shoulder joint contributes ~75% of the force, triceps finish the lockout ~25%'), keyed off the archetype. PRESENTED AS A BOTTOM SHEET: a compact 'How it's done' PILL sits under the exercise name; tapping it opens a slide-up sheet (web = scrim + dialog with Esc/scroll-lock, mobile = RN Modal animationType slide, both bottom-anchored with a grabber + close) holding the animation + muscles + stabilizers + cues. This keeps the page a clean STATS view for the many athletes who already know the lift; the animation loops only while the sheet is open (an `active` prop gates the rAF), and on mobile a light haptic fires on open (gated on the user's haptics preference). Renders on web (aurora/exercise-anatomy.tsx) and mobile (aurora/exercise-anatomy.tsx); the pill sits directly under the exercise name above the analytics and skips silently for cardio sports + custom names the DB doesn't know. Localized EN/PL/DE (w.analyze.exp.anatomy.*). ANIMATION SEPARATED FOR SWAP: the movement demo is deliberately isolated from the muscles/cues so it can be replaced by professional sketch animation without touching the anatomy content. Core exercise-animation.ts owns the movement taxonomy (exerciseArchetype), the skeleton + keyframes + skeletonAt, and returns a DISCRIMINATED-UNION spec from exerciseAnimation(name): SkeletonAnimation (procedural, today) | SketchAnimation (commissioned frames). A SKETCH_ANIMATIONS registry (keyed by exact name or archetype, empty today) is the single data swap point — populate it and the resolver returns the sketch, with the skeleton as the automatic per-lift fallback. Each client has its own exercise-animation.tsx component that resolves the spec and switches on kind (skeleton renderer live; sketch renderer — a cross-faded frame player — wired but dormant), embedded by the anatomy section. So shipping sketches is: (1) register assets in core, (2) the sketch renderer branch is already there — the muscle-activation/cues section never changes. FRONT/BACK BODY-MAP (Jul 2026): the side-profile motion is now complemented by an anatomical BODY-MAP that shows WHERE the effort lands — a second pure-shared core module (body-map.ts, unit-tested) of schematic geometry: two mannequin figures (front + back, so posterior-chain lifts light their hamstrings/glutes/lats/erectors — a single view would miss half the body), each muscle a simple polygon region in the same 0-100 box as the skeleton (bilateral muscles carry a mirrored left+right shape; each of the 20 DB muscles is assigned to EXACTLY ONE figure so it never appears twice). Every region GLOWS in proportion to that lift's share of effort — intensity = the muscle's pct ÷ the top mover's pct (0..1), computed by muscleGlows() from the SAME muscleActivation() data as the ranked bars, so the picture and the numbers can't drift: primary movers bright, secondary dimmer, untargeted faint (one hue, opacity carries the signal). exerciseBodyMap(name) returns the ranked glow + a muscle→intensity map, or null for a name the DB doesn't know. Rendered on web (aurora/body-map.tsx) and mobile (aurora/body-map.tsx) at parity, embedded in the 'How it's done' sheet directly under the 'Muscles worked' header — the VISUAL first, then the ranked bars — as two side-by-side figures (Front/Back labels) with a legend (Primary/Secondary/Not targeted) and a caption that names the top mover by default and swaps to whichever muscle you hover (web) / tap (mobile); theme-aware (Aurora dark ⇄ Kyoto light, drawn in the lime accent). New i18n w.analyze.exp.anatomy.map.* (front/back/primary/secondary/off, EN/PL/DE). Verified by headless-Chromium render across bench/deadlift/curl/pull-up/press/squat. BODY-MAP SEPARATED FOR SWAP (like the animation): the schematic mannequin is deliberately the zero-asset DEFAULT, ready to be replaced by professional anatomical illustration without touching the muscle/cues section. exerciseBodyMap(name) returns kind:'schematic'|'sketch' — the SAME discriminated-swap idiom as exerciseAnimation — carrying the always-present schematic `figures` plus an optional `sketch` (SketchBodyArt: base front/back illustration + per-muscle highlight overlays). A single SKETCH_BODY_ART holder (EMPTY today; the body art is GLOBAL — the illustration doesn't change per lift, only which muscles glow — so unlike the per-exercise SKETCH_ANIMATIONS registry it's one art set, not a name→asset map) is the single swap point: set it and every lift flips to kind:'sketch', with the SAME intensity data driving the overlay opacities. Each client's body-map.tsx switches on kind (schematic renderer live; sketch renderer — base image + intensity-composited per-muscle overlays — wired but dormant). NEXT: populate SKETCH_ANIMATIONS + SKETCH_BODY_ART once the licensed/commissioned art exists (exercise-video-library)." },
  { id: "exercises-smart-browse", area: "Core", status: "shipped", title: "Exercises picker — smart sort, hybrid buckets, Aurora-pass design", detail: "The Exercises screen (the movement picker) rebuilt from the raw last-used dump into the reviewed 'Aurora pass' design, on BOTH clients from ONE pure core module (engines/exercise-browse.ts, unit-tested). SMART ORDER: a time-decayed use score (Σ 0.5^(daysAgo/14) over the last 90 days) so the ranking tracks the CURRENT training block, not lifetime totals — switch from a year of back work to legs and the leg lifts top the list within a week; a recency-tier floor (used this week → this month → older) guarantees this week's rotation can never sink below ancient history. HYBRID BUCKETS: seven one-word sections (Olympic, Legs, Posterior, Push, Pull, Core, Engine — merging the muscle-group headings with the movement patterns; pattern is the tiebreaker so a deadlift filed under Back lands in Posterior, sled work in Engine, Olympic & Power plyo in Olympic; keyword fallback buckets free-typed names like 'Clean Extension' → Olympic, with the snatch/clean/jerk family beating the lift words they contain). SIGNALS: staple (trained ≥3 of the last 4 weeks → lime monogram tile), stale (established lift untouched ≥14 d → amber recency ghost), in-rotation (≤14 d). UI (web aurora/exercises.tsx + mobile aurora/exercises.tsx, assembled from shipped parts): Explore's hero + search, Smart/Groups/A–Z sort pills (lime fill active), a 'This block' band wearing Profile's cover gradient (violet→lime wash + lime corner glow) with in-rotation/this-week stats, Explore SectionHead-style bucket headers (18px black + mono count), plan-card row cards with monogram tiles and a single mono recency ghost ('5 d' / 'today') — counts/dates/kind live on the exercise page, not the list. Groups pill = fixed bucket order; Smart = buckets ordered by best-ranked entry; A–Z = flat alphabetical; search filters flat. Localized EN/PL/DE (w.analyze.ex.*). Designed in-session (8 sorting concepts → combined buckets → Ive reduction → Aurora tokens); rationale preserved in the session's preview HTML." },
  { id: "exercise-analytics-rankings", area: "Core", status: "planned", title: "Exercise analytics — rankings (standards, percentiles, club board)", detail: "Concept 7 of the exercise-analytics designs (reference/exercise-analytics-designs.html), explicitly excluded from the v2 build by user decision. Would add: strength-standards ladder (beginner→elite by bodyweight multiple), percentile vs bodyweight class, age/sex-graded running percentile, and a club leaderboard (bodyweight-normalised, opt-in). Standards + percentile tables can ship as static core data; the club board needs the social schema (see social-schema)." },
  { id: "training-analytics-hub", area: "Core", status: "shipped", title: "Training analytics hub (muscle breakdown, volume trends, exercise analytics)", detail: "A 'Trends' destination that sits ABOVE the per-exercise dashboards (exercise-dashboard) and ties the logging-quality ideas together — distinct from the web-dashboards capability (the client/coach/admin SCOPE overview); this is the deep training view. analytics.ts (pure + 3 unit tests): weeklyVolumeTrend (rolling 8-week WORKING-set count + tonnage — warm-ups excluded via warmup-sets) and exerciseTable (one row per movement trained in the period with frequency, heaviest actual lift (topWeight — e1RM demoted to secondary), volume and an improvement trend ▲/▼/→ off the top weight, sorted by volume, built on exerciseDashboard). The screen composes three sections: (1) VOLUME TRENDS — weekly working-sets + tonnage bars; (2) MUSCLE BREAKDOWN — this week's per-muscle sets coloured by landmark zone (volumeStatus/volumeAdvice from volume-landmarks) with a link to the Volume screen for detail; (3) EXERCISE ANALYTICS TABLE — sortable, an 8wk/6mo/1yr/all period selector, each row DRILLING INTO that movement's per-exercise dashboard. Web components/trends.tsx (recharts; row → focuses the Exercises screen via a shared exerciseFocus state in app-shell) + mobile app/trends.tsx (dependency-free bars; row → router.push('/exercises', { name }) which the Exercises route preselects from the param). Nav entry 'trends' (analyze group, athlete) localized EN/PL/DE; screen body English for v1. Honest empty states. NEXT: per-muscle volume trend lines (not just overall) and sortable column headers." },
  { id: "trends-sheet", area: "Core", status: "shipped", title: "Trends — one sheet, figures first (card redesign)", detail: "The Trends screen's three floating cards (weekly sets, weekly tonnage, exercise analytics) are now ONE sheet divided by hairlines — idea 7 of design/trend-cards-redesign-ideas.html, picked from seven treatments. What it fixes, in the order the critique found it: (1) THE FIGURE LEADS. The week's number was the smallest text on the card (10px mono, bottom-right corner) under 80dp of chart; it is now the band's subject at fs.display with its unit beside it and its eight-week average under it. (2) TRUE ZERO. Every empty week used to be floored at a 6px stub, so 'trained nothing' and 'trained a little' drew identically and the floor read as a real baseline. The new sparkline (packages/core/src/spark.ts, `sparkline()` — ONE geometry function, unit-tested, consumed by web <svg> and mobile react-native-svg so the two lines cannot drift) anchors the scale at zero and sits an empty week ON the baseline. (3) THE TWINS. Sets and tonnage were the same eight weeks drawn twice in two hues; they are now two bands of one object. (4) ONE MEANING PER COLOUR. Chartreuse marks only the current week and the live selection — exercise names return to chalk, and the period switch loses its filled pill for an underline that moves. (5) THE ARROW BECOMES A FIGURE. `ExerciseTableRow.change` carries the SIGNED delta behind `trend` (strength: kg on the top load; cardio: seconds per km on pace, where a negative number is faster), rendered by the shared `fmtRowChange()` as '+5 kg' / '−12 s/km' with a true minus, colour still taken from `trend` because the sign alone can't say 'improved'. The column is sortable like the rest. (6) SENTENCE-CASE LABELS, no mono capitals and no separator in a title — mono is kept for data, where tabular figures earn it. Sorting keeps all five keys (the header's second line mirrors the row's second line: freq – volume). New i18n setsMeasure/tonnageMeasure/avg8w/perExercise/colChange (EN/PL/DE). Web recharts BarCharts retired from this screen. Web + mobile identical in the same change." },
  { id: "web-session-detail", area: "Web", status: "shipped", title: "Session detail (web)", detail: "History rows are now clickable (with a 🏆 PR chip) and open a full session breakdown matching mobile: minutes/sets/tonnage stats, a PR banner (pr-detection), a muscle-focus tonnage chart (volumeByMuscle), the heaviest lift's e1RM trend (recharts LineChart over e1rmSeries), and — for runs — a first-class PACE trend (paceSeries over the session's headline cardio move, recharts LineChart with a reversed axis so faster trends up, m:ss/km ticks), plus a per-exercise table with each set + block est-1RM, PR-badged. Pure client state in the History screen — no new route." },
  { id: "web-plans-sport", area: "Web", status: "shipped", title: "Plans + Sport screens", detail: "Render the shared plan library and sport engine. The Plans landing is the library cover over one full-bleed shelf per category (see plans-stack-one-object); free-text SEARCH over the shared, unit-tested filterGoalGroups(query) in @hybrid/core (matches goal name/blurb, drops empty groups) is what narrows it, so the two clients narrow identically and can't drift, and an empty result shows a 'no goals match' line. The category chips no longer filter — with every category already on screen as its own shelf, narrowing to one emptied the screen, so they dock under the collapsed cover bar and JUMP to a shelf instead. The Sport screen remembers the athlete's sport, level and per-sport performance markers (persisted client-side on web; sport + level on mobile), so it reflects them rather than opening on a default selection." },
  { id: "web-periodize", area: "Web", status: "shipped", title: "Periodize", detail: "Renders a real macrocycle (phase timeline + load/recovery microcycles). Now on mobile too (app/periodize.tsx — same phase timeline + per-phase microcycle bars off the enrolled season), reachable from the More hub + the cockpit." },
  { id: "web-running", area: "Web", status: "shipped", title: "Running analytics (folded into the Endurance hub)", detail: "Running analytics — now the 'running' discipline INSIDE the Endurance hub (the standalone Running screen + its nav item were removed on both clients to avoid duplicating what the hub already shows) — read the logged cardio: a pure, unit-tested running engine (running.ts — runTotals, runStats per move with best pace + longest, weeklyMileage over the last 8 weeks, paceEffortSplit, pacedRunMoves) drives headline totals (runs / distance / time / easy-%), a weekly-mileage chart (recharts bars on web, dependency-free bars on mobile), a pace trend per move (paceSeries, reversed axis / faster-is-taller bars), an easy/steady/hard PACE-ZONE bar — intensity DERIVED FROM PACE with no manual input: per move, anchored to the athlete's best (fastest) pace (hard ≤6% off best, easy ≥16% slower), and a tightly-clustered move (<8% spread) reads as steady rather than guessing; the bar auto-hides until there's enough pace data — and a by-movement table (runs/km/longest/best pace). Honest empty state until a run with distance + minutes is logged. These now render inside the Endurance hub (aurora/endurance.tsx, both clients) when 'running' is the selected discipline — the old aurora/running.tsx screens + the /(tabs)/running route + the 'running' nav item were deleted. DISCIPLINE-TAGGED CARDIO: every logged sport lands in a cardio block (a pool session, tennis, a ride, a row all share the same shape), so a CardioBlock now carries a coarse `discipline` tag (running/swimming/cycling/rowing/skiing/walking/sport/other — session.ts cardioDiscipline()). It's stamped at log time by the sport/run loggers (quick-sport, sport, run-track on BOTH clients) and backfilled from the name on read by migrateBlocks, so consumers read a stable tag instead of re-guessing. The Running screen filters via runningSessions() (discipline === 'running') so a swim or tennis session never counts as a 'run'; the Cockpit's Endurance summary filters via enduranceSessions() (drops discipline === 'sport' — tennis/football/etc — but keeps swims/rides/rows/generic cardio); the AI coach keeps its mileage/pace/easy-hard math run-coherent and reports other endurance (swim/ride/row) as a separate cross-training count. Both clients feed the SAME filters, so they can't drift." },
  { id: "endurance-hub", area: "Core", status: "shipped", title: "Endurance hub — per-discipline analytics (swim/bike/row/ski), BOTH clients", detail: "The Running screen was runs-only, so swims, rides, rows and skis had no analytics home — the Endurance hub gives each endurance discipline the same analytics the Running screen gave running, keyed off the CardioBlock `discipline` tag. CORE: endurance.ts — activeDisciplines(sessions) (disciplines with logged cardio, most efforts first; excludes 'sport' — tennis/football aren't endurance), DISCIPLINE_META (per-discipline label key + emoji + pace-vs-speed mode + pacePer + unit), formatDisciplinePace()/disciplinePaceUnit() (labels a canonical sec/km rate as that discipline's pace — /km run, /100m swim, /500m row — or km/h SPEED for cycling), and disciplineSessions() in running.ts. 6 unit tests. BOTH CLIENTS (parity): mobile app/(tabs)/endurance.tsx + components/aurora/endurance.tsx, and web components/aurora/endurance.tsx mounted at the 'endurance' screen — same sections in the same order (discipline picker, totals, weekly volume, effort split, pace trend, by-move table), same core helpers, same empty states; only the rendering differs (recharts on web, dependency-free bars on mobile). Every pace/best value is labelled in the selected discipline's own unit. PARITY HISTORY: the standalone Running screen was removed from both clients and folded in as the 'running' discipline, but the web hub was initially NOT built — web got a 'get the app' pointer instead, which broke the parity rule and left the web Cockpit's Endurance module linking at nothing. The web hub now exists and the Cockpit links to it again on both clients. REMAINING (Phase 2): cycling speed refinements + elevation, swim stroke/zone breakdowns, per-discipline PRs (formatCardioPr), and per-effort distance in the discipline's natural unit (MVP shows km everywhere; only pace switches unit)." },
  { id: "web-velocity", area: "Web", status: "shipped", title: "Velocity (VBT) screen", detail: "Velocity screen on the shared vbt-engine: pick a lift → estimated 1RM from velocity, the load–velocity profile chart (measured sets + fitted line crossing the MVT), the velocity-zone reference, recent sets with bar speed + zone, and the autoregulated 'AI load' recommender (drag a target bar speed → suggested kg + %1RM). The live logger captures bar speed per set via the exercise detail sheet (live-logger-exercise-sheet, both clients); the Builder grid keeps its m/s column behind the velocity pref. With no bar speed logged the screen shows an honest empty state (no sample data) on web + mobile." },
  { id: "team-compare", area: "Web", status: "shipped", title: "Team compare (group coaching)", detail: "A coach lines up their whole roster side by side on any lift — best e1RM, the velocity-based 1RM, best bar speed, total volume and reps — as a ranked bar chart + table, switchable by exercise and metric. /api/coach/compare computes every stat server-side from each ACTIVE client's real sessions (consent-gated by CoachLink, only the coach's own athletes). Empty-state guides coaches with no roster yet." },
  { id: "branded-select", area: "Web", status: "shipped", title: "Branded dropdown control", detail: "A single Select component in apps/web/lib/ui.tsx replaces every native <select> across the app (language switcher, talent profile/discovery, competition, RTP, org roster/teams, coach assign). Strips the OS chrome (appearance:none), draws a brand chevron, paints the control with @hybrid/core tokens (ink2/line/chalk + lime focus ring) and supports a rounded `pill` variant for the header language switch — so dropdowns stop looking like raw browser widgets and match the dark identity. Note: the open option list on macOS is still OS-rendered (unstylable by the web platform)." },

  { id: "liquid-glass", area: "Web", status: "shipped", title: "Liquid Glass material + command menu + light mode", detail: "A reusable Liquid Glass surface layer in apps/web (globals.css `.liquid-glass` + `.lg-thin/.lg-thick/.lg-vibrant` variants, exposed as the `<Glass>` primitive; `<Card>` is glass BY DEFAULT (with a `glass={false}` opt-out + a `variant`), so EVERY consumer + admin screen renders on glass, Stat/ChartFrame included). Both the consumer app shell AND the admin console carry the ambient field, and the consumer sidebar is collapsible to an icon-rail (persisted). Authentic glass — `@property`-animated tokens (blur/opacity/rim-angle/glow/lift interpolate), backdrop-filter blur+saturate, an inline-SVG visionOS grain, a conic rim light masked to a 1.5px ring, and a layered depth shadow stack — not gradient transparency. A fixed ambient field of slow-drifting accent blobs (lime/blue/violet) sits behind the app shell so the glass has real content to refract. Drives a central ⌘K/Ctrl-K command menu in app-shell.tsx: a floating orb blooms a control-center hub (scrim blurs the app behind) whose tiles mirror the sidebar nav (same NAV_GROUPS + per-item flag gating) and jump screens. LIGHT MODE: a header toggle (lib/use-theme.ts, persisted, sets `<html data-theme>`) flips the brand surface/text tokens — the surface + primary-text constants in lib/ui.tsx resolve through CSS variables, while LINE/ASH/accents stay raw hex because recharts feeds them to SVG presentation attributes (where var() can't resolve); three chart spots that used a themed token were repointed to chart-safe colours. Contrast-audited to WCAG AA+ in both themes via a theme-aware `--accent-text` token (lime on dark, #4c6606 on light). Honours prefers-reduced-motion (and prefers-reduced-transparency → drops blur/grain/field to solid surfaces) and falls back to a solid surface where backdrop-filter is unsupported. WCAG AA is guarded in CI by a pure contrast test in @hybrid/core (contrast.ts + theme/palette.ts THEMES, asserted in theme/palette.test.ts) so a token edit can't silently regress either theme. Nav is sourced from one canonical map in @hybrid/core (nav.ts NAV_ITEMS) shared by the web sidebar + ⌘K hub and the mobile command sheet. Standalone previews: reference/liquid-glass/system.html + before-after.html. KNOWN GAPS: deep inline-styled screens are not yet contrast-tuned for light mode (muted ASH text runs ~2.7:1 on light); theme is applied client-side so a light-mode user sees a brief dark flash on first paint (no SSR cookie yet)." },
  { id: "design-scale", area: "Core", status: "shipped", title: "Shared type & spacing scale (anti-drift)", detail: "A single source of truth for sizing in @hybrid/core (scale.ts): a named type ladder `fs` (nano 10 – micro 11 – caption 12 – body 13 – bodyLg 14 – note 15 – subtitle 16 – title 18 – heading 20 – display 26) and a spacing scale `space` (xxs 4 → huge 40), consumed by BOTH clients. WHY: before this, every fontSize/gap was an inline magic number duplicated across the web (apps/web) and mobile (apps/mobile) trees with no shared definition — exactly how the admin console drifted ~1px smaller than the consumer app (same widths, smaller text → it read miniature). The data showed web and mobile already use the SAME integer ladder (they differed only in WHICH rungs each screen picked), so ONE map serves both — and is the strongest guarantee against re-drift; if a genuine per-platform need appears, scale.ts splits into WEB_FS/MOBILE_FS without touching call sites. WIRING: both lib/ui files re-export `fs`/`space` and point their shared primitives at it (web: Card/Select/Stat/Chip/ChartFrame/tip; mobile: Card/GlassCard/Mono/Kicker/Chip/Button). ADOPTION: all ~21 web + 19 mobile admin section components were migrated off inline numbers onto the tokens — an EXACT-VALUE migration (each fs.<role>/space.<token> equals the literal it replaced), so zero visual change; a handful of bespoke one-off sizes (half-pixel values like 12.5/13.5, and rare hero numbers >26) are intentionally left raw. APP-WIDE: the same exact-value migration was then rolled across the ENTIRE consumer app on both clients (~91 web + ~86 mobile screen/component files — classic + Aurora, app-shell included), so the whole product now sizes off the shared rungs. Still raw by design: responsive ternaries (e.g. `fontSize: isMobile ? 22 : 30`) and half-pixel values — these are conditional/bespoke and frequently use sizes outside the body ladder, so snapping them would change pixels. Guards web+mobile parity (CLAUDE.md): the size vocabulary is now shared, not hand-mirrored." },
  { id: "theme-discipline", area: "Core", status: "shipped", title: "Disciplined themes — Aurora (dark) + Japandi (light)", detail: "Replaced the multi-accent 'AI-slop' look with two disciplined themes, picked from a 10-concept exploration (reference/today-cockpit-design-concepts/). THE DIAGNOSIS: the UI competed FIVE accents at once (lime + blue + violet + amber + red on near-black) — that rainbow, not the lime, read as inconsistent/generated. THE FIX is one accent + a neutral ramp + type/grid hierarchy. TWO THEMES, both in @hybrid/core theme/palette.ts (the single source mirrored by web globals.css [data-theme] + mobile lib/theme.tsx): (1) `dark` = AURORA — a refined neutral charcoal ramp (card #151715, line #242724) with lime as the SINGLE accent and red kept strictly for risk/injury; (2) `light` = JAPANDI — warm oat-paper surfaces (ink #efe9df, card #fcfaf4), clay/sage darkened accentText, calm low contrast. Japandi REPLACES the old cool light theme (the theme set is now exactly these two — labelled 'Aurora' / 'Japandi' in web Preferences + mobile Settings appearance, mobile keeps the System auto-switch). All Japandi text/accent pairs clear WCAG AA on its card (guarded by theme/palette.test.ts). ACCENT DISCIPLINE applied to TODAY + COCKPIT on BOTH clients (apps/{web,mobile}/components/aurora/{today,home,cockpit,today-quick}): every decorative blue/violet/amber chrome (section-header dots/kickers, the AI-coach + upsell accents, the amber streak pill, the violet plan-meta, the check-in heart, the freemium teaser dots) collapses to a single lime accent over neutral ash kickers; the cockpit Section/teaser dropped their per-section `color` prop entirely. DATA COLOURS ARE KEPT (the 'keep data colours' decision): readiness/HPI/risk band colours (the shared semantic.ts role map), the nutrition over-budget red bar, and the reconciled-week sport-vs-strength coding all stay — colour there encodes state, not decoration. Core tests + web/mobile typecheck green (web Prisma-codegen errors are sandbox-only). (LIGHT THEME SINCE EVOLVED: the Japandi palette described here went through Clay & Sage on Oat — see japandi-clay-sage — and is now KYOTO HOUR, washi/pine/vermilion with the picker labelled 'Aurora' / 'Kyoto Hour'; see kyoto-hour-light-theme. The two-theme discipline itself is unchanged.)" },
  { id: "theme-discipline-rollout", area: "Core", status: "shipped", title: "Single-accent discipline rolled out app-wide", detail: "Rolled the single-accent discipline (see theme-discipline) across the whole CONSUMER + COACH + ANALYZE product, in committed batches. RULE: decorative blue/violet/amber chrome → one lime accent + neutral ash kickers; errors → semantic red; KEEP data/state colours (semantic role map, load/RPE + velocity zones, sport-source, macro P/C/F, chart series + axes + legends, rating stars/medals/PR trophy, status states, bio-age delta / weight-rate / volume guidance / MEV-MAV-MRV landmarks / asymmetry / flags). DONE (web + mobile parity): Today, Cockpit, ReconciledWeek (+ mobile twin), live logger, quick-sport; PLAN/TRAIN (plans, sport, builder, competition, train); RECOVERY/HISTORY (checkins, nutrition, longevity, history, calendar); TODAY-EMBEDDED (ai-coach, coach-rail, feed-preview) + Upgrade; COACH (coach, coach-apply, coaches, coach-invite + banners, org, tactical, talent, coach-groups, coach-programs); SOCIAL (feed, leaderboard, social-ui/social-kit, discover); ACCOUNT/NAV (account-settings, app-shell, mobile settings; pill-nav/more springboard already chalk; login/mfa/announcement kept their role/warning semantics); ANALYZE/CHART (performance, trends, volume, exercises, velocity, video, forceplate, analytics, statistics) — chrome only, chart series kept. ADMIN (operator-only) — REVIEWED and found already disciplined: it is a coherent SINGLE-accent surface where AMBER is the deliberate operator identity (shell wordmark, nav-active, section labels) — not a rainbow. Its blue/violet/amber are almost entirely SEMANTIC LEGENDS, kept: the role map (ADMIN=amber / COACH=violet / CLIENT=lime), the verified-coach blue tick, email/agent status maps (scheduled/sending/sent/failed), and recharts series. Only a few purely-decorative metadata chips (a 'joined {date}', a scheduled-time, an email-trigger label) were neutralised to ash. NOTE: admin keeps amber as its operator accent on purpose (signals operator mode, and amber is warm-harmonious in both Aurora and Japandi); unifying admin onto the brand lime/clay accent would be a separate product decision + a large raw-hex codemod, deliberately not done. Net: everything an athlete, coach, or operator sees is now disciplined — consumer/coach = lime (Aurora) / clay (Japandi) single accent, admin = amber operator accent, all with semantic role/status/chart legends preserved." },
  { id: "japandi-identity", area: "Core", status: "shipped", title: "Japandi identity — clay accent + serif display", detail: "Japandi now matches its approved concept (reference/today-cockpit-design-concepts/04-japandi): a warm CLAY/terracotta accent and a Fraunces SERIF display over a clean sans body — not the muted olive-lime first shipped. ACCENT: the `lime` token (which drives every accent fill) becomes clay #a5573c in the light theme only — web `[data-theme=light]` overrides --color-lime/--lime-text/--accent-text, core THEMES.light.accentText.lime = #a5573c, mobile paletteFor() sets palette.lime = #a5573c. #a5573c is the concept's #b06a4f darkened just enough to clear WCAG AA (4.9 as a fill under light text, 5.0 as text on the cream card); on-accent text flips to light paper (--on-accent / mobile onAccent) so labels read on the clay. Aurora (dark) is unchanged (raw bright lime, dark on-accent). SERIF (web): Fraunces is loaded; a new --font-heading var (Archivo in Aurora, Fraunces in Japandi) is applied to the hero headings on Today + Cockpit (greeting, plan/session titles, AI-coach title, command-center, HPI + Stat numbers, nutrition kcal, reconciled-week values); body/prose stays on the sans --font-display and labels stay mono — the concept's serif-display/sans-body split. AMBIENT FIELD was already retinted warm for Japandi. Contrast guarded by palette.test.ts (658 green). See japandi-serif-mobile for the one remaining gap. (SUPERSEDED Jul 2026 by kyoto-hour-light-theme: the light accent is now PINE #44584c — clay is retired — and the light display face is Shippori Mincho, not Fraunces. The per-theme --font-heading / accent-fill ARCHITECTURE built here still carries the new values.)" },
  { id: "japandi-serif-mobile", area: "Mobile", status: "shipped", title: "Japandi serif display on mobile (Fraunces)", detail: "Mobile now matches web's Japandi serif character. @expo-google-fonts/fraunces added (installed with --ignore-scripts to skip the blocked @prisma/engines postinstall); Fraunces_500Medium/600SemiBold/700Bold loaded in apps/mobile/app/_layout.tsx useFonts(); F.serifMed/serifSemi/serifBold added to apps/mobile/lib/ui.tsx with a `serifIf(scheme, archivo)` helper (returns Fraunces in light/Japandi, the given Archivo weight in dark/Aurora — the mobile twin of web's --font-heading). Applied to: the shared AHeading primitive (so EVERY screen title goes serif in Japandi), and the hero headings/numbers on Today (greeting, plan/session/AI-coach titles, reconciled-week Metric values, nutrition kcal) + Cockpit (goal, blocks, HPI score, Stat values). Body stays Archivo sans, labels stay JetBrains mono — the concept's serif-display/sans-body split. Verified: mobile typecheck clean + `expo export --platform ios` bundles green (Fraunces module resolves + Metro bundles the weights). On-DEVICE visual still wants an EAS build to confirm rendering (no simulator in this sandbox), same bar as the rest of the mobile Aurora kit. (SUPERSEDED Jul 2026 by kyoto-hour-light-theme: serifIf() now returns the Shippori Mincho cuts in light and @expo-google-fonts/fraunces was replaced by @expo-google-fonts/shippori-mincho — the serifIf/useFonts WIRING described here is unchanged, only the face swapped.)" },
  { id: "liquid-glass-mobile", area: "Mobile", status: "shipped", title: "Liquid Glass on mobile (expo-blur)", detail: "The web Liquid Glass material ported to React Native (apps/mobile/components/liquid-glass.tsx): a `GlassCard` on an expo-blur BlurView base with a brand tint film, a top rim-highlight, a soft border and a depth shadow (grain is omitted — no perf-free RN noise primitive); a frosted `GlassTabBarBackground` behind the bottom tab bar; and a central `CommandMenu` — a floating glass orb (FAB) that blooms a blurred control-center sheet of nav tiles (the mobile analog of the web ⌘K hub), animated with core Animated springs (no Reanimated, so no extra native babel config). Wired globally in app/(tabs)/_layout.tsx. The `GlassCard` primitive now lives in lib/ui (alongside `Card`), and `Card` renders on GlassCard BY DEFAULT (with a `glass={false}` solid opt-out), so EVERY mobile screen sits on glass — parity with web where `<Card>` is glass by default. The web ambient drifting-blob field is ported too: a `GlassField` (lib/ui) of slow-drifting lime/blue/violet blobs (faked with stacked low-opacity concentric circles — no SVG/gradient dep — and core Animated loops) mounts once behind every `Screen` so the glass has real content to refract, matching the web `.lg-field`. LIGHT/DARK: a mobile theme system (lib/theme.tsx — ThemeProvider + useTheme, palette from the shared @hybrid/core THEMES) follows the OS appearance by default with a System/Light/Dark override in Settings; the shared primitives (lib/ui Screen/Card/Mono/Kicker/Chip/Button), the glass surfaces (GlassCard/tab bar/command sheet) and the status bar all follow it. The command sheet is built from the shared nav map (nav.ts). Shares the @hybrid/core palette so it stays in lockstep with web. Every screen follows the theme: surfaces/text via a per-component palette shadow and accent TEXT wrapped in txt() so it stays WCAG AA on light (parity with web). iOS bundle export verified; on-DEVICE rendering of the native blur + the themed screens still needs an EAS build to verify visually (blocked on the Apple Developer account + Expo token — see mobile-preview)." },

  // ---- Mobile ----
  { id: "mobile-app", area: "Mobile", status: "shipped", title: "Native app (code)", detail: "Expo app: Supabase auth + a funnel-first tab navigator (Today / Train / History / More) on the same core and the same /api backend. The dense screens (Plans, Sport, Velocity, Coach) plus the pushed consumer/coaching routes — Nutrition, Check-in, Calendar, Progress photos (camera/library capture), Onboarding — now live behind the More hub so the gym path stays uncluttered. The Today home (Fitness GPS) leads with a one-tap Start and the Accountability/Future-Self/Twin cards + 'Assigned by your coach' workouts. iOS bundle verified (incl. the expo-image-picker native module); on-device run needs an EAS build (see mobile-preview). BOOTS WITHOUT A KEY: when EXPO_PUBLIC_SUPABASE_ANON_KEY is unset (e.g. a fresh Simulator run), lib/supabase.ts hands createClient a harmless placeholder instead of an empty string so the client can't throw 'supabaseKey is required.' at startup — the app opens logged-out (isSupabaseConfigured() stays false, gating every auth/storage call) and the login screen shows a 'set the key' hint rather than crashing." },
  { id: "train-funnel", area: "Mobile", status: "shipped", title: "Train funnel — start → log → finish → share → analyze", detail: "The deliberate path for the everyday athlete: ease in the gym, depth at home. (1) START is one tap — a hero button on Today and a Train launcher (empty / AI-prescribed / repeat-last) both open a focused live-workout screen. (2) LOG is frictionless: a fresh workout opens with a 5→1→GO get-ready COUNT-IN overlay (the elapsed clock only starts at GO, so the time reflects real training, not setup; skipped when resuming an in-progress draft), then a running elapsed clock, add exercises from the MOVEMENTS map or free-type, big set rows (kg/reps/RPE) with previous-set carry-over, a ✓ to bank a set, and an auto rest timer — no menus, big tap targets. A set row can be SWIPED LEFT to delete one added by accident (built on Animated + PanResponder — only claims horizontal drags so inputs/scroll still work; long-pressing the set number also deletes). A PAUSE/HOLD button next to Finish freezes the elapsed clock and any running rest (shifting both forward on resume so neither jumps); the header shows a PAUSED state. The SCREEN STAYS AWAKE while logging (expo-keep-awake — no dimming mid-set), exercises can be REORDERED in place (↑/↓ on each card, matching the web builder), and every strength exercise shows a 'LAST TIME' reference (the most recent prior session's sets for that lift via the shared lastStrengthByLift helper, computed once per session — not re-sorted on the per-second timer re-render) so progressive overload has a target to beat. CARDIO is its own exercise kind (separate from interval CONDITIONING): logs distance (km) + minutes with a live derived pace (min/km via the shared pacePerKm), while conditioning logs minutes; neither asks for RPE (strength-only); the picker classifies a typed/library move via inferBlockKind (catalog + keyword). A set can be tapped to a DROP SET (lighter no-rest continuation, or '+ drop set') and a strength exercise joined into a SUPERSET with the exercise BELOW it — the '⛓ superset' control sits on the UPPER card so even the FIRST exercise can start a superset (labelled A1/A2/A3… via the shared supersetLabels) — both ride the same SessionBlock fields the web logger writes (StrengthSet.drop / StrengthBlock.group). A 'What's RPE?' sheet shows the shared RPE_SCALE + reps-in-reserve explainer so a beginner can self-rate. (3) FINISH saves the real Session via /api/sessions (or the device, in guest mode — see guest-first-workout) and shows a completion summary (duration, sets, tonnage, today's est-1RM bests). A 🏆 PR celebration fires the moment a lift beats its prior best (see pr-detection). (4) SHARE renders a branded PNG card to the native share sheet (see share-card). (5) ANALYZE: the summary funnels into History → a per-session detail screen (see session-detail) for the at-home deep dive (and the web goes deeper still). All flow copy is localized EN/PL/DE. app/workout.tsx + the rebuilt Train tab; the old form-heavy Log tab is replaced." },
  { id: "guest-first-workout", area: "Mobile", status: "shipped", title: "Guest mode — train before you sign up", detail: "Removes the cold-start wall: a brand-new user lands on a welcome screen and can START THEIR FIRST WORKOUT with no account. Guest sessions are persisted on-device (AsyncStorage, lib/guest.ts) and the full live-workout + summary + share flow works offline. The completion screen then offers 'Save & track progress → create a free account'; on sign-in, flushGuestSessions() pushes every locally-stored workout up to /api/sessions so nothing is lost and it appears in History + on the web. Unauthed routing now goes welcome → (guest workout | login?mode=signup) instead of a hard login gate." },
  { id: "share-card", area: "Mobile", status: "shipped", title: "Shareable workout card (image)", detail: "The post-workout summary and the session-detail screen render a branded HYBRID stat card (title, minutes/sets/tonnage, est-1RM bests with 🏆 PR markers) and capture that exact view to a PNG via react-native-view-shot, then open the native share sheet through expo-sharing — an image made for social. A reusable lib/share.tsx (WorkoutShareCard + shareWorkout) backs both. Degrades gracefully to a formatted text share (RN Share) when image capture or the share sheet is unavailable. Capture/share are JS-driven but the underlying modules are native, so on-device behavior is verified by an EAS build (see mobile-preview). WEB PARITY + a 9:16 STORY card now ship too — see empty-log-share-stats." },
  { id: "empty-log-share-stats", area: "Core", status: "shipped", title: "Empty-log section — live in-session stats + 9:16 story share (web + mobile)", detail: "The 'log a workout from scratch' loop is now a first-class, parity-matched section on BOTH clients with live stats and social share. ENTRY: the center bottom-nav button already opens an EMPTY live session (mobile /workout?source=empty; web app-shell screen='log' → AuroraLogger with no seeded blocks); added an explicit 'Empty log' tile to the mobile More hub (app/(tabs)/more.tsx) to match the web 'More' sheet, which already lists the casual 'Log session' nav item. LIVE STATS: a new pure helper @hybrid/core live-stats.ts — liveSessionStats(blocks, prior) returns running exercises / logged working-sets / tonnage (sessionVolume) / strength + cardio PR counts (newPrsInSession/newCardioPrsInSession), counting a set only once reps/load is typed; pure + 5 unit tests. It drives a live SCOREBOARD strip that appears the moment the first set lands — web components/aurora/logger.tsx and mobile app/workout.tsx render the same exercises/sets/volume cells plus a 🏆 PR badge, so the in-gym screen shows the session adding up in real time (same numbers the finish summary uses). SHARE: web previously had NO workout share at all (parity gap) — apps/web/lib/workout-share.ts now draws a branded 9:16 (1080×1920) Instagram-story PNG on a <canvas> (no new dependency; wordmark + lime glow, minutes/sets/volume, today's est-1RM bests with PR markers) and hands it to the Web Share API (navigator.share with files), degrading to a PNG download then a text/clipboard share; the web finish screen gains a 'Share to story' CTA (glowing on a PR/first-ever). Mobile adds a tall WorkoutStoryCard (9:16) to lib/share.tsx captured from an off-screen render via the existing react-native-view-shot path, with a 'Share to story' button on the summary alongside the original square card. All copy localized EN/PL/DE (live.*, summary.shareStory, emptyLog.*, w.train.logger.live*/share*). Web canvas share verified by typecheck/build; mobile capture is native, verified on an EAS build (see mobile-preview)." },
  { id: "session-detail", area: "Mobile", status: "shipped", title: "Session detail — the 'analyze at home' screen", detail: "The explicit counterpart to the in-gym ease: tap any History row to open app/session/[id].tsx — duration, tonnage and set count up top, a 🏆 PR banner (pr-detection vs prior history), a muscle-focus card (volumeByMuscle bars — what the session actually trained), then a full per-exercise breakdown (every set's kg×reps×RPE×velocity and the block's est-1RM, PR-badged) with a dependency-free e1RM trend sparkline per lift (e1rmSeries over the whole history) AND a pace-trend sparkline per cardio move (paceSeries; faster = taller, delta shown as time saved/lost per km), plus the branded share card so an old win can be re-shared. History rows now show a PR chip and a 'tap for the full breakdown' hint. Conditioning blocks read back their full interval via the shared core conditioningSummary/blockSummary helpers (format – rounds×work/rest s – minutes – RPE) — one formatter the web History + mobile History/detail all use so they can't drift. Localized EN/PL/DE." },
  { id: "exercise-picker", area: "Mobile", status: "shipped", title: "Fast exercise picker (search + your lifts)", detail: "Adding an exercise mid-workout is now one tap: the picker opens with a search box (autofocused) and a 'Your lifts' row of the athlete's own most-recently-used movements (exerciseHistory, incl. custom names they've typed before), above the movement Library. Typing filters both lists live and offers '+ \"<what you typed>\"' to add a brand-new exercise, preserving strength/conditioning kind from history. Localized EN/PL/DE." },
  { id: "mobile-exercise-library", area: "Mobile", status: "shipped", title: "Mobile picker consumes the admin exercise library (+ alias dedup + muscle-group grouping)", detail: "PARITY with web's cms-exercise-library — the admin-authored custom catalog is now pickable on the phone. A mobile useExercises() twin (lib/queries.ts, TanStack Query + Bearer fetch of /api/exercises via lib/api.ts fetchCustomExercises) folds the library over the built-in MOVEMENTS with mergeMovements and returns the SAME shape web does: movements (resolution map, alias keys kept), catalog (pickable names from catalogNames), aliases (aliasNames — superseded lifts hidden), and categoryByName (categoriesByName). Both mobile pickers — the live logger (app/workout.tsx) and the AURORA routine builder (components/aurora/builder.tsx) — now call exercisesByCategory(MOVEMENTS, catalog, categoryByName), filter aliased names, and render muscle-group section headers, so a custom 'Barbell Bench Press' (aliasing built-in 'Bench Press') shows once, under its 'Chest' heading, identically on web + mobile. Degrades to the built-ins alone when signed-out / the API is unavailable. Verified: mobile typecheck + iOS bundle export; live rows need the deployed API + a seeded table (reference/sql-exercise-seed.sql)." },
  { id: "rest-haptics", area: "Mobile", status: "shipped", title: "Rest COUNTDOWN + set haptics + saved rest", detail: "In-gym ergonomics on the live workout: banking a set (tap ✓) fires a light haptic (expo-haptics) and starts a rest COUNTDOWN — it targets a default 90s (or a tapped 60/90/120/180s preset) and ticks DOWN to zero showing the time LEFT, then flips to a lime 'Rest done – +mm:ss' over-rest readout with a success-buzz the instant the target is hit — an eyes-off cue so you can rest heads-down between sets (tapping the active preset clears the target back to a plain count-up stopwatch). A prominent '■ Stop' button ends the rest manually at any time (e.g. when you're choosing the next exercise). BACKGROUND ALERT: a local notification (expo-notifications) is scheduled for when the countdown ends and fires with sound even if the app is pocketed / the phone is locked (permission requested best-effort; kept in sync as the rest starts/changes/stops, cancelled on Stop) — so the cue lands whether the phone's in your hand or not. SAVED AS DATA: the rest taken before each set (the live gap between banking the previous set and this one) is recorded on StrengthSet.rest (seconds) and surfaced per-set in the session-detail breakdown — an optional field, so web-editor / imported sessions are unaffected. NO-REST-AWARE: banking a set that flows straight into a DROP SET or the next exercise of a SUPERSET does NOT start the rest clock (you keep moving) — the rest only kicks in after the last drop / the last superset exercise, matching how the structures are actually trained. A one-time 'how logging works' coach tip (what ✓ does, the rest countdown + presets, how to superset) shows on the live screen until the athlete banks their first-ever set or dismisses it (persisted in AsyncStorage). Haptics no-op gracefully where unsupported; the device feedback itself is verified by an EAS build (see mobile-preview)." },
  { id: "weekly-recap-ui", area: "Mobile", status: "shipped", title: "'Your week' recap + share (web + mobile)", detail: "The weekly-recap engine surfaced on both Today screens: a 'Your week' card (sessions, tonnage, sets, active days, top muscle, PRs, and the delta vs last week). On mobile it's a branded card captured to a PNG via the shared share infra — 'Share your week' to social — with a nudge when the week's still empty. On web it's a span-2 panel on the consumer home. Mobile copy localized EN/PL/DE." },
  { id: "coach-week-view", area: "Web", status: "shipped", title: "Coach sees the athlete's week", detail: "The same weeklyRecap an athlete sees on their own Today now headlines the coach's client-detail view (web Coach screen + mobile Coach tab): sessions, tonnage, sets, active days, top muscle, the week's PRs, and the delta vs last week — computed from the client's real sessions the coach already reads (CoachLink-gated). One source of truth for both sides of the relationship, so a check-in starts from the same numbers." },
  { id: "workout-resume", area: "Mobile", status: "shipped", title: "Resume an interrupted workout", detail: "The live workout auto-saves an in-progress draft to the device (lib/draft.ts, debounced) as you log, so a crash, a dead battery or an accidental back-swipe never costs the session. Today's hero and the Train launcher detect the draft and offer Resume (with an exercise count + 'in progress'); the launcher also exposes Start-fresh (drops the draft) and Discard. The draft is cleared on finish. Plain AsyncStorage — no backend needed." },
  { id: "workout-minimize", area: "Core", status: "shipped", title: "Minimize a live workout into the nav accessory", detail: "The live logger had two ways out and BOTH ended the session: 'Cancel' — which actually just called router.back() and discarded nothing, a mislabel whose string was even borrowed from the coach namespace (w.teams.coach.cancel) — and 'Finish'. Nothing said 'put this away and carry on', even though the accessory strip above the nav pill (see nav-native-tabs) was already built and already watching the persisted draft. The header now reads MINIMIZE / clock / ⋯ + Finish on BOTH clients. Minimize is a chevron-down glyph (already in the kit, so no new icon was needed) pointing at where the session goes: mobile app/workout.tsx leaves the route and the session reappears in NativeTabs.BottomAccessory; web components/aurora/logger.tsx calls a new onMinimize prop that app-shell routes to Today, where pill-nav's SessionAccessory picks the localStorage draft up. Nothing is lost either way — the draft is persisted on every change. DISCARD, the one irreversible exit, is deliberately NOT a peer: it is a row inside the ⋯ menu, behind a confirm (mobile useConfirm's promise-based sheet; web a matching Sheet with Cancel first and the destructive action second, so the button under a resting thumb is never the irreversible one). This was the chosen shape out of four studied: two adjacent unlabelled glyphs, one reversible and one not, in the corner a thumb rests on is the arrangement that loses sessions — and ✕ was rejected outright for discard because on iOS it means 'close this' (dismiss, nothing lost), which is exactly what the chevron beside it would do; ✕ already means close-this-card in three places in the same logger. Both loggers latch a `discarded` ref that gates the debounced draft save, so a write scheduled in the 500ms before a discard cannot land AFTER clearDraft() and resurrect the session the athlete just confirmed away. Localized EN/PL/DE (workout.minimize / moreOptions / discardSession / discardTitle / discardBody, reusing train.discard for the confirm button). Verified here: both typechecks, the web build, the iOS bundle export, and the 2025 core tests — including the web↔mobile copy-parity guard and the vocabulary rule that calls the object a session." },
  { id: "workout-minimize-lossless", area: "Core", status: "planned", title: "Minimize restores the POSITION, not just the session", detail: "What shipped in workout-minimize is content-lossless but not position-lossless: the draft restores the exercises and the clock, not the focused set, the scroll offset or an open keypad — because the live state lives INSIDE the logger screen. That is also why the mobile workout route still sets gestureEnabled:false, whose comment records the reason exactly: swiping out mid-set loses the live session's context. Hoisting the running session into a module-level store read through useSyncExternalStore — the pattern components/aurora/session-accessory.tsx already uses for its own draft and clock, for the same reason: two surfaces must read one truth without drifting — would make the route a VIEW of the session rather than its owner, and restore would return the athlete to set 2 of 5 with the field still focused. It also unblocks three things that are dishonest without it: drag-down-to-minimize (the back-swipe can only be handed back once leaving is provably free), a Log-set control in the accessory strip itself so a straight-set block can be finished without restoring, and rest-driven auto-minimize. Refactor-shaped, with no visible feature of its own, and it touches the most load-bearing screen in the app." },
  { id: "offline-sync", area: "Mobile", status: "shipped", title: "Never-lose-a-workout offline sync", detail: "Finishing a workout while offline (or on a server hiccup) no longer fails: the session is stashed on the device using the same store guests use, the summary shows a 'saved on this device — will sync' note, and the SessionProvider flushes the backlog to /api/sessions on the next sign-in AND every time the app returns to foreground (likely back online) via AppState. So the gym's dead signal can't eat a PR." },
  { id: "mobile-ci", area: "Mobile", status: "shipped", title: "Mobile CI — typecheck + iOS bundle export", detail: "CI (.github/workflows/ci.yml) runs `pnpm typecheck` across core/web/mobile AND now exports the iOS bundle (`pnpm --filter @hybrid/mobile export:ios` → `expo export --platform ios`) on every PR/push to main. The export proves the Expo app actually bundles — Metro resolution, native-module + asset registration — which a type-only check can't see, and needs no simulator (the same headless check called out in CLAUDE.md). This is the build gate the web-only Vercel deploy doesn't cover." },
  { id: "ios-simulator-guide", area: "Web", status: "shipped", title: "iOS Simulator runbook (admin)", detail: "Admin → Governance → Guidance → the 'simulator' guide (switcher): a beginner-friendly, explain-it-like-I'm-a-kid step-by-step guide for opening the managed-Expo mobile app on a pretend iPhone (Apple's iOS Simulator). CONSOLIDATED: this was a standalone 'iOS simulator' Governance tab; it's now documentation-as-DATA in @hybrid/core (guidance.ts SIMULATOR_GUIDE) rendered by the shared Guidance screen (apps/web/components/admin/guidance.tsx) alongside the deploy + accounts guides — one operator-runbook hub, single source of truth, mobile-admin-ready. The GuideBlock model gained a copy-able `cmd` block (the command boxes keep their Copy button) and a `matrix` cheat-sheet block to carry this content faithfully. Opens with a plain-words glossary (Mac, Terminal, 'type a command', Xcode, Simulator, the app code) so no jargon is unexplained, then ONE continuous numbered walkthrough (steps 1–8, each box copy-pasteable with a Copy button) that goes from nothing to the app running via the quick Expo Go path — get Xcode from the App Store, download an iPhone runtime in Xcode → Settings → Components, install node + pnpm, `git clone` + `cd` + `pnpm install` (each line explained in kid terms), install Watchman, `pnpm --filter @hybrid/mobile dev`, press `i` to pop up the pretend phone, then tap around — ending in a friendly ✓ Done note (repeat only steps 6–7 thereafter; an admin supplies EXPO_PUBLIC_SUPABASE_ANON_KEY to enable sign-in). IMPORTANT: Expo Go now throws a red 'Native module is null, cannot access legacy storage' (AsyncStorage) screen for this app because it uses native modules Expo Go can't load, so the native dev build (steps 9–10: CocoaPods + `npx expo run:ios`) is flagged as the RECOMMENDED / most-reliable path — it fixes that red screen and is what makes login/camera/save-photo actually work. A 'cloud robot' EAS build (`eas build --profile preview --platform ios`) is the third option when local building is too slow. Plus a 'which one do I pick' cheat sheet and a plain-language 'if something looks wrong' section whose top entries are the real snags from a live walkthrough: the AsyncStorage red screen (→ run the dev build), a 'Verifying iOS … simruntime' that looks frozen for 5–20 min (one-time, be patient), harmless CHHapticPattern / 'CA Event app launch measurement' log noise on the Simulator (safe to ignore), a `git pull` blocked by local changes (→ `git checkout -- <file>` then pull), and running `pnpm install` from the wrong folder (must be inside `hybrid/`). Also has an 'After we change the app — get the latest & reload' card: leave Expo running, `git pull` in a new tab, reload with Cmd+R / `r` (Fast Refresh often auto-updates), and when a full restart vs reload is needed (new deps / native code) — plus that website-only changes don't touch the Simulator app, and how to check your branch (`git branch --show-current` / `git status`). Troubleshooting also covers the zsh '#'-comment trap (a note pasted after a command runs as args → ERR_PNPM_ADDING_TO_ROOT) and the reload-key mixup (Cmd+T = new Terminal tab, NOT reload; use Cmd+R in the Simulator or `r` in Expo). Reference docs only; the sandbox can't boot a Simulator (no macOS, Supabase host blocked) so these run on the user's Mac." },
  { id: "mobile-store-assets", area: "Mobile", status: "shipped", title: "App Store submission assets", detail: "The standalone HYBRID app is now store-ready (no Claude branding anywhere — it ships as `app.hybrid.mobile`). Branded icon set generated on-brand (lime H on ink #0c0d0c) at apps/mobile/assets/ — icon.png (1024² flattened, no alpha per Apple's rule), Android adaptiveIcon foreground, expo-splash-screen image, and a web favicon — all wired into app.json. App version bumped 0.0.0 → 1.0.0 with ios.buildNumber 1. The remaining gap to a live submission is purely credentials (see mobile-preview), not the app." },
  { id: "mobile-preview", area: "Mobile", status: "shipped", title: "On-device build (internal distribution)", detail: "ACHIEVED: the app now builds via EAS and installs on a REAL iPhone through an internal-distribution build — `npx eas build --platform ios --profile device` (apps/mobile/eas.json `device` profile = internal, simulator:false), installed over the build's QR / expo.dev → Builds. Apple is authenticated with an App Store Connect API KEY that has the ADMIN role (export EXPO_ASC_API_KEY_PATH / EXPO_ASC_KEY_ID / EXPO_ASC_ISSUER_ID — Admin is required, not App Manager, so EAS can manage certs/profiles, register the device, and sync capabilities) because the Apple ID's only second factor is a hardware security key, which EAS/Fastlane's interactive login can't complete; the public Supabase anon key is defaulted in the app so it signs in without extra EAS env. The Apple Developer + Expo accounts now exist (Apple team T4WC9M8Y3S). The full runbook + the stale-checkout and security-key traps are documented in the admin Guidance deploy guide (sandbox-build section). REMAINING for a public launch: a TestFlight / App Store submission (`eas build --profile production` + `eas submit` + Apple review) — tracked in the deploy guide's status section. BUILD METHOD (chosen): NO-CLONE CLOUD — the user wants to keep the sud-italia experience (no local clone, no Mac), so the documented primary path is a cloud EAS build triggered from the browser: .github/workflows/mobile-release.yml runs `eas build --platform ios --profile production --auto-submit` on an ubuntu runner (the compile + signing happen on Expo's CLOUD builders; the runner just kicks it off and waits), invoked via GitHub → Actions → Run workflow or a `mobile-v*` tag. Needs five repo secrets: EXPO_TOKEN, EXPO_PUBLIC_SUPABASE_ANON_KEY, APPLE_ASC_API_KEY_P8 (the raw .p8 file contents pasted as-is — written to apps/mobile/asc-key.p8 at runtime via printf; *.p8 is git-ignored. Earlier base64 variant was dropped because pasting the raw PEM into a base64 secret failed `base64 --decode` with 'invalid input'), APPLE_ASC_KEY_ID, APPLE_ASC_ISSUER_ID (injected into eas.json submit.production.ios at runtime via jq so the IDs stay out of git). ONE-TIME CREDENTIAL BOOTSTRAP — NOW DONE (2026-06-26): a `--non-interactive` CI build REUSES iOS signing credentials but will NOT create them the first time (fails 'Distribution Certificate is not validated for non-interactive builds / Credentials are not set up' — eas-cli #3202). The bootstrap was completed live by running interactively once on the user's Mac (`npx eas build --profile production --platform ios` with EXPO_ASC_API_KEY_PATH/KEY_ID/ISSUER_ID + EXPO_APPLE_TEAM_ID=T4WC9M8Y3S exported so Apple auth goes via the ASC key, not the hardware-key-2FA-blocked interactive login). Result stored on EAS: Apple Distribution Certificate (serial 25DD967C9657247A2AF99EE677FA33A, exp 2027-06-16) + App Store Provisioning Profile (portal id G6SM2S47CK, active) for com.hybriddomain.xyz. So from now on the no-clone GitHub Actions button reuses these hands-free. KEY ID is ZRWGCS2PUS (the .p8 file is AuthKey_ZRWGCS2PUS.p8; issuer 654187d8-9306-4753-97f6-c33797648364) — NOTE the RQTCHVF25S id in older notes was a DIFFERENT/old key, and the GitHub secret APPLE_ASC_KEY_ID + APPLE_ASC_API_KEY_P8 must be updated to the ZRWGCS2PUS key or the automated build 401s. REMAINING blocker to an actual TestFlight binary: the account's monthly FREE EAS Build quota is exhausted (resets ~2026-07-01) — so either wait for the reset then click the GitHub button, upgrade the EAS plan, or do a fully-local build. LOCAL BUILD STATUS (tried live on the user's M1 Max, Xcode 26.5 / CocoaPods 1.16.2 / Fastlane installed): `eas build --local` now runs all the way through pnpm install + expo-doctor + pod-equivalent and into code-signing, but fails at the PREPARE_CREDENTIALS phase with 'Distribution certificate with fingerprint … hasn't been imported successfully' — a known flaky bug in eas-cli-local-build-plugin's throwaway-keychain import on recent macOS, NOT a project/credential problem (creds are valid; the cloud build will use the same ones fine). So local-via-eas is a rabbit hole; the reliable local alternative is `pnpm prebuild:ios` then Xcode Archive → Distribute → TestFlight (Xcode manages the keychain natively). Net: the clean path to the first TestFlight binary is the no-clone cloud GitHub button once the free quota resets (~Jul 1), or an EAS plan upgrade to build immediately. SHIPPED (2026-06-26): a real TestFlight build IS now live — uploaded via local Xcode Archive → Distribute → TestFlight (1.0.0, build 2, com.hybriddomain.xyz), installed and running on device. PIPELINE PIVOT (user requirement: NO Expo build service / 'nothing to do with dev expo'; and they ship sud-italia via GitHub, not Codemagic-the-service): .github/workflows/mobile-release.yml builds on a GitHub macOS runner using codemagic-cli-tools (open-source Apple-signing helper, NOT codemagic.io) + `expo prebuild` as local code-gen only (no Expo account/token). Signing is AUTOMATIC — `app-store-connect fetch-signing-files --create --certificate-key` creates/reuses the Apple Distribution cert + App Store profile from the ASC API key, so NO Keychain export and NO .p12 (the earlier Fastlane/.p12 approach was dropped because it forced manual cert export). Sets an always-increasing CFBundleVersion via agvtool — whole SECONDS since 2024-01-01 UTC (~78M; monotonic with the clock, always above the last upload, no API call or stored state, so a re-run/retry can't reuse a build number), then uploads via `app-store-connect publish --testflight`. (The earlier `get-latest-testflight-build-number` query was returning empty → `$((0+1))` → build '1' → a repeated 409 'bundle version must be higher than 2'; the self-contained timestamp removes that dependency. Matches apps/mobile/app.config.js, which covers the local Xcode-archive path the same way.) Free + UNLIMITED (public repo, no EAS quota). Secrets: APPLE_ASC_API_KEY_P8 / APPLE_ASC_KEY_ID (ZRWGCS2PUS) / APPLE_ASC_ISSUER_ID / EXPO_PUBLIC_SUPABASE_ANON_KEY + APPLE_CERT_PRIVATE_KEY (a one-time `openssl genrsa 2048` key — no Keychain, no .p12). EXPO_TOKEN unused. CAVEAT: first run may hit Apple's 2-Distribution-cert cap (EAS + Xcode certs already exist) → revoke the old EAS 'iPhone Distribution' cert at developer.apple.com once, then re-run. The fundamental truth conveyed to the user: ANY CI iOS signing needs the signing key available to the runner once (Apple's design) — sud-italia had this set up once and forgotten; this is the lightest form of it. Also: the OTA/eas-update config still points at Expo's u.expo.dev servers — if the user wants ZERO Expo at runtime too, drop expo-updates and rely on the (free, unlimited) CI build for every change. Equivalent no-clone alternative noted in the runbook: the EAS GitHub integration (connect repo at expo.dev, click Build on the dashboard). TRADE-OFF: a cloud build consumes the EAS Build free-tier quota (that's the price of no Mac) — but it's only run for real native builds/releases; JS changes ship free via OTA (eas-update), and the monthly quota resets. OPTIONAL local/Xcode path (free + unlimited, but needs a clone + a Mac) stays documented as a secondary option: CNG → `pnpm prebuild:ios` → `pnpm run:ios` or Xcode Archive, or `pnpm build:local` for a signed .ipa. Convenience scripts (prebuild:ios / run:ios / build:local) + EXPO_PUBLIC_SUPABASE_ANON_KEY in .env.example support it." },
  { id: "eas-update", area: "Mobile", status: "shipped", title: "OTA updates (EAS Update) — ship JS without a new build", detail: "Wires up over-the-air updates so the common case (JS/TS changes: screens, logic, styling) ships to an already-installed build for FREE instead of burning an EAS Build credit — the fix for the 'ran out of free builds' wall, since a TestFlight build and a dev build consume the SAME cloud-build quota and only a real build can carry NATIVE changes. Done in code: expo-updates (~56.0.19) added; app.json gains updates.url = https://u.expo.dev/<projectId> with runtimeVersion.policy='fingerprint' (the fingerprint auto-invalidates OTA when native deps change, so a JS update is never delivered to an incompatible binary — safer than 'appVersion' given the native modules react-native-iap / @expo/ui / expo-notifications); eas.json build profiles each carry a `channel` (development/preview/production; the `device` on-device test build and `production`/TestFlight both track the `production` channel). Mobile typecheck + iOS bundle export both green. OPERATE: after a JS change, `cd apps/mobile && pnpm update --message \"…\"` (= `eas update --branch production`) pushes the OTA; the installed app picks it up on next launch. You still do a full `eas build` only when native code/deps change. Web parity: web already ships every change instantly via the Vercel auto-deploy on main, so OTA is the mobile equivalent — no web work needed. NOTE: publishing an update requires Expo auth (interactive `eas login`, or an EXPO_TOKEN robot secret for CI) — the config is committed and inert until then; a one-time CI workflow to auto-publish OTA on push to main is an easy follow-up once EXPO_TOKEN is set as a repo secret." },
  { id: "push-notifications", area: "Mobile", status: "blocked", title: "Push notifications + reminders", detail: "The retention loop's delivery layer: smart-timed session/check-in/streak reminders and re-engagement nudges (the Accountability Engine already decides WHO to nudge and WITH WHAT — see accountability-engine). The scheduling/targeting logic can be built; what's missing is the device-delivery channel. NOTE: the expo-notifications config plugin was temporarily removed from app.json so the iOS dev/ad-hoc build could ship for IAP testing — because the Apple account authenticates via an App Store Connect API key only (hardware-key 2FA blocks cookie/password login), EAS can't sync the Push Notifications capability/aps-environment entitlement into the provisioning profile. Re-add the plugin once push credentials are provisioned (a profile that includes the Push Notifications capability + aps-environment).", blockedBy: "Expo push setup (EAS project + push credentials / APNs+FCM keys) and stored device tokens; an EAS build (see mobile-preview) is a prerequisite. Also: provision a profile WITH the Push Notifications capability — under API-key-only Apple auth EAS skips capability syncing, so this needs either cookie/password auth (blocked by hardware-key 2FA) or a manually-created profile, then re-add the expo-notifications plugin to app.json." },

  // ---- Auth ----
  { id: "account-reset", area: "Backend", status: "shipped", title: "Reset account (wipe my data)", detail: "A Settings → Danger zone control that erases ALL of the signed-in user's data while keeping their login: POST /api/account/reset (confirm token required) now delegates to the SHARED wipeUserData() helper (apps/web/lib/account-wipe.ts) so it covers EVERY user-owned table — including the private-tab tables (BodyMetric, JournalEntry, HiddenHighlight, HighlightOrder), PlanDayOverride/OnboardingState, and the full social graph (SocialProfile, Post, Kudos, Comment, Follow, Block, CoachProfile, ProgramEnrollment, CoachReview) that the old inline list SILENTLY LEFT BEHIND — plus sessions/macrocycles/biometrics/signals/check-ins/RTP/videos/events/risk/talent/connections/memberships/templates/assignments/coach links+notes, strictly user-scoped. Progress-photo Storage is cleared via the service-role client (works for web cookie AND mobile Bearer). UI on web (Settings screen, type-RESET to arm) and mobile (More → Settings; also clears on-device guest/draft caches). Localized EN/PL/DE." },
  { id: "account-self-delete", area: "Backend", status: "shipped", title: "Delete my account (self-serve — App Store 5.1.1(v) + GDPR)", detail: "Apple requires an in-app way to DELETE (not just deactivate) an account for any app that supports sign-up, and GDPR Art. 17 requires self-serve erasure — previously HYBRID had only 'reset' (which keeps the login) and admin-only deletion, a hard App Store blocker. Now DELETE /api/account (auth-scoped, rate-limited, body { confirm: 'DELETE' }) hard-deletes ALL of the user's data via the shared wipeUserData() helper (+ email footprint, keeping the EmailSuppression opt-out), removes their progress photos, deletes the User row, then deletes the Supabase AUTH identity via the service-role admin client so the login can't be reused. UI is a dedicated 'Delete my account' danger-zone block (type DELETE to arm) on BOTH clients — web components/account-settings.tsx (redirects to /login after) and mobile components/aurora/settings.tsx (clears guest/draft caches + signs out). The wipe helper is the SINGLE source of truth shared by reset, self-delete and admin-delete so coverage can't drift. Localized EN/PL/DE (settings.delete* keys). Auth deletion degrades to a no-op without SUPABASE_SERVICE_ROLE_KEY (the DB delete is authoritative)." },
  { id: "admin-panel", area: "Web", status: "shipped", title: "Admin console (institutional admin panel)", detail: "A dedicated, WordPress-style operator console at /admin (and ready for an admin.hybrid.app subdomain — a host rewrite in middleware.ts maps it onto the same route group). Gated server-side: app/admin/layout.tsx resolves the DB user and redirects any non-ADMIN before a byte of admin UI/data is sent — the client shell is only chrome. Every /api/admin/* route starts with the shared requireAdmin() guard (lib/admin.ts). Sections: Overview (live KPIs — users/MAU/sessions/coaches/orgs/links, 12-week signup-vs-session growth, role/lang/plan splits), Users (searchable + paginated directory with a detail drawer and role/language editor — with rails: can't self-demote or remove the last admin), Orgs & coaching (the org + coach↔client link graph, management metadata only), Moderation (the trust & safety review queue — see moderation-queue), a full CONTENT/CMS group — Announcements (broadcast, cms-announcements), Exercise library (cms-exercise-library), Media library (cms-media-library), Localization (cms-localization), Feature flags (cms-feature-flags) — Capabilities & data (the registry + Data Network refit), Audit log, and System (DB health/round-trip, deployment + versions, env-var PRESENCE only — never secrets). INSTITUTIONAL GUARANTEES: full RBAC + an append-only audit trail — every privileged mutation writes an AdminAudit row (actor, action, target, before/after, IP, timestamp), surfaced in the Audit log. Privacy-preserving by design: admins see aggregates + management metadata + activity COUNTS, never another user's raw private training rows; impersonation is deliberately excluded. NOTE: run reference/sql-admin-audit.sql in Supabase to create the AdminAudit table (RLS-locked to the server) — until then privileged actions still work but aren't recorded, and the panel flags it. WEB IS NOW RESPONSIVE: the console works on phones/tablets — the sidebar collapses to a hamburger drawer and every section reflows (grids stack, wide tables become horizontally scrollable). TYPE SCALE NORMALIZED TO THE CLIENT APP: the section bodies were authored data-dense (clustered at 10–12px) and read miniature next to the consumer app (which bases at 13–14px), even though the shells share identical widths/padding (admin's main column is actually wider). The admin section type scale was lifted to sit on top of the client's (web: a uniform +1px on every fontSize ≤ 13, preserving each screen's internal hierarchy; cramped table rows loosened by +2px vertical padding) so the two surfaces feel like one product. Mobile is calibrated separately: there the admin already shared the client's 11px body base, so only the excess ≤10px 'tiny' text was lifted (+1) — a blanket bump would have overshot. The fix is now ENFORCED against future drift by a shared scale (see design-scale): every admin section on BOTH clients references named rungs (fs.body, space.lg) from @hybrid/core instead of inline magic numbers, so the two surfaces can no longer silently diverge. MOBILE PARITY: the SAME console now ships on the Expo app (apps/mobile/app/admin/* + components/admin/*) — admin-gated route group, a section springboard, and all 19 sections hitting the same /api/admin/* backend with a Bearer token; reachable from the More tab (admin-only). See mobile-admin for the handful of native parity gaps." },
  { id: "mobile-admin", area: "Mobile", status: "shipped", title: "Mobile admin console (full 19-section parity)", detail: "The institutional admin console (admin-panel) ported to the Expo app so operators can run the platform from a phone — satisfying the web↔mobile parity rule for the operator surface (it was previously web-only). ARCHITECTURE: an expo-router route group apps/mobile/app/admin/* gated by app/admin/_layout.tsx (redirects a signed-out → /login and a non-admin → the app tabs; the REAL boundary stays server-side — every /api/admin/* call runs requireAdmin and 401/403s a non-admin regardless of the client). A shared lib/admin-api.ts wraps the SAME backend the web console uses (adminGet/adminSend, Supabase access token as a Bearer header — the CSRF middleware exempts Bearer). app/admin/index.tsx is a grouped section springboard; app/admin/[section].tsx is the dynamic host that wraps each body in the standard Screen + header. The section registry (components/admin/sections.ts) mirrors the web nav one-for-one. ALL 19 sections are implemented natively in components/admin/* (Overview, Users, Orgs & coaching, Moderation, Financials, Agent HQ, AI agents, Announcements, Exercise library, Media library, Localization, Feature flags, Capabilities & data, Access control + coach applications, Security, Audit log, Guest workouts, System, Guidance) reusing a shared RN admin kit (components/admin/_kit.tsx) + lib/ui primitives, hitting the identical endpoints + payload shapes as their web twins (read-the-web-component parity), with the same loading / unavailable-SQL / error / empty states and the same optimistic-mutation-then-resync discipline (deletes behind Alert confirms). Entry point: an admin-only 'Admin console' card on the More tab. NATIVE PARITY GAPS (recorded, not lost): (1) charts — recharts is web-only, so dashboards render the same DATA as native stat tiles + label/bar rows; (2) agent RUN uses the non-streaming POST /[id]/run instead of the SSE /stream endpoint (RN fetch can't readily consume a ReadableStream) — same final {output,steps,usage}, no live token streaming; (3) media UPLOAD of new bytes + clipboard copy and CSV/PDF export stay web-only for now (manage/edit/delete/reveal-URL work on mobile); (4) datetime entry for scheduled announcements is plain ISO text (no native picker yet); (5) the per-feature persona-access editor and KPI logging are present, but the coach seat-mix sliders / KPI trend line chart are simplified. Verified: mobile typecheck clean + the iOS bundle exports (the CI mobile gate)." },
  { id: "admin-guidance", area: "Web", status: "shipped", title: "Admin Guidance — deploy/ops runbooks", detail: "A Guidance tab in the admin console (Governance → Guidance, apps/web/components/admin/guidance.tsx) that explains, in beginner-plain language, how HYBRID actually ships: a 'big picture' of web (auto-deploy to Vercel on main) vs mobile (Expo → EAS → TestFlight → App Store); a glossary of every moving part (Expo, expo.dev, Expo Go, the Apple Developer Program, App Store Connect, EAS Build/Submit/Update, TestFlight, what the terminal is for); a step-by-step App Store runbook; how to UPDATE after merging a PR (note: EAS Update OTA is NOT wired up yet, so every mobile change currently needs a fresh EAS Build; native changes additionally need Submit + Apple review; web/backend ride the Vercel deploy); a SANDBOX-BUILD runbook for internal on-device testing (build from the merged branch — EAS bundles your local committed code, not GitHub, so `git pull` first; the `device` internal-distribution profile + QR install; and the App Store Connect API-key workaround when hardware-key 2FA blocks Apple login); Vercel-vs-own-VPS hosting trade-offs; and a 'where we stand' section (the Apple Developer + Expo blockers are now cleared and the app has run on a real device; the public App Store submission is the remaining step). The content is documentation-as-DATA in @hybrid/core (guidance.ts — GUIDES/DEPLOY_GUIDE/SIMULATOR_GUIDE, typed GuideBlock/GuideSection, the block set now including copy-able `cmd` boxes + a `matrix` cheat-sheet) so the copy is the single source of truth and a future mobile admin renders the same words. The tab carries THREE guides (a switcher in the TOC): the deploy/ops runbook above, an iOS SIMULATOR runbook (the beginner copy-paste guide to running the app on Apple's Simulator — merged in from a former standalone 'iOS simulator' tab so all operator runbooks live under one Guidance hub; see ios-simulator-guide), and an ACCOUNTS & IDENTITY map — the source-of-truth inventory of every account HYBRID runs on (domain hybriddomain.xyz on GoDaddy, mail contact@hybriddomain.xyz on Google Workspace, GitHub/Vercel/Supabase, and the still-to-create Apple Developer Organization + Expo accounts), the 'which email owns what' decision (currently open, with a business-mailbox recommendation), the LLC → D-U-N-S → Apple-Organization path, a DECIDED domain & email architecture (landing on hybrid.app, app./admin. subdomains, no-reply@/marketing@/support@ unified onto hybrid.app once acquired — with an open cross-subdomain-session question), and the GoDaddy-DNS → Vercel wiring (keeping Workspace MX intact). hybrid.app remains the intended production domain; hybriddomain.xyz is the working placeholder. The runbook copy is documentation-as-DATA in @hybrid/core, and the mobile admin console now renders these SAME guides natively (the Guidance section, apps/mobile/components/admin/guidance.tsx), so web and mobile operators read identical words — see mobile-admin." },
  { id: "security-posture", area: "Web", status: "shipped", title: "Security posture + control registry (admin Security tab)", detail: "A live security dashboard in the admin console (Governance → Security) and the test suite that backs it. packages/core/security.ts is the single source of truth: shared, unit-tested primitives (normalizeRole, isValidLanguage, clampPage/clampPageSize, evaluateRoleChange — the lockout/escalation rule, redactSensitive) that the admin API actually uses, plus a registry of ~30 SECURITY_CONTROLS across Authentication / Authorization / Data protection / Audit / Input validation / Transport & headers / Secrets / Privacy / Supply chain / Abuse, each with severity + an honest status: pass (green — implemented AND covered by a test), todo (red — the remaining work, e.g. a strict nonce-based script-src CSP), or manual (amber — done in code, needs an out-of-repo step like applying RLS SQL in Supabase). Hardening since the first cut closed most of the reds: per-IP fixed-window RATE LIMITING (tested limiter applied to the AI coach + admin mutations, 429 + Retry-After), request BODY-SIZE caps (413), DEPENDENCY CVE SCANNING (Dependabot + a CI audit that fails on high/critical), and a CSP BASELINE (object-src 'none', base-uri/form-action 'self', frame-ancestors 'none', upgrade-insecure-requests). A further batch added CSRF PROTECTION (middleware rejects cross-origin cookie-auth mutations via a tested Origin/Referer check; mobile Bearer calls exempt), SUPPORT-READ AUDITING (an admin opening an individual's record writes a user.view audit entry), AES-256-GCM TOKEN ENCRYPTION at rest for wearable OAuth tokens (lib/crypto.ts, round-trip + tamper tested; activates on TOKEN_ENCRYPTION_KEY), an RFC-9116 /.well-known/security.txt disclosure contact, and TOTP MULTI-FACTOR AUTH end-to-end (enroll/verify/remove in account settings + a sign-in step-up that's a no-op until a factor is enrolled, so it can't lock anyone out; stepUpRequired + code validation unit-tested). and a STRICT NONCE-BASED CSP (per-request nonce in middleware → script-src 'self' 'nonce' 'strict-dynamic'; pages render dynamically so the nonce injects, verified against the running production server — every Next script incl. the inline RSC stream carries the matching nonce and chunks load via strict-dynamic). With that, every code-side control is green. Deploy/Supabase setup status: the AdminAudit SQL and TOKEN_ENCRYPTION_KEY are applied. ⚠️ DEFERRED: per-user MFA (TOTP) enrollment is intentionally on hold until the production domain is registered — enroll + verify the challenge flow in the browser then (Supabase TOTP is on by default; no code change needed). RLS reference SQL should also be confirmed applied in Supabase. The /security tab renders a posture score (share of controls green), a critical-open warning, LIVE runtime probes (HTTPS, DB reachable, audit table present, auth configured) from /api/admin/security, and every control grouped by category with its evidence. GUARANTEED HONEST: 226 core tests (incl. 22 security tests) + a web static-scan suite (vitest) assert the green controls actually hold — every API route authenticates, every /api/admin route requires ADMIN, OAuth tokens are never selected into responses, no dangerouslySetInnerHTML, security headers present, no committed secrets / secret logging — so a regression that weakens a control turns CI red. Hardening shipped alongside: baseline security response headers in next.config (HSTS, X-Frame-Options DENY, nosniff, Referrer-Policy, Permissions-Policy, frame-ancestors 'none'); the admin role path now routes through the tested core guards; pagination is clamped against resource-exhaustion (fixed a real bug where an absent pageSize fell to the minimum instead of the default). Both web test + the mobile iOS-bundle export run in CI." },
  { id: "cms-announcements", area: "Web", status: "shipped", title: "CMS — announcements / broadcast", detail: "The first content-management surface in the admin console (Content → Announcements), turning the operator panel into a CMS: an admin authors a message (title + body, level info/success/warning, audience all/coaches/clients) and drives it through a draft → published → archived lifecycle with optional scheduled publishAt + auto-expiry expiresAt and a 'pin as banner' flag — no code change or deploy needed to talk to the app. Announcement model + reference/sql-announcement.sql (RLS: any signed-in user reads only PUBLISHED rows; all mutations are server-only). Admin CRUD at /api/admin/announcements (+ /[id]) — ADMIN-gated, rate-limited, body-capped, and every create/update/delete writes an AdminAudit row. The read side /api/announcements returns only the published, in-window, audience-matched rows for the caller; pinned ones render as a per-device-dismissible banner atop the web app shell. The reusable pattern (model + RLS + admin CRUD + audited mutations + in-app surface) the rest of the CMS collections build on. NOTE: run reference/sql-announcement.sql in Supabase to create the table." },
  { id: "cms-exercise-library", area: "Web", status: "shipped", title: "CMS — exercise library (admin-managed catalog)", detail: "The second CMS content type (Content → Exercise library): a DB-backed, admin-authored exercise catalog that is a SUPERSET of the core Movement shape — engine-critical fields (pattern, muscles, baseLoad, system, validated against the same core enums) PLUS authored content (category, equipment, aliases, description, coaching cues, demo video URL — the slot the blocked exercise-video-library plugs into). Lifecycle: draft → published → archived. ARCHITECTURE: the 9 built-in movements stay in @hybrid/core so the engines stay PURE and the catalog works with an empty DB; a new pure, unit-tested mergeMovements(builtins, custom[]) folds the library over the built-ins by name (a custom entry overrides a built-in; aliases resolve to the same Movement but never clobber a real entry) into the one Record<string,Movement> the engines + pickers already consume — no engine signature changes. Name is the engine key; on rename the old name is auto-kept as an alias so prior logged sessions still resolve. Exercise model + reference/sql-exercise.sql (RLS: signed-in users read only PUBLISHED rows; mutations server-only). Admin CRUD at /api/admin/exercises (+ /[id]) — ADMIN-gated, rate-limited, body-capped, audited (P2002 → 409 on duplicate name). Read side /api/exercises (published) feeds a useExercises() hook that merges client-side; wired into the web Builder's exercise picker so an authored exercise immediately autocompletes across the app. PICKER DEDUP (aliases resolve but aren't pickable): mergeMovements keeps every alias key for engine RESOLUTION (an old logged session under an alias still attributes), but the two new pure helpers catalogNames(builtins, custom) + aliasNames(custom) drive DISPLAY — the pickable catalog is the primary names only, with any name a custom entry aliases removed. So a descriptive custom lift (e.g. 'Barbell Bench Press') that aliases the generic built-in 'Bench Press' shows ONCE under its own name while 'Bench Press' is hidden from the picker + datalist (workout-blocks.tsx filters both the pattern buckets and BASE_CATALOG through the alias set) yet still resolves for prior logs. reference/exercise-catalog.md is the deduplicated source-of-truth list the library seeds from, and reference/sql-exercise-seed.sql is the idempotent 209-row INSERT that populates the table from it (pattern/muscles best-effort-mapped to the coarse engine enums; isolation groups the enum lacks — biceps/calves/abs/forearms — left empty). MUSCLE-GROUP GROUPING: exercisesByCategory now takes a categoryByName map (categoriesByName helper) so library exercises group under their muscle-group heading (Chest, Back, …, LIBRARY_CATEGORY_ORDER) instead of the catch-all 'Other'; built-ins still bucket by movement pattern. MOBILE PARITY: shipped — the mobile pickers now consume this same library (see mobile-exercise-library). NOTE: run reference/sql-exercise.sql THEN reference/sql-exercise-seed.sql in the Supabase SQL Editor — the sandbox can't reach Supabase, so nothing appears in the picker until those run. EDIT ANY EXERCISE (built-ins included): the admin directory now lists the CODE built-ins alongside the custom DB rows (one A–Z list; GET /api/admin/exercises folds builtinExerciseRefs() under the custom rows, a same-name custom row hiding its built-in twin). A built-in is a virtual row (source 'builtin', synthetic id) with an 'Edit / override' action: it opens the editor pre-filled from the built-in's engine fields (pattern kept via LIBRARY_PATTERNS — the CMS allow-list is now core's full pattern taxonomy so a built-in override round-trips its pattern losslessly; muscles/category/equipment carried over) and SAVING creates a custom override (POST) that supersedes it by name. Renaming during an override seeds the original built-in name into aliases automatically (the PATCH route already does this for a custom rename), so prior logs resolve AND every summary canonicalizes to the new name (see exercise-name-canonicalization). If the Exercise table doesn't exist yet the built-ins still LIST (read-only) under a non-blocking banner instead of the old blocking 'not initialized' screen. Editing is a WEB admin surface (mobile consumes the result via the shared catalog + server-canonicalized sessions — no mobile editor by design, same scope as mobile-exercise-library)." },
  { id: "cms-media-library", area: "Web", status: "shipped", title: "CMS — media library (shared asset catalog)", detail: "The third CMS content type (Content → Media library): an admin-managed catalog of shared assets (exercise demo clips, announcement imagery) that turns scattered URLs into a managed library. Bytes live in a PUBLIC Supabase Storage bucket 'media' (reusing the progress-photos storage pattern) with admin-only writes — a new public.is_admin() RLS helper gates insert/update/delete on storage.objects while keeping public read, so the stable CDN URL can be embedded anywhere. A MediaAsset catalog table (title/alt/kind/tags/size + lifecycle) is the searchable index + the URL other content points at; reference/sql-media-library.sql creates the bucket, is_admin(), the storage policies, and the table (RLS: signed-in read published, mutations server-only). Admin uploads client-side (like progress photos), then POSTs the row to /api/admin/media (+ /[id]) — ADMIN-gated, rate-limited, body-capped, audited; DELETE removes the row and best-effort removes the bytes (admin auth carries through is_admin()). Read side /api/media returns published assets. The admin screen is a grid with image/video previews, draft/publish/archive, tag/title editing, and a one-click Copy-URL that drops straight into an Exercise's demo-video field (cms-exercise-library) — connecting the CMS types. NOTE: run reference/sql-media-library.sql in Supabase; the actual upload/delete round-trip is untestable from this sandbox (Supabase host blocked), same as progress-photos. MOBILE PARITY: the mobile admin console (apps/mobile/components/admin/media.tsx) manages, edits, status-cycles, deletes existing assets and reveals the public URL, but UPLOADING new bytes is out of v1 scope on mobile — new clips/images are uploaded from the web console (the RN Storage upload + a clipboard copy aren't wired yet)." },
  { id: "cms-localization", area: "Web", status: "shipped", title: "CMS — localization manager (edit EN/PL/DE in-app)", detail: "The fourth CMS content type (Content → Localization): a non-engineer can fix copy or fill a missing PL/DE string from the admin UI — no code edit, no deploy. ARCHITECTURE mirrors the exercise library: the shipped TRANSLATIONS stay in @hybrid/core as the baseline (the app always renders offline-first on them), and a SPARSE Translation table holds only the (lang,key) rows an admin edited/added. A new pure, unit-tested makeTWithOverrides(lang, overrides) layers the overrides over the baseline (override active-lang → shipped active-lang → override en → shipped en → key); makeT is unchanged so nothing else breaks. allTranslationKeys()/baselineString() expose the catalog to the editor. Translation model + reference/sql-translation.sql (RLS: signed-in read all — UI copy isn't secret; mutations server-only). Admin CRUD at /api/admin/translations — ADMIN-gated, rate-limited, body-capped, audited; POST upserts and an empty value REVERTS to baseline. Read side /api/translations groups overrides by language and is wired into BOTH clients' LanguageProvider (web fetch + mobile Bearer via fetchTranslationOverrides), so an edit reaches web AND the phone. The editor is a searchable, group-filterable key table (overridden / missing-translation filters, per-cell revert, live key + override counts). NOTE: run reference/sql-translation.sql in Supabase to create the table." },
  { id: "cms-feature-flags", area: "Web", status: "shipped", title: "CMS — feature flags / runtime config", detail: "The fifth CMS content type (Content → Feature flags): toggle app capabilities at runtime, no redeploy. ARCHITECTURE matches the other CMS layers — the KNOWN flags + defaults live in a FEATURE_FLAGS registry in @hybrid/core (so the app runs on defaults with an empty DB, and only a flag that code actually reads can gate anything), while a sparse FeatureFlag table stores per-flag OVERRIDES (enabled / audience / optional JSON value). Pure, unit-tested evaluator: evaluateFlags/evaluateFlag + flagAudienceMatches (admins always match; coaches/clients scoped) + flagValues. FeatureFlag model + reference/sql-feature-flags.sql (RLS: signed-in read all; mutations server-only). Admin CRUD at /api/admin/flags (+ /[key] reset) — ADMIN-gated, rate-limited, body-capped, audited; only registry keys are accepted, an empty override row resets to default. Read side /api/flags evaluates the registry against the caller's role and returns a boolean map (+ values); a fail-OPEN useFlags() hook consumes it. WIRED end-to-end: the web app shell gates the announcement banner behind app.announcements and hides nav items (Nutrition/Talent/Longevity/Tactical) behind nav.* flags — flip a toggle in the console and the feature appears/disappears on the next load. The editor lists every registry flag with an on/off switch, audience scope, override/default badge, and per-flag reset. NOTE: run reference/sql-feature-flags.sql in Supabase so toggles persist (until then the app runs on registry defaults)." },
  { id: "moderation-queue", area: "Web", status: "shipped", title: "Moderation queue (trust & safety)", detail: "The sixth admin surface (Platform → Moderation): a review workflow over user-generated content, with two feeders. (1) APPROVAL GATE — a discoverable talent profile must be approved before it surfaces in discovery: TalentProfile gains moderationStatus (existing rows grandfathered to 'approved'; /api/talent sets a new/edited discoverable profile to 'pending'), and /api/talent/search now requires 'approved', so unreviewed/edited profiles wait in the queue. The athlete sees a 'pending review' / 'not approved' note on their own Talent screen. (2) REPORTS — any signed-in user can flag a discoverable profile (a ⚑ on each discovery result → /api/reports, rate-limited, dup-collapsed); a denormalized Report model feeds the queue. The admin console has a two-tab queue: pending profiles (Approve / Reject) and open reports (Take down → rejects the target out of discovery / Dismiss / Mark resolved). Every decision is ADMIN-gated + audited (moderation.profile.*, moderation.report.*). Report model + TalentProfile columns + reference/sql-moderation.sql (RLS: a user inserts only their own report; reads/resolutions are server/admin-only). NOTE: run reference/sql-moderation.sql in Supabase to add the columns + table." },
  { id: "auth-email", area: "Auth", status: "shipped", title: "Email auth + roles", detail: "Supabase email sign-up/in on web + mobile. Role model CLIENT/COACH/ADMIN; admin can toggle all dashboards. SIGN-OUT RESILIENCE FIX (Jul 2026): the primary 'Sign out' now sticks even offline. Two defects were fixed on BOTH clients — (1) the plain sign-out used the DEFAULT scope, which is GLOBAL, so it unexpectedly revoked every device AND was redundant with the explicit 'Sign out everywhere' button; it now uses scope:'local' (this device only), leaving 'everywhere' as the sole global revoke. (2) supabase.auth.signOut() only removes the persisted session when its network revoke SUCCEEDS (auth-js returns early on any non-401/403/404 error, e.g. offline/timeout/5xx), so a failed revoke left the token behind — `sb-*` cookie (web) / `sb-*` AsyncStorage key (mobile) — and getUser()/getSession() silently signed the user back in on the next launch ('logged out but still logged in'). The `hybrid.*` state wipe never touched those `sb-*` keys. Now clearClientState() force-clears the Supabase auth token regardless of the revoke result — web session.tsx expires every `sb-*` cookie, mobile session.tsx drops every `sb-*` AsyncStorage key — and mobile also nulls the React session directly (the auth listener only fires SIGNED_OUT on a successful revoke). So sign-out tears down locally every time. Web=web/lib/session.tsx, mobile=mobile/lib/session.tsx. Plus MIDDLEWARE SESSION REFRESH (web): the edge middleware previously did only CSRF/CSP and never rotated the Supabase auth cookie — Server Components can't write cookies, so an access token that expired between visits left SSR rendering from a stale session until the browser client refreshed it. middleware.ts now runs the standard @supabase/ssr refresh (createServerClient + getUser()) with the rotated cookies written onto BOTH the downstream request (this render sees them) and the response (the browser persists them); gated on an `sb-*` cookie being present so logged-out traffic never pays the auth round-trip, and best-effort so a refresh hiccup never blocks a page." },
  { id: "auth-social", area: "Auth", status: "blocked", title: "Apple + Google sign-in", detail: "Code paths exist (buttons + OAuth callback).", blockedBy: "Enable providers in Supabase: Google Cloud OAuth client; Apple needs the Apple Developer Program + Services ID." },

  // ---- Backend / Data ----
  { id: "db", area: "Data", status: "shipped", title: "Database (Prisma + Supabase)", detail: "29 models with RLS enabled — core: User, Session, Macrocycle, Biometric, Plan, Signal; coaching: CoachLink, CoachNote, Checkin, WorkoutTemplate, Assignment; performance/roadmap: RtpProtocol, RiskOutcome, ModelFit, VideoAnalysis, Event, TalentProfile, Connection; teams: Organization, Team, Membership, OrgInvite; governance: AdminAudit; CMS: Announcement, Exercise, MediaAsset, Translation, FeatureFlag; trust & safety: Report. Each feature ships its own migration in reference/*.sql (table + policies) since the sandbox can't reach the Supabase host." },
  { id: "api", area: "Backend", status: "shipped", title: "Shared API", detail: "One Next.js backend (app/api/*) both clients call — every route is user-scoped and accepts web cookies OR mobile Bearer tokens. Surface spans /api/me, /api/sessions, /api/signals, /api/macrocycles, /api/checkins, /api/templates, /api/assignments, /api/events, /api/rtp, /api/video, /api/talent, /api/state, /api/connect/[provider], /api/datanet, /api/org/*, the coach routes (/api/coach/squad, /api/coach/compare, /api/coach/links/[id]/{sessions,notes,checkins,assignments}), the CMS read routes (/api/announcements, /api/exercises, /api/media, /api/translations, /api/flags), user reporting (/api/reports), and the ADMIN-gated console routes (/api/admin/{stats,users,announcements,exercises,media,translations,flags,moderation,…})." },
  { id: "rls-policies", area: "Backend", status: "shipped", title: "Row-level security policies", detail: "Base policies in reference/rls-policies.sql (own-rows for Session/Macrocycle/Biometric/Signal, coach read via ACTIVE CoachLink, private CoachNotes hidden from clients, Plan readable by signed-in users). Each later feature adds its own own-rows + active-coach policies in its migration file (sql-checkin, sql-workout-builder, sql-coach-tags, sql-progress-photos storage RLS, sql-rtp, sql-org-graph, sql-coach-macrocycle, etc.). Defense-in-depth atop the API-layer enforcement." },

  // ---- AI / Integrations ----
  { id: "ai-coach", area: "AI", status: "shipped", title: "AI coach (server-side Anthropic)", detail: "/api/ai-coach builds context from your real sessions + signal-derived recovery and grounds the note in the Athlete Twin — HPI + its limiting pillar, ranked state drivers, and tissue-level injury flags. It now also feeds the coach the ENDURANCE side and EFFORT trend: cardio mileage (total + last-4-weeks via the running engine), recent pace, the easy-vs-hard balance (paceEffortSplit — derived from pace, not RPE), and the athlete's average logged strength RPE across recent efforts — and the system prompt weighs both sides of hybrid training (flagging an off easy/hard balance, or a grind when RPE sits ≥8.5). Calls Claude server-side (claude-opus-4-8, adaptive thinking); falls back to a Twin-aware engine note (state summary + risk warning) if the key is ever unset. ANTHROPIC_API_KEY is SET in Vercel, so the LLM coach is live (never called from a client). This same key powers the AI agent org (see agent-org)." },
  { id: "biometrics-manual", area: "Data", status: "shipped", title: "Readiness check-in (manual biometrics)", detail: "Enter HRV / resting HR / sleep; persisted to the Biometric table and fed into the readiness engine (today vs. rolling baseline). Web dashboard." },
  { id: "vbt-capture", area: "Integrations", status: "blocked", title: "Live bar-velocity & trajectory capture", detail: "The whole VBT analytics stack (vbt-engine + Velocity screen + team-compare) is live and consumes velocity from any source. What's missing is the on-device CAPTURE that produces real per-rep velocity and the sagittal bar-path/trajectory: either a bar-mounted IMU sensor over BLE or a phone-camera CV pipeline (extends video.ts pose frames). Until then, velocity is entered manually per set (m/s) in the Logger's exercise detail sheet and still drives the full profile + 1RM + autoregulation. Per-rep trajectory plots are stubbed in the UI.", blockedBy: "A bar-sensor BLE SDK (e.g. an Enode/Vitruve-class device) or a native camera pose-capture module in the EAS build to emit per-rep velocity + bar path." },
  { id: "financials-model", area: "Web", status: "shipped", title: "Financials & unit-economics console", detail: "Admin → Business → Financials: the business-model + cost-structure surface and a deep, self-explaining unit-economics model computed by a pure, unit-tested @hybrid/core/economics engine (REVENUE_STREAMS + PricingTiers + COST_DRIVERS + DEFAULT_ASSUMPTIONS + computeEconomics + METRIC_GUIDE) and seeded from the real /api/admin/stats counts (every assumption editable via sliders). Covers: (1) revenue — MRR/ARR by stream, blended ARPU, COGS breakdown (Anthropic, Supabase+Vercel, Stripe, coach success/support, fixed opex), gross margin, monthly P&L, subscriber break-even; (2) PER-SEGMENT unit economics — B2C vs coach priced on their own ARPU, contribution margin, churn, CAC → LTV, CAC payback, LTV:CAC (no more mushy blended single number); (3) a SaaS health scorecard — Rule of 40, net & gross revenue retention, quick ratio, magic number, burn multiple, cash runway, annualized growth; (4) a 12-month forward forecast — MRR trajectory + cumulative cash chart with the modeled P&L break-even month and cash-out month. Ships METRIC_GUIDE, a plain-language glossary (what each metric means, the formula, the benchmark) surfaced inline so the screen teaches as it models. Documents all four revenue streams — B2C Pro ($12.99/mo – $99/yr), coach seats (Starter/Pro/Business $29/$79/$199), org/enterprise (~$40–80/athlete/yr), and the future data-network line. COSTS are now the real run-rate, not a placeholder: per-user COGS (Anthropic AI coach ~$2.00/active AI user/mo, Supabase+Vercel marginal ~$0.20/active user/mo, Stripe 2.9%+$0.30/charge, coach success ~$3.00/seat/mo) plus an itemized ~$72/mo fixed opex (Supabase Pro $25 + Claude API for internal agents $20 + Apple Developer $99/yr + hybrid.app renewal $100/yr + the @hybriddomain.xyz mailbox + hybriddomain.xyz renewal; the one-time hybrid.app $300 premium domain + zł5.34 registration called out separately, excluded from the run-rate). FOCUS MARKETS + LOCALIZED PRICING (new, MARKET_PRICING in economics.ts): the five launch markets — US (anchor), UK, EU (ex-PL), Poland and Singapore — each with its currency, the localized Pro monthly/annual + coach-seat + org price, the USD-equivalent at the reference FX (18 Jun 2026), the consumer tax (VAT/GST), the local Stripe fee, a purchasing-power price index vs the US, and a per-market rationale (Poland localized to ~60% of the US price on PPP; Singapore a touch above on GST + higher Stripe fee). ENTITLEMENT MATRIX (new, ENTITLEMENT_MATRIX + PLAN_COLUMNS): a 'what each plan gets' grid — Free vs Pro vs Coach vs Org across ~20 features (logging free forever; intelligence + training depth on Pro; roster/teams on the coach seat; org graph/medical/video on enterprise), the tiers nesting Pro ⊂ Coach ⊂ Org. All three (markets, entitlement matrix, the model) are pure + unit-tested in @hybrid/core. Modeling/planning only (read-only, no writes, no new API) — actually CHARGING money stays the blocked `billing` capability." },
  { id: "billing", area: "Backend", status: "blocked", title: "Billing & payments (coach marketplace)", detail: "Payment rails for the coach MARKETPLACE — the client pays the coach for a paid program and HYBRID takes a platform fee on the transaction (see social-paid-coaching). NOT seat fees: coach tooling is free, permanently (see coach-tooling-free) — the Jul 2026 strategy review reframed coaches from a revenue line into the acquisition channel, so there is no 'HYBRID charges the coach for tools' path to build. The old seat-fee tiers survive only as the shelved counterfactual inside the admin Financials model (economics.ts). What's missing here is the live charge path for client→coach checkout; it can be built behind a provider abstraction but can't be wired or tested without provider keys.", blockedBy: "A Stripe account + STRIPE_SECRET_KEY / STRIPE_WEBHOOK_SECRET (and Connect onboarding for coach payouts) in the server env." },
  { id: "coach-tooling-free", area: "Core", status: "shipped", title: "Coach tooling is free — coaches are the acquisition channel", detail: "The Jul 2026 strategy review's call, now the recorded product policy: one coach brings 30–200 athletes at zero CAC, so taxing the channel with seat fees is strictly worse than growing it. What this means in code: the verified COACH role unlocks everything (access.ts whitelists 'coach'; coach nav is role-gated, never paywalled), roster/invites/program builder/groups/squad monitor/check-in replies carry no entitlement checks on either client, and the invite route's roster cap is an anti-abuse guardrail (200) rather than a billing tier — the 'enforce 10/40/150 when billing lands' TODO is deleted. economics.ts reframes the coach stream: tooling $0 forever, revenue later as a marketplace platform fee on coach-sold programs (social-paid-coaching), with the old seat tiers kept only as a what-if counterfactual in the Financials model. The only gate on coaching is the verification queue (coach-verification), which is quality control, not pricing." },
  { id: "exercise-video-library", area: "Web", status: "blocked", title: "Exercise video / demo library", detail: "Per-exercise demo clips + coaching cues a beginner needs for confidence and a coach needs to stop re-explaining. The library metadata, search, swap-by-pattern and player UI can be built on the existing MOVEMENTS map; the demo media itself needs sourcing/licensing.", blockedBy: "A licensed exercise-video catalog (or commissioned clips) + hosting/CDN; or a content partner." },
  { id: "nutrition-fooddb", area: "Data", status: "shipped", title: "Food database search + barcode lookup (Open Food Facts)", detail: "The frictionless food-search path on top of nutrition logging is now LIVE on Open Food Facts — the free, open, no-key food database. Core (@hybrid/core/nutrition-off.ts, pure + unit-tested) normalizes OFF's loose product JSON to one OffFood shape (name, brand, serving, kcal + P/C/F, preferring per-serving nutriments and falling back to per-100 g) and owns the endpoint URL builders (offSearchUrl text search, offBarcodeUrl by EAN/UPC, isLikelyBarcode). A thin auth-gated server proxy /api/nutrition/search (GET ?q= text OR ?barcode= — a numeric query auto-routes to barcode lookup) adds the required User-Agent, bounds the upstream call (8 s AbortController), and returns normalized foods (graceful empty → the client falls back to manual entry). The 'My foods' sub-screen on BOTH clients is now SEARCH-FIRST: one box (text or barcode) → debounced results as rows (brand · serving · macros) each with LOG-to-today (writes the same energyIntake/protein/carbs/fat signals, source 'off') or a bookmark SAVE-to-library (POST /api/nutrition/products, respects the free FREE_PRODUCT_LIMIT cap → upgrade). Below sits the user's saved foods + a redesigned manual builder (labelled colour-coded macro tiles + a live 4·4·9 kcal readout) for anything the DB lacks. PORTION & QUANTITY: logging any item — a search hit, a saved food, or a saved meal — opens a shared editor sheet (the app Sheet, web + mobile) with a serving × quantity stepper (0.5 steps + a typed value); the calorie total and every macro RECOMPUTE LIVE as you dial, and the scaled amounts are what get written (a search hit can also be Saved to the library from the same sheet). This is the tracker-standard portion control the flat form lacked. Web + mobile at parity; i18n EN/PL/DE. Live CAMERA barcode scanning (point-and-scan) is a separate native follow-up — see nutrition-barcode-camera. TWO-TIER (Jul 2026): the same search box now returns HYBRID Verified items ABOVE the community results (see nutrition-verified-foods), and every hit carries the full label panel — saturates, sugars, fibre, salt (see nutrition-label-panel)." },
  { id: "wearables", area: "Integrations", status: "blocked", title: "Wearable sync (WHOOP / Oura / Garmin / Apple)", detail: "Connector layer built: core registry + normalizers (parseWhoop/parseOura/parseHealthKit → Signal[], unit-tested), prisma Connection model + reference/sql-connection-table.sql, OAuth start/callback + sync routes (/api/connect/[provider]), /api/connections, and a Connections hub screen (mobile parity: app/connections/). Each provider writes into the Signal ontology without touching the engines. OAuth providers show 'setup pending' until creds are set. Apple's native half is now built — tracked separately in apple-healthkit.", blockedBy: "Per-provider OAuth credentials in Vercel env (e.g. WHOOP_CLIENT_ID/SECRET, OURA_CLIENT_ID/SECRET) + NEXT_PUBLIC_SITE_URL." },
  { id: "connections-provider-pages", area: "Integrations", status: "shipped", title: "Connections — a dedicated page per provider", detail: "Every provider in the Connections hub opens its OWN page: web uses the same focus-page pattern as the exercise page (components/aurora/connection-page.tsx inside the connections screen), mobile a real route (app/connections/[provider].tsx). The hub is now a pure directory (status chip + provides + Open); connect/sync/disconnect actions and a recent-data list (latest Signal rows from that source) live on the provider page. Built as new files beside the hub so the change is trivially revertable. EN/PL strings." },
  { id: "apple-healthkit", area: "Mobile", status: "blocked", title: "Apple Watch / Health native sync (HealthKit)", detail: "The apple connector's native half, isolated in apps/mobile/lib/healthkit.ts + the Apple provider page: @kingstinct/react-native-healthkit (Nitro, new-arch — the first pick, react-native-health, compiled after patching but its legacy NativeModule never registers on RN 0.85, which removed the legacy architecture), permission request, 30-day HRV (queried in ms, daily mean) / resting-HR / nightly-sleep-hours reads, relayed to the EXISTING /api/connect/apple/sync (parseHealthKit → Signal rows, deduped by the userId+kind+ts+source index) — plus a new /api/connect/apple/register that records the Connection row so the hub shows a real status, and lastSyncAt now stamps for apple syncs too. Degrades gracefully wherever the native module is absent (Expo Go / Android show the install hint). Signing self-heals in the mobile-release workflow (enables the HealthKit App ID capability + deletes stale provisioning profiles via the App Store Connect API); plugins/with-plain-healthkit.js keeps the entitlements to plain HealthKit only.", blockedBy: "Verify on-device with the next TestFlight build: Connections → Apple Watch / Health should offer Connect Apple Health (not the install hint); grant the 3 read permissions → Sync now → Signal rows appear with source=apple. Then flip this to shipped." },
  { id: "device-workout-match", area: "Mobile", status: "blocked", title: "Match a logged workout with the device's recording (Apple Watch)", detail: "Open any workout summary and pull the watch's read of that EXACT session onto the row: the hero panel carries a 'Match the workout from your watch' button → a sheet reads the HealthKit workouts around the session (queryWorkoutSamples ± the shared 24 h window — wide on purpose, quick-logged sports are stamped at log time, not play time), ranks them in core (rankDeviceWorkouts: time proximity + duration similarity, best match tagged), and one tap PATCHes the frozen DeviceWorkout onto Session.device — everything the recording carries: uuid, activity label resolved on-device, interval, measured duration/kcal/distance, avg+max+min HR, steps, elevation ascended, swim strokes, flights climbed, average METs, indoor flag, weather temperature, source. The picker's best candidate renders as THE card (lime-washed, tagged, its own match affordance) so the choice reads at a glance — server-sanitised (sanitizeDeviceWorkout) and matchedAt server-stamped. THE MEASUREMENT WINS, INCLUDING IN THE ENGINES. Once a session is matched, the device's read IS the session everywhere — never just on the summary. Session-level: done-receipt takes its duration, distance and climb; energy.ts takes its kcal (basis 'device', and the figure drops the '~' because it is no longer an estimate); the sRPE load model scales to the measured minutes so load ÷ minutes stays the mean RPE; the nutrition fuel bump eats for the measured burn; the wrist's avg HR joins the summary tiles and its max HR the premium facts. Block-level: core/device-truth.ts projects the recording onto the session's activity block (`deviceTrueSession`), and every engine that walks blocks applies it at its entry — toTrainingLog (so tissue fatigue, injury risk, performance state and readiness all read measured minutes/distance), running/endurance totals + weekly mileage + pace splits, cardio PRs, per-exercise dashboards and widgets, the fitness-level 5 km-equivalent, weekly recaps and the social distance comparison, the History row headline and the session-detail breakdown. Attribution is deliberately conservative: exactly ONE timed block takes the recording; zero (a pure lifting session) or two or more leaves the blocks alone rather than splitting one interval by guesswork. Only measured quantities are projected — RPE, zone, stroke and the exercise name stay the athlete's. The server-side engine inputs (athlete-state, ai-coach, coach squad, social) now select Session.device for the same reason the `feel` column is selected there: dropping it would make the server reason about a different athlete than the app shows. What was typed in is the SECONDARY reading, kept on one surface: the 'Your device's read' panel on BOTH clients, 'You logged' in one column and the device's measurements in the other (both read with ignoreDevice so the same number can't print twice), with re-match + unlink (unlink works on web too). That panel speaks the ACTIVITY's own units so it can sit next to the watch face without translation — a pool swim reads '510 m' and '3:52 /100m' (not '0.51 km' at '38:36 /km'), rowing splits per 500 m, everything else per km — and the pace takes the recording's second-accurate `durationSec` rather than the whole minutes every engine reads, because 19:41 rounded to 20 min would print 3:55 against the watch's 3:52 — and the DURATION row shows that same measured time on the device's own clock ('19:41', '1:34:12' past the hour) beside the typed '20 min', since printing '20 min' in both columns invents an agreement neither side claimed. The app column's DERIVED figures (the modelled kcal, the pace computed from two typed numbers) wear the '~'; what the athlete typed does not, because a self-report is not a model. The bridge's unit conversion moved to apps/mobile/lib/health-quantities.ts — pure, no react-native import — and is pinned by apps/mobile's FIRST unit tests (health-quantities.test.ts, vitest), which assert the literal unit strings the native serializers emit ('meters' from a workout total vs 'm' from a statistic, 's', 'kcal', 'count', 'degC'). An unrecognised unit makes a metric vanish rather than throw, so that contract is now the thing under test. And because the stored read is a SNAPSHOT, a fix to what the native bridge understands would otherwise only reach future matches — so the Apple Health sync carries a repair pass (refreshMatchedWorkouts): it asks HealthKit for exactly the uuids already on the athlete's sessions (one query, no date window), re-normalizes each, and re-PATCHes only the rows whose read actually changed, leaving recordings the watch no longer holds matched rather than silently unlinking them. The device is also NAMED properly: the native read resolves the HKDevice name (then the source's true name via toJSON, then the product-type family), because this library hands the source back as a Nitro hybrid object whose own `name` is the class name — which is why the first build displayed the literal 'SourceProxy'. core's deviceSourceLabel/isDeviceName filter that junk on read as well as on write, so rows matched before the fix render as 'Apple Watch' rather than the bridge's class. Connect/permissions ride inside the sheet: the workout/HR/active-energy read types are asked on first open (and folded into the Apple Health connect for new users), and re-opening the sheet IS the re-sync. Shape, ranking, comparison rows and API sanitisation live in core/session-device.ts (pure, unit-tested); i18n EN/PL/DE. NATIVE CONSTRAINT (permanent, recorded per the parity rule): only the phone can read HealthKit, so the MATCH action is iOS-only — web renders the matched panel, can unlink, and points matching at the iPhone app.", blockedBy: "Session.device is APPLIED in production (sql-session-device.sql run in the Supabase SQL Editor, Jul 2026) — the DB side is done. Matching itself is VERIFIED on-device (Jul 2026, TestFlight): a manually logged tennis session matched its watch recording. What's left is one more TestFlight pass on this change: after matching, the summary must headline the device's duration/kcal (94 min, 677 kcal — not the typed 90 min, ~860 kcal) and the chip + comparison header must read as the device signature (see device-signature-mark) rather than 'SourceProxy' or the retired ⌚ emoji. ALSO on that pass: a matched POOL SWIM must now show DISTANCE and PACE in the device column (they read '—' in the Jul 2026 build — the bridge serializes a workout's totalDistance with the literal unit string 'meters' while the converter only accepted 'm', so every measured distance was dropped, taking the derived pace with it). The reference recording is 510 m in 19:41 → the panel must read '510 m' and '3:52 /100m', matching the watch's own summary exactly. And because Session.device is a snapshot frozen at match time, the SESSIONS ALREADY MATCHED must be repaired by the same pass: Connections → Apple Health → Sync now re-reads every stored uuid straight from HealthKit and re-PATCHes the ones whose read changed, reporting the count ('N matched workouts re-read from your watch') — confirm an old swim gains its distance + pace without the athlete re-matching it by hand. Also on that pass, the WRAPPED panels must now agree with that comparison table rather than reading a rounded version of it — the same swim's hero and stat strip must show 510 m and 3:52 /100m (they showed 500 m at 4:00 /100m, and a swim pace PR headlined '39:13 /km'); see session-wrapped-measured-precision. Then flip to shipped." },
  { id: "device-import", area: "Mobile", status: "blocked", title: "Import a workout the device already recorded (auto-sync)", detail: "The other direction from device-workout-match: the training STARTS on the wrist and the app pulls it in, with every value the recording carries and nothing typed. Every log surface leads with it — the quick-log carousel on BOTH clients opens with an 'Import from your watch' bar above the sport grid, because if the watch already recorded it there is nothing to type. The mobile sheet reads the last 14 days (queryRecentDeviceWorkouts, the same normalizer as the match read), plans them in core (planDeviceImport) and shows what a tap will DO before it does it: a new recording adds a session, one that IS a session the athlete already logged joins that row instead of duplicating it, and ones already in the log sit greyed at the bottom as proof of what synced. Rows are individually excludable — the watch calls a six-minute walk to the shop a workout. THE DOUBLE-COUNT PROBLEM is the whole design: dedupe is decided SERVER-side against the database (POST /api/sessions/import-device runs the same shared plan), so an auto-sync that retries on a flaky network, or a second phone syncing at the same moment, cannot write the same session twice — recordings are matched on the health store's own uuid, and the attach write is guarded on the row still being unmatched. Pairing is one-to-one and greedy on closeness, and it is deliberately conservative: an interval-logged session absorbs a recording only on ≥50% overlap, a point-logged one (the quick-log sheet stamps startedAt == completedAt hours after the game) needs BOTH a stamp within 3 h and a duration agreeing within 30% — anything short of that imports as its own session, because a duplicate the athlete can delete is recoverable and a recording welded onto the wrong session is not. Imported sessions land at the TRAINING's time, not the sync's, titled by the catalog sport the activity maps to (HealthKit's ambiguous enums — hockey, skatingSports — keep the device's own wording rather than guess), carrying a stamped discipline and the recording on Session.device, so THE MEASUREMENT WINS downstream exactly as for a hand-matched session. AUTOMATIC is the point of the ask: loggerPrefs.deviceAutoImport (off by default, on both clients' logger settings and inside the sheet) makes every foreground pull new workouts in silently — throttled to 30 min, never opening an unprompted permission sheet, silent on failure. Pure + unit-tested in core/device-import.ts; i18n EN/PL/DE. NATIVE CONSTRAINT (recorded per the parity rule): a health store is native, so the READ is iOS-only — web ships the same entry point, the same auto-import switch and the receipt (every session carrying a device read, with its measured figures), and says plainly that the pull happens on the phone. PROVIDERS: the sheet ends with a 'Where it reads from' strip driven by DEVICE_IMPORT_PROVIDERS — Apple 'Ready', Garmin 'Not connected yet' — so an athlete hunting for their Garmin gets an answer instead of importing nothing and guessing why. Garmin is a real placeholder, not a stub: its logo is now traced into device-marks.ts (wordmark lockup + the delta as the compact glyph, ® dropped for legibility per the Apple precedent), deviceSourceLabel already names it, and a Garmin DeviceWorkout plans, blocks and imports through exactly the same code as an Apple one (unit-tested) — the only missing piece is a reader. Nothing downstream branches on the provider, so the day the credentials land, no planning code changes. NO PHANTOM 'YOU LOGGED': an import-created session's block is the recording, copied — so the summary's device panel must not read those figures back as what the athlete typed. deviceImportedSession (core, unit-tested) recognises the echo — the session's interval is the recording's to the millisecond AND the block figures are the recording's, unedited — and both clients then render the panel single-column (measured only, with its own lead + footer copy, EN/PL/DE). Decided from shape, not a stored flag, so sessions imported before the fix heal too, and an athlete's genuine edit to a figure brings the logged column back.", blockedBy: "Verify on-device with the next TestFlight build: the quick-log's 'Import from your watch' bar should list the last fortnight of Apple Watch workouts with the right plan per row, importing should create/attach exactly once (re-open the sheet — everything should read 'Already in your log'), an imported session's summary panel should show the measured column ALONE (no 'You logged' column of echoed figures), and with auto-import on a fresh watch workout should appear on Home without a tap. Everything else — the plan, the server route, the web half — is done and testable in CI. Garmin is listed but deliberately inert: it needs the OAuth credentials tracked under `wearables`, not new import code." },
  { id: "device-signature-mark", area: "Core", status: "shipped", title: "Device signature — the matched device's own mark", detail: "A matched session no longer signs itself with a ⌚ emoji — which renders as a different object on every platform, has no equivalent for a strap or a head unit, and cannot carry a manufacturer's logo. core/device-marks.ts holds the artwork as shape data normalised to a 100-unit-tall viewBox: the Apple Watch lockup and the Apple mark alone, plus Garmin’s wordmark + its delta glyph, and HYBRID’s own watch/band silhouettes for the connectors whose logos we don’t ship yet, mapped provider → drawing by deviceMarkFor() beside the deviceSourceLabel() that already resolves the device’s NAME. EVERY LOGO READS AT THE SAME SIZE, which the first cut got wrong: scaling each drawing so its BOUNDING BOX fills the box is the obvious move and it is incorrect, because the boxes hold different things — Apple's is bounded by the apple (36% above its letters), Garmin's by the delta (90% above), so at one requested height Apple's letterforms came out 1.39x Garmin's, one logo visibly bigger than the other in the same row. Drawings are now normalised on what the EYE measures: a wordmark on its CAP HEIGHT (DEVICE_MARK_CAP), with the cap band parked at the same y in every wordmark (DEVICE_MARK_CAP_TOP) so logos share a baseline as well as a size and the ascenders live in headroom above; a glyph on DEVICE_MARK_GLYPH, the geometric mean of its ink area's square root and its bounding height — neither alone works, since a triangle and an apple of equal HEIGHT don't read as equal size while a flat band and a tall watch of equal INK don't either. Each art carries its `kind` and `optical`, and the suite fails if a new logo is added by eye instead of by measurement. Two forms: the lockup wherever the device is being named (Wrapped hero chip, the device panel’s measured column header, the match sheet title), the compact mark wherever it is merely being counted (a candidate card, the match CTA). THE ONE RULE, and the reason the module exists: a manufacturer’s logo reproduces in solid black or solid white and nothing else — no accent, no gradient, no opacity, no stretch. So neither renderer takes a `color` prop; callers name the SURFACE and the ink comes from DEVICE_MARK_INK (the brand’s chalk and ink, unit-tested to contain no accent and to meet AA on the ground it names), and size is height-only so the width follows the artwork and the aspect ratio survives any layout. The knock-on is a colour grammar worth keeping: on a matched session WHITE means ‘the device said so’ (the lockup, the words on its line, the measured column) and lime means ‘HYBRID said so’ — which is why the hero chip and the device panel’s measured figures moved off lime. Copy reads ‘Measured on’ + the lockup, a fragment the artwork finishes, so the device is never named twice. Renderers: apps/web/components/aurora/device-mark.tsx (inline SVG) and apps/mobile/components/aurora/device-mark.tsx (react-native-svg) drawing the SAME path data, so both clients are identical at every size; a connector with no artwork falls back to naming the device in text." },
  { id: "device-signature-placements", area: "Core", status: "planned", title: "Device signature — the remaining surfaces", detail: "The mark ships on the Wrapped hero, the device panel and the match sheet (device-signature-mark). Four surfaces still show a matched session with nothing saying so: the SHARE CARD (a footer receipt — lockup then the timestamp, the only surface that leaves the phone, so it uses the product name and never the athlete’s personal device name), the LOGBOOK + HISTORY rows and the WEEK RAIL + CALENDAR (the compact mark leading a measured row, answering ‘which of these numbers do I trust’ without opening anything), and CONNECTIONS (the connected state showing the lockup and the last read instead of a generic row). Two further directions from the same pitch: per-stat PROVENANCE (the mark in the corner of each measured figure, opposite the ‘~’ estimate sign — needs WrappedBasic.estimate to become a three-way basis of measured/modelled/logged) and the HANDOFF motion on match confirm (the mark travelling from the chosen candidate into the hero chip, the chip then beating at the measured avg HR). Anything on a themed surface passes on=‘light’ so the mark inks black there — the Wrapped panels are dark whatever the theme does." },

  // ---- North-star roadmap (see reference/north-star-strategy.md) ----
  // Year 1 — System of Record
  { id: "athlete-twin", area: "Data", status: "shipped", title: "Athlete Digital Twin + Performance State", detail: "computePerformanceState fuses HPI + readiness + fatigue into one object WITH ranked 'why did it move' drivers (load + recovery attribution) and a one-line summary, fed by the persisted Signal ontology. Dedicated web Performance screen: HPI cockpit + 14-day HPI/readiness trajectory (performanceTrajectory replays the log) + tissue body map. A MOBILE Performance screen too (app/performance.tsx — HPI cockpit + pillar bars, a dependency-free 14-day HPI trajectory, and the tissue-level injury-risk table), reachable from the More hub + the cockpit. Also on the dashboard, mobile Home, and grounds the AI coach. Next depth: nightly materialization/caching." },
  { id: "injury-risk", area: "AI", status: "shipped", title: "Tissue-level injury risk + return-to-play", detail: "computeInjuryRisk scores every tissue 0..100 (per-tissue ACWR + absolute load + recovery suppression) AND maps it through a versioned logistic calibration to an injury probability (RISK_MODEL_VERSION; documented prior, refit when the data network has labeled outcomes). Surfaced as a body map + per-tissue table (risk, P(injury), ACWR, drivers). Return-to-play rails (rtp.ts): 5 gated stages (acute→…→return-to-perform), the engine blocks advancement until every gate is met; RtpProtocol model + /api/rtp + a checklist panel. The calibration is a LIVE refit loop: labeled outcomes captured (RiskOutcome — positives recorded when an RTP protocol opens, plus club records fed in), refitCalibration re-fits the logistic, persisted (ModelFit) and applied everywhere once ≥30 samples exist; admin Refit on the Data Network screen, with negative-sample snapshots (/api/datanet/snapshot) so the logistic trains on both classes. RTP is auditable: every gate attestation, advance, and override (reason-required, force-advance) is appended to an immutable audit log with who + role + timestamp. WEB↔MOBILE PARITY: the mobile Aurora Performance screen now matches web — the per-tissue table carries the ACWR + top-driver columns, the trajectory plots BOTH HPI (bars) and Readiness (per-day markers) via native primitives (no chart lib), and the full gated RtP panel (tissue picker → open → gate checklist → advance/override + audit trail) ships on mobile against the same /api/rtp. The one remaining web-only piece is the anterior/posterior tissue BODY-MAP SVG (deferred on mobile — needs react-native-svg, a dep the app deliberately avoids). PLAIN-LANGUAGE GUIDANCE: the per-tissue driver is no longer an opaque English template string — computeInjuryRisk now tags each RiskDriver with a machine-readable `kind` (spike/load/detrain/recovery) plus the ACWR behind it, and both clients resolve it through localized keys (RISK_DRIVER_LABEL_KEY / RISK_DRIVER_EXPLAIN_KEY → w.injury.* EN/PL/DE). The Cockpit injury card carries a collapsible 'What's raising this?' panel that explains each active driver in plain language with what-to-do copy (e.g. a 'workload spike' = last-7-days load well above your 4-week weekly average, ACWR past ~1.3), plus a one-line ACWR gloss under 'Things to watch'; the Analyze per-tissue table (web + mobile) shows the same localized driver label and the ACWR note. BUGFIX — the degenerate 4.00 ACWR: the per-tissue table reported ACWR 4.00 on EVERY tissue for any athlete whose logged sessions all sat inside the 7-day acute window. That is arithmetic, not a spike — for such a log chronic₂₈ equals acute₇, so acute / (chronic/4) = 4.00 exactly, the formula's ceiling, identical on every tissue regardless of what was actually trained. Worse, it handed each tissue the full 55-point 'workload spike' driver, so a brand-new athlete's first week read as HIGH risk everywhere. computeInjuryRisk now gates enoughHistory the way computeLoad already did: the log must span ≥14 days (MIN_HISTORY_DAYS) AND the tissue must carry load OUTSIDE the acute window (tissueLoadWindow gained a `from` bound) — the second half matters on its own, since a tissue trained for the first time this week has no baseline however long the athlete's overall history is. With no baseline the ACWR reports a neutral 1, both clients' tables show '—', and BOTH ratio-derived drivers (spike and detraining) are held at 0; absolute tissue load and recovery suppression still score, so a new athlete gets a real risk number, just not a fabricated one. The same leak is closed on the coach console: /api/coach/squad sent load.acwr unguarded, so a squad row read '4' beneath an 'insufficient' band — it now sends 0, which both team monitors already render as '—'. This also cleans the personalization evidence set (injury-personalization): maxAcwrAt / acwrEventsFromHistory were replaying those 4.00 phantoms as 'tolerated spikes' and pushing the learned onset toward its 1.6 cap. EXPLAINED, NOT JUST BLANKED: a bare '—' where a number used to sit reads as broken data, so computeInjuryRisk now returns `awaitingBaseline` (tissues trained in the last 7 days that have no chronic base yet — a tissue simply not trained is NOT listed, so a seasoned athlete never sees the note), plus `historyDays` / `minHistoryDays`. Both clients render a plain-language panel under the per-tissue table when it is non-empty (w.injury.acwrPending / acwrPendingBody, EN/PL/DE): why the dash is there, that a number would be arithmetic (every area would read 4.00), roughly two weeks until it resolves, and that the risk score itself is still real (tissue load + recovery, minus the ratio term). The engine owns the decision, so web and mobile can't drift. The coach console gets the counterpart: the team monitors (web + mobile) add a second note under the ACWR legend, shown only when a row actually carries the 'insufficient' band (w.teams.monitor.acwrInsufficient). ONE CARD — THE TISSUE MERGE (Aug 2026): injury risk and return-to-play were two sibling cards stating the same subject twice — a risk summary that showed no tissue, and an always-open seven-chip form with a chartreuse fill for an event that happens twice a year. They are now ONE card (aurora/tissue-card.tsx, web + mobile), whose SHAPE is the signal. The engine defines overall risk as Math.max of the per-tissue scores, so the headline number IS one of the tissues — which lets the card draw a single object at two zoom levels: collapsed, one 0..100 axis carrying a tick per tissue (the heaviest tick being the overall) with band zones at 30/50/70 and a dashed FLAG LINE at 50 where a tissue joins the worklist; opened, the same tissues as ROWS on the SAME scale, each with its own risk, calibrated probability and ACWR, the flag line running straight down the block. That replaced the 5-column table which sat behind the disclosure at minWidth 420 inside a horizontal scroller (a spreadsheet you dragged sideways on a phone); the driver now prints only on flagged rows instead of being a column of dashes. The geometry is shared — tissue-axis.ts (tissueAxis / RISK_ZONES / FLAG_THRESHOLD / injuryHeadlineKey, 18 tests) — so neither client rounds its own tick positions and both speak the headline sentence from one key. Rows are a disclosure only while calm: a flagged tissue opens them itself. RTP is no longer a card but this card's deep end — the tissue chips appear only AFTER 'Log an injury' is pressed, and an open protocol (gates, advance, reason-required override, audit trail — all unchanged) takes over the card's body. Kept on the card face in every state: per-tissue risk, P. injury and ACWR, plus the model version, which keeps its footer line. Two honesty fixes fell out of the merge: the per-tissue ratio and the whole-body ACWR from computeLoad are different numbers, so the watch tiles are now labelled 'whole-body, not per tissue'; and the awaiting-baseline explanation sits directly under the rows where the dash appears. New copy in EN/PL/DE (w.injury.tissue / line.clear|elevated|high / allTissues / wholeBody / logInjury / pickArea, w.rtp.*); the console-cased 'RETURN-TO-PLAY – GATED PROTOCOLS' heading, the 'Things to watch' label over its own fallback sentence, and the 'No active protocols' empty state are retired. THE PROTOCOL, REDESIGNED (Aug 2026): the return-to-play surface was the last part of this capability still shaped like a form, and it is now rebuilt on both clients (aurora/protocol.tsx, web + mobile; presentation logic in @hybrid/core rtp-view.ts, geometry in injury-body.ts). ASKING: \"which area is hurt?\" was a ragged wrap of seven word-chips with one PRE-SELECTED — a question that arrived already answered, in our vocabulary rather than the athlete's (\"Posterior\"), under a chartreuse GO fill on the worst news an athlete ever files. It is now a SHEET showing a body you touch (see injury-body-map-primary), nothing pre-selected, the choice read back in words plus an anatomical locator underneath, and a neutral chalk primary that stays inert until the question has an answer. A SECOND REAL QUESTION was added — when it started (today / this week / longer ago, resolving through `injuryDateFor`) — because the API stamped every injury as happening the moment the protocol was opened, so day one was a fiction and the day count that follows from it was wrong. LIVING WITH ONE: a stage pill, a progress bar and a column of raw browser checkboxes were three drawings of one fact, none of which said where in the journey you stood or how long you had been in it. The protocol is now a LADDER of all six stages on one spine — the rail through the stage marks IS the progress bar. Stages behind you carry the date you entered them, recovered from the audit trail we were already keeping (and marked `forced` when they were entered by override rather than met); the current rung is the only one that opens, carrying a plain-language line about what the stage is FOR, its gates, and — only when every gate is met — the one action that leaves it. When gates remain, the honest line (\"2 gates to go\") sits where the button was, with Override as a quiet text control rather than a red pill shouting beside a lime one. Abandon had an API action and NO UI, so a protocol opened by mistake was permanent; there is now a two-step \"Close this protocol\" that keeps the record in the trail. The audit trail folds away behind a disclosure and is laid out as a timeline rather than joined strings. LOCALIZATION: every stage name and every gate criterion was a hardcoded English string from engines/rtp.ts printed straight into a Polish or German UI — they now resolve through RTP_STAGE_KEY / RTP_STAGE_SUB_KEY / RTP_GATE_KEY / RTP_ACTION_KEY (EN/PL/DE), and the seven areas through INJURY_AREA_KEY, which also renames them everywhere on the card so the rows, the axis tooltips and the protocol header stop calling the same tissue two different things. Colour discipline: the accent fill is now reserved for advancing and for being cleared — the two things that are genuinely good. 44 new tests across injury-body + rtp-view. Next: org-role gating of overrides (medical-only)." },
  { id: "admin-engine-room", area: "AI", status: "shipped", title: "Admin Engine Room — live engine transparency console", detail: "A dedicated admin section (AI → Engine room, apps/web/components/admin/engine-room.tsx) that exposes the FULL math behind the intelligence stack. It runs the real @hybrid/core engines client-side (they're pure) on either the built-in sample athlete or any real athlete's stored inputs — served by GET /api/admin/engine (admin-gated, and the support-read writes a user.engine.view audit row; returns the TrainingLog + Biometrics + live calibration so no math is duplicated server-side). Shows: headline HPI/readiness/injury-risk/p(injury) with semantic band colors; the ranked state drivers; a 14-day HPI+readiness trajectory chart with hover tooltips; the per-tissue injury table (fatigue, ACWR, the four risk components as a stacked bar — spike/load/detrain/recovery — score, calibrated probability, band); the live logistic calibration curve with the athlete's position marked and the active ModelFit version chip; an HPI weight-profile switcher (hybrid/strength/endurance); and a WHAT-IF SIMULATOR — sliders for last-7-day training scale and today's HRV/resting-HR/sleep that transform the inputs (whatIfLog/whatIfBio in @hybrid/core engine-room.ts, unit-tested) and re-run the whole stack live, with deltas vs actual. The FORMULA SHEET renders ENGINE_FORMULAS — every formula the stack runs (fatigue decay/dose/normalization, endurance saturation, bioAdj, readiness, HPI blend, sRPE, ACWR, the four injury components, band gates, the logistic calibration, and — added with the volume work — the VOLUME LANDMARK stack, the BLOCK VOLUME RAMP and FEEL TIMING) as DATA with constants + meaning, drift-guarded by tests that recompute the live engines from the documented expressions. The three newer groups are: `landmarks` (the four-layer resolution order population → profile → observed → manual; the stimulus multiplier on MV/MEV and the compounded recovery multiplier on MRV with every factor's live value; the MAV band re-derived at its proportional position; and the observed ceiling correction with its ±35% bound and two-week evidence gate), `volumeBlock` (this week's target = mev + (top − mev) × ramp, with the deload at MV), and `feelTiming` (the acute-fatigue residual curve, the timing-adjusted session cost with its strain threshold, the recall discount, and the check-in soreness-polarity conversion that documents the freshness trap in the open). Kept current with the engines as they change — the pooled recovery reading (`recovery-pooled`: soreness and energy folded onto one spentness scale, lag-adjusted, one threshold) was added when the one-card merge replaced the two raw thresholds, and a `fitnessLevel` group (level-from-relative-strength with the live entry ratios, plus the influence-weighted profile-completeness score) and `landmark-frame` (body mass read against the frame carrying it) followed the training-level work. Their constants are rendered FROM the live exports rather than hand-copied, so the sheet cannot drift by construction; the behavioural guards — that the documented expression reproduces what the engine actually computes — are mutation-tested (flipping the deload target from MV to MEV, or round to floor in the landmark scaling, each fails a named test). UNDERSTAND & COMPARE (Jul 2026, second pass): the console now goes beyond formulas to full TRACEABILITY. (1) DERIVATIONS — packages/core engines/derivation.ts builds step-by-step SUBSTITUTED arithmetic (the athlete's actual numbers plugged into each formula): deriveReadiness (per-muscle fatigue → average → base → each wearable metric's deviation × weight → clamp → final), deriveHpi (S/E/R, the weighted blend, and the limiter-gap comparison), deriveTissueRisk (acute + chronic windows → ACWR → each of the four components with real values → band → σ substitution), all ending in EXACTLY the live engine's output (drift-guard tests per derivation; biometricDeviations + tissueLoadWindow were exported from the engines so derivations reuse the same primitives). Rendered as collapsible 'How is this calculated' panels for readiness + HPI and a per-tissue picker under the injury table; derivations follow the active what-if so the math always explains the numbers on screen. (2) FEELING LAB — the one-tap check-in made inspectable: the rating→feeling thresholds (FEELING_THRESHOLDS, drift-guarded against feelingFromRating), and feelingImpacts() runs the REAL prescribeSession once per feeling so the operator sees in kg and sets what primed/good/flat/wrecked does to today's session for this athlete (×1.05 / ×1.0 / ×0.94 / ×0.85, wrecked sheds a set), with the honest note that the feeling scales the PRESCRIPTION only — it never touches HPI/readiness/risk. (3) SCENARIOS — the what-if simulator gained named scenarios: one-click presets (Crashed recovery, Eased week 50%, Overreached 150% — biometric presets are relative to the athlete's own baseline) plus save-current-sliders, all compared in one table (HPI/readiness/risk/p/flagged with deltas vs actual). (4) COMPARE ATHLETES — a side-by-side card (second athlete picker against the same audited /api/admin/engine feed): actual states only, each computed with that athlete's own inputs, calibration and personal onset — metric table, a deterministic 'biggest divergence' line naming the HPI pillar that separates them, and each side's ranked drivers, answering 'why does one athlete read better'. (5) EFFORT MODEL — a card for the per-athlete learning loop behind 'how did that feel?' (see effort-model): the learned effort bias on a bounded scale against the population prior, the rated-session count, the leave-one-out error beside the unpersonalised engine's baseline with an honest verdict either way, and the 'same work over time' fitness trend. Mobile parity for this admin section is tracked as its own planned entry (mobile-engine-room) — the shared math already lives in @hybrid/core so the native section is a render-only port." },
  { id: "admin-engine-explain", area: "AI", status: "shipped", title: "Engine Room — grounded LLM explanation layer", detail: "An 'Explain this athlete' card in the admin Engine Room backed by POST /api/admin/engine/explain (admin-gated, rate-limited 12/min, body-size capped, per-user reads audited as user.engine.explain). The server RECOMPUTES the full engine state itself — sample athlete or a real athlete's stored inputs, with the sanitized what-if transforms applied via the shared whatIfLog/whatIfBio — GROUNDED ON THE EFFORT MODEL TOO: the prompt carries a line naming how many sessions the athlete has rated, whether they report the work harder or easier than the log implies, the held-out error against the unpersonalised baseline, and the same-work-over-time trend. It has to: the log those numbers come from is personalTrainingLog, so a reported effort moves ACWR hard (the same month of training reads 1.43 or 0.40 depending only on what the athlete said it cost them), and a narrative blind to that input would confidently attribute an elevated risk to something else. Zero ratings says exactly that, rather than 'they report what the log implies' — which would be a claim about an athlete who has said nothing. The line is in the DETERMINISTIC path as well, since that is what an operator actually reads until ANTHROPIC_API_KEY is configured. So the LLM is grounded exclusively on structured engine output (HPI components + limiter, readiness + bioAdj, per-tissue risk with ACWR and per-driver point contributions, calibrated p(injury), model version), never on client-supplied numbers and never free to invent data. Claude (claude-opus-5, adaptive thinking, cached system prompt) narrates what the numbers mean and what a coach should do, contrasting simulated-vs-actual when a what-if is active. HONEST DEGRADATION: without ANTHROPIC_API_KEY (or on an API error) the endpoint returns the engines' own deterministic explanation (state summary + readinessWhy + flagged tissues) labelled 'engine fallback' with a note — same pattern as the AI coach — so the card is useful today and upgrades the moment the key is set (the same key the AI coach + nutrition scan wait on)." },
  { id: "injury-body-map-primary", area: "AI", status: "shipped", title: "Injury card — the body IS the subject (one figure, both clients)", detail: "SHIPPED on BOTH clients, as part of the protocol redesign (see injury-risk). All four parts landed. (1) A REAL SILHOUETTE: the card's nine rounded rectangles are gone. The Tissue card and the injury picker now draw the SAME schematic mannequin the exercise body-map has always used — @hybrid/core injury-body.ts derives the seven engine areas from the existing per-muscle polygons (quads; glutes; posterior = hamstrings + calves; back = traps + upper-back + lats + lower-back; chest; shoulders = front + side delts; triceps), so anatomy authored once is drawn everywhere and cannot drift. Untracked parts of the body stay faint, which makes what you can choose legible without a word of instruction. (2) TOUCH TARGETS: solved by resolution rather than by inflating shapes into each other — `nearestInjuryArea` measures a touch against each shape's centre, so the whole limb is live (a touch anywhere down the back of the arm reads as triceps) while a touch near nothing tracked resolves to NOTHING rather than a wrong answer. `injuryTouchPoint` does the letterbox-correct box→viewBox conversion in core, because mapping linearly across the rendered box mis-reads every tap near the edges — exactly where the small areas live. Both are pure and tested. (3) THE FLAG AND THE PROTOCOL ARE ONE OBJECT: touching an area on the card's risk figure opens the injury sheet with that area already answered; the word-chips are gone entirely. (4) THE MOBILE TWIN: mobile draws the identical figure via react-native-svg (already a dependency), closing a parity gap that had stood since the merge — mobile had NO body map at all. The card's chassis is unchanged: the figure sits in the opened state where the rows already are." },
  { id: "injury-personalization", area: "AI", status: "shipped", title: "Per-athlete online learning — personal ACWR spike onset", detail: "The injury engine's spike component is now personalized per athlete. packages/core engines/personal.ts: derivePersonalization() learns a PERSONAL spike onset (bounded 1.1..1.6 around the population prior 1.3) with the same shrinkage idiom the data network uses for cohort norms — spikes above the prior tolerated WITHOUT injury raise it toward what the athlete demonstrated, recorded injuries lower it (an injury at low ACWR is strong evidence of fragility), a pseudo-observation prior weight (8) keeps thin evidence near the prior, and uninformative events (no spike, no injury) carry no signal. Evidence comes from the athlete's OWN engine: acwrEventsFromHistory()/maxAcwrAt() replay the training log at each labeled RiskOutcome's date and pair the peak per-tissue ACWR with the outcome — so the flywheel that refits the population calibration (data-network) also personalizes the individual threshold. computeInjuryRisk gained an optional spikeOnset opt (spike = ramp(ACWR, onset, onset+0.9) × 55; default exactly reproduces the population 1.3/2.2 behavior — regression-tested), threaded through computeEngineTrace. Server: GET /api/admin/engine derives it from the user's RiskOutcome rows and returns it as `personal`; /api/admin/engine/explain uses the same onset so the LLM narrative matches the on-screen numbers. UI: an Engine Room 'Personal model' card shows the onset scale (prior vs personal markers), evidence counts (tolerated spikes / injuries / n), and the spike formula in effect; the per-tissue table and what-if simulator compute with the personal onset. 13 unit tests. NEXT: surface the personal onset in the consumer clients' injury explanations (today it's admin-only), and per-tissue onsets once outcome rows reliably carry the tissue." },
  { id: "per-pattern-training-age", area: "AI", status: "planned", title: "Per-movement-pattern training age (scoped MEV/MRV scaling)", detail: "Today fitness-level.ts estimates ONE global level from the athlete's best lift or run, and landmark-profile.ts applies one experience scalar to every muscle — so an elite bench presser who took up squatting last month gets advanced-scaled (×1.15) leg landmarks until the observed layer corrects them. The blast radius is bounded (stated experience always wins, the multiplier is ±15%, blocks start at MEV, and landmark-adapt corrects per muscle within two qualifying weeks) but the right shape is a training age per movement pattern / muscle group: the estimator already holds per-benchmark-lift evidence (squat/hinge/press ratios, run pace), so scope the stimulus/recovery experience factors to the patterns each muscle is trained through, with the global estimate as the fallback for untested patterns. Surface any per-pattern disagreement the same way resolveExperience does today — shown, never silently applied." },
  { id: "clearance-superposition", area: "AI", status: "planned", title: "Clearance pairs under double sessions (superposition residual model)", detail: "recovery-pairs.ts drops a clearance pair when a second session ends inside its gap — correctly conservative, because the later read measures the SUM of both sessions' residuals and attributing it to one would fit a confidently wrong personal rate. Cost: a two-a-day athlete's FIRST session of the day never pairs (the last session of the day still pairs with the next-morning check-in, so they are not starved outright — the truly starved case is 3+/day). Fix is a modelling extension, not a threshold tweak: compute the expected residual as the superposition of expectedResidual(h) over ALL sessions that ended before the read, weighted by each session's immediate cost, so contaminated reads become usable instead of dropped. Keep the identifiability discipline from feel-timing.ts — normalise against the population curve, never fit a personal time constant from a single pair." },
  { id: "mobile-engine-room", area: "Mobile", status: "planned", title: "Engine Room section in the mobile admin console", detail: "Port the web admin Engine Room (admin-engine-room) to apps/mobile/components/admin/ like the other 19 admin sections: sample/real athlete picker against GET /api/admin/engine, headline HPI/readiness/risk/p(injury), per-tissue table with the component split, what-if sliders (the whatIfLog/whatIfBio transforms are already shared in @hybrid/core), and the ENGINE_FORMULAS formula sheet. Charts use native primitives (bars/markers) like the mobile Performance screen — no chart lib." },
  { id: "ai-copilot", area: "AI", status: "planned", title: "AI Coach Copilot (grounded + agentic)", detail: "Upgrade of /api/ai-coach into an agent grounded in the Twin + the club's own methodology: drafts plans as editable objects, explains with citations to the athlete's data, proposes (never auto-commits) clinical changes. Human-in-the-loop + full audit." },
  { id: "agent-org", area: "AI", status: "shipped", title: "AI agent org — dynamic config, control & execution", detail: "An admin-controlled executive team (CEO/CFO/CMO/COO + custom roles) defined as DATA, not hard-coded prompts. agents.ts in @hybrid/core (pure + unit-tested) holds the role PRESETS and the dynamic builders: buildSystemPrompt(def) assembles the live system prompt from editable fields (mandate, responsibilities, KPIs, guardrails, escalation, tone, collaborators, tools) so changing a KPI rewrites what the agent runs on; buildAgentConfig(def) maps a definition onto the Claude Managed Agents shape; coordinatedAgents/delegateToolName/resolveEffort wire delegation + clamp effort to each model. AgentConfig model + reference/sql-agents.sql (server-only RLS — deny-by-default). CONTROL PLANE: admin CRUD at /api/admin/agents (+ /[id]) — ADMIN-gated, rate-limited, body-capped, audited; create-from-preset, edit every field, pause/resume (status), delete. EXECUTION PLANE: /api/admin/agents/[id]/run executes an active agent on a task via the Messages API using its generated prompt (apps/web/lib/agent-runtime.ts) — an EXECUTIVE runs an agentic loop that exposes its reports as delegate_to_<role> tools and, when it delegates, the orchestrator runs that functional agent (its own prompt/model) and feeds the result back: a real coordinator→functional hierarchy on plain tool use (turn- and token-bounded), audited (agent.run). TWO RUNTIMES (selectable per agent): 'messages' — stateless Messages-API run with the coordinator→functional delegation above (apps/web/lib/agent-runtime.ts); 'managed' — a Claude Managed Agents session with a durable MEMORY STORE mounted so the agent remembers across runs (apps/web/lib/managed-runtime.ts, lazily creates+reuses the managed agent + memory store, ids persisted on the row). STREAMING: /api/admin/agents/[id]/stream sends live progress over SSE (text deltas + delegation boundaries); /run is the non-streaming JSON twin. RUN HISTORY: every run is persisted to AgentRun (reference/sql-agent-runs.sql); read per-agent via /api/admin/agents/[id]/runs AND across the org via /api/admin/agent-runs (surfaced in the Agent HQ → Reports tab, status-filterable). SCHEDULED RUNS: AgentSchedule (reference/sql-agent-schedules.sql) holds standing tasks per agent on a cadence (hourly/daily/weekly); a Vercel Cron (apps/web/vercel.json) hits /api/cron/agents — auth'd by CRON_SECRET, NOT admin — which runs every due schedule on an active agent, records the run (ranBy 'scheduler') and rolls nextRunAt forward; managed per-agent in the editor's Schedules section. Admin console: a command-center DASHBOARD (AI → Agent HQ, /api/admin/agents/overview) — Command center (headline stats incl. 7-day DOLLAR COST via core costUsd/MODEL_PRICING, an org chart with live status, a 7-day activity chart, a recent-activity feed, upcoming scheduled work, and a 'needs attention' count), SCORECARDS (per-agent: success-rate vs a 90% target, runs/cost 7d, last run, and KPI TARGET-VS-ACTUAL — KPIs carry an optional numeric target, admins log numeric actuals inline (AgentKpiMeasurement), shown as % of target + a trend sparkline + an expandable actual-vs-target trend chart over time with a target reference line), a WORK board (drag-to-assign an agent onto a dropzone + quick run + queued/recent columns), an INBOX (PERSISTENT, dismissible notifications — AgentNotification, written on run failure, mark one/all read — plus schedules that can't fire, with an unread badge), and a REPORTS tab (the org-wide run feed, exportable to CSV via /api/admin/agent-runs/export or print-to-PDF). Actual 30-day agent run spend (tokens × model list price via core costUsd) also feeds the admin Financials console as a real cost callout. The builder screen (AI → AI agents): roster with status/model/effort, a full editor (KPI/responsibility/guardrail list editors, model+effort+authority+runtime selects, tool toggles, Schedules), a LIVE system-prompt preview, a Run panel that STREAMS the agent's output + delegation trace + token usage live, and a per-agent History view. Live runs need ANTHROPIC_API_KEY server-side (the same key the ai-coach uses); scheduled runs additionally need CRON_SECRET; the spend-causing actions (run/stream/schedule) go through requireAgentOperator — restrict them to specific admins by setting AGENT_OPERATOR_EMAILS (comma-separated) in the server env (unset = every admin is an operator, back-compatible). SPEND GOVERNANCE: per-agent APPROVAL GATES (approvalThresholdUsd — a run whose estimated cost ≥ the threshold is held as an AgentApproval and must be approved by a DIFFERENT operator, who triggers the execution; Approvals tab in HQ with a pending-count badge) and per-agent BUDGET CAPS (budgetUsd7d — when trailing-7-day spend reaches the cap the agent is auto-paused + a notification raised; enforced on every manual and scheduled run). DAILY DIGEST: a Vercel Cron (/api/cron/agent-digest, CRON_SECRET) posts a 24h run summary (count, success rate, $ spend, top agents, failures) to Slack via SLACK_WEBHOOK_URL; previewable + send-now in the HQ Command center (/api/admin/agents/digest). MONTHLY COST REPORT: per-agent monthly spend — current + previous month in the HQ Command center with CSV download (/api/admin/agents/cost-report) and a Vercel Cron (/api/cron/agent-monthly, 1st of month) that Slacks the prior month. PER-AGENT TIMELINE: a unified activity feed in the agent editor (config edits from the audit trail + runs + approvals, /api/admin/agents/[id]/timeline). SLACK INTERACTIVE APPROVALS: approval requests post to Slack with Approve/Deny buttons; the callback (/api/slack/interactivity) verifies the Slack request signature (SLACK_SIGNING_SECRET), executes the decision (idempotent on retry), and replaces the message — needs a Slack app with interactivity pointed at that URL (web Approvals enforce the two-person rule; Slack records the Slack approver). without them the endpoints return an honest 'unconfigured'/'not configured' note and the rest of the screen still works. The managed runtime additionally needs the managed-agents beta (can't be exercised from this sandbox — Supabase + the API are out of reach here); reference/agent-managed-smoke-test.md documents the deployed verification. NOTE: run reference/sql-agents.sql, sql-agent-runs.sql, sql-agent-schedules.sql, sql-agent-kpi-notifications.sql, then sql-agent-approvals.sql in Supabase. Optional env: SLACK_WEBHOOK_URL (digest/report/approval delivery), SLACK_SIGNING_SECRET (Slack interactive approvals), AGENT_OPERATOR_EMAILS (restrict run/spend)." },
  { id: "agent-scheduled-runs", area: "AI", status: "blocked", title: "Scheduled agent runs (cron)", detail: "The scheduling layer of the agent org (see agent-org) is BUILT: AgentSchedule (hourly/daily/weekly per agent), the editor's Schedules section, and /api/cron/agents which runs every due schedule on an active agent, records it (ranBy 'scheduler') and rolls nextRunAt forward. A Vercel Cron in apps/web/vercel.json fires it (default daily 08:00 UTC). Manual + streamed runs are already LIVE (ANTHROPIC_API_KEY is set — see ai-coach); only the SCHEDULED path is gated on the cron credential.", blockedBy: "Set CRON_SECRET in the Vercel env (Vercel Cron sends it to /api/cron/agents as a Bearer token). Until then the endpoint returns 503 'cron not configured' and schedules never fire." },
  { id: "agent-slack-approvals", area: "AI", status: "blocked", title: "Slack interactive approvals", detail: "Approval requests post to Slack with Approve/Deny buttons (postSlackApproval); the callback /api/slack/interactivity verifies the Slack request signature (verifySlackSignature) and runs the shared decideApproval (idempotent on retry / double-click). Code is COMPLETE and typechecks. KNOWN LIMITATIONS — (1) couldn't be exercised from the build sandbox (no live Slack app / network); verify the round-trip once configured. (2) Approve executes the held run SYNCHRONOUSLY, which can exceed Slack's ~3s ack window — the run still completes and the message is replaced with the outcome, but Slack may briefly show a timeout; it's idempotent so no double-run. The clean fix is ack-immediately-then-run via next/server after() or a queue. (3) The two-person rule (a DIFFERENT operator must approve) is enforced only for WEB approvals, where the operator's email is known; the Slack path records the Slack approver but does not block self-approval — mapping Slack user IDs → operator emails is needed to extend it. The web Approvals tab is the fully-governed path; Slack is a convenience.", blockedBy: "A Slack app with Interactivity enabled, request URL pointed at /api/slack/interactivity, plus SLACK_SIGNING_SECRET and SLACK_WEBHOOK_URL in the server env. Optional hardening: after()/queue for the 3s ack, and a Slack-user→operator map for the two-person rule over Slack." },
  // Year 2 — Risk & Teams
  { id: "org-graph", area: "Backend", status: "shipped", title: "Team Operating System (Org Graph)", detail: "Organization + self-referential Team hierarchy + Membership with roles (OWNER/DIRECTOR/COACH/MEDICAL/ANALYST/ATHLETE). Access scoped by role × data sensitivity AND by team subtree in core (org.ts canSeeAthlete/visibleTeamIds, unit-tested). Operational: managers invite staff/athletes by email — existing users join immediately, others get a pending OrgInvite claimed automatically on first sign-in (revocable). Members read an athlete's Twin via /api/org/[id]/athlete/[uid], gated by role (tissue-level injury detail is medical-tier) AND by team scope (a U16 coach sees only their subtree). DB: prisma models + reference/sql-org-graph.sql + sql-org-invite.sql. Next: board reporting, athlete promotion carrying history." },
  // Year 3 — Intelligence & Video
  { id: "video-intel", area: "AI", status: "shipped", title: "Video intelligence (markerless motion analysis)", detail: "Analysis engine shipped (video.ts): consumes pose-keypoint frames → joint angles, rep counting, L/R asymmetry, depth, and a 0..100 technique score with flags; emits an asymmetry Signal that feeds the Twin's injury risk (technique breakdown lines up with fatigue — the fusion Hudl lacks). VideoAnalysis model + /api/video + a Video screen (lists your real recordings; no demo data). Mobile parity: app/video.tsx. 10 unit tests. Remaining integration: on-device/phone pose-estimation capture to produce the frames (native client) — the only way to create an analysis." },
  { id: "competition-intel", area: "AI", status: "shipped", title: "Competition intelligence + peaking optimizer", detail: "Peaking optimizer shipped (peaking.ts): set an event date and optimizeForEvent back-solves the macrocycle to the weeks available and projects a fitness–fatigue–form curve (Banister impulse-response) so the form peak lands ON the event — finals, not heats. Event model + /api/events + a Competition screen (macro timeline + projection chart + 'peak lands on event' readout). Mobile parity: app/competition.tsx. 5 unit tests. Next: opponent/field-strength models from results data, environment-aware load (heat/altitude/time-zone)." },
  // Year 4 — Network & Talent
  { id: "talent-graph", area: "Data", status: "shipped", title: "Talent Graph + benchmarks", detail: "benchmarks.ts: age/sex/sport percentile norms (normal-CDF over documented priors, BENCHMARK_MODEL_VERSION) + maturation-adjusted projection that separates talent from early physical maturity (a youth at the adult median reads exceptional potential). HPI pulled live from the Twin. TalentProfile model + /api/talent (own report) + /api/talent/search (consent-gated discovery — only 'discoverable' profiles, rank by percentile or potential) + a Talent screen. Mobile parity: app/talent.tsx (profile/benchmarks/discovery). 'LinkedIn for athletic talent', v0. Next: refit norms on the real population dataset; richer cohorts." },
  // ---- Year 5 — vertical expansion ----
  { id: "tactical-vertical", area: "AI", status: "shipped", title: "Tactical / SOF readiness", detail: "tactical.ts: a Deployment Readiness Index fuses the Twin (HPI + injury availability) with occupational capacity (load carriage, work capacity) into a duty status (ready/qualified/limited/non-deployable), with a hard medical gate, plus a unit-level go/no-go rollup. /api/state + a Tactical screen (personal DRI + illustrative unit board). Mobile parity: app/tactical.tsx. 6 unit tests. Next: plug real units through the Org Graph; tactical-specific capacity tests." },

  { id: "longevity-vertical", area: "AI", status: "shipped", title: "Performance medicine / longevity", detail: "longevity.ts: estimates biological age vs chronological from the Twin's recovery markers (resting HR, HRV, VO₂, sleep) with documented marker priors, plus a healthspan score + flags. Longevity screen prefills markers from the Signal ontology. Mobile parity: app/longevity.tsx. 4 unit tests. Heuristic v0 (not a diagnostic); blood markers (bloodMarker SignalKind) + data-network refit are next." },

  { id: "data-network", area: "Data", status: "shipped", title: "Data network effects (the moat)", detail: "datanet.ts: aggregates consented observations into cohort norms with k-anonymity (≥5), shrinkNorm refits the synthetic priors toward observed data as it accumulates, and refitCalibration re-fits the injury logistic on labeled outcomes (gradient descent from the prior). Admin /api/datanet + a Data Network screen surface the benchmarking-intelligence aggregate (the sellable data layer, not raw rows). The flywheel is wired; it sharpens as the population grows. OFFLINE EVALUATION (Jul 2026): the learning loop now scores itself — datanet.ts gained brierScore (calibration error of any coefficient set on the labeled outcomes), rocAuc (rank-based Mann–Whitney with tie handling — coefficient-free, so it evaluates the heuristic score's ranking power itself) and reliabilityBuckets (predicted-p bins vs observed injury rate — the calibration diagram), all unit-tested; /api/datanet computes them on the stored RiskOutcome set for BOTH the live ModelFit and the documented prior, and returns the fit HISTORY (last 12 ModelFit rows). The Data Network screen renders a Model-evaluation card (AUC + live-vs-prior Brier with an honest 'refit beats the prior / prior still ahead' verdict and honest empty states when a class is missing), a reliability diagram (dots vs the perfect-calibration diagonal, per-bin n in the tooltip), and the fit-history table with the live version chipped. Next: persist refit norms back into the benchmark engine + a federated/clean-room export for federations." },

  // ---- Planned features ----
  { id: "coach-layer", area: "Web", status: "shipped", title: "Coach layer", detail: "CoachLink mutual-consent invites (accept/decline), roster, per-client sessions, and coaching notes incl. private (never shown to the client). Coach analytics dashboard computes from the real roster. Authorized by the relationship in the API. On web + mobile (the mobile Coach tab + plan enrollment hit the same API)." },

  // ---- Social layer + coach marketplace ----
  { id: "social-engine", area: "Core", status: "shipped", title: "Social engine (feed – privacy – leaderboard – compare)", detail: "packages/core/src/social.ts — the pure, unit-tested heart of the social surfaces, built ON the existing engines so social numbers match the rest of the app (recap.weeklyRecap, habits.streak, session.totalVolume/bestE1rmByLift, records.newPrsInSession, activity.relativeTime). Exports: normalizeHandle/isValidHandle/suggestHandle (the @handle rules used by both clients + the API); relationTo (derives self|none|following|follower|friend|close from the follow edges — friend = mutual active follow) + canViewResults (the visibility×relation privacy gate: public|followers|private, close-friends override); buildSocialFeed (turns followees' sessions into a sorted feed of completed-session + PR items, each anchored by (subjectType, subjectId) for kudos/comments, close-friends boosted); friendLeaderboard (ranks a circle by weekly volume/sessions/distance/active-days/streak/PRs); compareAthletes (head-to-head on the week's training + all-time bests on shared lifts, with a per-line scoreline); profileStats (lifetime totals for a profile card). 25 unit tests in social.test.ts. Consumed identically by web + mobile via the @hybrid/core barrel." },
  { id: "social-profiles", area: "Web", status: "shipped", title: "Public profiles + @handles + privacy", detail: "Every user can claim a public @handle (SocialProfile: handle, displayName, bio, avatar, visibility, showcase) and choose who sees their RESULTS — public | FOLLOWERS-ONLY (the default) | private — while the profile CARD stays searchable regardless. The privacy gate (canViewResults) is enforced server-side on the feed, leaderboard, compare and the profile-stats reads, and mirrored as defense-in-depth RLS. APIs: /api/social/profile (GET my profile + suggested handle + lifetime stats, PUT to claim/update), /api/social/profile/[handle] (GET a card, privacy-gated stats, the viewer's relation + follow state), /api/social/search (find people by handle/name). The public profile is MERGED into the one account Profile ('You') screen — there is no separate 'My profile' nav item. Web: components/social-profile.tsx renders embedded inside components/aurora/profile.tsx (claim/edit the handle + privacy, stats + connections); a reusable ProfileDrawer views anyone. Mobile: components/aurora/my-social-profile.tsx renders inside components/aurora/profile.tsx ('You' tab); components/social-kit.tsx ProfileModal views anyone. Template-aware on web (radii soften under Aurora); native on mobile. NOTE: run reference/sql-social.sql (tracked as social-schema)." },
  { id: "social-follow", area: "Web", status: "shipped", title: "Follow + friends + close-friends graph", detail: "An asymmetric follow graph with two richer tiers, exactly as scoped: you FOLLOW anyone (active immediately for public/followers profiles; a follow of a PRIVATE profile lands PENDING until they approve via /api/social/follow/respond); a mutual active follow makes you FRIENDS (derived, no extra table — friends unlock the leaderboard + richer compare); and you can mark a followee a CLOSE FRIEND (a curated inner circle that's boosted to the top of the feed). Follow model = (followerId, followeeId, status active|pending, closeFriend). APIs: /api/social/follow (POST/DELETE), /follow/respond (approve/deny a pending request), /close-friend (toggle), /connections (followers/following/friends/requests), /suggestions (people-you-may-know from friends-of-friends + a shared coach). Web: the discover screen (components/social-discover.tsx, search + suggestions + follow) + the connections tabs inside the account Profile screen. Mobile: app/discover.tsx + the connections tabs inside the Profile ('You') screen." },
  { id: "social-feed", area: "Web", status: "shipped", title: "Activity feed + kudos + comments", detail: "A real cross-athlete activity feed (built by buildSocialFeed from your active-followees' REAL logged sessions + the PRs detected in them — no fabricated posts), with your own activity woven in. Each item carries kudos (👏) + threaded comments, anchored by (subjectType, subjectId) so reactions attach to derived items without a materialized posts table. APIs: /api/social/feed (the engine feed enriched with kudos/comment counts + whether I've cheered each item), /api/social/kudos (toggle), /api/social/comments (GET/POST). Web: components/social-feed.tsx (feed nav) — cards with cheer + inline comments, tap an author → ProfileDrawer. Mobile: app/feed.tsx with the same. A compact FEED STRIP also sits in the CONNECT section of Today/Home (components/aurora/feed-preview.tsx on both clients) — the latest few items, Instagram-Threads style, tapping through to the full Feed; it renders nothing when the feed is empty. A STORIES RAIL (components/aurora/stories.tsx on both clients) now leads the top of Today: the distinct authors of the same /api/social/feed shown as IG-style avatar bubbles (a ring = recent activity), led by your own 'Your story' bubble that opens the feed to post; it invents no friends (empty feed → just your story). IDENTITY / PRIVACY: a card leads with the athlete's real name (User.name / SocialProfile.displayName) — an email address is NEVER shown; authorCards no longer derives a handle from the email local-part (opaque id-slice fallback instead) and carries a hasProfile flag so the feed hides a synthetic @handle entirely (a profile-less athlete renders as just their name, never '@a1b2c3d4'); feedCardView falls back to '@handle' only for a genuine handle. Push delivery of kudos/follow notifications is the one piece still pending (see push-notifications)." },
  { id: "social-leaderboard", area: "Web", status: "shipped", title: "Friends leaderboard", detail: "A weekly leaderboard across your FRIENDS (mutual follows) + you, ranked by a switchable metric — volume (kg), sessions, distance (km), active days, current streak, or PRs — all computed by friendLeaderboard off everyone's real sessions (privacy already satisfied: friendship is mutual consent). /api/social/leaderboard?metric=. Web: components/social-leaderboard.tsx (leaderboard nav, metal medals, you highlighted, tap a rival → compare). Mobile: app/leaderboard.tsx with a horizontal metric switch." },
  { id: "social-compare", area: "Core", status: "shipped", title: "Head-to-head friend comparison", detail: "compareAthletes (social.ts) scores you vs another athlete line-by-line on the week's training (volume, sessions, distance, active days, streak) PLUS all-time bests on the lifts you BOTH train, with a headline scoreline (who leads more lines). Gated by the same privacy rule as the feed — you must be allowed to see their results. /api/social/compare?handle=. Surfaced inside the profile drawer/modal on both clients (a 'Compare' action from the feed, discover, leaderboard or a profile). Generalizes the math behind the coach-only cross-roster comparison so peers get it too." },
  { id: "coach-marketplace", area: "Web", status: "shipped", title: "Coach marketplace (directory + storefronts + start a program)", detail: "Turns the previously invite-ONLY coaching system into a discoverable marketplace: any user can browse/search a directory of coaches (verified first, with rating + published-program count + sport/specialty filter), open a coach's public STOREFRONT (CoachProfile: headline, bio, specialties, sports, accepting-clients, price note), and START an online program with one click — a CLIENT-initiated enrolment (the inverse of the existing coach→client CoachInvite). Starting a program opens a CoachLink (PENDING, or ACTIVE when the coach set autoAccept) + a ProgramEnrollment, and the coach accepts/declines from their storefront; CoachProgram gains published/summary/level/visibility so a coach lists a program to the world. Reuses the whole existing CoachLink/CoachProgram/Assignment machinery — once active the coach programs against the client exactly as before. APIs: /api/coaches (directory), /api/coaches/[handle] (storefront + published programs + reviews + my state), /api/coaches/enroll, /api/coach/profile (GET/PUT the coach's own storefront), /api/coach/enrollments (list + accept/decline). Web: components/coaches.tsx (coaches nav — directory + coach detail drawer + a 'My coaching' storefront editor for coaches). Mobile: app/coaches.tsx (directory + coach modal + storefront). FREE enrolment in this build; PAID checkout is a separate blocked layer (social-paid-coaching). NOTE: run reference/sql-social.sql." },
  { id: "coach-reviews", area: "Web", status: "shipped", title: "Coach ratings & reviews", detail: "Clients rate (1–5) and review a coach; only an athlete with a real (active/ended) CoachLink may review, one review per coach↔client, and the storefront shows the average + count (verified-client reviews, not anonymous spam). CoachReview model; /api/coaches/[handle]/reviews (GET/POST). Surfaced on the coach storefront drawer/modal on both clients." },
  { id: "coach-rail-marquee", area: "Core", status: "shipped", title: "Follow-a-coach rail — marquee card redesign", detail: "The Today/Explore coach rail (web + mobile aurora/coach-rail.tsx, at parity) redesigned from the cramped 220px chip card to a 290px MARQUEE card — the winning concept from the design/follow-coach-redesign-ideas.html study, applied to every coach as a swipeable slider. Each card: an accent wash bleeding from the top corner, an accent-ringed avatar with the initials + verified check in the coach's accent-text tone, the name in the display face, ONE non-wrapping mono specialty line ('OLYMPIC LIFTING – PEAKING' — replaces the raggedly-wrapping chips), an athlete pull-quote doing the selling (DiscoverCoach.quote, falling back to the coach's own headline for real marketplace coaches until storefronts expose a featured review), and a bottom-pinned proof strip (★ rating / reviews / years coaching — cells drop when unknown). Fixes the four sins of the old card: ragged chip wrapping, too-narrow width, no social proof, and no shared card geometry. Data: DiscoverCoach gains optional quote + years (mapped from the marketplace API when present; seeded on the placeholder people)." },
  { id: "social-feed-posts", area: "Core", status: "shipped", title: "Shareable feed posts (status updates + share-a-PR-card)", detail: "First-class feed posts on top of the derived (session/PR) feed: a user shares a STATUS update or a PR CARD (attach-my-latest-PR computes their current best lift server-side) to their followers. Post model (kind status|pr|workout, text, data Json); reactions reuse the (subjectType,subjectId) anchoring with subjectType 'post' (kudos/comments whitelists extended). buildSocialFeed now merges each author's posts into the sorted feed (close-friend boosted, same as sessions). APIs: POST /api/social/posts (text + attachPr → server computes the PR card via bestE1rmByLift), DELETE /api/social/posts/[id] (also clears its kudos/comments). A composer (status + 🏆 attach-latest-PR) sits atop the Feed on web (social-feed.tsx) + mobile (app/feed.tsx), with delete on your own posts. Posts respect the same follow/privacy/block gate as the rest of the feed. Pure feed-merge unit-tested. NOTE: re-run reference/sql-social.sql (idempotent) to add the Post table. NEXT: a 'Share to feed' button on the post-workout summary (the shareable story-slide moment) + photo attachments." },
  { id: "social-i18n", area: "Core", status: "shipped", title: "Localize the social + marketplace surface (EN/PL/DE)", detail: "The whole social/marketplace surface is now EN/PL/DE, matching the rest of the Aurora app. The web social-* screens and their mobile app/* twins share ONE key set so both clients read the same strings. DONE (all shipped): (1) the Today/Explore COACH RAIL (w.explore.coach*); (2) the COMMUNITY CORE — Feed (composer, cheer/comment, empty, delete/error), Discover (find-friends, search, suggestions, the coach reason tag), Leaderboard (title/sub/empty/You), and the shared follow/profile-view primitives (FollowButton relations, Stars 'no reviews', verified-coach tooltip, avatar alt, profile-modal stats, block/report confirms, private-results, top lifts, compare header) — web social-feed/discover/leaderboard/ui/profile.tsx + mobile app/feed,discover,leaderboard.tsx + social-kit.tsx; (3) the COACHES MARKETPLACE — directory (title/sub/tabs/search/empty/cards, 'N programs' plural, '– full'), the coach-detail storefront a client sees (programs, week/day preview, enrol, reviews), and the coach's own storefront editor (field labels + placeholders, accepting-clients/auto-accept, publish, enrolment accept/decline) — web coaches.tsx + mobile app/coaches.tsx; (4) the PROFILE-EDIT / identity settings forms — the focused field editors (name/handle/display-name/bio/email/visibility with live handle-availability copy) and the sectioned Photo/Identity/Contact/Visibility layout — web social-profile.tsx editor + mobile my-social-profile.tsx + app/profile-edit.tsx. All keys in i18n-web/home.ts (w.social.* + w.coaches.* + w.profile.*, EN/PL/DE), reusing common.* for close/cancel/loading/error/save/done. Handle rules, block/report confirms and the taken/available lines interpolate {h}/{n} at the call site." },
  { id: "social-leaderboard-clubs", area: "Core", status: "planned", title: "Club & challenge leaderboards", detail: "The leaderboard is friends-only (mutual follows). Add club/challenge leaderboards — a named group or a time-boxed challenge (e.g. 'most volume in March', a Hyrox prep cohort) anyone can join, ranked by the same friendLeaderboard metrics. Ties into the Org graph (a team is already a group of users) and the accountability loop." },
  { id: "social-avatar-upload", area: "Integrations", status: "blocked", title: "Profile photo upload (avatars)", detail: "The profile editor takes an avatar IMAGE URL (and renders it), but there's no in-app image upload — users must host the image elsewhere. Real upload needs a Supabase Storage bucket + signed-upload policy + an image picker on each client (web file input; mobile expo-image-picker). Initials monograms are the fallback, and the profile-settings-redesign added one-tap branded GRADIENT PRESETS (AVATAR_PRESETS — small PNG data-URIs that persist + render on both clients today) so people have a non-default avatar without a photo. A disabled 'Upload photo (soon)' button is already in the editor UI on both clients; only the actual photo write is blocked.", blockedBy: "A Supabase Storage bucket (e.g. 'avatars') with an RLS upload policy scoped to the owner, then wire the existing 'Upload photo (soon)' button to the upload (web <input type=file> → signed upload; mobile expo-image-picker, which is already installed). The avatarUrl column + rendering + the picker UI already exist." },
  { id: "social-safety", area: "Backend", status: "shipped", title: "Block + report (social safety)", detail: "Block model (mutual invisibility): a blocked pair disappears from each other's feed, search, suggestions, leaderboards and compare, can't follow, and blocking tears down any follow edges both ways. /api/social/block (POST/DELETE). Reporting reuses the existing Report model + admin moderation queue — /api/reports now accepts targetType 'socialProfile' and 'comment' (existence-checked, deduped, rate-limited). Block + Report actions on the profile drawer/modal on both clients. blockedIdsFor() is applied across all the social read paths. NOTE: re-run reference/sql-social.sql (idempotent) to add the Block table." },
  { id: "social-schema", area: "Data", status: "shipped", title: "Social + marketplace schema (Supabase tables + RLS)", detail: "The social/marketplace models (SocialProfile, Follow, Kudos, Comment, CoachProfile, ProgramEnrollment, CoachReview + the new CoachProgram columns) are in prisma/schema.prisma and reference/sql-social.sql (idempotent CREATE TABLE / ALTER + RLS, consistent with the existing app_user_id() policy approach). The agent can't reach Supabase/Postgres from this sandbox, so the SQL must be run by hand. Every /api/social/* and /api/coaches/* route soft-degrades (P2021/P2010) to empty until then, so the app stays deployable. APPLIED: sql-social ran in production via sql-pending.sql (Jul 2026) — the social + marketplace APIs now serve real tables." },
  { id: "social-paid-coaching", area: "Backend", status: "blocked", title: "Paid coaching programs (marketplace checkout)", detail: "The marketplace ships with FREE enrolment (start a program → a coaching relationship, no charge). Charging for an online program/package reuses the already-built billing abstraction; it's gated on the same Stripe credentials as the rest of billing — see `billing` and `full-billing-stripe`. The CoachProfile.priceNote is free-text marketing copy until then.", blockedBy: "A Stripe account + keys in the server env (see the `billing` / `full-billing-stripe` capabilities). Then add a checkout step to /api/coaches/enroll and gate ProgramEnrollment 'active' on payment." },
  { id: "plans-enroll", area: "Backend", status: "shipped", title: "Plan enrollment", detail: "Enrolling in a plan builds a macrocycle from the engine and persists it (POST /api/macrocycles); Periodize renders your enrolled season. Both clients enroll from the Plans screen (web fetch; mobile enrollPlan)." },
  { id: "plans-leave", area: "Backend", status: "shipped", title: "Leave / delete an enrolled plan", detail: "DELETE /api/macrocycles/[id] ends a self-enrolled season (ownership-checked, mirrors /api/sessions/[id]). The athlete explicitly chooses whether to KEEP their logged workouts (default — History/analytics untouched) or ALSO DELETE the Session rows logged during the plan's active window (startedAt → the next-started season, since sessions carry no planId and the plan↔session link is derived); the destructive branch is armed by a typed-DELETE confirm. The plan's PlanDayOverride skips/postpones are cleared either way (best-effort if the table isn't migrated). Surfaced as a QUIET 'Leave plan' text link at the BOTTOM of the enrolled plan's own detail page on BOTH clients (LeavePlanSection in web + mobile aurora/plans.tsx) — deliberately NOT a persistent button (a product decision: an ever-visible exit reads as an invitation to quit and demotivates); the Plans root keeps an info-only 'Current plan' card with no leave affordance. Localized EN/PL/DE (w.train.plans.leave*)." },
  { id: "plans-leave-goal-only", area: "Web", status: "shipped", title: "Leave UI for goal-only enrollments", detail: "A season enrolled WITHOUT a named plan (Macrocycle.planId null — e.g. goal-only onboarding or a coach-programmed season) has no plan detail page to host the quiet leave link, so BOTH clients render the shared LeavePlanSection at the bottom of the Periodize (season) screen for planId-null seasons only (named-plan seasons keep their single exit on the plan's own page). Same keep-vs-delete-history flow + typed-DELETE confirm. Known sliver: on WEB the Periodize screen is gated off the free/casual persona, so a casual + goal-only user has no web leave surface (mobile Periodize is ungated and covers them); acceptable for now — revisit if casual goal-only enrollment becomes a real path." },
  { id: "plan-arbiter", area: "Core", status: "shipped", title: "Plan-as-arbiter — unify Plans + Sport + daily prescription", detail: "Three engines independently answer 'what should I train?' on different horizons: Plans/periodization (engines/periodization.ts) sets the SEASON arc (phase, load vs recovery week); the Sport engine (sports.ts → prescribeForSport) picks today's transferable S&C from the athlete's e1RM; and the daily route (engines/prescription.ts → prescribeSession) emits a session from readiness math. They used to overlap (the same lift twice) or pull against each other (a heavy daily lift in a deload week) with no coordination. reconcilePlan (engines/reconcile.ts, pure + 7 unit tests) makes the enrolled macrocycle PHASE the arbiter: the current microcycle's intensity/volume is the WEEK'S ENVELOPE (via currentPhase()), and the daily + sport movements are dosed WITHIN it — working loads scaled toward the phase intensity, set counts toward the phase volume (clamped 0.6–1.15× load, 0.5–1.2× volume, plate-rounded). Overlap is resolved by priority: the readiness-aware daily primary lift owns its movement and a sport block naming the same lift is dropped as a duplicate; a recovery/deload week trims accessory transfer work and conditioning rounds so a planned deload isn't undone by bolt-on sport volume. Returns one ordered session (strength → sport transfer → conditioning), the envelope + factors, the dropped movements with reasons, and a plain-language why. SURFACED as a shared 'This week' card (components/reconciled-week.tsx) on the web Today AND Periodize screens, and mirrored natively on the mobile Today — phase + envelope + the single reconciled session (each block tagged daily/sport, with what was dropped), built from the enrolled season (currentWeek derived from the macrocycle's startedAt), the daily prescription, and the athlete's saved sport selection. MATERIALIZED: scheduleWeek (reconcile.ts) + reconciledToSessionBlocks lay the reconciled session across the week's training days (even-spread offsets), and a 'Schedule this week' action writes them as self-authored Assignments via POST /api/assignments (athlete = assignedBy = me, capped at 14) — they land on the Calendar (engines/calendar.ts) alongside coach assignments. Because every day comes from ONE phase-arbitrated plan, the dated rows can't collide with each other. The week is VARIED by SEQUENTIAL re-prescription, not a hard-coded rotation: buildTrainingWeek prescribes each training day off a log that already carries the simulated fatigue of the earlier generated days this week (real sessions aged forward, each generated day inserted at its offset), so the engine naturally avoids the muscles it just hammered and the rotation is EMERGENT — a heavy squat today is why tomorrow picks a press. Each day still reconciles against the phase and gets a round-robin share of the sport transfer work; today's wearable reading only colours day 0. The Schedule action uses it (scheduleWeek remains the simple repeat-one primitive). AVAILABILITY-AWARE: days/week is no longer fixed — trainingDaysPerWeek (habits.ts) infers it from the athlete's actual recent cadence (median distinct active days/week), falling back to their onboarding answer (persisted client-side as hybrid.daysPerWeek) before there's history; surfaced in the Schedule button (e.g. '– 4d'). COACH-SIDE: the coach client detail (components/coach.tsx) has a 'Generate a periodized week' action — pick a goal, and the SAME buildTrainingWeek runs on the client's real logged sessions (loads dosed off their numbers, days/week from their cadence) first PERSISTS the macrocycle to the client (POST /api/coach/links/[id]/macrocycle, CoachLink-gated; matching active-coach RLS in reference/sql-coach-macrocycle.sql) so the client's Periodize/Today show the same season the coach programmed against, then assigns the week. RE-SYNC OFF REAL RESULTS: scheduling is idempotent and refreshable — POST /api/assignments accepts replace:true, which clears the upcoming, still-pending self-authored days (today onward, completed + coach days untouched) in one transaction before writing the new set, so re-running regenerates the rest of the week off your ACTUAL logs (not the up-front simulation) and double-tapping never duplicates. AUTO RE-SYNC (event-driven): weekNeedsResync (reconcile.ts) flags a self-scheduled week whose pending future days were generated BEFORE the latest logged session; web Today/Periodize + mobile Today watch for a NEWER session (the screens re-render on a fresh log; mobile reloads on tab focus via useFocusEffect) and, keyed on the latest-session timestamp, regenerate the rest of the week once per new session — so logging a day automatically re-prescribes the remainder off that real result. COACH WEEK PICKER: the coach generator surfaces the season's weeks (Wk N – phase, deload-flagged) so they can program any week's stimulus (peak/deload), not just week 1. 16 reconciler/cadence unit tests. NEXT: nightly server-side regeneration so the week refreshes even if no client opens, and richer coach controls (event-anchored seasons, multi-week blocks)." },
  { id: "i18n", area: "Core", status: "shipped", title: "Localization (EN/PL/DE)", detail: "Shared i18n in core (base dictionary + per-domain web bundles), persisted language switchers on web + mobile, 1562 keys at full EN/PL/DE parity (no missing/extra keys per language). FULL SCREEN COVERAGE on both clients: every web Aurora screen (incl. the onboarding wizard, previously hardcoded EN) and ALL ~28 mobile Aurora screens (Home, Cockpit, AI-coach, Builder, Calendar, Check-in, Competition, Connections, Exercises, Force-plate, Longevity, Nutrition, Onboarding, Performance, Periodize, Profile, Progress, Run-track, Tactical, Talent, Trends, Velocity, Video, Volume, Welcome, global-nav, plus the earlier Today/Train/History/More tabs, live Workout + summary, Plans/Sport/Coach) now resolve through t() — including native dialogs, capability/blocked notes, env hints and empty states. A PL/DE correctness audit also fixed real mistranslations (e.g. PL 'bój'→'ćwiczenie' for lifts, 'płyta siłowa'→'platforma dynamometryczna' for force plate, 'wioślarz'→'wiosłowanie' for rowing; DE 'Hebungen'→'Lifts', the swapped Intermediate/Advanced experience tiers, decimal-comma formatting). Data content (plan descriptions, sport rationales) stays source-language by design. SCOPE: Aurora is now the ONLY template and it is FULLY localized on both clients — every Aurora screen/component plus the settings preference-row labels/descriptions resolve through t(). (The old classic-template screens were deleted in the Aurora-only collapse, so the previously-tracked i18n-classic-template work is moot — there are no classic screens left to localize.) Admin-only screens (apps/*/admin/*) are intentionally English." },

  { id: "i18n-today-redesign-labels", area: "Core", status: "shipped", title: "Localize the Today redesign labels (Performance-State tags + sport-picker sheet)", detail: "The Today redesign's new strings now resolve through t() on BOTH clients at full EN/PL/DE parity. Keys live in the shared dictionary (i18n-web/home.ts, merged into TRANSLATIONS via WEB_BUNDLES, which mobile also consumes through makeTWithOverrides): w.home.quickSport.search / .choose / .close and w.home.today.psTag.readiness / .injury / .velocity / .analytics (HPI stays a literal acronym; the AI-coach tag reuses w.home.today.aiCoach). Web (apps/web/components/aurora/today.tsx + quick-sport.tsx) and mobile (apps/mobile/components/aurora/home.tsx — the Performance-State feature tags — and the shared sheet apps/mobile/components/quick-sport.tsx — title/search/close) all read these keys; no more English literals for the redesign labels." },


  // ---- First-test feedback fixes (workout-history-dashboard) ----
  { id: "workout-archive-delete", area: "Backend", status: "shipped", title: "Archive / delete a workout from History", detail: "Two distinct controls: ARCHIVE excludes a workout from analytics AND hides it (recoverable); DELETE permanently removes it. Session gains a nullable archivedAt; /api/sessions GET excludes archived by default and '?archived=1' returns only archived (the restore view); /api/sessions/[id] PATCH {archived} soft-archives/restores and DELETE permanently removes — both own-rows-only. Archived rows are excluded from ALL session-derived analytics, not just the list: the shared athleteState helper (HPI/readiness/injury risk → /api/state, tactical, longevity), /api/ai-coach, and the coach analytics surfaces (squad, roster, compare, client sessions) all filter archivedAt:null. Admin platform stats + the user's own data export still include them (real history). Surfaced on web History + mobile History (archive/delete per row, an Archived view, restore). NOTE: run reference/sql-history-checkin-anon.sql to add Session.archivedAt." },
  { id: "anon-workout-logging", area: "Backend", status: "shipped", title: "Anonymous (pre-account) workout logging for admin", detail: "A guest training before they have an account now has their workout mirrored to the backend (best-effort, no auth) so an admin sees real pre-signup usage. New AnonSession model (no userId — only an opaque per-install deviceId + platform, not PII); mobile lib/guest.ts POSTs to /api/anon-sessions on every guest save (never blocking the on-device save). Admin reads them at /api/admin/anon-sessions (requireAdmin + audited) and can delete spam/test rows. When the guest later signs up, flushGuestSessions still creates their real Session rows; the anonymous rows are kept as the usage picture. NOTE: run reference/sql-history-checkin-anon.sql to create the AnonSession table." },
  { id: "admin-destructive", area: "Backend", status: "shipped", title: "Admin: delete accounts + any workout", detail: "Admins can now perform destructive moderation: DELETE /api/admin/users/[id] permanently deletes a user account and ALL their data (table-by-table wipe like account/reset, then the User row) — with the same rails as a role change (can't delete yourself or the last admin) and a rate limit; DELETE /api/admin/sessions/[id] removes ANY user's logged workout; DELETE /api/admin/anon-sessions?id removes an anonymous one. Every deletion is rate-limited and written to the AdminAudit trail (actor, action, target, metadata, IP). Surfaced in the Users detail danger-zone + the admin Anonymous-workouts screen." },
  { id: "dashboard-plan-coach-cards", area: "Web", status: "shipped", title: "Dashboard 'Your plan today' + AI-coach card", detail: "The home dashboard's top card is renamed 'Your route today' → 'Your plan today' and now reflects the athlete's GOAL / PERIODIZATION / ROUTINE — when an enrolled macrocycle exists it surfaces the season goal + current phase + week alongside today's prescription (falls back to the readiness-based route when there's no season). The card sits in a horizontally scroll-snapping row: scroll RIGHT to reach a new AI-COACH card (entry point into the server-side AI coach). FULL PARITY: web (components/today.tsx) embeds the inline AskCoach in the card; mobile (app/(tabs)/index.tsx, horizontal paging ScrollView) opens a native AI-coach screen (app/ai-coach.tsx) that POSTs the SAME /api/ai-coach (Claude server-side + engine fallback) and renders the note with source/readiness/HPI chips." },
  { id: "workout-countin-first", area: "Mobile", status: "shipped", title: "Get-ready count-in shows first (no elapsed leak)", detail: "Fixed the live-workout entry: pressing Start used to drop straight into the workout (and tick a stray elapsed second) before the 5→GO count-in appeared, because the count-in was only armed AFTER the async session load. The count-in is now seeded synchronously from the known route source on the first frame for an explicit fresh start, and the elapsed clock is held until the initial restore resolves — so the count-in is the VERY FIRST thing on screen and the clock starts at GO. Resuming an in-progress draft still skips the count-in and keeps its running clock." },
  { id: "plan-visible-from-zero", area: "Core", status: "shipped", title: "Enrolled plan visible from session zero", detail: "Onboarding's enrolled macrocycle used to be invisible until the athlete had logged a workout — the 'Your plan today' / 'This week' cards were gated behind sessions.length>0, so finishing onboarding looked like a no-op. reconcilePlan only needs the macro phase + a (cold-start-capable) daily prescription, so that gate is dropped: from the moment you enroll, the plan card shows today's prescribed session + the phase line (goal – phase – wk N/total) and the reconciled 'This week' card renders the phase envelope + session — on web (today.tsx + reconciled-week.tsx) and mobile (index.tsx). Auto-scheduling/auto-resync still wait for a real logged session (no scheduling off cold-start defaults)." },
  { id: "intake-tailors-prescription", area: "Core", status: "shipped", title: "Experience + equipment tailor the daily session", detail: "Onboarding's experience and equipment answers were previously discarded after the plan recommendation. They are now persisted client-side (hybrid.experience / hybrid.equipment, like hybrid.daysPerWeek — saved on both the enroll AND the 'continue without a plan' paths) and fed into prescribeSession (new opts.experience / opts.equipment, threaded through buildTrainingWeek too). EQUIPMENT picks the movement tier — barbell (full gym), dumbbell variants at home, bodyweight ('BW', rep-driven, no fabricated kg) for minimal — and swaps machine conditioning (rower/bike) for a bodyweight metcon; EXPERIENCE tunes volume + intensity (beginners lighter, more reps, one fewer set; advanced a bit more). The session's 'why' explains the tailoring. Consumed on the web + mobile dashboards (today's plan card + the reconciled week). Pure + unit-tested (movement-tier + experience-dose cases)." },
  { id: "named-plan-drives-today", area: "Core", status: "shipped", title: "Enrolled named plan's day drives 'Your plan today'", detail: "When the athlete enrolls in a REAL uploaded plan (e.g. PR 56's Bodybuilding 4-Day Full Body), that plan's EXACT day now drives the dashboard 'Your plan today' card instead of the engine's algorithmic pick. The enrolled plan id is persisted (Macrocycle.planId, nullable; onboarding sends it; /api/macrocycles stores + returns it; both clients thread it through the macro fetch). New pure core helpers (plan-day.ts): planToday(planId, sessionsLogged) resolves the plan's day for today (walking the plan's days in order, cycling — each logged session advances one day), and planDayToBlocks() converts the day's items into logger SessionBlocks. The card lists the day's exercises (sets×reps – RPE); 'Start' PREFILLS that exact session into the logger — web via a seed-blocks prop on the Logger, mobile via a new /workout?source=plan that rebuilds the day. Goals without a named plan keep the engine prescription. NOTE: run reference/sql-macrocycle-planid.sql to add Macrocycle.planId. Pure + unit-tested." },

  { id: "session-start-hook", area: "Core", status: "shipped", title: "SessionStart hook — deps install + open-backlog surfacing (web)", detail: "A Claude Code (web) SessionStart hook that keeps remote/ephemeral sessions productive and honest — it makes the project test/build out of the box in a fresh container AND puts the open backlog in front of the agent every session. THREE FILES. (a) .claude/settings.json registers a single SessionStart hook of type 'command' pointing at $CLAUDE_PROJECT_DIR/.claude/hooks/session-start.sh — the harness runs it once when a session starts (startup/resume/clear/compact), passing event JSON on stdin and $CLAUDE_PROJECT_DIR / $CLAUDE_ENV_FILE / $CLAUDE_CODE_REMOTE in the env. (b) .claude/hooks/session-start.sh (bash, set -euo pipefail) is WEB-ONLY: it exits 0 immediately unless $CLAUDE_CODE_REMOTE='true' (locally deps already exist and context persists, so there's nothing to do). On the web it cd's to $CLAUDE_PROJECT_DIR and then: STEP 1 — if pnpm is on PATH, runs `pnpm install` with all output redirected to /tmp/hybrid-session-install.log (NOT stdout — stdout is reserved for the hook's JSON, and any stray text there would corrupt it; failures are swallowed with `|| true` so a flaky install never blocks the session); this is what makes `pnpm --filter @hybrid/core test`, the web/mobile typecheck and the iOS bundle export work in the otherwise-empty container. STEP 2 — runs `node .claude/hooks/backlog-context.mjs` (best-effort, `|| true`), whose stdout becomes the hook's output. (c) .claude/hooks/backlog-context.mjs is a PURE-NODE parser (ESM, no npm deps, no build/transpile step, runs on the container's node directly): it reads THIS file (packages/core/src/capabilities.ts) as text, scans line-by-line, and for every entry whose status FIELD is planned or blocked (matched by anchoring to the entry's real top-level shape — `{ id:…, area:…, status:` at the START of the line — so prose in a detail/blockedBy string that merely mentions a status never miscounts, including this very entry) it pulls out the id, title (and, for blocked, the blockedBy, truncated to 130 chars so context can't balloon) via a small quote-aware regex; it then prints a single JSON object {hookSpecificOutput:{hookEventName:'SessionStart',additionalContext:'…'}} — the documented SessionStart contract — whose additionalContext is a compact markdown brief: a header explaining what it is + the rule, then a 'PLANNED — not built yet (N)' list and a 'BLOCKED — built, waiting on a credential/decision (N)' list (each '- [id] title [— needs: …]'). If the registry can't be read or nothing is planned/blocked it exits 0 silently (no context added). SHIPPED entries are intentionally excluded, so the brief is only ever the OPEN work. WHY IT EXISTS: deferrals used to be spoken mid-session and lost when the ephemeral web session ended (e.g. mobile account-settings parity sat undone across several PRs because the ask lived only in chat); now the backlog is injected at the top of every session and the project's parity/capabilities rule is enforced in practice — the loop is: defer something → record it HERE as a `planned` entry (never a prose footnote) → the hook resurfaces it next session until it ships. COST / PERF: the hook runs SYNCHRONOUSLY and ONCE at startup (so deps are guaranteed ready before the first turn, avoiding a race where the agent runs tests before install finishes). It therefore adds a one-time startup wait that is almost entirely the `pnpm install` (the node parser is milliseconds), plus a small bounded chunk of context tokens (the planned+blocked brief). It does NOT run per message/turn, so it has ZERO effect on response latency or token-generation speed during the conversation. It can be switched to ASYNC mode (the hook prints an async marker — async:true + asyncTimeout — first and installs in the background) for faster session startup, at the cost of a brief race window early in the session. ACTIVATION: the web loads hooks from the checked-out repo at session start, so this only takes effect for sessions started AFTER it's merged to the default branch. Validated: the hook emits valid SessionStart JSON; core tests + web typecheck stay green with the registry additions." },

  // ---- Deferred backlog (planned) ----
  // Work that was acknowledged-but-not-built in an earlier PR. Recorded here as
  // structured `planned` entries (not prose footnotes) so the SessionStart hook
  // surfaces them every session and they can't get lost between sessions.
  { id: "account-session-listing", area: "Web", status: "planned", title: "Active sessions/devices + login history", detail: "The account Security section ships Sign-out-everywhere (global signOut) on BOTH clients, and the profile-settings-redesign added a 'Where you're logged in' group with a 'This device — signed in now' indicator (client-side, both clients). What's still missing is the real multi-device LISTING + login-history + per-session revoke: that needs the Supabase service-role admin API (it can't run with the user's own anon session), so build a read-only server route (e.g. /api/account/sessions, service-role, own-user-only) and render the device list under that group. Deferred from account-settings-pro." },
  { id: "mobile-mfa", area: "Mobile", status: "blocked", blockedBy: "Live Supabase auth access — the sandbox blocks the Supabase host, so the enroll→challenge→verify→unenroll round-trip can't be exercised end-to-end. Code is done; unblocks once it can run against a real project (MFA enabled).", title: "Two-factor auth (TOTP) on mobile", detail: "BUILT — parity with web's TOTP MFA. The mobile Security group now renders <MfaSettings/> (apps/mobile/components/aurora/mfa-settings.tsx), mirroring the web flow (apps/web/components/account/mfa.tsx) exactly: supabase.auth.mfa.enroll → challenge → verify → unenroll/listFactors, gated on isSupabaseConfigured(), sharing the core helper isValidTotpCode and the same enroll/verify/remove states + copy. The otpauth QR reuses the hand-rolled QrMatrix from coach-invite.tsx (renders the enroll totp.uri — no QR/svg dependency, iOS export stays green) with the secret shown for manual entry. Verified by typecheck + iOS bundle export; the auth round-trip itself is unverifiable in this sandbox (Supabase host blocked), so this is BLOCKED rather than shipped until it can be exercised against a real project." },
  { id: "prefs-cross-device-sync", area: "Core", status: "planned", title: "Cross-device sync of per-device preferences", detail: "The workout-logger prefs (logger-prefs.ts) and the persona/template/theme choices are stored PER-DEVICE (web localStorage / mobile AsyncStorage), so they don't follow the user across devices. (Notification/privacy prefs already sync — they live in Supabase auth user_metadata.) Lift the logger + UI prefs into a synced store too: a User-prefs column or user_metadata, read on login with the local store as a fast cache/fallback, so a user's setup matches on web and phone. Deferred from logger-settings + account-settings-pro." },
  { id: "upgrade-pricing", area: "Web", status: "planned", title: "Upgrade page — confirm price against live billing products", detail: "The upgrade sheet (aurora/upgrade.tsx, web + mobile) now DISPLAYS a fixed price + free-trial copy — $9.99/month with a '7-day free trial – cancel anytime' note and a 'Start free trial' CTA (i18n keys w.account.upgrade.sheet-*/start-trial/trial-note/per-month, en/pl/de). What remains: reconcile that displayed number/trial against the REAL Stripe Price + Apple IAP product once billing is unblocked (see full-billing-stripe / full-billing-iap), and drive it from the live product metadata rather than hardcoded copy so the two can never drift. Needs the live billing products first." },
  // --- Production-readiness audit: remediation backlog (deferred items that need
  // runtime verification or are larger refactors; recorded so they aren't lost) ---
  { id: "web-data-layer", area: "Web", status: "shipped", title: "Client data-layer / query cache (TanStack Query)", detail: "The web app now runs on a shared TanStack Query cache (components/query-provider.tsx) with per-concern hooks over shared keys — use-sessions/use-macrocycle/use-signals/use-biometrics/use-roster/use-checkins — and mutation→invalidate via lib/use-invalidate.ts, so a write on one screen revalidates every consumer of that key instead of leaving private copies stale. SAFE-CACHE CONTRACT (2026-07): lib/read.ts defines the three-state read every data screen consumes — `ready` (a real server answer is in hand), `refreshing` (a fetch is in flight; drives refresh UI ONLY and never gates content) and `failed` (show an error, never emptiness). This closed the class of bug where a screen holding `[]` before its first response could not tell 'no training history' from 'we have not asked yet', and so asserted the zero-state as fact. useSessions/useMacrocycle `loading` was ALSO redefined from `isPending || isFetching` to unknown-only, which fixed the mirror-image bug: a background revalidate used to drop already-rendered content back to a cold-start skeleton. REMAINING: screen-level remount on nav (the `<div key={screen}>` force-remount in app-shell) is untouched — see web-code-splitting." },
  { id: "web-code-splitting", area: "Web", status: "planned", title: "Code-split the app-shell screen switch", detail: "app-shell.tsx statically imports ~80 screen components (classic + aurora variants) plus recharts into ONE client bundle for the single /app route, so first load ships every screen's JS. Convert the screen switch to next/dynamic (lazy, default-export client components) and lazy-load recharts/admin. Deferred because an 80-component dynamic conversion needs runtime verification of each lazy boundary." },
  { id: "safe-cache-reads", area: "Core", status: "shipped", title: "Safe cache — screens never state what they don't know", detail: "Fixes the reported \"page loads, shows nothing, then shows things after a while\" behaviour — which was NOT slowness. A screen holding useState([]) before its first fetch answered could not distinguish 'this athlete has no training history' from 'we have not asked yet', so it rendered the ZERO-STATE AS FACT — Performance told an athlete with years of data to \"log a session\", showed \"No season yet\" and \"No active protocols\" — then swapped in HPI 51 a second later. The app was asserting something it did not know and retracting it. THE CONTRACT: a read is now three-state, not a bare value — `ready` (a real server-returned value is in hand: render it, even while refreshing), unknown (render a SKELETON; never a zero-state, empty list or computed number, each of which is an unsupported claim) and `failed` (render an error, never emptiness). Defined once per client and mirrored: apps/mobile/lib/queries.ts (`Read`/`toRead`/`combineReads`) and apps/web/lib/read.ts. `refreshing` drives the pull-to-refresh spinner and NOTHING else — gating content on it is the same lie in reverse, which is exactly what web's `loading: isPending || isFetching` did (a background revalidate dropped rendered content back to a cold-start skeleton); it is now unknown-only. APPLIED: mobile Performance moved off useState+useEffect(Promise.all) onto the shared cache (sessions/signals/macrocycle/checkins), so it renders instantly from cache when arriving from Today and revalidates behind the spinner instead of refetching from nothing; mobile Today derives its cold-start gate from the reads rather than a one-shot flag (also correct after sign-out/cache eviction); web Performance takes sessionsReady/macroReady from the shell and skeletons the Performance State card, the Goal widget and the Season/Set-up widget — including the HEADING, which is itself a claim (\"Set up\" vs \"Season\"). Per-source revalidation replaced the all-or-nothing Promise.all fan-out that committed the whole screen at the slowest of five endpoints. INVALIDATION MADE TOTAL (what makes the cache safe rather than merely fast): new shared keys for macrocycle + check-ins on both clients, and the writes that falsify them now drop them — readiness-face saves invalidate checkins (mobile checkin.tsx + home.tsx, web checkins.tsx + today.tsx), plan enrol/leave invalidate the macrocycle (mobile plans.tsx, percent-program.tsx, leave-plan.tsx; web plans.tsx). A write path with no entry in useRevalidate is now documented as a staleness BUG, not a missing optimisation. ALSO: mobile gained throwing queryMacrocycle/queryCheckins fetchers so a timeout surfaces as a failure instead of resolving to an empty list; and useRefreshAll() gives focus effects a referentially STABLE refresher (an unstable one re-fires while focused → the documented refetch loop)." },
  { id: "day-rollover-reactivity", area: "Core", status: "shipped", title: "\"Today\" re-derives at midnight instead of going stale", detail: "A pre-existing correctness bug, independent of caching but exposed by it. Day-scoped values were computed by calling the clock INSIDE a useMemo keyed only on its data — `new Date().toDateString()` in home/performance todayFeeling, weeklyRecap(sessions, Date.now(), bw) — so nothing recomputed when the calendar day turned over. A phone left backgrounded overnight (the normal case, not an edge case) woke showing yesterday's date in the masthead, yesterday's feeling card, and scaled today's prescription off yesterday's check-in. FIX: core gained `msUntilNextLocalDay()` (DST-safe — steps a whole LOCAL calendar day from local midnight, so 23/25-hour days still land on midnight; always >= 1 so a timer scheduled on it cannot spin), joining the existing day-key convention in day-key.ts. Each client got a `useToday()` hook returning the local day key as a REACTIVE value, re-emitting on two triggers because neither suffices alone: a timer armed to the next local midnight (covers the app being open across the boundary) and a wake signal (mobile AppState→active, web visibilitychange/focus — covers the far more common case where the device slept and JS timers never fired). The setter compares before writing, so a wake on the same day does not re-render. The day key is now an explicit DEPENDENCY of every day-scoped memo, and because a day flip re-renders, render-time date derivations (the masthead date, masthead()) correct themselves too. Wired on both clients: mobile home.tsx + performance.tsx, web today.tsx + performance.tsx. Covered by unit tests in day-key.test.ts (timezone-robust, month/year boundaries)." },
  { id: "mobile-fetch-error-states", area: "Mobile", status: "shipped", title: "Surface fetch errors (stop empty-state-on-failure)", detail: "A failed read no longer masquerades as genuinely-empty data. FOUNDATION: throwing query fetchers (ApiError + fetchJson → querySessions/querySignals) feed the React Query hooks (useSessionsQuery/useSignalsQuery) so useQuery's isError/retry fire; every call has a 15s timeout (lib/fetch.ts) so a hang can't read as a slow load. NOW SHIPPED (2026-07): a shared <FetchError> card — 'Couldn't load' + a connection hint + a soft Retry that re-runs the query (common.loadError/loadErrorHint/retry, EN/PL/DE) — with a TWIN on BOTH clients (apps/mobile/components/aurora/fetch-error.tsx + apps/web/components/aurora/fetch-error.tsx) so the error voice is one idiom. Wired into the marquee empty-state-on-failure surfaces at parity: (1) HOME/TODAY — when the sessions fetch errors with no cached data the daily-loop hero shows the retry card instead of the first-run chooser (which would read as 'new athlete' when the network merely dropped); mobile home.tsx gates on useSessionsQuery.isError, web app-shell threads useSessions().error → AuroraToday fetchError/onRetry. (2) HISTORY — mobile refactored to the shared card; web app-shell threads the same error → AuroraHistory. (3) NUTRITION — the signals-driven day summary shows the retry card instead of a '0 eaten / full target' fresh-day read (mobile useSignalsQuery.isError; web tracks a loadErr on the /api/signals fetch, treating 401 as an honest empty). DELIBERATELY EXEMPT: the guided Check-in WIZARD degrades gracefully — its today's-row prefill is optional and the form still logs offline, so a blocking error card there would harm usability (a false-empty only exists where the screen IS the data). REMAINING: Feed, Coach console and Trends still use the soft imperative-fetch pattern (parity-followups)." },
  { id: "mobile-list-virtualization", area: "Mobile", status: "planned", title: "Virtualize long lists (FlatList/FlashList)", detail: "Every list was .map() inside a ScrollView (no recycling — a heavy user's History mounted hundreds of Views up-front on every focus), and aurora/history.tsx additionally ran prsForSession O(n²) inside the row map. HISTORY DONE (2026-07 audit follow-up): converted to a real FlatList (keyExtractor, initialNumToRender/windowSize/removeClippedSubviews, ListHeaderComponent for the title+toggle+swipe-hint and ListEmptyComponent for the loading/error/empty states) — it's the sole scroller now (AuroraScreen scroll={false} provides the SafeArea/backdrop/entrance chrome) so the list is genuinely virtualized, not nested in a ScrollView; and the PR badge counts are memoized into a single map per data change instead of O(n²) per row. EXERCISE PICKER DONE (follow-up): the workout.tsx exercise-picker modal — which rebuilt the entire movement catalog + all sports and re-rendered every row inside a ScrollView on EVERY keystroke — now flattens the grouped catalog into a memoized item array (headers/subheaders/rows in one PickItem[], recomputed only when the search text / catalog changes, not per render) rendered by a FlatList (windowed, removeClippedSubviews); header labels are translated at render time so the memo is independent of `t`. Typing no longer re-mounts the whole list. SOCIAL FEED DONE (follow-up): app/feed.tsx converted from Screen(ScrollView) + feed.map to a FlatList (composer + title as ListHeaderComponent, loading/empty as ListEmptyComponent, per-item Card as renderItem); the shared Screen gained an opt-in `scroll={false}` prop + a useScreenBottomPad() helper so a screen can supply its own virtualized scroller while keeping the SafeArea/backdrop/keyboard chrome. LEADERBOARD DONE (follow-up): app/leaderboard.tsx ranked list is now a FlatList (inside its Card, which is a plain View so nesting is fine) with the title + metric pills as a fixed header. FOUR high-traffic/unbounded lists virtualized: History, exercise picker, Feed, Leaderboard — the actual scroll/typing-jank sources. REMAINING (deliberately deferred, low value): the marketplace Coaches directory (app/coaches.tsx) — currently small/bounded and a dual-mode (browse + storefront) layout, so a FlatList conversion is invasive with more layout risk than perf reward; revisit if the directory grows. The reusable pattern (Screen `scroll={false}` + useScreenBottomPad) is in place for it." },
  { id: "dynamic-type", area: "Mobile", status: "shipped", title: "Dynamic Type — large accessibility text doesn't break the layout", detail: "RN already scales every <Text> with the OS 'Larger Text' / Dynamic Type setting (we never set allowFontScaling={false}), so the gap was never that text wouldn't grow — it was that growth was UNCAPPED, so at the largest accessibility sizes the fixed-height chrome clipped/overflowed and the app became unusable (the floating Aurora nav pill rendered 9.5/8.5px labels with numberOfLines={1} in a hard-height frosted pill; the calendar day-count badge had overflow:'hidden'). Fix: lib/ui.tsx now exports FIXED_FONT_SCALE (1.15) and MAX_FONT_SCALE (1.4) caps; fixed-height surfaces pass maxFontSizeMultiplier={FIXED_FONT_SCALE} so they bound the multiplier while reflowable body text keeps scaling freely. Applied to the shared Kicker/Chip label primitives, both nav-pill labels (side items + Train FAB), and the calendar badge (overflow:'hidden' removed so a scaled digit can't be clipped). Net: the app stays legible AND laid-out from default through the largest Dynamic Type step. CORRECTION (Aug 2026 iOS design audit): this entry OVERSTATED its coverage. The caps were real and correct, but they were applied at 5 of the app's 2,097 <Text> nodes — and one of the surfaces named above, the floating nav pill, no longer exists (the bottom bar became a real NativeTabs). Worse, the caps alone were never sufficient: all 29 of the app's lineHeight values were ABSOLUTE dp, so at Larger Text the OS scales the glyphs and leaves the line box where it was — text collides with itself before it clips, and no multiplier cap fixes that. The prerequisite shipped with `design-token-ratchet`: leading is now a RATIO (leading(size, role)), so a scaled size carries its line box with it. MAX_FONT_SCALE is now applied at the kit primitives so screens inherit it rather than each remembering. THE SWEEP LANDED (see type-leading-derived): all 210 absolute lineHeights that sat on a line with an fs.* token were DERIVED through leading(), so the line box now scales with the glyphs — which was the actual blocker, not the caps. And 110 single-line <Text> nodes gained FIXED_FONT_SCALE: text with numberOfLines={1} cannot reflow by definition, so an uncapped multiplier does not grow the box, it destroys content. Caps went 5 → 122. DELIBERATELY NOT capped: reflowable body text, which SHOULD keep scaling to the full 1.4 — a blanket cap across all 2,079 Text nodes would have been the wrong fix wearing the right number. STILL OPEN, and it needs a device: walking the app at the largest accessibility step to catch the fixed-height chrome that neither rule reaches — rows whose height is set by a sibling, and the 77 remaining absolute leadings that sit on a RAW fontSize and so are gated behind tokenising the size first." },
  { id: "web-font-rem", area: "Web", status: "planned", title: "Web font-scaling parity — px → rem so browser text-size is honoured", detail: "Mobile honours OS Dynamic Type (see `dynamic-type`); the web equivalent is respecting the browser's base/minimum font-size, which only works with rem-relative sizing. Today web text is split: Tailwind text-* utilities are already rem-based (scale correctly), but the inline `fontSize: <px>` styles and the inline `fontSize: fs.body` numbers (fs is consumed as raw px on web) are FIXED px — they ignore the browser font-size setting and only respond to full-page zoom. The a11y audit also flagged sub-10px inline labels (profile heatmap/stat keys at 8–9px) as the worst offenders. Parity fix: route web inline sizes through a rem helper (e.g. fsRem(fs.body)) or a --font-scale root variable, and floor inline sizes to ≥11px. Deferred: it touches inline styles across most web screens and wants the running app to verify no row/truncation regressions." },
  { id: "a11y-baseline", area: "Core", status: "shipped", title: "Accessibility baseline — focus, contrast, labels, roles (web + mobile)", detail: "First pass on the a11y audit's highest-impact, systemic gaps, landed on both clients in parity. WEB (globals.css): a global :focus-visible ring (2px lime, !important to beat the ~40 inline outline:none) so keyboard users can see focus (WCAG 2.4.7); a ::placeholder colour set to the theme-aware `ash` token + color-scheme:dark light so placeholders clear AA on the dark fields (they were UA-grey ~3.5:1); aria-labels on icon/glyph-only buttons (× closes, ↑↓⧉ block controls, timer transport, calendar arrows — 16 buttons / 9 files); and purpose-based aria-labels on the login email/password/name/MFA inputs (placeholder-only before → failed 1.3.1/3.3.2/4.1.2). MOBILE: the shared primitives now carry role+state so the fix propagates everywhere — Button (role=button + disabled state), ToggleRow (role=switch + checked/disabled + 10pt hitSlop), the kit ASegment + check-in rating/share controls (role=radio/checkbox + selected/checked, fixing colour-only selection → 1.4.1), and the shared AField input (accessibilityLabel from its placeholder); plus accessibilityRole=button + localized accessibilityLabel (common.back) on the icon-only back buttons across 18 screens and direction-aware labels on the calendar month arrows." },
  { id: "mobile-back-button-parity", area: "Mobile", status: "shipped", title: "Consistent screen-back button (mobile ↔ web parity)", detail: "Every pushed mobile screen now returns via ONE shared control instead of the per-screen back buttons each screen used to hand-roll — so the mobile app matches the web app's single consistent treatment (the RULE: web ↔ mobile parity). NEW PRIMITIVE: `ABack` in apps/mobile/components/aurora/kit.tsx — a 44×44 line-bordered square with the Aurora `back` glyph and a localized accessibilityLabel (common.back), defaulting to router.back() with an optional onPress override for in-screen pops (settings sub-page, admin section canGoBack→/admin fallback). This is the same 44×44 field-radius icon button the web headers use (aurora interval-timer / standalone chrome), so the clients no longer drift. It REPLACES the divergent variants: the 40×40 `‹` glyph button with no a11y label (Find-friends, Edit-profile, Coaches, Feed, Leaderboard), the `← Back`/`← History`/`← Roster` text links (AI coach, coach-apply, session detail, admin section), the hardcoded-'Back' icon buttons (notifications, timer, statistics) and the ~14 duplicated canonical headers (calendar, check-in, nutrition, progress, trends, performance, running, velocity, connections, exercises, longevity, volume, forceplate, video, login). It also ADDS the back button that was MISSING on the hidden-tab routes reached from the More springboard — Plans, Sport, Coach, Cockpit and History — which had none even though their siblings Velocity/Running already did. Genuinely distinct affordances are intentionally kept as-is: the live-logger 'Cancel', the onboarding wizard's prev-step pill (paired with Next), and the admin index '← App' exit link (a replace-to-app, not a stack pop). THEME-AWARE SURFACE: Aurora (dark) keeps the transparent outlined square; Japandi (light) fills it as a SOFT SURFACE (ink2 tile + a touch of depth) because a hollow outline reads as unfinished on the warm paper ground — driven by `scheme` in the mobile ABack and mirrored on web via `--back-surface`/`--back-shadow` tokens ([data-theme=\"light\"] in globals.css) wired into the standalone back buttons (statistics, interval-timer, notifications). FULL SWEEP (follow-up): the first pass only converted EXISTING back buttons and added them to the hidden-tab routes; a subsequent exhaustive audit of every pushed Stack route caught seven more screens that had a header but NO back control at all — Builder, Run-track, Periodize (both the active + no-plan states), Competition, Talent, Tactical and Logger-settings — all now carry `ABack`. The audit rule: any screen reached by push (not a primary nav destination) gets `ABack`; the only header-bearing screens intentionally without it are the primary tabs (Today/Train/More/Profile roots), the auth/funnel screens (welcome/onboarding wizard), and the admin index's '← App' exit link. Mobile typecheck + iOS bundle export green." },
  { id: "a11y-keyboard-dialogs", area: "Web", status: "shipped", title: "Keyboard operability — dialog focus-trap + operable cards", detail: "Second a11y pass, web keyboard correctness. New shared hook lib/use-dialog.ts (focus-in on open, Tab/Shift+Tab trap, Escape-to-close, restore-focus-to-trigger; capture-phase so it wins over inner stopPropagation) wired into all six modal/drawer surfaces — exercise picker (workout-blocks), tour, profile + coach drawers (social-profile/coaches), the Aurora More sheet (pill-nav, gated on its open flag), and the admin add-user modal (which was also missing role=dialog/aria-modal) — each container now role=dialog + aria-modal + tabIndex=-1 (WCAG 2.4.3/2.1.2). Separately, clickable <div>/<span> with onClick but no keyboard path (WCAG 2.1.1) are now operable via role=button + tabIndex=0 + Enter/Space onKeyDown: plan/goal cards (plans), coach-client card (coach), and the Teams org open-athlete / revoke-invite / close controls (org) — the destructive revoke and the ✕ also got aria-labels. (save-routine-card / social-feed / admin agent-hq were already real <button>s.)" },
  { id: "a11y-reduced-motion", area: "Core", status: "shipped", title: "Reduced motion respected on both clients", detail: "WEB: the @media (prefers-reduced-motion: reduce) block, previously scoped to the glass/command selectors, is now a global *,*::before,*::after catch-all that neutralises EVERY animation/transition — ambient blob field, conic rim sweep, Aurora screen-enter, win-pop, hover lifts and inline-styled transitions (near-zero, not 0, so animationend/transitionend still fire). MOBILE: RN doesn't honour the OS Reduce Motion setting automatically, so a new hook lib/use-reduced-motion.ts wraps AccessibilityInfo.isReduceMotionEnabled (with live reduceMotionChanged updates); the two central motion sources now gate on it — the perpetual ambient-blob drift loop (lib/ui.tsx AuroraField) holds still, and the per-screen fade+rise entrance (kit.tsx AuroraScreen) renders at rest. Parity with the web media query." },
  { id: "a11y-tap-targets", area: "Mobile", status: "shipped", title: "Touch targets reach the platform minimum", detail: "The genuinely finger-unfriendly mobile controls — below the iOS 44pt / Android 48dp bar — now extend their touch area with hitSlop (which grows the hittable region without changing the visual layout, the right tool for these absolutely-positioned / tightly-packed controls): the profile avatar edit button (30×30), the workout set-type cycle button (28×30), the routine-builder steppers (32×36, which also gained Decrease/Increase labels) and the command-menu close (34×34, also labelled). NOTE on web: its icon buttons (30×30, 26×26 closes) already clear WCAG 2.2 AA — SC 2.5.8 Target Size (Minimum) is 24×24 — so they were left as-is; 44px there is only the AAA bar (2.5.5)." },
  { id: "a11y-live-regions", area: "Core", status: "shipped", title: "Interval-timer state announced to screen readers", detail: "The interval timer's big clock ticks every second; announcing that would be unbearable, so instead the timer now announces only PHASE transitions (which happen at work/rest boundaries) — a blind user hears \"Work – Round 1/3\", \"Rest – …\", \"Done\" as it progresses, with no per-second spam. WEB: a visually-hidden aria-live=\"assertive\" aria-atomic region whose text is just the phase + round (the seconds aren't in it, so it only re-announces on a boundary), empty while idle. MOBILE: AccessibilityInfo.announceForAccessibility on phase change, deduped via a ref so a phase is spoken once. The two clients mirror each other. (Toasts + async save/error live regions are still open — see a11y-followups.)" },
  { id: "a11y-landmarks", area: "Core", status: "shipped", title: "Screen-reader landmarks, headings + skip link", detail: "WEB: the app-shell already wrapped content in <aside>/<nav>/<main>/<header>; this names them and adds the missing scaffolding for keyboard/SR navigation — the primary <nav> gets an aria-label (\"Primary\"), <main> gets id=\"main\" + tabIndex=-1 as a jump target, and a new visually-hidden-until-focused skip-to-content link (.skip-link in globals.css, localized nav.skipToContent EN/PL/DE) is the first focusable element so users can bypass the sidebar. MOBILE: the shared AHeading screen-title primitive now sets accessibilityRole=\"header\", so VoiceOver/TalkBack rotor heading-navigation works on every Aurora screen at once. (A deeper per-screen heading-LEVEL order audit on web is still possible but the landmark + skip-link baseline is in.)" },
  { id: "a11y-locale-dir", area: "Web", status: "shipped", title: "Document language + direction follow the active locale", detail: "The server renders <html lang=\"en\"> statically, so a PL/DE user's content was mislabelled as English — a real bug, since screen readers pick voice + pronunciation rules from lang. The web LanguageProvider now syncs document.documentElement.lang to the active locale on change, and sets dir via the new @hybrid/core localeDirection(lang) helper (backed by RTL_LANGS, empty today since en/pl/de are all LTR). This both fixes the lang-attribute bug now AND is the single seam an RTL locale would flip the whole document from. Mobile: nothing to wire today — RN VoiceOver/TalkBack read the device locale, and there's no RTL locale to force via I18nManager." },
  { id: "a11y-rtl-migration", area: "Core", status: "planned", title: "Full RTL layout support (logical properties)", detail: "DEFERRED ON PURPOSE, not forgotten. localeDirection/RTL_LANGS + the web dir sync (see a11y-locale-dir) make the app direction-AWARE, but a genuinely mirrored RTL layout needs a physical→logical style migration across BOTH apps — marginLeft/Right→Start/End, left/right absolute offsets, textAlign, the 180°-rotated calendar arrow, row flex assumptions — plus I18nManager.forceRTL + a reload on mobile. That's a large sweep with real regression surface and, critically, NOTHING to verify against while every shipped locale (en/pl/de) is LTR. It should be done as one focused pass IF/WHEN an RTL language (Arabic/Hebrew) is added to LANGS — at which point RTL_LANGS gets the entry and this work is scoped by that locale." },
  { id: "a11y-status-messages", area: "Core", status: "shipped", title: "Async error / notice messages announce to screen readers", detail: "Inline status messages that appear after an async action (login/save/validation errors, \"check your email\" notices, success confirmations) were plain text a screen reader never spoke when they changed — failing WCAG 4.1.3 (Status Messages). Now they carry a live-region role across both clients. WEB: role=\"alert\" on error / mixed success-or-error messages (assertive), role=\"status\" on neutral notices (polite); since the shared <Mono>/<Card> primitives don't forward arbitrary props to the DOM, those messages are wrapped in a role-bearing <div>. ~35 components (login + classic login, account/MFA, check-in, nutrition, builder, run-track, forceplate, upgrade, coach, quick-sport, invite, and the admin console err/msg banners). MOBILE: accessibilityLiveRegion (\"assertive\" errors / \"polite\" notices) + accessibilityRole=\"alert\" on the inline message elements (drives Android TalkBack), plus AccessibilityInfo.announceForAccessibility at the single clean set points (login, settings, coach-apply, social handle, workout) for iOS VoiceOver where live-region has no effect. Native Alert.alert calls (already announced) and always-present helper text were left alone." },
  { id: "a11y-followups", area: "Core", status: "planned", title: "Accessibility audit — remaining items", detail: "Tracked from the full a11y audit, after the baseline + keyboard-dialogs + reduced-motion + tap-targets + live-regions + landmarks + locale-dir + status-messages passes. Remaining, lower-priority: (1) a deeper per-screen heading-LEVEL (h1→h2→h3) order audit on web (landmarks + role=header are in; the exact heading hierarchy per screen isn't audited); (2) full RTL layout — see `a11y-rtl-migration` (deferred until an RTL locale ships); (3) a manual pass at max Dynamic Type / 200% browser zoom to confirm the inferred truncation fixes on real devices." },
  { id: "schema-deletion-cascade", area: "Core", status: "shipped", title: "Account-deletion FK cascade (defense-in-depth)", detail: "DONE in code: every user/relationship FK now carries onDelete Cascade (and SetNull on the self-referential Team.parent) in prisma/schema.prisma, with the exact drop/recreate migration in reference/sql-ondelete-cascade.sql (generated via prisma migrate diff). The app already deletes children explicitly (admin user-delete + /account/reset), so this changes no app behaviour — it guarantees a raw/RLS delete of a User/Org/CoachLink can't orphan rows or be blocked by a dangling FK, which a schema-level security review would otherwise flag. Tables that store userId as a plain String (no relation) are already orphan-safe. APPLIED in production via sql-pending.sql (Jul 2026)." },
  { id: "schema-tenant-isolation-rls", area: "Core", status: "shipped", title: "Tenant isolation — complete + ENABLE row-level security", detail: "The audit's 'no tenant boundary' finding resolves to RLS, not an orgId column: athlete data here is USER-owned (a user can be in several orgs / have a coach), so an orgId column would mis-model it — the org/coach read paths are correctly relationship-based (Membership/CoachLink) and enforced in the API. The real gap was the DB defense-in-depth layer: (1) reference/rls-policies.sql CREATED policies but never ran ENABLE ROW LEVEL SECURITY, so they were INERT; (2) ~10 user-data tables (Signal, Checkin, Connection w/ OAuth tokens, RtpProtocol, VideoAnalysis, Event, TalentProfile, RiskOutcome, WorkoutTemplate, OnboardingState, …) had no policy at all. reference/sql-rls-extend.sql fixes both: enables RLS on every sensitive table, adds self-ownership (+ coach-read where the product allows) policies for the user-owned tables, and sets a deny-all baseline for the relational/org/admin/agent/email tables. Safe for the app (Prisma uses the privileged role, which bypasses RLS); it only blocks direct anon-key/PostgREST access. HARDENED (2026-07 audit): the policy LOGIC itself carried escalation bugs that enabling RLS would merely ACTIVATE — now fixed in rls-policies.sql + sql-all.sql: (a) User UPDATE is column-restricted via REVOKE/GRANT so a signed-in user can't PATCH their own role/entitlement to ADMIN through PostgREST; (b) CoachLink insert is forced to PENDING and only the client can activate, so a forged ACTIVE link can't read a victim's data; (c) org/team/membership writes + CoachInvite claim are server-only / own-email-scoped (no self-join-as-OWNER, no anon PII enumeration); (d) ProcessedWebhookEvent gets RLS enabled (was world-writable); (e) a blanket `revoke all on public tables from anon` closes the whole unauthenticated PostgREST surface behind the policies. APPLIED in production via sql-pending.sql (Jul 2026). Spot-check any time with: select relname, relrowsecurity from pg_class where relnamespace='public'::regnamespace and relkind='r' order by relrowsecurity; (every row should be true)." },

  // ---- web↔mobile parity gaps (from the per-screen parity diff) ------------
  { id: "other-sports-today", area: "Core", status: "shipped", title: "Other sports on Today — the racket/team/combat block", detail: "Tennis, squash, badminton, five-a-side — everything the loggers stamp as `discipline: \"sport\"` — had been logged since the sport catalog shipped and had NOWHERE to appear. ENDURANCE_DISCIPLINES deliberately excludes the tag (a tennis match is not endurance), so a Tuesday-night habit fed the week's sessions and hours in the \"This week\" card and then vanished. This block, directly under Endurance on Today, is where it lands. ONE LANE PER SPORT, NOT PER DISCIPLINE: every racket/team/combat session carries the SAME tag, so keying off it the way endurance-lanes.ts does would collapse them into a single lane called \"Sport\" — exactly the picker-shaped flattening the endurance block was built to escape. The grouping key is the block's own NAME, matched against OLYMPIC_SPORTS for its icon and category, with a generic marker and a null category for a sport typed by hand (Kabaddi still gets a lane). ONE TILE, NOT A RAIL, PER SPORT: the catalog gives these sports `metrics: TIME` — no distance, no pace, no zones — so a tile carries the four things a timed sport can honestly say about itself (efforts, hours, an 8-week frequency strip, when it was last played) and the block spends its width on the NUMBER of sports rather than the depth of each. Inventing a pace for a squash match to fill a rail would be fabricating a metric the sport does not have. CORE: other-sports.ts — otherSportLanes() (grouping, most-played first with ties broken on RECENCY so two sports at four efforts each are ordered by which one you are still doing; the discipline tag is preferred and the NAME is the fallback, matching the endurance filters, so blocks logged before the loggers stamped a tag still land here), sportWeekBars() (normalised against the lane's own busiest week, same shape volumeBars() returns so both blocks draw bars through identical code), otherSportTotals() (the head reports the block so nobody adds up tiles), OTHER_SPORT_CAP = 4 with an expander. A session outside the 8-week window still counts in the totals; it simply isn't charted. 15 unit tests. BOTH CLIENTS (parity): aurora/other-sports.tsx on web + mobile, rendered straight after AuroraEnduranceLanes and before the Go Full baits. Full-bleed rail on the exercise-widget idiom (margin 0 calc(-1 * var(--page-pad-x)) on web, marginHorizontal -16 on mobile) with matching inner padding. Frequency bars use VIOLET, not teal: teal already means cardio on the lanes directly above, and two blocks in the same colour would read as one. Renders nothing until a sport is logged, so no tile needs an empty state. Each tile opens the Sport screen. i18n EN/PL/DE." },
  { id: "endurance-today-lanes", area: "Core", status: "shipped", title: "Endurance on Today — sport lanes (per-discipline rails)", detail: "The Endurance hub was a destination in More: one discipline at a time behind a picker, which meant a hybrid athlete's endurance was invisible unless they went looking for it, and invisible ALL AT ONCE even then (pick running, lose the swim). It now renders inline on Today — directly under the \"This week\" verdict card, whose KM column these rails break down, so the week's total and its per-sport detail read as one thought (it spent its first months at the FOOT of the scroll, under Nutrition, which put them at opposite ends) — and inverts while it does: EVERY logged discipline gets a lane, and a lane is a full-bleed horizontal rail of that discipline's own analytics — efforts/distance/time, 8-week volume bars, the pace trend, the pace zones, the last effort. THE SHAPE IS THE POINT: adding a metric WIDENS a lane's rail, it never LENGTHENS the block, so five sports carrying five cards each still cost five rows and the whole endurance read fits under Nutrition without Today growing a second screen. CORE: endurance-lanes.ts — enduranceLanes() (one lane per discipline with logged cardio, derived entirely from the existing running engine: runTotals/weeklyMileage/paceEffortSplit/disciplineSessions, so there is no second definition of a week or an effort), orderLanes()/nextLaneOrder() (the block's ONE control cycles most trained → most recent → longest; 'most trained' is activeDisciplines' own order so moving between Today and the hub never reshuffles the sports), LANE_CAP = 3 with an expander (a fourth lane pushes the block past a screen of its own), laneWeekTotals() RETIRED Jul 2026 with the totals strip it fed: the \"This week\" verdict card higher up Today already states the week for ALL training, and a second cross-sport strip beneath it counted a DIFFERENT population under near-identical labels — \"5 sessions, 3.2 h\" above \"3 efforts, 0.9 h\", with nothing on either saying which was which. The week's distance moved into that card as its own column (shown only for an athlete who logs endurance); per-sport efforts/km/h stay on each lane's SummaryTile, where the lane names the scope. The block now opens straight on its lanes. zonePercents() (largest-remainder rounding so the legend always sums to 100 beside a full bar), paceDelta()/paceTrendPoints() (FASTER IS UP on every discipline — one rule works because storage is always canonical seconds-per-km, so a lower number is both a quicker run and a faster ride), volumeBars(). A lane's pace trend is read off the SAME weeklyMileage buckets its volume bars draw, so two cards in one lane can never disagree about a week. 25 unit tests. BOTH CLIENTS (parity): aurora/endurance-lanes.tsx on web + mobile, rendered straight after AuroraWeekVerdict on Today (today.tsx / home.tsx) and before the Go Full baits. Rails use the exercise-widget bleed (margin 0 calc(-1 * var(--page-pad-x)) on web, marginHorizontal -16 on mobile) with matching inner padding. Charts are hand-rolled SVG on both (recharts stays on the hub) — Today should not pull a chart library into its first paint, and hand-rolling gets the two clients pixel-identical. The block is NOT gated on dayIsToday — an eight-week volume chart is not a property of the day you happen to be scrubbed to. Athlete-gated (the hub's own minPersona), renders nothing until there is endurance logged, so no lane needs an empty state. NAV: the More entry is retired via a new NavItem.promotedTo field rather than deleted — on web the nav id IS the screen id, so removing it would strand the hub. The route, icon, i18n label and persona gate all stay live (navVisibleTo and sanitizePersonaAccess deliberately keep honouring it, and the parity guardrail still resolves it on both clients); only the menu listing goes, and each lane's 'See all ›' opens the hub. The hub keeps what a rail can't carry: the by-move table and the full-size charts. i18n EN/PL/DE." },
  { id: "parity-guardrail", area: "Core", status: "shipped", title: "Web↔mobile parity enforced in CI", detail: "The parity rule (one product, two clients) was prose only, and it drifted twice in the same area — the Running screen was deleted from web without a web Endurance hub to replace it, and Analytics was removed from web while mobile had no Analytics screen, leaving the dashboard with NO live surface on either client and a mobile→browser→'open it on your phone' dead-end. apps/web/__tests__/parity.test.ts now makes the rule mechanical: it scans the ACTUAL source of both clients — the web app-shell's `screen === \"<id>\"` branches and the mobile More springboard's HREF route map — and asserts every canonical NAV_ITEMS id resolves to a real surface on both. A deliberate gap is allowed ONLY via the ACCEPTED_GAPS allow-list, and each entry must name a capability that is `planned` or `blocked` (asserted against CAPABILITIES), so an escape hatch is always auditable and can never point at a 'shipped' capability. It also fails if an accepted gap silently closes (stale allow-list entry), regression-locks analytics + endurance by name, and sanity-checks that both surface maps parsed non-empty so a refactor can't turn the suite into a vacuous pass. Runs in the existing CI test job. Currently 3 accepted gaps, all tracked by mobile-team-surfaces: squad, teamcompare, org." },
  { id: "mobile-team-surfaces", area: "Mobile", status: "shipped", title: "Team Compare / Squad Monitor / Org on mobile", detail: "SHIPPED — the last three web-only nav destinations now exist on mobile: components/aurora/team-compare.tsx, team-monitor.tsx and org.tsx with app/team-compare.tsx, squad.tsx and org.tsx routes, plus their HREF entries, so the More springboard opens real screens instead of tagging them web-only and launching the browser. Each runs on the SAME endpoints as its web twin (/api/coach/compare, /api/coach/squad, /api/org) AND the same shared core engines — buildTeamTree/flattenTree/canManageOrg/canRead/roleScope for Org, athleteSegment/SEGMENT_LABELS for the monitor — so role permissions and segment logic cannot drift between clients: that logic lives in core rather than being re-implemented per client. Where the web layout could not survive a phone it was re-formed rather than shrunk: the monitor's 8-column table becomes one card per athlete carrying the same eight facts, Compare's horizontal bar chart plus 7-column table becomes ranked meters plus stacked per-athlete detail, and Org's <select> dropdowns become tap-through role/team rails. All operations are preserved (create org, nested teams, add/invite members, change role or team, revoke invite, open an athlete's Performance-State readout). New lib/api.ts helpers (fetchTeamCompare, fetchSquad, and the org CRUD set) degrade to empty/null rather than throwing, so a non-coach simply sees an empty state. This also removes all three entries from the parity-guardrail test's ACCEPTED_GAPS list — that test fails if an accepted gap silently closes, which is how it should be. Historical context: these were web-only (web aurora/team-compare.tsx, team-monitor.tsx, org.tsx) while mobile had no route at all." },
  { id: "mobile-analytics", area: "Mobile", status: "shipped", title: "Analytics dashboard on mobile (athlete + coach + operator scopes)", detail: "Closes the half of the Analytics parity gap that never existed: mobile had no Analytics screen, so the More springboard tagged it web-only and tapping it OPENED THE BROWSER. app/analytics.tsx + components/aurora/analytics.tsx now render all three scopes off the SAME engines and endpoints the web dashboard uses, so the numbers can't drift: ATHLETE (sessions / total volume / heaviest lift / last readiness, a top-lift heaviest-load trend, volume-per-session over the last 8, and a heaviest-per-lift PR table) via totalVolume/sessionVolume/bestTopLoadByLift/topLoadSeries/liftNames with the user's units + bodyweight lookup; COACH (clients / avg adherence / avg readiness / roster volume, adherence-by-client meters, roster table with readiness colour-coded) via GET /api/coach/roster through the new fetchRoster() in lib/api.ts (RosterRow mirrors web's lib/use-roster.ts row-for-row); OPERATOR (users / MAU / sessions / coaches, plans-by-goal and language-split meters) via GET /api/admin/stats through adminGet(). Scope availability, landing scope, demotion fallback and the privacy note all come from the shared core helpers (see web-dashboards) rather than being re-derived. Charts are dependency-free bars + meters (the trends/endurance/volume idiom) so no charting library ships to the phone. Strings reuse the w.home.analytics.* bundle plus new analytics.subtitle / analytics.scope.* / analytics.privacy.* keys (EN/PL/DE). Reachable from the More springboard via HREF.analytics — the web-only blue dot is gone." },
  { id: "mobile-coach-console-parity", area: "Mobile", status: "shipped", title: "Coach console — client tools parity", detail: "Mobile aurora/coach.tsx ClientDetail (345 lines) is a subset of web's (669). Missing on mobile: roster tag add/remove, per-client template assignment, generate-periodized-week (enroll macro + buildTrainingWeek bulk-assign), and the weekly check-ins + coach-reply section. Bring the mobile ClientDetail to parity with the web programming tools." },
  { id: "mobile-performance-detail", area: "Mobile", status: "shipped", title: "Performance screen — detail parity", detail: "Ported three of the four missing web features to mobile aurora/performance.tsx on the same engines: the Return-to-Play panel (RtpPanel + /api/rtp helpers in lib/api.ts), the injury-table ACWR + top-driver columns, and the Readiness trajectory alongside HPI. The last web-only piece, the anterior/posterior tissue body-map, is CLOSED (Aug 2026): both clients now draw the same shared mannequin from @hybrid/core injury-body.ts via react-native-svg, which the app does depend on — see injury-body-map-primary." },
  { id: "mobile-calendar-layers", area: "Mobile", status: "shipped", title: "Calendar — events + coach-assignment layers", detail: "Mobile aurora/calendar.tsx renders only the session heat-grid. Web additionally fetches /api/events (amber event dots + detail) and /api/assignments (violet dots, assignment detail, and a 'Mark done' PATCH), plus a legend and a Today-jump. Add the events + assignments layers on mobile." },
  { id: "mobile-nutrition-weight-chart", area: "Mobile", status: "shipped", title: "Nutrition — bodyweight-trend chart", detail: "Web aurora/nutrition.tsx renders a weightTrend line chart and appends a weightChangeKg/28d suffix to the maintenance line; mobile omits both (never imports weightTrend). Add the bodyweight-trend chart to the mobile nutrition screen." },
  { id: "mobile-velocity-capture", area: "Mobile", status: "shipped", title: "Per-set velocity (VBT) input in the mobile logger", detail: "Mobile-logged sessions feed the velocity-profile engine: per-set bar speed (StrengthSet.vel) is entered in the live logger's exercise detail sheet (live-logger-exercise-sheet), at parity with web. The earlier inline m/s cell on the set row was superseded by the sheet in the late-Jul 2026 logger review." },
  { id: "web-logger-prefs", area: "Web", status: "shipped", title: "Expose the full logger preference set on web", detail: "Mobile logger-settings exposes ~17 prefs; web account-settings exposes only 4 (detailed, countWarmups, fractionalVolume, units). The web logger already READS several unexposed ones (plateCalc, autoAdvance, restTimer, restSeconds, keepAwake, haptics) at their stored default, so web users can't change behaviour they're subject to. Surface the shared prefs on web (restNotify/restSound stay native-only)." },
  { id: "web-coach-console-tools", area: "Web", status: "planned", title: "Coach groups + program builder on the web console", detail: "Mobile coach.tsx mounts CoachGroups (components/coach-groups.tsx) and CoachPrograms (multi-week builder) behind the coach.groups/coach.programs flags; the web Aurora coach console (AuroraCoach) surfaces neither, though the /api/coach/groups + /api/coach/programs APIs exist. Wire both into the web coach screen for parity." },
  { id: "parity-audit-2026-07", area: "Core", status: "shipped", title: "Web/mobile parity audit (Jul 2026) - destinations + copy reconciled, guarded by a test", detail: "A full parity sweep against the CANONICAL nav (@hybrid/core nav.ts NAV_ITEMS, 40 destinations), comparing the web app-shell screen switch to the mobile More hub's id->route HREF map. RESULT: all 40 destinations resolve on WEB; 4 do not resolve on MOBILE. Three of those (org, squad, teamcompare) are the already-declared mobile-team-surfaces gap and degrade honestly - the More hub tags them 'WEB' and opens the web app. The fourth is BROKEN, plus three more findings the nav diff alone does not catch: (1) ANALYTICS WAS DEAD ON BOTH CLIENTS - NOW FIXED ON WEB. The web app-shell rendered a MobileOnlyScreen pointer ('Analytics lives in the app - open HYBRID on your phone') while mobile had no analytics route, so its More hub tagged the item 'WEB' and sent the athlete back to the web app: a circular dead end whose copy asserted something untrue. The web implementation existed and compiled the whole time (apps/web/components/aurora/analytics.tsx, ~43 w.home.analytics.* keys) but had ZERO importers - orphaned when analytics was retired from web (see web-dashboards) while the mobile build (mobile-analytics) never happened. RESOLVED: app-shell now renders a persona-scoped AnalyticsScreen (every athlete gets AuroraAthleteAnalytics; a coach also gets AuroraCoachAnalytics off useRoster; an admin also gets AuroraOperatorAnalytics), so the destination works on web again and mobile's 'WEB' tag is truthful rather than circular. The MobileOnlyScreen helper now carries a warning not to point at mobile for a surface mobile has not built. While wiring it, AStat's decorative leading dot was removed per the no-decorative-dot rule. mobile-analytics REMAINS the open gap - this restores the destination, it does not close mobile parity. (2) AI COACH is unreachable on both. apps/web/components/aurora/ai-coach.tsx has zero importers; on mobile the /ai-coach route exists but NOTHING navigates to it (no router.push anywhere). The /api/ai-coach endpoint is live, so this is a missing door on both clients, not a missing feature. (3) COACH-APPLY is NOT a gap (a corrected false positive from the first pass, which inferred it from filenames alone). Mobile gives it a dedicated route (app/coach-apply.tsx, reached from Settings and the More hub); web hosts the SAME flow - intro, the identical 3 steps, credentials field, submit and status readout - inside components/account-settings.tsx under the 'coaching' tab. Same feature, different placement. A filename diff cannot see this, so parity checks must confirm against the rendered flow, not the file tree. (4) COPY-LEVEL DRIFT outside the social surface. The two clients implement the SAME screens off DIFFERENT i18n key namespaces - 448 keys used only by web, 293 only by mobile. Largest clusters: the logger (web w.train.logger 47 + loggerPrefs 17 vs mobile workout/live/summary ~59), plans (web w.train.plans 30 vs mobile plans 14), history (web w.analyze.hist 23 vs mobile history 8), blocks (web w.train.blocks 22). Both clients HAVE these screens, so this is not feature absence - it is two copies of the same copy, which can and does diverge in wording without any test catching it. social-i18n already collapsed the social surface onto ONE shared key set; the same treatment is owed to logger / plans / history / builder. RESOLUTION (all four destination gaps closed): analytics re-wired on web AND built on mobile (components/aurora/analytics.tsx + app/analytics.tsx, all three scopes off the same endpoints, charts in the house Spark/measured-bar idiom rather than a charting library); org, squad and teamcompare BUILT on mobile (components/aurora/org.tsx, team-monitor.tsx, team-compare.tsx + their routes), each on the SAME endpoints and the SAME shared engines as its web twin - buildTeamTree/flattenTree/canManageOrg/canRead/roleScope for Org and athleteSegment/SEGMENT_LABELS for the monitor - so role permissions and segment logic cannot drift, since that logic lives in core rather than in either client; the web tables and <select> dropdowns become stacked cards and tap-through rails, because neither survives a phone's width. The AI coach got a door on BOTH clients: an 'AI coach' module tile on each Cockpit's horizon list (web setScreen('aicoach') -> the previously-orphaned aurora/ai-coach.tsx; mobile router.push('/ai-coach')), matching mobile's existing not-in-nav route. New i18n w.home.cockpit.aiCoach/aiCoachValue and the previously MISSING nav.org (the web sidebar had been falling back to raw English), all EN/PL/DE. VERIFIED: re-running the nav diff now returns EMPTY in both directions - all 40 destinations resolve on web AND on mobile. COPY DRIFT (4) NOW RESOLVED TOO: 77 English strings were reachable through a web-only key AND a different mobile-only key (mobile carried legacy flat namespaces - live.*, log.*, summary.*, plans.*, history.*, coach.*, more.*, quickSport.*, recap.*, settings.*, workout.* - duplicating web's structured w.* keys). All 77 mobile call sites now point at the canonical w.* key and the duplicate entries are deleted from all three locales. CRITICALLY, 20 of the 77 had ALREADY diverged in Polish or German while still reading identically in English - so no English-language review could ever have caught them. One was an outright mistranslation: the Polish for 'No sessions logged yet' used 'zalogowanych' (the logged-IN / authentication sense) instead of 'zapisanych' (recorded). Three web keys turned out to have NO pl/de values at all, where mobile did - those translations were backfilled onto the canonical key rather than dropped. GUARD: packages/core/src/i18n-parity.test.ts fails if any English string becomes reachable through both a web-only and a mobile-only key. It understands runtime-built keys (t(`nav.${id}`)), since a client that resolves a namespace from a variable never names those keys literally and would otherwise look like it wasn't using them. Verified by injecting a duplicate and confirming the test fails on it. DELIBERATELY NOT collapsed: 11 generic one-word labels ('Loading...', 'Saving...', 'PR', 'Pause', 'blocks', ...) that each screen keys for itself - a language may translate the same English word differently by context, so forcing one key would make translation worse. They are allowlisted by VALUE in the test, so a whole sentence can never sneak in under that exemption. METHOD (re-runnable): diff NAV_ITEMS ids against the web screen cases and the mobile HREF map; then diff the t() keys used under apps/web vs apps/mobile. NOT a gap: mfa (mobile-mfa is declared blocked), endurance (deliberately mobile-first, and mobile HAS the route so the web pointer is truthful)." },
  { id: "parity-followups", area: "Core", status: "planned", title: "Web↔mobile parity — minor drifts", detail: "Smaller one-sided drifts from the per-screen diff, each low-risk: web-only — plan-detail Rest/RPE columns, sport PR markers, competition fitness/fatigue series, session-detail mixed-distance stat, history readiness chip, trends tonnage chart/column, running efforts column, statistics vs mobile (mobile has an extra HPI card, web doesn't), profile-drawer 'View coaching' link + Top-lifts list, checkin week-streak, longevity per-contribution note. Mobile-only — guest workout logging, quick-increment load buttons, Train resume-draft card, AI-coach readiness/HPI chips + auto-generate, session-detail per-set rest column. Web settings has a Simple/Full mode toggle mobile lacks. Onboarding free-text questions are captured on web only (mobile returns null for text-kind). Bring each to parity or fold into the design-system-unification-sweep." },

  // ---- Strategy review (Jul 2026) — see audit/08-strength-platform-strategy-2026-07.md ----
  // The competitive teardown found four genuinely uncopyable assets and a set of
  // table-stakes gaps that every named competitor already ships. Recorded here so
  // the analysis can't evaporate into prose. NOTE: the same review recommends
  // RETIRING a large share of the shipped surface (tactical, longevity, talent,
  // org graph, competition intel, video intel, force plate, the nutrition stack,
  // the email platform, the agent org, the CMS) — that decision is the founder's,
  // so nothing is marked retired here; see the Kill List in the audit doc.
  { id: "history-import", area: "Core", status: "planned", title: "Import training history (Hevy / Strong / CSV)", detail: "TABLE STAKES + the switching mechanic. The #1 reason a lifter won't change trackers is two years of history. Hevy and Strong both export CSV. Import should reconstruct the full session history, then RECOMPUTE personal records with HYBRID's correct maths — bodyweight-aware tonnage (10 BW pull-ups at 70 kg = 700 kg), both-bells dumbbell tonnage, canonicalized exercise names — and finish on a Wrapped of the athlete's own imported years. The migration tool doubles as the differentiation demo." },
  { id: "live-activity-rest", area: "Mobile", status: "planned", title: "Rest timer as a Live Activity / Dynamic Island", detail: "TABLE STAKES. The rest countdown belongs on the lock screen so the phone goes back in the pocket between sets. Highest delight-per-line-of-code available on iOS; every named competitor either has it or is asked for it. Pairs with the existing rest-haptics + saved-rest work." },
  { id: "home-widget", area: "Mobile", status: "blocked", title: "Home-screen + Lock-screen widgets", detail: "TABLE STAKES, now BUILT and gated behind a flag. A real WidgetKit extension (apps/mobile/targets/widget — @bacons/apple-targets generates the Xcode target during prebuild): home-screen small/medium plus lock-screen circular (the streak) and rectangular (today's title + done state), deep-linking into the app (hybrid://), honest empty state until the app has run once. DATA PATH: the Today screen publishes a compact snapshot (title, plan-day sub, streak, done) through the local Expo module apps/mobile/modules/widget-bridge, which writes it to the App Group's UserDefaults and reloads the WidgetKit timelines — no network in the widget, it renders what the app last knew and says when that's stale. The whole native side is OPT-IN via WITH_APPLE_TARGETS=1 at prebuild (app.config.js) and the release workflow's with_targets input, so the plain release pipeline is untouched until the extra bundle id + App Group exist in the portal. Web parity: none possible — a home-screen widget is an OS surface web does not have (recorded per the parity rule, like device-workout-match's match action). NEXT: an interactive 'start rest timer' intent, and live-activity-rest for the in-session lock screen.", blockedBy: "Run the 'Mobile — build & TestFlight' workflow with with_targets=true. The workflow registers com.hybriddomain.xyz.widget and fetches its profile automatically; if the archive fails on the App Group entitlement, create group.com.hybriddomain.xyz once in developer.apple.com → Identifiers and tick it for the app + widget App IDs (the one step the ASC API key can't do), then re-run. Then verify on-device: add the widget, open the app once, the widget shows today's session + streak; tap → app opens." },
  { id: "watch-app", area: "Mobile", status: "blocked", title: "Apple Watch companion (today at a glance)", detail: "TABLE STAKES since ~2018, v1 now BUILT and gated behind the same flag as home-widget. A real watchOS SwiftUI app (apps/mobile/targets/watch, generated by @bacons/apple-targets at prebuild): today's session title, plan-day sub, streak and done state on the wrist, rendered from the same snapshot the widget uses — delivered over WatchConnectivity applicationContext (an App Group does NOT span two devices; the phone-side push lives in modules/widget-bridge, which re-sends the stored snapshot on session activation so a Watch paired later still fills in). DELIBERATE v1 SCOPE: a glance app, not a logger — 'log from the wrist' and then silent-logging build on this scaffold, and shipping the glance first is what makes the Watch target, signing and data path real before the hard part. Web parity: none possible — an OS surface (recorded per the parity rule). NEXT: wrist logging (sets confirmed from the watch), then silent-logging's set detection.", blockedBy: "Run the 'Mobile — build & TestFlight' workflow with with_targets=true (registers com.hybriddomain.xyz.watchkitapp + fetches its profile; watch targets are the least-trodden path in apple-targets, so expect this first run to need a fix on the mac if Xcode balks). Then verify on-device: install from TestFlight onto a paired Watch, open the iPhone app once, the Watch shows today + streak." },
  { id: "adaptive-mrv", area: "AI", status: "shipped", title: "Adaptive recoverable volume (per-athlete MRV estimator)", detail: "10x. The population MV/MEV/MAV/MRV table — the same textbook numbers every competitor uses — is now only the FIRST of four layers. engines/landmark-resolve.ts (`athleteLandmarks`) composes them in order, each closer to the individual than the last, and returns the provenance with the numbers so no screen can pass an average off as a measurement: (1) POPULATION, the table; (2) PROFILE (engines/landmark-profile.ts) — MEV/MV scale with a STIMULUS multiplier (training age: a novice grows off ~0.7× what an advanced lifter needs) and MRV with a RECOVERY multiplier (training age up, then chronological age −1.2%/yr past 30, body mass −0.4%/kg past 80, sleep, life stress, energy deficit, and training frequency), with the MAV band re-derived at its proportional position between the athlete's own MEV and MRV so each muscle keeps its shape and the ordering can't invert; every factor is returned with its multiplier and the value that produced it, plus a confidence that rises as the profile fills in; (3) OBSERVED (engines/landmark-adapt.ts) — the ceiling corrected by what actually happened, because a ceiling is only ever found by running into it: weeks carrying at least MAV-high sets are classified TOLERATED (week-on-week e1RM held, post-session fatigue and check-in soreness moderate, reported energy holding up) or OVERREACHED (top sets fell >3%, or fatigue/soreness spiked, or reported energy collapsed — see volume-recovery-feed for the check-in feed); symptoms set an upper bound and beat 'I got away with it', tolerated weeks at/near the ceiling raise it, the move is bounded to ±35% of the prior, and with fewer than two qualifying weeks it returns the prior untouched at zero confidence, carrying the evidence rows that moved it; (4) MANUAL — the athlete's own typed numbers, applied last, always winning. Wired into BOTH Volume screens: a 'Whose numbers are these?' card names the layer, lists the factors as signed percentages, shows the confidence, carries the profile editor (training age, age, body mass, sleep, stress, energy intake, sessions/week — prefilled from the intake answers and the bodyweight log so nothing is typed twice) and the 'learn from my training' switch. Answers the question directly: an 18-year-old 40 kg novice training 3×/wk resolves quads to MEV 6 / MAV 9–14 / MRV 15, a 40-year-old 120 kg veteran on 5×/wk to MEV 9 / MAV 12–17 / MRV 18 — different for opposite reasons (no work capacity yet vs. age and mass), against a population 8 / 12–18 / 20. The estimate now carries its STATED INTERVAL (MrvEstimate.lo/hi): unproven it is the whole ±35% corridor, it narrows as qualifying weeks accumulate (2 weeks → ±3, 4+ → ±1), and each side pins to what the weeks proved — a tolerated week props the bottom (the ceiling is at least what was carried), a symptomatic week caps the top — so the band is honest about WHICH side the evidence nailed down; shown with the adapted ceilings on both Volume screens as e.g. 'Quads 17 (15–19)'. Moat unchanged: the estimate needs longitudinal WITHIN-PERSON data that cannot be bought or scraped, and it compounds." },
  { id: "accent-channel-guard-gaps", area: "Web", status: "planned", title: "Accent text channel \u2014 the 56 sites the guard cannot see", detail: "apps/web/__tests__/accent-text-channel.test.ts enforces that no `color:` resolves to an accent FILL, and it caught 78 sites. Its two regexes only match a LITERAL at the head of the value \u2014 `color: C(\"red\")` and `color: var(--color-red)` \u2014 so two shapes slip through and are still painting glyphs in the fill: a literal inside a larger expression (`color: on ? C(\"lime\") : C(\"ash\")`, the toggle/selected-state idiom) at 37 sites across 23 files, and a COMPUTED accent (`color: C(token)`, `color: C(ZONE_TOKEN[zone])`) at 19 more. Same AA failures the guard was written for: on Kyoto Hour, sand is 1.57:1 and terracotta 3.26:1 against the card, at a 10\u201314px type scale that the large-text exemption never covers. Found while shipping volume-detail-drawer \u2014 the Volume screen had NINE of them, all now moved to `accentText()`, and its accent tokens are typed `AccentKey` so a computed one still resolves through the text channel. NOT swept app-wide in that change: 56 sites across 23 files is its own pass, and it belongs with the guard that should have caught them. TO DO: widen FILL_AS_TEXT to match an accent anywhere in the value expression, decide the rule for a computed accent (type the token as AccentKey and route it through accentText, as Volume now does, rather than trying to resolve it in a regex), then fix the fallout. The mobile twin is not affected \u2014 its idiom is txt(C, C.accent), which already maps fill to text tone." },
  { id: "volume-detail-drawer", area: "Core", status: "shipped", title: "Volume detail opens in place — and the provenance is a sheet", detail: "The compact volume block on Performance answered \"5/7 in range\", drew the seven-column week-shape, named the two muscles that were out of range — and then sent the athlete to a DIFFERENT SCREEN to read the detail of the card they were already looking at. Everything the shape raised a question about (the block ramp, Ease off / Add volume, the per-muscle rails) lived one full navigation away, with the shape itself left behind. Two changes on BOTH clients (apps/web/components/aurora/volume.tsx + apps/mobile/components/aurora/volume.tsx). (1) THE DETAIL EASES OPEN UNDERNEATH. The door is now a disclosure: pressing it opens a drawer under the week-shape carrying the block, both prescriptions and the muscle rails, with the chevron rotating rather than swapping glyph so the control reads as one object in two states. Web runs a 0fr → 1fr grid row (globals.css `.motion-drawer`) — a real height animation with nothing measured, so content that grows inside an open drawer just follows; mobile measures the panel and interpolates its height on the SAME `springs.sheet` curve, then hands the height back to `auto` once the opening has settled, which is what keeps an expanding muscle row from being clipped to a height measured before it grew. Both substitute a cross-dissolve under Reduce Motion. The sections are authored ONCE and rendered at two weights through a shared `Panel` (card on the screen, hairline-divided flat section inside the drawer), so the drawer is not a summary of the screen — it IS the screen, off the same components and the same landmark resolve. (2) WHOSE NUMBERS ARE THESE IS DISPATCHED AS A SHEET. The provenance ladder, the completeness meter and 'Show the working' (level, factors, the log's correction, the ceiling replay) were the seventh card at the foot of the reading, where they read as more of the prescription; they now sit behind a door row and open as a Sheet (medium/large detents) from wherever the reading appears — the screen or the drawer — so the question is answered without the athlete losing their place. COST DISCIPLINE: the eight-week per-muscle histories and the landmark REPLAY (one full resolve per week of history) are gated on one `deep` flag, so a Performance page that only wants the week's shape pays for the week's shape and the heavy passes are bought the moment the drawer opens; once opened the detail stays mounted, because unmounting it on close would give the collapse nothing to collapse. ONE DISCLOSURE, EVERYWHERE: every fold on the surface now runs the same drawer — the compact card's detail, 'Show the working' inside the provenance sheet, a muscle row's MV floor and eight-week chart, and the band definition under a spotlight. Three of those were `{open && \u2026}` conditionals that POPPED inside a card that eases, which read as three different mechanisms rather than one idea at different scales; they are now the shared `Drawer` on both clients. Two things fall out of keeping the content MOUNTED so a collapse has something to collapse: the fold does not render until it has been opened once (seven muscle rows each carrying an eight-week chart is not free on a phone), and a closed drawer is taken out of the focus order and the accessibility tree \u2014 `inert` on web, `accessibilityElementsHidden` + `importantForAccessibility=\"no-hide-descendants\"` + `pointerEvents=\"none\"` on mobile \u2014 because a clipped panel is otherwise still reachable by Tab and by VoiceOver. The spotlight's band is held through its own collapse, so the definition does not blank out the instant the spotlight is dismissed. TWO FUNCTIONAL BUGS FIXED ON THE WAY. (a) Leaving for the model editor from INSIDE the provenance sheet did not close it \u2014 the sheet is a modal over the shell (a Modal in its own native window on mobile), so a route change underneath just swapped the screen it was covering: the athlete tapped 'Training age', the app navigated, and they still saw the panel they tapped from. Both clients now close the sheet on the way out. (b) On mobile that same 'Next' row \u2014 the single most valuable thing the athlete could do to personalize their landmarks \u2014 set an `aboutOpen` flag that NOTHING rendered, so the control did nothing when pressed while its web twin opened the model editor; it now goes where web goes, and BOTH Performance pages now pass the model route into the compact block \u2014 the provenance sheet is reachable from there too, and without a destination that same row rendered its arrow and did nothing on both clients (a control that only ever had a destination while the card lived on the standalone screen). Dead code in both volume screens went with them (the retired in-place editor's leftovers: an unused Stepper, the bodyweight/check-in hooks the shared use-volume-model has owned since the model editor moved out, and six unused type imports). The standalone Volume screen (nav \u2192 Analyze \u2192 Volume, mobile /volume) is unchanged and still carries the same sections as cards. New copy `w.analyze.vol.hideDetail` localized EN/PL/DE." },
  { id: "volume-periodization", area: "Core", status: "shipped", title: "Periodized volume — the MEV → MAV ramp across a block", detail: "Landmarks are the walls of the corridor, not the target; sitting at MRV every week is the classic mistake, because it leaves no room to progress and buries the athlete in fatigue by week three. engines/volume-block.ts turns the landmarks into a WEEK-BY-WEEK prescription: week 1 sits at MEV, the accumulation weeks ramp linearly toward the top of MAV, an optional planned overreach runs the last load week into the MAV→MRV gap (stopping one set short of the ceiling), and the deload week drops to MV. `blockVolumePlan` then reports each muscle against THIS WEEK'S target rather than the static band — the same 12 quad sets read as over target in an introduction week and short in a peak week — while `overCeiling` keeps the MRV ceiling winning over the plan regardless of the ramp. `blockFromMacrocycle` reads the block position straight out of the periodization engine's macrocycle (mesocycle = block, trailing recovery microcycle = deload) so the season plan and the volume ramp stay one thing. On BOTH Volume screens: a 'This block' card draws the whole block as a ramp strip (a low introduction week, the climb, the step down of the deload) with the week's job named, the per-muscle rails carry the week's target as a caret on the same normalised rail, and the block (length, current week, last-load-week style, deload) is editable in place. Off by default — switched off the screen is exactly the landmark view it was." },
  { id: "checkin-honest-metrics", area: "Core", status: "shipped", title: "One tap answers one question (bug fix)", detail: "BUG FIX with real downstream consequences. The one-tap readiness face on Today asked \"how ready do you feel?\" and wrote the picked level into ALL FOUR check-in metrics — energy, sleep, soreness and mood — as though the athlete had reported four measurements. They reported one; the other three were invented and stored indistinguishably from answers actually given. The guided flow had the same defect from the other end: its ratings defaulted to 3 and all four were submitted, so a question walked past without a tap was stored as a middling 3. Neither invention was inert. The volume profile reads mean check-in SLEEP and presents it to the athlete as MEASURED (green field, \"read from your own data\"), and the adaptive-MRV estimator reads soreness and energy as recovery evidence over an 8-week window — so one tap was silently feeding three models numbers nobody had entered, and the app was labelling them measurements. FIXED in core (checkin-flow.ts): `quickCheckinMetrics(rating)` returns exactly `{ energy, sleep: null, soreness: null, mood: null }`, and both clients send it; the guided wizard now tracks which metrics were ACTUALLY answered (touched here, or already non-null in today\'s stored row) and sends null for the rest, with the review card showing a dash rather than a neutral face for anything unanswered — a face would claim a reading that was never given. `checkinRating` already averaged only the metrics present, so a single-metric check-in still resolves to exactly the feeling the athlete picked; `answeredMetrics` / `outstandingMetrics` / `checkinCompleteness` / `firstOutstandingStep` expose the partial state, and every downstream reader already treated null as unknown rather than as a 3. Also folds two smaller drifts: both wizards prefilled by comparing days with their own `new Date().toDateString()` while the rest of the screen used `localDayKey` (two definitions of \"today\" in one component), and the web wizard issued a private GET /api/checkins alongside the shared cache — both now read one cache through one day-key helper. reference/sql-checkin-unfabricate.sql is an OPTIONAL cleanup for rows already written, which nulls the three copied metrics where all four are equal; it is explicitly a heuristic (a genuine flat-3 check-in is indistinguishable) and the contamination otherwise ages out in 4-8 weeks on its own." },
  { id: "checkin-followup-popup", area: "Web", status: "shipped", title: "Today's feeling card — the follow-up is a pop-up", detail: "The card keeps its one row of four faces (the thing that works: a single glanceable question, one tap to answer). What changed is everything after the tap. The rest of the check-in used to expand INLINE inside the card, which made the card grow into a wizard and buried Today\'s other content; it now opens as a POP-UP — Sheet on both clients — that gets the surface it needs to ask three questions properly, and dismissing it leaves honest partial data rather than a half-filled form. The pop-up opens AUTOMATICALLY on the tap, because that is the moment the athlete is most willing to answer more and, since the quick tap no longer fabricates the other three (see checkin-honest-metrics), it is now the only way sleep, freshness and mood ever get real values. It resumes at the first UNANSWERED question via `firstOutstandingStep` rather than the old hardcoded \"start at Sleep\", which was only correct while the tap pretended to answer Energy. The card\'s trigger row shows completeness as \"1 / 4 answered\" plus a four-dot readout naming which metrics are in — a count alone doesn\'t tell you what you would be answering — and switches to a quiet complete state once all four are logged. Web and mobile carry identical logic and copy from core." },
  { id: "checkin-answers-survive", area: "Core", status: "shipped", title: "The check-in keeps the answers you gave (bug fix)", detail: "Three reported symptoms — \"the readiness face doesn't match the check-in\", \"I answered everything and it still feels unsaved\", \"there are dashes after I answered\" — with four independent causes, all of them the app contradicting the athlete about their own data. (1) SILENT DATA LOSS. POST /api/checkins upserts the day, but wrote EVERY column on every save, so any field a sender omitted was stored as null — and each surface sends a different subset. Re-tapping readiness in the afternoon sent {energy, sleep: null, soreness: null, mood: null} and DELETED the three answers logged that morning; submitting the follow-up on web (whose form never loaded the day's extras) deleted the weight, adherence and note every time. The route now PATCHES an existing day: an absent key is left alone, an explicitly-null key clears. Core supplies the wire payloads — `quickCheckinPatch` (the one metric a tap answered) and `checkinMetricPatch` (only the questions actually answered) — and the web wizard now prefills the day's extras the way mobile always did, with CheckinRow widened to name the fields the API had always returned. (2) THE PHANTOM DASHES. The wizard's ratings default to a neutral 3, and the metric card rendered that default as a SELECTED tile under a confident word (\"Okay\"), so pressing Next told the athlete twice they had answered. Nothing was stored — correctly, a default is not a report — and the review card two steps later showed a dash for every question they thought they had just answered. The metric card now mirrors the effort card, which already got this right: untouched, the face is dimmed to 30%, the word reads \"Not answered\", no tile is selected, and the advance button says SKIP (quiet outline) rather than Next (lime pill). The progress bar likewise fills on ANSWERS rather than position, so walking to the end no longer draws a complete bar over a one-answer check-in. The review's dashes became BUTTONS back to their question, under a \"2 / 4 answered — tap a dash to answer that one\" line. (3) THE CONFIRMATION NOBODY SAW. Embedded in Today's follow-up sheet, `onDone` fired on the POST's return and the host closed the sheet — mounting and unmounting the wizard's \"Check-in logged\" card in the same tick. Finishing the check-in looked exactly like the app dropping it. `onDone` now only REFRESHES; the new `onClose` is the dismissal and the athlete presses it, from a confirmation that states the count, swaps to a partial-save line when questions are blank, and offers \"Answer the rest\" straight back to the first one. (4) THE ANSWER THAT CHANGED ITSELF. Today's picker highlighted `checkinFeeling` — the MEAN of every metric present — under \"how ready do you feel?\". Tap Primed, then log sleep 3 / freshness 2 / mood 4, and the card came back highlighting Good and reporting \"you logged Good\": the app overwriting the athlete's own answer with a number they never gave. New `quickCheckinFeeling` reads the metric the question actually writes; the average still feeds the load model, which is a different question that genuinely benefits from more signal. The 6h cooldown moved off `feeling` onto whether the day has a ROW, so a day answered without its readiness question can't lock the very question it is asking. Also unified the VOCABULARY: `checkinMetricWordKey` names the quick metric in the picker's words (Wrecked/Flat/Good/Primed — the face was already the readiness face) instead of the generic scale words, and qEnergy now asks \"How ready do you feel?\" verbatim in EN/PL/DE, so one tap and one card ask one question. The follow-up subtitle dropped its hardcoded \"Three more questions\", which was wrong on every day the athlete trained. Both clients, identical logic and copy from core. SECOND PASS — the same class of bug, everywhere else it lived. (5) EVERY subjectiveReadiness CALLER read the average. The readiness pick drives four things — the picker highlight, the week rail's readiness pill, the load multiplier, and the nudge that QUOTES it back (\"Eased to 94% — you're feeling flat today\", rendered with that feeling's own face) — and all six call sites across both clients (Today/Home, both Cockpits, the web logger's AI quick-start, mobile workout.tsx) passed `checkinFeeling`. So the rail pill said \"Good\" while the card directly beneath it highlighted the Primed face just tapped, and the Cockpit told athletes they felt flat on a day they had described as primed. `checkinFeeling` had ZERO callers that legitimately wanted an average — every one of them wanted the answer — and now has none in app code; it keeps its export and a warning doc-comment for the honest reading it does describe (the day as a whole). (6) TWO STALE-DAY BUGS in web today.tsx's todayFeeling: it called the clock INSIDE the memo with no `today` dependency (a tab open across midnight scaled today's load off yesterday's check-in) and compared days with its own `toDateString()` rather than `localDayKey` — both already fixed for `dayCheckin` twenty lines above it in the same file. Same `toDateString()` drift removed from the web logger and mobile workout.tsx. (7) THE TAP DIDN'T COUNT UNTIL THE SERVER AGREED. The POST invalidates the cache and the follow-up sheet opens in the SAME tick, so every reader below ran on the pre-tap row until the refetch landed: the face just pressed wasn't highlighted, the trigger still read \"0 / 4 answered\", and `firstOutstandingIndex` opened the flow ON THE READINESS QUESTION THAT HAD JUST BEEN ANSWERED — which is how a walked-past default became a dash in the review. Both cards now hold the tap optimistically, scoped to the viewed DAY so switching the rail can't carry it and applied only until the stored row carries a readiness answer of its own, so the server's value wins with no clean-up. (8) The web wizard's prefill effect re-ran on every cache change and re-merged the EXTRAS, so a refetch could undo a note the athlete had just cleared; extras now seed once while the ratings keep merging (they have to — that refetch is what tells the sheet Energy is answered). 11 new core tests." },
  { id: "fitness-level-engine", area: "AI", status: "shipped", title: "Training level read from the bar, not from a tap", detail: "Training age is the strongest single input to the volume model — the only one that scales the STIMULUS end, so it moves MEV as well as MRV — and it came from one onboarding tap. Self-assessment is unreliable in both directions: eight hard months reads as \"intermediate\", a decade of unprogressive gym-going reads as \"advanced\". engines/fitness-level.ts estimates it from the log instead. Relative strength (best e1RM ÷ body mass) on five benchmark lifts — Back Squat, Deadlift, Bench Press, Overhead Press, Front Squat — is compared to published-standard entry ratios for novice / intermediate / advanced / elite, shifted for sex (per-lift factors, ~0.68 upper body to ~0.78 deadlift) and scaled by the same age-development curve the talent engine uses, so a 16-year-old and a 45-year-old hitting the same ratio are not read as the same athlete. The BEST lift sets the level, not the average — training age is what you have built, not a number dragged down by the lift you neglect. Only working sets count, only ≤12-rep efforts (a rep-out is not a max test), only the last 180 days, and names resolve through the movement catalog so a library alias still counts. Confidence rises with how many benchmark lifts are represented (one is a data point, three a picture) and is capped at 0.85, because a ratio is a proxy for training age rather than a measurement of it. `resolveExperience` keeps the athlete's own answer WINNING — the same rule the landmark resolver applies to every manual value — and reports `disagrees` so the UI can show the mismatch and offer the estimate rather than silently overriding. With no bodyweight, no benchmark lift or nothing in the window it returns `basis: \"none\"` and zero confidence: the caller falls back to what the athlete said, never to a default tier. Surfaced on both Volume screens with the lifts and ratios behind it. BOTH HALVES OF A HYBRID ATHLETE: relative strength answers the question for a lifter and says nothing about a runner, so there is a second, independent read. Running performance is normalised to a 5 km equivalent with Riegel (T5 = T x (5/D)^1.06) so a 10 km and a parkrun are comparable — a marathoner is not read as a slow 5 km runner — and scored against published pace standards (6:00 / 5:00 / 4:10 / 3:20 per km for novice / intermediate / advanced / elite, male at peak training age), with the female table 11% slower and the same age-development curve applied, dividing rather than multiplying because for a pace an easier bar is a SLOWER one. Runs under 3 km are not aerobic tests and over 45 km are past what Riegel is good for; both are ignored. Whichever half is stronger sets the level, for the same reason the best lift does, and `basis` always names which halves had data (\"strength\" / \"endurance\" / \"both\" / \"none\") so the card says \"from your best lifts and your best run\" rather than implying it read everything. A runner needs no body mass, since a pace is not relative to one. STILL RUNNING-ONLY, and named rather than guessed: cycling and rowing pace depend on gearing, terrain, drag factor and draft, the same watts produce wildly different splits, and a threshold table over raw speed would be a fiction — a cyclist with no runs and no lifts still gets `basis: \"none\"` and falls back to what they told us. Distinct from benchmarks.ts, which answers a different question (percentile against a sport cohort, for the coach talent report) and shares only the development curve." },
  { id: "volume-model-web", area: "Web", status: "shipped", title: "Volume model editor on web", detail: "The volume MODEL — the athlete's own per-muscle landmark profile (MV/MEV/MAV/MRV edited set by set, the numbers that personalize every landmark readout) plus the about-you profile behind it — has its own route on BOTH clients: apps/web/components/aurora/volume-model.tsx (screen id `volume-model`, reached from Volume's header and its provenance card) and apps/mobile/app/volume-model.tsx. Both resolve through the shared lib/use-volume-model hook, so the screen and the route can never compute different landmarks, and both LEAD with the diff — the same profile resolved with and without the athlete's overrides, so every band they have moved shows as a change from the estimate it replaced and can be put back. RECORD CORRECTION (Aug 2026): this shipped as part of the Performance rebuild (`performance-six-surfaces`, follow-up (a)) and neither this entry nor the parity guard's ACCEPTED_GAPS list was updated with it — so the registry claimed a gap that no longer existed, and apps/web/__tests__/parity.test.ts had been failing on main with its own instruction ('listed as an accepted gap but now ships on both — remove it from ACCEPTED_GAPS'). Both are corrected here. The guard working as designed is the reason it was caught." },
  { id: "volume-profile-completeness", area: "Core", status: "shipped", title: "What the model still doesn't know about you", detail: "The personalized landmarks are only as individual as the profile behind them, and between \"population table\" and \"estimated for you\" the athlete had no way to tell which they were looking at or what one more answer would buy. engines/athlete-profile.ts names the gap: every input carries a WEIGHT reflecting how much it actually moves the estimate (training age 0.30, body mass 0.18, down to stress 0.03 — a distribution summing to 1, not a checklist), so the meter is weighted by influence rather than by counting boxes. A progress bar that treats training age and stress as equal is lying about where the athlete's effort pays off. It reports the score, what is missing ordered by value, the single most valuable next answer with an i18n line saying what it unlocks, and which gaps the app could fill itself (`measured`, from landmark-context) so \"we worked it out\" is never shown as missing. PAIRED WITH ATHLETE HEIGHT, tracked separately as `athlete-height` (now shipped — the column is live and the athlete sets it in Profile → Body & progress). BodyMetric.heightCm feeds `frameAdjustedMassKg`, which reads body mass against the frame carrying it instead of as raw kilos: the recovery multiplier docks mass above an 80 kg reference, but 95 kg at 195 cm and 95 kg at 170 cm are not the same load, and the flat rule penalised them identically. Mass is now compared to what the height predicts (a plain BMI-style expectation at 24.5 — deliberately NOT a body-composition model, since the app cannot see composition and pretending otherwise would be the same class of error as inventing a sleep score). Without height the raw-kg rule applies exactly as before, so nothing regresses; the factor still displays the athlete's REAL mass rather than the adjusted figure." },
  { id: "one-feeling-card", area: "Core", status: "shipped", title: "One instrument, asked at two moments", detail: "There were TWO places a feeling was logged: the daily check-in and a separate post-workout prompt. They asked the same question — \"how are you right now\", on the same 1-5 scale, drawn with the same faces — through two code paths with different maths. That is why the Today card could tell an athlete a reading \"isn't counted against your recovery\" while the estimator counted it anyway: one question, two implementations, already disagreeing. The fix was to make it ONE instrument, and that part stands: one scale, one lag model, one threshold, one place the maths lives. What the first pass got wrong was concluding that one instrument meant one MOMENT — the post-workout prompt was deleted outright, which threw away a reading the daily card cannot recover (see two-read-feel, which restores it as the first of two scheduled reads rather than as a second implementation). THE FLOW IS DYNAMIC (core/checkin-flow.ts `checkinSteps`): four daily questions, then ONE EFFORT QUESTION PER SESSION trained that day, then details. A rest day is exactly the four questions it always was. Effort is per-session rather than per-day on purpose — a hard lift and an easy jog on the same day are not one number — and it lands on Session.feel, which is where the effort model, `personalTrainingLog`, fatigue, readiness, ACWR and injury risk have always read it from, so NO MIGRATION and no second source of truth. `stepAnswered` / `dayCompleteness` / `firstOutstandingIndex` walk both halves, so the card's \"2 / 6 answered\" and its dot row count sessions as well as metrics, and the pop-up resumes at the first genuinely unanswered step whichever kind it is; a session already rated on the finish screen shows as answered rather than being asked twice. THE RECOVERY HALF MOVED WITH ITS MATHS: `RecoveryReport` gained `loggedAt` (Checkin.createdAt), landmark-adapt finds the last session that ended before each check-in was written, and runs the feel-timing lag model over it — so the check-in's freshness and energy are discounted for proximity to training exactly as the post-workout answer was. Freshness and energy are folded onto ONE spentness scale and pooled with any session-side reports into a single `recoveryCost`, read by a single threshold. That makes the card's promise true rather than aspirational: a flat reading 90 minutes after squats no longer moves the ceiling, the same reading 20 hours later does, and the floor of the scale still flags either way because the worst possible answer on every metric is past what one session explains. Rows with no write time fall back to the untouched raw rules." },
  { id: "feel-timing", area: "Core", status: "shipped", title: "When you logged the feeling changes what it means", detail: "\"How spent are you?\" is not one question — it is a different question at every hour after the session. Tick \"wrecked\" ten minutes after a heavy squat session and you have described a set of squats. Tick it ten hours later, showered and back at a desk, and you have described a problem. The app stored identical rows for both and every model read them as the same number. core/feel-timing.ts fixes that with one small stated model: RESIDUAL — acute fatigue decays, exponential (tau 6 h) toward a 35% floor standing in for the muscle-damage component that outlives the day, so `expectedResidual(h)` is the fraction still expected to be present at h hours; COST — the report divided by the residual expected at that lag, a timing-independent estimate of what the session actually cost (fatigue 4 at 1 h = 0.83, the same 4 at 10 h = 1.50); WEIGHT — full up to 12 h, then decaying toward 0.25, because a report given days later is recall rather than measurement; READ — the reading classified as immediate (<3 h, a read on the SESSION), sameDay (3-12 h), nextDay (12-36 h, a read on RECOVERY and the most informative one), or stale. Thresholds are written against `cost`, not the 1-5 scale, because 5 is the top of that scale and saturates: a 5 at 1 h and a 5 at 10 h both display as 5 while their costs differ by a third. COST_HIGH (1.15) is calibrated so a hard session logged in the gym is not a flag and the same answer hours later is, and MIN_STRAIN_FATIGUE stops a long lag from inflating \"I feel fine\" into evidence of strain — dividing a small number by a small number must not manufacture a signal. Wired into the adaptive-MRV estimator: a week is judged on the timing-adjusted cost where its sessions carry timestamps and on the untouched raw 1-5 rule where they don't, never on both (the cost already contains the raw value; consulting both would count one report twice). Surfaced in the post-workout prompt on BOTH clients, which now names the read and says what it is measuring, and mirrored on the way IN by the Today feeling card (see feeling-card-redesign). Also fixes the readiness side of the same blind spot: `readinessContext` reads today's check-in against the last session, so \"wrecked\" 90 minutes after training is not scored as a recovery failure. Session.feelLoggedAt is APPLIED in production (sql-pending.sql run, Jul 2026); rows from before it keep NULL and fall back to the raw 1-5 rule, so nothing is retroactively re-interpreted." },
  { id: "checkin-soreness-polarity", area: "Core", status: "shipped", title: "The check-in's soreness column stores FRESHNESS (bug fix)", detail: "BUG FIX + a guard against its whole class. The `Checkin.soreness` column, its Prisma comment and its field name all say 5 = very sore. The stored value is the OPPOSITE: the guided flow asks \"How fresh do your muscles feel?\", the one-tap face on Today writes the picked readiness level into all four metrics, and `checkinRating` averages the four as if higher were better everywhere. Every WRITER agrees that 5 means fresh; only the name disagrees. That is a trap with teeth, because a consumer reading the field by its name gets a plausible, exactly backwards answer — no crash, no type error. The volume estimator shipped with precisely that bug: an athlete reporting \"my legs feel great\" had their training ceiling lowered for it, every day, and the more honestly they checked in the worse it got. Fixed by naming the polarity ONCE in core/checkin-scales.ts (`sorenessFromCheckin` = 6 - stored, plus the inverse and a validated pass-through) and converting at the boundary in landmark-adapt instead of remembering; the Prisma comment now states the real semantics and points at the accessor. Pinned by tests that assert the conversion, the round-trip, and — the part that actually prevents a recurrence — that the accessor still agrees with every writer in the app (the flow's question key, checkinRating's averaging, and the primed-athlete-is-the-least-sore relation), so a future change to any writer breaks the test rather than silently re-inverting a model. THE LABEL NOW AGREES TOO: the metric is called FRESHNESS everywhere a human reads it — the daily card, the guided flow, the coach console, EN/PL/DE — which is the direction the question always ran (\"how fresh do your muscles feel?\") and the direction the value is stored, so the heading no longer means the opposite of the question under it. The coach console was showing the raw stored number under a \"soreness\" label, i.e. exactly backwards, and is now correct without any conversion. Only two things still say `soreness`: the Postgres column and the metric key that has to match it. Nothing translates on the wire; the copy key simply differs from the storage key, which is why `metricLabelKey` exists instead of building an i18n key from the field name. Guarded by a test that resolves the metric's own strings in all three languages and fails if any of them contains a word for soreness — scoped to this scale, since \"watch for soreness\" elsewhere in the app is a symptom being described rather than this metric being mislabelled." },
  { id: "feeling-card-redesign", area: "Web", status: "shipped", title: "Today's feeling card — reads its own answer in context", detail: "Two defects and a redesign. (1) BUG: the card's \"logged X ago\" read `weekOf` — the day the check-in COVERS, which for a back-logged day is that day's NOON — instead of `createdAt`, the moment the row was written. Back-logging yesterday produced \"logged in 4 hours\". Both clients now read createdAt, with weekOf only as the fallback for rows that predate it. (2) The card asked a question and then said nothing about what the answer was worth. A readiness tap 90 minutes after a heavy session and the same tap a day later are opposite readings — the first is the session talking and should NOT be scored as a recovery failure, the second is exactly the signal that should change the plan — and the card presented them identically. It now reads today's answer against the last completed session via core's `readinessContext`/`readinessNoteKey` (the same clock-changes-the-meaning model as feel-timing, applied on the way in) and says which reading it is looking at, in amber when the answer is low and the lag says it counts. Web and mobile carry the identical logic and copy from core, so the two cards cannot drift." },
  { id: "volume-recovery-feed", area: "Core", status: "shipped", title: "Check-in soreness, sleep and energy feed the volume estimator", detail: "Closes the loop the adaptive-MRV estimator was designed around: it read the training log but not the DAILY CHECK-IN, so the cheapest honest recovery signal in the app went unused. Both Volume screens now pass check-ins straight through (web lib/use-checkins.tsx, mobile useCheckinsQuery) as `RecoveryReport[]` — the check-in's own 1–5 scales, unreinterpreted — and they land in two different places, deliberately. (1) THE OBSERVED LAYER: soreness and energy are averaged over the days inside each 7-day window and join post-session fatigue and e1RM drift in classifying a week. A soreness spike (≥4.2) or an energy collapse (≤1.8) now marks a week OVERREACHED on its own, and no week counts as TOLERATED while energy sits under 2.5 — so a ceiling comes down when the athlete says they are buried even while the bar still says otherwise, which is the whole point of asking. (2) MEASURED PROFILE DEFAULTS (engines/landmark-context.ts): mean check-in sleep fills the profile's sleep field, and energy availability is read off the SCALE rather than the food diary — a least-squares body-mass trend over six weeks (needs 3+ weigh-ins spanning 2+ weeks; a single dehydrated morning must not decide whether someone is cutting), classified deficit / maintenance / surplus at ±0.25% of body mass per week, and left NULL when it cannot be fitted rather than defaulting to maintenance (which would silently hand back a recovery multiplier of 1). Every derived value is a DEFAULT, never an override: `withMeasured` layers them under whatever the athlete typed, `measuredFields` reports which ones came from data, and both screens mark those fields — green label, muted value — with a line saying where each came from and that typing over it wins. STRESS IS DELIBERATELY NOT DERIVED: the check-in asks about mood and energy, and relabelling either as 'life stress' would put a number the athlete never gave into a model that scales their training ceiling; mood and energy earn their keep in the observed layer instead, where a flat week is evidence about that week rather than a standing claim about the athlete. Also exposes `useBodyweightPoints()` on both clients (the raw dated measurements, for consumers that need the trend rather than a point lookup)." },
  { id: "athlete-height", area: "Data", status: "shipped", title: "Standing height on the body log", detail: "There was no athlete height anywhere in the schema before this — the existing `height` column is on MediaAsset and means image pixels. BodyMetric.heightCm is LIVE in production (reference/sql-body-height.sql run Jul 2026). THE ATHLETE SETS IT IN PROFILE: Profile → Private → Body & progress opens the log sheet with a HeightRow at the top (both clients), a single field that saves ON ITS OWN — height is a standing fact, not a weigh-in, so it must not have to ride along with one, and nothing else on the form has to be filled in for it to land. It is deliberately NOT one of BODY_METRIC_DEFS: that grid is things you watch move, and charting a height as a trend would be nonsense; `latestHeightCm` reads it as a fact from the newest row that CARRIES one (height is entered once and every later weigh-in leaves it blank, so the newest row almost never holds it), ignoring implausible values. Unit follows the weight preference (kg → cm, lb → in) via core units.ts heightUnitFor/displayHeight/storeHeightCm/fmtHeight, with a ft\'in readback because nobody says \'72 in\'; a value outside 120–230 cm is rejected on both the client and /api/body, since 72 typed into a cm field is a unit mix-up rather than a small athlete. The height flows on into the volume profile as a MEASURED field (measuredProfile({ heightCm }) → withMeasured/measuredFields, fed by the new useAthleteHeight() hook on the shared /api/body fetch), so the Volume \'About you\' editor shows it as measured rather than asking a second time — VOLUME_PROFILE_FIELDS marks heightCm `derivable: true` for that reason, not because anything infers a height. A save calls refreshBodyweight() so the model sees it without a reload. WHAT IT BUYS: heightCm feeds `frameAdjustedMassKg` (engines/athlete-profile.ts), which reads body mass against the frame carrying it instead of as raw kilos — the recovery multiplier docks mass above an 80 kg reference, but 95 kg at 195 cm and 95 kg at 170 cm are not the same load, and the flat rule penalised them identically. Mass is now compared to what the height predicts (a plain BMI-style expectation at 24.5 — deliberately NOT a body-composition model, since the app cannot see composition and pretending otherwise would be the same class of error as inventing a sleep score). The factor still displays the athlete\'s REAL mass rather than the adjusted figure. Surfaced in the admin Engine Room as the `landmark-frame` formula (expression + constants + the note on where height comes from). The model degrades cleanly: an athlete who never sets a height gets the raw-kg rule exactly as before, so nothing regresses." },
  { id: "two-read-feel", area: "Core", status: "shipped", title: "Asked twice about the same session — because one answer cannot say both things", detail: "\"How do you feel?\" answered in the gym and the same question answered the next morning are not two samples of one measurement. They are two different measurements, and the app needs both. THE IMMEDIATE READ is taken at the end of the session, on the finish screen, while the athlete is still next to the bar: effort here is sRPE (the input to session load, ACWR and injury risk) and spentness here is the acute disturbance at its PEAK, which is the only honest anchor for everything that follows. It cannot be recovered later — ask at 09:00 the next day and you get a memory of a feeling, filtered through a night's sleep. THE RECOVERY READ is the daily card, hours later, once the acute spike has had time to drain: this is the one that says whether the session was ABSORBED, and the only one that can move a training ceiling. core/feel-schedule.ts owns the clock and nothing else — `feelSchedule` says which read is due, when the next one opens (`msUntilNextRead`, ready for a local notification) and when asking stops being worth it. The immediate window is 3 h (past that it is no longer describing the session, so the card stops asking rather than collecting a value it would have to discount to nothing); the recovery read opens at 6 h — deliberately inside the same-day band rather than waiting for the next morning, because `expectedResidual(6) ≈ 0.59` means the fast component has largely drained AND an evening session still gets asked before bed — and closes at the 36 h next-day boundary. The immediate read is PER SESSION (two sessions are two efforts and two disturbances); the recovery read is PER DAY, anchored to the last session to finish, because you do not recover from one session at a time. Neither read invents an instrument: the first is the restored post-workout card writing Session.feel/fatigue/feelLoggedAt, the second is the daily check-in that already existed. One question, two moments, no third code path. Both clients: the finish screen and the Wrapped carry the immediate card (which now says, once, WHY there will be a second ask), and the Today card leads with what the recovery read is for when it comes due." },
  { id: "readiness-reads", area: "Core", status: "shipped", title: "The second read — asking again is not editing the answer", detail: "The daily card asked \"how ready do you feel?\" and stored the answer in ONE column, `Checkin.energy`, one row per day. So the second time an athlete opened it the only thing they could do was OVERWRITE the morning's answer — and the card, knowing that, locked its four faces the moment the day's check-in was complete. Both halves were wrong in the same way. \"Flat ninety minutes after squats\" and \"flat fourteen hours later\" are not one answer someone got wrong the first time; they are two measurements, and the SECOND is the one that should move training, while the FIRST is what makes it interpretable. The rest of the engine already knew this — feel-timing divides a report by the residual expected at its lag, feel-schedule schedules a recovery read six hours after the session, recovery-pairs measures the athlete's own clearance rate from PAIRS of reads — and all of it was starved: the store could hold one read a day, so a pair could almost never form. NOW EVERY ANSWER IS APPENDED (model CheckinRead, one row per read, with its own clock and the server's own measurement of hours-since-session), and core/readiness-reads.ts owns what that means. THE GATE (`readGate`): a new read is allowed once BOTH clocks have run out — four hours since the last read (MIN_RELOG_GAP_H, deliberately the same MIN_PAIR_GAP_H the pair model uses, because a re-read closer than that tells the maths nothing and asking for an answer that will be discarded is how a training app becomes a mood tracker) and six hours since a session the last read was taken in the shadow of (POST_SESSION_LOCK_H = the RECOVERY_DUE_H the recovery read was already scheduled at). Worked: session ends 09:00, athlete taps flat at 09:30, cadence would open at 13:30 but the session's recovery read isn't due until 15:00 — so the gate opens at 15:00 and the second answer lands where it is worth something. The day's FIRST read is never gated (an athlete logging how they feel walking out of the gym is telling the truth about that moment, and the card already names what that reading is worth), and the day is capped at four reads. THE PLACEMENT: readiness is the spentness scale read from the other end, so a read is inverted (6 − v) and handed to the SAME `feelReading` — one residual curve, one recall discount, one threshold, so the readiness card and the session card cannot disagree. THE DECISIVE READ: the day is judged on the latest read NOT taken minutes after training (falling back to the latest when every read is confounded) — latest rather than an average, because averaging \"wrecked at 09:30\" with \"good at 20:00\" describes neither moment, and because the whole point of the second read is that it SUPERSEDES the first as a statement of current state. It is what `prescribeSession` scales today's load off, and what the day's `Checkin.energy` column is set to on every write — so every existing reader (volume estimator, load factor, coach view) keeps working with no migration. THE PAIR: a day's first and last read go to the same `recoveryCurve` the session-side pairs use, at a 0.7 weight (same scale, same curve, noisier instrument), so two taps a day now measure this athlete's clearance rate where before they measured nothing. ONE DAY, ONE VOTE: `adaptLandmarks` groups reports by day before pooling and splits a day's weight across its reads — otherwise a training day logged three times would outvote a rest day logged once in every weekly mean, and training days are exactly the days that read low, so read frequency alone would have looked like overreaching. REDESIGNED TO 'ONE NUMBER' (concept 02 of design/readiness-card-concepts.html, six explorations rendered on the same day; states worked through in design/readiness-one-number-states.html). The card now LEADS with the reading that governs the day at display weight — 46px in that feeling's own tone — with its clock and lag as the stamp beside it. Consequences, each forced by a state rather than chosen for looks: the head ASKS ('How ready do you feel?') until there is an answer and then REPORTS ('Readiness'), because once the hero carries the reading the question above it is the same sentence twice; an empty day shows a light DASH, not a zero and not a middling 3, since inventing a reading is the exact failure this card exists to avoid; while the app is asking, the stamp switches from a lag to 'Since 10:00' so the number stops claiming to be current the moment a current one is wanted; the recovery ask drops its tinted panel and rides as the head's mono meta (in One Number the hero owns the top of the card, so a tinted block would be a second hero), and the day-full cap shows as '2 / 4' in the same slot; the readings record moves BEHIND A DOOR, shut by default with the count on it, which is the concept's trade — a card readable from across the room, with the day's story one tap away; and the info disclosure moves up beside the hero, where it explains the reading being shown. The sub-line keeps the one-line rule with a widened ladder: an explicit info tap wins, then what holds the faces, then what a new tap would do, then the ask on an empty day, then the day's trend. A just-tapped value is stamped with NOW rather than inheriting the previous reading's clock. SWEPT TO THE ONE-ACCENT DISCIPLINE (see design-system-unification) after the card had grown: (1) FOUR stacked grey blocks under the faces — a context note, an invitation, a gate reason and a countdown pill — collapse to ONE LINE, because only one of them is ever what the athlete needs at that moment (what holds the faces, else what a tap would do, else what the reading on record is worth); (2) the countdown moves up to the section head as mono right-side meta, which is where the Explore SectionHead standard already puts a scoping fact; (3) TWO lime-tinted surfaces were competing — the recovery ask and the follow-up trigger — so the follow-up ghosts to a hairline whenever the ask is showing: one fill at a time, and the fill belongs to the thing the app is actually asking for; (4) in the readings record the hue now appears EXACTLY ONCE — only the reading that governs the day is drawn in its feeling's colour, the earlier ones neutral, which retires the lime 'counts' label entirely. A cluster of parallel rows may not each wear their own hue, and the faces survive being drawn in ash because the expression is carried by the stroke, not the tint (ReadinessFace gained a `tone` override on both clients for exactly this). Both clients give the day's readings A PLACE OF THEIR OWN — a titled record under a hairline, one row per read carrying the FACE it was given as, the clock time it was given at, and how long after training that was, with the decisive one marked and a line naming the trend. It replaces 'Logged Flat, 5h ago', which is what a value looks like when the app can only hold one; a day holds a sequence now, and the sequence is the interesting part. A read with no session behind it says 'no session' rather than showing a lag of zero, and — when the gate is held — why it is held and when it opens, rather than a dead row of faces. AND WHEN THE GATE OPENS THE FACES GO BLANK: leaving the earlier answer lit invites the athlete to CORRECT it, which is the one thing this card is no longer for, and it is also just false — 'how are you right now' has no answer yet. The reading is not hidden, it stays on the record below with its clock, and the line under the faces says why they are empty and removes the fear that stops people answering twice: 'Answer for right now. Your earlier reading is kept, not replaced.' It also retires the flat 6h check-in cooldown, which gated the wrong thing in both directions: inside a day it was exempt (so the overwrite it should have stopped went through) and across days it blocked logging TODAY because yesterday had been back-logged an hour earlier. The API never 429s on it: inside the gate a readiness write is a CORRECTION of the read on record (same clock, new value), so the guided check-in's Edit can't fail a whole submission over one field. THE ENGINE ROOM CARRIES IT: five new formulas in the admin console's formula sheet, rendered from the code — `read-gate` (the two clocks, and that both numbers are borrowed rather than invented), `readiness-spent` (the 6 - v reflection onto the shared curve, with the worked 0.56-at-1h vs 1.21-at-14h pair), `decisive-read`, `readiness-pair` (the 0.7 discount) and `day-one-vote` — each with a drift guard that evaluates the printed formula against the live engine, so the console cannot quote a number the code no longer runs. A follow-up audit also corrected two things the first pass got wrong: (1) `readReports` stamped the day's freshness/sleep/mood with the NEWEST read's clock, which would have re-read a freshness answer given an hour after training as one given fourteen hours after it and inflated its cost ~2x for no reason but bookkeeping - every value now travels on the clock it was actually answered on, and a day with fewer than two reads is passed through exactly as the engine always saw it; (2) the readiness pair was unreachable - `pairReads` required the session's own post-workout `fatigue` answer, so an athlete who skips the finish card but taps the faces twice measured nothing. It now falls back to a read taken inside the immediate window as the pair's immediate side (at the readiness discount), while still preferring the session's own answer at full weight wherever it exists. APPLIED IN PRODUCTION: reference/sql-checkin-reads.sql was run in the Supabase SQL Editor (Jul 2026) — it created CheckinRead with its RLS policies and backfilled each existing day's stored answer as that day's first read, so the history is not blank and a day logged before the change can still form a pair with a read taken after it. prisma/migrations/20260730120000_checkin_reads is the same change for any environment reconciled onto Prisma migrations." },
  { id: "measured-clearance", area: "AI", status: "shipped", title: "Your own recovery rate, measured against the population curve", detail: "10x, and it is the reason asking twice is worth the extra tap. `expectedResidual` is a POPULATION curve: how fast fatigue drains for people in general. Divide a single report by it and you get that session's cost with timing removed — useful, but it silently assumes this athlete drains at the population rate, which is exactly what the volume model exists to deny. Ask twice about the SAME session and the assumption becomes measurable: both reports are converted to a cost against the same curve, so if the athlete recovers exactly as modelled the two costs come out EQUAL. `recoveryCurve` (core/feel-timing.ts) is their ratio — below 0.85 they drained faster than the curve, above 1.15 they are still carrying it long after the model says it should have gone. That second case is a reading no single report can produce: \"4/5 the next morning\" alone cannot tell you whether the session was brutal or the recovery was poor, and the pair can. NO PERSONAL TIME CONSTANT IS FITTED, deliberately: R(h1)/R(h2) is not monotone in tau, so a single pair admits two values and picking the one nearer the population figure would dress an assumption up as a measurement. The ratio is what the data supports. `athleteClearance` (engines/recovery-pairs.ts) matches check-ins back to sessions and DROPS any pair with a second session inside its gap — train Monday evening, again Tuesday morning, then check in, and reading that as Monday's drain would blame Monday for Tuesday's work and conclude the athlete recovers badly forever. It also refuses pairs closer than 4 h apart (the expected residual barely moves), pairs with an untimed read, and pairs whose immediate report is under 3/5 — an athlete who walked out fine has nothing to drain, and 2 in the gym against 2 the next morning divides 0.26 by 0.61 and reads as badly impaired when nothing happened to them either time. What survives is conservative by design: on a heavy week most days produce no pair at all, and below two clean pairs the index is exactly 1 at zero confidence. It then scales the RECOVERY end of the landmarks only (clearing slowly says nothing about how much work it takes to grow you), bounded to 0.85-1.12 and scaled by confidence, and is applied BEFORE the week classifier so the adaptive estimator bounds itself around a prior that already reflects measured recovery. Surfaced as a \"Measured recovery\" factor on both Volume screens, alongside the profile factors the athlete typed — and marked as measured, not claimed." },
  { id: "landmark-replay", area: "AI", status: "shipped", title: "Has the ceiling estimate settled? — the adaptive MRV proves itself", detail: "The adaptive estimator produced ONE number: your recoverable ceiling, today. It was tested against synthetic weeks and it was arithmetically correct, and none of that answered the question an athlete actually has, which is whether to believe it. A single number cannot answer that; a TRAJECTORY can. engines/landmark-replay.ts re-runs the estimator at every week of the athlete's own history — same inputs, same rules, only the clock moved back, and strictly no lookahead (each point sees only the sessions and check-ins that existed then) — and the SHAPE of the answer is the evidence: SETTLED (the ceiling stopped moving several weeks ago — it has seen enough of this athlete to stop changing its mind, which is the closest thing to a validated ceiling the app can offer), CONVERGING (still moving, but inside a band you can train in, shown with the movement visible rather than as a confident single figure), UNSETTLED (jumping around — the honest response is to say the estimate is not ready, not to print it), or INSUFFICIENT. A week only counts as evidence if the log moved the ceiling OFF the profile-only answer, by either observed route: the week classifier, or the measured clearance rate. That distinction is load-bearing — an athlete who ramps into a wall and backs off stops producing qualifying weeks (there is no longer enough volume to test a ceiling) while their measured clearance is still holding the ceiling down, and counting only the classifier would report \"not enough evidence\" at the exact moment the app is most confident about them. Equally, a flat line at the prior is NEVER reported as settled. It is a diagnostic, not a second estimator: it calls the same resolver the app uses, pinned by a test asserting the replay's last point IS the number on screen, so it cannot drift from what it is auditing. Proven end to end against a twelve-week block fixture — three squat sessions a week, sets ramping from MEV past the ceiling, a top set that holds while volume is absorbed and slides when it isn't, and a daily check-in tracking the same story: the absorbed athlete's ceiling goes 19 to 22 and settles, the athlete who stops absorbing comes back down to 17 and settles there. Shown on both Volume screens as the trajectory itself (\"19 → 22 → 22 → 22\") plus the verdict, per muscle the log has actually tested." },
  { id: "verified-record", area: "Data", status: "blocked", title: "Verified Strength Record — tiers 0–2 (witness co-signing)", detail: "10x — the biggest single bet in the strategy review, tiers 0–2 now BUILT. Every strength number on the internet is self-reported and therefore worthless; there is no strength equivalent of a verified race time. core/attestation.ts declares the full six-tier ladder (0 claimed, 1 sensed, 2 witnessed, 3 recorded, 4 instrumented, 5 sanctioned) with the evidence each tier actually proves, and grades live from evidence the athlete cannot type: 0 = as logged; 1 = the session carries a matched device recording (HONEST SCOPE: the wearable corroborates the workout — time/duration/HR — not the barbell load; true rep-signature sensing arrives with silent-logging); 2 = a second account co-signed THAT lift. Storage is RecordAttestation (prisma + reference/sql-verified-record.sql, appended to sql-pending.sql): one row per witness request per lift per session, the claim (e1RM + top load, kg) SNAPSHOTTED server-side from the session's own blocks at request time so the number the witness signs can never drift, append-only in spirit (status moves once, pending → cosigned/declined, stamped). API: /api/records/attest (GET badges + witness inbox, POST ask-by-@handle — ownership checked, lift verified against the stored blocks, block-list respected, rate-limited) and /api/records/attest/respond (witness-only, pending-only), both soft-degrading until the SQL runs. UI on BOTH clients: the session detail's PR list carries a 'Verified record' panel (tier badge per PR + ask-a-witness), and the social feed opens with the co-sign inbox ('X asks you to confirm you watched their Back Squat at 180 kg' → I watched it / Decline) — every request is also an invite, which is the growth loop. NEXT: tier badges on share cards + the feed's PR cards, the public READ API (the institutional wedge), tier 3 video capture, and Spotter Protocol as the tier-2 bootstrap.", blockedBy: "Run reference/sql-verified-record.sql (or re-run sql-pending.sql) in the Supabase SQL Editor — the RecordAttestation table doesn't exist in production yet; until then the panel reads Claimed/Sensed only and the routes soft-degrade. Then verify a live round-trip between two real accounts (ask → inbox → co-sign → badge flips to Witnessed)." },
  { id: "silent-logging", area: "Mobile", status: "planned", title: "Silent logging — sets detected, not typed", detail: "10x. Hevy's moat is that logging is FAST; a speed moat isn't beaten by being 15% faster, it's beaten by removing the activity. Watch IMU + phone (+ optional earbud motion) detects set start, rep count, tempo and rest boundaries; the athlete confirms by exception. Target: a full session in under five taps. Moat: every confirmed pre-filled set is a LABELED motion example, so rep-detection accuracy compounds daily and a competitor starting later starts at zero. Depends on watch-app." },
  { id: "equipment-identity", area: "Data", status: "planned", title: "Equipment identity — QR-anchored machines, normalized load", detail: "10x. 'Leg press 200 kg' is meaningless: it depends on lever arm, carriage tare, cable ratio and stack increment, which is why cross-gym comparison and true strength standards don't exist in any app. Give every rack/machine an identity (QR sticker or scanned photo) carrying make, model, ratio, tare and increment, and normalize logged load to force at the hands. Makes history gym-portable, makes the verified record and the MRV estimates physically correct, and is a GROUND GAME — a gym-by-gym physical asset (à la Foursquare's venue DB) that can't be copied by shipping code. The sticker is also a permanent free impression in front of every member of that gym." },
  { id: "program-efficacy", area: "Data", status: "shipped", title: "Program Efficacy Index v1 (programs ranked by measured outcome)", detail: "10x + the content engine, v1 SHIPPED. Program selection is the highest-stakes decision a lifter makes and it's made on influencer vibes because nobody has ever published: this program, run by people like you, produced this much strength. core/program-efficacy.ts (pure, tested) judges every closed 12-week enrollment window: OUTCOME = per-lift best e1RM in the window's first three weeks vs its last three, athlete-level = mean across qualifying lifts, program-level = the MEDIAN across athletes (one outlier PR can't buy a ranking); ADHERENCE = logged-days rate against the days the program prescribes, banded high/mid/low; DROPOUT = last logged session before week 8, published with the result and excluded from the median rather than double-punished. Every cohort under K_ANON (5) is suppressed, never estimated — per-lift and per-band rows independently. Served by the PUBLIC unauthenticated GET /api/efficacy (k-anonymous aggregates only, CDN-cached 1 h) and published on the PUBLIC /programs page (apps/web/app/programs) — ranked cards with n, adherence, dropout, per-lift medians, honest 'collecting evidence' shells below the k floor, and the methodology stated in full; auto-updating by construction (recomputed from the live DB, no editor, no cron). IN-APP both plan detail renderers on BOTH clients print the same one-liner ('Measured outcome: +6.2% e1RM in 12 weeks, median, n=23') via core efficacyLine — web MeasuredOutcome in aurora/plans.tsx, mobile components/measured-outcome.tsx — identical copy by construction. NEXT: endurance programs need a pace-based outcome (they honestly show as collecting), coach-authored programs join via ProgramEnrollment, training-age/sex bands once those fields have server-side coverage, claim-based planSchedule adherence, sitemap/robots + OG so the SEO asset actually gets crawled, and a nightly rollup (ModelFit pattern) when the live scan outgrows its caps." },
  { id: "spotter-protocol", area: "Core", status: "planned", title: "Spotter Protocol (the two-person primitive)", detail: "10x, cheap. Lifting is one of the few activities with a structurally necessary second person, and nobody has built software for that relationship. Two devices present → pair → the spotter's device co-signs the set, counts assisted reps separately, and captures video from the right angle; the spotter gets credit on the feed. Every use is an invite, and it's the free bootstrap for verified-record tier 2." },
];

export function capabilitiesByStatus(status: CapabilityStatus): Capability[] {
  return CAPABILITIES.filter((c) => c.status === status);
}
